import React, { useState, useEffect } from 'react';
import { Vaccination } from '../types';
import { getVaccineAdvice } from '../services/gemini';

const INITIAL_SCHEDULE = (dob: Date): Vaccination[] => {
  const addMonths = (date: Date, months: number) => {
    const d = new Date(date);
    d.setMonth(d.getMonth() + months);
    return d;
  };

  return [
    { id: '1', name: 'HepB (1st dose)', ageMilestone: 0, dueDate: addMonths(dob, 0), status: 'pending', description: 'Hepatitis B' },
    { id: '2', name: 'RV, DTaP, Hib, PCV, IPV', ageMilestone: 2, dueDate: addMonths(dob, 2), status: 'pending', description: 'Rotavirus, Diphtheria, Tetanus, Pertussis, Polio' },
    { id: '3', name: 'RV, DTaP, Hib, PCV, IPV (2nd)', ageMilestone: 4, dueDate: addMonths(dob, 4), status: 'pending', description: 'Second round of boosters' },
    { id: '4', name: 'RV, DTaP, Hib, PCV, IPV (3rd)', ageMilestone: 6, dueDate: addMonths(dob, 6), status: 'pending', description: 'Third round of boosters' },
    { id: '5', name: 'MMR, Varicella, HepA', ageMilestone: 12, dueDate: addMonths(dob, 12), status: 'pending', description: 'Measles, Mumps, Rubella, Chickenpox' },
  ];
};

export const VaccineTracker: React.FC = () => {
  const [dob, setDob] = useState<string>(() => {
    const d = new Date();
    d.setFullYear(d.getFullYear() - 1);
    return d.toISOString().split('T')[0];
  });
  const [schedule, setSchedule] = useState<Vaccination[]>([]);
  const [info, setInfo] = useState<{ name: string; text: string } | null>(null);
  const [loadingInfo, setLoadingInfo] = useState(false);

  useEffect(() => {
    if (dob) {
      setSchedule(INITIAL_SCHEDULE(new Date(dob)));
    }
  }, [dob]);

  const toggleStatus = (id: string) => {
    setSchedule(prev => prev.map(v => 
      v.id === id ? { 
        ...v, 
        status: v.status === 'completed' ? 'pending' : 'completed',
        receivedDate: v.status === 'completed' ? undefined : new Date()
      } : v
    ));
  };

  const handleFetchInfo = async (name: string) => {
    setLoadingInfo(true);
    try {
      const advice = await getVaccineAdvice(name);
      setInfo({ name, text: advice });
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingInfo(false);
    }
  };

  const isOverdue = (dueDate: Date) => {
    return new Date() > dueDate;
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Vaccination Schedule</h2>
          <p className="text-slate-500">Stay on top of your child's immunization milestones.</p>
        </div>
        <div className="bg-white p-3 rounded-2xl border border-slate-200 shadow-sm">
          <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Child's Birthday</label>
          <input 
            type="date" 
            value={dob}
            onChange={(e) => setDob(e.target.value)}
            className="text-slate-700 font-semibold focus:outline-none"
          />
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          {schedule.map((vaccine) => {
            const overdue = vaccine.status === 'pending' && isOverdue(vaccine.dueDate);
            return (
              <div 
                key={vaccine.id}
                className={`group p-6 rounded-3xl border-2 transition-all flex items-center justify-between ${
                  vaccine.status === 'completed' 
                    ? 'bg-emerald-50 border-emerald-100 opacity-80' 
                    : overdue 
                      ? 'bg-rose-50 border-rose-200'
                      : 'bg-white border-slate-100 hover:border-indigo-200'
                }`}
              >
                <div className="flex items-center gap-4">
                  <button 
                    onClick={() => toggleStatus(vaccine.id)}
                    className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
                      vaccine.status === 'completed' 
                        ? 'bg-emerald-500 text-white' 
                        : overdue 
                          ? 'bg-rose-100 border-2 border-rose-300 text-rose-500' 
                          : 'bg-slate-100 border-2 border-slate-200 text-slate-400'
                    }`}
                  >
                    {vaccine.status === 'completed' ? '✓' : '!'}
                  </button>
                  <div>
                    <h4 className={`font-bold ${vaccine.status === 'completed' ? 'text-emerald-900 line-through' : 'text-slate-800'}`}>
                      {vaccine.name}
                    </h4>
                    <p className="text-sm text-slate-500">
                      Due: {vaccine.dueDate.toLocaleDateString()} ({vaccine.ageMilestone} mo)
                    </p>
                    <button 
                      onClick={() => handleFetchInfo(vaccine.name)}
                      className="text-xs text-indigo-500 font-bold hover:underline mt-1"
                    >
                      What is this for?
                    </button>
                  </div>
                </div>
                {overdue && (
                  <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider">
                    Overdue
                  </span>
                )}
              </div>
            );
          })}
        </div>

        <div className="lg:col-span-1">
          {info ? (
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm sticky top-8 animate-in slide-in-from-right-4">
              <button onClick={() => setInfo(null)} className="float-right text-slate-400 hover:text-slate-600">×</button>
              <h3 className="text-xl font-bold text-slate-800 mb-4">{info.name}</h3>
              <div className="prose prose-sm prose-slate leading-relaxed">
                {info.text}
              </div>
            </div>
          ) : (
            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100 sticky top-8 text-center">
              <span className="text-3xl mb-4 block">ℹ️</span>
              <p className="text-indigo-800 font-medium">Click "What is this for?" to see AI-powered details about specific vaccines.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

