import React, { useState } from 'react';
import { analyzeScreening } from '../services/gemini';

const SCREENING_MODS = {
  mchat: {
    name: 'M-CHAT-R (Autism Screening)',
    questions: [
      { id: '1', text: 'If you point at something across the room, does your child look at it?' },
      { id: '2', text: 'Have you ever wondered if your child might be deaf?' },
      { id: '3', text: 'Does your child play pretend or make-believe?' },
      { id: '4', text: 'Does your child like climbing on things?' },
      { id: '5', text: 'Does your child make unusual finger movements near his or her eyes?' },
      { id: '6', text: 'Does your child point with one finger to ask for something or to get help?' },
      { id: '7', text: 'Does your child point with one finger to show you something interesting?' },
    ]
  },
  adhd: {
    name: 'Behavior & Focus Assessment (ADHD)',
    questions: [
      { id: '1', text: 'Does the child often fail to give close attention to details or make careless mistakes?' },
      { id: '2', text: 'Does the child often have difficulty sustaining attention in tasks or play activities?' },
      { id: '3', text: 'Does the child often seem not to listen when spoken to directly?' },
      { id: '4', text: 'Does the child often fidget with or tap hands or feet or squirm in seat?' },
      { id: '5', text: 'Does the child often leave seat in situations when remaining seated is expected?' },
      { id: '6', text: 'Does the child often blurt out an answer before a question has been completed?' },
    ]
  },
  speech: {
    name: 'Speech & Language Development',
    questions: [
      { id: '1', text: 'Does your child follow simple instructions (e.g., "Get your shoes")?' },
      { id: '2', text: 'Does your child use at least 50 different words?' },
      { id: '3', text: 'Does your child put two words together (e.g., "More juice")?' },
      { id: '4', text: 'Do strangers understand most of what your child says?' },
      { id: '5', text: 'Does your child repeat sounds or words often?' },
    ]
  }
};

export const ScreeningTool: React.FC = () => {
  const [activeMod, setActiveMod] = useState<keyof typeof SCREENING_MODS | null>(null);
  const [responses, setResponses] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState<string | null>(null);

  const handleSelectMod = (key: keyof typeof SCREENING_MODS) => {
    setActiveMod(key);
    setResponses({});
    setAnalysis(null);
  };

  const handleResponse = (qId: string, val: string) => {
    setResponses(prev => ({ ...prev, [qId]: val }));
  };

  const handleSubmit = async () => {
    if (!activeMod) return;
    setLoading(true);
    try {
      const result = await analyzeScreening(SCREENING_MODS[activeMod].name, responses);
      setAnalysis(result);
    } catch (e) {
      console.error(e);
      alert("Error analyzing assessment.");
    } finally {
      setLoading(false);
    }
  };

  const isComplete = activeMod && SCREENING_MODS[activeMod].questions.length === Object.keys(responses).length;

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-2xl font-bold text-slate-800">Developmental Screening</h2>
        <p className="text-slate-500">Validated tools to help identify potential developmental or behavioral concerns early.</p>
      </header>

      {!activeMod ? (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {Object.entries(SCREENING_MODS).map(([key, mod]) => (
            <button
              key={key}
              onClick={() => handleSelectMod(key as any)}
              className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all text-left space-y-3 group"
            >
              <div className="w-12 h-12 bg-indigo-50 rounded-xl flex items-center justify-center text-2xl group-hover:scale-110 transition-transform">
                {key === 'mchat' ? '🧩' : key === 'adhd' ? '🏃' : '🗣️'}
              </div>
              <h3 className="font-bold text-slate-800">{mod.name}</h3>
              <p className="text-sm text-slate-500">Quick assessment tool for parents.</p>
            </button>
          ))}
        </div>
      ) : (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="flex items-center justify-between bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
            <h3 className="font-bold text-slate-800">{SCREENING_MODS[activeMod].name}</h3>
            <button onClick={() => setActiveMod(null)} className="text-sm text-slate-400 hover:text-slate-600">Back to Tools</button>
          </div>

          <div className="bg-white rounded-3xl border border-slate-100 shadow-sm divide-y divide-slate-50">
            {SCREENING_MODS[activeMod].questions.map((q) => (
              <div key={q.id} className="p-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
                <p className="text-slate-700 font-medium md:max-w-xl">{q.text}</p>
                <div className="flex gap-2">
                  {['Yes', 'No'].map(val => (
                    <button
                      key={val}
                      onClick={() => handleResponse(q.id, val)}
                      className={`px-6 py-2 rounded-xl font-bold transition-all ${
                        responses[q.id] === val 
                          ? 'bg-indigo-500 text-white shadow-md' 
                          : 'bg-slate-50 text-slate-400 hover:bg-slate-100'
                      }`}
                    >
                      {val}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {!analysis && (
            <button
              onClick={handleSubmit}
              disabled={!isComplete || loading}
              className={`w-full py-4 rounded-2xl font-bold text-white shadow-lg transition-all ${
                isComplete && !loading ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-slate-300 cursor-not-allowed'
              }`}
            >
              {loading ? 'Analyzing with AI...' : 'Complete Assessment'}
            </button>
          )}

          {analysis && (
            <div className="bg-white p-8 rounded-[2.5rem] border border-indigo-100 shadow-xl animate-in zoom-in-95">
              <div className="flex items-center gap-2 mb-6 text-indigo-600">
                <span className="text-2xl">✨</span>
                <h3 className="text-xl font-bold">AI Assessment Summary</h3>
              </div>
              <div className="prose prose-slate max-w-none">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed text-lg">
                  {analysis}
                </div>
              </div>
              <div className="mt-8 p-4 bg-amber-50 rounded-2xl border border-amber-100 flex gap-3 text-amber-800 text-sm">
                <span>⚠️</span>
                <p><strong>Important:</strong> This screening tool is for informational guidance only and does not constitute a clinical diagnosis. Please share these results with your child's primary care provider for formal evaluation.</p>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

