  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return response.text;
};

export const analyzeScreening = async (testName: string, responses: any) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';
  const prompt = `
    As a pediatric specialist, analyze the results of a "${testName}" screening tool.
    Responses: ${JSON.stringify(responses)}

    REFER TO THE FOLLOWING CLINICAL STANDARDS AND TOOLS FOR INTERPRETATION:
    - Vanderbilt ADHD Diagnostic Rating Scale (VADRS)
    - Infant-Toddler Checklist (ITC)
    - Autism Spectrum Screening Questionnaire (ASSQ)
    - RAADS-14 (Ritvo Autism Asperger Diagnostic Scale-Revised)
    - Raising Children Network developmental resources

    Provide a professional but supportive summary for the parents.
    1. Score Interpretation: (Identify if the responses meet the thresholds for clinical concern according to the specific test norms.)
    2. Specific Observations: (Point out patterns in the responses, e.g., "consistent focus on social-communication items" or "high ratings in inattentive behaviors".)
    3. Next Steps: (Provide actionable advice such as speaking to a GP for a specialist referral, contacting school support, or seeking pediatric allied health.)
    4. Recommended Resources: (Specifically mention relevant sections of raisingchildren.net.au, Psychology-Tools.com, or RCH Melbourne.)

    DISCLAIMER: This is a screening tool, not a diagnosis. A follow-up with a pediatrician or specialist is mandatory for confirmation.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return response.text;
};

