                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {!analysis && (
            <div className="sticky bottom-8 bg-white/80 backdrop-blur-md p-4 rounded-3xl border border-slate-200 shadow-2xl flex items-center justify-between gap-4 max-w-2xl mx-auto">
               <div className="text-sm text-slate-500 px-4">
                 {Object.keys(responses).length} of {activeMod.questions.length} answered
