              <div className="prose prose-slate max-w-none">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed text-lg">
                  {analysis}
                </div>
              </div>
              <div className="mt-10 p-6 bg-amber-50 rounded-[2rem] border border-amber-100 flex gap-4 text-amber-800">
                <span className="text-2xl">⚠️</span>
                <div>
                  <h4 className="font-bold mb-1">Standard Medical Disclaimer</h4>
                  <p className="text-sm opacity-90 leading-relaxed">This screening summary is produced by an AI assistant for educational and triage purposes. It is not a formal medical diagnosis. Screening results that indicate high probability of a condition must be reviewed by a qualified pediatrician, clinical psychologist, or psychiatrist for a diagnostic evaluation.</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

