import React, { useState, useEffect } from 'react';
import { Vaccination } from '../types';
import { getVaccineAdvice } from '../services/gemini';

const INITIAL_SCHEDULE = (dob: Date): Vaccination[] => {
  const addMonths = (date: Date, months: number) => {
    const d = new Date(date);
    d.setMonth(d.getMonth() + months);
    return d;
  };

  return [
    { id: '1', name: 'HepB (1st dose)', ageMilestone: 0, dueDate: addMonths(dob, 0), status: 'pending', description: 'Hepatitis B' },
    { id: '2', name: 'RV, DTaP, Hib, PCV, IPV', ageMilestone: 2, dueDate: addMonths(dob, 2), status: 'pending', description: 'Rotavirus, Diphtheria, Tetanus, Pertussis, Polio' },
    { id: '3', name: 'RV, DTaP, Hib, PCV, IPV (2nd)', ageMilestone: 4, dueDate: addMonths(dob, 4), status: 'pending', description: 'Second round of boosters' },
    { id: '4', name: 'RV, DTaP, Hib, PCV, IPV (3rd)', ageMilestone: 6, dueDate: addMonths(dob, 6), status: 'pending', description: 'Third round of boosters' },
    { id: '5', name: 'MMR, Varicella, HepA', ageMilestone: 12, dueDate: addMonths(dob, 12), status: 'pending', description: 'Measles, Mumps, Rubella, Chickenpox' },
  ];
};

export const VaccineTracker: React.FC = () => {
  const [dob, setDob] = useState<string>(() => {
    const d = new Date();
    d.setFullYear(d.getFullYear() - 1);
    return d.toISOString().split('T')[0];
  });
  const [schedule, setSchedule] = useState<Vaccination[]>([]);
  const [info, setInfo] = useState<{ name: string; text: string } | null>(null);
  const [loadingInfo, setLoadingInfo] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    if (dob) {
      setSchedule(INITIAL_SCHEDULE(new Date(dob)));
    }
  }, [dob]);

  const toggleStatus = (id: string) => {
    setSchedule(prev => prev.map(v => 
      v.id === id ? { 
        ...v, 
        status: v.status === 'completed' ? 'pending' : 'completed',
        receivedDate: v.status === 'completed' ? undefined : new Date()
      } : v
    ));
  };

  const updateDetails = (id: string, field: keyof Vaccination, value: string) => {
    setSchedule(prev => prev.map(v => 
      v.id === id ? { ...v, [field]: value } : v
    ));
  };

  const handleFetchInfo = async (name: string) => {
    setLoadingInfo(true);
    try {
      const advice = await getVaccineAdvice(name);
      setInfo({ name, text: advice });
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingInfo(false);
    }
  };

  const isOverdue = (dueDate: Date) => {
    return new Date() > dueDate;
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Vaccination Schedule</h2>
          <p className="text-slate-500">Stay on top of your child's immunization milestones.</p>
        </div>
        <div className="bg-white p-3 rounded-2xl border border-slate-200 shadow-sm">
          <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Child's Birthday</label>
          <input 
            type="date" 
            value={dob}
            onChange={(e) => setDob(e.target.value)}
            className="text-slate-700 font-semibold focus:outline-none"
          />
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          {schedule.map((vaccine) => {
            const overdue = vaccine.status === 'pending' && isOverdue(vaccine.dueDate);
            const isEditing = editingId === vaccine.id;

            return (
              <div 
                key={vaccine.id}
                className={`group rounded-3xl border-2 transition-all overflow-hidden ${
                  vaccine.status === 'completed' 
                    ? 'bg-emerald-50 border-emerald-100' 
                    : overdue 
                      ? 'bg-rose-50 border-rose-200'
                      : 'bg-white border-slate-100 hover:border-indigo-200'
                }`}
              >
                <div className="p-6 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => toggleStatus(vaccine.id)}
                      className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
                        vaccine.status === 'completed' 
                          ? 'bg-emerald-500 text-white shadow-inner' 
                          : overdue 
                            ? 'bg-rose-100 border-2 border-rose-300 text-rose-500' 
                            : 'bg-slate-100 border-2 border-slate-200 text-slate-400'
                      }`}
                    >
                      {vaccine.status === 'completed' ? '✓' : '!'}
                    </button>
                    <div>
                      <h4 className={`font-bold ${vaccine.status === 'completed' ? 'text-emerald-900' : 'text-slate-800'}`}>
                        {vaccine.name}
                      </h4>
                      <p className="text-sm text-slate-500">
                        Due: {vaccine.dueDate.toLocaleDateString()} ({vaccine.ageMilestone} mo)
                      </p>
                      <div className="flex gap-3 mt-1">
                        <button 
                          onClick={() => handleFetchInfo(vaccine.name)}
                          className="text-xs text-indigo-500 font-bold hover:underline"
                        >
                          What is this for?
                        </button>
                        <button 
                          onClick={() => setEditingId(isEditing ? null : vaccine.id)}
                          className="text-xs text-slate-400 font-bold hover:text-indigo-500"
                        >
                          {isEditing ? 'Close Details' : 'Add Record Details'}
                        </button>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {overdue && (
                      <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider">
                        Overdue
                      </span>
                    )}
                    {vaccine.status === 'completed' && (
                      <span className="bg-emerald-100 text-emerald-700 text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider">
                        Administered
                      </span>
                    )}
                  </div>
                </div>

                {isEditing && (
                  <div className="px-6 pb-6 pt-2 bg-slate-50/50 border-t border-slate-100 animate-in slide-in-from-top-2">
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                      <div>
                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Manufacturer</label>
                        <input 
                          type="text" 
                          placeholder="e.g. Pfizer, GSK"
                          value={vaccine.manufacturer || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'manufacturer', e.target.value)}
                          className="w-full p-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Lot Number</label>
                        <input 
                          type="text" 
                          placeholder="e.g. AB1234"
                          value={vaccine.lotNumber || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'lotNumber', e.target.value)}
                          className="w-full p-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Clinic / Health Center</label>
                        <input 
                          type="text" 
                          placeholder="e.g. City Pediatrics"
                          value={vaccine.clinic || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'clinic', e.target.value)}
                          className="w-full p-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                      </div>
                    </div>
                  </div>
                )}

                {vaccine.status === 'completed' && !isEditing && (vaccine.manufacturer || vaccine.lotNumber || vaccine.clinic) && (
                  <div className="px-6 pb-4 pt-0 text-[11px] text-slate-400 flex flex-wrap gap-4 italic border-t border-slate-50/50">
                    {vaccine.manufacturer && <span><span className="font-bold uppercase tracking-tighter">Mfg:</span> {vaccine.manufacturer}</span>}
                    {vaccine.lotNumber && <span><span className="font-bold uppercase tracking-tighter">Lot:</span> {vaccine.lotNumber}</span>}
                    {vaccine.clinic && <span><span className="font-bold uppercase tracking-tighter">Loc:</span> {vaccine.clinic}</span>}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="lg:col-span-1">
          {info ? (
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm sticky top-8 animate-in slide-in-from-right-4 max-h-[80vh] overflow-y-auto">
              <button onClick={() => setInfo(null)} className="float-right text-slate-400 hover:text-slate-600 bg-slate-50 w-8 h-8 rounded-full flex items-center justify-center">×</button>
              <h3 className="text-xl font-bold text-slate-800 mb-4">{info.name}</h3>
              <div className="prose prose-sm prose-slate leading-relaxed">
                {info.text}
              </div>
              <div className="mt-6 p-3 bg-indigo-50 rounded-xl text-[10px] text-indigo-700 font-medium">
                Information based on Raising Children Network & Australian Clinical Guidelines.
              </div>
            </div>
          ) : (
            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100 sticky top-8 text-center">
              <span className="text-3xl mb-4 block">ℹ️</span>
              <p className="text-indigo-800 font-medium">Click "What is this for?" to see AI-powered details about specific vaccines.</p>
              <div className="mt-4 text-xs text-indigo-600 bg-white/50 p-4 rounded-2xl">
                Keep detailed records for school entry and international travel.
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

