      case 'growth': return <GrowthTracker />;
      case 'dosage': return <DoseCalculator />;
      case 'milestones': return <MilestoneNavigator />;
      case 'stories': return <CalmStory />;
      case 'screening': return <ScreeningTool />;
      case 'profile': return <MedicalProfile />;
      default: return <Dashboard onNavigate={setActiveView} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      <div key={activeView} className="animate-in fade-in slide-in-from-bottom-4 duration-300">
        {renderContent()}
      </div>
    </Layout>
  );
};

