import React, { useState } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis } from '../types';
import { analyzeMedicalProfile } from '../services/gemini';

export const MedicalProfile: React.FC = () => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: '',
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    prenatalScans: '',
    birthDetails: '',
    neonatalConcerns: '',
    birthWeight: undefined,
    birthLength: undefined,
    birthHeadCirc: undefined,
    apgar1: undefined,
    apgar5: undefined,
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({
    caregiverObservations: '',
  });

  const [loading, setLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'development' | 'attachment'>('history');

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');

  const handleAddMed = () => {
    if (newMed) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy] }));
      setNewAllergy('');
    }
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("Error generating health summary.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 pb-20">
      <header>
