import { GoogleGenAI, Modality } from "@google/genai";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeSymptoms = async (description: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a professional pediatric assistant. Analyze the following childhood symptoms: "${description}".
    If an image is provided, examine it for visible signs (like rashes or inflammation).

    BASE YOUR ANALYSIS AND ADVICE ON THESE AUTHORITATIVE SOURCES:
    1. Royal Children's Hospital (RCH) Melbourne Clinical Practice Guidelines (https://www.rch.org.au/clinicalguide/)
    2. Queensland Paediatric Clinical Guidelines (https://www.childrens.health.qld.gov.au/for-health-professionals/queensland-paediatric-emergency-care-qpec/queensland-paediatric-clinical-guidelines)
    3. Raising Children Network (https://raisingchildren.net.au/)

    Structure your response with:
    1. Potential Concerns: (Brief list based on clinical guidelines)
    2. Home Care Advice: (Supportive care aligned with RCH/Queensland guidelines)
    3. Triage Status: (Green - Monitor, Yellow - Call Doctor, Red - ER/Urgent)
    4. Key Questions: (Red flags or specific signs mentioned in guidelines)

    IMPORTANT: Include a prominent disclaimer that this is NOT a medical diagnosis and parents should consult a doctor. Mention that advice is guided by Australian clinical standards (RCH/Queensland Health).
  `;

  const contents: any = { parts: [{ text: prompt }] };

  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const calculateDosage = async (weightKg: number, medication: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Calculate the typical pediatric dosage for ${medication} for a child weighing ${weightKg}kg.
    CONSULT THE FOLLOWING FOR CALCULATIONS:
    - Royal Children's Hospital Melbourne Paediatric Pharmacopoeia/CPGs
    - Queensland Paediatric Clinical Guidelines

    Return the result in clear JSON format with:
    - medicationName
    - recommendedDose (mg or mg/kg)
    - frequency (e.g. every 6 hours)
    - maxDose24h (mg)
    - cautionaryNotes (including specific contraindications from RCH/Queensland guidelines)

    ALWAYS emphasize checking with a pharmacist or doctor before administering. Use standard Australian pediatric protocols.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json"
    }
  });

  return JSON.parse(response.text || '{}');
};

export const generateCalmingStory = async (childName: string, theme: string) => {
  const ai = getAIClient();
  const prompt = `Tell a very short, 2-minute calming, soothing story for a child named ${childName} about ${theme}. Use simple, gentle language.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: prompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  return base64Audio;
};

