                      {a}
                      <button onClick={() => setHistory({...history, allergies: history.allergies.filter(item => item !== a)})} className={`${filterQuery ? 'text-white/80 hover:text-white' : 'text-rose-300 hover:text-rose-500'}`}>×</button>
                    </span>
                  ))}
                  {filterQuery && filteredAllergies.length === 0 && (
                    <span className="text-xs text-slate-400 italic">No matching allergies</span>
                  )}
                </div>
