                    </span>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'complex' && (
          <div className="p-8 space-y-8 animate-in slide-in-from-right-4">
            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200">
