import React, { useState, useRef } from 'react';
import { analyzeSymptoms } from '../services/gemini';

const RED_FLAGS = [
  "Difficulty breathing / Abnormal noises",
  "High fever >38°C in infants <3 months",
  "Lethargy or difficult to wake",
  "Non-blanching rash (doesn't disappear under pressure)",
  "Persistent vomiting or dehydration",
  "Extreme pain unresponsive to simple analgesia"
];

export const SymptomChecker: React.FC = () => {
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim()) return;
    setLoading(true);
    try {
      const res = await analyzeSymptoms(description, image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error analyzing symptoms. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-3xl font-bold text-slate-800">Symptom AI Triage</h2>
        <p className="text-slate-500">Professional analysis using Australian RCH and Queensland clinical guidelines.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-6">
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="e.g. 10-month-old with barky cough, noisy breathing, and fever..."
              className="w-full h-40 p-6 rounded-3xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none resize-none transition-all text-lg font-medium"
            />

            <div className="flex flex-wrap items-center gap-4">
              <input
                type="file"
                accept="image/*"
                className="hidden"
                ref={fileInputRef}
                onChange={handleFileChange}
              />
              <button
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center gap-3 px-6 py-3 bg-slate-50 text-slate-700 rounded-2xl hover:bg-slate-100 transition-colors font-bold"
              >
                📷 Upload Physical Sign
              </button>

              <button
                onClick={handleAnalyze}
                disabled={loading || !description.trim()}
                className={`flex-1 py-3 rounded-2xl font-bold text-white shadow-lg transition-all transform hover:-translate-y-1 ${
                  loading 
                    ? 'bg-slate-300' 
                    : 'bg-indigo-600 hover:bg-indigo-700'
                }`}
              >
                {loading ? 'Analysing Clinical Guidelines...' : 'Analyse Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-48 h-48 group">
                <img src={image} alt="Preview" className="w-full h-full object-cover rounded-3xl border border-slate-200" />
                <button
                  onClick={() => setImage(null)}
                  className="absolute -top-3 -right-3 bg-rose-500 text-white w-8 h-8 rounded-full flex items-center justify-center shadow-lg"
                >
                  ×
                </button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-indigo-50 animate-in fade-in slide-in-from-bottom-6 border-l-[12px] border-l-indigo-600">
              <div className="flex items-center gap-3 mb-8 text-indigo-700 font-bold">
                <span className="text-3xl">👨‍⚕️</span>
                <h3 className="text-2xl italic">AI Triage Insights</h3>
              </div>
              <div className="prose prose-slate max-w-none prose-lg">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-medium">
                  {result.text}
                </div>
              </div>

              {result.sources.length > 0 && (
                <div className="mt-10 pt-8 border-t border-slate-100">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Evidence-Based Clinical Guidelines</h4>
                  <div className="flex flex-wrap gap-3">
                    {result.sources.map((source: any, i: number) => (
                      <a
                        key={i}
                        href={source.web?.uri}
                        target="_blank"
                        rel="noreferrer"
                        className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-xs font-bold hover:bg-indigo-100 transition-colors"
                      >
                        {source.web?.title || 'Clinical Resource'}
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-50 border border-rose-200 p-8 rounded-[2.5rem] shadow-sm">
            <h3 className="text-xl font-bold text-rose-900 mb-6 flex items-center gap-2">
              <span className="text-2xl">⚠️</span> Red Flags
            </h3>
            <ul className="space-y-4">
              {RED_FLAGS.map((flag, idx) => (
                <li key={idx} className="flex items-start gap-3 text-rose-800 text-sm font-bold leading-tight">
                  <span className="text-rose-400 mt-1">•</span>
                  {flag}
                </li>
              ))}
            </ul>
            <div className="mt-8 p-4 bg-white rounded-2xl border border-rose-100 text-center">
              <p className="text-rose-900 font-extrabold text-lg">Call 000 if child is critical</p>
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2.5rem] border border-indigo-100">
            <h4 className="font-bold text-indigo-900 mb-3">Escalation Pathway</h4>
            <div className="space-y-3 text-sm text-indigo-800 font-medium">
              <p>1. Local GP for mild/chronic concerns.</p>
              <p>2. HealthDirect (1800 022 222) for 24/7 nurse triage.</p>
              <p>3. Nearest Emergency Dept for acute illness.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

