import { GoogleGenAI, Modality, Type } from "@google/genai";

// Use process.env.API_KEY directly as per guidelines
const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSymptoms = async (description: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a professional pediatric assistant. Analyze the following childhood symptoms: "${description}".
    If an image is provided, examine it for visible signs (like rashes or inflammation).

    BASE YOUR ANALYSIS AND ADVICE ON THESE AUTHORITATIVE SOURCES:
    1. Royal Children's Hospital (RCH) Melbourne Clinical Practice Guidelines (https://www.rch.org.au/clinicalguide/)
    2. Queensland Paediatric Clinical Guidelines (https://www.childrens.health.qld.gov.au/for-health-professionals/queensland-paediatric-clinical-guidelines)
    3. Raising Children Network (https://raisingchildren.net.au/)

    Structure your response with:
    1. Potential Concerns: (Brief list based on clinical guidelines)
    2. Home Care Advice: (Supportive care aligned with RCH/Queensland guidelines)
    3. Triage Status: (Green - Monitor, Yellow - Call Doctor, Red - ER/Urgent)
    4. Key Questions: (Red flags or specific signs mentioned in guidelines)

    IMPORTANT: Include a prominent disclaimer that this is NOT a medical diagnosis and parents should consult a doctor. Mention that advice is guided by Australian clinical standards (RCH/Queensland Health).
  `;

  const contents: any = { parts: [{ text: prompt }] };

  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const calculateDosage = async (weightKg: number, medication: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Calculate the typical pediatric dosage for ${medication} for a child weighing ${weightKg}kg.
    CONSULT THE FOLLOWING FOR CALCULATIONS:
    - Royal Children's Hospital Melbourne Paediatric Pharmacopoeia/CPGs
    - Queensland Paediatric Clinical Guidelines

    Return the result in clear JSON format.

    ALWAYS emphasize checking with a pharmacist or doctor before administering. Use standard Australian pediatric protocols.
  `;

  // Use responseSchema for robust JSON output as per guidelines
  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          medicationName: { type: Type.STRING },
          recommendedDose: { type: Type.STRING },
          frequency: { type: Type.STRING },
          maxDose24h: { type: Type.STRING },
          cautionaryNotes: { type: Type.STRING }
        },
        required: ["medicationName", "recommendedDose", "frequency", "maxDose24h", "cautionaryNotes"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const generateCalmingStory = async (childName: string, theme: string) => {
  const ai = getAIClient();
  const prompt = `Tell a very short, 2-minute calming, soothing story for a child named ${childName} about ${theme}. Use simple, gentle language.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: prompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  return base64Audio;
};

export const getVaccineAdvice = async (vaccineName: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';
  const prompt = `
    Provide brief parent-friendly information about the ${vaccineName} vaccine.
    USE INFORMATION FROM:
    - Raising Children Network (https://raisingchildren.net.au/)
    - National Immunisation Program (Australia)

    Include:
    1. Why it's important.
    2. Common mild side effects.
    3. Quick tips for managing post-vaccine discomfort.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const analyzeScreening = async (testName: string, responses: any) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';
  const prompt = `
    As a pediatric specialist, analyze the results of a "${testName}" screening tool.
    Responses: ${JSON.stringify(responses)}

    REFER TO THE FOLLOWING CLINICAL STANDARDS AND TOOLS FOR INTERPRETATION:
    - Vanderbilt ADHD Diagnostic Rating Scale (VADRS)
    - Infant-Toddler Checklist (ITC)
    - Autism Spectrum Screening Questionnaire (ASSQ)
    - RAADS-14 (Ritvo Autism Asperger Diagnostic Scale-Revised)
    - Raising Children Network developmental resources

    Provide a professional but supportive summary for the parents.
    1. Score Interpretation: (Identify if the responses meet the thresholds for clinical concern according to the specific test norms.)
    2. Specific Observations: (Point out patterns in the responses, e.g., "consistent focus on social-communication items" or "high ratings in inattentive behaviors".)
    3. Next Steps: (Provide actionable advice such as speaking to a GP for a specialist referral, contacting school support, or seeking pediatric allied health.)
    4. Recommended Resources: (Specifically mention relevant sections of raisingchildren.net.au, Psychology-Tools.com, or RCH Melbourne.)

    DISCLAIMER: This is a screening tool, not a diagnosis. A follow-up with a pediatrician or specialist is mandatory for confirmation.
  `;

  // FIXED: Changed shorthand 'contents' to 'contents: prompt'
  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const analyzeMedicalProfile = async (profileData: any) => {
  const ai = getAIClient();
  const model = 'gemini-3-pro-preview';
  const prompt = `
    You are a Senior Pediatric Registrar/Trainee performing a clinical handover for a patient presenting to the Emergency Department or General Practice.

    Data: ${JSON.stringify(profileData)}

    Please provide a structured Clinical Handover using the ISBAR format (Introduction, Situation, Background, Assessment, Recommendation).

    - INTRODUCTION: Professional identifier and patient context.
    - SITUATION: Concise summary of the child's current health status and any presenting complexity.
    - BACKGROUND: 
        1. Summarize Past Medical and Surgical History.
        2. List active medications, allergies, and specialist teams (e.g. Cardiology, Neurology).
        3. Discuss developmental/neonatal history relevant to clinical presentation.
        4. Mention medical devices (shunts, G-tubes, etc.) if applicable.
        5. IMPORTANT: Include any "Sick Day Plan" instructions provided by the parents/specialists for use when the child is unwell.
    - ASSESSMENT: A professional clinical interpretation of the data, noting any patterns or red flags.
    - RECOMMENDATION: Specific questions or priorities for the treating clinician (e.g., "Requires review of baseline neurology", "Consider baseline respiratory status in context of chronic lung disease").
    - ATTACHMENT CONTEXT: Briefly note the caregiver's attachment observations for psychosocial context.

    Adhere to Australian pediatric standards (RCH Melbourne/Queensland Health). Maintain high clinical utility for medical staff while remaining readable for parents.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

