export const ScreeningTool: React.FC = () => {
  const [activeModKey, setActiveModKey] = useState<keyof typeof SCREENING_MODS | null>(null);
  const [responses, setResponses] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const activeMod = activeModKey ? SCREENING_MODS[activeModKey] : null;

  const handleSelectMod = (key: keyof typeof SCREENING_MODS) => {
    setActiveModKey(key);
    setResponses({});
    setAnalysis(null);
  };

  const handleResponse = (qId: string, val: string) => {
    setResponses(prev => ({ ...prev, [qId]: val }));
  };

  const handleSubmit = async () => {
    if (!activeMod) return;
    setLoading(true);
    try {
      const result = await analyzeScreening(activeMod.name, responses);
      setAnalysis(result);
    } catch (e) {
      console.error(e);
      alert("Error analyzing assessment.");
    } finally {
      setLoading(false);
    }
  };

  const isComplete = activeMod && activeMod.questions.length === Object.keys(responses).length;

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-2xl font-bold text-slate-800">Developmental Screening</h2>
        <p className="text-slate-500">Clinical tools to identify potential developmental or behavioral concerns. Powered by Gemini AI analysis.</p>
      </header>

      {!activeMod ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {Object.entries(SCREENING_MODS).map(([key, mod]) => (
            <button
              key={key}
              onClick={() => handleSelectMod(key as any)}
              className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-lg transition-all text-left space-y-4 group relative overflow-hidden"
            >
              <div className="flex items-start justify-between">
                <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl group-hover:scale-110 transition-transform">
                  {key === 'itc' ? '👶' : key === 'vanderbilt' ? '🏃' : key === 'assq' ? '🧩' : '🤝'}
                </div>
                <span className="text-xs font-bold text-indigo-400 bg-indigo-50 px-2 py-1 rounded-lg uppercase tracking-wider">Clinical Tool</span>
              </div>
              <div>
                <h3 className="font-bold text-xl text-slate-800 mb-1">{mod.name}</h3>
                <p className="text-sm text-slate-500 leading-relaxed">{mod.description}</p>
              </div>
              <div className="text-indigo-500 font-bold text-sm flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
