import React, { useState, useRef } from 'react';
import { analyzeSymptoms } from '../services/gemini';

const RED_FLAGS = [
  { text: "Difficulty breathing / Abnormal noises", icon: "🫁" },
  { text: "High fever >38°C in infants <3 months", icon: "🌡️" },
  { text: "Lethargy or difficult to wake", icon: "😴" },
  { text: "Non-blanching rash (meningococcal sign)", icon: "🟣" },
  { text: "Persistent vomiting or dehydration", icon: "🤮" },
  { text: "Extreme pain / Unconsolable crying", icon: "😫" }
];

export const SymptomChecker: React.FC = () => {
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim()) return;
    setLoading(true);
    try {
      const res = await analyzeSymptoms(description, image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-3xl font-bold text-slate-800">Symptom AI Guide</h2>
        <p className="text-slate-500">Guideline-based analysis informing parents of typical home care and red flags.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-6">
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Describe what you're seeing (e.g. barky cough, noisy breathing, fever)..."
              className="w-full h-40 p-6 rounded-3xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none resize-none transition-all text-lg font-medium"
            />

            <div className="flex flex-wrap items-center gap-4">
              <input
                type="file"
                accept="image/*"
                className="hidden"
                ref={fileInputRef}
                onChange={handleFileChange}
              />
              <button
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center gap-3 px-6 py-3 bg-slate-50 text-slate-700 rounded-2xl hover:bg-slate-100 transition-colors font-bold"
              >
                📷 Upload Sign Photo
              </button>

              <button
                onClick={handleAnalyze}
                disabled={loading || !description.trim()}
                className={`flex-1 py-3 rounded-2xl font-bold text-white shadow-lg transition-all transform hover:-translate-y-1 ${
                  loading 
                    ? 'bg-slate-300' 
                    : 'bg-indigo-600 hover:bg-indigo-700'
                }`}
              >
                {loading ? 'Reviewing Health Guidelines...' : 'Review Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-48 h-48 group">
                <img src={image} alt="Preview" className="w-full h-full object-cover rounded-3xl border border-slate-200" />
                <button
                  onClick={() => setImage(null)}
                  className="absolute -top-3 -right-3 bg-rose-500 text-white w-8 h-8 rounded-full flex items-center justify-center shadow-lg"
                >
                  ×
                </button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-indigo-50 animate-in fade-in slide-in-from-bottom-6 border-l-[12px] border-l-indigo-600">
              <div className="flex items-center gap-3 mb-8 text-indigo-700 font-bold">
                <span className="text-3xl">👨‍⚕️</span>
                <h3 className="text-2xl italic">AI Symptom Insights</h3>
              </div>
              <div className="prose prose-slate max-w-none prose-lg">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-medium">
                  {result.text}
                </div>
              </div>

