export interface SpecialistContact {
  id: string;
  name: string;
  specialty: string;
  hospital?: string;
  contact?: string;
}

export interface MedicalDevice {
  id: string;
  type: string;
  model?: string;
  lastChanged?: string;
  notes?: string;
}

export interface FamilyHistory {
  maternal: string;
  paternal: string;
  siblings: string;
  other: string;
}

export interface SickDayPlan {
  instructions: string;
  emergencyMeds: string;
  fluidRequirements: string;
  triggers: string;
  emergencyContact: string;
}

export interface MedicalHistory {
  pastMedicalHistory: string;
  surgicalHistory: string;
  currentMedications: string[];
  allergies: string[];
  familyHistory: FamilyHistory;
  specialists: SpecialistContact[];
  devices: MedicalDevice[];
  sickDayPlan: SickDayPlan;
}

export interface DevelopmentalHistory {
  prenatalScans: string;
  birthDetails: string;
  neonatalConcerns: string;
  birthWeight?: number;
  birthLength?: number;
  birthHeadCirc?: number;
  apgar1?: number;
  apgar5?: number;
}

export interface AttachmentAnalysis {
  caregiverObservations: string;
  aiInterpretation?: string;
}

export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting';

import React, { useState, useMemo } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile } from '../services/gemini';

export const MedicalProfile: React.FC = () => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    surgicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: {
      maternal: '',
      paternal: '',
      siblings: '',
      other: '',
    },
    specialists: [],
    devices: [],
    sickDayPlan: {
      instructions: '',
      emergencyMeds: '',
      fluidRequirements: '',
      triggers: '',
      emergencyContact: ''
    },
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    prenatalScans: '',
    birthDetails: '',
    neonatalConcerns: '',
    birthWeight: undefined,
    birthLength: undefined,
    birthHeadCirc: undefined,
    apgar1: undefined,
    apgar5: undefined,
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({
    caregiverObservations: '',
  });

  const [loading, setLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'complex' | 'sickday' | 'development' | 'attachment'>('history');

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });
  const [filterQuery, setFilterQuery] = useState('');

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name && newSpecialist.specialty) {
      const specialist: SpecialistContact = {
        id: Math.random().toString(36).substr(2, 9),
        ...newSpecialist
      };
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, specialist] }));
      setNewSpecialist({ name: '', specialty: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type) {
      const device: MedicalDevice = {
        id: Math.random().toString(36).substr(2, 9),
        ...newDevice
      };
      setHistory(prev => ({ ...prev, devices: [...prev.devices, device] }));
      setNewDevice({ type: '', notes: '' });
    }
  };

  const updateSickDay = (field: keyof SickDayPlan, value: string) => {
    setHistory(prev => ({
      ...prev,
      sickDayPlan: { ...prev.sickDayPlan, [field]: value }
    }));
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("Error generating summary.");
    } finally {
      setLoading(false);
    }
  };

  const filteredMeds = useMemo(() => {
    if (!filterQuery) return history.currentMedications;
    return history.currentMedications.filter(m => m.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.currentMedications, filterQuery]);

  const filteredAllergies = useMemo(() => {
    if (!filterQuery) return history.allergies;
    return history.allergies.filter(a => a.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.allergies, filterQuery]);

  const isHistoryMatch = useMemo(() => {
    if (!filterQuery) return true;
    const q = filterQuery.toLowerCase();
    return history.pastMedicalHistory.toLowerCase().includes(q) || 
           history.surgicalHistory.toLowerCase().includes(q) ||
           history.familyHistory.maternal.toLowerCase().includes(q) ||
           history.familyHistory.paternal.toLowerCase().includes(q) ||
           history.familyHistory.siblings.toLowerCase().includes(q) ||
           history.familyHistory.other.toLowerCase().includes(q) ||
           JSON.stringify(history.sickDayPlan).toLowerCase().includes(q);
  }, [history, filterQuery]);

  return (
    <div className="space-y-8 pb-20">
      <header className="flex justify-between items-start">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">Comprehensive Health Record</h2>
          <p className="text-slate-500">Record for doctor visits, specialist continuity, and home tracking.</p>
        </div>
        <div className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-widest shadow-lg">
          Health Profile
        </div>
      </header>

      <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm max-w-full overflow-x-auto">
        {[
          { id: 'history', label: 'History', icon: '📋' },
          { id: 'complex', label: 'Complex Care', icon: '🏥' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🤒' },
          { id: 'development', label: 'Birth Record', icon: '🐣' },
          { id: 'attachment', label: 'Attachment', icon: '🤝' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-3 px-4 rounded-xl font-bold transition-all flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span>{tab.icon}</span>
            <span className="whitespace-nowrap">{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-8 space-y-8 animate-in slide-in-from-right-4">
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <span className="text-slate-400">🔍</span>
              </div>
              <input 
                type="text"
                placeholder="Search history, meds, allergies, or family patterns..."
                value={filterQuery}
                onChange={(e) => setFilterQuery(e.target.value)}
                className="w-full pl-11 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium text-slate-700"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className={`${!isHistoryMatch && filterQuery ? 'opacity-40 grayscale' : 'opacity-100'} transition-all`}>
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-wider mb-2">Past Health History</label>
                <textarea 
                  value={history.pastMedicalHistory}
                  onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                  placeholder="Known conditions, recent illnesses..."
                  className="w-full h-32 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-wider mb-2">Surgical History</label>
                <textarea 
                  value={history.surgicalHistory}
                  onChange={e => setHistory({...history, surgicalHistory: e.target.value})}
                  placeholder="List surgeries and dates..."
                  className="w-full h-32 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-3">
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-wider">Current Medications</label>
                <div className="flex gap-2">
                  <input 
                    value={newMed}
                    onChange={e => setNewMed(e.target.value)}
                    placeholder="Dose and route..."
                    className="flex-1 p-3 rounded-xl border border-slate-200 outline-none"
                    onKeyPress={e => e.key === 'Enter' && handleAddMed()}
                  />
                  <button onClick={handleAddMed} className="bg-indigo-600 text-white w-12 h-12 rounded-xl flex items-center justify-center">＋</button>
                </div>
                <div className="flex flex-wrap gap-2 min-h-[40px]">
                  {filteredMeds.map((m, i) => (
                    <span key={i} className={`px-3 py-1 rounded-lg text-sm flex items-center gap-2 font-medium transition-all ${filterQuery ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-700'}`}>
                      {m}
                      <button onClick={() => setHistory({...history, currentMedications: history.currentMedications.filter(item => item !== m)})} className="hover:text-red-400">×</button>
                    </span>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-wider">Allergies</label>
                <div className="flex gap-2">
                  <input 
                    value={newAllergy}
                    onChange={e => setNewAllergy(e.target.value)}
                    placeholder="Reaction type..."
                    className="flex-1 p-3 rounded-xl border border-slate-200 outline-none"
                    onKeyPress={e => e.key === 'Enter' && handleAddAllergy()}
                  />
                  <button onClick={handleAddAllergy} className="bg-rose-500 text-white w-12 h-12 rounded-xl flex items-center justify-center">＋</button>
                </div>
                <div className="flex flex-wrap gap-2 min-h-[40px]">
                  {filteredAllergies.map((a, i) => (
                    <span key={i} className={`px-3 py-1 rounded-lg text-sm flex items-center gap-2 font-bold transition-all ${filterQuery ? 'bg-rose-500 text-white' : 'bg-rose-50 text-rose-700'}`}>
                      {a}
                      <button onClick={() => setHistory({...history, allergies: history.allergies.filter(item => item !== a)})} className="hover:text-rose-300">×</button>
                    </span>
                  ))}
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100">
              <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                <span className="text-indigo-600">🧬</span> Family Medical History
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Maternal History (Mother)</label>
                    <textarea 
                      value={history.familyHistory.maternal}
                      onChange={e => setHistory({...history, familyHistory: {...history.familyHistory, maternal: e.target.value}})}
                      placeholder="Conditions Prevalence..."
                      className="w-full h-24 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Paternal History (Father)</label>
                    <textarea 
                      value={history.familyHistory.paternal}
                      onChange={e => setHistory({...history, familyHistory: {...history.familyHistory, paternal: e.target.value}})}
                      placeholder="Conditions Prevalence..."
                      className="w-full h-24 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-sm"
                    />
                  </div>
                </div>
                <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Sibling History</label>
                    <textarea 
                      value={history.familyHistory.siblings}
                      onChange={e => setHistory({...history, familyHistory: {...history.familyHistory, siblings: e.target.value}})}
                      placeholder="Known conditions..."
                      className="w-full h-24 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Other (Grandparents/Patterns)</label>
                    <textarea 
                      value={history.familyHistory.other}
                      onChange={e => setHistory({...history, familyHistory: {...history.familyHistory, other: e.target.value}})}
                      placeholder="Recurring health patterns..."
                      className="w-full h-24 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-sm"
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'complex' && (
          <div className="p-8 space-y-8 animate-in slide-in-from-right-4">
            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200">
              <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                <span>👨‍⚕️</span> Specialist Teams & Continuity
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <input 
                  placeholder="Doctor Name"
                  value={newSpecialist.name}
                  onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})}
                  className="p-3 rounded-xl border border-slate-200"
                />
                <input 
                  placeholder="Specialty (e.g. Cardiology)"
                  value={newSpecialist.specialty}
                  onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})}
                  className="p-3 rounded-xl border border-slate-200"
                />
              </div>
              <button onClick={handleAddSpecialist} className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl">Add Contact</button>

              <div className="mt-4 space-y-2">
                {history.specialists.map(s => (
                  <div key={s.id} className="bg-white p-3 rounded-xl border border-slate-200 flex justify-between items-center shadow-sm">
                    <div>
                      <span className="font-bold text-indigo-600">{s.specialty}:</span>
                      <span className="ml-2 text-slate-700">{s.name}</span>
                    </div>
                    <button onClick={() => setHistory({...history, specialists: history.specialists.filter(x => x.id !== s.id)})} className="text-slate-400">×</button>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-200">
              <h4 className="font-bold text-indigo-900 mb-4 flex items-center gap-2">
                <span>📟</span> Medical Devices & Equipment
              </h4>
              <div className="flex gap-2 mb-4">
                <input 
                  placeholder="Type (e.g. G-Tube, VP Shunt, CPAP)"
                  value={newDevice.type}
                  onChange={e => setNewDevice({...newDevice, type: e.target.value})}
                  className="flex-1 p-3 rounded-xl border border-slate-200"
                />
                <button onClick={handleAddDevice} className="bg-indigo-600 text-white w-12 h-12 rounded-xl flex items-center justify-center">＋</button>
              </div>
              <div className="space-y-2">
                {history.devices.map(d => (
                  <div key={d.id} className="bg-white p-3 rounded-xl border border-indigo-100 flex justify-between items-center">
                    <span className="font-bold text-slate-700">{d.type}</span>
                    <button onClick={() => setHistory({...history, devices: history.devices.filter(x => x.id !== d.id)})} className="text-slate-400">×</button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-8 space-y-6 animate-in slide-in-from-right-4">
            <div className="bg-orange-50 p-8 rounded-[2.5rem] border border-orange-200 shadow-sm">
              <div className="flex items-center gap-4 mb-6">
                <div className="w-16 h-16 bg-orange-500 rounded-3xl flex items-center justify-center text-3xl text-white shadow-lg">🤒</div>
                <div>
                  <h3 className="text-2xl font-bold text-orange-900">Dedicated Sick Day Plan</h3>
                  <p className="text-orange-700 font-medium">Critical documentation for managing acute illness in complex backgrounds.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                   <div>
                    <label className="block text-xs font-bold text-orange-900 uppercase tracking-wider mb-2">Triggers & When to Act</label>
                    <textarea 
                      value={history.sickDayPlan.triggers}
                      onChange={e => updateSickDay('triggers', e.target.value)}
                      placeholder="Symptoms that start the plan (e.g., vomiting once, fever >38.5)..."
                      className="w-full h-32 p-4 rounded-2xl border border-orange-200 focus:ring-2 focus:ring-orange-500 outline-none resize-none bg-white/50"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-orange-900 uppercase tracking-wider mb-2">Emergency Medications</label>
                    <textarea 
                      value={history.sickDayPlan.emergencyMeds}
                      onChange={e => updateSickDay('emergencyMeds', e.target.value)}
                      placeholder="e.g. Hydrocortisone 100mg IM, Insulin adjustments..."
                      className="w-full h-32 p-4 rounded-2xl border border-orange-200 focus:ring-2 focus:ring-orange-500 outline-none resize-none bg-white/50"
                    />
                  </div>
                </div>

                <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold text-orange-900 uppercase tracking-wider mb-2">Fluid & Nutritional Requirements</label>
                    <textarea 
                      value={history.sickDayPlan.fluidRequirements}
                      onChange={e => updateSickDay('fluidRequirements', e.target.value)}
                      placeholder="e.g. 10% Dextrose at maintenance rate, frequent sips of Dioralyte..."
                      className="w-full h-32 p-4 rounded-2xl border border-orange-200 focus:ring-2 focus:ring-orange-500 outline-none resize-none bg-white/50"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-orange-900 uppercase tracking-wider mb-2">Specialist Emergency Contact</label>
                    <input 
                      type="text"
                      value={history.sickDayPlan.emergencyContact}
                      onChange={e => updateSickDay('emergencyContact', e.target.value)}
                      placeholder="Metabolic/Endocrine consultant on call number..."
                      className="w-full p-4 rounded-2xl border border-orange-200 focus:ring-2 focus:ring-orange-500 outline-none bg-white/50"
                    />
                  </div>
                </div>
              </div>

              <div className="mt-6">
                <label className="block text-xs font-bold text-orange-900 uppercase tracking-wider mb-2">Detailed Management Instructions</label>
                <textarea 
                  value={history.sickDayPlan.instructions}
                  onChange={e => updateSickDay('instructions', e.target.value)}
                  placeholder="Full step-by-step instructions as provided by your specialist..."
                  className="w-full h-48 p-6 rounded-3xl border border-orange-200 focus:ring-2 focus:ring-orange-500 outline-none resize-none text-lg font-medium bg-white/50"
                />
              </div>

              <div className="p-6 bg-white rounded-3xl border border-orange-100 flex gap-4 text-orange-800 mt-6">
                <span className="text-2xl">💡</span>
                <p className="text-sm italic leading-relaxed">
                  <strong>Caregiver Tip:</strong> For children with metabolic, endocrine, or cardiac conditions, having this plan documented ensures any provider (ED, GP, or Paramedic) can initiate the correct protocol immediately.
                </p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'development' && (
          <div className="p-8 space-y-6 animate-in slide-in-from-right-4">
             <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Birth Weight (kg)</label>
                <input 
                  type="number" step="0.001"
                  value={devHistory.birthWeight || ''}
                  onChange={e => setDevHistory({...devHistory, birthWeight: Number(e.target.value)})}
                  className="w-full p-3 rounded-xl border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Apgars (1/5 min)</label>
                <div className="flex gap-2">
                  <input placeholder="1m" type="number" value={devHistory.apgar1 || ''} onChange={e => setDevHistory({...devHistory, apgar1: Number(e.target.value)})} className="w-full p-3 rounded-xl border border-slate-200" />
                  <input placeholder="5m" type="number" value={devHistory.apgar5 || ''} onChange={e => setDevHistory({...devHistory, apgar5: Number(e.target.value)})} className="w-full p-3 rounded-xl border border-slate-200" />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Head Circ (cm)</label>
                <input 
                  type="number" step="0.1"
                  value={devHistory.birthHeadCirc || ''}
                  onChange={e => setDevHistory({...devHistory, birthHeadCirc: Number(e.target.value)})}
                  className="w-full p-3 rounded-xl border border-slate-200 outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-wider mb-2">Birth Details</label>
                <textarea 
                  value={devHistory.birthDetails}
                  onChange={e => setDevHistory({...devHistory, birthDetails: e.target.value})}
                  placeholder="Gestation, delivery mode, etc..."
                  className="w-full h-32 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-wider mb-2">Prenatal History</label>
                <textarea 
                  value={devHistory.prenatalScans}
                  onChange={e => setDevHistory({...devHistory, prenatalScans: e.target.value})}
                  placeholder="Maternal health and scan details..."
                  className="w-full h-32 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'attachment' && (
          <div className="p-8 space-y-6 animate-in slide-in-from-right-4">
            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100 mb-6">
              <h4 className="font-bold text-indigo-900 mb-2">🫂 Attachment & Bond</h4>
              <p className="text-indigo-700 text-sm leading-relaxed">
                Record your observations on comfort-seeking and emotional attunement to help provide context for healthcare providers.
              </p>
            </div>
            <textarea 
              value={attachment.caregiverObservations}
              onChange={e => setAttachment({...attachment, caregiverObservations: e.target.value})}
              placeholder="Describe your child's emotional regulation and bond..."
              className="w-full h-48 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-lg"
            />
          </div>
        )}
      </div>

      <div className="flex justify-center gap-4">
        <button 
          onClick={handleAnalyze}
          disabled={loading}
          className={`flex-1 max-w-md px-12 py-5 rounded-3xl font-bold text-white shadow-xl hover:shadow-2xl transition-all transform hover:-translate-y-1 ${
            loading ? 'bg-slate-300' : 'bg-gradient-to-r from-indigo-700 to-indigo-900'
          }`}
