          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {currentMilestones.map(m => (
          <div 
            key={m.id}
            onClick={() => toggleMilestone(m.id)}
            className={`p-6 rounded-[2.5rem] border-2 cursor-pointer transition-all flex items-start gap-4 group ${
              m.completed 
                ? 'bg-emerald-50 border-emerald-200 shadow-sm' 
                : 'bg-white border-slate-100 hover:border-indigo-200 hover:shadow-md'
            }`}
          >
            <div className={`mt-1 w-8 h-8 rounded-2xl border-2 flex items-center justify-center shrink-0 transition-all ${
              m.completed ? 'bg-emerald-500 border-emerald-500 text-white rotate-0' : 'border-slate-200 text-transparent group-hover:border-indigo-300'
            }`}>
              <span className="text-lg font-bold">✓</span>
            </div>
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${
                  m.category === 'Motor' ? 'bg-blue-100 text-blue-600' :
                  m.category === 'Language' ? 'bg-purple-100 text-purple-600' :
                  m.category === 'Social' ? 'bg-pink-100 text-pink-600' :
                  'bg-amber-100 text-amber-600'
                }`}>
                  {m.category}
                </span>
                {m.completed && <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-wider">Met</span>}
              </div>
              <p className={`text-lg font-bold leading-tight ${m.completed ? 'text-emerald-900 opacity-70' : 'text-slate-800'}`}>
                {m.description.split('. ')[0]}.
              </p>
              <p className={`text-sm leading-relaxed font-medium ${m.completed ? 'text-emerald-800/60' : 'text-slate-500'}`}>
                {m.description.split('. ').slice(1).join('. ')}
              </p>
            </div>
          </div>
        ))}
        {currentMilestones.length === 0 && (
          <div className="col-span-full py-16 text-center text-slate-400 bg-slate-50 rounded-[3rem] border border-dashed border-slate-200">
            <span className="text-4xl block mb-4">✨</span>
            <p className="font-bold">No milestones defined for this stage yet.</p>
            <p className="text-sm">We are constantly updating our developmental trackers.</p>
          </div>
        )}
      </div>

      <div className="bg-indigo-50 p-8 rounded-[3rem] border border-indigo-100 shadow-sm">
        <div className="flex justify-between items-center mb-4">
          <div>
            <h4 className="font-bold text-indigo-900 text-lg">Your Child's Journey</h4>
            <p className="text-indigo-700/60 text-xs font-bold uppercase tracking-widest">Growth Tracker Progress</p>
          </div>
          <span className="text-indigo-700 font-black text-2xl">
            {Math.round((milestones.filter(m => m.completed).length / milestones.length) * 100)}%
          </span>
        </div>
        <div className="w-full bg-indigo-200/50 h-4 rounded-full overflow-hidden mb-6">
          <div 
            className="bg-indigo-600 h-full transition-all duration-1000 ease-out shadow-lg"
            style={{ width: `${(milestones.filter(m => m.completed).length / milestones.length) * 100}%` }}
          />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
           <div className="flex gap-4 p-4 bg-white/40 rounded-2xl">
            <span className="text-2xl">💡</span>
            <p className="text-indigo-800 text-sm font-medium leading-relaxed">
              <strong>Parenting Tip:</strong> These are general windows, not hard deadlines. Children develop at significantly different rates.
            </p>
          </div>
          <div className="flex gap-4 p-4 bg-white/40 rounded-2xl">
            <span className="text-2xl">🚨</span>
            <p className="text-indigo-800 text-sm font-medium leading-relaxed">
              <strong>When to consult:</strong> If your child loses skills they once had or shows significant delay in several areas, speak to your GP.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Modality, Type } from "@google/genai";

// Use process.env.API_KEY directly as per guidelines
const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSymptoms = async (description: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a supportive and professional pediatric health assistant. Analyze the following childhood symptoms provided by a parent: "${description}".
    If an image is provided, examine it for visible signs (like rashes or inflammation).

    BASE YOUR ANALYSIS AND ADVICE ON THESE AUTHORITATIVE SOURCES:
    1. Royal Children's Hospital (RCH) Melbourne Clinical Practice Guidelines (https://www.rch.org.au/clinicalguide/)
    2. Queensland Paediatric Clinical Guidelines (https://www.childrens.health.qld.gov.au/for-health-professionals/queensland-paediatric-clinical-guidelines)
    3. Raising Children Network (https://raisingchildren.net.au/)

    Structure your response with:
    1. Potential Areas to Discuss with a Doctor: (Brief list based on guidelines)
    2. Standard Home Care Advice: (Supportive care aligned with RCH/Queensland guidelines)
    3. Triage Guide: (Green - Monitor, Yellow - Consult Doctor, Red - Seek Urgent Care)
    4. Key Questions to Consider: (Red flags or specific signs mentioned in guidelines)

    IMPORTANT: Emphasize that this is NOT a medical diagnosis and is for informational purposes. Advice is guided by Australian clinical standards (RCH/Queensland Health).
  `;

  const contents: any = { parts: [{ text: prompt }] };

  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const extractProfileFromText = async (rawText: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Extract structured medical information from the following parent notes or medical document image.
    If it's an image, perform OCR first. Focus on:
    - Current Medications and doses
    - Known Allergies
    - Specialist doctors and their specialties
    - Medical devices (G-tubes, shunts, etc)
    - Sick Day Plan details (Triggers, Emergency Meds, Fluids)

    Raw Content: "${rawText}"

    Return a valid JSON object matching the structured schema. If a field is missing, return an empty string or array.
  `;

  const parts: any[] = [{ text: prompt }];
  if (imageBase64) {
    parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          pastMedicalHistory: { type: Type.STRING },
          surgicalHistory: { type: Type.STRING },
          currentMedications: { type: Type.ARRAY, items: { type: Type.STRING } },
          allergies: { type: Type.ARRAY, items: { type: Type.STRING } },
          specialists: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT, 
              properties: { name: { type: Type.STRING }, specialty: { type: Type.STRING } } 
            } 
          },
          devices: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT, 
              properties: { type: { type: Type.STRING }, notes: { type: Type.STRING } } 
            } 
          },
          sickDayPlan: {
            type: Type.OBJECT,
            properties: {
              instructions: { type: Type.STRING },
              emergencyMeds: { type: Type.STRING },
              fluidRequirements: { type: Type.STRING },
              triggers: { type: Type.STRING },
              emergencyContact: { type: Type.STRING }
            }
          }
        }
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const calculateDosage = async (weightKg: number, medication: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Provide informational weight-based pediatric dosage for ${medication} for a child weighing ${weightKg}kg.
    CONSULT THE FOLLOWING FOR CALCULATIONS:
    - Royal Children's Hospital Melbourne Paediatric Pharmacopoeia/CPGs
    - Queensland Paediatric Clinical Guidelines

    Return the result in clear JSON format.

    ALWAYS emphasize checking with a pharmacist or doctor before administering. Use standard Australian pediatric protocols.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          medicationName: { type: Type.STRING },
          recommendedDose: { type: Type.STRING },
          frequency: { type: Type.STRING },
          maxDose24h: { type: Type.STRING },
          cautionaryNotes: { type: Type.STRING }
        },
        required: ["medicationName", "recommendedDose", "frequency", "maxDose24h", "cautionaryNotes"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

