import React, { useState, useMemo, useRef } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Follow 4x4 protocol: 4 puffs of Ventolin via spacer, every 4 minutes. If no improvement, call 000.",
    triggers: "Coughing at night, wheezing during exercise, viral colds.",
    emergencyMeds: "Salbutamol (Ventolin) 100mcg/puff. Prednisolone (if prescribed).",
    fluidRequirements: "Encourage frequent small sips of water or electrolyte solution."
  },
  metabolic: {
    instructions: "Initiate emergency glucose protocol immediately if child is not tolerating oral intake.",
    triggers: "Vomiting once, diarrhea, or fever >38.5C.",
    emergencyMeds: "10% Dextrose (Emergency Letter protocol).",
    fluidRequirements: "Frequent sips of Dioralyte or prescribed glucose solution (SOS)."
  },
  adrenal: {
    instructions: "Administer hydrocortisone injection if vomiting or severe trauma occurs.",
    triggers: "Fever, vomiting, major stress, or trauma.",
    emergencyMeds: "Solu-Cortef 100mg IM injection. Double oral dose for illness.",
    fluidRequirements: "Ensure adequate salt and fluid intake."
  }
};

export const MedicalProfile: React.FC = () => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    surgicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    prenatalScans: '', birthDetails: '', neonatalConcerns: ''
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({ caregiverObservations: '' });

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'complex' | 'sickday' | 'development' | 'attachment'>('history');
  const [smartNotes, setSmartNotes] = useState('');
  const [smartImage, setSmartImage] = useState<string | null>(null);

  const smartFileInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });
  const [filterQuery, setFilterQuery] = useState('');

  const handleSmartImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSmartImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleMagicFill = async () => {
    if (!smartNotes && !smartImage) return;
    setSmartLoading(true);
    try {
      const extracted = await extractProfileFromText(smartNotes, smartImage || undefined);

      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: extracted.pastMedicalHistory || prev.pastMedicalHistory,
        surgicalHistory: extracted.surgicalHistory || prev.surgicalHistory,
        currentMedications: [...new Set([...prev.currentMedications, ...(extracted.currentMedications || [])])],
        allergies: [...new Set([...prev.allergies, ...(extracted.allergies || [])])],
        specialists: [...prev.specialists, ...(extracted.specialists || []).map((s: any) => ({ ...s, id: Math.random().toString(36).substr(2, 9) }))],
        devices: [...prev.devices, ...(extracted.devices || []).map((d: any) => ({ ...d, id: Math.random().toString(36).substr(2, 9) }))],
        sickDayPlan: {
          ...prev.sickDayPlan,
          ...extracted.sickDayPlan
        }
      }));

      setSmartNotes('');
      setSmartImage(null);
      alert("Health profile updated using Smart Entry! Please review the sections below.");
    } catch (e) {
      console.error(e);
      alert("Smart Entry failed. Please try again or fill fields manually.");
    } finally {
      setSmartLoading(false);
    }
  };

  const applyTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      setHistory(prev => ({
        ...prev,
        sickDayPlan: { ...prev.sickDayPlan, ...template }
      }));
      setActiveTab('sickday');
    }
  };

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const updateSickDay = (field: keyof SickDayPlan, value: string) => {
    setHistory(prev => ({
      ...prev,
      sickDayPlan: { ...prev.sickDayPlan, [field]: value }
    }));
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("Error generating summary.");
    } finally {
      setLoading(false);
    }
  };

  const filteredMeds = useMemo(() => {
    if (!filterQuery) return history.currentMedications;
    return history.currentMedications.filter(m => m.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.currentMedications, filterQuery]);

  const filteredAllergies = useMemo(() => {
    if (!filterQuery) return history.allergies;
    return history.allergies.filter(a => a.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.allergies, filterQuery]);

  const isHistoryMatch = useMemo(() => {
    if (!filterQuery) return true;
    const q = filterQuery.toLowerCase();
    return history.pastMedicalHistory.toLowerCase().includes(q) || 
           history.surgicalHistory.toLowerCase().includes(q) ||
           JSON.stringify(history.sickDayPlan).toLowerCase().includes(q);
  }, [history, filterQuery]);

  return (
    <div className="space-y-8 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Health Companion Profile</h2>
          <p className="text-slate-500 font-medium">Capture complex histories effortlessly with Smart Entry.</p>
        </div>
        <div className="bg-indigo-600 text-white px-5 py-2 rounded-2xl text-xs font-bold uppercase tracking-widest shadow-lg">
          Personal Record
        </div>
      </header>

      {/* Smart Entry Section - Making it easier for parents */}
      <section className="bg-white p-8 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden relative">
        <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-full -mr-16 -mt-16"></div>
        <div className="relative z-10 space-y-6">
          <div className="flex items-center gap-3">
            <span className="text-3xl">🪄</span>
            <h3 className="text-2xl font-bold text-slate-800">Smart Entry Assistant</h3>
          </div>
          <p className="text-slate-500 text-sm max-w-xl">
            Don't waste time typing every detail. Paste doctor notes, or upload a photo of a specialist letter. Our AI will organize it for you.
          </p>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="space-y-4">
              <textarea 
                value={smartNotes}
                onChange={e => setSmartNotes(e.target.value)}
                placeholder="Paste clinic letter text or brain dump child's history here..."
                className="w-full h-32 p-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-medium resize-none bg-slate-50/50"
              />
              <div className="flex gap-2">
                <input type="file" ref={smartFileInputRef} className="hidden" onChange={handleSmartImageUpload} accept="image/*" />
                <button 
                  onClick={() => smartFileInputRef.current?.click()}
                  className={`flex-1 py-3 rounded-xl border-2 border-dashed font-bold text-sm transition-all ${smartImage ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-200 text-slate-400 hover:border-indigo-300'}`}
                >
                  {smartImage ? '📄 Document Ready' : '📷 Upload Letter Photo'}
                </button>
                <button 
                  onClick={handleMagicFill}
                  disabled={smartLoading || (!smartNotes && !smartImage)}
                  className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 disabled:bg-slate-300 transition-all flex items-center gap-2"
                >
                  {smartLoading ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : '✨ Magic Fill'}
                </button>
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200 space-y-4">
              <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Quick Start Templates</h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <button onClick={() => applyTemplate('asthma')} className="p-3 bg-white border border-slate-100 rounded-xl text-xs font-bold text-slate-700 hover:border-indigo-400 hover:shadow-sm transition-all text-left flex items-center gap-2">
                  <span>🫁</span> Asthma Plan
                </button>
                <button onClick={() => applyTemplate('metabolic')} className="p-3 bg-white border border-slate-100 rounded-xl text-xs font-bold text-slate-700 hover:border-indigo-400 hover:shadow-sm transition-all text-left flex items-center gap-2">
                  <span>🧪</span> Metabolic Plan
                </button>
                <button onClick={() => applyTemplate('adrenal')} className="p-3 bg-white border border-slate-100 rounded-xl text-xs font-bold text-slate-700 hover:border-indigo-400 hover:shadow-sm transition-all text-left flex items-center gap-2">
                  <span>💊</span> Adrenal Plan
                </button>
                <button onClick={() => setActiveTab('history')} className="p-3 bg-white border border-slate-100 rounded-xl text-xs font-bold text-slate-400 italic text-left flex items-center gap-2">
                  <span>✏️</span> Custom...
                </button>
              </div>
            </div>
          </div>
