                <div>
                  <h3 className="text-4xl font-black italic tracking-tight">Health Summary Report</h3>
                  <p className="text-indigo-600 font-bold text-sm tracking-widest uppercase mt-1">Ready for Clinic Submission</p>
                </div>
              </div>
              <button 
                onClick={() => {
                  navigator.clipboard.writeText(aiAnalysis.text);
                  alert("Summary copied to clipboard.");
                }}
                className="bg-slate-100 text-slate-700 px-8 py-3 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all shadow-sm flex items-center gap-2"
              >
                <span>📋</span> Copy Report
              </button>
            </div>
            <div className="prose prose-indigo max-w-none prose-xl">
              <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold selection:bg-indigo-100 italic">
                {aiAnalysis.text}
              </div>
            </div>

            {aiAnalysis.sources && aiAnalysis.sources.length > 0 && (
              <div className="mt-12 pt-10 border-t border-slate-100">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Supporting Informational Resources</h4>
                <div className="flex flex-wrap gap-4">
                  {aiAnalysis.sources.map((source: any, i: number) => (
                    <a
                      key={i}
                      href={source.web?.uri}
                      target="_blank"
                      rel="noreferrer"
                      className="px-6 py-3 bg-indigo-50 text-indigo-700 rounded-2xl text-xs font-black hover:bg-indigo-100 transition-all border border-indigo-100 shadow-sm"
                    >
                      {source.web?.title || 'Guideline Reference'}
                    </a>
                  ))}
                </div>
              </div>
            )}

            <div className="mt-12 p-10 bg-rose-50 rounded-[3rem] border border-rose-100 flex gap-6 text-rose-900 shadow-sm">
              <span className="text-5xl">🚨</span>
              <div>
                <h4 className="font-black text-xl mb-2">Important Notice</h4>
                <p className="text-lg font-bold opacity-80 leading-snug">
                  This summary is generated to help you organize your child's medical information for discussion with healthcare professionals. It is not clinical advice or a medical diagnosis.
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

