            <span className="text-2xl">🚨</span>
            <p className="text-indigo-800 text-sm font-medium leading-relaxed">
              <strong>Loss of skills:</strong> If your child loses a skill they previously had (like babbling, walking, or social engagement), seek medical advice immediately.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

