                ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg scale-105' 
                : 'bg-white text-slate-500 border-slate-100 hover:border-indigo-200'
            }`}
          >
            {age}
          </button>
        ))}
      </div>

      <div className="space-y-10">
        {currentMilestones.length > 0 && (
          <section className="space-y-4">
            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
              <span>🌈</span> Development Progress
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {currentMilestones.map(m => (
                <div 
                  key={m.id}
                  onClick={() => toggleMilestone(m.id)}
                  className={`p-6 rounded-[2rem] border-2 cursor-pointer transition-all flex items-start gap-4 ${
                    m.completed ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-slate-100'
                  }`}
                >
                  <div className={`mt-1 w-7 h-7 rounded-xl border-2 flex items-center justify-center shrink-0 ${
                    m.completed ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-200'
                  }`}>
                    {m.completed && '✓'}
                  </div>
                  <div className="space-y-1">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.category}</span>
                    <p className="text-lg font-bold text-slate-800 leading-tight">{m.description}</p>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {currentRedFlags.length > 0 && (
          <section className="space-y-4">
            <h3 className="text-xl font-bold text-rose-600 flex items-center gap-2">
              <span className="animate-pulse">⚠️</span> QLD Clinical Red Flags
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {currentRedFlags.map(m => (
                <div 
                  key={m.id}
                  onClick={() => toggleMilestone(m.id)}
                  className={`p-6 rounded-[2rem] border-2 cursor-pointer transition-all flex items-start gap-4 ${
                    m.completed ? 'bg-rose-100 border-rose-300 opacity-60 shadow-inner' : 'bg-white border-rose-100 shadow-sm'
                  }`}
                >
                  <div className={`mt-1 w-7 h-7 rounded-xl border-2 flex items-center justify-center shrink-0 ${
                    m.completed ? 'bg-rose-500 border-rose-500 text-white' : 'border-rose-200 text-rose-300'
                  }`}>
                    {m.completed ? '✓' : '!'}
                  </div>
                  <div className="space-y-1">
                    <span className="text-[10px] font-black text-rose-400 uppercase tracking-widest">Medical Review Indicated</span>
                    <p className="text-lg font-bold text-rose-950 leading-tight">{m.description}</p>
                    {m.completed && <p className="text-xs font-bold text-rose-700 italic mt-2">Logged for doctor review</p>}
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}
      </div>

      <div className="mt-12 p-8 bg-indigo-950 rounded-[3rem] text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
          <div className="text-5xl">🚨</div>
          <div className="space-y-2">
            <h4 className="text-2xl font-black italic tracking-tight">The "Loss of Skills" Rule</h4>
            <p className="text-indigo-100 text-lg leading-relaxed">
              If your child loses any language, social, or motor skill they once had (e.g., stops babbling, stops making eye contact), this is <strong>always</strong> a priority for medical review.
            </p>
          </div>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500 rounded-full -mr-32 -mt-32 opacity-20 blur-3xl"></div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Follow 4x4 protocol: 4 puffs of Ventolin (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4 puffs. CALL 000 if: distressed, lips blue, or skin sucking in around ribs.",
    triggers: "Viral colds, exercise, smoke, seasonal pollens, cold air.",
    emergencyMeds: "Salbutamol (Ventolin) 100mcg/puff. Prednisolone (Oral Steroid) - Dose as per doctor.",
    fluidRequirements: "Offer small frequent sips of water. Monitor for signs of dehydration due to increased respiratory effort.",
    emergencyContact: "Family GP / Local Emergency Department"
  },
  metabolic: {
    instructions: "CRITICAL: Follow Emergency Letter instructions. Initiate high glucose fluids (10% glucose) every 1-2 hours. If vomiting once, proceed directly to Hospital ED for IV Dextrose. DO NOT FAST.",
    triggers: "Fever >38.5, vomiting, diarrhea, or refusing food/fluids.",
    emergencyMeds: "Emergency Glucose Letter (Hand to Triage Nurse). Rescue Fluids as prescribed.",
    fluidRequirements: "Max dose glucose solution (SOS/10%) at calculated maintenance rate (e.g. 100ml/kg/24hr).",
    emergencyContact: "Metabolic On-Call Registrar (Hospital Name)"
  },
  seizure: {
    instructions: "Time the seizure. Protect head, move to safe side position once safe. DO NOT put anything in mouth. Call 000 if: seizure >5 mins, first seizure, or difficulty breathing after.",
    triggers: "Fever (Febrile), missed medication, sleep deprivation, illness.",
    emergencyMeds: "Midazolam (Buccal/Intranasal) - Dose: [e.g. 5mg] if seizure persists past 5 minutes.",
    fluidRequirements: "Nil by mouth until fully conscious and alert.",
    emergencyContact: "Neurology Specialist / Epilepsy Nurse Coordinator"
  }
};

export const MedicalProfile: React.FC = () => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    surgicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    prenatalScans: '', birthDetails: '', neonatalConcerns: ''
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({ caregiverObservations: '' });

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'complex' | 'sickday' | 'development' | 'attachment'>('history');
  const [smartNotes, setSmartNotes] = useState('');
  const [smartImage, setSmartImage] = useState<string | null>(null);

  const smartFileInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });
  const [filterQuery, setFilterQuery] = useState('');

  const handleSmartImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSmartImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleMagicFill = async () => {
    if (!smartNotes && !smartImage) return;
    setSmartLoading(true);
    try {
      const extracted = await extractProfileFromText(smartNotes, smartImage || undefined);

      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: extracted.pastMedicalHistory || prev.pastMedicalHistory,
        surgicalHistory: extracted.surgicalHistory || prev.surgicalHistory,
        currentMedications: [...new Set([...prev.currentMedications, ...(extracted.currentMedications || [])])],
        allergies: [...new Set([...prev.allergies, ...(extracted.allergies || [])])],
        specialists: [...prev.specialists, ...(extracted.specialists || []).map((s: any) => ({ ...s, id: Math.random().toString(36).substr(2, 9) }))],
        devices: [...prev.devices, ...(extracted.devices || []).map((d: any) => ({ ...d, id: Math.random().toString(36).substr(2, 9) }))],
        sickDayPlan: {
          ...prev.sickDayPlan,
          ...extracted.sickDayPlan
        }
      }));

      setSmartNotes('');
      setSmartImage(null);
      alert("Health profile updated! Please check the individual sections.");
    } catch (e) {
      console.error(e);
      alert("Smart Fill failed. Please fill fields manually.");
    } finally {
      setSmartLoading(false);
    }
  };

  const applyTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      setHistory(prev => ({
        ...prev,
        sickDayPlan: { ...prev.sickDayPlan, ...template }
      }));
      setActiveTab('sickday');
    }
  };

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name.trim() && newSpecialist.specialty.trim()) {
      const specialist: SpecialistContact = {
        id: Math.random().toString(36).substr(2, 9),
        ...newSpecialist
      };
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, specialist] }));
      setNewSpecialist({ name: '', specialty: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type.trim()) {
      const device: MedicalDevice = {
        id: Math.random().toString(36).substr(2, 9),
        ...newDevice
      };
      setHistory(prev => ({ ...prev, devices: [...prev.devices, device] }));
      setNewDevice({ type: '', notes: '' });
    }
  };

  const updateSickDay = (field: keyof SickDayPlan, value: string) => {
    setHistory(prev => ({
      ...prev,
      sickDayPlan: { ...prev.sickDayPlan, [field]: value }
    }));
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("Error generating summary.");
    } finally {
      setLoading(false);
    }
  };

  const filteredMeds = useMemo(() => {
    if (!filterQuery) return history.currentMedications;
    return history.currentMedications.filter(m => m.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.currentMedications, filterQuery]);

  const filteredAllergies = useMemo(() => {
    if (!filterQuery) return history.allergies;
    return history.allergies.filter(a => a.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.allergies, filterQuery]);

  const isHistoryMatch = useMemo(() => {
    if (!filterQuery) return true;
    const q = filterQuery.toLowerCase();
    return history.pastMedicalHistory.toLowerCase().includes(q) || 
           history.surgicalHistory.toLowerCase().includes(q) ||
           JSON.stringify(history.sickDayPlan).toLowerCase().includes(q);
  }, [history, filterQuery]);

  return (
    <div className="space-y-8 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Health Companion Profile</h2>
          <p className="text-slate-500 font-medium">Capture complex histories with clinical accuracy.</p>
        </div>
        <div className="bg-indigo-600 text-white px-5 py-2 rounded-2xl text-xs font-bold uppercase tracking-widest shadow-lg">
          Personal Record
        </div>
      </header>

      {/* Smart Entry Dashboard */}
      <section className="bg-white p-8 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden relative">
        <div className="relative z-10 space-y-6">
          <div className="flex items-center gap-3">
            <span className="text-3xl">🪄</span>
            <h3 className="text-2xl font-bold text-slate-800">Smart Entry & Clinical Templates</h3>
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-4">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Document OCR / Brain Dump</label>
              <textarea 
                value={smartNotes}
                onChange={e => setSmartNotes(e.target.value)}
                placeholder="Paste letter text or upload a photo to auto-fill..."
                className="w-full h-32 p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none text-sm resize-none font-medium"
              />
              <div className="flex gap-2">
                <input type="file" ref={smartFileInputRef} className="hidden" onChange={handleSmartImageUpload} accept="image/*" />
                <button 
                  onClick={() => smartFileInputRef.current?.click()}
                  className="flex-1 py-3 bg-slate-100 rounded-xl font-bold text-xs text-slate-600 hover:bg-slate-200"
                >
                  {smartImage ? '📄 Image Attached' : '📷 Upload Photo'}
                </button>
                <button 
                  onClick={handleMagicFill}
                  disabled={smartLoading || (!smartNotes && !smartImage)}
                  className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 disabled:bg-slate-300"
                >
                  {smartLoading ? '...' : '✨ Smart Fill'}
                </button>
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest block mb-4">Magic Sick Day Templates</label>
              <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-1 gap-2">
                <button onClick={() => applyTemplate('asthma')} className="w-full p-4 bg-white border border-slate-100 rounded-2xl text-left hover:border-indigo-400 transition-all group">
                  <div className="flex items-center gap-3">
                    <span className="text-2xl group-hover:scale-110 transition-transform">🫁</span>
                    <div>
                      <h4 className="font-bold text-slate-800 text-sm leading-tight">Asthma Plan</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">4x4 Protocol Included</p>
                    </div>
                  </div>
                </button>
                <button onClick={() => applyTemplate('metabolic')} className="w-full p-4 bg-white border border-slate-100 rounded-2xl text-left hover:border-indigo-400 transition-all group">
                  <div className="flex items-center gap-3">
                    <span className="text-2xl group-hover:scale-110 transition-transform">🧪</span>
                    <div>
                      <h4 className="font-bold text-slate-800 text-sm leading-tight">Metabolic Crisis</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">Emergency Letter Ready</p>
                    </div>
                  </div>
                </button>
                <button onClick={() => applyTemplate('seizure')} className="w-full p-4 bg-white border border-slate-100 rounded-2xl text-left hover:border-indigo-400 transition-all group">
                  <div className="flex items-center gap-3">
                    <span className="text-2xl group-hover:scale-110 transition-transform">🧠</span>
                    <div>
                      <h4 className="font-bold text-slate-800 text-sm leading-tight">Seizure Plan</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">Rescue Midazolam</p>
                    </div>
                  </div>
                </button>
              </div>
            </div>
          </div>
        </div>
      </section>

      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm max-w-full overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📋' },
          { id: 'complex', label: 'Team & Gear', icon: '🏥' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🤒' },
          { id: 'development', label: 'Birth Record', icon: '🐣' },
          { id: 'attachment', label: 'Emotional', icon: '🤝' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 px-4 rounded-2xl font-bold transition-all flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span>{tab.icon}</span>
            <span className="whitespace-nowrap">{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div className="relative group">
              <input 
                type="text"
                placeholder="Search medications, history..."
                value={filterQuery}
                onChange={(e) => setFilterQuery(e.target.value)}
                className="w-full pl-6 pr-6 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] outline-none font-bold text-slate-700 shadow-inner"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Medications</label>
                <div className="flex gap-2">
                  <input value={newMed} onChange={e => setNewMed(e.target.value)} placeholder="e.g. Melatonin 2mg" className="flex-1 p-4 rounded-2xl border border-slate-100 bg-slate-50/30" />
                  <button onClick={handleAddMed} className="bg-indigo-600 text-white w-14 h-14 rounded-2xl text-2xl shadow-lg">＋</button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {filteredMeds.map((m, i) => (
                    <span key={i} className="px-4 py-2 bg-indigo-50 text-indigo-700 rounded-xl text-sm font-bold border border-indigo-100">{m}</span>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Allergies</label>
                <div className="flex gap-2">
                  <input value={newAllergy} onChange={e => setNewAllergy(e.target.value)} placeholder="e.g. Peanuts" className="flex-1 p-4 rounded-2xl border border-slate-100 bg-slate-50/30" />
                  <button onClick={handleAddAllergy} className="bg-rose-500 text-white w-14 h-14 rounded-2xl text-2xl shadow-lg">＋</button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {filteredAllergies.map((a, i) => (
                    <span key={i} className="px-4 py-2 bg-rose-50 text-rose-700 rounded-xl text-sm font-black border border-rose-100">{a}</span>
                  ))}
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Health History</label>
                <textarea 
                  value={history.pastMedicalHistory}
                  onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                  className="w-full h-40 p-6 rounded-[2rem] border border-slate-200 outline-none font-medium text-slate-700 bg-slate-50/30"
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Surgical Record</label>
                <textarea 
                  value={history.surgicalHistory}
                  onChange={e => setHistory({...history, surgicalHistory: e.target.value})}
                  className="w-full h-40 p-6 rounded-[2rem] border border-slate-200 outline-none font-medium text-slate-700 bg-slate-50/30"
                />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div className="bg-orange-50 p-10 rounded-[3rem] border border-orange-200 shadow-xl relative overflow-hidden">
              <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 mb-10">
                <div className="w-20 h-20 bg-orange-500 rounded-[2rem] flex items-center justify-center text-4xl text-white shadow-2xl">🤒</div>
                <div>
                  <h3 className="text-3xl font-bold text-orange-950">Active Sick Day Protocol</h3>
                  <p className="text-orange-800 font-bold opacity-70">Guided by QCH and RCH specialized action plans.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 relative z-10">
                <div className="space-y-6">
                   <div>
                    <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Triggers & Red Flags</label>
                    <textarea 
                      value={history.sickDayPlan.triggers}
                      onChange={e => updateSickDay('triggers', e.target.value)}
                      placeholder="Symptoms that indicate it's time to start the plan..."
                      className="w-full h-40 p-6 rounded-[2rem] border border-orange-200 outline-none bg-white font-medium text-orange-900 shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Emergency Rescue Meds</label>
                    <textarea 
                      value={history.sickDayPlan.emergencyMeds}
                      onChange={e => updateSickDay('emergencyMeds', e.target.value)}
                      placeholder="Specific doses for crisis (e.g. Solu-Cortef, Midazolam)..."
                      className="w-full h-40 p-6 rounded-[2rem] border border-orange-200 outline-none bg-white font-medium text-orange-900 shadow-sm"
                    />
                  </div>
                </div>

                <div className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Fluid Rescue (Sugar/Volume)</label>
                    <textarea 
                      value={history.sickDayPlan.fluidRequirements}
                      onChange={e => updateSickDay('fluidRequirements', e.target.value)}
                      placeholder="e.g. 10% glucose SOS solution, or asthma hydration..."
                      className="w-full h-40 p-6 rounded-[2rem] border border-orange-200 outline-none bg-white font-medium text-orange-900 shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Critical On-Call Contact</label>
                    <input 
                      type="text"
                      value={history.sickDayPlan.emergencyContact}
                      onChange={e => updateSickDay('emergencyContact', e.target.value)}
                      placeholder="Specialist team after-hours number..."
                      className="w-full p-6 rounded-[2rem] border border-orange-200 outline-none bg-white font-bold text-orange-900 shadow-sm"
                    />
                  </div>
                </div>
              </div>

              <div className="mt-8 relative z-10">
                <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Detailed Step-by-Step Instructions</label>
                <textarea 
                  value={history.sickDayPlan.instructions}
                  onChange={e => updateSickDay('instructions', e.target.value)}
                  placeholder="The full medical protocol..."
                  className="w-full h-64 p-8 rounded-[3rem] border border-orange-200 outline-none resize-none text-xl font-bold bg-white text-orange-950 shadow-inner"
                />
              </div>
            </div>
          </div>
        )}

        {/* Other tabs remain largely the same visually but now include the logic for templates and smart entry */}
        {activeTab === 'complex' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-200">
              <h4 className="font-bold text-slate-800 mb-6 flex items-center gap-3">👩‍⚕️ Clinical Support Team</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                <input placeholder="Doctor Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="p-4 rounded-2xl border border-slate-100" />
                <input placeholder="Specialty" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="p-4 rounded-2xl border border-slate-100" />
              </div>
              <button onClick={handleAddSpecialist} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl">Add to Team</button>
              <div className="mt-8 space-y-3">
                {history.specialists.map(s => (
                  <div key={s.id} className="bg-white p-5 rounded-[1.5rem] border border-slate-50 flex justify-between items-center shadow-sm">
                    <div>
                      <span className="font-black text-indigo-600 text-[10px] uppercase block">{s.specialty}</span>
                      <span className="text-slate-800 font-bold">{s.name}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex justify-center pt-10">
        <button 
          onClick={handleAnalyze}
          disabled={loading}
          className={`px-16 py-6 rounded-[2.5rem] font-black text-xl text-white shadow-2xl flex items-center gap-4 ${
            loading ? 'bg-slate-300' : 'bg-indigo-700'
          }`}
        >
          {loading ? 'Processing...' : '📄 Generate Full Health Summary ✨'}
        </button>
      </div>

      {aiAnalysis && (
        <div className="bg-white p-12 rounded-[4rem] border border-indigo-100 shadow-2xl mt-16 animate-in zoom-in-95 border-l-[16px] border-l-indigo-600">
          <div className="prose prose-indigo max-w-none prose-xl">
            <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic">
              {aiAnalysis.text}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

