  const [activeTab, setActiveTab] = useState('Newborn');

  const toggleMilestone = (id: string) => {
    setMilestones(prev => prev.map(m => m.id === id ? { ...m, completed: !m.completed } : m));
  };

  const ageGroups = ['Newborn', '6 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];

  const currentMilestones = milestones.filter(m => m.ageRange === activeTab && m.category !== 'Red Flag');
