          </div>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600 rounded-full -mr-32 -mt-32 opacity-20 blur-3xl"></div>
      </section>

      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm text-center">
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-2">Reference Standard</p>
        <p className="text-slate-600 font-medium">Queensland Paediatric Clinical Guidelines - Early Years Developmental Red Flags</p>
