            {/* Split description for emphasis on example */}
            <div className="space-y-2">
              <p className={`text-lg font-bold leading-tight ${m.completed ? 'opacity-80' : 'text-slate-800'}`}>
                {m.description.split('. Example:')[0]}
              </p>
              {m.description.includes('. Example:') && (
                <p className={`text-sm font-medium italic ${m.completed ? 'opacity-60' : 'text-slate-500'}`}>
                  <span className="font-bold not-italic text-[10px] uppercase tracking-wider block mb-1 opacity-70">What it looks like:</span>
                  {m.description.split('. Example:')[1]}
                </p>
              )}
            </div>

            {m.isRedFlag && !m.completed && (
              <div className="mt-4 flex items-center gap-2 text-rose-500">
                <span className="animate-pulse">⚠️</span>
                <span className="text-[10px] font-black uppercase tracking-tighter">Seek advice if observed regularly</span>
              </div>
            )}
            {m.isRedFlag && m.completed && (
              <div className="mt-4 flex items-center gap-2 text-rose-900 font-bold text-xs bg-rose-200/50 p-2 rounded-xl border border-rose-200">
                <span>📍</span> Logged for Doctor Discussion
              </div>
            )}
          </button>
        ))}
        {filteredData.length === 0 && (
          <div className="md:col-span-2 py-20 text-center text-slate-400 italic font-medium">
            No specific records for this selection.
          </div>
        )}
      </div>

      <section className="mt-12 p-8 bg-indigo-950 rounded-[3rem] text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
          <div className="text-6xl group-hover:rotate-12 transition-transform duration-500">🚑</div>
          <div className="space-y-3">
            <h4 className="text-2xl font-black italic tracking-tight">The "Loss of Skills" Rule</h4>
            <p className="text-indigo-100 text-lg leading-relaxed font-medium">
              If your child stops doing something they once could (e.g., stops talking, stops making eye contact, stops sitting), this is a <strong>top-priority red flag</strong>. Contact your pediatrician immediately for a review.
            </p>
          </div>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600 rounded-full -mr-32 -mt-32 opacity-20 blur-3xl"></div>
      </section>

      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm text-center">
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-2">Reference Standard</p>
        <p className="text-slate-600 font-medium text-sm">Queensland Paediatric Clinical Guidelines - Early Years Developmental Red Flags</p>
        <a href="https://www.childrens.health.qld.gov.au/__data/assets/pdf_file/0026/167093/red-flags.pdf" target="_blank" rel="noreferrer" className="text-indigo-600 text-xs font-black hover:underline mt-2 inline-block">View Official QCH PDF Resource</a>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

