      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div className="relative group">
              <input 
                type="text"
                placeholder="Search history or meds..."
                value={filterQuery}
                onChange={(e) => setFilterQuery(e.target.value)}
                className="w-full pl-6 pr-6 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] outline-none font-bold text-slate-700 shadow-inner focus:ring-2 focus:ring-indigo-500"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Medications</label>
                <div className="flex gap-2">
                  <input value={newMed} onChange={e => setNewMed(e.target.value)} placeholder="e.g. Melatonin 2mg" className="flex-1 p-4 rounded-2xl border border-slate-100 bg-slate-50/30" />
                  <button onClick={handleAddMed} className="bg-indigo-600 text-white w-14 h-14 rounded-2xl text-2xl shadow-lg transition-transform active:scale-95">＋</button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {filteredMeds.map((m, i) => (
                    <span key={i} className="px-4 py-2 bg-indigo-50 text-indigo-700 rounded-xl text-sm font-bold border border-indigo-100">{m}</span>
                  ))}
