                <div className="flex flex-wrap gap-2">
                  {filteredAllergies.map((a, i) => (
                    <span key={i} className="px-4 py-2 bg-rose-50 text-rose-700 rounded-xl text-sm font-black border border-rose-100">{a}</span>
                  ))}
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Medical History Details</label>
                <textarea 
                  value={history.pastMedicalHistory}
                  onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                  className="w-full h-40 p-6 rounded-[2rem] border border-slate-200 outline-none font-medium text-slate-700 bg-slate-50/30 focus:ring-2 focus:ring-indigo-500"
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Surgical History</label>
                <textarea 
                  value={history.surgicalHistory}
                  onChange={e => setHistory({...history, surgicalHistory: e.target.value})}
                  className="w-full h-40 p-6 rounded-[2rem] border border-slate-200 outline-none font-medium text-slate-700 bg-slate-50/30 focus:ring-2 focus:ring-indigo-500"
                />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div className="bg-orange-50 p-10 rounded-[3rem] border border-orange-200 shadow-xl relative overflow-hidden">
              <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 mb-10">
                <div className="w-20 h-20 bg-orange-500 rounded-[2rem] flex items-center justify-center text-4xl text-white shadow-2xl">🤒</div>
                <div>
                  <h3 className="text-3xl font-bold text-orange-950">Active Sick Day Protocol</h3>
                  <p className="text-orange-800 font-bold opacity-70">Customizable guidance for managing illness and flares.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 relative z-10">
                <div className="space-y-6">
                   <div>
                    <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Triggers & Red Flags</label>
                    <textarea 
                      value={history.sickDayPlan.triggers}
                      onChange={e => updateSickDay('triggers', e.target.value)}
                      placeholder="Symptoms that indicate it's time to start the plan..."
                      className="w-full h-40 p-6 rounded-[2rem] border border-orange-200 outline-none bg-white font-medium text-orange-900 shadow-sm focus:ring-2 focus:ring-orange-500"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Emergency Rescue Meds</label>
                    <textarea 
                      value={history.sickDayPlan.emergencyMeds}
