                      className="w-full p-6 rounded-[2rem] border border-orange-200 outline-none bg-white font-bold text-orange-900 shadow-sm focus:ring-2 focus:ring-orange-500"
                    />
                  </div>
                </div>
              </div>

              <div className="mt-8 relative z-10">
                <label className="block text-[10px] font-black text-orange-900 uppercase tracking-widest mb-3 ml-2">Detailed Instructions</label>
