                <div className="space-y-4 mb-6">
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="Doctor Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="p-4 rounded-2xl border border-slate-100" />
                    <input placeholder="Specialty" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="p-4 rounded-2xl border border-slate-100" />
                  </div>
                  <button onClick={handleAddSpecialist} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl transition-all hover:bg-indigo-700 active:scale-95">Add to Team</button>
                </div>
                <div className="space-y-3">
                  {history.specialists.map(s => (
                    <div key={s.id} className="bg-white p-5 rounded-[1.5rem] border border-slate-50 flex justify-between items-center shadow-sm">
                      <div>
                        <span className="font-black text-indigo-600 text-[10px] uppercase block">{s.specialty}</span>
                        <span className="text-slate-800 font-bold">{s.name}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-200">
                <h4 className="font-bold text-slate-800 mb-6 flex items-center gap-3">🛠️ Medical Devices</h4>
                <div className="space-y-4 mb-6">
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="Device Type (e.g. G-Tube)" value={newDevice.type} onChange={e => setNewDevice({...newDevice, type: e.target.value})} className="p-4 rounded-2xl border border-slate-100" />
                    <input placeholder="Notes / Model" value={newDevice.notes} onChange={e => setNewDevice({...newDevice, notes: e.target.value})} className="p-4 rounded-2xl border border-slate-100" />
                  </div>
                  <button onClick={handleAddDevice} className="w-full py-4 bg-slate-800 text-white font-black rounded-2xl shadow-xl transition-all hover:bg-slate-900 active:scale-95">Add Device</button>
                </div>
                <div className="space-y-3">
                  {history.devices.map(d => (
                    <div key={d.id} className="bg-white p-5 rounded-[1.5rem] border border-slate-50 flex justify-between items-center shadow-sm">
                      <div>
                        <span className="font-black text-slate-400 text-[10px] uppercase block">Device</span>
                        <span className="text-slate-800 font-bold">{d.type}</span>
                        <p className="text-xs text-slate-500">{d.notes}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'development' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Prenatal History</label>
                <textarea 
                  value={devHistory.prenatalScans}
                  onChange={e => setDevHistory({...devHistory, prenatalScans: e.target.value})}
                  className="w-full h-40 p-6 rounded-[2rem] border border-slate-200 outline-none font-medium text-slate-700 bg-slate-50/30"
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Birth Details</label>
                <textarea 
                  value={devHistory.birthDetails}
                  onChange={e => setDevHistory({...devHistory, birthDetails: e.target.value})}
                  className="w-full h-40 p-6 rounded-[2rem] border border-slate-200 outline-none font-medium text-slate-700 bg-slate-50/30"
                />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'attachment' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div className="bg-pink-50 p-10 rounded-[3rem] border border-pink-100">
               <div className="flex items-center gap-4 mb-6">
                <span className="text-4xl">🫂</span>
                <h3 className="text-2xl font-bold text-pink-900">Emotional Connection & Attachment</h3>
              </div>
              <p className="text-pink-800/70 mb-6 font-medium">Record observations about bonding, soothing, and interaction patterns.</p>
              <textarea 
                value={attachment.caregiverObservations}
                onChange={e => setAttachment({...attachment, caregiverObservations: e.target.value})}
                placeholder="How does your child respond to comfort? What are their unique cues?"
                className="w-full h-64 p-8 rounded-[2.5rem] border border-pink-200 outline-none font-medium text-pink-950 bg-white shadow-inner focus:ring-2 focus:ring-pink-500"
              />
            </div>
          </div>
        )}
      </div>

      <div className="flex flex-col items-center gap-4 pt-10">
        <button 
          onClick={handleAnalyze}
          disabled={loading}
          className={`px-16 py-6 rounded-[2.5rem] font-black text-xl text-white shadow-2xl flex items-center gap-4 transition-all transform hover:-translate-y-2 active:scale-95 ${
            loading ? 'bg-slate-300' : 'bg-indigo-700'
          }`}
        >
          {loading ? (
            <>
              <div className="w-6 h-6 border-4 border-white border-t-transparent rounded-full animate-spin" />
              Synthesizing History...
            </>
          ) : (
            <>
              <span>📋</span> Generate Concise Doctor Handover ✨
            </>
          )}
        </button>
        <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Designed for specialist & GP consultations</p>
      </div>

      {aiAnalysis && (
        <div className="bg-white p-12 rounded-[4rem] border border-indigo-100 shadow-2xl mt-16 animate-in zoom-in-95 border-l-[16px] border-l-indigo-600 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 flex gap-2">
             <button 
              onClick={handleCopy}
              className={`px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all flex items-center gap-2 ${
                copySuccess ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
              }`}
            >
              {copySuccess ? '✓ Copied' : '📋 Copy for Doctor'}
            </button>
          </div>

          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-3xl font-bold text-slate-800">Specialist Health Handover</h3>
              <p className="text-indigo-500 font-bold text-sm">Review clinical patterns, meds, and crisis protocols.</p>
            </div>
          </div>

          <div className="prose prose-indigo max-w-none prose-lg">
            <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic">
              {aiAnalysis.text}
            </div>
          </div>

          <div className="mt-12 p-8 bg-indigo-50 rounded-[2.5rem] border border-indigo-100 flex gap-4">
            <span className="text-3xl">📝</span>
            <div className="space-y-1">
              <h4 className="font-black text-indigo-900 text-sm uppercase tracking-widest">Handover Best Practice</h4>
              <p className="text-indigo-800 text-sm leading-relaxed">
                Show this summary to your doctor. It highlights critical "Sick Day Plans" and specialist-managed care often buried in long history letters.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export interface SymptomLog {
  id: string;
  timestamp: Date;
  description: string;
  aiResponse: string;
  media?: string;
}

export interface GrowthRecord {
  age: number; // in months
  weight: number; // kg
  height: number; // cm
  headCircumference?: number; // cm
  date: string;
}

export interface Vaccination {
  id: string;
  name: string;
  dueDate: Date;
  receivedDate?: Date;
  status: 'pending' | 'completed' | 'overdue';
  description: string;
  ageMilestone: number; // in months
  manufacturer?: string;
  lotNumber?: string;
  clinic?: string;
}

export interface Milestone {
  id: string;
  ageRange: string;
  category: 'Motor' | 'Cognitive' | 'Social' | 'Language';
  description: string;
  completed: boolean;
  isRedFlag: boolean;
}

export interface HealthCheck {
  id: string;
  ageMilestone: string;
  date?: string;
  completed: boolean;
  notes: string;
  professionalName?: string;
}

export interface SpecialistContact {
  id: string;
  name: string;
  specialty: string;
  hospital?: string;
  contact?: string;
}

export interface MedicalDevice {
  id: string;
  type: string;
  model?: string;
  lastChanged?: string;
  notes?: string;
}

export interface FamilyHistory {
  maternal: string;
  paternal: string;
  siblings: string;
  other: string;
}

export interface SickDayPlan {
  instructions: string;
  emergencyMeds: string;
  fluidRequirements: string;
  triggers: string;
  emergencyContact: string;
}

export interface MedicalHistory {
  pastMedicalHistory: string;
  surgicalHistory: string;
  currentMedications: string[];
  allergies: string[];
  familyHistory: FamilyHistory;
  specialists: SpecialistContact[];
  devices: MedicalDevice[];
  sickDayPlan: SickDayPlan;
}

export interface DevelopmentalHistory {
  // Pregnancy
  pregnancyMedications: string;
  pregnancyComplications: string; // e.g. diabetes, BP, infections
  scansAndTests: string;
  exposureConcerns: string; // e.g. smoking, alcohol, drugs

  // Birth
  gestationalAge: string; // weeks/days
  laborType: string; // e.g. spontaneous, induced
  deliveryMode: string; // e.g. vaginal, forceps, vacuum, C-section
  birthComplications: string;
  birthWeight?: number;
  birthLength?: number;
  birthHeadCirc?: number;
  apgar1?: number;
  apgar5?: number;
  resuscitationNeeded: string;

  // Neonatal
  jaundiceTreatment: string;
  specialCareNursery: string; // NICU/SCN details
  feedingIssues: string; // e.g. tongue tie, reflux, allergies
  earlyNeonatalConcerns: string;

  // Early Progress
  earlyMilestones: {
    smile: string;
    sit: string;
    walk: string;
    firstWords: string;
  };
  currentDevelopmentalConcerns: string;
}

export interface AttachmentAnalysis {
  caregiverObservations: string;
  aiInterpretation?: string;
}

export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting';

import React, { useState, useMemo, useRef } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Follow 4x4 protocol: 4 puffs of Ventolin (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4 puffs. CALL 000 if: distressed, lips blue, or skin sucking in around ribs.",
    triggers: "Viral colds, exercise, cigarette smoke, seasonal pollens, cold air.",
    emergencyMeds: "Salbutamol (Ventolin) 100mcg/puff. Prednisolone (Oral Steroid) - Dose: [X] mg daily for 3 days as per doctor.",
    fluidRequirements: "Offer small frequent sips of water. Monitor for signs of dehydration due to increased respiratory effort.",
    emergencyContact: "Family GP / Local Emergency Department"
  },
  metabolic: {
    instructions: "CRITICAL: Follow Emergency Letter instructions. Initiate high glucose fluids (10% glucose) every 1-2 hours. If vomiting once, proceed directly to Hospital ED for IV Dextrose. DO NOT FAST.",
    triggers: "Fever >38.5, vomiting, diarrhea, or refusing food/fluids.",
    emergencyMeds: "Emergency Glucose Letter (Hand to Triage Nurse). Rescue Fluids (SOS 10%) as prescribed.",
    fluidRequirements: "Max dose glucose solution (SOS/10%) at calculated maintenance rate (e.g. 100ml/kg/24hr).",
    emergencyContact: "Metabolic On-Call Registrar (Children's Hospital)"
  },
  seizure: {
    instructions: "Time the seizure. Protect head, move to safe side position once safe. DO NOT put anything in mouth. Call 000 if: seizure >5 mins, first seizure, or difficulty breathing after.",
    triggers: "Fever (Febrile), missed medication, sleep deprivation, illness, bright flashing lights.",
    emergencyMeds: "Midazolam (Buccal/Intranasal) - Dose: [X] mg if seizure persists past 5 minutes.",
    fluidRequirements: "Nil by mouth until fully conscious, alert, and swallowing safely.",
    emergencyContact: "Neurology Specialist / Epilepsy Nurse Coordinator"
  },
  anaphylaxis: {
    instructions: "Lay child flat. Do not stand or walk. If breathing is difficult, allow them to sit. Administer Adrenaline Autoinjector (EpiPen) into outer mid-thigh. Call 000 immediately. Record time of administration.",
    triggers: "Specific allergens (e.g., Peanuts, Dairy, Egg, Bee stings).",
    emergencyMeds: "Adrenaline Autoinjector (EpiPen 0.15mg/0.3mg). Second dose may be given after 5 mins if no improvement.",
    fluidRequirements: "Nil by mouth until cleared by hospital staff.",
    emergencyContact: "Immunology Team / Ambulance (000)"
  },
  adrenal: {
    instructions: "Give 'Stress Dose' of oral Hydrocortisone immediately. If child is vomiting or lethargic, administer Solu-Cortef injection (IM) and seek urgent medical care at the nearest Emergency Department.",
    triggers: "Fever >38°C, major injury, persistent vomiting, or major surgery.",
    emergencyMeds: "Hydrocortisone tablets (Stress Dosing). Solu-Cortef (Injection kit) for home use.",
    fluidRequirements: "Encourage fluids with electrolytes (e.g., Hydralyte) to prevent sodium loss.",
    emergencyContact: "Endocrinology Team / On-call Specialist"
  }
};

export const MedicalProfile: React.FC = () => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    surgicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    pregnancyMedications: '',
    pregnancyComplications: '',
    scansAndTests: '',
    exposureConcerns: '',
    gestationalAge: '',
    laborType: '',
    deliveryMode: '',
    birthComplications: '',
    birthWeight: undefined,
    birthLength: undefined,
    birthHeadCirc: undefined,
    apgar1: undefined,
    apgar5: undefined,
    resuscitationNeeded: '',
    jaundiceTreatment: '',
    specialCareNursery: '',
    feedingIssues: '',
    earlyNeonatalConcerns: '',
    earlyMilestones: {
      smile: '',
      sit: '',
      walk: '',
      firstWords: '',
    },
    currentDevelopmentalConcerns: ''
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({ caregiverObservations: '' });

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'complex' | 'sickday' | 'development' | 'attachment'>('history');
  const [smartNotes, setSmartNotes] = useState('');
  const [smartImage, setSmartImage] = useState<string | null>(null);
  const [templateApplied, setTemplateApplied] = useState<string | null>(null);
  const [copySuccess, setCopySuccess] = useState(false);

  const smartFileInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });
  const [filterQuery, setFilterQuery] = useState('');

  const handleSmartImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSmartImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleMagicFill = async () => {
    if (!smartNotes && !smartImage) return;
    setSmartLoading(true);
    try {
      const extracted = await extractProfileFromText(smartNotes, smartImage || undefined);

      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: extracted.pastMedicalHistory || prev.pastMedicalHistory,
        surgicalHistory: extracted.surgicalHistory || prev.surgicalHistory,
        currentMedications: [...new Set([...prev.currentMedications, ...(extracted.currentMedications || [])])],
        allergies: [...new Set([...prev.allergies, ...(extracted.allergies || [])])],
        specialists: [...prev.specialists, ...(extracted.specialists || []).map((s: any) => ({ ...s, id: Math.random().toString(36).substr(2, 9) }))],
        devices: [...prev.devices, ...(extracted.devices || []).map((d: any) => ({ ...d, id: Math.random().toString(36).substr(2, 9) }))],
        sickDayPlan: {
          ...prev.sickDayPlan,
          ...extracted.sickDayPlan
        }
      }));

      setSmartNotes('');
      setSmartImage(null);
      alert("Health profile updated! Please check the individual sections.");
    } catch (e) {
      console.error(e);
      alert("Smart Fill failed. Please fill fields manually.");
    } finally {
      setSmartLoading(false);
    }
  };

  const applyTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      setHistory(prev => ({
        ...prev,
        sickDayPlan: { ...prev.sickDayPlan, ...template }
      }));
      setTemplateApplied(type.charAt(0).toUpperCase() + type.slice(1));
      setActiveTab('sickday');
      setTimeout(() => setTemplateApplied(null), 3000);
    }
  };

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name.trim() && newSpecialist.specialty.trim()) {
      const specialist: SpecialistContact = {
        id: Math.random().toString(36).substr(2, 9),
        ...newSpecialist
      };
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, specialist] }));
      setNewSpecialist({ name: '', specialty: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type.trim()) {
      const device: MedicalDevice = {
        id: Math.random().toString(36).substr(2, 9),
        ...newDevice
      };
      setHistory(prev => ({ ...prev, devices: [...prev.devices, device] }));
      setNewDevice({ type: '', notes: '' });
    }
  };

  const updateSickDay = (field: keyof SickDayPlan, value: string) => {
    setHistory(prev => ({
      ...prev,
      sickDayPlan: { ...prev.sickDayPlan, [field]: value }
    }));
  };

  const updateDevHistory = (field: keyof DevelopmentalHistory | 'earlyMilestones', value: any) => {
    if (typeof field === 'string' && field === 'earlyMilestones') {
      setDevHistory(prev => ({
        ...prev,
        earlyMilestones: { ...prev.earlyMilestones, ...value }
      }));
    } else {
      setDevHistory(prev => ({
        ...prev,
        [field as keyof DevelopmentalHistory]: value
      }));
    }
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (error) {
      console.error(error);
      alert("Error generating summary.");
    } finally {
      setLoading(false);
    }
  };

  const handleCopy = () => {
    if (aiAnalysis) {
      navigator.clipboard.writeText(aiAnalysis.text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const filteredMeds = useMemo(() => {
    if (!filterQuery) return history.currentMedications;
    return history.currentMedications.filter(m => m.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.currentMedications, filterQuery]);

  const filteredAllergies = useMemo(() => {
    if (!filterQuery) return history.allergies;
    return history.allergies.filter(a => a.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.allergies, filterQuery]);

  return (
    <div className="space-y-8 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Health Companion Profile</h2>
          <p className="text-slate-500 font-medium">Capture complex histories with clinical accuracy.</p>
        </div>
        <div className="bg-indigo-600 text-white px-5 py-2 rounded-2xl text-xs font-bold uppercase tracking-widest shadow-lg">
          Personal Record
        </div>
      </header>

      {/* Smart Entry Dashboard */}
      <section className="bg-white p-8 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden relative">
        <div className="relative z-10 space-y-6">
          <div className="flex items-center justify-between">
             <div className="flex items-center gap-3">
              <span className="text-3xl">🪄</span>
              <h3 className="text-2xl font-bold text-slate-800">Smart Entry & Clinical Templates</h3>
            </div>
            {templateApplied && (
              <div className="bg-emerald-100 text-emerald-700 px-4 py-2 rounded-full text-xs font-bold animate-bounce border border-emerald-200">
                Applied: {templateApplied} Template ✨
              </div>
            )}
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-4">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Document OCR / Brain Dump</label>
              <textarea 
                value={smartNotes}
                onChange={e => setSmartNotes(e.target.value)}
                placeholder="Paste letter text or describe complex history here..."
                className="w-full h-32 p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none text-sm resize-none font-medium focus:ring-2 focus:ring-indigo-500"
              />
              <div className="flex gap-2">
                <input type="file" ref={smartFileInputRef} className="hidden" onChange={handleSmartImageUpload} accept="image/*" />
                <button 
                  onClick={() => smartFileInputRef.current?.click()}
                  className="flex-1 py-3 bg-slate-100 rounded-xl font-bold text-xs text-slate-600 hover:bg-slate-200 transition-colors"
                >
                  {smartImage ? '📄 Image Attached' : '📷 Upload Medical Doc'}
                </button>
                <button 
                  onClick={handleMagicFill}
                  disabled={smartLoading || (!smartNotes && !smartImage)}
                  className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 disabled:bg-slate-300 transition-all transform hover:-translate-y-1 active:translate-y-0"
                >
                  {smartLoading ? '...' : '✨ Smart Fill'}
                </button>
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest block mb-4">Common Plan Templates</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-2 gap-3">
                {[
                  { id: 'asthma', icon: '🫁', name: 'Asthma' },
                  { id: 'metabolic', icon: '🧪', name: 'Metabolic' },
                  { id: 'seizure', icon: '🧠', name: 'Seizure' },
                  { id: 'anaphylaxis', icon: '🥜', name: 'Anaphylaxis' },
                  { id: 'adrenal', icon: '💊', name: 'Adrenal Insuff.' },
                ].map(t => (
                  <button 
                    key={t.id}
                    onClick={() => applyTemplate(t.id)} 
                    className="flex items-center gap-3 p-3 bg-white border border-slate-100 rounded-2xl text-left hover:border-indigo-400 hover:shadow-md transition-all group"
                  >
                    <span className="text-xl group-hover:scale-110 transition-transform">{t.icon}</span>
                    <span className="font-bold text-slate-800 text-xs leading-tight">{t.name}</span>
                  </button>
                ))}
              </div>
              <p className="mt-4 text-[10px] text-slate-400 font-medium italic">
                *Templates populate the "Sick Day Plan" tab. You can customize them there.
              </p>
            </div>
          </div>
        </div>
      </section>

      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm max-w-full overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📋' },
