                 </div>
                 <div className="hidden sm:block">
                    <p className="text-sm font-black text-slate-800 uppercase tracking-tighter">Progress Tracker</p>
                    <p className="text-xs text-slate-400 font-bold">{Object.keys(responses).length} of {activeMod.questions.length} Answered</p>
                 </div>
               </div>
               <button
                onClick={handleSubmit}
                disabled={!isComplete || loading}
                className={`px-12 py-4 rounded-2xl font-black text-white shadow-2xl transition-all uppercase tracking-widest text-sm transform active:scale-95 ${
                  isComplete && !loading 
                    ? 'bg-indigo-600 hover:bg-indigo-700 hover:-translate-y-1'
                    : 'bg-slate-300 cursor-not-allowed grayscale'
                }`}
              >
                {loading ? 'Synthesizing...' : 'Finalize & Analyze✨'}
              </button>
            </div>
          )}

          {analysis && (
            <div className="space-y-8 animate-in slide-in-from-bottom-10 duration-700">
              {/* Visual Result Dashboard */}
              <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-2xl">
                <div className="flex items-center justify-between mb-10">
                  <h3 className="text-3xl font-black text-slate-800 tracking-tight italic">Score Visualization</h3>
                  <div className="px-4 py-1 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100">
                    Clinical Metrics
                  </div>
                </div>

                <div className="h-[400px] w-full bg-slate-50/50 rounded-[3rem] p-8 border border-slate-50 shadow-inner">
                  {activeModKey === 'sdq' && scoreData && (
                    <ResponsiveContainer width="100%" height="100%">
                      <RadarChart cx="50%" cy="50%" outerRadius="80%" data={scoreData as any}>
                        <PolarGrid stroke="#e2e8f0" />
                        <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12, fontWeight: 800 }} />
                        <PolarRadiusAxis angle={30} domain={[0, 4]} tick={false} axisLine={false} />
                        <Radar
                          name="Scoring"
                          dataKey="value"
                          stroke="#14b8a6"
                          fill="#14b8a6"
                          fillOpacity={0.5}
                        />
                        <Tooltip contentStyle={{ borderRadius: '1.5rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                      </RadarChart>
                    </ResponsiveContainer>
                  )}

                  {activeModKey === 'ace' && scoreData && (
                    <div className="flex flex-col items-center justify-center h-full space-y-8">
                       <div className="relative w-64 h-64">
                          <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                            <circle cx="50" cy="50" r="40" stroke="#f1f5f9" strokeWidth="8" fill="transparent" />
                            <circle 
                              cx="50" cy="50" r="40" stroke="#f43f5e" strokeWidth="8" fill="transparent" 
                              strokeDasharray={`${(scoreData[0].value as number / 10) * 251.2}, 251.2`}
                              strokeLinecap="round"
                            />
                          </svg>
                          <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className="text-6xl font-black text-rose-600 leading-none">{scoreData[0].value as number}</span>
                            <span className="text-xs font-black text-slate-400 uppercase tracking-widest mt-1">out of 10</span>
                          </div>
                       </div>
                       <p className="text-slate-500 font-medium text-center max-w-md italic">This score represents the number of specific traumatic category exposures identified. High scores are indicative of increased risk for chronic health issues but are balanced by Positive Childhood Experiences (PCEs).</p>
                    </div>
                  )}

                  {activeModKey === 'vanderbilt' && scoreData && (
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={scoreData as any} layout="vertical" margin={{ left: 40, right: 40 }}>
                        <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                        <XAxis type="number" hide />
                        <YAxis dataKey="category" type="category" tick={{ fill: '#64748b', fontWeight: 700 }} width={120} />
                        <Tooltip cursor={{ fill: 'transparent' }} contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                        <Bar dataKey="count" fill="#6366f1" radius={[0, 10, 10, 0]} barSize={40}>
                           {scoreData.map((entry: any, index: number) => (
                            <Cell key={`cell-${index}`} fill={index === 0 ? '#6366f1' : '#f59e0b'} />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  )}
                </div>

                <div className="mt-10 grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="p-6 bg-teal-50 rounded-[2rem] border border-teal-100 flex gap-4">
                    <span className="text-3xl">📊</span>
                    <div>
                      <h4 className="font-black text-teal-900 text-xs uppercase tracking-widest mb-1">Visual Analysis</h4>
                      <p className="text-teal-800 text-sm font-medium leading-relaxed">This visual breakdown helps identify specific domains where your child might be thriving or facing difficulties.</p>
                    </div>
                  </div>
                  <div className="p-6 bg-amber-50 rounded-[2rem] border border-amber-100 flex gap-4">
                    <span className="text-3xl">📝</span>
                    <div>
                      <h4 className="font-black text-amber-900 text-xs uppercase tracking-widest mb-1">Parental Intuition</h4>
                      <p className="text-amber-800 text-sm font-medium leading-relaxed">Scores are just one part of the story. Your observations as a primary caregiver are the most valuable context for doctors.</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Detailed AI Analysis */}
              <div className="bg-white p-12 rounded-[4rem] border border-teal-100 shadow-2xl border-l-[20px] border-l-teal-600 overflow-hidden relative">
                <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-teal-500 rounded-full opacity-5 blur-3xl"></div>

                <div className="flex items-center gap-6 mb-12">
                  <div className="w-20 h-20 bg-teal-50 rounded-[2rem] flex items-center justify-center text-5xl shadow-2xl">✨</div>
                  <div>
                    <h3 className="text-4xl font-black text-slate-800 tracking-tighter italic">AI Expert Interpretation</h3>
                    <p className="text-teal-600 font-black text-xs uppercase tracking-widest mt-1">Evidence-Based Clinical Context</p>
                  </div>
                </div>

                <div className="prose prose-slate max-w-none prose-lg">
                  <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic border-l-4 border-slate-100 pl-8 mb-12">
                    {analysis.text}
                  </div>
                </div>

                {analysis.sources && analysis.sources.length > 0 && (
                  <div className="mt-12 pt-10 border-t border-slate-100">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Authoritative Guidelines & Support</h4>
                    <div className="flex flex-wrap gap-4">
                      {analysis.sources.map((source: any, i: number) => (
                        <a
                          key={i}
                          href={source.web?.uri}
                          target="_blank"
                          rel="noreferrer"
                          className="px-6 py-4 bg-teal-50 text-teal-700 rounded-3xl text-xs font-black hover:bg-teal-100 transition-all shadow-sm hover:shadow-lg flex items-center gap-3"
                        >
                          🔗 {source.web?.title || 'Clinical Framework'}
                        </a>
                      ))}
                      <a 
                        href="https://emergingminds.com.au/resources/" 
                        target="_blank" 
                        rel="noreferrer" 
                        className="px-6 py-4 bg-slate-900 text-white rounded-3xl text-xs font-black hover:bg-slate-800 transition-all shadow-xl flex items-center gap-3"
                      >
                        🚀 Emerging Minds Resources
                      </a>
                    </div>
                  </div>
                )}

                <div className="mt-12 p-10 bg-rose-50 rounded-[3rem] border-2 border-dashed border-rose-200 text-rose-900 flex flex-col md:flex-row gap-8 items-center">
                   <div className="text-6xl grayscale opacity-50">⚠️</div>
                   <div>
                      <h4 className="font-black text-xl mb-2 tracking-tight">Crucial: This is Not a Diagnosis</h4>
                      <p className="font-medium opacity-80 text-lg leading-relaxed">
                        These scores indicate potential areas of concern for discussion with a Pediatrician or Clinical Psychologist. 
                        AI screening is designed to empower parents with data, not to replace professional medical assessment. 
                        <strong> If you have immediate safety concerns, please contact your GP or local crisis service.</strong>
                      </p>
                   </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { analyzeScreening } from '../services/gemini';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Cell
} from 'recharts';

type ResponseOption = { label: string; value: string };

interface ScreeningMod {
  name: string;
  url: string;
  description: string;
  options: ResponseOption[];
  questions: { id: string; text: string; category?: string }[];
}

