      { label: 'No', value: '0' },
      { label: 'Yes', value: '1' }
    ],
    questions: [
      { id: '1', text: 'Emotional Abuse' },
      { id: '2', text: 'Physical Abuse' },
      { id: '3', text: 'Sexual Abuse' },
      { id: '4', text: 'Emotional Neglect' },
      { id: '5', text: 'Physical Neglect' },
      { id: '6', text: 'Parental Divorce/Separation' },
