                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Describe what you're seeing (e.g. barky cough, noisy breathing, fever, duration)..."
                className="w-full h-44 p-6 rounded-3xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none resize-none transition-all text-lg font-medium leading-relaxed"
              />
            </div>

            <div className="flex flex-wrap items-center gap-4">
              <input
                type="file"
                accept="image/*"
                className="hidden"
                ref={fileInputRef}
                onChange={handleFileChange}
              />
