                onClick={() => fileInputRef.current?.click()}
                className="flex items-center gap-3 px-6 py-4 bg-slate-50 text-slate-700 rounded-2xl hover:bg-slate-100 transition-all font-bold border border-slate-200"
              >
                📷 {image ? 'Change Photo' : 'Upload Sign Photo'}
