                  <div>
                    <h3 className="text-4xl font-black text-slate-800 tracking-tighter italic">AI Expert Interpretation</h3>
                    <p className="text-teal-600 font-black text-xs uppercase tracking-widest mt-1">Evidence-Based Clinical Context</p>
                  </div>
                </div>

                <div className="prose prose-slate max-w-none prose-lg">
                  <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic border-l-4 border-slate-100 pl-8 mb-12">
                    {analysis.text}
                  </div>
                </div>

                {analysis.sources && analysis.sources.length > 0 && (
                  <div className="mt-12 pt-10 border-t border-slate-100">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Authoritative Guidelines & Support</h4>
                    <div className="flex flex-wrap gap-4">
                      {analysis.sources.map((source: any, i: number) => (
                        <a
                          key={i}
                          href={source.web?.uri}
                          target="_blank"
                          rel="noreferrer"
                          className="px-6 py-4 bg-teal-50 text-teal-700 rounded-3xl text-xs font-black hover:bg-teal-100 transition-all shadow-sm hover:shadow-lg flex items-center gap-3"
                        >
                          🔗 {source.web?.title || 'Clinical Framework'}
                        </a>
                      ))}
                      <a 
                        href="https://emergingminds.com.au/resources/" 
                        target="_blank" 
                        rel="noreferrer" 
                        className="px-6 py-4 bg-slate-900 text-white rounded-3xl text-xs font-black hover:bg-slate-800 transition-all shadow-xl flex items-center gap-3"
                      >
                        🚀 Emerging Minds Resources
                      </a>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

