        </div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
           <button 
            onClick={() => setActiveTab('tips')}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'tips' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-500'}`}
