            Positive Parenting
          </button>
          <button 
            onClick={() => setActiveTab('mentalhealth')}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'mentalhealth' ? 'bg-teal-600 text-white shadow-lg' : 'text-slate-500'}`}
          >
            Mental Health
          </button>
          <button 
            onClick={() => setActiveTab('clinical')}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'clinical' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}
          >
