                  className="bg-white p-4 rounded-2xl border border-slate-50 text-left flex items-center justify-between hover:shadow-xl hover:-translate-y-1 transition-all group"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-2xl group-hover:rotate-12 transition-transform">{item.icon}</span>
                    <span className="text-sm font-bold text-slate-700">{item.label}</span>
                  </div>
                  {item.source && (
                    <span className="text-[8px] font-black bg-indigo-100 text-indigo-600 px-2 py-0.5 rounded-full uppercase tracking-widest">
                      {item.source}
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          {loading ? (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-white rounded-[3rem] border border-slate-100 animate-pulse text-slate-400">
              <div className={`text-6xl mb-6 animate-bounce ${activeTab !== 'tips' ? 'grayscale' : ''}`}>🌻</div>
              <p className="font-black text-xl uppercase tracking-tighter">Synthesizing Evidence...</p>
              <p className="text-sm font-medium">Consulting Emerging Minds, CCI WA & Raising Children</p>
            </div>
          ) : advice ? (
            <div className={`bg-white p-12 rounded-[4rem] border shadow-2xl animate-in zoom-in-95 ${
              activeTab === 'mentalhealth' ? 'border-teal-100 border-l-[20px] border-l-teal-600' : 
              activeTab === 'clinical' ? 'border-indigo-100 border-l-[20px] border-l-indigo-600' :
              'border-amber-100 border-l-[20px] border-l-amber-500'
            }`}>
              <div className="flex items-center gap-6 mb-10">
                <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center text-4xl shadow-2xl ${
                  activeTab === 'mentalhealth' ? 'bg-teal-50' : 
                  activeTab === 'clinical' ? 'bg-indigo-50' : 'bg-amber-50'
                }`}>
                  {activeTab === 'mentalhealth' ? '🧠' : activeTab === 'clinical' ? '💎' : '🌻'}
                </div>
                <div>
                  <h3 className="text-3xl font-black text-slate-800 tracking-tight">Parenting Strategy</h3>
                  <p className={`${
                    activeTab === 'mentalhealth' ? 'text-teal-600' : 
                    activeTab === 'clinical' ? 'text-indigo-600' : 'text-amber-600'
                  } font-black text-sm uppercase tracking-widest`}>
                    Clinical Advice for {age}
                  </p>
                </div>
              </div>

              <div className="prose prose-slate max-w-none prose-lg">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic">
                  {advice.text}
                </div>
              </div>

              {advice.sources.length > 0 && (
                <div className="mt-12 pt-8 border-t border-slate-100">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Official Guideline Sources</h4>
                  <div className="flex flex-wrap gap-3">
                    {advice.sources.map((source, i) => (
                      <a
                        key={i}
                        href={source.web?.uri}
                        target="_blank"
                        rel="noreferrer"
                        className={`px-5 py-3 rounded-2xl text-xs font-black transition-all flex items-center gap-2 ${
                          activeTab === 'mentalhealth' ? 'bg-teal-50 text-teal-700 hover:bg-teal-100' : 
                          activeTab === 'clinical' ? 'bg-indigo-50 text-indigo-700 hover:bg-indigo-100' :
                          'bg-amber-50 text-amber-700 hover:bg-amber-100'
                        }`}
                      >
                        🔗 {source.web?.title || 'Authoritative Resource'}
                      </a>
                    ))}
                    <a href="https://www.cci.health.wa.gov.au/Resources/Looking-After-Yourself" target="_blank" rel="noreferrer" className="px-5 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-black hover:bg-indigo-700 transition-all flex items-center gap-2">
                       💎 Explore CCI WA Modules
                    </a>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-slate-50 rounded-[4rem] border-4 border-dashed border-slate-200 text-slate-400 p-12 text-center">
              <div className={`text-8xl mb-8 opacity-20 ${activeTab !== 'tips' ? 'grayscale' : ''}`}>🌻</div>
              <h3 className="text-3xl font-black text-slate-500 mb-4 tracking-tighter">Wellbeing Companion</h3>
              <p className="max-w-md text-slate-400 font-medium text-lg leading-relaxed">
                Select a stage and challenge on the left to receive evidence-based strategies from <strong>Emerging Minds</strong>, <strong>CCI Western Australia</strong>, and clinical Australian networks.
              </p>
            </div>
          )}
        </div>
      </div>

      <section className={`${activeTab === 'clinical' ? 'bg-indigo-950' : activeTab === 'mentalhealth' ? 'bg-teal-900' : 'bg-amber-900'} rounded-[3rem] p-12 text-white relative overflow-hidden shadow-2xl transition-colors duration-500`}>
        <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
          <div className="space-y-6">
            <h3 className="text-4xl font-black italic tracking-tighter">Psychological Tools for Families</h3>
            <p className="text-white/80 text-xl leading-relaxed font-medium">
              Integrating Cognitive Behavioral Therapy (CBT) modules from CCI WA helps adolescents manage perfectionism, social anxiety, and mood using structured, clinical worksheets.
            </p>
            <div className="flex flex-wrap gap-3">
              <div className="bg-white/10 backdrop-blur-md px-4 py-2 rounded-xl text-xs font-black uppercase">CBT Frameworks</div>
              <div className={`bg-white/10 backdrop-blur-md px-4 py-2 rounded-xl text-xs font-black uppercase`}>Skill-based modules</div>
            </div>
          </div>
          <div className="hidden md:flex justify-end">
            <div className="w-48 h-48 bg-white/5 rounded-full flex items-center justify-center text-8xl rotate-12 border border-white/10">💎</div>
          </div>
        </div>
        <div className="absolute -bottom-32 -left-32 w-96 h-96 bg-white/5 rounded-full opacity-30 blur-3xl"></div>
      </section>
    </div>
  );
};

export interface SymptomLog {
  id: string;
  timestamp: Date;
  description: string;
  aiResponse: string;
  media?: string;
}

export interface GrowthRecord {
  age: number; // in months
  weight: number; // kg
  height: number; // cm
  headCircumference?: number; // cm
  date: string;
}

export interface Vaccination {
  id: string;
  name: string;
  dueDate: Date;
  receivedDate?: Date;
  status: 'pending' | 'completed' | 'overdue';
  description: string;
  ageMilestone: number; // in months
  manufacturer?: string;
  lotNumber?: string;
  clinic?: string;
}

export interface Milestone {
  id: string;
  ageRange: string;
  category: 'Motor' | 'Cognitive' | 'Social' | 'Language';
  description: string;
  completed: boolean;
  isRedFlag: boolean;
}

export interface HealthCheck {
  id: string;
  ageMilestone: string;
  date?: string;
  completed: boolean;
  notes: string;
  professionalName?: string;
}

export interface SpecialistContact {
  id: string;
  name: string;
  specialty: string;
  hospital?: string;
  contact?: string;
}

export interface MedicalDevice {
  id: string;
  type: string;
  model?: string;
  lastChanged?: string;
  notes?: string;
}

export interface FamilyHistory {
  maternal: string;
  paternal: string;
  siblings: string;
  other: string;
}

export interface SickDayPlan {
  instructions: string;
  emergencyMeds: string;
  fluidRequirements: string;
  triggers: string;
  emergencyContact: string;
}

export interface MedicalHistory {
  pastMedicalHistory: string;
  surgicalHistory: string;
  currentMedications: string[];
  allergies: string[];
  familyHistory: FamilyHistory;
  specialists: SpecialistContact[];
  devices: MedicalDevice[];
  sickDayPlan: SickDayPlan;
}

export interface DevelopmentalHistory {
  // Pregnancy
  maternalAgeAtBirth?: number;
  assistedConception: string; // e.g. IVF, IUI
  pregnancyMedications: string;
  pregnancyComplications: string; // e.g. diabetes, BP, infections
  scansAndTests: string; // NIPT, Morphology findings
  exposureConcerns: string; // e.g. smoking, alcohol, drugs

  // Birth
  gestationalAge: string; // weeks/days
  laborType: string; // e.g. spontaneous, induced
  romDuration: string; // Duration of Rupture of Membranes
  liquorStatus: string; // e.g. clear, meconium
  deliveryMode: string; // e.g. vaginal, forceps, vacuum, C-section
  birthComplications: string;
  birthWeight?: number;
  birthLength?: number;
  birthHeadCirc?: number;
  apgar1?: number;
  apgar5?: number;
  resuscitationNeeded: string;

  // Neonatal
  jaundiceTreatment: string;
  vitaminKAndHepB: string;
  newbornScreening: string; // Guthrie test status
  specialCareNursery: string; // NICU/SCN details
  earlyNeonatalConcerns: string;

  // Feeding & Growth
  feedingHistory: string; // Breast/Bottle, solids start
  growthVelocity: string; // Percentile shifts

  // Early Progress
  earlyMilestones: {
    smile: string;
    sit: string;
    walk: string;
    firstWords: string;
  };
  currentDevelopmentalConcerns: string;
}

export interface AttachmentAnalysis {
  caregiverObservations: string;
  aiInterpretation?: string;
}

export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting';

import React, { useState, useMemo, useRef } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Follow 4x4 protocol: 4 puffs of Ventolin (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4 puffs. CALL 000 if: distressed, lips blue, or skin sucking in around ribs.",
    triggers: "Viral colds, exercise, cigarette smoke, seasonal pollens, cold air.",
