    emergencyContact: "Endocrinology Team / On-call Specialist"
  }
};

export const MedicalProfile: React.FC = () => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    surgicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    maternalAgeAtBirth: undefined,
    assistedConception: '',
    pregnancyMedications: '',
    pregnancyComplications: '',
    scansAndTests: '',
    exposureConcerns: '',
    gestationalAge: '',
    laborType: '',
    romDuration: '',
    liquorStatus: '',
    deliveryMode: '',
    birthComplications: '',
    birthWeight: undefined,
    birthLength: undefined,
    birthHeadCirc: undefined,
    apgar1: undefined,
    apgar5: undefined,
    resuscitationNeeded: '',
    jaundiceTreatment: '',
    vitaminKAndHepB: '',
    newbornScreening: '',
    specialCareNursery: '',
    earlyNeonatalConcerns: '',
    feedingHistory: '',
    growthVelocity: '',
    earlyMilestones: {
      smile: '',
      sit: '',
      walk: '',
      firstWords: '',
    },
    currentDevelopmentalConcerns: ''
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({ caregiverObservations: '' });

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'complex' | 'sickday' | 'development' | 'attachment'>('history');
  const [smartNotes, setSmartNotes] = useState('');
  const [smartImage, setSmartImage] = useState<string | null>(null);
  const [templateApplied, setTemplateApplied] = useState<string | null>(null);
  const [copySuccess, setCopySuccess] = useState(false);

  const smartFileInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });
  const [filterQuery, setFilterQuery] = useState('');

  const handleSmartImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSmartImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleMagicFill = async () => {
    if (!smartNotes && !smartImage) return;
    setSmartLoading(true);
    try {
      const extracted = await extractProfileFromText(smartNotes, smartImage || undefined);

      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: extracted.pastMedicalHistory || prev.pastMedicalHistory,
        surgicalHistory: extracted.surgicalHistory || prev.surgicalHistory,
        currentMedications: [...new Set([...prev.currentMedications, ...(extracted.currentMedications || [])])],
        allergies: [...new Set([...prev.allergies, ...(extracted.allergies || [])])],
        specialists: [...prev.specialists, ...(extracted.specialists || []).map((s: any) => ({ ...s, id: Math.random().toString(36).substr(2, 9) }))],
        devices: [...prev.devices, ...(extracted.devices || []).map((d: any) => ({ ...d, id: Math.random().toString(36).substr(2, 9) }))],
        sickDayPlan: {
          ...prev.sickDayPlan,
          ...extracted.sickDayPlan
        }
      }));

      setSmartNotes('');
      setSmartImage(null);
      alert("Health profile updated! Please check the individual sections.");
    } catch (e) {
      console.error(e);
      alert("Smart Fill failed. Please fill fields manually.");
    } finally {
      setSmartLoading(false);
    }
  };

  const applyTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      setHistory(prev => ({
        ...prev,
        sickDayPlan: { ...prev.sickDayPlan, ...template }
      }));
      setTemplateApplied(type.charAt(0).toUpperCase() + type.slice(1));
      setActiveTab('sickday');
      setTimeout(() => setTemplateApplied(null), 3000);
    }
  };

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name.trim() && newSpecialist.specialty.trim()) {
      const specialist: SpecialistContact = {
        id: Math.random().toString(36).substr(2, 9),
        ...newSpecialist
      };
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, specialist] }));
      setNewSpecialist({ name: '', specialty: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type.trim()) {
      const device: MedicalDevice = {
        id: Math.random().toString(36).substr(2, 9),
        ...newDevice
      };
      setHistory(prev => ({ ...prev, devices: [...prev.devices, device] }));
      setNewDevice({ type: '', notes: '' });
    }
  };

  const updateSickDay = (field: keyof SickDayPlan, value: string) => {
    setHistory(prev => ({
      ...prev,
      sickDayPlan: { ...prev.sickDayPlan, [field]: value }
    }));
  };

  const updateDevHistory = (field: keyof DevelopmentalHistory | 'earlyMilestones', value: any) => {
    if (typeof field === 'string' && field === 'earlyMilestones') {
      setDevHistory(prev => ({
        ...prev,
        earlyMilestones: { ...prev.earlyMilestones, ...value }
      }));
    } else {
      setDevHistory(prev => ({
        ...prev,
        [field as keyof DevelopmentalHistory]: value
      }));
    }
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (error) {
      console.error(error);
      alert("Error generating summary.");
    } finally {
      setLoading(false);
    }
  };

  const handleCopy = () => {
    if (aiAnalysis) {
      navigator.clipboard.writeText(aiAnalysis.text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const filteredMeds = useMemo(() => {
    if (!filterQuery) return history.currentMedications;
    return history.currentMedications.filter(m => m.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.currentMedications, filterQuery]);

  const filteredAllergies = useMemo(() => {
    if (!filterQuery) return history.allergies;
    return history.allergies.filter(a => a.toLowerCase().includes(filterQuery.toLowerCase()));
  }, [history.allergies, filterQuery]);

  return (
    <div className="space-y-8 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Health Companion Profile</h2>
          <p className="text-slate-500 font-medium">Capture complex histories with clinical accuracy.</p>
        </div>
        <div className="bg-indigo-600 text-white px-5 py-2 rounded-2xl text-xs font-bold uppercase tracking-widest shadow-lg">
          Personal Record
        </div>
      </header>

      {/* Smart Entry Dashboard */}
      <section className="bg-white p-8 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden relative">
        <div className="relative z-10 space-y-6">
          <div className="flex items-center justify-between">
             <div className="flex items-center gap-3">
              <span className="text-3xl">🪄</span>
              <h3 className="text-2xl font-bold text-slate-800">Smart Entry & Clinical Templates</h3>
            </div>
            {templateApplied && (
              <div className="bg-emerald-100 text-emerald-700 px-4 py-2 rounded-full text-xs font-bold animate-bounce border border-emerald-200">
                Applied: {templateApplied} Template ✨
              </div>
            )}
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-4">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Document OCR / Brain Dump</label>
              <textarea 
                value={smartNotes}
                onChange={e => setSmartNotes(e.target.value)}
                placeholder="Paste letter text or describe complex history here..."
                className="w-full h-32 p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none text-sm resize-none font-medium focus:ring-2 focus:ring-indigo-500"
              />
              <div className="flex gap-2">
                <input type="file" ref={smartFileInputRef} className="hidden" onChange={handleSmartImageUpload} accept="image/*" />
                <button 
                  onClick={() => smartFileInputRef.current?.click()}
                  className="flex-1 py-3 bg-slate-100 rounded-xl font-bold text-xs text-slate-600 hover:bg-slate-200 transition-colors"
                >
                  {smartImage ? '📄 Image Attached' : '📷 Upload Medical Doc'}
                </button>
                <button 
                  onClick={handleMagicFill}
                  disabled={smartLoading || (!smartNotes && !smartImage)}
                  className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 disabled:bg-slate-300 transition-all transform hover:-translate-y-1 active:translate-y-0"
                >
                  {smartLoading ? '...' : '✨ Smart Fill'}
                </button>
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest block mb-4">Common Plan Templates</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-2 gap-3">
                {[
                  { id: 'asthma', icon: '🫁', name: 'Asthma' },
                  { id: 'metabolic', icon: '🧪', name: 'Metabolic' },
                  { id: 'seizure', icon: '🧠', name: 'Seizure' },
                  { id: 'anaphylaxis', icon: '🥜', name: 'Anaphylaxis' },
                  { id: 'adrenal', icon: '💊', name: 'Adrenal Insuff.' },
                ].map(t => (
                  <button 
                    key={t.id}
                    onClick={() => applyTemplate(t.id)} 
                    className="flex items-center gap-3 p-3 bg-white border border-slate-100 rounded-2xl text-left hover:border-indigo-400 hover:shadow-md transition-all group"
                  >
                    <span className="text-xl group-hover:scale-110 transition-transform">{t.icon}</span>
                    <span className="font-bold text-slate-800 text-xs leading-tight">{t.name}</span>
                  </button>
                ))}
              </div>
              <p className="mt-4 text-[10px] text-slate-400 font-medium italic">
                *Templates populate the "Sick Day Plan" tab. You can customize them there.
              </p>
            </div>
          </div>
        </div>
      </section>

      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm max-w-full overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📋' },
          { id: 'complex', label: 'Team & Gear', icon: '🏥' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🤒' },
          { id: 'development', label: 'Developmental History', icon: '🐣' },
          { id: 'attachment', label: 'Emotional', icon: '🤝' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 px-4 rounded-2xl font-bold transition-all flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
