import React, { useState, useEffect } from 'react';
import { calculateDosage } from '../services/gemini';

interface DoseCalculatorProps {
  initialWeight?: number;
}

export const DoseCalculator: React.FC<DoseCalculatorProps> = ({ initialWeight }) => {
  const [weight, setWeight] = useState(initialWeight?.toString() || '');
  const [medication, setMedication] = useState('Paracetamol / Acetaminophen');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  useEffect(() => {
    if (initialWeight) {
      setWeight(initialWeight.toString());
    }
  }, [initialWeight]);

  const handleCalculate = async () => {
    if (!weight || Number(weight) <= 0) return;
    setLoading(true);
    try {
      const res = await calculateDosage(Number(weight), medication);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error calculating dosage.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">DoseWise Calculator</h2>
