                value={weight}
                onChange={e => setWeight(e.target.value)}
                placeholder="e.g. 12"
                className="w-full p-5 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none font-bold text-lg bg-slate-50/50" 
              />
              {initialWeight && (
                <div className="absolute top-1/2 -translate-y-1/2 right-4 bg-emerald-100 text-emerald-700 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest flex items-center gap-1">
                  <span>✅</span> Sync'd
                </div>
              )}
            </div>
            {initialWeight && (
              <p className="mt-2 text-[10px] text-emerald-600 font-bold ml-2">Using latest weight from Growth Tracker.</p>
