      {/* Smart Hub Section */}
      <section className="bg-white p-8 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden">
        <div className="flex items-center gap-3 mb-6">
          <span className="text-3xl">🪄</span>
          <h3 className="text-2xl font-bold text-slate-800">Smart Hub Sync</h3>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Clinical OCR / Document Import</label>
              <textarea 
                value={smartNotes}
                onChange={e => setSmartNotes(e.target.value)}
                className="w-full h-32 p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none text-sm resize-none font-medium"
                placeholder="Paste clinic letter or notes..."
              />
              <button onClick={handleMagicFill} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg">Process Smart Sync</button>
           </div>

           <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-4">Sync Symptoms from Guide</label>
             <div className="space-y-3 max-h-48 overflow-y-auto pr-2">
               {externalSymptoms.length > 0 ? externalSymptoms.map((s, i) => (
                 <button 
                  key={i} 
                  onClick={() => importSymptom(s)}
                  className="w-full p-4 bg-white border border-slate-200 rounded-xl text-left text-xs font-bold text-slate-600 hover:border-indigo-400 hover:shadow-md transition-all flex items-center gap-3"
                >
                   <span className="text-xl">🌡️</span>
                   <span className="line-clamp-2">{s}</span>
                   <span className="ml-auto text-indigo-500">Import</span>
                 </button>
               )) : (
                 <p className="text-center py-10 text-slate-400 text-xs font-medium italic">No recent symptom logs found to sync.</p>
               )}
             </div>
           </div>
        </div>
      </section>

      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {['history', 'complex', 'sickday', 'development', 'attachment'].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-xs uppercase tracking-widest ${
              activeTab === tab ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-10 space-y-10 animate-in slide-in-from-right-4">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Longitudinal Medical History</label>
              <textarea 
                value={history.pastMedicalHistory}
                onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                className="w-full h-80 p-8 rounded-[3rem] border border-slate-100 outline-none font-bold text-slate-700 bg-slate-50/20 focus:ring-2 focus:ring-indigo-500 shadow-inner"
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

