  onClearChallenge?: () => void;
}

export const ParentingTips: React.FC<ParentingTipsProps> = ({ preselectedChallenge, onClearChallenge }) => {
  const [age, setAge] = useState('Toddler (1-3 years)');
  const [challenge, setChallenge] = useState('');
  const [loading, setLoading] = useState(false);
  const [advice, setAdvice] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'tips' | 'mentalhealth' | 'clinical'>('tips');

  useEffect(() => {
    if (preselectedChallenge) {
      setChallenge(preselectedChallenge);
      handleGetAdvice(preselectedChallenge);
      if (onClearChallenge) setTimeout(onClearChallenge, 1000);
    }
  }, [preselectedChallenge]);

  const handleGetAdvice = async (selectedChallenge?: string) => {
    const finalChallenge = selectedChallenge || challenge;
    if (!finalChallenge) return;

    setLoading(true);
    setAdvice(null);
    try {
      const res = await getParentingAdvice(age, finalChallenge);
      setAdvice(res);
    } catch (error) {
      alert("Error generating advice.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Parenting Hub</h2>
          <p className="text-slate-500 font-medium">Clinical strategies supporting psychological wellbeing.</p>
        </div>
      </header>

      {preselectedChallenge && (
        <div className="bg-indigo-600 p-6 rounded-[2.5rem] text-white flex items-center justify-between shadow-xl animate-in slide-in-from-top-4">
          <div className="flex items-center gap-4">
             <span className="text-3xl">🔗</span>
             <div>
                <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Smart Link Sync</p>
                <p className="text-xl font-black italic">Analyzing strategies for "{preselectedChallenge}"</p>
             </div>
          </div>
          <div className="bg-white/20 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest">Linked from Screen</div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
            <select 
              value={age}
              onChange={e => setAge(e.target.value)}
              className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none font-bold"
            >
              <option>Toddler (1-3 years)</option>
              <option>Preschooler (3-5 years)</option>
              <option>School Age (5-12 years)</option>
              <option>Adolescent (12+ years)</option>
            </select>
            <div className="flex gap-2">
              <input 
                type="text"
                value={challenge}
                onChange={e => setChallenge(e.target.value)}
                className="flex-1 p-4 rounded-2xl border border-slate-100 bg-slate-50/50 font-medium text-sm"
                placeholder="Specific concern..."
              />
              <button onClick={() => handleGetAdvice()} className="w-14 h-14 bg-amber-500 text-white rounded-2xl shadow-lg">✨</button>
            </div>
          </div>

          <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Resilience Modules</h4>
             {COMMON_CHALLENGES.map(c => (
