export const analyzeScreening = async (testName: string, responses: any) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';
  const prompt = `
    Analyze the results of a "${testName}" screening tool for a parent.
    Responses: ${JSON.stringify(responses)}

    REFER TO THE FOLLOWING CLINICAL STANDARDS AND TOOLS FOR INTERPRETATION:
    - Vanderbilt ADHD Diagnostic Rating Scale (VADRS)
    - Infant-Toddler Checklist (ITC)
    - Autism Spectrum Screening Questionnaire (ASSQ)
    - RAADS-14 (Ritvo Autism Asperger Diagnostic Scale-Revised)
    - ACE Score (Adverse Childhood Experiences) - CDC/Harvard Center on the Developing Child
    - Strengths and Difficulties Questionnaire (SDQ) - Standardized Behavioral Screening
    - Emerging Minds Australia (https://emergingminds.com.au/) for Wellbeing & Trauma-Informed Frameworks.
    - Centre for Clinical Interventions (CCI) WA for Cognitive Behavioral frameworks.

    IF ANALYZING ACEs:
    1. Explain the score (0-10) with a trauma-informed lens. 
    2. Emphasize that ACEs are about exposure, not biology, and that Resilience and Positive Childhood Experiences (PCEs) are powerful counter-balances.
    3. Provide actionable advice for discussing this with a Pediatrician or Trauma-Informed Psychologist.
    4. List Australian support services like Blue Knot Foundation or Emerging Minds.

    IF ANALYZING SDQ (Strengths and Difficulties):
    1. Highlight areas of potential difficulty (Emotional, Conduct, Hyperactivity, Peers).
    2. Note identified "Strengths" (Prosocial behaviors).
    3. Utilize the Emerging Minds focus on child wellbeing and family resilience.

    Structure your response with:
    1. Score Context: (How these responses relate to typical thresholds in the tool.)
    2. Specific Observations: (Point out patterns in the responses.)
    3. Next Steps: (Provide actionable advice such as speaking to a GP for a referral.)
    4. Recommended Resources: (Specifically mention Emerging Minds, Raising Children Network, CCI Western Australia, or RCH Melbourne.)

    DISCLAIMER: This is a screening aid for informational purposes. It is not a diagnosis. A follow-up with a professional is mandatory.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

