    Adhere to information found in Australian pediatric resources. Include mental health/wellbeing pointers if relevant based on Emerging Minds principles.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
