import React, { useState, useRef, useMemo } from 'react';
import { MedicalHistory, DevelopmentalHistory, AttachmentAnalysis, SpecialistContact, MedicalDevice, SickDayPlan } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

interface MedicalProfileProps {
  externalSymptoms?: string[];
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Follow 4x4 protocol: 4 puffs of Ventolin (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. CALL 000 if: distressed, lips blue, or skin sucking in around ribs.",
    triggers: "Viral colds, exercise, smoke.",
    emergencyMeds: "Salbutamol 100mcg/puff. Prednisolone dose as per doctor.",
    fluidRequirements: "Frequent sips. Monitor for signs of dehydration.",
    emergencyContact: "GP / Local ED"
  },
  epilepsy: {
    instructions: "If seizure lasts >5 mins, administer Midazolam. Place in recovery position once finished. Do not put items in mouth.",
    triggers: "Fever, lack of sleep, illness.",
    emergencyMeds: "Buccal Midazolam (Dose as prescribed).",
    fluidRequirements: "Keep hydrated post-ictally.",
    emergencyContact: "Neurology Team / Ambulance"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ externalSymptoms = [] }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: '',
    surgicalHistory: '',
    currentMedications: [],
    allergies: [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  });

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    gestationalAge: '',
    deliveryMode: '',
    birthWeight: undefined,
    apgars: '',
    resuscitationNeeded: '',
    birthComplications: '',
    jaundice: false,
    nicuStay: '',
    newbornScreening: '',
    earlyMilestones: { smile: '', sit: '', walk: '', firstWords: '' },
  });

  const [attachment, setAttachment] = useState<AttachmentAnalysis>({ caregiverObservations: '' });

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'birth' | 'complex' | 'sickday' | 'emotional'>('history');
  const [smartNotes, setSmartNotes] = useState('');
  const [smartImage, setSmartImage] = useState<string | null>(null);
  const smartFileInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });

  const handleMagicFill = async () => {
    if (!smartNotes && !smartImage) return;
    setSmartLoading(true);
    try {
      const extracted = await extractProfileFromText(smartNotes, smartImage || undefined);
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: extracted.pastMedicalHistory || prev.pastMedicalHistory,
        surgicalHistory: extracted.surgicalHistory || prev.surgicalHistory,
        currentMedications: [...new Set([...prev.currentMedications, ...(extracted.currentMedications || [])])],
        allergies: [...new Set([...prev.allergies, ...(extracted.allergies || [])])],
        specialists: [...prev.specialists, ...(extracted.specialists || []).map((s: any) => ({ ...s, id: Math.random().toString(36).substr(2, 9) }))],
        devices: [...prev.devices, ...(extracted.devices || []).map((d: any) => ({ ...d, id: Math.random().toString(36).substr(2, 9) }))],
        sickDayPlan: { ...prev.sickDayPlan, ...extracted.sickDayPlan }
      }));
      setSmartNotes('');
      setSmartImage(null);
      alert("Health profile updated! Check relevant tabs.");
    } catch (e) {
      alert("Smart Fill failed. Please enter details manually.");
    } finally {
      setSmartLoading(false);
    }
  };

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name.trim()) {
      const spec: SpecialistContact = { id: Math.random().toString(36).substr(2, 9), ...newSpecialist };
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, spec] }));
      setNewSpecialist({ name: '', specialty: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type.trim()) {
      const dev: MedicalDevice = { id: Math.random().toString(36).substr(2, 9), ...newDevice };
      setHistory(prev => ({ ...prev, devices: [...prev.devices, dev] }));
      setNewDevice({ type: '', notes: '' });
    }
  };

  const applySickDayTemplate = (key: string) => {
    const template = SICK_DAY_TEMPLATES[key];
    if (template) {
      setHistory(prev => ({ ...prev, sickDayPlan: { ...prev.sickDayPlan, ...template } }));
      setActiveTab('sickday');
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-12 pb-32">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Health <span className="text-indigo-600">Companion</span></h2>
          <p className="text-slate-500 font-medium">Longitudinal medical records and professional clinician handover.</p>
        </div>
      </header>

      {/* Smart Hub Sync */}
      <section className="bg-white p-10 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden relative group">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl group-hover:opacity-10 transition-opacity"></div>
        <div className="flex items-center gap-4 mb-8">
          <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">🪄</div>
          <div>
            <h3 className="text-2xl font-black text-slate-800">Smart Record Import</h3>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">AI Extraction from letters or notes</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
          <div className="space-y-4">
            <textarea 
              value={smartNotes}
              onChange={e => setSmartNotes(e.target.value)}
              placeholder="Paste text from a doctor's letter or hospital discharge summary here..."
              className="w-full h-44 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/50 outline-none text-sm resize-none font-medium focus:ring-2 focus:ring-indigo-500"
            />
            <div className="flex gap-2">
              <button 
                onClick={() => smartFileInputRef.current?.click()}
                className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl hover:bg-slate-200 transition-all text-xs uppercase tracking-widest"
              >
                📷 {smartImage ? 'Change Image' : 'Photo of Document'}
              </button>
              <input type="file" ref={smartFileInputRef} className="hidden" accept="image/*" onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                  const reader = new FileReader();
                  reader.onloadend = () => setSmartImage(reader.result as string);
                  reader.readAsDataURL(file);
                }
              }} />
              <button 
                onClick={handleMagicFill}
                disabled={smartLoading || (!smartNotes && !smartImage)}
                className="px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl disabled:bg-slate-300 hover:bg-indigo-700 transition-all transform active:scale-95 text-xs uppercase tracking-widest"
              >
                {smartLoading ? 'Processing...' : 'Sync Record'}
              </button>
            </div>
          </div>

          <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Recent Cross-Module Imports</h4>
             <div className="space-y-3">
               {externalSymptoms.length > 0 ? externalSymptoms.map((s, i) => (
                 <div key={i} className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center justify-between group">
                   <p className="text-xs font-bold text-slate-600 line-clamp-1">{s}</p>
                   <button 
                    onClick={() => setHistory(prev => ({ ...prev, pastMedicalHistory: prev.pastMedicalHistory + '\n' + s }))}
                    className="text-[10px] font-black text-indigo-600 uppercase hover:underline shrink-0"
                   >
                    Add to History
                   </button>
                 </div>
               )) : (
                 <div className="flex flex-col items-center justify-center py-10 text-center space-y-2 opacity-40">
                   <span className="text-3xl">📥</span>
                   <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">No recent data to sync</p>
                 </div>
               )}
             </div>
          </div>
        </div>
      </section>

      {/* Navigation Tabs */}
      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar scroll-smooth">
        {[
          { id: 'history', label: 'Clinical History', icon: '📋' },
          { id: 'birth', label: 'Birth & Development', icon: '🐣' },
          { id: 'complex', label: 'Team & Gear', icon: '🏥' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🤒' },
          { id: 'emotional', label: 'Emotional Bonding', icon: '🫂' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[140px] py-4 rounded-2xl font-black transition-all text-xs uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span className="text-xl">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      {/* Main Content Sections */}
      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[600px] animate-in slide-in-from-bottom-6 duration-500">

        {/* CLINICAL HISTORY TAB */}
        {activeTab === 'history' && (
          <div className="p-10 space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-4">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Active Medications</label>
                <div className="flex gap-2">
                  <input value={newMed} onChange={e => setNewMed(e.target.value)} placeholder="e.g. Melatonin 2mg nightly" className="flex-1 p-4 rounded-2xl border border-slate-100 bg-slate-50/50" />
                  <button onClick={handleAddMed} className="bg-indigo-600 text-white px-6 rounded-2xl font-black shadow-lg">Add</button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {history.currentMedications.map((m, i) => (
                    <span key={i} className="px-4 py-2 bg-indigo-50 text-indigo-700 rounded-xl text-xs font-black border border-indigo-100 flex items-center gap-2">
                      {m} <button onClick={() => setHistory(prev => ({ ...prev, currentMedications: prev.currentMedications.filter((_, idx) => idx !== i) }))}>×</button>
                    </span>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Known Allergies</label>
