                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => applySickDayTemplate('asthma')} className="px-4 py-2 bg-white border border-amber-300 rounded-xl text-[10px] font-black text-amber-900 uppercase tracking-widest hover:bg-amber-100">Asthma Template</button>
