                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest mb-2 ml-2">When to Start (Triggers)</label>
                      <textarea value={history.sickDayPlan.triggers} onChange={e => setHistory({...history, sickDayPlan: { ...history.sickDayPlan, triggers: e.target.value }})} className="w-full h-32 p-6 rounded-3xl border border-amber-200 outline-none bg-white font-bold" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest mb-2 ml-2">Emergency Rescue Doses</label>
                      <textarea value={history.sickDayPlan.emergencyMeds} onChange={e => setHistory({...history, sickDayPlan: { ...history.sickDayPlan, emergencyMeds: e.target.value }})} className="w-full h-32 p-6 rounded-3xl border border-amber-200 outline-none bg-white font-bold" />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest mb-2 ml-2">Fluid / Maintenance Regimen</label>
                      <textarea value={history.sickDayPlan.fluidRequirements} onChange={e => setHistory({...history, sickDayPlan: { ...history.sickDayPlan, fluidRequirements: e.target.value }})} className="w-full h-32 p-6 rounded-3xl border border-amber-200 outline-none bg-white font-bold" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest mb-2 ml-2">Primary Specialist Contact</label>
                      <input value={history.sickDayPlan.emergencyContact} onChange={e => setHistory({...history, sickDayPlan: { ...history.sickDayPlan, emergencyContact: e.target.value }})} className="w-full p-6 rounded-3xl border border-amber-200 outline-none bg-white font-bold" />
                    </div>
                  </div>
                </div>
                <div className="mt-8">
                  <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest mb-2 ml-2">Detailed Protocol Steps</label>
                  <textarea value={history.sickDayPlan.instructions} onChange={e => setHistory({...history, sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value }})} className="w-full h-64 p-8 rounded-[3rem] border border-amber-200 outline-none bg-white text-xl font-black italic shadow-inner" placeholder="Step-by-step instructions (e.g. 4x4 for asthma)..." />
                </div>
             </div>
          </div>
        )}

        {/* EMOTIONAL BONDING TAB */}
        {activeTab === 'emotional' && (
          <div className="p-10 space-y-12">
             <div className="bg-pink-50 p-10 rounded-[3rem] border border-pink-100 space-y-8">
               <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-pink-500 rounded-2xl flex items-center justify-center text-4xl text-white shadow-lg">🤝</div>
                 <div>
                    <h3 className="text-2xl font-black text-pink-900">Emotional Connection & Attachment</h3>
                    <p className="text-pink-800 font-bold opacity-60">Observing how your child connects, soothes, and communicates.</p>
                 </div>
               </div>
               <textarea 
                value={attachment.caregiverObservations} 
                onChange={e => setAttachment({...attachment, caregiverObservations: e.target.value})} 
                className="w-full h-80 p-10 rounded-[4rem] border border-pink-200 outline-none bg-white font-bold text-pink-950 text-xl leading-relaxed shadow-inner italic"
                placeholder="What are your child's cues for comfort? How do they respond to your presence? Record your bond and growth together here..."
               />
             </div>
          </div>
        )}

      </div>

      {/* GENERATE HANDOVER SECTION */}
      <div className="flex flex-col items-center gap-6 pt-12">
        <button 
          onClick={handleGenerateHandover}
          disabled={loading}
          className={`px-16 py-7 rounded-[2.5rem] font-black text-2xl text-white shadow-2xl flex items-center gap-4 transition-all transform hover:-translate-y-2 active:scale-95 ${
            loading ? 'bg-slate-300' : 'bg-indigo-700 hover:bg-indigo-800'
          }`}
        >
          {loading ? (
             <><div className="w-6 h-6 border-4 border-white border-t-transparent rounded-full animate-spin" /> Synthesizing Handover...</>
          ) : (
            <>📋 Generate Specialist Handover✨</>
          )}
        </button>
        <p className="text-slate-400 text-xs font-black uppercase tracking-widest text-center max-w-sm">Use this for GP, Specialist visits, or Emergency Department triage to save time and ensure accuracy.</p>
      </div>

      {/* AI ANALYSIS OUTPUT */}
      {aiAnalysis && (
        <div className="bg-white p-14 rounded-[4rem] border border-indigo-100 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.15)] mt-20 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative">
          <button 
            onClick={() => { navigator.clipboard.writeText(aiAnalysis.text); alert("Copied to clipboard!"); }}
            className="absolute top-10 right-10 bg-indigo-50 text-indigo-700 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-100 shadow-sm"
          >
            📋 Copy Report
          </button>

          <div className="flex items-center gap-4 mb-10">
            <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">📝</div>
            <div>
              <h3 className="text-4xl font-black text-slate-800 tracking-tighter italic">Doctor's Handover Summary</h3>
              <p className="text-indigo-600 font-black text-xs uppercase tracking-widest">Clinical-Grade Clinical Synthesis</p>
            </div>
          </div>

          <div className="prose prose-indigo max-w-none prose-xl">
            <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic border-l-8 border-slate-50 pl-10">
              {aiAnalysis.text}
            </div>
          </div>

          <div className="mt-14 p-10 bg-slate-50 rounded-[3rem] border border-slate-200">
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Linked Health Context</h4>
            <div className="flex flex-wrap gap-3">
               <span className="px-5 py-2 bg-white rounded-xl border border-slate-200 text-xs font-black text-slate-600">ISBAR Framework</span>
               <span className="px-5 py-2 bg-white rounded-xl border border-slate-200 text-xs font-black text-slate-600">Australian Clinical Guidance</span>
               <span className="px-5 py-2 bg-white rounded-xl border border-slate-200 text-xs font-black text-slate-600">Sick Day Plan Included</span>
            </div>
