export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting' | 'setup';

import React, { useState } from 'react';
import { ChildProfile } from '../types';

interface ChildProfileSetupProps {
  initialProfile?: ChildProfile;
  onSave: (profile: ChildProfile) => void;
  onCancel?: () => void;
}

export const ChildProfileSetup: React.FC<ChildProfileSetupProps> = ({ initialProfile, onSave, onCancel }) => {
  const [name, setName] = useState(initialProfile?.name || '');
  const [dob, setDob] = useState(initialProfile?.dob || '');
  const [sex, setSex] = useState<ChildProfile['sex']>(initialProfile?.sex || 'Male');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !dob) return;
    onSave({ name, dob, sex });
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <header className="text-center space-y-2">
        <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-4 shadow-inner">
          🐣
        </div>
        <h2 className="text-3xl font-black text-slate-800 tracking-tight">
          {initialProfile ? 'Edit Child Profile' : 'Welcome to PediPulse!'}
        </h2>
        <p className="text-slate-500 font-medium">
          {initialProfile ? 'Update your child\'s basic information.' : 'Let\'s start by setting up your child\'s profile for personalized care.'}
        </p>
      </header>

      <form onSubmit={handleSubmit} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-2xl space-y-8">
        <div className="space-y-6">
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Child's Name</label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Leo"
              className="w-full p-5 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-lg bg-slate-50/30"
            />
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Date of Birth</label>
            <input
              type="date"
              required
              value={dob}
              onChange={(e) => setDob(e.target.value)}
              className="w-full p-5 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-lg bg-slate-50/30"
            />
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Biological Sex</label>
            <div className="flex gap-3">
              {(['Male', 'Female', 'Other'] as const).map((s) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => setSex(s)}
                  className={`flex-1 py-4 rounded-2xl font-black transition-all text-xs uppercase tracking-widest border-2 ${
                    sex === s
                      ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg'
                      : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="flex gap-4 pt-4">
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 py-5 bg-slate-100 text-slate-500 font-black rounded-2xl hover:bg-slate-200 transition-all text-sm uppercase tracking-widest"
            >
              Cancel
            </button>
          )}
          <button
            type="submit"
            className="flex-grow py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 transition-all transform active:scale-95 text-sm uppercase tracking-widest"
          >
            {initialProfile ? 'Update Profile' : 'Create Profile ✨'}
          </button>
        </div>
      </form>

      <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100 flex items-center gap-4 text-center">
        <span className="text-2xl">🔒</span>
        <p className="text-amber-800 text-xs font-bold leading-relaxed">
          All data is stored locally on your device and used only to personalize AI guidance and clinical calculators.
        </p>
      </div>
    </div>
  );
};

