const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [childProfile, setChildProfile] = useState<ChildProfile | undefined>(undefined);
  const [latestWeight, setLatestWeight] = useState<number | undefined>(undefined);
  const [recentSymptomLogs, setRecentSymptomLogs] = useState<string[]>([]);
  const [activeChallenge, setActiveChallenge] = useState<string | undefined>(undefined);

  const handleSymptomLogged = (summary: string) => {
    setRecentSymptomLogs(prev => [summary, ...prev].slice(0, 5));
  };

  const handleWeightSync = (weight: number) => {
    setLatestWeight(weight);
  };

  const handleSmartLinkChallenge = (challenge: string) => {
    setActiveChallenge(challenge);
    setActiveView('parenting');
  };

  const handleProfileSave = (profile: ChildProfile) => {
    setChildProfile(profile);
    setActiveView('dashboard');
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />;
      case 'setup': return <ChildProfileSetup initialProfile={childProfile} onSave={handleProfileSave} onCancel={childProfile ? () => setActiveView('dashboard') : undefined} />;
      case 'symptoms': return <SymptomChecker onSaveToProfile={handleSymptomLogged} />;
      case 'vaccines': return <VaccineTracker />;
      case 'growth': return <GrowthTracker onWeightUpdate={handleWeightSync} />;
      case 'dosage': return <DoseCalculator initialWeight={latestWeight} />;
      case 'milestones': return <MilestoneNavigator />;
      case 'stories': return <CalmStory />;
      case 'screening': return <ScreeningTool onLinkChallenge={handleSmartLinkChallenge} />;
      case 'profile': return <MedicalProfile externalSymptoms={recentSymptomLogs} />;
      case 'redbook': return <RedBook />;
      case 'parenting': return <ParentingTips preselectedChallenge={activeChallenge} onClearChallenge={() => setActiveChallenge(undefined)} />;
      default: return <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      <div key={activeView} className="animate-in fade-in slide-in-from-bottom-6 duration-700">
        {renderContent()}
      </div>
    </Layout>
  );
};

