import { Layout } from './components/Layout';
import { SymptomChecker } from './components/SymptomChecker';
import { GrowthTracker } from './components/GrowthTracker';
import { DoseCalculator } from './components/DoseCalculator';
import { MilestoneNavigator } from './components/MilestoneNavigator';
import { CalmStory } from './components/CalmStory';
import { VaccineTracker } from './components/VaccineTracker';
import { ScreeningTool } from './components/ScreeningTool';
import { MedicalProfile } from './components/MedicalProfile';
import { RedBook } from './components/RedBook';
import { ParentingTips } from './components/ParentingTips';
import { ChildProfileSetup } from './components/ChildProfileSetup';
import { BondingJournal } from './components/BondingJournal';

const Dashboard: React.FC<{ 
  onNavigate: (v: ViewType) => void; 
  latestWeight?: number;
  childProfile?: ChildProfile;
}> = ({ onNavigate, latestWeight, childProfile }) => {

  const childAge = useMemo(() => {
    if (!childProfile?.dob) return null;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let age = now.getFullYear() - birth.getFullYear();
    const m = now.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) {
      age--;
    }

    if (age === 0) {
      const months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
      return `${months} ${months === 1 ? 'month' : 'months'}`;
    }
    return `${age} ${age === 1 ? 'year' : 'years'} old`;
  }, [childProfile]);

  const medicalCards = [
    { id: 'symptoms', title: 'Symptom Guide', desc: 'AI Triage & Red Flags', icon: '🌡️', color: 'bg-rose-50 text-rose-600', badge: 'Triage' },
    { id: 'dosage', title: 'Safe Dosing', desc: 'Weight-based Guidance', icon: '💊', color: 'bg-indigo-50 text-indigo-600', badge: 'Clinical' },
    { id: 'growth', title: 'Growth Tracking', desc: 'Percentile Analysis', icon: '📈', color: 'bg-blue-50 text-blue-600', badge: 'Metrics' },
    { id: 'vaccines', title: 'Immunisation', desc: 'Records & Schedule', icon: '💉', color: 'bg-red-50 text-red-600', badge: 'Records' },
    { id: 'profile', title: 'Medical Profile', desc: 'Clinical Handover', icon: '📋', color: 'bg-slate-100 text-slate-700', badge: 'Clinical' },
    { id: 'redbook', title: 'Digital Red Book', desc: 'PHR Records', icon: '📕', color: 'bg-rose-100 text-rose-700', badge: 'National' },
  ];

  const wellbeingCards = [
    { id: 'milestones', title: 'Milestones', desc: 'Development Monitor', icon: '✨', color: 'bg-purple-50 text-purple-600', badge: 'Growth' },
    { id: 'screening', title: 'Screening Tools', desc: 'Behavior & ASD Aids', icon: '🔍', color: 'bg-teal-50 text-teal-600', badge: 'Assessment' },
    { id: 'parenting', title: 'Parenting Hub', desc: 'Resilience & CBT', icon: '🌻', color: 'bg-amber-50 text-amber-600', badge: 'Psychosocial' },
    { id: 'bonding', title: 'Bonding Journal', desc: 'Attachment & Cues', icon: '🫂', color: 'bg-rose-50 text-rose-500', badge: 'Connection' },
    { id: 'stories', title: 'Calm Stories', desc: 'Soothing Audio', icon: '🌙', color: 'bg-indigo-900 text-white', badge: 'Mindfulness' },
  ];

  return (
    <div className="space-y-16 animate-in fade-in duration-700 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-6 border-b border-slate-100 pb-10">
        <div className="space-y-2">
          <div className="flex items-center gap-3 mb-2">
            <h1 className="text-5xl font-black text-slate-800 tracking-tighter italic">PediPulse <span className="text-indigo-600">Hub</span></h1>
            {!childProfile && (
              <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">Setup Needed</span>
            )}
          </div>
          <p className="text-slate-500 text-xl font-medium max-w-xl leading-relaxed">
            {childProfile 
              ? `Personalized care intelligence for ${childProfile.name}.`
              : "Unified intelligence for medical management and developmental wellbeing."
            }
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 items-stretch">
          {childProfile ? (
            <button 
              onClick={() => onNavigate('setup')}
              className="bg-white px-8 py-5 rounded-[2.5rem] border border-slate-100 shadow-xl shadow-slate-200/50 flex items-center gap-5 group hover:border-indigo-200 transition-all"
            >
               <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-2xl group-hover:scale-110 transition-transform">
                {childProfile.sex === 'Female' ? '👧' : childProfile.sex === 'Male' ? '👦' : '👶'}
               </div>
               <div className="text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{childAge}</p>
                  <p className="text-2xl font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{childProfile.name}</p>
               </div>
            </button>
          ) : (
            <button 
              onClick={() => onNavigate('setup')}
              className="bg-indigo-600 text-white px-8 py-5 rounded-[2.5rem] shadow-xl shadow-indigo-200/50 flex items-center gap-5 hover:bg-indigo-700 transition-all animate-pulse"
            >
               <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-2xl">👋</div>
               <div className="text-left">
                  <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Getting Started</p>
                  <p className="text-xl font-black">Complete Profile</p>
               </div>
            </button>
          )}

          {latestWeight && (
            <div className="bg-white px-8 py-5 rounded-[2.5rem] border border-slate-100 shadow-xl shadow-slate-200/50 flex items-center gap-5">
               <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-2xl">⚖️</div>
               <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Weight Sync</p>
                  <p className="text-2xl font-black text-slate-800">{latestWeight} <span className="text-sm text-slate-400">kg</span></p>
               </div>
            </div>
          )}
        </div>
      </header>

      {/* MEDICAL PILLAR */}
      <section className="space-y-8">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-3">
              <span className="w-8 h-8 bg-indigo-100 rounded-lg flex items-center justify-center text-sm">🏥</span>
              Clinical & Medical Management
            </h2>
            <p className="text-slate-400 text-sm font-medium">Triage, medication management, and clinical records.</p>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {medicalCards.map((card) => (
            <button
              key={card.id}
              onClick={() => onNavigate(card.id as ViewType)}
              className="group bg-white p-8 rounded-[3rem] border border-slate-100 text-left hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 relative overflow-hidden"
            >
              <div className="flex justify-between items-start mb-6">
                <div className={`w-16 h-16 ${card.color} rounded-3xl flex items-center justify-center text-3xl group-hover:scale-110 transition-transform`}>
                  {card.icon}
                </div>
                <span className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em]">{card.badge}</span>
              </div>
              <h3 className="text-2xl font-bold text-slate-800 mb-2 tracking-tight">{card.title}</h3>
              <p className="text-slate-500 text-sm leading-relaxed font-medium">{card.desc}</p>
              <div className="mt-6 flex items-center gap-2 text-indigo-600 font-black text-[10px] uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-all transform translate-x-[-10px] group-hover:translate-x-0">
                Launch Module <span>→</span>
              </div>
            </button>
          ))}
        </div>
      </section>

      {/* WELLBEING PILLAR */}
      <section className="space-y-8">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-3">
              <span className="w-8 h-8 bg-teal-100 rounded-lg flex items-center justify-center text-sm">🌻</span>
              Development & Psychosocial Wellbeing
            </h2>
            <p className="text-slate-400 text-sm font-medium">Resilience building, behavioral screening, and emotional connection.</p>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
          {wellbeingCards.map((card) => (
            <button
              key={card.id}
              onClick={() => onNavigate(card.id as ViewType)}
              className="group bg-white p-8 rounded-[3rem] border border-slate-100 text-left hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 flex flex-col md:flex-row md:items-center gap-8"
            >
              <div className={`w-24 h-24 ${card.color} rounded-[2rem] flex items-center justify-center text-5xl shrink-0 group-hover:rotate-6 transition-transform shadow-inner`}>
                {card.icon}
              </div>
              <div className="flex-1">
                <div className="flex justify-between items-center mb-1">
                   <h3 className="text-2xl font-bold text-slate-800 tracking-tight">{card.title}</h3>
                   <span className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em]">{card.badge}</span>
                </div>
                <p className="text-slate-500 text-lg leading-snug font-medium mb-4">{card.desc}</p>
                <div className="flex items-center gap-2 text-teal-600 font-black text-[10px] uppercase tracking-widest">
                  Explore Guidance <span>→</span>
                </div>
              </div>
            </button>
          ))}
        </div>
      </section>

      <section className="bg-slate-900 rounded-[4rem] p-12 text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
          <div className="space-y-6">
            <div className="inline-block bg-white/10 px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-white/20">Handover Expert</div>
            <h2 className="text-4xl md:text-5xl font-black italic tracking-tighter leading-tight">Clinical Handover Summary.</h2>
            <p className="text-slate-400 text-xl leading-relaxed font-medium">
              Prepare a clinical-grade health summary for specialist or GP visits. Combines medical history, medications, and connection observations into one concise report.
            </p>
            <button 
              onClick={() => onNavigate('profile')}
              className="bg-indigo-600 text-white px-12 py-5 rounded-2xl font-black text-lg hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-900/40"
            >
              Prepare Profile
            </button>
          </div>
          <div className="hidden lg:flex justify-end pr-10">
            <div className="w-64 h-64 bg-white/5 rounded-[4rem] flex items-center justify-center text-[120px] rotate-12 border border-white/10">📋</div>
          </div>
        </div>
        <div className="absolute -bottom-32 -left-32 w-96 h-96 bg-indigo-600 rounded-full opacity-20 blur-[100px]"></div>
      </section>
    </div>
  );
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [childProfile, setChildProfile] = useState<ChildProfile | undefined>(undefined);
  const [latestWeight, setLatestWeight] = useState<number | undefined>(undefined);
  const [recentSymptomLogs, setRecentSymptomLogs] = useState<string[]>([]);
  const [activeChallenge, setActiveChallenge] = useState<string | undefined>(undefined);
  const [bondingNotes, setBondingNotes] = useState<string>('');

  const handleSymptomLogged = (summary: string) => {
    setRecentSymptomLogs(prev => [summary, ...prev].slice(0, 5));
  };

  const handleWeightSync = (weight: number) => {
    setLatestWeight(weight);
  };

  const handleSmartLinkChallenge = (challenge: string) => {
    setActiveChallenge(challenge);
    setActiveView('parenting');
  };

  const handleProfileSave = (profile: ChildProfile) => {
    setChildProfile(profile);
    setActiveView('dashboard');
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />;
      case 'setup': return <ChildProfileSetup initialProfile={childProfile} onSave={handleProfileSave} onCancel={childProfile ? () => setActiveView('dashboard') : undefined} />;
      case 'symptoms': return <SymptomChecker onSaveToProfile={handleSymptomLogged} />;
      case 'vaccines': return <VaccineTracker />;
      case 'growth': return <GrowthTracker onWeightUpdate={handleWeightSync} />;
      case 'dosage': return <DoseCalculator initialWeight={latestWeight} />;
      case 'milestones': return <MilestoneNavigator />;
      case 'stories': return <CalmStory />;
      case 'screening': return <ScreeningTool onLinkChallenge={handleSmartLinkChallenge} />;
      case 'profile': return <MedicalProfile externalSymptoms={recentSymptomLogs} attachmentData={{ caregiverObservations: bondingNotes }} />;
      case 'bonding': return <BondingJournal observations={bondingNotes} onUpdate={setBondingNotes} childName={childProfile?.name} />;
      case 'redbook': return <RedBook />;
      case 'parenting': return <ParentingTips preselectedChallenge={activeChallenge} onClearChallenge={() => setActiveChallenge(undefined)} />;
      default: return <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      <div key={activeView} className="animate-in fade-in slide-in-from-bottom-6 duration-700">
        {renderContent()}
      </div>
    </Layout>
  );
};

export default App;

