export const SymptomChecker: React.FC<SymptomCheckerProps> = ({ onSaveEvent }) => {
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim()) return;
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description, image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = () => {
    if (result && onSaveEvent) {
      const event: Omit<ClinicalEvent, 'id'> = {
        source: 'Symptoms',
        description: `Observation: ${description.slice(0, 100)}... Triage Action: ${result.text.match(/Triage Guide:.*?(?=\n|$)/i)?.[0] || 'See AI Analysis'}`,
        date: new Date().toLocaleDateString(),
        severity: result.text.toLowerCase().includes('red') ? 'High' : result.text.toLowerCase().includes('yellow') ? 'Medium' : 'Low'
      };
      onSaveEvent(event);
      setSaved(true);
    }
  };

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Symptom AI Guide</h2>
        <p className="text-slate-500 font-medium">Guideline-based analysis informing typical home care and clinical red flags.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-6">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Observation Description</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Describe what you're seeing (e.g. barky cough, noisy breathing, fever)..."
                className="w-full h-44 p-6 rounded-3xl border border-slate-100 bg-slate-50/30 focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all text-lg font-bold leading-relaxed shadow-inner"
              />
            </div>

            <div className="flex flex-wrap items-center gap-4">
              <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center gap-3 px-6 py-4 bg-white text-slate-700 rounded-2xl hover:bg-slate-50 transition-all font-black border-2 border-slate-100 text-xs uppercase tracking-widest"
              >
                📷 {image ? 'Change Photo' : 'Upload Sign'}
              </button>

              <button
                onClick={handleAnalyze}
                disabled={loading || !description.trim()}
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all transform hover:-translate-y-1 active:translate-y-0 uppercase tracking-widest text-sm ${
                  loading ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700'
                }`}
              >
                {loading ? 'Consulting Protocols...' : 'Review Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-48 h-48 group animate-in zoom-in-95">
                <img src={image} alt="Preview" className="w-full h-full object-cover rounded-3xl border-2 border-indigo-100 shadow-md" />
                <button onClick={() => setImage(null)} className="absolute -top-3 -right-3 bg-rose-500 text-white w-8 h-8 rounded-full flex items-center justify-center shadow-lg font-bold">×</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-indigo-50 animate-in fade-in slide-in-from-bottom-6 border-l-[16px] border-l-indigo-600 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl"></div>

              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
                <div className="flex items-center gap-4">
                  <div className="w-16 h-16 bg-indigo-50 rounded-[1.5rem] flex items-center justify-center text-4xl shadow-inner">👨‍⚕️</div>
                  <div>
                    <h3 className="text-3xl font-black text-slate-800 tracking-tighter italic">AI Analysis</h3>
                    <p className="text-indigo-600 font-black text-[10px] uppercase tracking-widest">Clinical Guideline Synthesis</p>
                  </div>
                </div>
                <button 
                  onClick={handleSave}
                  disabled={saved}
                  className={`px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-lg flex items-center gap-2 ${
                    saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700 hover:bg-indigo-200'
                  }`}
                >
                  {saved ? '✓ Logged to History' : '📋 Link to Medical Hub'}
                </button>
              </div>

              <div className="prose prose-slate max-w-none prose-lg">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic border-l-4 border-slate-100 pl-8 mb-10">
