export const MilestoneNavigator: React.FC<MilestoneNavigatorProps> = ({ onLogRedFlag }) => {
  const [milestones, setMilestones] = useState<Milestone[]>(INITIAL_DATA);
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    setMilestones(updated);

    // Auto-link red flags to the clinical event bus
    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed && onLogRedFlag) {
      onLogRedFlag(`Developmental Concern (${item.ageRange}): ${item.description.split('. Example:')[0]}`);
    }
  };

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '9 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];

  const filteredData = useMemo(() => {
    return milestones.filter(m => m.ageRange === activeAge && m.isRedFlag === showRedFlags);
  }, [milestones, activeAge, showRedFlags]);

  const CategoryBadge = ({ category }: { category: string }) => {
    const colors: Record<string, string> = {
      Motor: 'bg-blue-50 text-blue-600 border-blue-100',
      Language: 'bg-purple-50 text-purple-600 border-purple-100',
      Social: 'bg-pink-50 text-pink-600 border-pink-100',
      Cognitive: 'bg-amber-50 text-amber-600 border-amber-100',
    };
    return (
      <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black uppercase tracking-widest border ${colors[category] || 'bg-slate-50 text-slate-500 border-slate-100'}`}>
        {category}
      </span>
    );
  };

  return (
    <div className="space-y-8 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Milestone Screening</h2>
          <p className="text-slate-500 font-medium">Tracking development across all areas based on QCH clinical guidelines.</p>
        </div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm self-stretch md:self-auto overflow-x-auto no-scrollbar">
          {ageGroups.map(age => (
            <button
              key={age}
              onClick={() => setActiveAge(age)}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${
                activeAge === age ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              {age}
            </button>
          ))}
        </div>
      </header>

      <div className="flex bg-white p-1.5 rounded-[2rem] border border-slate-200 shadow-sm max-w-sm">
        <button 
          onClick={() => setShowRedFlags(false)}
          className={`flex-1 py-3 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${
            !showRedFlags ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          Typical Milestones
        </button>
        <button 
          onClick={() => setShowRedFlags(true)}
          className={`flex-1 py-3 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${
            showRedFlags ? 'bg-rose-50 text-rose-700' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          Clinical Concerns
        </button>
      </div>

      <div className={`grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in slide-in-from-bottom-4 duration-500`}>
        {filteredData.map(m => (
          <button
            key={m.id}
            onClick={() => toggleMilestone(m.id)}
            className={`p-6 rounded-[2.5rem] border-2 text-left transition-all relative group overflow-hidden h-full ${
              m.completed 
                ? (showRedFlags ? 'bg-rose-50 border-rose-200' : 'bg-emerald-50 border-emerald-200')
                : 'bg-white border-slate-100 hover:border-indigo-200 hover:shadow-xl'
            }`}
          >
            <div className="flex justify-between items-start mb-3">
              <CategoryBadge category={m.category} />
              <div className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${
                m.completed 
                  ? (showRedFlags ? 'bg-rose-600 border-rose-600 text-white' : 'bg-emerald-600 border-emerald-600 text-white')
                  : 'border-slate-100 text-transparent group-hover:border-indigo-200'
              }`}>
                {m.completed && <span className="text-lg font-black">✓</span>}
              </div>
            </div>

            <div className="space-y-2">
              <p className={`text-lg font-bold leading-tight ${m.completed ? 'opacity-80' : 'text-slate-800'}`}>
                {m.description.split('. Example:')[0]}
              </p>
              {m.description.includes('. Example:') && (
                <p className={`text-sm font-medium italic ${m.completed ? 'opacity-60' : 'text-slate-500'}`}>
                  <span className="font-bold not-italic text-[10px] uppercase tracking-wider block mb-1 opacity-70">What it looks like:</span>
                  {m.description.split('. Example:')[1]}
                </p>
              )}
            </div>

            {m.isRedFlag && !m.completed && (
              <div className="mt-4 flex items-center gap-2 text-rose-500">
                <span className="animate-pulse">⚠️</span>
                <span className="text-[10px] font-black uppercase tracking-tighter">Seek advice if observed regularly</span>
              </div>
            )}
            {m.isRedFlag && m.completed && (
              <div className="mt-4 flex items-center gap-2 text-rose-900 font-bold text-xs bg-rose-200/50 p-2 rounded-xl border border-rose-200">
                <span>📍</span> Logged for Doctor Discussion
              </div>
            )}
          </button>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { MedicalHistory, DevelopmentalHistory, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

interface MedicalProfileProps {
  pendingEvents?: ClinicalEvent[];
  onClearEvent?: (id: string) => void;
  attachmentData?: AttachmentAnalysis;
  prefilledHistory?: Partial<MedicalHistory>;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Follow 4x4 protocol: 4 puffs of Ventolin (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. CALL 000 if: distressed, lips blue, or skin sucking in around ribs.",
    triggers: "Viral colds, exercise, smoke.",
    emergencyMeds: "Salbutamol 100mcg/puff. Prednisolone dose as per doctor.",
    fluidRequirements: "Frequent sips. Monitor for signs of dehydration.",
    emergencyContact: "GP / Local ED"
  },
  epilepsy: {
    instructions: "If seizure lasts >5 mins, administer Midazolam. Place in recovery position once finished. Do not put items in mouth.",
    triggers: "Fever, lack of sleep, illness.",
    emergencyMeds: "Buccal Midazolam (Dose as prescribed).",
    fluidRequirements: "Keep hydrated post-ictally.",
    emergencyContact: "Neurology Team / Ambulance"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ pendingEvents = [], onClearEvent, attachmentData, prefilledHistory }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: prefilledHistory?.pastMedicalHistory || '',
    surgicalHistory: '',
    currentMedications: prefilledHistory?.currentMedications || [],
    allergies: prefilledHistory?.allergies || [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  });

  // Sync if prefilled changes (e.g. from setup)
  useEffect(() => {
    if (prefilledHistory) {
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: prefilledHistory.pastMedicalHistory ?? prev.pastMedicalHistory,
        currentMedications: prefilledHistory.currentMedications ?? prev.currentMedications,
        allergies: prefilledHistory.allergies ?? prev.allergies,
      }));
    }
  }, [prefilledHistory]);

  const [devHistory, setDevHistory] = useState<DevelopmentalHistory>({
    gestationalAge: '',
    deliveryMode: '',
    birthWeight: undefined,
    apgars: '',
    resuscitationNeeded: '',
    birthComplications: '',
    jaundice: false,
    nicuStay: '',
    newbornScreening: '',
    earlyMilestones: { smile: '', sit: '', walk: '', firstWords: '' },
  });

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'birth' | 'complex' | 'sickday'>('history');
  const [smartNotes, setSmartNotes] = useState('');
  const [smartImage, setSmartImage] = useState<string | null>(null);
  const smartFileInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState('');
  const [newAllergy, setNewAllergy] = useState('');
  const [newSpecialist, setNewSpecialist] = useState({ name: '', specialty: '' });
  const [newDevice, setNewDevice] = useState({ type: '', notes: '' });

  const handleMergeEvent = (event: ClinicalEvent) => {
    setHistory(prev => ({
      ...prev,
      pastMedicalHistory: prev.pastMedicalHistory + `\n[${event.date} - Source: ${event.source}] ${event.description}`
    }));
    if (onClearEvent) onClearEvent(event.id);
  };

  const handleMagicFill = async () => {
    if (!smartNotes && !smartImage) return;
    setSmartLoading(true);
    try {
      const extracted = await extractProfileFromText(smartNotes, smartImage || undefined);
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: extracted.pastMedicalHistory || prev.pastMedicalHistory,
        surgicalHistory: extracted.surgicalHistory || prev.surgicalHistory,
        currentMedications: [...new Set([...prev.currentMedications, ...(extracted.currentMedications || [])])],
        allergies: [...new Set([...prev.allergies, ...(extracted.allergies || [])])],
        specialists: [...prev.specialists, ...(extracted.specialists || []).map((s: any) => ({ ...s, id: Math.random().toString(36).substr(2, 9) }))],
        devices: [...prev.devices, ...(extracted.devices || []).map((d: any) => ({ ...d, id: Math.random().toString(36).substr(2, 9) }))],
        sickDayPlan: { ...prev.sickDayPlan, ...extracted.sickDayPlan }
      }));
      setSmartNotes('');
      setSmartImage(null);
      alert("Health profile updated! Check relevant tabs.");
    } catch (e) {
      alert("Smart Fill failed. Please enter details manually.");
    } finally {
      setSmartLoading(false);
    }
  };

  const handleAddMed = () => {
    if (newMed.trim()) {
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, newMed.trim()] }));
      setNewMed('');
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim()) {
      setHistory(prev => ({ ...prev, allergies: [...prev.allergies, newAllergy.trim()] }));
      setNewAllergy('');
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name.trim()) {
      const spec: SpecialistContact = { id: Math.random().toString(36).substr(2, 9), ...newSpecialist };
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, spec] }));
      setNewSpecialist({ name: '', specialty: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type.trim()) {
      const dev: MedicalDevice = { id: Math.random().toString(36).substr(2, 9), ...newDevice };
      setHistory(prev => ({ ...prev, devices: [...prev.devices, dev] }));
      setNewDevice({ type: '', notes: '' });
    }
  };

  const applySickDayTemplate = (key: string) => {
    const template = SICK_DAY_TEMPLATES[key];
    if (template) {
      setHistory(prev => ({ ...prev, sickDayPlan: { ...prev.sickDayPlan, ...template } }));
      setActiveTab('sickday');
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, devHistory, attachment: attachmentData, linkedEvents: pendingEvents });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-12 pb-32">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Health <span className="text-indigo-600">Companion</span></h2>
          <p className="text-slate-500 font-medium">Longitudinal clinical records and professional handover tools.</p>
        </div>
      </header>

      {/* Smart Hub Sync */}
