import { GoogleGenAI, Modality, Type } from "@google/genai";

// Use process.env.API_KEY directly as per guidelines
const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSymptoms = async (description: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a supportive and professional pediatric clinical triage assistant. 
    Your goal is to provide guideline-based interpretation of childhood symptoms.

    PATIENT REPORT: "${description}"
    ${imageBase64 ? "VISUAL EVIDENCE: A photo of the symptom has been provided. Carefully examine the image for visible signs like rashes, inflammation, or physical signs of distress." : ""}

    BASE YOUR ANALYSIS AND ADVICE ON THESE AUTHORITATIVE SOURCES:
    1. Royal Children's Hospital (RCH) Melbourne Clinical Practice Guidelines
    2. Queensland Paediatric Clinical Guidelines
    3. Raising Children Network (https://raisingchildren.net.au/)
    4. Emerging Minds Australia (https://emergingminds.com.au/) for mental health aspects.

    Structure your response with:
    1. Potential Observations & Areas to Discuss with a Doctor: (Brief list based on guidelines and visual inspection)
    2. Standard Home Care Advice: (Supportive care aligned with RCH/Queensland guidelines)
    3. Triage Guide: (Green - Monitor at home, Yellow - Consult Doctor soon, Red - Seek Urgent Care immediately)
    4. Clinical Questions for Parent: (Standard triage questions mentioned in guidelines)

    IMPORTANT: Emphasize that this is NOT a medical diagnosis and is for informational purposes only. Use professional Australian clinical terminology.
  `;

  const contents: any = { parts: [{ text: prompt }] };

  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const extractProfileFromText = async (rawText: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Extract structured medical information from the following parent notes or medical document image.
    If it's an image, perform OCR first. Focus on:
    - Current Medications and doses
    - Known Allergies
    - Specialist doctors and their specialties
    - Medical devices (G-tubes, shunts, etc)
    - Sick Day Plan details (Triggers, Emergency Meds, Fluids)

    Raw Content: "${rawText}"

    Return a valid JSON object matching the structured schema. If a field is missing, return an empty string or array.
  `;

  const parts: any[] = [{ text: prompt }];
  if (imageBase64) {
    parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          pastMedicalHistory: { type: Type.STRING },
          surgicalHistory: { type: Type.STRING },
          currentMedications: { type: Type.ARRAY, items: { type: Type.STRING } },
          allergies: { type: Type.ARRAY, items: { type: Type.STRING } },
          specialists: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT, 
              properties: { name: { type: Type.STRING }, specialty: { type: Type.STRING } } 
            } 
          },
          devices: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT, 
              properties: { type: { type: Type.STRING }, notes: { type: Type.STRING } } 
            } 
          },
          sickDayPlan: {
            type: Type.OBJECT,
            properties: {
              instructions: { type: Type.STRING },
              emergencyMeds: { type: Type.STRING },
              fluidRequirements: { type: Type.STRING },
              triggers: { type: Type.STRING },
              emergencyContact: { type: Type.STRING }
            }
          }
        }
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const calculateDosage = async (weightKg: number, medication: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Provide informational weight-based pediatric dosage for the over-the-counter (OTC) medication "${medication}" for a child weighing ${weightKg}kg.

    STRICTLY CONSULT THE FOLLOWING FOR CALCULATIONS:
    - Royal Children's Hospital (RCH) Melbourne Paediatric Pharmacopoeia / Clinical Practice Guidelines
    - Queensland Paediatric Clinical Guidelines

    YOUR TASK:
    1. Calculate the standard single dose (mg) based on ${weightKg}kg.
    2. Provide the frequency (e.g., "Every 4-6 hours, max 4 doses in 24h").
    3. Calculate the absolute maximum cumulative dose for 24 hours.
    4. List critical cautionary notes specific to this OTC medicine (e.g., liver safety for Paracetamol, stomach irritation for Ibuprofen, age restrictions).
    5. Mention concentration awareness (e.g., 100mg/5mL vs 200mg/5mL).

    Return the result in clear JSON format.

    ALWAYS emphasize checking with a pharmacist or doctor before administering. Use standard Australian pediatric protocols. This is for OTC INFORMATIONAL purposes only.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          medicationName: { type: Type.STRING },
          recommendedDose: { type: Type.STRING },
          frequency: { type: Type.STRING },
          maxDose24h: { type: Type.STRING },
          cautionaryNotes: { type: Type.STRING }
        },
        required: ["medicationName", "recommendedDose", "frequency", "maxDose24h", "cautionaryNotes"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

