  type: string;
  model?: string;
  size?: string;
  lastChanged?: string;
  nextChangeDue?: string;
  notes?: string;
}

export interface FamilyHistory {
  maternal: string;
  paternal: string;
  siblings: string;
  other: string;
}

export interface SickDayPlan {
  instructions: string;
  emergencyMeds: string;
  fluidRequirements: string;
  triggers: string;
  emergencyContact: string;
  planPhoto?: string; // New field for capturing physical documents
}

export interface Recommendation {
  id: string;
  source: string; // The specialist who made it
  date: string;
  action: string;
}

export interface MedicalHistory {
  pastMedicalHistory: string;
  surgicalHistory: string;
  currentMedications: string[];
  allergies: string[];
  familyHistory: FamilyHistory;
  specialists: SpecialistContact[];
  devices: MedicalDevice[];
  sickDayPlan: SickDayPlan;
  activeRecommendations?: Recommendation[];
}

export interface DevelopmentalHistory {
  // Birth
  gestationalAge: string;
  deliveryMode: string;
  birthWeight?: number;
  apgars?: string;
  resuscitationNeeded: string;
  birthComplications: string;

  // Neonatal
  jaundice: boolean;
  nicuStay: string;
  newbornScreening: string;

  // Early Progress
  earlyMilestones: {
    smile: string;
    sit: string;
    walk: string;
    firstWords: string;
  };
}

export interface AttachmentAnalysis {
  caregiverObservations: string;
  aiInterpretation?: string;
}

export interface ClinicalEvent {
  id: string;
  source: 'Symptoms' | 'Vaccines' | 'Milestones' | 'Growth';
  description: string;
  date: string;
  severity?: 'Low' | 'Medium' | 'High';
}

export interface ChildProfile {
  name: string;
  dob: string;
  sex: 'Male' | 'Female' | 'Other';
  weight?: number;
  height?: number;
  pastMedicalHistory?: string;
  medications?: string[];
  allergies?: string[];
  complexNeeds?: boolean;
}

export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting' | 'setup' | 'bonding';

import React, { useState, useRef, useEffect } from 'react';
import { MedicalHistory, DevelopmentalHistory, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, Recommendation } from '../types';
import { analyzeMedicalProfile, extractProfileFromText } from '../services/gemini';

interface MedicalProfileProps {
  pendingEvents?: ClinicalEvent[];
  onClearEvent?: (id: string) => void;
  attachmentData?: AttachmentAnalysis;
  prefilledHistory?: Partial<MedicalHistory>;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Standard Australian 4x4 Protocol: Give 4 puffs of blue reliever (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4x4. Call 000 if child is distressed, lips blue, or skin is sucking in at the ribs/neck.",
    triggers: "Viral colds, exercise, cigarette smoke, dust mites, rapid weather changes.",
    emergencyMeds: "Salbutamol (Ventolin/Asmol) 100mcg inhaler. Oral prednisolone as per GP/Specialist weight-based plan.",
    fluidRequirements: "Frequent small sips. Monitor for increased work of breathing while swallowing.",
    emergencyContact: "General Practitioner / Respiratory Specialist / Nearest Children's ED"
  },
  epilepsy: {
    instructions: "Stay calm and time the seizure. Protect from injury (move hard objects). Place in recovery position once jerking stops. DO NOT restrain or put anything in mouth. Call 000 if: Seizure >5 mins, 2nd seizure occurs quickly, or this is a first-ever seizure.",
    triggers: "Fever/Illness, missed doses, lack of sleep, flickering lights (if photosensitive).",
    emergencyMeds: "Buccal Midazolam (if prescribed): Administer exact dose into the side of the mouth between gums and cheek.",
    fluidRequirements: "Hydrate only when child is fully alert and recovered.",
    emergencyContact: "Neurology Specialist / Epilepsy Nurse Coordinator / 000"
  },
  metabolic: {
