    triggers: "Fever >38°C, diarrhea, vomiting, prolonged fasting (>6-8 hours).",
    emergencyMeds: "Glucose polymer (Poly-Joule/Maxijul) as per metabolic specialist's concentration guide. Antipyretics for fever.",
    fluidRequirements: "Calculated high-carbohydrate feeds every 2 hours, including overnight. Do not skip feeds.",
    emergencyContact: "On-call Metabolic Consultant / Metabolic Clinic"
  },
  adrenal: {
    instructions: "COMMENCE STRESS DOSING for fever >38°C or significant illness. Double the oral Hydrocortisone dose every 6-8 hours. If vomiting occurs even once, administer IM Hydrocortisone (Solu-Cortef) immediately and call 000.",
    triggers: "Fever, major injury (e.g. broken bone), vomiting, diarrhea, general anesthesia.",
    emergencyMeds: "Hydrocortisone tablets (oral). Solu-Cortef (IM Injection) for emergency use.",
    fluidRequirements: "Hydrate with electrolyte solutions (e.g. Hydralyte). Monitor for low blood pressure or extreme lethargy.",
    emergencyContact: "Endocrine Specialist / Local Pediatric ED"
  },
  t1d: {
    instructions: "Check Blood Glucose and Ketones every 2 hours. Follow specific insulin adjustment guides provided by clinic. Call specialist if: Blood Glucose >15mmol/L with persistent ketones, or if child is vomiting and cannot keep fluids down.",
    triggers: "Infection, fever, missed insulin, high stress.",
    emergencyMeds: "Correction doses of rapid-acting insulin. Glucagon kit (for severe hypoglycemia).",
