    emergencyContact: "Diabetes Educator / On-call Endocrinologist"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ pendingEvents = [], onClearEvent, attachmentData, prefilledHistory }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: prefilledHistory?.pastMedicalHistory || '',
    surgicalHistory: '',
    currentMedications: prefilledHistory?.currentMedications || [],
    allergies: prefilledHistory?.allergies || [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '', planPhoto: undefined },
    activeRecommendations: []
  });

  useEffect(() => {
    if (prefilledHistory) {
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: prefilledHistory.pastMedicalHistory ?? prev.pastMedicalHistory,
        currentMedications: prefilledHistory.currentMedications ?? prev.currentMedications,
        allergies: prefilledHistory.allergies ?? prev.allergies,
      }));
    }
  }, [prefilledHistory]);

  const [loading, setLoading] = useState(false);
  const [smartLoading, setSmartLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'mdt' | 'gear' | 'sickday'>('history');

  const [smartNotes, setSmartNotes] = useState('');
  const smartFileInputRef = useRef<HTMLInputElement>(null);
  const planPhotoInputRef = useRef<HTMLInputElement>(null);

  // Form states
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', lastSeen: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', lastChanged: '', nextChangeDue: '' });
  const [newRecommendation, setNewRecommendation] = useState<Partial<Recommendation>>({ source: '', action: '', date: new Date().toISOString().split('T')[0] });

  const handleMergeEvent = (event: ClinicalEvent) => {
    setHistory(prev => ({
      ...prev,
      pastMedicalHistory: prev.pastMedicalHistory + `\n[${event.date} - Source: ${event.source}] ${event.description}`
    }));
    if (onClearEvent) onClearEvent(event.id);
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name && newSpecialist.specialty) {
      const spec: SpecialistContact = { id: Math.random().toString(36).substr(2, 9), ...newSpecialist } as SpecialistContact;
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, spec] }));
      setNewSpecialist({ name: '', specialty: '', lastSeen: '', nextReview: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type) {
      const dev: MedicalDevice = { id: Math.random().toString(36).substr(2, 9), ...newDevice } as MedicalDevice;
      setHistory(prev => ({ ...prev, devices: [...prev.devices, dev] }));
      setNewDevice({ type: '', model: '', lastChanged: '', nextChangeDue: '' });
    }
  };

  const handleAddRecommendation = () => {
    if (newRecommendation.action) {
      const rec: Recommendation = { id: Math.random().toString(36).substr(2, 9), ...newRecommendation } as Recommendation;
      setHistory(prev => ({ ...prev, activeRecommendations: [...(prev.activeRecommendations || []), rec] }));
      setNewRecommendation({ source: '', action: '', date: new Date().toISOString().split('T')[0] });
    }
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setHistory(prev => ({
          ...prev,
          sickDayPlan: { ...prev.sickDayPlan, planPhoto: reader.result as string }
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const applySickDayTemplate = (key: keyof typeof SICK_DAY_TEMPLATES) => {
    const template = SICK_DAY_TEMPLATES[key];
    if (template && window.confirm(`This will update the Sick Day fields based on the ${key.toUpperCase()} template. Proceed?`)) {
      setHistory(prev => ({
        ...prev,
        sickDayPlan: {
          ...prev.sickDayPlan,
          instructions: template.instructions || '',
          emergencyMeds: template.emergencyMeds || '',
          fluidRequirements: template.fluidRequirements || '',
          triggers: template.triggers || '',
          emergencyContact: template.emergencyContact || ''
        }
      }));
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-12 pb-32">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Complex Care <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Professional MDT coordination and clinical ISBAR records.</p>
        </div>
        <div className="bg-indigo-50 border border-indigo-100 px-4 py-2 rounded-2xl flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse"></span>
            <span className="text-[10px] font-black text-indigo-700 uppercase tracking-widest">ISBAR Framework Enabled</span>
        </div>
      </header>

      {/* Cross-Module Smart Hub */}
      <section className="bg-white p-10 rounded-[3rem] border border-indigo-100 shadow-xl overflow-hidden relative group">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl group-hover:opacity-10 transition-opacity"></div>
        <div className="flex items-center gap-4 mb-8">
          <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">🪄</div>
          <div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tighter">Clinical Sync Hub</h3>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Bridging fragmented records</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
          <div className="space-y-6">
             <div className="bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100">
               <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Letter Import & AI Synthesis</h4>
               <textarea 
                value={smartNotes}
                onChange={e => setSmartNotes(e.target.value)}
                placeholder="Paste specialist letter text here..."
                className="w-full h-32 p-5 rounded-2xl border border-slate-200 bg-white outline-none text-sm resize-none font-medium focus:ring-2 focus:ring-indigo-500"
              />
              <div className="flex gap-2 mt-4">
                <button onClick={() => smartFileInputRef.current?.click()} className="flex-1 py-3 bg-white text-slate-600 font-black rounded-xl hover:bg-slate-50 transition-all text-[10px] uppercase border border-slate-200">📷 Photo</button>
                <input type="file" ref={smartFileInputRef} className="hidden" accept="image/*" />
                <button className="px-8 py-3 bg-indigo-600 text-white font-black rounded-xl shadow-lg text-[10px] uppercase tracking-widest">Sync</button>
              </div>
             </div>
          </div>

          <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Pending MDT Activity</h4>
             <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 no-scrollbar">
               {pendingEvents.length > 0 ? pendingEvents.map((event) => (
                 <div key={event.id} className={`bg-white p-5 rounded-2xl border flex items-start justify-between group transition-all ${
                   event.severity === 'High' ? 'border-rose-100 bg-rose-50/20' : 'border-slate-100'
                 }`}>
                   <div className="space-y-1">
                     <p className="text-[9px] font-black text-indigo-600 uppercase tracking-widest">{event.source} • {event.date}</p>
                     <p className="text-xs font-bold text-slate-600 leading-snug">{event.description}</p>
                   </div>
                   <button onClick={() => handleMergeEvent(event)} className="text-[9px] font-black text-emerald-600 uppercase hover:underline ml-4">Merge</button>
                 </div>
               )) : (
                 <div className="flex flex-col items-center justify-center py-10 text-center space-y-2 opacity-40">
                   <span className="text-3xl">🧩</span>
                   <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">MDT History clear</p>
                 </div>
               )}
             </div>
          </div>
        </div>
      </section>

      {/* Navigation Tabs */}
      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'Baseline History', icon: '📋' },
          { id: 'mdt', label: 'Multidisciplinary Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Medical Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Sick Day Protocol', icon: '🤒' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[160px] py-4 rounded-2xl font-black transition-all text-xs uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span className="text-xl">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      {/* Main Content Sections */}
      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[600px] animate-in slide-in-from-bottom-6 duration-500">

        {/* BASELINE HISTORY */}
        {activeTab === 'history' && (
          <div className="p-10 space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-6">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Longitudinal Diagnoses</label>
                <textarea 
                  value={history.pastMedicalHistory}
                  onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                  className="w-full h-44 p-8 rounded-[3rem] border border-slate-100 bg-slate-50/20 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Chronic conditions and primary medical history..."
                />
              </div>
              <div className="space-y-6">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Active Recommendations</label>
                <div className="bg-amber-50/50 p-6 rounded-[2.5rem] border border-amber-100 space-y-4">
                  <div className="flex gap-2">
                    <input 
                      value={newRecommendation.action} 
                      onChange={e => setNewRecommendation({...newRecommendation, action: e.target.value})}
                      placeholder="Add specialist advice..."
                      className="flex-1 p-3 rounded-xl border border-amber-200 text-sm"
                    />
                    <button onClick={handleAddRecommendation} className="bg-amber-500 text-white px-4 rounded-xl font-black text-xs uppercase">Add</button>
                  </div>
                  <div className="space-y-2">
                    {history.activeRecommendations?.map(rec => (
                      <div key={rec.id} className="bg-white p-3 rounded-xl border border-amber-100 text-xs font-bold flex justify-between">
                        <span>{rec.action}</span>
                        <button onClick={() => setHistory(prev => ({...prev, activeRecommendations: prev.activeRecommendations?.filter(x => x.id !== rec.id)}))} className="text-rose-400">×</button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* MDT TEAM MANAGEMENT */}
        {activeTab === 'mdt' && (
          <div className="p-10 space-y-8">
            <div className="bg-indigo-50 p-8 rounded-[3rem] border border-indigo-100 mb-8">
              <h4 className="font-black text-indigo-900 mb-6 flex items-center gap-2">👨‍⚕️ Add Team Member</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <input placeholder="Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                <input placeholder="Specialty" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                <input type="date" value={newSpecialist.lastSeen} onChange={e => setNewSpecialist({...newSpecialist, lastSeen: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                <button onClick={handleAddSpecialist} className="bg-indigo-600 text-white p-4 rounded-xl font-black text-xs uppercase shadow-lg">Join Team</button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {history.specialists.map(s => (
                <div key={s.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all relative group">
                  <button onClick={() => setHistory(prev => ({...prev, specialists: prev.specialists.filter(x => x.id !== s.id)}))} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity font-black">×</button>
                  <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1">{s.specialty}</p>
                  <h5 className="text-xl font-black text-slate-800 mb-4">{s.name}</h5>
                  <div className="space-y-2 border-t border-slate-50 pt-4">
                    <p className="text-[9px] font-black text-slate-400 uppercase">Last seen: <span className="text-slate-800">{s.lastSeen || 'N/A'}</span></p>
                    <p className="text-[9px] font-black text-slate-400 uppercase">Review due: <span className="text-indigo-600">{s.nextReview || 'TBC'}</span></p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* MEDICAL GEAR TRACKING */}
        {activeTab === 'gear' && (
          <div className="p-10 space-y-8">
            <div className="bg-slate-900 p-8 rounded-[3rem] text-white">
               <h4 className="font-black text-xl mb-6">⚙️ Device Maintenance Log</h4>
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <input placeholder="Device Type (e.g. G-Tube)" value={newDevice.type} onChange={e => setNewDevice({...newDevice, type: e.target.value})} className="p-4 rounded-xl bg-white/10 border-none text-sm font-bold text-white placeholder:text-white/40" />
                  <input placeholder="Size / Model" value={newDevice.model} onChange={e => setNewDevice({...newDevice, model: e.target.value})} className="p-4 rounded-xl bg-white/10 border-none text-sm font-bold text-white placeholder:text-white/40" />
                  <input type="date" value={newDevice.lastChanged} onChange={e => setNewDevice({...newDevice, lastChanged: e.target.value})} className="p-4 rounded-xl bg-white/10 border-none text-sm font-bold text-white uppercase" />
                  <button onClick={handleAddDevice} className="bg-indigo-500 text-white p-4 rounded-xl font-black text-xs uppercase shadow-xl hover:bg-indigo-400 transition-colors">Log Component</button>
               </div>
            </div>

            <div className="space-y-4">
              {history.devices.map(d => (
                <div key={d.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6 shadow-sm">
                  <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-3xl">🔩</div>
                    <div>
                      <h5 className="text-2xl font-black text-slate-800 tracking-tight">{d.type}</h5>
                      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Ref: {d.model || 'Standard'}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-8 text-center">
                    <div>
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Installed</p>
                      <p className="font-black text-slate-800">{d.lastChanged || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-1">Next Change Due</p>
                      <p className="font-black text-indigo-600">{d.nextChangeDue || 'N/A'}</p>
                    </div>
                    <button onClick={() => setHistory(prev => ({...prev, devices: prev.devices.filter(x => x.id !== d.id)}))} className="text-rose-400 hover:text-rose-600 font-black ml-4">×</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* SICK DAY PROTOCOL */}
        {activeTab === 'sickday' && (
          <div className="p-10 space-y-8">
            <div className="bg-amber-50 p-10 rounded-[3rem] border border-amber-200 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none text-9xl">🤒</div>
                <div className="flex items-center gap-6 mb-10">
                   <div className="w-16 h-16 bg-amber-500 rounded-2xl flex items-center justify-center text-white text-3xl shadow-xl">🚨</div>
                   <div>
                     <h4 className="text-3xl font-black text-amber-950 tracking-tight italic">Acute Deterioration Protocol</h4>
                     <p className="text-amber-800 font-bold opacity-70 italic">What every clinician needs to know when your child is unwell.</p>
                   </div>
                </div>

                {/* Templates Section */}
                <div className="mb-10 bg-white/40 p-6 rounded-3xl border border-amber-200/50">
                   <p className="text-[10px] font-black text-amber-900 uppercase tracking-widest mb-4 ml-2">Clinical Standards (RCH / Australian Guidelines)</p>
                   <div className="flex flex-wrap gap-2">
                     <button onClick={() => applySickDayTemplate('asthma')} className="px-5 py-3 bg-white border border-amber-200 rounded-2xl text-xs font-black text-amber-900 shadow-sm hover:shadow-md transition-all">🫁 Asthma Plan</button>
                     <button onClick={() => applySickDayTemplate('epilepsy')} className="px-5 py-3 bg-white border border-amber-200 rounded-2xl text-xs font-black text-amber-900 shadow-sm hover:shadow-md transition-all">🧠 Seizure Management</button>
                     <button onClick={() => applySickDayTemplate('metabolic')} className="px-5 py-3 bg-white border border-amber-200 rounded-2xl text-xs font-black text-amber-900 shadow-sm hover:shadow-md transition-all">🧪 Metabolic Emergency</button>
                     <button onClick={() => applySickDayTemplate('adrenal')} className="px-5 py-3 bg-white border border-amber-200 rounded-2xl text-xs font-black text-amber-900 shadow-sm hover:shadow-md transition-all">⚖️ Adrenal Stress Dose</button>
                     <button onClick={() => applySickDayTemplate('t1d')} className="px-5 py-3 bg-white border border-amber-200 rounded-2xl text-xs font-black text-amber-900 shadow-sm hover:shadow-md transition-all">💉 T1D Sick Day</button>
                   </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                  <div className="space-y-6">
                    <div className="space-y-2">
                       <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest ml-2">Specific Triggers</label>
                       <textarea 
                        value={history.sickDayPlan.triggers} 
                        onChange={e => setHistory({...history, sickDayPlan: {...history.sickDayPlan, triggers: e.target.value}})} 
                        className="w-full h-32 p-6 rounded-3xl bg-white border-none shadow-inner font-bold text-slate-700" 
                        placeholder="Fever >38.5, Cough, Vomiting..." 
                       />
                    </div>
                    <div className="space-y-2">
                       <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest ml-2">Emergency Rescue Doses</label>
                       <textarea 
                        value={history.sickDayPlan.emergencyMeds} 
                        onChange={e => setHistory({...history, sickDayPlan: {...history.sickDayPlan, emergencyMeds: e.target.value}})} 
                        className="w-full h-32 p-6 rounded-3xl bg-white border-none shadow-inner font-bold text-slate-700" 
                        placeholder="E.g. Midazolam protocol or Steroid stress dose..." 
                       />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="block text-[10px] font-black text-amber-900 uppercase tracking-widest ml-2">Step-by-Step Triage Instructions</label>
                      <textarea 
                        value={history.sickDayPlan.instructions} 
                        onChange={e => setHistory({...history, sickDayPlan: {...history.sickDayPlan, instructions: e.target.value}})} 
                        className="w-full h-72 p-8 rounded-[3rem] bg-white border-none shadow-inner font-bold text-lg leading-relaxed italic text-slate-700" 
                        placeholder="1. Administer rescue meds... 2. Call Specialist... 3. Go to ED if..." 
                      />
                    </div>
                  </div>
                </div>

                {/* Digital Record Capture */}
                <div className="mt-10 pt-10 border-t border-amber-200/40">
                   <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                      <div className="space-y-1 text-center md:text-left">
                        <h5 className="font-black text-amber-950">📷 Plan Document Capture</h5>
                        <p className="text-amber-800 text-xs font-bold opacity-70 italic">Snap a photo of your physical hospital plan to keep as a digital backup.</p>
                      </div>
                      <input type="file" ref={planPhotoInputRef} className="hidden" accept="image/*" capture="environment" onChange={handlePhotoCapture} />
                      <button 
                        onClick={() => planPhotoInputRef.current?.click()}
                        className="px-8 py-4 bg-amber-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-xs hover:bg-amber-700 transition-all"
                      >
                        {history.sickDayPlan.planPhoto ? 'Retake Document Photo' : 'Capture Physical Plan'}
                      </button>
                   </div>

                   {history.sickDayPlan.planPhoto && (
                     <div className="mt-8 relative group max-w-lg mx-auto overflow-hidden rounded-[3rem] border-4 border-white shadow-2xl transition-transform hover:scale-[1.02]">
                        <img src={history.sickDayPlan.planPhoto} alt="Physical Sick Day Plan" className="w-full h-auto object-cover" />
                        <button 
                          onClick={() => setHistory(prev => ({...prev, sickDayPlan: {...prev.sickDayPlan, planPhoto: undefined}}))}
                          className="absolute top-6 right-6 w-12 h-12 bg-rose-600 text-white rounded-full flex items-center justify-center font-black text-2xl shadow-2xl opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          ×
                        </button>
                        <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/60 to-transparent p-8">
                           <p className="text-white text-[10px] font-black uppercase tracking-widest">Linked Clinical Document Record</p>
                        </div>
                     </div>
                   )}
                </div>
            </div>
          </div>
        )}
      </div>

      {/* ISBAR GENERATOR */}
      <div className="flex flex-col items-center gap-6 pt-12">
        <button 
          onClick={handleGenerateHandover}
          disabled={loading}
          className={`px-16 py-7 rounded-[2.5rem] font-black text-2xl text-white shadow-2xl flex items-center gap-4 transition-all transform hover:-translate-y-2 active:scale-95 ${
            loading ? 'bg-slate-300' : 'bg-indigo-700 hover:bg-indigo-800'
          }`}
        >
          {loading ? "Synthesizing ISBAR..." : "📋 Generate MDT Handover ✨"}
        </button>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] text-center max-w-sm">Professional-Grade Clinical Communication</p>
      </div>

      {aiAnalysis && (
        <div className="bg-white p-14 rounded-[4rem] border border-indigo-100 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)] mt-20 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500 rounded-full opacity-5 blur-[100px]"></div>
           <div className="flex items-center justify-between mb-12">
             <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl shadow-inner">📄</div>
                <div>
                   <h3 className="text-4xl font-black text-slate-800 italic tracking-tighter">Clinical ISBAR Summary</h3>
                   <p className="text-indigo-600 font-black text-[10px] uppercase tracking-widest">Optimized for Specialist & ED Presentation</p>
                </div>
             </div>
             <button onClick={() => {navigator.clipboard.writeText(aiAnalysis.text); alert("ISBAR Handover Copied!");}} className="bg-indigo-50 text-indigo-700 px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest">Copy to Clipboard</button>
           </div>

           <div className="prose prose-indigo max-w-none prose-xl whitespace-pre-wrap text-slate-700 italic font-bold leading-relaxed border-l-8 border-slate-50 pl-10">
            {aiAnalysis.text}
           </div>

           <div className="mt-14 pt-10 border-t border-slate-100 grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="p-6 bg-slate-50 rounded-3xl text-center">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Framework</p>
                 <p className="text-sm font-black text-slate-800">ISBAR 2.0</p>
              </div>
              <div className="p-6 bg-slate-50 rounded-3xl text-center">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Standard</p>
                 <p className="text-sm font-black text-slate-800">Australian MDT</p>
              </div>
              <div className="p-6 bg-slate-50 rounded-3xl text-center">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Context</p>
                 <p className="text-sm font-black text-slate-800">Comprehensive Care</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

