};

import React, { useState } from 'react';
import { ChildProfile, Medication } from '../types';

interface ChildProfileSetupProps {
  initialProfile?: ChildProfile;
  onSave: (profile: ChildProfile) => void;
  onCancel?: () => void;
}

export const ChildProfileSetup: React.FC<ChildProfileSetupProps> = ({ initialProfile, onSave, onCancel }) => {
  const [name, setName] = useState(initialProfile?.name || '');
  const [dob, setDob] = useState(initialProfile?.dob || '');
  const [sex, setSex] = useState<ChildProfile['sex']>(initialProfile?.sex || 'Male');
  const [weight, setWeight] = useState(initialProfile?.weight?.toString() || '');
  const [height, setHeight] = useState(initialProfile?.height?.toString() || '');
  const [medHistory, setMedHistory] = useState(initialProfile?.pastMedicalHistory || '');

  const [meds, setMeds] = useState<Medication[]>(initialProfile?.medications || []);
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: '' });

  const [allergies, setAllergies] = useState<string[]>(initialProfile?.allergies || []);
  const [newAllergy, setNewAllergy] = useState('');

  const handleAddMed = () => {
    if (newMed.name) {
      setMeds([...meds, { id: Math.random().toString(36).substr(2, 9), ...newMed } as Medication]);
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
    }
  };

  const handleAddAllergy = () => {
    if (newAllergy.trim() && !allergies.includes(newAllergy.trim())) {
      setAllergies([...allergies, newAllergy.trim()]);
      setNewAllergy('');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !dob) return;
    onSave({
      name,
      dob,
      sex,
      weight: weight ? parseFloat(weight) : undefined,
      height: height ? parseFloat(height) : undefined,
      pastMedicalHistory: medHistory,
      medications: meds,
      previousMedications: initialProfile?.previousMedications || [],
      allergies: allergies
    });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-10 duration-700 pb-20">
      <header className="text-center space-y-4">
        <div className="w-24 h-24 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-6 shadow-2xl rotate-3">
          🩺
        </div>
        <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">
          {initialProfile ? 'Update Child Records' : 'Clinical Onboarding'}
        </h2>
        <p className="text-slate-500 font-medium max-w-xl mx-auto">
          {initialProfile 
            ? 'Refine your child\'s baseline medical and growth data.' 
            : 'Initialize your child\'s clinical profile to enable personalized AI triage and precise growth analysis.'}
        </p>
      </header>

      <form onSubmit={handleSubmit} className="space-y-10">
        {/* Basic Section */}
        <section className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
          <div className="flex items-center gap-3 mb-2">
            <span className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-lg">🆔</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Identity & Basic Metrics</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Legal Name</label>
              <input
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Full Name"
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-lg"
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date of Birth</label>
              <input
                type="date"
                required
                value={dob}
                onChange={(e) => setDob(e.target.value)}
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-lg uppercase"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Sex</label>
              <select 
                value={sex} 
                onChange={(e) => setSex(e.target.value as any)}
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 font-bold"
              >
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Other">Other</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Initial Weight (kg)</label>
              <input
                type="number"
                step="0.01"
                value={weight}
                onChange={(e) => setWeight(e.target.value)}
                placeholder="0.00"
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 font-bold"
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Initial Height (cm)</label>
              <input
                type="number"
                step="0.1"
                value={height}
                onChange={(e) => setHeight(e.target.value)}
                placeholder="00.0"
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 font-bold"
              />
            </div>
          </div>
        </section>

        {/* Clinical History Section */}
        <section className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
          <div className="flex items-center gap-3 mb-2">
            <span className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center text-lg">📋</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Medical Background</h3>
          </div>

          <div className="space-y-2">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Past Medical & Surgical History</label>
            <textarea
              value={medHistory}
              onChange={(e) => setMedHistory(e.target.value)}
              placeholder="List any chronic conditions, past surgeries, or significant hospital admissions..."
              className="w-full h-40 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-rose-500 outline-none font-medium resize-none"
            />
          </div>

          <div className="space-y-6">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Regular Medications</label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-50 p-6 rounded-3xl">
              <input value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} placeholder="Medication Name" className="p-3 rounded-xl border border-slate-100" />
              <input value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} placeholder="Dose (e.g. 5mL)" className="p-3 rounded-xl border border-slate-100" />
              <input value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} placeholder="Timing (e.g. Morning)" className="p-3 rounded-xl border border-slate-100" />
              <button type="button" onClick={handleAddMed} className="bg-indigo-600 text-white rounded-xl font-black text-xs uppercase p-3">Add to List</button>
            </div>
            <div className="space-y-2">
              {meds.map((m) => (
                <div key={m.id} className="flex justify-between items-center bg-white p-3 rounded-xl border border-indigo-100 text-xs font-bold">
                   <span>{m.name} ({m.dose}) - {m.instructions}</span>
                   <button type="button" onClick={() => setMeds(meds.filter(x => x.id !== m.id))} className="text-rose-400">×</button>
                </div>
              ))}
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-50">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Known Allergies</label>
            <div className="flex gap-2">
              <input 
                value={newAllergy} 
                onChange={e => setNewAllergy(e.target.value)} 
                placeholder="Add allergy" 
                className="flex-1 p-4 rounded-xl border border-slate-100 bg-slate-50/50 text-sm"
                onKeyPress={e => e.key === 'Enter' && (e.preventDefault(), handleAddAllergy())}
              />
              <button type="button" onClick={handleAddAllergy} className="bg-rose-500 text-white px-4 rounded-xl font-black text-xs uppercase">Add</button>
            </div>
            <div className="flex flex-wrap gap-2 min-h-[40px]">
              {allergies.map((a, i) => (
                <span key={i} className="px-3 py-1 bg-rose-50 text-rose-700 rounded-lg text-[10px] font-black border border-rose-100 flex items-center gap-2 uppercase tracking-wider">
                  {a} <button type="button" onClick={() => setAllergies(allergies.filter((_, idx) => idx !== i))}>×</button>
                </span>
              ))}
            </div>
          </div>
        </section>

        <div className="flex gap-4 pt-4">
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 py-6 bg-slate-100 text-slate-500 font-black rounded-3xl hover:bg-slate-200 transition-all text-sm uppercase tracking-widest"
            >
              Cancel
            </button>
          )}
          <button
            type="submit"
            className="flex-grow py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-2xl hover:bg-indigo-700 transition-all transform active:scale-95 text-sm uppercase tracking-widest"
          >
            {initialProfile ? 'Sync Updated Records' : 'Finalize & Create Profile ✨'}
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
