export const MedicalProfile: React.FC<MedicalProfileProps> = ({ pendingEvents = [], onClearEvent, attachmentData, prefilledHistory }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: prefilledHistory?.pastMedicalHistory || '',
    surgicalHistory: '',
    currentMedications: prefilledHistory?.currentMedications || [],
    previousMedications: prefilledHistory?.previousMedications || [],
    allergies: prefilledHistory?.allergies || [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '', planPhoto: undefined },
    activeRecommendations: [],
    medicalReports: [],
    acuteLogs: []
  });

  useEffect(() => {
    if (prefilledHistory) {
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: prefilledHistory.pastMedicalHistory ?? prev.pastMedicalHistory,
        currentMedications: prefilledHistory.currentMedications ?? prev.currentMedications,
        previousMedications: prefilledHistory.previousMedications ?? prev.previousMedications,
        allergies: prefilledHistory.allergies ?? prev.allergies,
      }));
    }
  }, [prefilledHistory]);

  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'gear' | 'reports' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const planPhotoInputRef = useRef<HTMLInputElement>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', lastSeen: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', lastChanged: '', nextChangeDue: '' });

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          setHistory(prev => ({
            ...prev,
            medicalReports: [...(prev.medicalReports || []), newReport]
          }));
          alert("Report analyzed and synthesized!");
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddMedication = () => {
    if (newMed.name) {
      const med: Medication = { id: Math.random().toString(36).substr(2, 9), ...newMed } as Medication;
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, med] }));
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
    }
  };

  const archiveMedication = (med: Medication) => {
    const reason = window.prompt(`Why was ${med.name} ceased?`, "Treatment course completed");
    if (reason !== null) {
      const ceased: PreviousMedication = {
        id: med.id,
        name: med.name,
        dose: med.dose,
        indication: med.indication,
        ceasedDate: new Date().toISOString().split('T')[0],
        ceaseReason: reason
      };
      setHistory(prev => ({
        ...prev,
        currentMedications: prev.currentMedications.filter(x => x.id !== med.id),
        previousMedications: [...prev.previousMedications, ceased]
      }));
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-12 pb-32">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Complex Care <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical ISBAR coordination for complex pediatric needs.</p>
        </div>
      </header>

      {/* Navigation Tabs */}
      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📋' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Sick Day', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-xs uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span className="text-xl">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[600px] animate-in slide-in-from-bottom-6 duration-500">

        {/* HISTORY */}
        {activeTab === 'history' && (
          <div className="p-10 space-y-12">
            <div className="space-y-6">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Longitudinal Diagnoses</label>
              <textarea 
                value={history.pastMedicalHistory}
                onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                className="w-full h-44 p-8 rounded-[3rem] border border-slate-100 bg-slate-50/20 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500"
                placeholder="e.g. 26wk Preterm, Chronic Lung Disease, G-Tube..."
              />
            </div>
          </div>
        )}

        {/* REPORTS (LETTERS) */}
        {activeTab === 'reports' && (
          <div className="p-10 space-y-10">
            <div className="bg-indigo-50 p-10 rounded-[3rem] border border-indigo-100 flex flex-col md:flex-row items-center justify-between gap-6">
               <div className="space-y-2 text-center md:text-left">
                  <h4 className="text-2xl font-black text-indigo-950 tracking-tight flex items-center gap-2">
                     <span className="text-3xl">🪄</span> Letter Insight AI
                  </h4>
                  <p className="text-indigo-800 font-bold opacity-70 italic text-sm">Upload specialist letters to get parent-friendly summaries and action items.</p>
               </div>
               <input type="file" ref={reportInputRef} className="hidden" accept="image/*" onChange={handleReportUpload} />
               <button 
                  onClick={() => reportInputRef.current?.click()}
                  disabled={reportLoading}
                  className="px-10 py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-[10px] hover:bg-indigo-700 transition-all"
               >
                  {reportLoading ? 'Processing Document...' : 'Upload & Analyze Letter'}
               </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
               {history.medicalReports?.map(report => (
                  <div key={report.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all space-y-4">
                     <div className="flex justify-between items-start">
                        <div>
                           <p className="text-[9px] font-black text-indigo-600 uppercase tracking-widest">{report.date}</p>
                           <h5 className="text-xl font-black text-slate-800">{report.specialist}</h5>
                        </div>
                        {report.photoUrl && <div className="w-12 h-12 bg-slate-50 rounded-xl overflow-hidden border border-slate-200"><img src={report.photoUrl} className="w-full h-full object-cover" /></div>}
                     </div>
                     <p className="text-sm font-bold text-slate-600 leading-relaxed italic border-l-4 border-indigo-100 pl-4">"{report.summary}"</p>
                     <div className="space-y-2">
                        <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Key Actions</p>
                        <ul className="space-y-1">
                           {report.actionItems.map((item, i) => (
                              <li key={i} className="text-xs font-black text-slate-800 flex items-center gap-2">
                                 <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></span> {item}
                              </li>
                           ))}
                        </ul>
                     </div>
                  </div>
               ))}
            </div>
          </div>
        )}

        {/* MEDS, MDT, GEAR, SICKDAY content (omitted for brevity, keep existing logic) */}
        {activeTab === 'meds' && <div className="p-10">Medications view here...</div>}
        {activeTab === 'mdt' && <div className="p-10">Care Team view here...</div>}
        {activeTab === 'gear' && <div className="p-10">Devices view here...</div>}
        {activeTab === 'sickday' && <div className="p-10">Sick Day view here...</div>}
      </div>

      <div className="flex flex-col items-center gap-6 pt-12">
        <button 
          onClick={handleGenerateHandover}
          disabled={loading}
          className={`px-16 py-7 rounded-[2.5rem] font-black text-2xl text-white shadow-2xl flex items-center gap-4 transition-all transform hover:-translate-y-2 active:scale-95 ${
            loading ? 'bg-slate-300' : 'bg-indigo-700 hover:bg-indigo-800'
          }`}
        >
          {loading ? "Synthesizing ISBAR..." : "📋 Generate MDT Handover ✨"}
        </button>
      </div>

      {aiAnalysis && (
        <div className="bg-white p-14 rounded-[4rem] border border-indigo-100 shadow-2xl mt-20 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative">
           <div className="prose prose-indigo max-w-none prose-xl whitespace-pre-wrap text-slate-700 italic font-bold leading-relaxed border-l-8 border-slate-50 pl-10">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { AcuteLogEntry } from '../types';

interface AcuteTrackerProps {
  onLogEntry: (entry: Omit<AcuteLogEntry, 'id'>) => void;
  entries: AcuteLogEntry[];
}

export const AcuteTracker: React.FC<AcuteTrackerProps> = ({ onLogEntry, entries }) => {
  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');

  const handleAdd = () => {
    if (!value) return;
    onLogEntry({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type,
      value,
      notes
    });
    setValue('');
    setNotes('');
  };

  const icons = { Fluid: '🥤', Temperature: '🌡️', Output: '🚽', Medication: '💊' };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6">
      <header>
        <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Sync Log</span></h2>
        <p className="text-slate-500 font-medium italic">High-resolution tracking for sick days (fluids, fever, output).</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
            <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
               {Object.keys(icons).map((t) => (
                  <button
                    key={t}
                    onClick={() => setType(t as any)}
                    className={`flex-1 py-3 rounded-xl text-xl transition-all ${type === t ? 'bg-white shadow-md scale-105' : 'opacity-40 hover:opacity-100'}`}
                  >
                    {icons[t as keyof typeof icons]}
                  </button>
               ))}
            </div>

            <div className="space-y-4">
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Reading / Amount</label>
                  <input 
                    value={value} 
                    onChange={e => setValue(e.target.value)} 
                    placeholder={type === 'Fluid' ? 'e.g. 50ml' : type === 'Temperature' ? 'e.g. 38.5C' : 'e.g. Wet Nappy'}
                    className="w-full p-4 rounded-xl border border-slate-100 bg-slate-50 font-black text-lg"
                  />
               </div>
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Quick Note</label>
                  <input 
                    value={notes} 
                    onChange={e => setNotes(e.target.value)} 
                    placeholder="Refused half, lethargic etc..."
                    className="w-full p-4 rounded-xl border border-slate-100 bg-slate-50 text-sm font-bold"
                  />
               </div>
               <button onClick={handleAdd} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-xs hover:bg-rose-700 transition-all transform active:scale-95">Log Acute Event</button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3">
           <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm min-h-[400px]">
              <h3 className="text-xl font-black text-slate-800 mb-8">24-Hour Clinical Timeline</h3>
              <div className="space-y-4">
                 {entries.length > 0 ? entries.map(entry => (
                    <div key={entry.id} className="flex items-center gap-6 p-5 rounded-2xl border border-slate-50 bg-slate-50/20 group hover:border-rose-100 transition-all">
                       <span className="text-xs font-black text-slate-400 w-16">{entry.timestamp}</span>
                       <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">{icons[entry.type]}</div>
                       <div className="flex-1">
                          <p className="text-lg font-black text-slate-800">{entry.value} <span className="text-[10px] text-slate-400 uppercase tracking-widest ml-2">{entry.type}</span></p>
                          {entry.notes && <p className="text-xs font-bold text-slate-500 italic">"{entry.notes}"</p>}
                       </div>
                    </div>
                 )) : (
                    <div className="flex flex-col items-center justify-center py-20 opacity-30">
                       <span className="text-6xl mb-4">📉</span>
                       <p className="font-black text-xl">No acute events logged yet.</p>
                    </div>
                 )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

