          <p className="text-slate-500 text-xl font-medium max-w-xl">Clinical intelligence for complex pediatric care.</p>
        </div>

        <div className="flex gap-4">
           {childProfile && (
             <button onClick={() => onNavigate('acutelogs')} className="bg-rose-600 text-white px-8 py-5 rounded-[2.5rem] shadow-xl flex items-center gap-4 hover:bg-rose-700 transition-all animate-pulse">
