           )}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {[
          { id: 'symptoms', title: 'Symptom Guide', desc: 'AI Triage & Guidance', icon: '🌡️', color: 'bg-rose-50 text-rose-600' },
