const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [childProfile, setChildProfile] = useState<ChildProfile | undefined>(undefined);
  const [acuteLogs, setAcuteLogs] = useState<AcuteLogEntry[]>([]);
  const [vaccinations, setVaccinations] = useState<Vaccination[]>([]);
  const [growthRecords, setGrowthRecords] = useState<GrowthRecord[]>([]);
  const [latestWeight, setLatestWeight] = useState<number | undefined>(undefined);
  const [bondingNotes, setBondingNotes] = useState<string>('');
  const [pendingClinicalEvents, setPendingClinicalEvents] = useState<ClinicalEvent[]>([]);

  const handleAddAcuteLog = (entry: Omit<AcuteLogEntry, 'id'>) => {
    const newEntry = { ...entry, id: Math.random().toString(36).substr(2, 9) };
    setAcuteLogs(prev => [newEntry, ...prev]);
  };

  const handleWeightUpdate = (w: number) => {
    setLatestWeight(w);
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />;
      case 'acutelogs': return <AcuteTracker onLogEntry={handleAddAcuteLog} entries={acuteLogs} />;
      case 'profile': return <MedicalProfile prefilledHistory={{ acuteLogs, growthRecords, vaccinations }} attachmentData={{ caregiverObservations: bondingNotes }} pendingEvents={pendingClinicalEvents} />;
      case 'redbook': return (
        <RedBook 
          vaccinations={vaccinations} 
          growthRecords={growthRecords} 
          onVaccineUpdate={setVaccinations} 
          onGrowthUpdate={setGrowthRecords} 
          onWeightUpdate={handleWeightUpdate}
        />
      );
      case 'setup': return <ChildProfileSetup initialProfile={childProfile} onSave={setChildProfile} onCancel={() => setActiveView('dashboard')} />;
      case 'symptoms': return <SymptomChecker onSaveEvent={e => setPendingClinicalEvents(prev => [{...e, id: Math.random().toString(36)}, ...prev])} />;
      case 'growth': return <GrowthTracker onWeightUpdate={handleWeightUpdate} />;
      case 'dosage': return <DoseCalculator initialWeight={latestWeight} />;
      case 'milestones': return <MilestoneNavigator />;
      case 'bonding': return <BondingJournal observations={bondingNotes} onUpdate={setBondingNotes} childName={childProfile?.name} />;
      case 'vaccines': return <VaccineTracker />;
      default: return <Dashboard onNavigate={setActiveView} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Modality, Type } from "@google/genai";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSymptoms = async (description: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a supportive and professional pediatric clinical triage assistant. 
    Your goal is to provide guideline-based interpretation of childhood symptoms.

    PATIENT REPORT: "${description}"
    ${imageBase64 ? "VISUAL EVIDENCE: A photo of the symptom has been provided. Carefully examine the image for visible signs like rashes, inflammation, or physical signs of distress." : ""}

    BASE YOUR ANALYSIS AND ADVICE ON THESE AUTHORITATIVE SOURCES:
    1. Royal Children's Hospital (RCH) Melbourne Clinical Practice Guidelines
    2. Queensland Paediatric Clinical Guidelines
    3. Raising Children Network (https://raisingchildren.net.au/)
    4. Emerging Minds Australia (https://emergingminds.com.au/) for mental health aspects.

    Structure your response with:
    1. Potential Observations & Areas to Discuss with a Doctor: (Brief list based on guidelines and visual inspection)
    2. Standard Home Care Advice: (Supportive care aligned with RCH/Queensland guidelines)
    3. Triage Guide: (Green - Monitor at home, Yellow - Consult Doctor soon, Red - Seek Urgent Care immediately)
    4. Clinical Questions for Parent: (Standard triage questions mentioned in guidelines)

    IMPORTANT: Emphasize that this is NOT a medical diagnosis and is for informational purposes only. Use professional Australian clinical terminology.
  `;

  const contents: any = { parts: [{ text: prompt }] };

  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

