    instructions: "Standard Australian 4x4 Protocol: Give 4 puffs of blue reliever (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4x4. Call 000 if child is distressed, lips blue, or skin is sucking in at the ribs/neck. Follow up with GP within 24 hours even if improved.",
    triggers: "Viral colds, exercise, cigarette smoke, dust mites, pollens.",
    emergencyMeds: "Salbutamol (Ventolin/Asmol) 100mcg inhaler via spacer. Oral prednisolone as per specialist weight-based plan.",
    fluidRequirements: "Frequent small sips. Watch for difficulty drinking during high work of breathing.",
    emergencyContact: "Respiratory Specialist / GP Clinic / 000"
  },
  epilepsy: {
    instructions: "Stay calm and time the seizure. Protect from injury (move furniture). Recovery position once jerking stops. DO NOT restrain or put anything in mouth. Call 000 if: Seizure >5 mins, 2nd seizure occurs without regaining consciousness, or child is injured/breathing is labored.",
    triggers: "Fever, illness, fatigue, missed medication, flashing lights (if photosensitive).",
    emergencyMeds: "Buccal Midazolam (if prescribed): Administer specified dose between gums and cheek. Note exact time given.",
    fluidRequirements: "Hydrate only once fully awake and able to swallow safely.",
    emergencyContact: "Neurology Specialist / Epilepsy Nurse / 000"
  },
  metabolic: {
    instructions: "Commence Emergency Regimen (ER) immediately (SOS regimen) at the first sign of illness/fever. Give glucose polymer drinks at specified concentration. Seek ED REVIEW IMMEDIATELY if child: Refuses ER, vomits even once, becomes lethargic, or has unusual breath odor (ketosis).",
    triggers: "Fever >38°C, vomiting, diarrhea, prolonged fasting (>6 hours).",
    emergencyMeds: "Glucose polymer (Poly-Joule/Maxijul) as per metabolic specialist's protocol. Antipyretics for fever.",
    fluidRequirements: "Calculated high-carbohydrate feeds every 2 hours (including overnight).",
    emergencyContact: "On-call Metabolic Consultant / Clinic"
  },
  adrenal: {
    instructions: "COMMENCE STRESS DOSING for fever >38°C or significant illness. Double or Triple the oral Hydrocortisone dose every 6 hours as per clinic plan. IF VOMITING OCCURS: Administer IM Hydrocortisone (Solu-Cortef) immediately and call 000.",
    triggers: "Fever, trauma (e.g. broken bone), vomiting, major surgery.",
    emergencyMeds: "Oral Hydrocortisone tablets. Solu-Cortef IM Injection kit (Emergency Rescue).",
    fluidRequirements: "Oral rehydration solution (Hydralyte). Monitor for low blood pressure or extreme lethargy.",
    emergencyContact: "Endocrine Specialist / On-call Endocrinologist"
  },
  t1d: {
    instructions: "Check Blood Glucose and Ketones every 2 hours. Follow specific adjustment guide for insulin doses (Sick Day Rules). SEEK MEDICAL HELP IF: Persistent high ketones (>1.5 mmol/L), child is vomiting, or blood sugar remains high despite correction doses.",
    triggers: "Illness, infection, high stress, pump failure.",
    emergencyMeds: "Rapid-acting insulin for corrections. Glucagon Hypokit (for severe hypoglycemia).",
    fluidRequirements: "Fluids without sugar if BG high; fluids with sugar if BG trending low.",
    emergencyContact: "Diabetes Educator / On-call Diabetes Team"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ pendingEvents = [], onClearEvent, attachmentData, prefilledHistory }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: prefilledHistory?.pastMedicalHistory || '',
    surgicalHistory: '',
    currentMedications: prefilledHistory?.currentMedications || [],
    previousMedications: prefilledHistory?.previousMedications || [],
    allergies: prefilledHistory?.allergies || [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '', planPhoto: undefined },
    activeRecommendations: [],
    medicalReports: [],
    acuteLogs: [],
    conditions: []
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'gear' | 'reports' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const planPhotoInputRef = useRef<HTMLInputElement>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);

  // New item states
  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active' });
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', lastSeen: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', lastChanged: '', nextChangeDue: '' });
  const [newRecommendation, setNewRecommendation] = useState<Partial<Recommendation>>({ source: '', action: '', date: new Date().toISOString().split('T')[0] });

  useEffect(() => {
    if (prefilledHistory) {
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: prefilledHistory.pastMedicalHistory ?? prev.pastMedicalHistory,
        currentMedications: prefilledHistory.currentMedications ?? prev.currentMedications,
        previousMedications: prefilledHistory.previousMedications ?? prev.previousMedications,
        allergies: prefilledHistory.allergies ?? prev.allergies,
      }));
    }
  }, [prefilledHistory]);

  // Filtering Logic
  const filteredConditions = useMemo(() => {
    return (history.conditions || []).filter(c => 
      c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (c.notes || '').toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [history.conditions, searchTerm]);

  const filteredPastMeds = useMemo(() => {
    return (history.previousMedications || []).filter(m => 
      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.ceaseReason.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.indication.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [history.previousMedications, searchTerm]);

  const filteredRecommendations = useMemo(() => {
    return (history.activeRecommendations || []).filter(r => 
      r.action.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.source.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [history.activeRecommendations, searchTerm]);

  const filteredReports = useMemo(() => {
    return (history.medicalReports || []).filter(r => 
      r.specialist.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.summary.toLowerCase().includes(searchTerm.toLowerCase()) ||
      r.actionItems.some(item => item.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [history.medicalReports, searchTerm]);

  const filteredMeds = useMemo(() => {
    return history.currentMedications.filter(m => 
      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.indication.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [history.currentMedications, searchTerm]);

  const filteredEvents = useMemo(() => {
    return pendingEvents.filter(e => 
      e.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      e.source.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [pendingEvents, searchTerm]);

  const handleAddCondition = () => {
    if (newCondition.name) {
      const cond: Condition = { id: Math.random().toString(36).substr(2, 9), ...newCondition } as Condition;
      setHistory(prev => ({ ...prev, conditions: [...(prev.conditions || []), cond] }));
      setNewCondition({ name: '', status: 'Active' });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          setHistory(prev => ({
            ...prev,
            medicalReports: [...(prev.medicalReports || []), newReport]
          }));
          alert("Specialist letter analyzed and synthesized!");
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddMedication = () => {
    if (newMed.name) {
      const med: Medication = { id: Math.random().toString(36).substr(2, 9), ...newMed } as Medication;
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, med] }));
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
    }
  };

  const archiveMedication = (med: Medication) => {
    const reason = window.prompt(`Why was ${med.name} ceased?`, "Treatment course completed");
    if (reason !== null) {
      const ceased: PreviousMedication = {
        id: med.id,
        name: med.name,
        dose: med.dose,
        indication: med.indication,
        ceasedDate: new Date().toISOString().split('T')[0],
        ceaseReason: reason
      };
      setHistory(prev => ({
        ...prev,
        currentMedications: prev.currentMedications.filter(x => x.id !== med.id),
        previousMedications: [...prev.previousMedications, ceased]
      }));
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name && newSpecialist.specialty) {
      const spec: SpecialistContact = { id: Math.random().toString(36).substr(2, 9), ...newSpecialist } as SpecialistContact;
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, spec] }));
      setNewSpecialist({ name: '', specialty: '', lastSeen: '', nextReview: '' });
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type) {
      const dev: MedicalDevice = { id: Math.random().toString(36).substr(2, 9), ...newDevice } as MedicalDevice;
      setHistory(prev => ({ ...prev, devices: [...prev.devices, dev] }));
      setNewDevice({ type: '', model: '', lastChanged: '', nextChangeDue: '' });
    }
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setHistory(prev => ({
          ...prev,
          sickDayPlan: { ...prev.sickDayPlan, planPhoto: reader.result as string }
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const applySickDayTemplate = (key: keyof typeof SICK_DAY_TEMPLATES) => {
    const template = SICK_DAY_TEMPLATES[key];
    if (template && window.confirm(`Load the Australian ${key.toUpperCase()} clinical protocol? Current plan text will be overwritten.`)) {
      setHistory(prev => ({
        ...prev,
        sickDayPlan: {
          ...prev.sickDayPlan,
          instructions: template.instructions || '',
          emergencyMeds: template.emergencyMeds || '',
          fluidRequirements: template.fluidRequirements || '',
          triggers: template.triggers || '',
          emergencyContact: template.emergencyContact || ''
        }
      }));
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-12 pb-32">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Complex Care <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical ISBAR coordination for complex pediatric needs.</p>
        </div>

        {/* GLOBAL SEARCH / FILTER */}
        <div className="relative w-full lg:w-96 group">
           <span className="absolute left-5 top-1/2 -translate-y-1/2 text-xl opacity-40 group-focus-within:opacity-100 transition-opacity">🔍</span>
           <input 
            type="text" 
            placeholder="Filter conditions, meds, reports..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-14 pr-6 py-4 rounded-3xl bg-white border border-slate-200 shadow-sm outline-none focus:ring-2 focus:ring-indigo-500 font-bold italic"
           />
           {searchTerm && (
             <button onClick={() => setSearchTerm('')} className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500 font-black">×</button>
           )}
        </div>
      </header>

      {/* Navigation Tabs */}
      <div className="flex bg-white p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📋' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[130px] py-4 rounded-2xl font-black transition-all text-xs uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span className="text-xl">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[600px] animate-in slide-in-from-bottom-6 duration-500">

        {/* BASELINE HISTORY - ENHANCED SEARCHABLE CONDITIONS & PREVIOUS MEDS */}
        {activeTab === 'history' && (
          <div className="p-10 space-y-12">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">

              <div className="space-y-12">
                {/* Searchable Conditions */}
                <section className="space-y-6">
                  <header className="flex justify-between items-center px-2">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active Diagnoses</label>
                     {searchTerm && <span className="text-[9px] font-black text-indigo-500 bg-indigo-50 px-2 py-0.5 rounded-md uppercase">Filtering</span>}
                  </header>

                  <div className="bg-slate-50/50 p-6 rounded-[2.5rem] border border-slate-100 space-y-4">
                    <div className="flex gap-2">
                      <input 
                        value={newCondition.name} 
                        onChange={e => setNewCondition({...newCondition, name: e.target.value})}
                        placeholder="Add specific diagnosis..."
                        className="flex-1 p-3 rounded-xl border border-slate-200 text-sm font-bold shadow-inner"
                      />
                      <button onClick={handleAddCondition} className="bg-indigo-600 text-white px-4 rounded-xl font-black text-xs uppercase">Log</button>
                    </div>

                    <div className="space-y-2 max-h-[250px] overflow-y-auto no-scrollbar">
                      {filteredConditions.map(cond => (
                        <div key={cond.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex justify-between items-center group transition-all hover:border-indigo-100">
                          <div className="flex items-center gap-3">
                             <span className="w-2 h-2 rounded-full bg-emerald-500"></span>
                             <h5 className="font-black text-slate-800 text-sm">{cond.name}</h5>
                          </div>
                          <button onClick={() => setHistory(prev => ({...prev, conditions: prev.conditions?.filter(x => x.id !== cond.id)}))} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity">×</button>
                        </div>
                      ))}
                    </div>
                  </div>
                </section>

                {/* Previous Medications & Cease Reasons */}
                <section className="space-y-6">
                  <header className="flex justify-between items-center px-2">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Previous Medications (Historical)</label>
                  </header>

                  <div className="bg-rose-50/30 p-6 rounded-[2.5rem] border border-rose-100 space-y-3 max-h-[400px] overflow-y-auto no-scrollbar">
                    {filteredPastMeds.map(med => (
                      <div key={med.id} className="bg-white p-5 rounded-2xl border border-rose-50 shadow-sm space-y-2">
                         <div className="flex justify-between items-start">
                            <h5 className="font-black text-slate-800 text-sm">{med.name} <span className="text-[10px] text-rose-400 ml-1">{med.dose}</span></h5>
                            <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest">{med.ceasedDate}</span>
                         </div>
                         <div className="flex gap-2 items-start">
                            <span className="text-xs">🚫</span>
                            <div>
                               <p className="text-[10px] font-black text-rose-600 uppercase tracking-widest">Reason for Ceasing</p>
                               <p className="text-xs text-slate-600 font-bold italic">"{med.ceaseReason}"</p>
                            </div>
                         </div>
                      </div>
                    ))}
                    {filteredPastMeds.length === 0 && (
                      <p className="text-center py-6 text-xs text-slate-400 font-bold italic opacity-50">No historical medication records found.</p>
                    )}
                  </div>
                </section>
              </div>

              <div className="space-y-12">
                <section className="space-y-6">
                  <header className="flex justify-between items-center px-2">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Searchable Events & Recommendations</label>
                  </header>

                  <div className="bg-amber-50/50 p-6 rounded-[2.5rem] border border-amber-100 space-y-4">
                    <div className="flex gap-2">
                      <input 
                        value={newRecommendation.action} 
                        onChange={e => setNewRecommendation({...newRecommendation, action: e.target.value})}
                        placeholder="Add current specialist rec..."
                        className="flex-1 p-3 rounded-xl border border-amber-200 text-sm font-bold shadow-inner"
                      />
                      <button onClick={() => {
                          if (newRecommendation.action) {
                            setHistory(prev => ({...prev, activeRecommendations: [...(prev.activeRecommendations || []), { id: Math.random().toString(), ...newRecommendation } as any]}));
                            setNewRecommendation({ ...newRecommendation, action: '' });
                          }
                      }} className="bg-amber-500 text-white px-4 rounded-xl font-black text-xs uppercase">Add</button>
                    </div>

                    <div className="space-y-3 max-h-[500px] overflow-y-auto no-scrollbar">
                      {filteredRecommendations.map(rec => (
                        <div key={rec.id} className="bg-white p-4 rounded-2xl border border-amber-100 text-xs font-bold flex justify-between items-start group shadow-sm transition-all hover:shadow-md">
                          <div className="flex gap-3">
                             <span className="text-amber-400 mt-1">✨</span>
                             <span className="text-slate-700 leading-relaxed">{rec.action}</span>
                          </div>
                          <button onClick={() => setHistory(prev => ({...prev, activeRecommendations: prev.activeRecommendations?.filter(x => x.id !== rec.id)}))} className="text-rose-400 opacity-0 group-hover:opacity-100">×</button>
                        </div>
                      ))}

                      {filteredEvents.map(event => (
                        <div key={event.id} className="bg-indigo-50 p-4 rounded-2xl border border-indigo-100 text-xs font-bold flex flex-col gap-2 relative group shadow-sm">
                           <div className="flex justify-between">
                              <span className="text-[8px] font-black uppercase text-indigo-400 tracking-widest">{event.source} • {event.date}</span>
                              <span className={`w-2 h-2 rounded-full ${event.severity === 'High' ? 'bg-rose-500' : 'bg-amber-500'}`}></span>
                           </div>
                           <p className="text-indigo-900 italic">"{event.description}"</p>
                        </div>
                      ))}

                      {searchTerm && filteredRecommendations.length === 0 && filteredEvents.length === 0 && (
                        <div className="py-20 text-center space-y-2 opacity-40">
                           <span className="text-4xl">🔎</span>
                           <p className="text-xs font-black uppercase tracking-widest">No matching history items</p>
                        </div>
                      )}
                    </div>
                  </div>
                </section>

                <section className="space-y-6">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Longitudinal Narrative Notes</label>
                  <textarea 
                    value={history.pastMedicalHistory}
                    onChange={e => setHistory({...history, pastMedicalHistory: e.target.value})}
                    className="w-full h-44 p-8 rounded-[3rem] border border-slate-100 bg-slate-50/20 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500"
                    placeholder="General developmental and clinical journey overview..."
                  />
                </section>
              </div>
            </div>
          </div>
        )}

        {/* MEDICATION MANAGEMENT TAB */}
        {activeTab === 'meds' && (
          <div className="p-10 space-y-12">
            <section className="space-y-8">
               <div className="bg-indigo-50 p-8 rounded-[3rem] border border-indigo-100">
                  <h4 className="font-black text-indigo-900 mb-6 flex items-center gap-2 uppercase tracking-widest text-sm">💊 Add Regular Medication</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    <input placeholder="Drug Name" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input placeholder="Dose (e.g. 5mL)" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input placeholder="Timing (e.g. BD/Noon)" value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input placeholder="Indication" value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input type="date" value={newMed.startDate} onChange={e => setNewMed({...newMed, startDate: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-xs font-black uppercase" />
                    <button onClick={handleAddMedication} className="bg-indigo-600 text-white p-4 rounded-xl font-black text-xs uppercase shadow-lg hover:bg-indigo-700 transition-all">Add to Regimen</button>
                  </div>
               </div>

               <div className="space-y-4">
                  <h3 className="text-xl font-black text-slate-800 ml-4 flex items-center gap-2">
                    Active Regimen 
                    {searchTerm && <span className="text-[10px] font-black text-indigo-600 uppercase ml-2 bg-indigo-50 px-2 py-1 rounded-lg">Filtering: {searchTerm}</span>}
                  </h3>
                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                    {filteredMeds.map(m => (
                      <div key={m.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-all">
                         <div className="flex gap-4 items-center">
                            <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-2xl shrink-0">💧</div>
                            <div>
                               <h5 className="font-black text-slate-800">{m.name} <span className="text-xs text-indigo-600 ml-1">{m.dose}</span></h5>
                               <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{m.instructions} • For: {m.indication || 'General'}</p>
                            </div>
                         </div>
                         <button onClick={() => archiveMedication(m)} className="text-[10px] font-black text-rose-500 uppercase hover:underline opacity-0 group-hover:opacity-100 transition-opacity">Cease Med</button>
                      </div>
                    ))}
                  </div>
               </div>
            </section>

            <section className="space-y-6 pt-10 border-t border-slate-50">
               <h3 className="text-xl font-black text-slate-400 ml-4 italic text-sm uppercase tracking-widest">Historical Records (Ceased)</h3>
               <div className="space-y-3">
                  {history.previousMedications.map(m => (
                    <div key={m.id} className="bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between gap-6 opacity-70">
                       <div className="flex gap-4 items-center">
                          <div className="w-10 h-10 bg-slate-100 text-slate-400 rounded-xl flex items-center justify-center text-xl shrink-0">📜</div>
                          <div>
