          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
