                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    <input placeholder="Drug Name" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input placeholder="Dose (e.g. 5mL)" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input placeholder="Timing (e.g. BD/Noon)" value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input placeholder="Indication" value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-sm font-bold" />
                    <input type="date" value={newMed.startDate} onChange={e => setNewMed({...newMed, startDate: e.target.value})} className="p-4 rounded-xl border-none shadow-inner text-xs font-black uppercase" />
                    <button onClick={handleAddMedication} className="bg-indigo-600 text-white p-4 rounded-xl font-black text-xs uppercase shadow-lg hover:bg-indigo-700 transition-all">Add to Regimen</button>
                  </div>
