               <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                  {filteredPastMeds.map(med => (
                    <div key={med.id} className="bg-rose-50/20 p-6 rounded-[2.5rem] border border-rose-100 shadow-sm space-y-4 opacity-80 group hover:opacity-100 transition-opacity">
                       <div className="flex justify-between items-start">
                          <div className="flex gap-4 items-center">
                             <div className="w-10 h-10 bg-white text-slate-300 rounded-xl flex items-center justify-center text-xl shrink-0 border border-slate-100">📜</div>
