        {activeTab === 'reports' && (
          <div className="p-10 space-y-10">
            <div className="bg-indigo-50 p-10 rounded-[3rem] border border-indigo-100 flex flex-col md:flex-row items-center justify-between gap-6 relative overflow-hidden">
               <div className="absolute top-0 right-0 p-12 text-8xl opacity-5 pointer-events-none">✨</div>
               <div className="space-y-2 text-center md:text-left">
                  <h4 className="text-2xl font-black text-indigo-950 tracking-tight flex items-center gap-2">
                     <span className="text-3xl">🪄</span> Letter Insight AI
                  </h4>
                  <p className="text-indigo-800 font-bold opacity-70 italic text-sm">Convert complex specialist letters into plain-English action items.</p>
               </div>
               <input type="file" ref={reportInputRef} className="hidden" accept="image/*" onChange={handleReportUpload} />
               <button 
                  onClick={() => reportInputRef.current?.click()}
                  disabled={reportLoading}
                  className="px-10 py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-[10px] hover:bg-indigo-700 transition-all flex items-center gap-3"
               >
                  {reportLoading ? (
                    <><div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div> Processing...</>
