import React, { useState, useMemo } from 'react';
import { HealthCheck, Vaccination, GrowthRecord } from '../types';
import { VaccineTracker } from './VaccineTracker';
import { GrowthTracker } from './GrowthTracker';

interface RedBookProps {
  vaccinations: Vaccination[];
  growthRecords: GrowthRecord[];
  onVaccineUpdate: (vaccines: Vaccination[]) => void;
  onGrowthUpdate: (records: GrowthRecord[]) => void;
  onWeightUpdate?: (weight: number) => void;
}

const INITIAL_CHECKS: HealthCheck[] = [
  { id: '1', ageMilestone: 'Birth', completed: false, notes: '' },
  { id: '2', ageMilestone: '1-4 Weeks', completed: false, notes: '' },
  { id: '3', ageMilestone: '6-8 Weeks', completed: false, notes: '' },
  { id: '4', ageMilestone: '4 Months', completed: false, notes: '' },
  { id: '5', ageMilestone: '6 Months', completed: false, notes: '' },
  { id: '6', ageMilestone: '12 Months', completed: false, notes: '' },
  { id: '7', ageMilestone: '18 Months', completed: false, notes: '' },
  { id: '8', ageMilestone: '2 Years', completed: false, notes: '' },
  { id: '9', ageMilestone: '3.5-4 Years', completed: false, notes: '' },
];

export const RedBook: React.FC<RedBookProps> = ({ 
  vaccinations, 
  growthRecords, 
  onVaccineUpdate, 
  onGrowthUpdate,
  onWeightUpdate 
}) => {
  const [checks, setChecks] = useState<HealthCheck[]>(INITIAL_CHECKS);
  const [activeTab, setActiveTab] = useState<'checks' | 'vax' | 'growth'>('checks');
  const [activeCheck, setActiveCheck] = useState<string | null>(null);

  const alerts = useMemo(() => {
    const overdueVax = vaccinations.filter(v => v.status === 'pending' && new Date() > new Date(v.dueDate));
    const pendingChecks = checks.filter(c => !c.completed);

    // Growth faltering check: if weight dropped or plateaued between last two records
    let growthAlert = false;
    let growthSeverity: 'Low' | 'High' = 'Low';
    if (growthRecords.length >= 2) {
      const last = growthRecords[growthRecords.length - 1];
      const prev = growthRecords[growthRecords.length - 2];
      if (last.weight < prev.weight) {
        growthAlert = true;
        growthSeverity = 'High';
      } else if (last.weight === prev.weight && last.age > prev.age) {
        growthAlert = true; // Plateau
        growthSeverity = 'Low';
      }
    }

    return { overdueVax, pendingChecks, growthAlert, growthSeverity };
  }, [vaccinations, checks, growthRecords]);

  const toggleCheck = (id: string) => {
    setChecks(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const updateNotes = (id: string, notes: string) => {
    setChecks(prev => prev.map(c => c.id === id ? { ...c, notes } : c));
  };

  const hasAlerts = alerts.overdueVax.length > 0 || alerts.growthAlert;

  return (
    <div className="space-y-8 pb-32">
      {/* HIGH VISIBILITY ALERT BANNER */}
      {hasAlerts && (
        <div className="bg-white rounded-[3rem] border-2 border-rose-500 shadow-[0_20px_50px_-12px_rgba(244,63,94,0.3)] overflow-hidden animate-in slide-in-from-top-10 duration-700">
          <div className="bg-rose-600 px-10 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-2xl animate-bounce">🚨</span>
              <h3 className="text-white font-black text-sm uppercase tracking-[0.2em]">Urgent Health Notifications</h3>
            </div>
            <span className="bg-white/20 text-white px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">
              Action Required
            </span>
          </div>

          <div className="p-10 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {alerts.overdueVax.length > 0 && (
                <div className="bg-rose-50 p-6 rounded-[2rem] border border-rose-100 flex items-start gap-5 group transition-all hover:bg-rose-100/50">
                  <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-3xl shadow-sm border border-rose-200">💉</div>
                  <div className="space-y-2 flex-1">
                    <p className="font-black text-rose-900 text-lg leading-tight">
                      {alerts.overdueVax.length} Missed Immunisations
                    </p>
                    <p className="text-rose-700/70 text-xs font-bold italic leading-relaxed">
                      Missing standard vaccinations increases risk of preventable disease. Please consult your GP clinic soon.
                    </p>
                    <button 
                      onClick={() => setActiveTab('vax')} 
                      className="mt-2 bg-rose-600 text-white px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg hover:bg-rose-700 transition-all flex items-center gap-2"
                    >
                      Update Records <span>→</span>
                    </button>
                  </div>
                </div>
              )}

              {alerts.growthAlert && (
                <div className={`p-6 rounded-[2rem] border flex items-start gap-5 group transition-all ${
                  alerts.growthSeverity === 'High' 
                    ? 'bg-rose-50 border-rose-100' 
                    : 'bg-amber-50 border-amber-100'
                }`}>
                  <div className={`w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-3xl shadow-sm border ${
                    alerts.growthSeverity === 'High' ? 'border-rose-200' : 'border-amber-200'
                  }`}>
                    {alerts.growthSeverity === 'High' ? '📉' : '⚖️'}
                  </div>
                  <div className="space-y-2 flex-1">
                    <p className={`font-black text-lg leading-tight ${
                      alerts.growthSeverity === 'High' ? 'text-rose-900' : 'text-amber-900'
                    }`}>
                      {alerts.growthSeverity === 'High' ? 'Weight Faltering Detected' : 'Growth Plateau Observed'}
                    </p>
                    <p className={`text-xs font-bold italic leading-relaxed ${
                      alerts.growthSeverity === 'High' ? 'text-rose-700/70' : 'text-amber-700/70'
                    }`}>
                      {alerts.growthSeverity === 'High' 
                        ? 'Weight loss between measurements is a clinical red flag. Review with a Pediatrician or GP today.'
                        : 'Weight has not increased despite increasing age. Monitor feeding and discuss at next review.'}
                    </p>
                    <button 
                      onClick={() => setActiveTab('growth')} 
                      className={`mt-2 text-white px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg transition-all flex items-center gap-2 ${
                        alerts.growthSeverity === 'High' ? 'bg-rose-600 hover:bg-rose-700' : 'bg-amber-600 hover:bg-amber-700'
                      }`}
                    >
                      Review Growth Trajectory <span>→</span>
                    </button>
                  </div>
                </div>
              )}
            </div>

            <div className="pt-4 border-t border-slate-100 flex items-center gap-3">
              <span className="text-slate-400 text-[10px] font-black uppercase tracking-[0.3em]">Smart Sync:</span>
              <p className="text-slate-500 text-[10px] font-bold italic">These alerts are automatically included in the <strong className="text-indigo-600">Clinical ISBAR Handover</strong> generated in the Medical Profile tab.</p>
            </div>
          </div>
        </div>
      )}

      <header className="flex flex-col md:flex-row justify-between items-start gap-6 pt-4">
        <div className="flex items-center gap-5">
          <div className="w-16 h-20 bg-rose-600 rounded-xl flex items-center justify-center text-white font-black text-center p-2 shadow-2xl leading-tight rotate-[-5deg] border-2 border-white">
            MY HEALTH RECORD
          </div>
          <div>
            <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">Digital <span className="text-rose-600">Red Book</span></h2>
            <p className="text-slate-500 font-medium italic">Standardised Child Health & Development Record</p>
          </div>
        </div>
      </header>

      {/* NAVIGATION TABS */}
      <div className="flex bg-white p-1.5 rounded-[2.5rem] border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'checks', label: 'Health Checks', icon: '🗓️' },
          { id: 'vax', label: 'Immunisation', icon: '💉' },
          { id: 'growth', label: 'Growth Chart', icon: '📉' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[140px] py-4 rounded-3xl font-black transition-all text-xs uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-rose-600 text-white shadow-xl scale-105 z-10' : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            <span className="text-xl">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl overflow-hidden min-h-[600px] animate-in zoom-in-95 duration-500">

        {/* HEALTH CHECKS TIMELINE */}
        {activeTab === 'checks' && (
          <div className="p-12 space-y-10">
            <h3 className="text-2xl font-black text-slate-800 flex items-center gap-3">
              <span className="text-rose-500 text-3xl">📅</span> Scheduled Assessments
            </h3>
            <div className="space-y-6 relative before:absolute before:left-6 before:top-4 before:bottom-4 before:w-1 before:bg-slate-100">
              {checks.map((check) => (
                <div key={check.id} className="relative pl-16">
                  <button 
                    onClick={() => toggleCheck(check.id)}
                    className={`absolute left-0 w-12 h-12 rounded-2xl border-4 flex items-center justify-center transition-all z-10 shadow-lg ${
                      check.completed 
                        ? 'bg-rose-600 border-rose-100 text-white' 
                        : 'bg-white border-slate-50 text-slate-200 hover:border-rose-100'
                    }`}
                  >
                    {check.completed ? '✓' : ''}
                  </button>
                  <div 
                    className={`p-6 rounded-[2.5rem] border-2 transition-all cursor-pointer ${
                      activeCheck === check.id ? 'border-rose-200 bg-rose-50/50 shadow-inner' : 'border-slate-50 bg-white hover:border-slate-100'
                    }`}
                    onClick={() => setActiveCheck(activeCheck === check.id ? null : check.id)}
                  >
                    <div className="flex justify-between items-center">
                      <h4 className="font-black text-xl text-slate-800 tracking-tight">{check.ageMilestone} Check</h4>
                      <div className="flex items-center gap-2">
                        {check.completed ? (
                          <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full uppercase">Record Complete</span>
                        ) : (
                          <span className="text-[10px] font-black text-slate-400 bg-slate-50 px-3 py-1 rounded-full uppercase">Pending Nurse</span>
                        )}
                      </div>
                    </div>
                    {activeCheck === check.id && (
                      <div className="mt-6 space-y-4 animate-in fade-in slide-in-from-top-4">
                        <textarea 
                          className="w-full h-32 p-6 rounded-3xl border border-slate-100 bg-white text-sm font-bold italic outline-none focus:ring-2 focus:ring-rose-500 shadow-inner"
                          placeholder="Nurse/GP Clinical Observations (e.g. sleep cycles, feeding, physical findings)..."
                          value={check.notes}
                          onChange={(e) => updateNotes(check.id, e.target.value)}
                        />
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* INTEGRATED VACCINE TRACKER */}
        {activeTab === 'vax' && (
          <div className="p-12">
             <VaccineTracker />
          </div>
        )}

        {/* INTEGRATED GROWTH TRACKER */}
        {activeTab === 'growth' && (
          <div className="p-12">
             <GrowthTracker onWeightUpdate={onWeightUpdate} />
          </div>
        )}

      </div>
    </div>
  );
};

