import { BondingJournal } from './components/BondingJournal';
import { AcuteTracker } from './components/AcuteTracker';

const Dashboard: React.FC<{ 
  onNavigate: (v: ViewType) => void; 
  latestWeight?: number;
  childProfile?: ChildProfile;
}> = ({ onNavigate, latestWeight, childProfile }) => {

  const childAge = useMemo(() => {
    if (!childProfile?.dob) return null;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let age = now.getFullYear() - birth.getFullYear();
    const m = now.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) age--;
    return age === 0 ? "Under 1 year" : `${age} years old`;
  }, [childProfile]);

  return (
    <div className="space-y-16 animate-in fade-in duration-700 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start gap-6 border-b border-slate-100 pb-10">
        <div className="space-y-2">
          <h1 className="text-5xl font-black text-slate-800 tracking-tighter italic">PediPulse <span className="text-indigo-600">Hub</span></h1>
          <p className="text-slate-500 text-xl font-medium max-w-xl">Clinical intelligence for complex pediatric care.</p>
        </div>

        <div className="flex gap-4">
           {childProfile && (
             <button onClick={() => onNavigate('acutelogs')} className="bg-rose-600 text-white px-8 py-5 rounded-[2.5rem] shadow-xl flex items-center gap-4 hover:bg-rose-700 transition-all animate-pulse">
                <span className="text-2xl">🚨</span>
                <div className="text-left">
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Active Illness</p>
                   <p className="text-xl font-black">Sick Day Log</p>
                </div>
             </button>
           )}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {[
          { id: 'symptoms', title: 'Symptom Guide', desc: 'AI Triage & Guidance', icon: '🌡️', color: 'bg-rose-50 text-rose-600' },
          { id: 'dosage', title: 'Safe Dosing', desc: 'Weight-based OTC', icon: '💊', color: 'bg-indigo-50 text-indigo-600' },
          { id: 'profile', title: 'Medical Hub', desc: 'ISBAR & Letters', icon: '📋', color: 'bg-slate-100 text-slate-700' },
          { id: 'redbook', title: 'Digital Red Book', desc: 'Unified Health Record', icon: '📕', color: 'bg-rose-50 text-rose-600' },
          { id: 'milestones', title: 'Milestones', desc: 'Development Monitor', icon: '✨', color: 'bg-purple-50 text-purple-600' },
        ].map(card => (
          <button key={card.id} onClick={() => onNavigate(card.id as ViewType)} className="group bg-white p-8 rounded-[3rem] border border-slate-100 text-left hover:shadow-2xl transition-all">
            <div className={`w-16 h-16 ${card.color} rounded-2xl flex items-center justify-center text-3xl mb-6`}>{card.icon}</div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">{card.title}</h3>
            <p className="text-slate-500 text-sm font-medium">{card.desc}</p>
          </button>
        ))}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');
  const [childProfile, setChildProfile] = useState<ChildProfile | undefined>(undefined);
  const [acuteLogs, setAcuteLogs] = useState<AcuteLogEntry[]>([]);
  const [vaccinations, setVaccinations] = useState<Vaccination[]>([]);
  const [growthRecords, setGrowthRecords] = useState<GrowthRecord[]>([]);
  const [milestones, setMilestones] = useState<Milestone[]>([]);
  const [latestWeight, setLatestWeight] = useState<number | undefined>(undefined);
  const [bondingNotes, setBondingNotes] = useState<string>('');
  const [pendingClinicalEvents, setPendingClinicalEvents] = useState<ClinicalEvent[]>([]);

  const handleAddAcuteLog = (entry: Omit<AcuteLogEntry, 'id'>) => {
    const newEntry = { ...entry, id: Math.random().toString(36).substr(2, 9) };
    setAcuteLogs(prev => [newEntry, ...prev]);
  };

  const handleWeightUpdate = (w: number) => {
    setLatestWeight(w);
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />;
      case 'acutelogs': return <AcuteTracker onLogEntry={handleAddAcuteLog} entries={acuteLogs} />;
      case 'profile': return <MedicalProfile prefilledHistory={{ acuteLogs, growthRecords, vaccinations, milestones }} attachmentData={{ caregiverObservations: bondingNotes }} pendingEvents={pendingClinicalEvents} />;
      case 'redbook': return (
        <RedBook 
          vaccinations={vaccinations} 
          growthRecords={growthRecords} 
          onVaccineUpdate={setVaccinations} 
          onGrowthUpdate={setGrowthRecords} 
          onWeightUpdate={handleWeightUpdate}
        />
      );
      case 'setup': return <ChildProfileSetup initialProfile={childProfile} onSave={setChildProfile} onCancel={() => setActiveView('dashboard')} />;
      case 'symptoms': return <SymptomChecker onSaveEvent={e => setPendingClinicalEvents(prev => [{...e, id: Math.random().toString(36)}, ...prev])} />;
      case 'growth': return <GrowthTracker onWeightUpdate={handleWeightUpdate} />;
      case 'dosage': return <DoseCalculator initialWeight={latestWeight} />;
      case 'milestones': return <MilestoneNavigator onLogRedFlag={(desc) => {
        setPendingClinicalEvents(prev => [{ id: Math.random().toString(36), source: 'Development', description: desc, date: new Date().toLocaleDateString(), severity: 'Medium' }, ...prev]);
      }} />;
      case 'bonding': return <BondingJournal observations={bondingNotes} onUpdate={setBondingNotes} childName={childProfile?.name} />;
      case 'vaccines': return <VaccineTracker onSaveEvent={e => setPendingClinicalEvents(prev => [{...e, id: Math.random().toString(36)}, ...prev])} />;
      default: return <Dashboard onNavigate={setActiveView} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      {children}
    </Layout>
  );
};

export default App;

