export const calculateDosage = async (weightKg: number, medication: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-pro-preview';

  const prompt = `
    Provide informational weight-based pediatric dosage for the over-the-counter (OTC) medication "${medication}" for a child weighing ${weightKg}kg.

    STRICTLY CONSULT THE FOLLOWING FOR CALCULATIONS:
    - Royal Children's Hospital (RCH) Melbourne Paediatric Pharmacopoeia / Clinical Practice Guidelines
    - Queensland Paediatric Clinical Guidelines

    YOUR TASK:
    1. Calculate the standard single dose (mg) based on ${weightKg}kg.
    2. Provide the frequency (e.g., "Every 4-6 hours, max 4 doses in 24h").
    3. Calculate the absolute maximum cumulative dose for 24 hours.
    4. List critical cautionary notes specific to this OTC medicine (e.g., liver safety for Paracetamol, stomach irritation for Ibuprofen, age restrictions).
    5. Mention concentration awareness (e.g., 100mg/5mL vs 200mg/5mL).

    Return the result in clear JSON format.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          medicationName: { type: Type.STRING },
          recommendedDose: { type: Type.STRING },
          frequency: { type: Type.STRING },
          maxDose24h: { type: Type.STRING },
          cautionaryNotes: { type: Type.STRING }
        },
        required: ["medicationName", "recommendedDose", "frequency", "maxDose24h", "cautionaryNotes"]
