    emergencyMeds: "Rapid-acting insulin for corrections. Glucagon Hypokit (for severe hypoglycemia).",
    fluidRequirements: "Fluids without sugar if BG high; fluids with sugar if BG trending low.",
    emergencyContact: "Diabetes Educator / On-call Diabetes Team"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ pendingEvents = [], onClearEvent, attachmentData, prefilledHistory }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: prefilledHistory?.pastMedicalHistory || '',
    surgicalHistory: '',
    currentMedications: prefilledHistory?.currentMedications || [],
    previousMedications: prefilledHistory?.previousMedications || [],
    allergies: prefilledHistory?.allergies || [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '', planPhoto: undefined },
    activeRecommendations: [],
    medicalReports: [],
    acuteLogs: [],
    conditions: []
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'gear' | 'reports' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const planPhotoInputRef = useRef<HTMLInputElement>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);

  // New item states
  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active' });
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', goals: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', lastChanged: '', nextChangeDue: '' });

  useEffect(() => {
    if (prefilledHistory) {
      setHistory(prev => ({
        ...prev,
        pastMedicalHistory: prefilledHistory.pastMedicalHistory ?? prev.pastMedicalHistory,
        currentMedications: prefilledHistory.currentMedications ?? prev.currentMedications,
        previousMedications: prefilledHistory.previousMedications ?? prev.previousMedications,
        allergies: prefilledHistory.allergies ?? prev.allergies,
        specialists: prefilledHistory.specialists ?? prev.specialists,
      }));
    }
  }, [prefilledHistory]);

  const medicalSpecialists = useMemo(() => history.specialists.filter(s => s.category === 'Medical'), [history.specialists]);
  const alliedHealthTeam = useMemo(() => history.specialists.filter(s => s.category === 'Allied Health'), [history.specialists]);
  const supportNetwork = useMemo(() => history.specialists.filter(s => s.category === 'Support'), [history.specialists]);

  const handleAddSpecialist = () => {
    if (newSpecialist.name && newSpecialist.specialty) {
      const spec: SpecialistContact = { id: Math.random().toString(36).substr(2, 9), ...newSpecialist } as SpecialistContact;
      setHistory(prev => ({ ...prev, specialists: [...prev.specialists, spec] }));
      setNewSpecialist({ name: '', specialty: '', category: 'Medical', goals: '' });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          setHistory(prev => ({
            ...prev,
            medicalReports: [...(prev.medicalReports || []), newReport]
          }));
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddMedication = () => {
    if (newMed.name) {
      const med: Medication = { id: Math.random().toString(36).substr(2, 9), ...newMed } as Medication;
      setHistory(prev => ({ ...prev, currentMedications: [...prev.currentMedications, med] }));
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
    }
  };

  const archiveMedication = (med: Medication) => {
    const reason = window.prompt(`Why was ${med.name} ceased?`, "Treatment course completed");
    if (reason !== null) {
      const ceased: PreviousMedication = {
        id: med.id,
        name: med.name,
        dose: med.dose,
        indication: med.indication,
        ceasedDate: new Date().toISOString().split('T')[0],
        ceaseReason: reason
      };
      setHistory(prev => ({
        ...prev,
        currentMedications: prev.currentMedications.filter(x => x.id !== med.id),
        previousMedications: [ceased, ...prev.previousMedications]
      }));
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type) {
      const dev: MedicalDevice = { id: Math.random().toString(36).substr(2, 9), ...newDevice } as MedicalDevice;
      setHistory(prev => ({ ...prev, devices: [...prev.devices, dev] }));
      setNewDevice({ type: '', model: '', lastChanged: '', nextChangeDue: '' });
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-12 pb-32">
      {/* PROFESSIONAL CLINICAL HEADER */}
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 border-b border-slate-100 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Medical <span className="text-indigo-600">Care Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Multi-disciplinary clinical coordination (MDT).</p>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
          <div className="relative flex-1 lg:w-80 group">
             <span className="absolute left-4 top-1/2 -translate-y-1/2 text-lg opacity-40">🔍</span>
             <input 
              type="text" 
              placeholder="Filter profile data..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-11 pr-4 py-3 rounded-2xl bg-white border border-slate-200 shadow-sm outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
             />
          </div>
          <button 
            onClick={handleGenerateHandover}
            disabled={loading}
            className="px-6 py-3 bg-indigo-600 text-white font-black rounded-2xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2 text-xs uppercase tracking-widest"
          >
            {loading ? 'Synthesizing...' : 'Generate ISBAR'}
          </button>
        </div>
      </header>

      {/* CLINICAL SUMMARY DASHBOARD */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {[
          { label: 'Active Meds', value: history.currentMedications.length, icon: '💊', color: 'text-indigo-600 bg-indigo-50' },
          { label: 'Allergies', value: history.allergies.length, icon: '🚫', color: 'text-rose-600 bg-rose-50' },
          { label: 'Allied Health', value: alliedHealthTeam.length, icon: '🫂', color: 'text-teal-600 bg-teal-50' },
          { label: 'Conditions', value: (history.conditions || []).length, icon: '📋', color: 'text-emerald-600 bg-emerald-50' },
          { label: 'Specialists', value: medicalSpecialists.length, icon: '👨‍⚕️', color: 'text-amber-600 bg-amber-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl ${stat.color}`}>
              {stat.icon}
            </div>
            <div className="text-2xl font-black text-slate-800">{stat.value}</div>
            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Navigation Tabs */}
      <div className="flex bg-slate-100/50 p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📜' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Reports', icon: '✉️' },
          { id: 'mdt', label: 'Care Team (MDT)', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Emergency', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-indigo-700 shadow-md border border-slate-200' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <span className="text-lg">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px] animate-in slide-in-from-bottom-6 duration-500">

        {/* MDT Team Tab - REDESIGNED FOR ALLIED HEALTH */}
        {activeTab === 'mdt' && (
          <div className="p-8 md:p-12 space-y-12">
            <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-200">
              <h4 className="font-black text-slate-800 mb-6 text-[10px] uppercase tracking-widest flex items-center gap-2">
                <span>➕</span> Expand Multi-Disciplinary Team
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <input placeholder="Provider Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="p-4 rounded-xl border border-slate-200 shadow-sm text-sm font-bold" />
                <input placeholder="Specialty (e.g. OT, Cardio)" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="p-4 rounded-xl border border-slate-200 shadow-sm text-sm font-bold" />
                <select 
                  value={newSpecialist.category} 
                  onChange={e => setNewSpecialist({...newSpecialist, category: e.target.value as any})}
                  className="p-4 rounded-xl border border-slate-200 shadow-sm text-sm font-bold bg-white"
                >
                  <option value="Medical">Medical Specialist</option>
                  <option value="Allied Health">Allied Health (OT/PT/Speech)</option>
                  <option value="Support">Support (Coordinator/SW)</option>
                </select>
                <button onClick={handleAddSpecialist} className="bg-indigo-600 text-white p-4 rounded-xl font-black text-xs uppercase shadow-lg hover:bg-indigo-700">Add to Team</button>
                {newSpecialist.category === 'Allied Health' && (
                  <div className="lg:col-span-4 mt-2">
                    <input 
                      placeholder="Current Therapy Goal (e.g. improve fine motor, social communication)..." 
                      value={newSpecialist.goals} 
                      onChange={e => setNewSpecialist({...newSpecialist, goals: e.target.value})} 
                      className="w-full p-4 rounded-xl border border-teal-100 bg-teal-50/30 text-sm font-bold italic"
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="space-y-12">
              {/* Medical Specialists Group */}
              {medicalSpecialists.length > 0 && (
                <section className="space-y-6">
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2">Medical Specialists</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {medicalSpecialists.map(s => (
                      <div key={s.id} className="bg-white p-8 rounded-[2.5rem] border border-amber-50 shadow-sm flex flex-col items-center text-center space-y-3 relative group">
                        <button onClick={() => setHistory(prev => ({...prev, specialists: prev.specialists.filter(x => x.id !== s.id)}))} className="absolute top-4 right-4 text-slate-200 hover:text-rose-500 font-black opacity-0 group-hover:opacity-100 transition-opacity">×</button>
                        <div className="w-16 h-16 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner mb-2">👨‍⚕️</div>
                        <h5 className="text-lg font-black text-slate-800 tracking-tight leading-tight">{s.name}</h5>
                        <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest">{s.specialty}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {/* Allied Health Group */}
              {alliedHealthTeam.length > 0 && (
                <section className="space-y-6">
                  <h3 className="text-sm font-black text-teal-600 uppercase tracking-widest border-b border-teal-50 pb-2">Allied Health Team</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {alliedHealthTeam.map(s => (
                      <div key={s.id} className="bg-teal-50/30 p-8 rounded-[2.5rem] border border-teal-100 shadow-sm flex flex-col space-y-4 relative group">
                        <button onClick={() => setHistory(prev => ({...prev, specialists: prev.specialists.filter(x => x.id !== s.id)}))} className="absolute top-4 right-4 text-slate-200 hover:text-rose-500 font-black opacity-0 group-hover:opacity-100 transition-opacity">×</button>
                        <div className="flex items-center gap-4">
                           <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-3xl shadow-sm border border-teal-100">🫂</div>
                           <div>
                              <h5 className="text-lg font-black text-slate-800 tracking-tight leading-tight">{s.name}</h5>
                              <p className="text-[10px] font-black text-teal-600 uppercase tracking-widest">{s.specialty}</p>
                           </div>
                        </div>
                        {s.goals && (
                          <div className="bg-white p-4 rounded-2xl border border-teal-50 mt-2">
                             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Therapy Goal</p>
                             <p className="text-xs font-bold text-teal-900 italic leading-relaxed">"{s.goals}"</p>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {/* Support Network Group */}
              {supportNetwork.length > 0 && (
                <section className="space-y-6">
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2">Support & Coordination</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {supportNetwork.map(s => (
                      <div key={s.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-4 relative group">
                        <button onClick={() => setHistory(prev => ({...prev, specialists: prev.specialists.filter(x => x.id !== s.id)}))} className="absolute top-2 right-4 text-slate-200 hover:text-rose-500 font-black opacity-0 group-hover:opacity-100">×</button>
                        <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-xl">🛡️</div>
                        <div>
                          <h5 className="font-black text-slate-800 text-sm leading-tight">{s.name}</h5>
                          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{s.specialty}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>
              )}
            </div>
          </div>
        )}

        {/* Other tabs remain functional... */}
        {/* History Tab */}
        {activeTab === 'history' && (
          <div className="p-8 md:p-12 space-y-12">
             <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
              <div className="lg:col-span-4 space-y-8">
                <section className="space-y-4">
                  <header className="px-2">
                     <label className="text-[10px] font-black text-rose-500 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span>
                       Critical Alerts & Allergies
                     </label>
                  </header>
                  <div className="bg-rose-50/50 p-6 rounded-[2.5rem] border-2 border-rose-100 space-y-4 shadow-sm">
                    {history.allergies.length > 0 ? (
                      <div className="flex flex-wrap gap-2">
                        {history.allergies.map((a, i) => (
                          <span key={i} className="px-4 py-2 bg-white text-rose-700 rounded-xl text-[10px] font-black border border-rose-200 uppercase tracking-widest shadow-sm">
                            🚫 {a}
                          </span>
                        ))}
                      </div>
                    ) : (
                      <p className="text-xs text-rose-400 font-bold italic">No known allergies recorded.</p>
                    )}
                  </div>
                </section>

                <section className="space-y-4">
                  <header className="px-2">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active Diagnoses</label>
                  </header>
                  <div className="bg-slate-50/50 p-6 rounded-[2.5rem] border border-slate-100 space-y-4">
                    <div className="flex gap-2">
                      <input 
                        value={newCondition.name} 
                        onChange={e => setNewCondition({...newCondition, name: e.target.value})}
                        placeholder="Add diagnosis..."
                        className="flex-1 p-3 rounded-xl border border-slate-200 text-sm font-bold shadow-sm outline-none focus:ring-1 focus:ring-indigo-500"
                      />
                      <button onClick={() => { if(newCondition.name) { setHistory(prev => ({...prev, conditions: [...(prev.conditions || []), {id: Math.random().toString(36), name: newCondition.name!, status: 'Active'}]})); setNewCondition({name:''}); } }} className="bg-indigo-600 text-white px-4 rounded-xl font-black text-xs uppercase">Add</button>
