                          <div className="flex items-center gap-3">
                             <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                             <h5 className="font-black text-slate-800 text-xs">{cond.name}</h5>
                          </div>
                          <button onClick={() => setHistory(prev => ({...prev, conditions: prev.conditions?.filter(x => x.id !== cond.id)}))} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity">×</button>
