                  </div>
                  <div className="space-y-2">
                      <label className="text-[10px] font-black text-rose-100 uppercase tracking-widest ml-4">Intervention Workflow (ED Instructions)</label>
                      <textarea 
                        value={history.sickDayPlan.instructions} 
                        onChange={e => setHistory({...history, sickDayPlan: {...history.sickDayPlan, instructions: e.target.value}})} 
                        className="w-full h-[360px] p-10 rounded-[3rem] bg-white text-slate-800 font-black text-xl leading-relaxed italic outline-none focus:ring-4 focus:ring-white/20 shadow-2xl" 
                        placeholder="Detailed medical steps for physician review..." 
                      />
                    </div>
                </div>
            </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-[0_50px_100px_-20px_rgba(0,0,0,0.4)] mt-12 animate-in zoom-in-95 border-l-[30px] border-l-indigo-500 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500 rounded-full opacity-10 blur-[100px]"></div>
           <div className="flex flex-col md:flex-row items-center justify-between mb-16 gap-8 relative z-10">
             <div className="flex items-center gap-8">
                <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center text-5xl shadow-inner border border-white/5">📄</div>
                <div>
                   <h3 className="text-5xl font-black italic tracking-tighter">Clinical ISBAR</h3>
                   <p className="text-indigo-400 font-black text-xs uppercase tracking-[0.3em]">Optimized Handover Output</p>
                </div>
             </div>
             <button onClick={() => {navigator.clipboard.writeText(aiAnalysis.text); alert("ISBAR Copied!");}} className="bg-indigo-600 text-white px-10 py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-indigo-700 transition-all border border-indigo-400">Copy To Clipboard</button>
           </div>

           <div className="relative z-10 prose prose-invert max-w-none prose-2xl whitespace-pre-wrap text-indigo-50 font-bold italic leading-relaxed border-l-8 border-white/5 pl-12">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, Recommendation, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  pendingEvents?: ClinicalEvent[];
  onClearEvent?: (id: string) => void;
  attachmentData?: AttachmentAnalysis;
  prefilledHistory?: Partial<MedicalHistory>;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
