    fluidRequirements: "Frequent small sips. Watch for difficulty drinking during high work of breathing.",
    emergencyContact: "Respiratory Specialist / GP Clinic / 000"
  },
  epilepsy: {
    instructions: "Stay calm and time the seizure. Protect from injury (move furniture). Recovery position once jerking stops. DO NOT restrain or put anything in mouth. Call 000 if: Seizure >5 mins, 2nd seizure occurs without regaining consciousness, or child is injured/breathing is labored.",
    triggers: "Fever, illness, fatigue, missed medication, flashing lights (if photosensitive).",
    emergencyMeds: "Buccal Midazolam (if prescribed): Administer specified dose between gums and cheek. Note exact time given.",
    fluidRequirements: "Hydrate only once fully awake and able to swallow safely.",
    emergencyContact: "Neurology Specialist / Epilepsy Nurse / 000"
  },
