    Prepare 5 high-value clinical questions for a parent to ask during an appointment with a ${appointment.specialty} (${appointment.provider}).

    CHILD PROFILE SUMMARY:
    Conditions: ${JSON.stringify(profileData.conditions)}
    Current Meds: ${JSON.stringify(profileData.currentMedications)}
    Appointment Purpose: ${appointment.purpose}

    Base questions on Australian clinical best practices (e.g., RCH Melbourne).
    Return questions in a clear, parent-friendly list.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt
  });

  return response.text;
};

export const analyzeMedicalReport = async (imageBase64: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';
  const prompt = `OCR and synthesize this medical document for a parent.`;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] || imageBase64 } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          specialist: { type: Type.STRING },
          diagnosis: { type: Type.STRING },
          summary: { type: Type.STRING },
          actionItems: { type: Type.ARRAY, items: { type: Type.STRING } },
          questions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["specialist", "diagnosis", "summary", "actionItems", "questions"]
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

