import React, { useState, useRef, useEffect, useMemo } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, Recommendation, MedicalReport, Condition, Appointment } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport, prepareAppointmentQuestions } from '../services/gemini';

interface MedicalProfileProps {
  pendingEvents?: ClinicalEvent[];
  onClearEvent?: (id: string) => void;
  attachmentData?: AttachmentAnalysis;
  prefilledHistory?: Partial<MedicalHistory>;
}

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ pendingEvents = [], attachmentData, prefilledHistory }) => {
  const [history, setHistory] = useState<MedicalHistory>({
    pastMedicalHistory: prefilledHistory?.pastMedicalHistory || '',
    surgicalHistory: '',
    currentMedications: prefilledHistory?.currentMedications || [],
    previousMedications: prefilledHistory?.previousMedications || [],
    allergies: prefilledHistory?.allergies || [],
    familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
    specialists: [],
    appointments: [],
    devices: [],
    sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '', planPhoto: undefined },
    activeRecommendations: [],
    medicalReports: [],
    conditions: []
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [prepLoading, setPrepLoading] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday' | 'appointments'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // New item states
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', goals: '' });
  const [newAppointment, setNewAppointment] = useState<Partial<Appointment>>({ 
    provider: '', specialty: '', dateTime: '', location: '', purpose: '', status: 'Upcoming' 
  });

  useEffect(() => {
    if (prefilledHistory) {
      setHistory(prev => ({
        ...prev,
        ...prefilledHistory,
        appointments: prefilledHistory.appointments || prev.appointments || []
      }));
    }
  }, [prefilledHistory]);

  const handleAddAppointment = () => {
    if (newAppointment.provider && newAppointment.dateTime) {
      const apt: Appointment = { 
        id: Math.random().toString(36).substr(2, 9), 
        preVisitNotes: '',
        postVisitSummary: '',
        reminderSent: false,
        ...newAppointment 
      } as Appointment;
      setHistory(prev => ({ ...prev, appointments: [...prev.appointments, apt] }));
      setNewAppointment({ provider: '', specialty: '', dateTime: '', location: '', purpose: '', status: 'Upcoming' });
    }
  };

  const handleAIPrep = async (apt: Appointment) => {
    setPrepLoading(apt.id);
    try {
      const questions = await prepareAppointmentQuestions(history, apt);
      setHistory(prev => ({
        ...prev,
        appointments: prev.appointments.map(a => 
          a.id === apt.id ? { ...a, preVisitNotes: questions } : a
        )
      }));
    } catch (e) {
      alert("Error generating prep questions.");
    } finally {
      setPrepLoading(null);
    }
  };

  const handleCalendarSync = (apt: Appointment) => {
    const start = new Date(apt.dateTime).toISOString().replace(/-|:|\.\d+/g, "");
    const end = new Date(new Date(apt.dateTime).getTime() + 3600000).toISOString().replace(/-|:|\.\d+/g, ""); // +1hr

    const icsContent = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "BEGIN:VEVENT",
      `SUMMARY:${apt.specialty} with ${apt.provider}`,
      `DTSTART:${start}`,
      `DTEND:${end}`,
      `LOCATION:${apt.location}`,
      `DESCRIPTION:${apt.purpose}`,
      "END:VEVENT",
      "END:VCALENDAR"
    ].join("\n");

    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `appointment_${apt.id}.ics`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
