          <p className="text-slate-500 font-medium italic">Clinical coordination and ISBAR data management.</p>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
          <button 
            onClick={async () => {
              setLoading(true);
              const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
              setAiAnalysis(result);
              setLoading(false);
            }}
            disabled={loading}
            className="px-6 py-3 bg-indigo-600 text-white font-black rounded-2xl shadow-lg hover:bg-indigo-700 transition-all text-xs uppercase tracking-widest"
          >
            {loading ? 'Synthesizing...' : 'Generate ISBAR'}
          </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex bg-slate-100/50 p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📜' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'appointments', label: 'Appointments', icon: '🗓️' },
          { id: 'reports', label: 'Reports', icon: '✉️' },
          { id: 'mdt', label: 'Care Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'sickday', label: 'Emergency', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-indigo-700 shadow-md border border-slate-200' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <span className="text-lg">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px]">
        {activeTab === 'appointments' && (
          <div className="p-8 md:p-12 space-y-12">
            {/* Appointment Add Form */}
            <section className="bg-indigo-50/50 p-8 rounded-[3rem] border border-indigo-100 space-y-6">
              <h4 className="font-black text-indigo-900 flex items-center gap-2 uppercase tracking-widest text-[10px]">🗓️ Schedule Specialist Visit</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                <input placeholder="Provider Name" value={newAppointment.provider} onChange={e => setNewAppointment({...newAppointment, provider: e.target.value})} className="p-4 rounded-2xl border border-white bg-white shadow-sm text-sm font-bold" />
