                    onChange={e => updateHistory({ sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value } })}
                    className="w-full h-80 p-8 rounded-[3rem] bg-white text-slate-800 font-black text-xl leading-relaxed italic shadow-2xl outline-none focus:ring-4 focus:ring-white/20"
                    placeholder="Enter urgent clinical instructions..."
                   />
                </div>
             </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] mt-12 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500 rounded-full opacity-10 blur-[100px]"></div>
           <div className="flex items-center justify-between mb-16 relative z-10">
              <h3 className="text-6xl font-black italic tracking-tighter text-indigo-100">ISBAR <span className="text-indigo-500">Handover</span></h3>
              <button onClick={() => {navigator.clipboard.writeText(aiAnalysis.text); alert("ISBAR Copied!");}} className="px-10 py-5 bg-indigo-600 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl border border-indigo-400">Copy to Clipboard</button>
           </div>
           <div className="relative z-10 whitespace-pre-wrap text-2xl font-bold italic leading-relaxed text-indigo-50 border-l-8 border-white/5 pl-12">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI, Modality, Type } from "@google/genai";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSymptoms = async (description: string, imageBase64?: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a supportive and professional pediatric clinical triage assistant. 
    Your goal is to provide guideline-based interpretation of childhood symptoms.

    PATIENT REPORT: "${description}"
    ${imageBase64 ? "VISUAL EVIDENCE: A photo of the symptom has been provided." : ""}

    Structure your response with:
    1. Potential Observations:
    2. Home Care Advice:
    3. Triage Guide: (Green, Yellow, Red)
    4. Questions for Parent:
  `;

  const contents: any = { parts: [{ text: prompt }] };
  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64.split(',')[1] || imageBase64
      }
    });
  }

  const response = await ai.models.generateContent({
    model,
    contents,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
  };
};

export const prepareAppointmentQuestions = async (profileData: any, appointment: any) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';

  const prompt = `
    You are a pediatric clinical nurse navigator specializing in complex care coordination.
    Prepare a structured list of 5-7 high-value clinical questions for a parent to ask during an appointment with a ${appointment.specialty} (${appointment.provider}).

    CONTEXT:
    Child's Name: ${profileData.name || 'Child'}
    Active Diagnoses: ${JSON.stringify(profileData.conditions?.map((c: any) => c.name) || [])}
    Current Medications: ${JSON.stringify(profileData.currentMedications?.map((m: any) => `${m.name} ${m.dose}`) || [])}
    Appointment Purpose: ${appointment.purpose}

    GUIDELINES:
    1. Focus on Australian clinical best practices (e.g., RCH Melbourne, QCH).
    2. Include questions about: medication side effects, long-term prognosis, impact on daily life/schooling, and specific red flags for this condition.
    3. Format as a clean list with each question on a new line starting with "• ".
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt
  });

  return response.text;
};

export const analyzeMedicalReport = async (imageBase64: string) => {
  const ai = getAIClient();
  const model = 'gemini-3-flash-preview';
  const prompt = `OCR and synthesize this medical document for a parent.`;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] || imageBase64 } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          specialist: { type: Type.STRING },
          diagnosis: { type: Type.STRING },
          summary: { type: Type.STRING },
          actionItems: { type: Type.ARRAY, items: { type: Type.STRING } },
          questions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["specialist", "diagnosis", "summary", "actionItems", "questions"]
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

