            <span className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-lg">🆔</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Identity & Basic Metrics</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Legal Name</label>
              <input
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Full Name"
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-lg"
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date of Birth</label>
              <input
                type="date"
                required
                value={dob}
                onChange={(e) => setDob(e.target.value)}
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-lg uppercase"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Sex</label>
              <select 
                value={sex} 
                onChange={(e) => setSex(e.target.value as any)}
                className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 font-bold"
              >
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Other">Other</option>
              </select>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Weight</label>
              <div className="relative group">
                <input
                  type="number"
                  step="0.001"
                  min="0"
                  value={weight}
                  onChange={(e) => setWeight(e.target.value)}
                  placeholder="0.000"
                  className="w-full p-5 pr-14 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 font-bold text-lg outline-none transition-all"
                />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 font-black text-slate-300 group-focus-within:text-indigo-600 transition-colors uppercase text-[10px] tracking-widest">kg</span>
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Height</label>
              <div className="relative group">
                <input
                  type="number"
                  step="0.1"
                  min="0"
                  value={height}
                  onChange={(e) => setHeight(e.target.value)}
                  placeholder="00.0"
                  className="w-full p-5 pr-14 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 font-bold text-lg outline-none transition-all"
                />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 font-black text-slate-300 group-focus-within:text-indigo-600 transition-colors uppercase text-[10px] tracking-widest">cm</span>
              </div>
            </div>
          </div>
        </section>

        {/* Clinical History Section */}
        <section className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
          <div className="flex items-center gap-3 mb-2">
            <span className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center text-lg">📋</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Medical Background</h3>
          </div>

          <div className="space-y-2">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Longitudinal Medical History</label>
            <textarea
              value={medHistory}
              onChange={(e) => setMedHistory(e.target.value)}
              placeholder="List chronic conditions, past surgeries, or specialist involvements..."
              className="w-full h-40 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-rose-500 outline-none font-medium resize-none"
            />
          </div>

          <div className="space-y-6">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Active Medications</label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100">
              <div className="space-y-1">
                 <input value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} placeholder="Drug Name" className="w-full p-3 rounded-xl border border-slate-200" />
              </div>
              <div className="space-y-1">
                 <input value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} placeholder="Dose (e.g. 5mg/5mL)" className="w-full p-3 rounded-xl border border-slate-200" />
              </div>
              <div className="space-y-1">
                 <input value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} placeholder="Indication (What is it for?)" className="w-full p-3 rounded-xl border border-slate-200" />
              </div>
              <div className="space-y-1">
                 <input value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} placeholder="Dosing Times (e.g. BD/Noon)" className="w-full p-3 rounded-xl border border-slate-200" />
              </div>
              <div className="md:col-span-2 flex gap-4">
                 <div className="flex-1">
                    <input type="date" value={newMed.startDate} onChange={e => setNewMed({...newMed, startDate: e.target.value})} className="w-full p-3 rounded-xl border border-slate-200 uppercase text-xs font-black" />
                 </div>
                 <button type="button" onClick={handleAddMed} className="bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest px-8">Add Medication</button>
              </div>
            </div>
            <div className="space-y-2">
              {meds.map((m) => (
                <div key={m.id} className="flex justify-between items-center bg-white p-5 rounded-2xl border border-indigo-100 text-xs font-bold shadow-sm">
                   <div className="flex flex-col gap-0.5">
                      <span className="text-slate-800 text-sm font-black italic">{m.name} <span className="text-indigo-600 opacity-60 ml-1">{m.dose}</span></span>
                      <span className="text-slate-400 font-medium">For: {m.indication || 'N/A'} • Started: {m.startDate || 'Unknown'}</span>
                   </div>
                   <button type="button" onClick={() => setMeds(meds.filter(x => x.id !== m.id))} className="w-8 h-8 bg-rose-50 text-rose-500 rounded-lg flex items-center justify-center font-black">×</button>
                </div>
              ))}
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-50">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Allergies & Reactions</label>
            <div className="flex gap-2">
              <input 
                value={newAllergy} 
                onChange={e => setNewAllergy(e.target.value)} 
                placeholder="e.g. Peanuts (Anaphylaxis)" 
                className="flex-1 p-4 rounded-xl border border-slate-100 bg-slate-50/50 text-sm"
                onKeyPress={e => e.key === 'Enter' && (e.preventDefault(), handleAddAllergy())}
              />
              <button type="button" onClick={handleAddAllergy} className="bg-rose-500 text-white px-6 rounded-xl font-black text-[10px] uppercase tracking-widest">Add</button>
            </div>
            <div className="flex flex-wrap gap-2 min-h-[40px]">
              {allergies.map((a, i) => (
                <span key={i} className="px-4 py-2 bg-rose-50 text-rose-700 rounded-xl text-[10px] font-black border border-rose-100 flex items-center gap-2 uppercase tracking-wider">
                  {a} <button type="button" onClick={() => setAllergies(allergies.filter((_, idx) => idx !== i))}>×</button>
                </span>
              ))}
            </div>
          </div>
        </section>

        <div className="flex gap-4 pt-4">
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 py-6 bg-slate-100 text-slate-500 font-black rounded-3xl hover:bg-slate-200 transition-all text-sm uppercase tracking-widest"
            >
              Cancel
            </button>
          )}
          <button
            type="submit"
            className="flex-grow py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-2xl hover:bg-indigo-700 transition-all transform active:scale-95 text-sm uppercase tracking-widest"
          >
            {initialProfile ? 'Sync Updated Records' : 'Finalize & Create Profile ✨'}
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  pendingEvents?: ClinicalEvent[];
  attachmentData?: AttachmentAnalysis;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Standard Australian 4x4 Protocol: Give 4 puffs of blue reliever (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4x4. Call 000 if child is distressed, lips blue, or skin is sucking in at the ribs/neck.",
    triggers: "Viral colds, exercise, cigarette smoke, dust mites, pollens.",
    emergencyMeds: "Salbutamol (Ventolin/Asmol) 100mcg inhaler via spacer.",
    fluidRequirements: "Frequent small sips. Watch for difficulty drinking during high work of breathing.",
    emergencyContact: "GP Clinic / 000"
  },
  epilepsy: {
    instructions: "Stay calm and time the seizure. Protect from injury. Recovery position once jerking stops. Call 000 if: Seizure >5 mins or child is injured.",
    triggers: "Fever, illness, fatigue, missed medication.",
    emergencyMeds: "Buccal Midazolam (if prescribed).",
    fluidRequirements: "Hydrate only once fully awake.",
    emergencyContact: "Neurology Nurse / 000"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);

  // Helper selectors
  const medicalSpecialists = useMemo(() => history.specialists.filter(s => s.category === 'Medical'), [history.specialists]);
  const alliedHealthTeam = useMemo(() => history.specialists.filter(s => s.category === 'Allied Health'), [history.specialists]);

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ medicalReports: [...(history.medicalReports || []), newReport] });
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ 
        sickDayPlan: { ...history.sickDayPlan, ...template } 
      });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-in fade-in duration-500">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 border-b border-slate-100 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical coordination and ISBAR synthesis.</p>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
          <button 
            onClick={handleGenerateHandover}
            disabled={loading}
            className="px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-3 text-xs uppercase tracking-widest"
          >
            {loading ? 'Synthesizing...' : 'Generate ISBAR Handover'}
            {!loading && <span className="text-lg">✨</span>}
          </button>
        </div>
      </header>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Active Meds', value: history.currentMedications.length, icon: '💊', color: 'text-indigo-600 bg-indigo-50' },
          { label: 'Allergies', value: history.allergies.length, icon: '🚫', color: 'text-rose-600 bg-rose-50' },
          { label: 'Team Members', value: history.specialists.length, icon: '🫂', color: 'text-emerald-600 bg-emerald-50' },
          { label: 'Diagnoses', value: history.conditions?.length || 0, icon: '📋', color: 'text-amber-600 bg-amber-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-50 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl ${stat.color}`}>
              {stat.icon}
            </div>
            <div className="text-2xl font-black text-slate-800">{stat.value}</div>
            <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="flex bg-slate-100/50 p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📜' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Care Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-indigo-700 shadow-md border border-slate-200' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <span className="text-lg">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
            <div className="flex items-center gap-4 mb-4">
               <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-2xl">📜</div>
               <h3 className="text-2xl font-black text-slate-800">Longitudinal Clinical Narrative</h3>
            </div>
            <textarea 
              value={history.pastMedicalHistory}
              onChange={e => updateHistory({ pastMedicalHistory: e.target.value })}
              className="w-full h-96 p-8 rounded-[2.5rem] border border-slate-50 bg-slate-50/30 outline-none text-slate-700 font-bold italic leading-relaxed shadow-inner focus:ring-2 focus:ring-indigo-100 transition-all"
              placeholder="Document the clinical story here..."
            />
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <section className="space-y-6">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b pb-4">Active Medications</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {history.currentMedications.map(m => (
                    <div key={m.id} className="bg-white p-8 rounded-[2.5rem] border border-indigo-50 shadow-sm flex items-center gap-6 group hover:border-indigo-100 transition-all">
                       <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">💊</div>
                       <div>
                          <h5 className="text-lg font-black text-slate-800 tracking-tight">{m.name}</h5>
                          <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{m.dose} • {m.instructions}</p>
                          <p className="text-xs text-slate-400 mt-1">For: {m.indication}</p>
                       </div>
                    </div>
                  ))}
                  {history.currentMedications.length === 0 && <p className="text-slate-400 italic">No active medications logged.</p>}
                </div>
             </section>

             <section className="space-y-6">
                <h3 className="text-sm font-black text-rose-400 uppercase tracking-widest border-b pb-4">Allergies & Adverse Reactions</h3>
                <div className="flex flex-wrap gap-4">
                  {history.allergies.map((a, i) => (
                    <div key={i} className="px-6 py-3 bg-rose-50 text-rose-700 rounded-2xl text-xs font-black border border-rose-100 uppercase tracking-widest flex items-center gap-2">
                       🚫 {a}
                    </div>
                  ))}
                  {history.allergies.length === 0 && <p className="text-slate-400 italic">No allergies documented.</p>}
                </div>
             </section>

             {history.previousMedications.length > 0 && (
               <section className="space-y-6">
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b pb-4">Ceased Medications</h3>
                  <div className="space-y-3">
                    {history.previousMedications.map(m => (
                      <div key={m.id} className="bg-slate-50 p-6 rounded-3xl flex justify-between items-center opacity-70">
                         <div>
                            <p className="font-bold text-slate-700">{m.name} <span className="text-xs font-normal opacity-60">({m.dose})</span></p>
                            <p className="text-[10px] font-black uppercase text-slate-400">Ceased: {m.ceasedDate} • Reason: {m.ceaseReason}</p>
                         </div>
                      </div>
                    ))}
                  </div>
               </section>
             )}
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="p-12 space-y-10 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-800">Specialist Letters & Reports</h3>
                <button 
                  onClick={() => reportInputRef.current?.click()}
                  disabled={reportLoading}
                  className="px-6 py-3 bg-indigo-50 text-indigo-700 rounded-2xl text-xs font-black uppercase tracking-widest border border-indigo-100 hover:bg-indigo-100 transition-all"
                >
                  {reportLoading ? 'Processing...' : 'Upload & Analyze ✨'}
                </button>
                <input type="file" ref={reportInputRef} onChange={handleReportUpload} className="hidden" accept="image/*" />
             </div>

             <div className="grid grid-cols-1 gap-6">
                {history.medicalReports?.map(report => (
                  <div key={report.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm space-y-6 group hover:shadow-xl transition-all">
                     <div className="flex justify-between items-start">
                        <div className="flex gap-4">
                           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">✉️</div>
                           <div>
                              <h5 className="text-xl font-black text-slate-800">{report.specialist}</h5>
                              <p className="text-xs font-bold text-slate-400 italic">{report.date}</p>
                           </div>
                        </div>
                     </div>
                     <div className="bg-slate-50/50 p-6 rounded-[2rem] space-y-4">
                        <p className="text-sm text-slate-600 leading-relaxed font-bold italic border-l-4 border-indigo-200 pl-6">{report.summary}</p>
                        <div className="flex flex-wrap gap-2">
                           {report.actionItems.map((item, i) => (
                              <span key={i} className="px-4 py-2 bg-white rounded-xl text-[10px] font-black uppercase tracking-widest text-indigo-600 border border-indigo-50">✓ {item}</span>
                           ))}
                        </div>
                     </div>
                  </div>
                ))}
                {(!history.medicalReports || history.medicalReports.length === 0) && (
                   <div className="py-20 text-center space-y-4 border-4 border-dashed border-slate-50 rounded-[3rem]">
                      <span className="text-6xl grayscale opacity-30 block">📄</span>
                      <p className="text-slate-400 font-black uppercase tracking-widest text-sm">No reports uploaded yet.</p>
                   </div>
                )}
             </div>
          </div>
        )}

        {activeTab === 'mdt' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <section className="space-y-6">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b pb-4">Specialist Doctors</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {medicalSpecialists.map(s => (
                    <div key={s.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:border-indigo-100 transition-all">
                       <div className="w-16 h-16 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">👨‍⚕️</div>
                       <div>
                          <h5 className="text-lg font-black text-slate-800 tracking-tight">{s.name}</h5>
                          <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest">{s.specialty}</p>
                       </div>
                    </div>
                  ))}
                  <div className="bg-slate-50 border-4 border-dashed border-slate-100 rounded-[2.5rem] p-8 flex flex-col items-center justify-center text-center space-y-2 opacity-60">
                     <p className="text-[10px] font-black uppercase text-slate-400">Add via Appointments Tab</p>
                  </div>
                </div>
             </section>

             {alliedHealthTeam.length > 0 && (
               <section className="space-y-6">
                  <h3 className="text-sm font-black text-teal-600 uppercase tracking-widest border-b pb-4">Allied Health & Therapy</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {alliedHealthTeam.map(s => (
                      <div key={s.id} className="bg-teal-50/20 p-8 rounded-[2.5rem] border border-teal-100 flex flex-col gap-4">
                         <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">🫂</div>
                            <div>
                               <h5 className="font-black text-slate-800">{s.name}</h5>
                               <p className="text-[9px] font-black text-teal-600 uppercase">{s.specialty}</p>
                            </div>
                         </div>
                         {s.goals && <p className="text-xs font-bold italic text-teal-900 leading-relaxed border-l-2 border-teal-200 pl-4">{s.goals}</p>}
                      </div>
                    ))}
                  </div>
               </section>
             )}
          </div>
        )}

        {activeTab === 'gear' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-800">Medical Devices & Gear</h3>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {history.devices?.map(device => (
                  <div key={device.id} className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
                     <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">⚙️</div>
                        <div>
                           <h5 className="font-black text-slate-800">{device.type}</h5>
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{device.model || 'Standard Model'}</p>
                        </div>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black text-indigo-600 uppercase">Change Due</p>
                        <p className="text-sm font-bold">{device.nextChangeDue || 'As Needed'}</p>
                     </div>
                  </div>
                ))}
                {(!history.devices || history.devices.length === 0) && (
                   <div className="col-span-full py-20 text-center space-y-4 border-4 border-dashed border-slate-50 rounded-[3rem]">
                      <span className="text-6xl opacity-30 block">🩹</span>
                      <p className="text-slate-400 font-black uppercase tracking-widest text-sm">No medical equipment logged.</p>
                   </div>
                )}
             </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
             <div className="bg-rose-600 p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-10 text-9xl">🚨</div>
                <div className="relative z-10 space-y-10">
                   <div className="flex items-center justify-between">
                      <h4 className="text-4xl font-black italic tracking-tighter">Sick Day Plan</h4>
                      <div className="flex gap-2">
                        {Object.keys(SICK_DAY_TEMPLATES).map(key => (
                          <button key={key} onClick={() => applySickDayTemplate(key)} className="px-4 py-2 bg-white/20 rounded-xl text-[10px] font-black uppercase hover:bg-white/40 transition-all border border-white/20">{key}</button>
                        ))}
                      </div>
                   </div>
                   <textarea 
                    value={history.sickDayPlan.instructions}
                    onChange={e => updateHistory({ sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value } })}
                    className="w-full h-80 p-8 rounded-[3rem] bg-white text-slate-800 font-black text-xl leading-relaxed italic shadow-2xl outline-none focus:ring-4 focus:ring-white/20"
                    placeholder="Enter urgent clinical instructions..."
                   />
                </div>
             </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] mt-12 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500 rounded-full opacity-10 blur-[100px]"></div>
           <div className="flex items-center justify-between mb-16 relative z-10">
              <h3 className="text-6xl font-black italic tracking-tighter text-indigo-100">ISBAR <span className="text-indigo-500">Handover</span></h3>
              <button onClick={() => {navigator.clipboard.writeText(aiAnalysis.text); alert("ISBAR Copied!");}} className="px-10 py-5 bg-indigo-600 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl border border-indigo-400">Copy to Clipboard</button>
           </div>
           <div className="relative z-10 whitespace-pre-wrap text-2xl font-bold italic leading-relaxed text-indigo-50 border-l-8 border-white/5 pl-12">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  pendingEvents?: ClinicalEvent[];
  attachmentData?: AttachmentAnalysis;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Standard Australian 4x4 Protocol: Give 4 puffs of blue reliever (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4x4. Call 000 if child is distressed, lips blue, or skin is sucking in at the ribs/neck.",
    triggers: "Viral colds, exercise, cigarette smoke, dust mites, pollens.",
    emergencyMeds: "Salbutamol (Ventolin/Asmol) 100mcg inhaler via spacer.",
    fluidRequirements: "Frequent small sips. Watch for difficulty drinking during high work of breathing.",
    emergencyContact: "GP Clinic / 000"
  },
  epilepsy: {
    instructions: "Stay calm and time the seizure. Protect from injury. Recovery position once jerking stops. Call 000 if: Seizure >5 mins or child is injured.",
    triggers: "Fever, illness, fatigue, missed medication.",
    emergencyMeds: "Buccal Midazolam (if prescribed).",
    fluidRequirements: "Hydrate only once fully awake.",
    emergencyContact: "Neurology Nurse / 000"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);

  // Medication Form States
  const [showActiveForm, setShowActiveForm] = useState(false);
  const [showCeasedForm, setShowCeasedForm] = useState(false);
  const [newActive, setNewActive] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newCeased, setNewCeased] = useState<Partial<PreviousMedication>>({ name: '', dose: '', indication: '', ceasedDate: '', ceaseReason: '' });

  // Helper selectors
  const medicalSpecialists = useMemo(() => history.specialists.filter(s => s.category === 'Medical'), [history.specialists]);
  const alliedHealthTeam = useMemo(() => history.specialists.filter(s => s.category === 'Allied Health'), [history.specialists]);

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ medicalReports: [...(history.medicalReports || []), newReport] });
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ 
        sickDayPlan: { ...history.sickDayPlan, ...template } 
      });
    }
  };

  const handleAddActive = () => {
    if (newActive.name) {
      updateHistory({
        currentMedications: [...history.currentMedications, { 
          ...newActive, 
          id: Math.random().toString(36).substr(2, 9),
          startDate: new Date().toISOString().split('T')[0]
        } as Medication]
      });
      setNewActive({ name: '', dose: '', instructions: '', indication: '' });
      setShowActiveForm(false);
    }
  };

  const handleAddCeased = () => {
    if (newCeased.name) {
      updateHistory({
        previousMedications: [...(history.previousMedications || []), { 
          ...newCeased, 
          id: Math.random().toString(36).substr(2, 9) 
        } as PreviousMedication]
      });
      setNewCeased({ name: '', dose: '', indication: '', ceasedDate: '', ceaseReason: '' });
      setShowCeasedForm(false);
    }
  };

  const handleCeaseMed = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}?`);
    const date = prompt(`Date ceased? (YYYY-MM-DD)`, new Date().toISOString().split('T')[0]);
    if (reason && date) {
      updateHistory({
        currentMedications: history.currentMedications.filter(m => m.id !== med.id),
        previousMedications: [...(history.previousMedications || []), {
          id: med.id,
          name: med.name,
          dose: med.dose,
          indication: med.indication,
          ceasedDate: date,
          ceaseReason: reason
        }]
      });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-in fade-in duration-500">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 border-b border-slate-100 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical coordination and ISBAR synthesis.</p>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
          <button 
            onClick={handleGenerateHandover}
            disabled={loading}
            className="px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-3 text-xs uppercase tracking-widest"
          >
            {loading ? 'Synthesizing...' : 'Generate ISBAR Handover'}
            {!loading && <span className="text-lg">✨</span>}
          </button>
        </div>
      </header>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Active Meds', value: history.currentMedications.length, icon: '💊', color: 'text-indigo-600 bg-indigo-50' },
          { label: 'Allergies', value: history.allergies.length, icon: '🚫', color: 'text-rose-600 bg-rose-50' },
          { label: 'Team Members', value: history.specialists.length, icon: '🫂', color: 'text-emerald-600 bg-emerald-50' },
          { label: 'Diagnoses', value: history.conditions?.length || 0, icon: '📋', color: 'text-amber-600 bg-amber-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-50 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl ${stat.color}`}>
              {stat.icon}
            </div>
            <div className="text-2xl font-black text-slate-800">{stat.value}</div>
            <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="flex bg-slate-100/50 p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📜' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Care Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-indigo-700 shadow-md border border-slate-200' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <span className="text-lg">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
            <div className="flex items-center gap-4 mb-4">
               <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-2xl">📜</div>
               <h3 className="text-2xl font-black text-slate-800">Longitudinal Clinical Narrative</h3>
            </div>
            <textarea 
              value={history.pastMedicalHistory}
              onChange={e => updateHistory({ pastMedicalHistory: e.target.value })}
              className="w-full h-96 p-8 rounded-[2.5rem] border border-slate-50 bg-slate-50/30 outline-none text-slate-700 font-bold italic leading-relaxed shadow-inner focus:ring-2 focus:ring-indigo-100 transition-all"
              placeholder="Document the clinical story here..."
            />
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <section className="space-y-6">
                <div className="flex justify-between items-center border-b pb-4">
                   <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Active Medications</h3>
                   <button 
                    onClick={() => setShowActiveForm(!showActiveForm)} 
                    className="text-[10px] font-black uppercase text-indigo-600 hover:text-indigo-800 transition-colors"
                   >
                     {showActiveForm ? 'Cancel' : '+ Add New'}
                   </button>
                </div>

                {showActiveForm && (
                  <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-indigo-100 grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-top-4">
                     <input placeholder="Drug Name" value={newActive.name} onChange={e => setNewActive({...newActive, name: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Dose (e.g. 10mg)" value={newActive.dose} onChange={e => setNewActive({...newActive, dose: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Instructions (e.g. BD)" value={newActive.instructions} onChange={e => setNewActive({...newActive, instructions: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Indication" value={newActive.indication} onChange={e => setNewActive({...newActive, indication: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <button onClick={handleAddActive} className="md:col-span-2 py-4 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase">Confirm Addition</button>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {history.currentMedications.map(m => (
                    <div key={m.id} className="bg-white p-8 rounded-[2.5rem] border border-indigo-50 shadow-sm flex items-center justify-between group hover:border-indigo-100 transition-all">
                       <div className="flex items-center gap-6">
                          <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">💊</div>
                          <div>
                             <h5 className="text-lg font-black text-slate-800 tracking-tight">{m.name}</h5>
                             <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{m.dose} • {m.instructions}</p>
                             <p className="text-xs text-slate-400 mt-1">For: {m.indication}</p>
                          </div>
                       </div>
                       <button 
                        onClick={() => handleCeaseMed(m)} 
                        className="opacity-0 group-hover:opacity-100 px-4 py-2 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-xl hover:bg-rose-100 transition-all"
                       >
                         Cease
                       </button>
                    </div>
                  ))}
                  {history.currentMedications.length === 0 && <p className="text-slate-400 italic">No active medications logged.</p>}
                </div>
             </section>

             <section className="space-y-6">
                <h3 className="text-sm font-black text-rose-400 uppercase tracking-widest border-b pb-4">Allergies & Adverse Reactions</h3>
                <div className="flex flex-wrap gap-4">
                  {history.allergies.map((a, i) => (
                    <div key={i} className="px-6 py-3 bg-rose-50 text-rose-700 rounded-2xl text-xs font-black border border-rose-100 uppercase tracking-widest flex items-center gap-2">
                       🚫 {a}
                    </div>
                  ))}
                  {history.allergies.length === 0 && <p className="text-slate-400 italic">No allergies documented.</p>}
                </div>
             </section>

             <section className="space-y-6">
                <div className="flex justify-between items-center border-b pb-4">
                   <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Previous Medications (History)</h3>
                   <button 
                    onClick={() => setShowCeasedForm(!showCeasedForm)} 
                    className="text-[10px] font-black uppercase text-slate-600 hover:text-slate-800 transition-colors"
                   >
                     {showCeasedForm ? 'Cancel' : '+ Log Past Medication'}
                   </button>
                </div>

                {showCeasedForm && (
                  <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-200 grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-top-4">
                     <input placeholder="Drug Name" value={newCeased.name} onChange={e => setNewCeased({...newCeased, name: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Last Dose Used" value={newCeased.dose} onChange={e => setNewCeased({...newCeased, dose: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input type="date" value={newCeased.ceasedDate} onChange={e => setNewCeased({...newCeased, ceasedDate: e.target.value})} className="p-4 rounded-xl border border-slate-200 uppercase text-xs font-black" />
                     <input placeholder="Reason for Ceasing" value={newCeased.ceaseReason} onChange={e => setNewCeased({...newCeased, ceaseReason: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <button onClick={handleAddCeased} className="md:col-span-2 py-4 bg-slate-600 text-white rounded-xl font-black text-xs uppercase">Record History</button>
                  </div>
                )}

                <div className="space-y-4">
                  {history.previousMedications.map(m => (
                    <div key={m.id} className="bg-slate-50 p-8 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-start md:items-center border border-slate-100 group">
                       <div className="flex gap-6 items-center">
                          <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm grayscale opacity-50">💊</div>
                          <div>
                            <p className="text-lg font-bold text-slate-700">{m.name} <span className="text-xs font-normal opacity-60">({m.dose})</span></p>
                            <p className="text-[10px] font-black uppercase text-slate-400 mt-1">For: {m.indication || 'N/A'}</p>
                          </div>
                       </div>
                       <div className="mt-4 md:mt-0 md:text-right bg-white p-4 rounded-2xl border border-slate-100 shadow-sm min-w-[200px]">
                          <p className="text-[9px] font-black uppercase text-rose-500 tracking-widest mb-1">Ceased: {m.ceasedDate}</p>
                          <p className="text-xs font-bold text-slate-600 italic leading-snug">Reason: {m.ceaseReason}</p>
                       </div>
                    </div>
                  ))}
                  {history.previousMedications.length === 0 && <p className="text-slate-400 italic">No medication history logged.</p>}
                </div>
             </section>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="p-12 space-y-10 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-800">Specialist Letters & Reports</h3>
                <button 
                  onClick={() => reportInputRef.current?.click()}
                  disabled={reportLoading}
                  className="px-6 py-3 bg-indigo-50 text-indigo-700 rounded-2xl text-xs font-black uppercase tracking-widest border border-indigo-100 hover:bg-indigo-100 transition-all"
                >
                  {reportLoading ? 'Processing...' : 'Upload & Analyze ✨'}
                </button>
                <input type="file" ref={reportInputRef} onChange={handleReportUpload} className="hidden" accept="image/*" />
             </div>

             <div className="grid grid-cols-1 gap-6">
                {history.medicalReports?.map(report => (
                  <div key={report.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm space-y-6 group hover:shadow-xl transition-all">
                     <div className="flex justify-between items-start">
                        <div className="flex gap-4">
                           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">✉️</div>
                           <div>
                              <h5 className="text-xl font-black text-slate-800">{report.specialist}</h5>
                              <p className="text-xs font-bold text-slate-400 italic">{report.date}</p>
                           </div>
                        </div>
                     </div>
                     <div className="bg-slate-50/50 p-6 rounded-[2rem] space-y-4">
                        <p className="text-sm text-slate-600 leading-relaxed font-bold italic border-l-4 border-indigo-200 pl-6">{report.summary}</p>
                        <div className="flex flex-wrap gap-2">
                           {report.actionItems.map((item, i) => (
                              <span key={i} className="px-4 py-2 bg-white rounded-xl text-[10px] font-black uppercase tracking-widest text-indigo-600 border border-indigo-50">✓ {item}</span>
                           ))}
                        </div>
                     </div>
                  </div>
                ))}
                {(!history.medicalReports || history.medicalReports.length === 0) && (
                   <div className="py-20 text-center space-y-4 border-4 border-dashed border-slate-50 rounded-[3rem]">
                      <span className="text-6xl grayscale opacity-30 block">📄</span>
                      <p className="text-slate-400 font-black uppercase tracking-widest text-sm">No reports uploaded yet.</p>
                   </div>
                )}
             </div>
          </div>
        )}

        {activeTab === 'mdt' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <section className="space-y-6">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b pb-4">Specialist Doctors</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {medicalSpecialists.map(s => (
                    <div key={s.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:border-indigo-100 transition-all">
                       <div className="w-16 h-16 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">👨‍⚕️</div>
                       <div>
                          <h5 className="text-lg font-black text-slate-800 tracking-tight">{s.name}</h5>
                          <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest">{s.specialty}</p>
                       </div>
                    </div>
                  ))}
                  <div className="bg-slate-50 border-4 border-dashed border-slate-100 rounded-[2.5rem] p-8 flex flex-col items-center justify-center text-center space-y-2 opacity-60">
                     <p className="text-[10px] font-black uppercase text-slate-400">Add via Appointments Tab</p>
                  </div>
                </div>
             </section>

             {alliedHealthTeam.length > 0 && (
               <section className="space-y-6">
                  <h3 className="text-sm font-black text-teal-600 uppercase tracking-widest border-b pb-4">Allied Health & Therapy</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {alliedHealthTeam.map(s => (
                      <div key={s.id} className="bg-teal-50/20 p-8 rounded-[2.5rem] border border-teal-100 flex flex-col gap-4">
                         <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">🫂</div>
                            <div>
                               <h5 className="font-black text-slate-800">{s.name}</h5>
                               <p className="text-[9px] font-black text-teal-600 uppercase">{s.specialty}</p>
                            </div>
                         </div>
                         {s.goals && <p className="text-xs font-bold italic text-teal-900 leading-relaxed border-l-2 border-teal-200 pl-4">{s.goals}</p>}
                      </div>
                    ))}
                  </div>
               </section>
             )}
          </div>
        )}

        {activeTab === 'gear' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-800">Medical Devices & Gear</h3>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {history.devices?.map(device => (
                  <div key={device.id} className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
                     <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">⚙️</div>
                        <div>
                           <h5 className="font-black text-slate-800">{device.type}</h5>
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{device.model || 'Standard Model'}</p>
                        </div>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black text-indigo-600 uppercase">Change Due</p>
                        <p className="text-sm font-bold">{device.nextChangeDue || 'As Needed'}</p>
                     </div>
                  </div>
                ))}
                {(!history.devices || history.devices.length === 0) && (
                   <div className="col-span-full py-20 text-center space-y-4 border-4 border-dashed border-slate-50 rounded-[3rem]">
                      <span className="text-6xl opacity-30 block">🩹</span>
                      <p className="text-slate-400 font-black uppercase tracking-widest text-sm">No medical equipment logged.</p>
                   </div>
                )}
             </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
             <div className="bg-rose-600 p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-10 text-9xl">🚨</div>
                <div className="relative z-10 space-y-10">
                   <div className="flex items-center justify-between">
                      <h4 className="text-4xl font-black italic tracking-tighter">Sick Day Plan</h4>
                      <div className="flex gap-2">
                        {Object.keys(SICK_DAY_TEMPLATES).map(key => (
                          <button key={key} onClick={() => applySickDayTemplate(key)} className="px-4 py-2 bg-white/20 rounded-xl text-[10px] font-black uppercase hover:bg-white/40 transition-all border border-white/20">{key}</button>
                        ))}
                      </div>
                   </div>
                   <textarea 
                    value={history.sickDayPlan.instructions}
                    onChange={e => updateHistory({ sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value } })}
                    className="w-full h-80 p-8 rounded-[3rem] bg-white text-slate-800 font-black text-xl leading-relaxed italic shadow-2xl outline-none focus:ring-4 focus:ring-white/20"
                    placeholder="Enter urgent clinical instructions..."
                   />
                </div>
             </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] mt-12 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500 rounded-full opacity-10 blur-[100px]"></div>
           <div className="flex items-center justify-between mb-16 relative z-10">
              <h3 className="text-6xl font-black italic tracking-tighter text-indigo-100">ISBAR <span className="text-indigo-500">Handover</span></h3>
              <button onClick={() => {navigator.clipboard.writeText(aiAnalysis.text); alert("ISBAR Copied!");}} className="px-10 py-5 bg-indigo-600 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl border border-indigo-400">Copy to Clipboard</button>
           </div>
           <div className="relative z-10 whitespace-pre-wrap text-2xl font-bold italic leading-relaxed text-indigo-50 border-l-8 border-white/5 pl-12">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  pendingEvents?: ClinicalEvent[];
  attachmentData?: AttachmentAnalysis;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "Standard Australian 4x4 Protocol: Give 4 puffs of blue reliever (Salbutamol) via spacer, 1 puff at a time with 4 breaths each. Wait 4 minutes. If no improvement, repeat 4x4. Call 000 if child is distressed, lips blue, or skin is sucking in at the ribs/neck.",
    triggers: "Viral colds, exercise, cigarette smoke, dust mites, pollens.",
    emergencyMeds: "Salbutamol (Ventolin/Asmol) 100mcg inhaler via spacer.",
    fluidRequirements: "Frequent small sips. Watch for difficulty drinking during high work of breathing.",
    emergencyContact: "GP Clinic / 000"
  },
  epilepsy: {
    instructions: "Stay calm and time the seizure. Protect from injury. Recovery position once jerking stops. Call 000 if: Seizure >5 mins or child is injured.",
    triggers: "Fever, illness, fatigue, missed medication.",
    emergencyMeds: "Buccal Midazolam (if prescribed).",
    fluidRequirements: "Hydrate only once fully awake.",
    emergencyContact: "Neurology Nurse / 000"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);

  // Form States for manual input
  const [showActiveForm, setShowActiveForm] = useState(false);
  const [showCeasedForm, setShowCeasedForm] = useState(false);
  const [showSpecialistForm, setShowSpecialistForm] = useState(false);
  const [showDeviceForm, setShowDeviceForm] = useState(false);
  const [showReportForm, setShowReportForm] = useState(false);
  const [showConditionForm, setShowConditionForm] = useState(false);

  const [newActive, setNewActive] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newCeased, setNewCeased] = useState<Partial<PreviousMedication>>({ name: '', dose: '', indication: '', ceasedDate: '', ceaseReason: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', nextChangeDue: '', notes: '' });
  const [newManualReport, setNewManualReport] = useState<Partial<MedicalReport>>({ specialist: '', date: new Date().toISOString().split('T')[0], summary: '', actionItems: [] });
  const [newActionItem, setNewActionItem] = useState('');
  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active', dateDiagnosed: '' });

  // Helper selectors
  const medicalSpecialists = useMemo(() => history.specialists.filter(s => s.category === 'Medical'), [history.specialists]);
  const alliedHealthTeam = useMemo(() => history.specialists.filter(s => s.category === 'Allied Health'), [history.specialists]);

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ medicalReports: [...(history.medicalReports || []), newReport] });
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ 
        sickDayPlan: { ...history.sickDayPlan, ...template } 
      });
    }
  };

  const handleAddActive = () => {
    if (newActive.name) {
      updateHistory({
        currentMedications: [...history.currentMedications, { 
          ...newActive, 
          id: Math.random().toString(36).substr(2, 9),
          startDate: new Date().toISOString().split('T')[0]
        } as Medication]
      });
      setNewActive({ name: '', dose: '', instructions: '', indication: '' });
      setShowActiveForm(false);
    }
  };

  const handleAddSpecialist = () => {
    if (newSpecialist.name && newSpecialist.specialty) {
      updateHistory({
        specialists: [...history.specialists, { ...newSpecialist, id: Math.random().toString(36).substr(2, 9) } as SpecialistContact]
      });
      setNewSpecialist({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
      setShowSpecialistForm(false);
    }
  };

  const handleAddDevice = () => {
    if (newDevice.type) {
      updateHistory({
        devices: [...(history.devices || []), { ...newDevice, id: Math.random().toString(36).substr(2, 9) } as MedicalDevice]
      });
      setNewDevice({ type: '', model: '', nextChangeDue: '', notes: '' });
      setShowDeviceForm(false);
    }
  };

  const handleAddManualReport = () => {
    if (newManualReport.specialist && newManualReport.summary) {
      updateHistory({
        medicalReports: [...(history.medicalReports || []), { ...newManualReport, id: Math.random().toString(36).substr(2, 9) } as MedicalReport]
      });
      setNewManualReport({ specialist: '', date: new Date().toISOString().split('T')[0], summary: '', actionItems: [] });
      setShowReportForm(false);
    }
  };

  const handleAddCondition = () => {
    if (newCondition.name) {
      updateHistory({
        conditions: [...(history.conditions || []), { ...newCondition, id: Math.random().toString(36).substr(2, 9) } as Condition]
      });
      setNewCondition({ name: '', status: 'Active', dateDiagnosed: '' });
      setShowConditionForm(false);
    }
  };

  const handleCeaseMed = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}?`);
    const date = prompt(`Date ceased? (YYYY-MM-DD)`, new Date().toISOString().split('T')[0]);
    if (reason && date) {
      updateHistory({
        currentMedications: history.currentMedications.filter(m => m.id !== med.id),
        previousMedications: [...(history.previousMedications || []), {
          id: med.id,
          name: med.name,
          dose: med.dose,
          indication: med.indication,
          ceasedDate: date,
          ceaseReason: reason
        }]
      });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-in fade-in duration-500">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 border-b border-slate-100 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical coordination and ISBAR synthesis.</p>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
          <button 
            onClick={handleGenerateHandover}
            disabled={loading}
            className="px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-3 text-xs uppercase tracking-widest"
          >
            {loading ? 'Synthesizing...' : 'Generate ISBAR Handover'}
            {!loading && <span className="text-lg">✨</span>}
          </button>
        </div>
      </header>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Active Meds', value: history.currentMedications.length, icon: '💊', color: 'text-indigo-600 bg-indigo-50' },
          { label: 'Allergies', value: history.allergies.length, icon: '🚫', color: 'text-rose-600 bg-rose-50' },
          { label: 'Team Members', value: history.specialists.length, icon: '🫂', color: 'text-emerald-600 bg-emerald-50' },
          { label: 'Diagnoses', value: history.conditions?.length || 0, icon: '📋', color: 'text-amber-600 bg-amber-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-50 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl ${stat.color}`}>
              {stat.icon}
            </div>
            <div className="text-2xl font-black text-slate-800">{stat.value}</div>
            <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="flex bg-slate-100/50 p-1 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📜' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Care Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Sick Day Plan', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-indigo-700 shadow-md border border-slate-200' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <span className="text-lg">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
            <section className="space-y-6">
              <div className="flex items-center gap-4 mb-4">
                 <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-2xl">📜</div>
                 <h3 className="text-2xl font-black text-slate-800">Longitudinal Clinical Narrative</h3>
              </div>
              <textarea 
                value={history.pastMedicalHistory}
                onChange={e => updateHistory({ pastMedicalHistory: e.target.value })}
                className="w-full h-64 p-8 rounded-[2.5rem] border border-slate-50 bg-slate-50/30 outline-none text-slate-700 font-bold italic leading-relaxed shadow-inner focus:ring-2 focus:ring-indigo-100 transition-all"
                placeholder="Document the clinical story here..."
              />
            </section>

            <section className="space-y-6">
              <div className="flex justify-between items-center border-b pb-4">
                 <h3 className="text-sm font-black text-amber-600 uppercase tracking-widest">Active Diagnoses & Conditions</h3>
                 <button onClick={() => setShowConditionForm(!showConditionForm)} className="text-[10px] font-black uppercase text-amber-600">+ Add Diagnosis</button>
              </div>

              {showConditionForm && (
                <div className="bg-amber-50 p-8 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-3 gap-4 animate-in slide-in-from-top-4">
                  <input placeholder="Condition Name" value={newCondition.name} onChange={e => setNewCondition({...newCondition, name: e.target.value})} className="p-4 rounded-xl border border-amber-100" />
                  <input type="date" value={newCondition.dateDiagnosed} onChange={e => setNewCondition({...newCondition, dateDiagnosed: e.target.value})} className="p-4 rounded-xl border border-amber-100 uppercase text-xs font-black" />
                  <select value={newCondition.status} onChange={e => setNewCondition({...newCondition, status: e.target.value as any})} className="p-4 rounded-xl border border-amber-100 font-black">
                    <option value="Active">Active</option>
                    <option value="Resolved">Resolved</option>
                    <option value="Under Investigation">Under Investigation</option>
                  </select>
                  <button onClick={handleAddCondition} className="md:col-span-3 py-4 bg-amber-600 text-white rounded-xl font-black text-xs uppercase">Save Diagnosis</button>
                </div>
              )}

              <div className="flex flex-wrap gap-4">
                {history.conditions?.map(c => (
                  <div key={c.id} className="px-6 py-4 bg-white border border-amber-100 rounded-[1.5rem] shadow-sm flex flex-col">
                    <span className="text-lg font-black text-slate-800 tracking-tight">{c.name}</span>
                    <div className="flex items-center gap-2 mt-1">
                      <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${c.status === 'Active' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`}>{c.status}</span>
                      <span className="text-[9px] text-slate-400 font-bold">Diagnosed: {c.dateDiagnosed || 'N/A'}</span>
                    </div>
                  </div>
                ))}
                {(!history.conditions || history.conditions.length === 0) && <p className="text-slate-400 italic">No formal diagnoses logged.</p>}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <section className="space-y-6">
                <div className="flex justify-between items-center border-b pb-4">
                   <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Active Medications</h3>
                   <button 
                    onClick={() => setShowActiveForm(!showActiveForm)} 
                    className="text-[10px] font-black uppercase text-indigo-600 hover:text-indigo-800 transition-colors"
                   >
                     {showActiveForm ? 'Cancel' : '+ Add New'}
                   </button>
                </div>

                {showActiveForm && (
                  <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-indigo-100 grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-top-4">
                     <input placeholder="Drug Name" value={newActive.name} onChange={e => setNewActive({...newActive, name: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Dose (e.g. 10mg)" value={newActive.dose} onChange={e => setNewActive({...newActive, dose: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Instructions (e.g. BD)" value={newActive.instructions} onChange={e => setNewActive({...newActive, instructions: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <input placeholder="Indication" value={newActive.indication} onChange={e => setNewActive({...newActive, indication: e.target.value})} className="p-4 rounded-xl border border-slate-200" />
                     <button onClick={handleAddActive} className="md:col-span-2 py-4 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase">Confirm Addition</button>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {history.currentMedications.map(m => (
                    <div key={m.id} className="bg-white p-8 rounded-[2.5rem] border border-indigo-50 shadow-sm flex items-center justify-between group hover:border-indigo-100 transition-all">
                       <div className="flex items-center gap-6">
                          <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">💊</div>
                          <div>
                             <h5 className="text-lg font-black text-slate-800 tracking-tight">{m.name}</h5>
                             <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{m.dose} • {m.instructions}</p>
                             <p className="text-xs text-slate-400 mt-1">For: {m.indication}</p>
                          </div>
                       </div>
                       <button 
                        onClick={() => handleCeaseMed(m)} 
                        className="opacity-0 group-hover:opacity-100 px-4 py-2 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-xl hover:bg-rose-100 transition-all"
                       >
                         Cease
                       </button>
                    </div>
                  ))}
