                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {history.currentMedications.map(m => (
                    <div key={m.id} className="bg-white p-8 rounded-[2.5rem] border border-indigo-50 shadow-sm flex items-center justify-between group hover:border-indigo-100 transition-all">
                       <div className="flex items-center gap-6">
                          <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">💊</div>
                          <div>
                             <h5 className="text-lg font-black text-slate-800 tracking-tight">{m.name}</h5>
                             <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{m.dose} • {m.instructions}</p>
