export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const reportInputRef = useRef<HTMLInputElement>(null);
  const sickPlanPhotoRef = useRef<HTMLInputElement>(null);

  // Manual input form states
  const [showConditionForm, setShowConditionForm] = useState(false);
  const [showActiveMedForm, setShowActiveMedForm] = useState(false);
  const [showCeasedMedForm, setShowCeasedMedForm] = useState(false);
  const [showTeamForm, setShowTeamForm] = useState(false);
  const [showGearForm, setShowGearForm] = useState(false);
  const [showReportForm, setShowReportForm] = useState(false);

  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active', dateDiagnosed: '' });
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newCeased, setNewCeased] = useState<Partial<PreviousMedication>>({ name: '', dose: '', indication: '', ceasedDate: '', ceaseReason: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', nextChangeDue: '', notes: '' });
  const [newManualReport, setNewManualReport] = useState<Partial<MedicalReport>>({ specialist: '', date: new Date().toISOString().split('T')[0], summary: '', actionItems: [] });

  const medicalSpecialists = useMemo(() => history.specialists.filter(s => s.category === 'Medical'), [history.specialists]);
  const alliedHealthTeam = useMemo(() => history.specialists.filter(s => s.category === 'Allied Health'), [history.specialists]);

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ medicalReports: [...(history.medicalReports || []), newReport] });
        } catch (err) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSickDayPhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateHistory({
          sickDayPlan: { ...history.sickDayPlan, planPhoto: reader.result as string }
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (e) {
      alert("Error generating ISBAR handover.");
    } finally {
      setLoading(false);
    }
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ 
        sickDayPlan: { ...history.sickDayPlan, ...template } 
      });
    }
  };

  const handleAddMed = () => {
    if (newMed.name) {
      updateHistory({
        currentMedications: [...history.currentMedications, { ...newMed, id: Math.random().toString(36).substr(2, 9), startDate: new Date().toISOString().split('T')[0] } as Medication]
      });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
      setShowActiveMedForm(false);
    }
  };

  const handleCeaseMed = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}?`);
    const date = prompt(`Date ceased? (YYYY-MM-DD)`, new Date().toISOString().split('T')[0]);
    if (reason && date) {
      updateHistory({
        currentMedications: history.currentMedications.filter(m => m.id !== med.id),
        previousMedications: [...(history.previousMedications || []), {
          id: med.id,
          name: med.name,
          dose: med.dose,
          indication: med.indication,
          ceasedDate: date,
          ceaseReason: reason
        }]
      });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-in fade-in duration-500">
      <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 border-b border-slate-100 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Comprehensive clinical coordination and ISBAR synthesis.</p>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
          <button 
            onClick={handleGenerateHandover}
            disabled={loading}
            className="px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-3 text-xs uppercase tracking-widest"
          >
            {loading ? 'Synthesizing...' : 'Generate ISBAR Handover'}
            {!loading && <span className="text-lg">✨</span>}
          </button>
        </div>
      </header>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Active Meds', value: history.currentMedications.length, icon: '💊', color: 'text-indigo-600 bg-indigo-50' },
          { label: 'Allergies', value: history.allergies.length, icon: '🚫', color: 'text-rose-600 bg-rose-50' },
          { label: 'Team Members', value: history.specialists.length, icon: '🫂', color: 'text-emerald-600 bg-emerald-50' },
          { label: 'Diagnoses', value: history.conditions?.length || 0, icon: '📋', color: 'text-amber-600 bg-amber-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-50 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl ${stat.color}`}>
              {stat.icon}
            </div>
            <div className="text-2xl font-black text-slate-800">{stat.value}</div>
            <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Primary Navigation Tabs */}
      <div className="flex bg-slate-100/50 p-1.5 rounded-3xl border border-slate-200 shadow-sm overflow-x-auto no-scrollbar">
        {[
          { id: 'history', label: 'History', icon: '📜' },
          { id: 'meds', label: 'Medications', icon: '💊' },
          { id: 'reports', label: 'Letters', icon: '✉️' },
          { id: 'mdt', label: 'Care Team', icon: '👨‍👩‍👧‍👦' },
          { id: 'gear', label: 'Devices', icon: '⚙️' },
          { id: 'sickday', label: 'Emergency Plan', icon: '🚨' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 min-w-[130px] py-4 rounded-2xl font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-indigo-700 shadow-md border border-slate-200' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <span className="text-lg">{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      {/* Tab Content Areas */}
      <div className="bg-white rounded-[3rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px]">

        {/* HISTORY TAB */}
        {activeTab === 'history' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
            <section className="space-y-6">
              <div className="flex items-center gap-4 mb-4">
                 <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-2xl">📜</div>
                 <h3 className="text-2xl font-black text-slate-800">Clinical Narrative</h3>
              </div>
              <textarea 
                value={history.pastMedicalHistory}
                onChange={e => updateHistory({ pastMedicalHistory: e.target.value })}
                className="w-full h-64 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/30 outline-none text-slate-700 font-bold italic leading-relaxed shadow-inner focus:ring-2 focus:ring-indigo-100 transition-all"
                placeholder="Document the long-term clinical story, birth history, and chronic evolution..."
              />
            </section>

            {/* Recent Observations List */}
            {pendingEvents.length > 0 && (
              <section className="space-y-6">
                <div className="flex items-center gap-4 mb-4">
                   <div className="w-12 h-12 bg-rose-50 rounded-2xl flex items-center justify-center text-2xl">📷</div>
                   <h3 className="text-2xl font-black text-slate-800">Recent Observations (for Clinician)</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {pendingEvents.map(event => (
                    <div key={event.id} className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 flex flex-col gap-4">
                      <div className="flex justify-between items-start">
                        <div>
                          <p className="text-[10px] font-black uppercase text-rose-600 tracking-widest">{event.source} • {event.date}</p>
                          <p className="text-sm font-bold text-slate-800 mt-1">{event.description}</p>
                        </div>
                        <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${
                          event.severity === 'High' ? 'bg-rose-100 text-rose-600' : 
                          event.severity === 'Medium' ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'
                        }`}>{event.severity}</span>
                      </div>
                      {event.media && (
                        <div className="relative aspect-video rounded-2xl overflow-hidden border border-slate-200">
                          <img src={event.media} alt="Observation" className="w-full h-full object-cover" />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </section>
            )}

            <section className="space-y-6">
              <div className="flex justify-between items-center border-b pb-4">
                 <h3 className="text-sm font-black text-amber-600 uppercase tracking-widest">Formal Diagnoses</h3>
                 <button onClick={() => setShowConditionForm(!showConditionForm)} className="text-[10px] font-black uppercase text-amber-600">+ Add Diagnosis</button>
              </div>

              {showConditionForm && (
                <div className="bg-amber-50 p-8 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-top-4">
                  <input placeholder="Diagnosis Name" value={newCondition.name} onChange={e => setNewCondition({...newCondition, name: e.target.value})} className="p-4 rounded-xl border border-amber-100" />
                  <input type="date" value={newCondition.dateDiagnosed} onChange={e => setNewCondition({...newCondition, dateDiagnosed: e.target.value})} className="p-4 rounded-xl border border-amber-100 uppercase text-xs font-black" />
                  <button 
                    onClick={() => { if(newCondition.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newCondition, id: Math.random().toString(36).substr(2, 9) } as Condition] }); setNewCondition({name: '', status: 'Active'}); setShowConditionForm(false); } }} 
                    className="md:col-span-2 py-4 bg-amber-600 text-white rounded-xl font-black text-xs uppercase"
                  >
                    Save Condition
                  </button>
                </div>
              )}

              <div className="flex flex-wrap gap-4">
                {history.conditions?.map(c => (
                  <div key={c.id} className="px-6 py-4 bg-white border border-amber-100 rounded-3xl shadow-sm flex flex-col">
                    <span className="text-lg font-black text-slate-800 tracking-tight">{c.name}</span>
                    <span className="text-[10px] text-slate-400 font-bold">Diagnosed: {c.dateDiagnosed || 'N/A'}</span>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {/* MEDICATIONS TAB */}
        {activeTab === 'meds' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <section className="space-y-6">
                <div className="flex justify-between items-center border-b pb-4">
                   <h3 className="text-sm font-black text-indigo-400 uppercase tracking-widest">Active Regimen</h3>
                   <button onClick={() => setShowActiveMedForm(!showActiveMedForm)} className="text-[10px] font-black uppercase text-indigo-600">+ Add New</button>
                </div>

                {showActiveMedForm && (
                  <div className="bg-indigo-50/50 p-8 rounded-[2.5rem] border border-indigo-100 grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-top-4">
                     <input placeholder="Drug Name" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="p-4 rounded-xl border border-slate-200 bg-white" />
                     <input placeholder="Dose (e.g. 5mL)" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="p-4 rounded-xl border border-slate-200 bg-white" />
                     <input placeholder="Instructions (e.g. BD)" value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} className="p-4 rounded-xl border border-slate-200 bg-white" />
                     <input placeholder="Indication" value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="p-4 rounded-xl border border-slate-200 bg-white" />
                     <button onClick={handleAddMed} className="md:col-span-2 py-4 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase">Confirm Active Medication</button>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {history.currentMedications.map(m => (
                    <div key={m.id} className="bg-white p-8 rounded-[2.5rem] border border-indigo-50 shadow-sm flex items-center justify-between group hover:border-indigo-100 transition-all">
                       <div className="flex items-center gap-6">
                          <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">💊</div>
                          <div>
                             <h5 className="text-lg font-black text-slate-800 tracking-tight">{m.name}</h5>
                             <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{m.dose} • {m.instructions}</p>
                             <p className="text-xs text-slate-400 mt-1">For: {m.indication}</p>
                          </div>
                       </div>
                       <button onClick={() => handleCeaseMed(m)} className="opacity-0 group-hover:opacity-100 px-4 py-2 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-xl hover:bg-rose-100 transition-all">Cease</button>
                    </div>
                  ))}
                  {history.currentMedications.length === 0 && <p className="text-slate-400 italic">No active medications logged.</p>}
                </div>
             </section>

             <section className="space-y-6">
                <h3 className="text-sm font-black text-rose-400 uppercase tracking-widest border-b pb-4">Allergies & Adverse Reactions</h3>
                <div className="flex flex-wrap gap-4">
                  {history.allergies.map((a, i) => (
                    <div key={i} className="px-6 py-3 bg-rose-50 text-rose-700 rounded-2xl text-xs font-black border border-rose-100 uppercase tracking-widest flex items-center gap-2">🚫 {a}</div>
                  ))}
                  <button onClick={() => { const a = prompt("New Allergy?"); if(a) updateHistory({ allergies: [...history.allergies, a] }); }} className="px-6 py-3 border-2 border-dashed border-slate-200 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:border-indigo-300 transition-all">+ Add Allergy</button>
                </div>
             </section>

             <section className="space-y-6">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b pb-4">Medication History (Ceased)</h3>
                <div className="space-y-4">
                  {history.previousMedications.map(m => (
                    <div key={m.id} className="bg-slate-50 p-8 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-start md:items-center border border-slate-100">
                       <div className="flex gap-6 items-center">
                          <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm grayscale opacity-50">💊</div>
                          <div>
                            <p className="text-lg font-bold text-slate-700">{m.name} <span className="text-xs font-normal opacity-60">({m.dose})</span></p>
                            <p className="text-[10px] font-black uppercase text-slate-400 mt-1">Ceased: {m.ceasedDate}</p>
                          </div>
                       </div>
                       <div className="mt-4 md:mt-0 md:text-right bg-white p-4 rounded-2xl border border-slate-100 shadow-sm min-w-[200px]">
                          <p className="text-[9px] font-black uppercase text-rose-500 tracking-widest mb-1">Reason for Ceasing</p>
                          <p className="text-xs font-bold text-slate-600 italic leading-snug">{m.ceaseReason}</p>
                       </div>
                    </div>
                  ))}
                </div>
             </section>
          </div>
        )}

        {/* REPORTS/LETTERS TAB */}
        {activeTab === 'reports' && (
          <div className="p-12 space-y-10 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-800">Specialist Correspondence</h3>
                <div className="flex gap-2">
                   <button onClick={() => setShowReportForm(!showReportForm)} className="px-6 py-3 bg-white text-slate-600 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-slate-200 hover:bg-slate-50 transition-all">{showReportForm ? 'Cancel' : '+ Manual Entry'}</button>
                   <button onClick={() => reportInputRef.current?.click()} disabled={reportLoading} className="px-6 py-3 bg-indigo-50 text-indigo-700 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-indigo-100 hover:bg-indigo-100 transition-all">{reportLoading ? 'Processing...' : 'Analyze Letter ✨'}</button>
                </div>
                <input type="file" ref={reportInputRef} onChange={handleReportUpload} className="hidden" accept="image/*" />
             </div>

             {showReportForm && (
                <div className="bg-indigo-50/50 p-10 rounded-[3rem] border border-indigo-100 space-y-6 animate-in slide-in-from-top-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <input placeholder="Specialist Name" value={newManualReport.specialist} onChange={e => setNewManualReport({...newManualReport, specialist: e.target.value})} className="p-4 rounded-2xl border border-indigo-200" />
                    <input type="date" value={newManualReport.date} onChange={e => setNewManualReport({...newManualReport, date: e.target.value})} className="p-4 rounded-2xl border border-indigo-200 font-black uppercase text-xs" />
                  </div>
                  <textarea placeholder="Visit Summary / Outcomes" value={newManualReport.summary} onChange={e => setNewManualReport({...newManualReport, summary: e.target.value})} className="w-full h-32 p-4 rounded-2xl border border-indigo-200 resize-none font-bold italic" />
                  <button onClick={() => { if(newManualReport.specialist && newManualReport.summary) { updateHistory({ medicalReports: [...(history.medicalReports || []), { ...newManualReport, id: Math.random().toString(36).substr(2, 9) } as MedicalReport] }); setShowReportForm(false); setNewManualReport({specialist: '', summary: ''}); } }} className="w-full py-5 bg-indigo-600 text-white rounded-[2rem] font-black text-xs uppercase shadow-xl">Save Record</button>
                </div>
             )}

             <div className="grid grid-cols-1 gap-6">
                {history.medicalReports?.map(report => (
                  <div key={report.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm space-y-6 hover:shadow-xl transition-all">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">✉️</div>
                        <div>
                           <h5 className="text-xl font-black text-slate-800">{report.specialist}</h5>
                           <p className="text-xs font-bold text-slate-400 italic">{report.date}</p>
                        </div>
                     </div>
                     <div className="bg-slate-50/50 p-6 rounded-[2rem] space-y-4">
                        <p className="text-sm text-slate-600 leading-relaxed font-bold italic border-l-4 border-indigo-200 pl-6">{report.summary}</p>
                        <div className="flex flex-wrap gap-2">
                           {report.actionItems.map((item, i) => <span key={i} className="px-4 py-2 bg-white rounded-xl text-[10px] font-black uppercase tracking-widest text-indigo-600 border border-indigo-50">✓ {item}</span>)}
                        </div>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {/* CARE TEAM TAB */}
        {activeTab === 'mdt' && (
          <div className="p-12 space-y-12 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center">
                <h3 className="text-2xl font-black text-slate-800">Care Team & MDT</h3>
                <button onClick={() => setShowTeamForm(!showTeamForm)} className="px-6 py-3 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase tracking-widest">{showTeamForm ? 'Cancel' : '+ Add Member'}</button>
             </div>

             {showTeamForm && (
                <div className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 space-y-6 animate-in slide-in-from-top-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <input placeholder="Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="p-4 rounded-2xl border border-emerald-200" />
                    <input placeholder="Specialty" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="p-4 rounded-2xl border border-emerald-200" />
                    <select value={newSpecialist.category} onChange={e => setNewSpecialist({...newSpecialist, category: e.target.value as any})} className="p-4 rounded-2xl border border-emerald-200 font-black">
                      <option value="Medical">Medical Specialist</option>
                      <option value="Allied Health">Allied Health / Therapy</option>
                    </select>
                  </div>
                  <button onClick={() => { if(newSpecialist.name) { updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: Math.random().toString(36).substr(2, 9) } as SpecialistContact] }); setShowTeamForm(false); setNewSpecialist({name: '', specialty: '', category: 'Medical'}); } }} className="w-full py-4 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase shadow-xl">Add to Team</button>
                </div>
             )}

             <section className="space-y-6">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest border-b pb-4">Specialists</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {medicalSpecialists.map(s => (
                    <div key={s.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:border-indigo-100 transition-all">
                       <div className="w-16 h-16 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">👨‍⚕️</div>
                       <div>
                          <h5 className="text-lg font-black text-slate-800 tracking-tight">{s.name}</h5>
                          <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest">{s.specialty}</p>
                       </div>
                    </div>
                  ))}
                </div>
             </section>

             {alliedHealthTeam.length > 0 && (
               <section className="space-y-6">
                  <h3 className="text-sm font-black text-teal-600 uppercase tracking-widest border-b pb-4">Allied Health & Therapy</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {alliedHealthTeam.map(s => (
                      <div key={s.id} className="bg-teal-50/20 p-8 rounded-[2.5rem] border border-teal-100 flex flex-col gap-4">
                         <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">🫂</div>
                            <div>
                               <h5 className="font-black text-slate-800">{s.name}</h5>
                               <p className="text-[9px] font-black text-teal-600 uppercase">{s.specialty}</p>
                            </div>
                         </div>
                      </div>
                    ))}
                  </div>
               </section>
             )}
          </div>
        )}

        {/* DEVICES/GEAR TAB */}
        {activeTab === 'gear' && (
          <div className="p-12 space-y-8 animate-in slide-in-from-right-4">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-800">Medical Equipment</h3>
                <button onClick={() => setShowGearForm(!showGearForm)} className="px-6 py-3 bg-indigo-50 text-indigo-700 rounded-2xl text-[10px] font-black uppercase tracking-widest">{showGearForm ? 'Cancel' : '+ Add Device'}</button>
             </div>

             {showGearForm && (
                <div className="bg-indigo-50/50 p-10 rounded-[3rem] border border-indigo-100 space-y-6 animate-in slide-in-from-top-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <input placeholder="Device Type (e.g. CPAP, PEG)" value={newDevice.type} onChange={e => setNewDevice({...newDevice, type: e.target.value})} className="p-4 rounded-2xl border border-indigo-200" />
                    <input placeholder="Model / Size" value={newDevice.model} onChange={e => setNewDevice({...newDevice, model: e.target.value})} className="p-4 rounded-2xl border border-indigo-200" />
                    <input type="date" value={newDevice.nextChangeDue} onChange={e => setNewDevice({...newDevice, nextChangeDue: e.target.value})} className="p-4 rounded-2xl border border-indigo-200 uppercase text-xs font-black" />
                  </div>
                  <button onClick={() => { if(newDevice.type) { updateHistory({ devices: [...(history.devices || []), { ...newDevice, id: Math.random().toString(36).substr(2, 9) } as MedicalDevice] }); setShowGearForm(false); setNewDevice({type: ''}); } }} className="w-full py-4 bg-indigo-600 text-white rounded-[2rem] font-black text-xs uppercase shadow-xl">Save Gear</button>
                </div>
             )}

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {history.devices?.map(device => (
                  <div key={device.id} className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
                     <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-2xl shadow-sm">⚙️</div>
                        <div>
                           <h5 className="font-black text-slate-800">{device.type}</h5>
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{device.model || 'Standard'}</p>
                        </div>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black text-indigo-600 uppercase">Next Change Due</p>
                        <p className="text-sm font-bold">{device.nextChangeDue || 'Manual Check'}</p>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        )}

        {/* SICK DAY PLAN TAB */}
        {activeTab === 'sickday' && (
          <div className="p-12 space-y-10 animate-in slide-in-from-right-4">
             <div className="bg-rose-600 p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-10 text-9xl">🚨</div>
                <div className="relative z-10 space-y-10">
                   <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                      <h4 className="text-4xl font-black italic tracking-tighter">Emergency Action Plan</h4>
                      <div className="flex flex-wrap gap-2">
                        {Object.keys(SICK_DAY_TEMPLATES).map(key => (
                          <button key={key} onClick={() => applySickDayTemplate(key)} className="px-5 py-2.5 bg-white/20 rounded-2xl text-[10px] font-black uppercase hover:bg-white/40 transition-all border border-white/20">Apply {key} Template</button>
                        ))}
                      </div>
                   </div>
                   <textarea 
                    value={history.sickDayPlan.instructions}
                    onChange={e => updateHistory({ sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value } })}
                    className="w-full h-[400px] p-10 rounded-[3rem] bg-white text-slate-800 font-black text-lg leading-relaxed italic shadow-2xl outline-none focus:ring-4 focus:ring-white/20"
                    placeholder="Enter urgent clinical instructions (e.g., 4x4 Asthma Protocol, Rescue Medication dosages)..."
                   />
                </div>
             </div>

             {/* Photo Management Section */}
             <section className="space-y-6">
                <div className="flex flex-col md:flex-row items-center justify-between gap-6 border-b pb-6 border-slate-100">
                  <div>
                    <h5 className="text-xl font-black text-slate-800">Physical Plan Documentation</h5>
                    <p className="text-sm text-slate-500 font-medium">Keep a copy of the official plan provided by your doctor.</p>
                  </div>
                  <div className="flex gap-3 w-full md:w-auto">
                    <input 
                      type="file" 
                      accept="image/*" 
                      capture="environment" 
                      className="hidden" 
                      ref={sickPlanPhotoRef} 
                      onChange={handleSickDayPhotoUpload} 
                    />
                    <button 
                      onClick={() => sickPlanPhotoRef.current?.click()}
                      className="flex-1 md:flex-none px-8 py-4 bg-indigo-50 text-indigo-700 rounded-2xl text-xs font-black uppercase tracking-widest border border-indigo-100 hover:bg-indigo-100 transition-all flex items-center justify-center gap-2"
                    >
                      📸 {history.sickDayPlan.planPhoto ? 'Update Photo' : 'Capture Physical Plan'}
                    </button>
                    {history.sickDayPlan.planPhoto && (
                      <button 
                        onClick={() => updateHistory({ sickDayPlan: { ...history.sickDayPlan, planPhoto: undefined } })}
                        className="px-8 py-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-black uppercase tracking-widest border border-rose-100 hover:bg-rose-100 transition-all"
                      >
                        Delete
                      </button>
                    )}
                  </div>
                </div>

                {history.sickDayPlan.planPhoto ? (
                  <div className="relative group animate-in zoom-in-95">
                    <img 
                      src={history.sickDayPlan.planPhoto} 
                      alt="Physical Emergency Plan" 
                      className="w-full h-auto rounded-[3rem] border-4 border-slate-50 shadow-2xl group-hover:brightness-95 transition-all cursor-zoom-in"
                      onClick={() => window.open(history.sickDayPlan.planPhoto)}
                    />
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                       <span className="bg-white/90 backdrop-blur-md px-6 py-3 rounded-full font-black text-indigo-600 text-xs uppercase tracking-widest shadow-xl">Click to View Full Size</span>
                    </div>
                  </div>
                ) : (
                  <div className="py-20 text-center space-y-4 border-4 border-dashed border-slate-50 rounded-[4rem] bg-slate-50/30">
                     <span className="text-6xl grayscale opacity-20 block">📄</span>
                     <p className="text-slate-400 font-black uppercase tracking-widest text-xs">No physical plan captured yet</p>
                  </div>
                )}
             </section>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] mt-12 animate-in zoom-in-95 border-l-[30px] border-l-indigo-600 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500 rounded-full opacity-10 blur-[100px]"></div>
           <div className="flex items-center justify-between mb-16 relative z-10">
              <h3 className="text-6xl font-black italic tracking-tighter text-indigo-100">ISBAR <span className="text-indigo-500">Handover</span></h3>
              <button onClick={() => {navigator.clipboard.writeText(aiAnalysis.text); alert("ISBAR Copied!");}} className="px-10 py-5 bg-indigo-600 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl border border-indigo-400">Copy to Clipboard</button>
           </div>
           <div className="relative z-10 whitespace-pre-wrap text-2xl font-bold italic leading-relaxed text-indigo-50 border-l-8 border-white/5 pl-12">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

