}

export interface GrowthRecord {
  age: number;
  weight: number;
  height: number;
  headCircumference?: number;
  date: string;
}

export interface Medication {
  id: string;
  name: string;
  dose: string;
  instructions: string;
  indication: string;
  startDate: string;
}

export interface PreviousMedication {
  id: string;
