  dose: string;
  indication: string;
  ceasedDate: string;
  ceaseReason: string;
}

export interface Vaccination {
  id: string;
  name: string;
  dueDate: Date;
  receivedDate?: Date;
  status: 'pending' | 'completed' | 'overdue';
  description: string;
  ageMilestone: number;
  manufacturer?: string;
  lotNumber?: string;
