import React, { useState, useRef } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { ClinicalEvent } from '../types';

interface SymptomCheckerProps {
  onSaveEvent?: (event: Omit<ClinicalEvent, 'id'>) => void;
}

const RED_FLAGS = [
  { text: "Difficulty breathing / Noisy breaths", icon: "🫁" },
  { text: "High fever in infants < 3mo", icon: "🌡️" },
  { text: "Lethargy / Floppiness", icon: "😴" },
  { text: "Non-blanching purple rash", icon: "🟣" },
  { text: "Eye Discharge / Swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC<SymptomCheckerProps> = ({ onSaveEvent }) => {
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = () => {
    if (result && onSaveEvent) {
      const event: Omit<ClinicalEvent, 'id'> = {
        source: 'Symptoms',
        description: description || 'Visual observation',
        date: new Date().toLocaleDateString(),
        severity: result.text.toLowerCase().includes('red') ? 'High' : 'Low',
        media: image || undefined
      };
      onSaveEvent(event);
      setSaved(true);
    }
  };

  return (
    <div className="space-y-8 pb-20">
      <header>
        <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
        <p className="text-slate-500 text-sm font-medium">Capture signs and receive guideline-based analysis.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Description</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Describe barks, rashes, or behaviors..."
                className="w-full h-40 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none"
              />
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input 
                type="file" 
                accept="image/*" 
                capture="environment" 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
              />

              <button
                onClick={() => fileInputRef.current?.click()}
                className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase tracking-widest w-full sm:w-auto transition-all ${
                  image ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-slate-500'
                }`}
              >
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>

              <button
                onClick={handleAnalyze}
                disabled={loading || (!description.trim() && !image)}
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${
                  loading ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'
                }`}
              >
                {loading ? 'Consulting Protocols...' : 'Review Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto group animate-in zoom-in-95">
                <img src={image} alt="Symptom Evidence" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button 
                  onClick={() => setImage(null)} 
                  className="absolute top-4 right-4 bg-white text-rose-500 w-8 h-8 rounded-full flex items-center justify-center shadow-xl font-black"
                >
                  ×
                </button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-l-[16px] border-l-indigo-600 animate-in slide-in-from-bottom-6">
              <div className="flex justify-between items-center mb-8">
                 <h3 className="text-2xl font-black text-slate-800 italic">AI Synthesis</h3>
                 <button 
                  onClick={handleSave}
                  disabled={saved}
                  className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg ${
                    saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700'
                  }`}
                >
                  {saved ? 'Logged' : 'Sync to Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-lg leading-relaxed">
                {result.text}
              </div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-600 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8 text-6xl opacity-10 italic font-black">!</div>
             <h3 className="text-2xl font-black italic tracking-tighter mb-6">Red Flags</h3>
             <div className="space-y-3">
                {RED_FLAGS.map((f, i) => (
                  <div key={i} className="bg-white/10 p-4 rounded-2xl flex items-center gap-3">
                    <span className="text-xl">{f.icon}</span>
                    <span className="text-xs font-bold leading-tight">{f.text}</span>
                  </div>
                ))}
             </div>
             <a href="tel:000" className="mt-8 block w-full py-4 bg-white text-rose-600 rounded-2xl text-center font-black text-2xl shadow-xl active:scale-95 transition-transform">CALL 000</a>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { MedicalHistory, Medication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  pendingEvents?: ClinicalEvent[];
  attachmentData?: AttachmentAnalysis;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "AUSTRALIAN 4x4 PROTOCOL:\n1. Give 4 puffs of blue reliever (Salbutamol) via spacer.\n2. 1 puff at a time with 4 breaths each.\n3. Wait 4 minutes.\n4. If no improvement, repeat 4x4.\n\nCALL 000 IF:\n- Child is distressed or can't talk in sentences.\n- Skin is sucking in at ribs/neck.\n- Lips are blue.",
    triggers: "Viral colds, exercise, smoke, dust mites, weather changes.",
    emergencyMeds: "Salbutamol 100mcg (Ventolin/Asmol) via spacer.",
    fluidRequirements: "Encourage small, frequent sips. Monitor hydration if work of breathing is high.",
    emergencyContact: "GP Clinic or 000"
  },
  seizure: {
    instructions: "1. Stay calm and time the seizure.\n2. Protect from injury (move hard objects).\n3. Place on side once jerking stops.\n\nCALL 000 IF:\n- Seizure lasts > 5 mins.\n- First ever seizure.\n- Child is injured or having trouble breathing.",
    triggers: "Fever, illness, fatigue, missed medication.",
    emergencyMeds: "Midazolam (as per specialist protocol) / Buccal dosage as prescribed.",
    fluidRequirements: "No fluids until child is fully alert and awake.",
    emergencyContact: "Neurology Liaison / 000"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [editingEventId, setEditingEventId] = useState<string | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);
  const eventPhotoRef = useRef<HTMLInputElement>(null);

  // Form Visibility States
  const [showConditionForm, setShowConditionForm] = useState(false);
  const [showActiveMedForm, setShowActiveMedForm] = useState(false);
  const [showTeamForm, setShowTeamForm] = useState(false);
  const [showGearForm, setShowGearForm] = useState(false);

  // New Item States
  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active', dateDiagnosed: '' });
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: new Date().toISOString().split('T')[0] });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', nextChangeDue: '', notes: '' });

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist.name,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ 
            medicalReports: [...(history.medicalReports || []), newReport]
          });
          alert(`Report Sync Complete! Specialist: ${result.specialist.name}`);
        } catch (err) {
          console.error(err);
          alert("Failed to analyze report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEventPhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && editingEventId) {
      const reader = new FileReader();
      reader.onloadend = () => {
        alert("Photo capture recorded for ID: " + editingEventId);
        setEditingEventId(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addItem = (category: string) => {
    if (category === 'condition' && newCondition.name) {
      updateHistory({ conditions: [...(history.conditions || []), { ...newCondition, id: Math.random().toString(36).substr(2, 9) } as Condition] });
      setNewCondition({ name: '', status: 'Active', dateDiagnosed: '' });
      setShowConditionForm(false);
    } else if (category === 'med' && newMed.name) {
      updateHistory({ currentMedications: [...(history.currentMedications || []), { ...newMed, id: Math.random().toString(36).substr(2, 9) } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: new Date().toISOString().split('T')[0] });
      setShowActiveMedForm(false);
    } else if (category === 'team' && newSpecialist.name) {
      updateHistory({ specialists: [...(history.specialists || []), { ...newSpecialist, id: Math.random().toString(36).substr(2, 9) } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
      setShowTeamForm(false);
    } else if (category === 'gear' && newDevice.type) {
      updateHistory({ devices: [...(history.devices || []), { ...newDevice, id: Math.random().toString(36).substr(2, 9) } as MedicalDevice] });
      setNewDevice({ type: '', model: '', nextChangeDue: '', notes: '' });
      setShowGearForm(false);
    }
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ sickDayPlan: { ...history.sickDayPlan, ...template } });
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'sickday', label: 'Sick Day', icon: '🚨' }
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 text-sm font-medium">Your child's longitudinal clinical repository.</p>
        </div>
        <button 
          onClick={handleGenerateHandover}
          disabled={loading}
          className="bg-indigo-600 text-white px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center gap-2"
        >
          {loading ? 'Analyzing...' : 'Generate ISBAR Handover ✨'}
        </button>
      </header>

      <input type="file" accept="image/*" capture="environment" ref={eventPhotoRef} onChange={handleEventPhotoCapture} className="hidden" />
      <input type="file" accept="image/*" ref={reportInputRef} onChange={handleReportUpload} className="hidden" />

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-2 overflow-x-auto no-scrollbar">
        <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex min-w-max">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-6 py-3 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center gap-2 transition-all ${
                activeTab === tab.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <span className="text-lg">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-8 space-y-10">
            <section className="space-y-6">
              <div className="flex justify-between items-center">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                  <span className="text-emerald-500">🧬</span> Active Conditions
                </h3>
                <button onClick={() => setShowConditionForm(true)} className="px-4 py-2 bg-emerald-50 text-emerald-600 rounded-xl text-[10px] font-black uppercase">Add Condition</button>
              </div>
              {showConditionForm && (
                <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                  <input placeholder="Condition Name" value={newCondition.name} onChange={e => setNewCondition({...newCondition, name: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <input type="date" value={newCondition.dateDiagnosed} onChange={e => setNewCondition({...newCondition, dateDiagnosed: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                    <select value={newCondition.status} onChange={e => setNewCondition({...newCondition, status: e.target.value as any})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold">
                      <option>Active</option>
                      <option>Resolved</option>
                      <option>Under Investigation</option>
                    </select>
                  </div>
                  <button onClick={() => addItem('condition')} className="w-full py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase">Save Condition</button>
                </div>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(history.conditions || []).map(c => (
                  <div key={c.id} className="p-6 bg-emerald-50/30 rounded-3xl border border-emerald-100 flex items-center justify-between">
                    <div>
                      <h4 className="font-black text-emerald-900">{c.name}</h4>
                      <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Since {c.dateDiagnosed || 'Unknown'} • {c.status}</p>
                    </div>
                  </div>
                ))}
              </div>
            </section>

            <section className="space-y-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <span className="text-indigo-600">📜</span> Narrative & Birth Story
              </h3>
              <textarea 
                value={history.pastMedicalHistory}
                onChange={e => updateHistory({ pastMedicalHistory: e.target.value })}
                className="w-full h-48 p-6 rounded-3xl border border-slate-100 bg-slate-50/50 outline-none text-slate-700 font-bold italic shadow-inner focus:ring-2 focus:ring-indigo-100 resize-none"
                placeholder="Birth weight, gestation, early milestones..."
              />
            </section>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <span className="text-rose-500">📸</span> Clinical Observations
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {pendingEvents.map(event => (
                  <div key={event.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 relative group overflow-hidden">
                    <div className="flex justify-between items-start mb-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{event.date} • {event.source}</p>
                        <p className="text-sm font-bold text-slate-800 leading-tight">{event.description}</p>
                      </div>
                      <div className="flex gap-2">
                         <button onClick={() => { setEditingEventId(event.id); eventPhotoRef.current?.click(); }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-indigo-600 border border-indigo-50 shadow-sm active:scale-95 transition-transform">📷</button>
                         <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase ${event.severity === 'High' ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>{event.severity}</span>
                      </div>
                    </div>
                    {event.media ? (
                      <div className="relative h-40 rounded-2xl overflow-hidden border border-slate-200">
                        <img src={event.media} alt="Observation" className="w-full h-full object-cover" />
                      </div>
                    ) : (
                      <div className="h-40 bg-slate-100 rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center gap-2">
                         <span className="text-2xl opacity-20">🖼️</span>
                         <p className="text-[9px] font-black text-slate-300 uppercase">No visual log</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
               <h3 className="text-xl font-black text-slate-800">Active Regimen</h3>
               <button onClick={() => setShowActiveMedForm(true)} className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[10px] font-black uppercase">Add Med</button>
            </div>
            {showActiveMedForm && (
                <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                  <input placeholder="Medication Name" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <input placeholder="Dose (e.g. 5ml)" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                    <input placeholder="Indication" value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                  </div>
                  <textarea placeholder="Instructions" value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                  <button onClick={() => addItem('med')} className="w-full py-3 bg-rose-600 text-white rounded-xl text-[10px] font-black uppercase">Save Medication</button>
                </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {history.currentMedications.map(m => (
                 <div key={m.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-between">
                    <div>
                      <h4 className="font-black text-slate-800">{m.name}</h4>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{m.dose} • {m.instructions}</p>
                    </div>
                    <span className="text-2xl">💊</span>
                 </div>
               ))}
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">Clinical Letters & Reports</h3>
              <button onClick={() => reportInputRef.current?.click()} className="px-6 py-3 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl flex items-center gap-2">
                {reportLoading ? 'Analyzing...' : 'Upload & Sync ✨'}
              </button>
            </div>
            <div className="grid grid-cols-1 gap-4">
              {(history.medicalReports || []).map(report => (
                <div key={report.id} className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-1">{report.date} • {report.specialist}</p>
                      <h4 className="text-xl font-black text-slate-800 italic">{report.summary}</h4>
                    </div>
                    <button className="text-indigo-600 text-xs font-black uppercase tracking-widest">View Details</button>
                  </div>
                  {report.actionItems && report.actionItems.length > 0 && (
                    <div className="pt-4 border-t border-slate-200">
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Key Actions</p>
                      <div className="space-y-1">
                        {report.actionItems.map((item, idx) => (
                          <p key={idx} className="text-xs font-bold text-slate-600 flex items-center gap-2">• {item}</p>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              ))}
              {(history.medicalReports || []).length === 0 && (
                <div className="py-20 text-center opacity-20 flex flex-col items-center">
                  <span className="text-6xl mb-4">📂</span>
                  <p className="font-black text-sm uppercase tracking-widest">No reports archived</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'mdt' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">Care Team (MDT)</h3>
              <button onClick={() => setShowTeamForm(true)} className="px-4 py-2 bg-teal-50 text-teal-600 rounded-xl text-[10px] font-black uppercase">Add Specialist</button>
            </div>
            {showTeamForm && (
              <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                <input placeholder="Provider Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                <div className="grid grid-cols-2 gap-4">
                  <input placeholder="Specialty" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                  <input placeholder="Hospital/Clinic" value={newSpecialist.hospital} onChange={e => setNewSpecialist({...newSpecialist, hospital: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                </div>
                <button onClick={() => addItem('team')} className="w-full py-3 bg-teal-600 text-white rounded-xl text-[10px] font-black uppercase">Save Specialist</button>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(history.specialists || []).map(s => (
                <div key={s.id} className="p-6 bg-white rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center text-2xl">🩺</div>
                    <div>
                      <h4 className="font-black text-slate-800">{s.name}</h4>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{s.specialty} • {s.hospital || 'Private Clinic'}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'gear' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">Medical Gear & Devices</h3>
              <button onClick={() => setShowGearForm(true)} className="px-4 py-2 bg-amber-50 text-amber-600 rounded-xl text-[10px] font-black uppercase">Add Device</button>
            </div>
            {showGearForm && (
              <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                <input placeholder="Device Type (e.g. NG Tube)" value={newDevice.type} onChange={e => setNewDevice({...newDevice, type: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                <div className="grid grid-cols-2 gap-4">
                  <input placeholder="Model/Brand" value={newDevice.model} onChange={e => setNewDevice({...newDevice, model: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                  <input type="date" value={newDevice.nextChangeDue} onChange={e => setNewDevice({...newDevice, nextChangeDue: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                </div>
                <button onClick={() => addItem('gear')} className="w-full py-3 bg-amber-600 text-white rounded-xl text-[10px] font-black uppercase">Save Device</button>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(history.devices || []).map(d => (
                <div key={d.id} className="p-6 bg-amber-50/20 rounded-3xl border border-amber-100 flex items-center justify-between">
                  <div>
                    <h4 className="font-black text-slate-800">{d.type}</h4>
                    <p className="text-[10px] font-bold text-amber-600 uppercase tracking-widest">{d.model} • Due: {d.nextChangeDue || '--'}</p>
                  </div>
                  <span className="text-2xl">⚙️</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-8 space-y-10">
             <div className="bg-rose-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 text-8xl opacity-10 pointer-events-none italic">🚨</div>
                <div className="relative z-10 space-y-6">
                   <h3 className="text-3xl font-black italic tracking-tighter">Emergency Protocol</h3>
                   <div className="flex gap-2">
                      <button onClick={() => applySickDayTemplate('asthma')} className="px-4 py-2 bg-white/20 rounded-xl text-[10px] font-black uppercase border border-white/20">Asthma 4x4</button>
                      <button onClick={() => applySickDayTemplate('seizure')} className="px-4 py-2 bg-white/20 rounded-xl text-[10px] font-black uppercase border border-white/20">Seizure Plan</button>
                   </div>
                   <textarea 
                    value={history.sickDayPlan.instructions}
                    onChange={e => updateHistory({ sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value } })}
                    className="w-full h-64 p-8 rounded-[2.5rem] bg-white text-slate-800 font-bold text-lg md:text-xl leading-relaxed italic shadow-2xl outline-none"
                    placeholder="Enter sick day instructions here..."
                   />
                </div>
             </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-10 rounded-[3rem] text-white shadow-2xl animate-in zoom-in-95 border-l-[16px] border-l-indigo-600">
           <h3 className="text-3xl font-black italic tracking-tighter mb-8 text-indigo-100">ISBAR Handover</h3>
           <div className="whitespace-pre-wrap text-lg font-bold italic leading-relaxed text-indigo-50 border-l-4 border-white/10 pl-8">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  pendingEvents?: ClinicalEvent[];
  attachmentData?: AttachmentAnalysis;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "AUSTRALIAN 4x4 PROTOCOL:\n1. Give 4 puffs of blue reliever (Salbutamol) via spacer.\n2. 1 puff at a time with 4 breaths each.\n3. Wait 4 minutes.\n4. If no improvement, repeat 4x4.\n\nCALL 000 IF:\n- Child is distressed or can't talk in sentences.\n- Skin is sucking in at ribs/neck.\n- Lips are blue.",
    triggers: "Viral colds, exercise, smoke, dust mites, weather changes.",
    emergencyMeds: "Salbutamol 100mcg (Ventolin/Asmol) via spacer.",
    fluidRequirements: "Encourage small, frequent sips. Monitor hydration if work of breathing is high.",
    emergencyContact: "GP Clinic or 000"
  },
  seizure: {
    instructions: "1. Stay calm and time the seizure.\n2. Protect from injury (move hard objects).\n3. Place on side once jerking stops.\n\nCALL 000 IF:\n- Seizure lasts > 5 mins.\n- First ever seizure.\n- Child is injured or having trouble breathing.",
    triggers: "Fever, illness, fatigue, missed medication.",
    emergencyMeds: "Midazolam (as per specialist protocol) / Buccal dosage as prescribed.",
    fluidRequirements: "No fluids until child is fully alert and awake.",
    emergencyContact: "Neurology Liaison / 000"
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [editingEventId, setEditingEventId] = useState<string | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);
  const eventPhotoRef = useRef<HTMLInputElement>(null);

  // Form Visibility States
  const [showConditionForm, setShowConditionForm] = useState(false);
  const [showActiveMedForm, setShowActiveMedForm] = useState(false);
  const [showPrevMedForm, setShowPrevMedForm] = useState(false);
  const [showTeamForm, setShowTeamForm] = useState(false);
  const [showGearForm, setShowGearForm] = useState(false);

  // New Item States
  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active', dateDiagnosed: '' });
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: new Date().toISOString().split('T')[0] });
  const [newPrevMed, setNewPrevMed] = useState<Partial<PreviousMedication>>({ name: '', dose: '', indication: '', ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', nextChangeDue: '', notes: '' });

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist.name,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ 
            medicalReports: [...(history.medicalReports || []), newReport]
          });
          alert(`Report Sync Complete! Specialist: ${result.specialist.name}`);
        } catch (err) {
          console.error(err);
          alert("Failed to analyze report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEventPhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && editingEventId) {
      const reader = new FileReader();
      reader.onloadend = () => {
        alert("Photo capture recorded for ID: " + editingEventId);
        setEditingEventId(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addItem = (category: string) => {
    if (category === 'condition' && newCondition.name) {
      updateHistory({ conditions: [...(history.conditions || []), { ...newCondition, id: Math.random().toString(36).substr(2, 9) } as Condition] });
      setNewCondition({ name: '', status: 'Active', dateDiagnosed: '' });
      setShowConditionForm(false);
    } else if (category === 'med' && newMed.name) {
      updateHistory({ currentMedications: [...(history.currentMedications || []), { ...newMed, id: Math.random().toString(36).substr(2, 9) } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: new Date().toISOString().split('T')[0] });
      setShowActiveMedForm(false);
    } else if (category === 'prevMed' && newPrevMed.name) {
      updateHistory({ previousMedications: [...(history.previousMedications || []), { ...newPrevMed, id: Math.random().toString(36).substr(2, 9) } as PreviousMedication] });
      setNewPrevMed({ name: '', dose: '', indication: '', ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: '' });
      setShowPrevMedForm(false);
    } else if (category === 'team' && newSpecialist.name) {
      updateHistory({ specialists: [...(history.specialists || []), { ...newSpecialist, id: Math.random().toString(36).substr(2, 9) } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
      setShowTeamForm(false);
    } else if (category === 'gear' && newDevice.type) {
      updateHistory({ devices: [...(history.devices || []), { ...newDevice, id: Math.random().toString(36).substr(2, 9) } as MedicalDevice] });
      setNewDevice({ type: '', model: '', nextChangeDue: '', notes: '' });
      setShowGearForm(false);
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}?`);
    if (reason === null) return;

    const ceasedDate = new Date().toISOString().split('T')[0];
    const prevMed: PreviousMedication = {
      id: med.id,
      name: med.name,
      dose: med.dose,
      indication: med.indication,
      ceasedDate,
      ceaseReason: reason
    };

    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), prevMed]
    });
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ sickDayPlan: { ...history.sickDayPlan, ...template } });
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'sickday', label: 'Sick Day', icon: '🚨' }
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 text-sm font-medium">Your child's longitudinal clinical repository.</p>
        </div>
        <button 
          onClick={handleGenerateHandover}
          disabled={loading}
          className="bg-indigo-600 text-white px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center gap-2"
        >
          {loading ? 'Analyzing...' : 'Generate ISBAR Handover ✨'}
        </button>
      </header>

      <input type="file" accept="image/*" capture="environment" ref={eventPhotoRef} onChange={handleEventPhotoCapture} className="hidden" />
      <input type="file" accept="image/*" ref={reportInputRef} onChange={handleReportUpload} className="hidden" />

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-2 overflow-x-auto no-scrollbar">
        <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex min-w-max">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-6 py-3 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center gap-2 transition-all ${
                activeTab === tab.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <span className="text-lg">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl min-h-[500px]">
        {activeTab === 'history' && (
          <div className="p-8 space-y-10">
            <section className="space-y-6">
              <div className="flex justify-between items-center">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                  <span className="text-emerald-500">🧬</span> Active Conditions
                </h3>
                <button onClick={() => setShowConditionForm(true)} className="px-4 py-2 bg-emerald-50 text-emerald-600 rounded-xl text-[10px] font-black uppercase">Add Condition</button>
              </div>
              {showConditionForm && (
                <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                  <input placeholder="Condition Name" value={newCondition.name} onChange={e => setNewCondition({...newCondition, name: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <input type="date" value={newCondition.dateDiagnosed} onChange={e => setNewCondition({...newCondition, dateDiagnosed: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                    <select value={newCondition.status} onChange={e => setNewCondition({...newCondition, status: e.target.value as any})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold">
                      <option>Active</option>
                      <option>Resolved</option>
                      <option>Under Investigation</option>
                    </select>
                  </div>
                  <button onClick={() => addItem('condition')} className="w-full py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase">Save Condition</button>
                </div>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(history.conditions || []).map(c => (
                  <div key={c.id} className="p-6 bg-emerald-50/30 rounded-3xl border border-emerald-100 flex items-center justify-between">
                    <div>
                      <h4 className="font-black text-emerald-900">{c.name}</h4>
                      <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Since {c.dateDiagnosed || 'Unknown'} • {c.status}</p>
                    </div>
                  </div>
                ))}
              </div>
            </section>

            <section className="space-y-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <span className="text-indigo-600">📜</span> Narrative & Birth Story
              </h3>
              <textarea 
                value={history.pastMedicalHistory}
                onChange={e => updateHistory({ pastMedicalHistory: e.target.value })}
                className="w-full h-48 p-6 rounded-3xl border border-slate-100 bg-slate-50/50 outline-none text-slate-700 font-bold italic shadow-inner focus:ring-2 focus:ring-indigo-100 resize-none"
                placeholder="Birth weight, gestation, early milestones..."
              />
            </section>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <span className="text-rose-500">📸</span> Clinical Observations
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {pendingEvents.map(event => (
                  <div key={event.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 relative group overflow-hidden">
                    <div className="flex justify-between items-start mb-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{event.date} • {event.source}</p>
                        <p className="text-sm font-bold text-slate-800 leading-tight">{event.description}</p>
                      </div>
                      <div className="flex gap-2">
                         <button onClick={() => { setEditingEventId(event.id); eventPhotoRef.current?.click(); }} className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-indigo-600 border border-indigo-50 shadow-sm active:scale-95 transition-transform">📷</button>
                         <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase ${event.severity === 'High' ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>{event.severity}</span>
                      </div>
                    </div>
                    {event.media ? (
                      <div className="relative h-40 rounded-2xl overflow-hidden border border-slate-200">
                        <img src={event.media} alt="Observation" className="w-full h-full object-cover" />
                      </div>
                    ) : (
                      <div className="h-40 bg-slate-100 rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center gap-2">
                         <span className="text-2xl opacity-20">🖼️</span>
                         <p className="text-[9px] font-black text-slate-300 uppercase">No visual log</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="p-8 space-y-12">
            {/* Active Medications Section */}
            <section className="space-y-6">
              <div className="flex justify-between items-center">
                 <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                    <span className="text-rose-600">💊</span> Active Regimen
                 </h3>
                 <button onClick={() => setShowActiveMedForm(!showActiveMedForm)} className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest">
                   {showActiveMedForm ? 'Cancel' : 'Add Medication'}
                 </button>
              </div>
              {showActiveMedForm && (
                  <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-200 space-y-6 animate-in zoom-in-95 shadow-inner">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Medication Name</label>
                        <input placeholder="e.g. Salbutamol" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Indication</label>
                        <input placeholder="e.g. Asthma" value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Dose</label>
                        <input placeholder="e.g. 2 puffs" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Start Date</label>
                        <input type="date" value={newMed.startDate} onChange={e => setNewMed({...newMed, startDate: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Instructions</label>
                      <textarea placeholder="e.g. Daily via spacer" value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-xs font-bold resize-none h-24" />
                    </div>
                    <button onClick={() => addItem('med')} className="w-full py-4 bg-rose-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl transition-all active:scale-95">Save Active Medication</button>
                  </div>
              )}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {history.currentMedications.map(m => (
                   <div key={m.id} className="p-6 bg-white rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-rose-100 transition-all">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center text-2xl">💊</div>
                        <div>
                          <h4 className="font-black text-slate-800">{m.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-tight">{m.dose} • {m.instructions}</p>
                          <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.1em] mt-1">Started: {m.startDate || 'Unknown'}</p>
                        </div>
                      </div>
                      <button onClick={() => ceaseMedication(m)} className="opacity-0 group-hover:opacity-100 px-3 py-1.5 bg-rose-100 text-rose-600 rounded-lg text-[9px] font-black uppercase tracking-widest transition-opacity">Cease</button>
                   </div>
                 ))}
                 {history.currentMedications.length === 0 && !showActiveMedForm && (
                   <div className="col-span-full py-12 text-center opacity-20 italic font-black uppercase tracking-widest text-sm">No active medications</div>
                 )}
              </div>
            </section>

            {/* Previous Medications Section */}
            <section className="space-y-6 pt-8 border-t border-slate-100">
               <div className="flex justify-between items-center">
                  <h3 className="text-xl font-black text-slate-500 flex items-center gap-2">
                     <span className="text-slate-400">⏳</span> Previous Medications
                  </h3>
                  <button onClick={() => setShowPrevMedForm(!showPrevMedForm)} className="px-4 py-2 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase tracking-widest">
                    {showPrevMedForm ? 'Cancel' : 'Add History'}
                  </button>
               </div>
               {showPrevMedForm && (
                  <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-200 space-y-6 animate-in zoom-in-95 shadow-inner">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Medication Name</label>
                        <input placeholder="Medication" value={newPrevMed.name} onChange={e => setNewPrevMed({...newPrevMed, name: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Indication</label>
                        <input placeholder="e.g. Fever" value={newPrevMed.indication} onChange={e => setNewPrevMed({...newPrevMed, indication: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Dose</label>
                        <input placeholder="e.g. 5ml" value={newPrevMed.dose} onChange={e => setNewPrevMed({...newPrevMed, dose: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Ceased Date</label>
                        <input type="date" value={newPrevMed.ceasedDate} onChange={e => setNewPrevMed({...newPrevMed, ceasedDate: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-sm font-bold" />
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Reason for Ceasing</label>
                      <textarea placeholder="e.g. Side effects, completed course, no longer required..." value={newPrevMed.ceaseReason} onChange={e => setNewPrevMed({...newPrevMed, ceaseReason: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-200 text-xs font-bold resize-none h-24" />
                    </div>
                    <button onClick={() => addItem('prevMed')} className="w-full py-4 bg-slate-400 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl transition-all active:scale-95">Save to History</button>
                  </div>
               )}
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {(history.previousMedications || []).map(m => (
                    <div key={m.id} className="p-6 bg-slate-50/50 rounded-3xl border border-slate-100 flex items-start gap-4 transition-all opacity-80 hover:opacity-100">
                      <div className="w-10 h-10 bg-slate-100 text-slate-400 rounded-xl flex items-center justify-center text-xl shrink-0">🥣</div>
                      <div className="flex-1 min-w-0">
                        <h4 className="font-black text-slate-600 truncate">{m.name}</h4>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest truncate">{m.dose} • {m.indication}</p>
                        <div className="mt-3 p-3 bg-white rounded-xl border border-slate-50">
                           <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-1">Outcome</p>
                           <p className="text-xs font-bold text-slate-500 italic leading-snug">Ceased {m.ceasedDate}: {m.ceaseReason}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                  {(history.previousMedications || []).length === 0 && !showPrevMedForm && (
                     <div className="col-span-full py-12 text-center opacity-20 italic font-black uppercase tracking-widest text-sm">No historical records</div>
                  )}
               </div>
            </section>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">Clinical Letters & Reports</h3>
              <button onClick={() => reportInputRef.current?.click()} className="px-6 py-3 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl flex items-center gap-2">
                {reportLoading ? 'Analyzing...' : 'Upload & Sync ✨'}
              </button>
            </div>
            <div className="grid grid-cols-1 gap-4">
              {(history.medicalReports || []).map(report => (
                <div key={report.id} className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-1">{report.date} • {report.specialist}</p>
                      <h4 className="text-xl font-black text-slate-800 italic">{report.summary}</h4>
                    </div>
                    <button className="text-indigo-600 text-xs font-black uppercase tracking-widest">View Details</button>
                  </div>
                  {report.actionItems && report.actionItems.length > 0 && (
                    <div className="pt-4 border-t border-slate-200">
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Key Actions</p>
                      <div className="space-y-1">
                        {report.actionItems.map((item, idx) => (
                          <p key={idx} className="text-xs font-bold text-slate-600 flex items-center gap-2">• {item}</p>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              ))}
              {(history.medicalReports || []).length === 0 && (
                <div className="py-20 text-center opacity-20 flex flex-col items-center">
                  <span className="text-6xl mb-4">📂</span>
                  <p className="font-black text-sm uppercase tracking-widest">No reports archived</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'mdt' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">Care Team (MDT)</h3>
              <button onClick={() => setShowTeamForm(true)} className="px-4 py-2 bg-teal-50 text-teal-600 rounded-xl text-[10px] font-black uppercase">Add Specialist</button>
            </div>
            {showTeamForm && (
              <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                <input placeholder="Provider Name" value={newSpecialist.name} onChange={e => setNewSpecialist({...newSpecialist, name: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                <div className="grid grid-cols-2 gap-4">
                  <input placeholder="Specialty" value={newSpecialist.specialty} onChange={e => setNewSpecialist({...newSpecialist, specialty: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                  <input placeholder="Hospital/Clinic" value={newSpecialist.hospital} onChange={e => setNewSpecialist({...newSpecialist, hospital: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                </div>
                <button onClick={() => addItem('team')} className="w-full py-3 bg-teal-600 text-white rounded-xl text-[10px] font-black uppercase">Save Specialist</button>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(history.specialists || []).map(s => (
                <div key={s.id} className="p-6 bg-white rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center text-2xl">🩺</div>
                    <div>
                      <h4 className="font-black text-slate-800">{s.name}</h4>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{s.specialty} • {s.hospital || 'Private Clinic'}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'gear' && (
          <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">Medical Gear & Devices</h3>
              <button onClick={() => setShowGearForm(true)} className="px-4 py-2 bg-amber-50 text-amber-600 rounded-xl text-[10px] font-black uppercase">Add Device</button>
            </div>
            {showGearForm && (
              <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-200 space-y-4 animate-in zoom-in-95">
                <input placeholder="Device Type (e.g. NG Tube)" value={newDevice.type} onChange={e => setNewDevice({...newDevice, type: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                <div className="grid grid-cols-2 gap-4">
                  <input placeholder="Model/Brand" value={newDevice.model} onChange={e => setNewDevice({...newDevice, model: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                  <input type="date" value={newDevice.nextChangeDue} onChange={e => setNewDevice({...newDevice, nextChangeDue: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                </div>
                <button onClick={() => addItem('gear')} className="w-full py-3 bg-amber-600 text-white rounded-xl text-[10px] font-black uppercase">Save Device</button>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(history.devices || []).map(d => (
                <div key={d.id} className="p-6 bg-amber-50/20 rounded-3xl border border-amber-100 flex items-center justify-between">
                  <div>
                    <h4 className="font-black text-slate-800">{d.type}</h4>
                    <p className="text-[10px] font-bold text-amber-600 uppercase tracking-widest">{d.model} • Due: {d.nextChangeDue || '--'}</p>
                  </div>
                  <span className="text-2xl">⚙️</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'sickday' && (
          <div className="p-8 space-y-10">
             <div className="bg-rose-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 text-8xl opacity-10 pointer-events-none italic">🚨</div>
                <div className="relative z-10 space-y-6">
                   <h3 className="text-3xl font-black italic tracking-tighter">Emergency Protocol</h3>
                   <div className="flex gap-2">
                      <button onClick={() => applySickDayTemplate('asthma')} className="px-4 py-2 bg-white/20 rounded-xl text-[10px] font-black uppercase border border-white/20">Asthma 4x4</button>
                      <button onClick={() => applySickDayTemplate('seizure')} className="px-4 py-2 bg-white/20 rounded-xl text-[10px] font-black uppercase border border-white/20">Seizure Plan</button>
                   </div>
                   <textarea 
                    value={history.sickDayPlan.instructions}
                    onChange={e => updateHistory({ sickDayPlan: { ...history.sickDayPlan, instructions: e.target.value } })}
                    className="w-full h-64 p-8 rounded-[2.5rem] bg-white text-slate-800 font-bold text-lg md:text-xl leading-relaxed italic shadow-2xl outline-none"
                    placeholder="Enter sick day instructions here..."
                   />
                </div>
             </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-10 rounded-[3rem] text-white shadow-2xl animate-in zoom-in-95 border-l-[16px] border-l-indigo-600">
           <h3 className="text-3xl font-black italic tracking-tighter mb-8 text-indigo-100">ISBAR Handover</h3>
           <div className="whitespace-pre-wrap text-lg font-bold italic leading-relaxed text-indigo-50 border-l-4 border-white/10 pl-8">
            {aiAnalysis.text}
           </div>
        </div>
      )}
    </div>
  );
};

