export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting' | 'setup' | 'bonding' | 'acutelogs' | 'appointments';

import React, { useState, useRef } from 'react';
import { MedicalHistory, Medication, PreviousMedication, SpecialistContact, MedicalDevice, SickDayPlan, AttachmentAnalysis, ClinicalEvent, MedicalReport, Condition } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';

interface MedicalProfileProps {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  pendingEvents?: ClinicalEvent[];
  attachmentData?: AttachmentAnalysis;
}

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "AUSTRALIAN 4x4 PROTOCOL:\n1. Give 4 puffs of blue reliever (Salbutamol) via spacer.\n2. 1 puff at a time with 4 breaths each.\n3. Wait 4 minutes.\n4. If no improvement, repeat 4x4.",
    triggers: "Viral colds, exercise, cigarette smoke, dust mites, weather changes, animal dander.",
    emergencyMeds: "Salbutamol 100mcg (Ventolin/Asmol) via spacer (MDI). Ensure spacer is clean and dry.",
    fluidRequirements: "Encourage small, frequent sips. Monitor for high work of breathing during hydration.",
    emergencyContact: "GP Clinic, HealthDirect (1800 022 222), or 000 if child cannot speak in full sentences."
  },
  seizure: {
    instructions: "1. Stay calm and time the seizure.\n2. Protect from injury (clear objects).\n3. Do not put anything in mouth.\n4. Place on side once jerking stops.",
    triggers: "High fever (febrile convulsion), illness, fatigue, flashing lights, missed medication.",
    emergencyMeds: "Midazolam (as per specialist seizure management plan) / Buccal dosage as prescribed.",
    fluidRequirements: "Nothing by mouth until child is fully alert, awake, and back to baseline.",
    emergencyContact: "Neurology Liaison, Treating Specialist, or 000 if seizure lasts more than 5 minutes."
  }
};

export const MedicalProfile: React.FC<MedicalProfileProps> = ({ 
  history, 
  updateHistory, 
  pendingEvents = [], 
  attachmentData 
}) => {
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [editingEventId, setEditingEventId] = useState<string | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);
  const eventPhotoRef = useRef<HTMLInputElement>(null);

  // Form Visibility States
  const [showConditionForm, setShowConditionForm] = useState(false);
  const [showActiveMedForm, setShowActiveMedForm] = useState(false);
  const [showPrevMedForm, setShowPrevMedForm] = useState(false);
  const [showTeamForm, setShowTeamForm] = useState(false);
  const [showGearForm, setShowGearForm] = useState(false);

  // New Item States
  const [newCondition, setNewCondition] = useState<Partial<Condition>>({ name: '', status: 'Active', dateDiagnosed: '' });
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '', startDate: new Date().toISOString().split('T')[0] });
  const [newPrevMed, setNewPrevMed] = useState<Partial<PreviousMedication>>({ name: '', dose: '', indication: '', startDate: '', ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', nextChangeDue: '', notes: '' });

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          const newReport: MedicalReport = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString(),
            specialist: result.specialist.name,
            summary: result.summary,
            actionItems: result.actionItems,
            photoUrl: reader.result as string
          };
          updateHistory({ 
            medicalReports: [...(history.medicalReports || []), newReport]
          });
          alert(`Report Sync Complete! Specialist: ${result.specialist.name}`);
        } catch (err) {
          console.error(err);
          alert("Failed to analyze report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEventPhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && editingEventId) {
      const reader = new FileReader();
      reader.onloadend = () => {
        alert("Photo capture recorded for ID: " + editingEventId);
        setEditingEventId(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, attachment: attachmentData });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addItem = (category: string) => {
    if (category === 'condition' && newCondition.name) {
      updateHistory({ conditions: [...(history.conditions || []), { ...newCondition, id: Math.random().toString(36).substr(2, 9) } as Condition] });
      setNewCondition({ name: '', status: 'Active', dateDiagnosed: '' });
      setShowConditionForm(false);
    } else if (category === 'med' && newMed.name) {
      updateHistory({ currentMedications: [...(history.currentMedications || []), { ...newMed, id: Math.random().toString(36).substr(2, 9) } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '', startDate: new Date().toISOString().split('T')[0] });
      setShowActiveMedForm(false);
    } else if (category === 'prevMed' && newPrevMed.name) {
      updateHistory({ previousMedications: [...(history.previousMedications || []), { ...newPrevMed, id: Math.random().toString(36).substr(2, 9) } as PreviousMedication] });
      setNewPrevMed({ name: '', dose: '', indication: '', startDate: '', ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: '' });
      setShowPrevMedForm(false);
    } else if (category === 'team' && newSpecialist.name) {
      updateHistory({ specialists: [...(history.specialists || []), { ...newSpecialist, id: Math.random().toString(36).substr(2, 9) } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', category: 'Medical', hospital: '', goals: '' });
      setShowTeamForm(false);
    } else if (category === 'gear' && newDevice.type) {
      updateHistory({ devices: [...(history.devices || []), { ...newDevice, id: Math.random().toString(36).substr(2, 9) } as MedicalDevice] });
      setNewDevice({ type: '', model: '', nextChangeDue: '', notes: '' });
      setShowGearForm(false);
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}?`);
    if (reason === null) return;

    const ceasedDate = new Date().toISOString().split('T')[0];
    const prevMed: PreviousMedication = {
      id: med.id,
      name: med.name,
      dose: med.dose,
      indication: med.indication,
      startDate: med.startDate,
      ceasedDate,
      ceaseReason: reason
    };

    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), prevMed]
    });
  };

  const applySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ sickDayPlan: { ...history.sickDayPlan, ...template } });
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'sickday', label: 'Sick Day', icon: '🚨' }
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 text-sm font-medium">Your child's longitudinal clinical repository.</p>
        </div>
        <button 
          onClick={handleGenerateHandover}
          disabled={loading}
          className="bg-indigo-600 text-white px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center gap-2"
        >
          {loading ? 'Analyzing...' : 'Generate ISBAR Handover ✨'}
        </button>
      </header>

      <input type="file" accept="image/*" capture="environment" ref={eventPhotoRef} onChange={handleEventPhotoCapture} className="hidden" />
