import React, { useState, useRef } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { ClinicalEvent } from '../types';

interface SymptomCheckerProps {
  onSaveEvent?: (event: Omit<ClinicalEvent, 'id'>) => void;
}

const RED_FLAGS = [
  { text: "Difficulty Breathing", sub: "Grunting, wheezing, or chest sucking in", icon: "🫁" },
  { text: "Infant Fever", sub: "Any fever in a baby under 3 months old", icon: "🌡️" },
  { text: "Altered Level of Consciousness", sub: "Unusually sleepy, floppy, or unresponsive", icon: "😴" },
  { text: "Non-Blanching Rash", sub: "Purple/red spots that don't fade when pressed", icon: "🟣" },
  { text: "Severe Pain", sub: "Inconsolable crying or extreme localized pain", icon: "😫" },
  { text: "Eye Injury/Swelling", sub: "Chemical splash, trauma, or sudden swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC<SymptomCheckerProps> = ({ onSaveEvent }) => {
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = () => {
    if (result && onSaveEvent) {
      const event: Omit<ClinicalEvent, 'id'> = {
        source: 'Symptoms',
        description: description || 'Visual observation',
        date: new Date().toLocaleDateString(),
        severity: result.text.toLowerCase().includes('red') ? 'High' : 'Low',
        media: image || undefined
      };
      onSaveEvent(event);
      setSaved(true);
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header>
        <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
        <p className="text-slate-500 text-sm font-medium">Capture signs and receive guideline-based analysis.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clinical Description</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="e.g. Barking cough, new rash on torso, refused last 2 feeds..."
                className="w-full h-40 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none"
              />
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input 
                type="file" 
                accept="image/*" 
                capture="environment" 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
              />

              <button
                onClick={() => fileInputRef.current?.click()}
                className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase tracking-widest w-full sm:w-auto transition-all ${
                  image ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-slate-500'
                }`}
              >
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>

              <button
                onClick={handleAnalyze}
                disabled={loading || (!description.trim() && !image)}
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${
                  loading ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'
                }`}
              >
                {loading ? 'Consulting Protocols...' : 'Review Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto group animate-in zoom-in-95">
                <img src={image} alt="Symptom Evidence" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button 
                  onClick={() => setImage(null)} 
                  className="absolute top-4 right-4 bg-white text-rose-500 w-8 h-8 rounded-full flex items-center justify-center shadow-xl font-black"
                >
                  ×
                </button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-l-[16px] border-l-indigo-600 animate-in slide-in-from-bottom-6">
              <div className="flex justify-between items-center mb-8">
                 <h3 className="text-2xl font-black text-slate-800 italic">AI Synthesis</h3>
                 <button 
                  onClick={handleSave}
                  disabled={saved}
                  className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all ${
                    saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700 active:scale-95'
                  }`}
                >
                  {saved ? 'Logged' : 'Sync to Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-lg leading-relaxed">
                {result.text}
              </div>
            </div>
          )}
        </div>

        {/* Enhanced Red Flags Sidebar */}
        <div className="space-y-6">
          <div className="bg-rose-600 p-8 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden ring-4 ring-rose-100 border-4 border-rose-500">
             <div className="absolute top-0 right-0 -mr-10 -mt-10 p-12 text-[120px] opacity-10 italic font-black pointer-events-none">!</div>

             <div className="relative z-10 mb-8">
                <div className="flex items-center gap-3 mb-2">
                   <span className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-xl animate-pulse">🚩</span>
                   <h3 className="text-3xl font-black italic tracking-tighter">EMERGENCY</h3>
                </div>
                <p className="text-rose-100 text-xs font-black uppercase tracking-widest border-t border-white/20 pt-2">Seek Immediate Medical Care</p>
             </div>

             <div className="space-y-3 relative z-10">
                {RED_FLAGS.map((f, i) => (
                  <div key={i} className="bg-white/10 p-4 rounded-2xl flex items-start gap-4 hover:bg-white/20 transition-all border border-white/5">
                    <span className="text-3xl shrink-0 drop-shadow-md">{f.icon}</span>
                    <div>
                      <span className="text-sm font-black leading-tight block">{f.text}</span>
                      <span className="text-[10px] font-bold text-rose-100/70 leading-tight italic block mt-0.5">{f.sub}</span>
                    </div>
                  </div>
                ))}
             </div>

             <div className="mt-8 space-y-4 relative z-10">
                <a 
                  href="tel:000" 
                  className="block w-full py-5 bg-white text-rose-600 rounded-[2rem] text-center font-black text-3xl shadow-2xl active:scale-95 transition-all hover:brightness-110 flex items-center justify-center gap-4 border-b-8 border-rose-100"
                >
                  <span className="animate-pulse">📞</span> 000
                </a>
                <p className="text-center text-[9px] font-black uppercase tracking-[0.2em] text-rose-200">Emergency Services (Australia)</p>
             </div>

             {/* Animated warning stripes at bottom */}
             <div className="absolute bottom-0 left-0 right-0 h-2 bg-[repeating-linear-gradient(45deg,transparent,transparent_10px,rgba(255,255,255,0.1)_10px,rgba(255,255,255,0.1)_20px)]"></div>
          </div>

          <div className="bg-amber-50 p-8 rounded-[2.5rem] border border-amber-100 shadow-sm flex items-start gap-4">
             <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-xl shadow-inner shrink-0">💡</div>
             <div>
                <h4 className="text-[10px] font-black text-amber-800 uppercase tracking-widest mb-1">HealthDirect Triage</h4>
                <p className="text-amber-900 text-[11px] font-bold italic leading-relaxed">
                  Unsure? Speak to a registered nurse 24/7 on <a href="tel:1800022222" className="underline">1800 022 222</a>.
                </p>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

