interface ParentingTipsProps {
  preselectedChallenge?: string;
  onClearChallenge?: () => void;
}

export const ParentingTips: React.FC<ParentingTipsProps> = ({ preselectedChallenge, onClearChallenge }) => {
  const [age, setAge] = useState('Toddler (1-3 years)');
  const [challenge, setChallenge] = useState('');
  const [loading, setLoading] = useState(false);
  const [advice, setAdvice] = useState<{ text: string; sources: any[] } | null>(null);
  const [activeTab, setActiveTab] = useState<'tips' | 'mentalhealth' | 'clinical' | 'literacy'>('tips');

  // Literacy States
  const [searchQuery, setSearchQuery] = useState('');
  const [aiTermExplanation, setAiTermExplanation] = useState<string | null>(null);
  const [literacyLoading, setLiteracyLoading] = useState(false);

  useEffect(() => {
    if (preselectedChallenge) {
      setChallenge(preselectedChallenge);
      handleGetAdvice(preselectedChallenge);
      if (onClearChallenge) setTimeout(onClearChallenge, 1000);
    }
  }, [preselectedChallenge]);

  const handleGetAdvice = async (selectedChallenge?: string) => {
    const finalChallenge = selectedChallenge || challenge;
    if (!finalChallenge) return;

    setLoading(true);
    setAdvice(null);
    setActiveTab('tips');
    try {
      const res = await getParentingAdvice(age, finalChallenge);
      setAdvice(res);
    } catch (error) {
      alert("Error generating advice.");
    } finally {
      setLoading(false);
    }
  };

  const handleExplainTerm = async () => {
    if (!searchQuery.trim()) return;
    setLiteracyLoading(true);
    setAiTermExplanation(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Explain the medical term or condition "${searchQuery}" for a parent with a young child. 
        Use simple, supportive, non-alarmist language. 
        Reference reliable Australian pediatric sources (RCH Melbourne, Raising Children Network) where appropriate. 
        Structure: 1. Simple Definition, 2. Common Signs, 3. When to worry. Keep it concise.`,
      });
      setAiTermExplanation(response.text);
    } catch (e) {
      alert("Error explaining term.");
    } finally {
      setLiteracyLoading(false);
    }
  };

  const filteredTerms = HEALTH_LITERACY_TERMS.filter(t => 
    t.term.toLowerCase().includes(searchQuery.toLowerCase()) || 
    t.category.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row justify-between items-start gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Parenting <span className="text-amber-500">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical strategies and evidence-based resources for emotional development.</p>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner overflow-x-auto no-scrollbar">
          <button 
            onClick={() => setActiveTab('tips')}
            className={`px-4 sm:px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'tips' ? 'bg-white text-amber-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
          >
            AI Strategies
          </button>
          <button 
            onClick={() => setActiveTab('literacy')}
            className={`px-4 sm:px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'literacy' ? 'bg-white text-emerald-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
          >
            Health Literacy
          </button>
          <button 
            onClick={() => setActiveTab('mentalhealth')}
            className={`px-4 sm:px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'mentalhealth' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
          >
            Resources
          </button>
          <button 
            onClick={() => setActiveTab('clinical')}
            className={`px-4 sm:px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'clinical' ? 'bg-white text-teal-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
          >
            Frameworks
          </button>
        </div>
      </header>

      {activeTab === 'tips' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-2">Age Group</label>
                <select 
                  value={age}
                  onChange={e => setAge(e.target.value)}
                  className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none font-black text-slate-900"
                >
                  <option>Toddler (1-3 years)</option>
                  <option>Preschooler (3-5 years)</option>
                  <option>School Age (5-12 years)</option>
                  <option>Adolescent (12+ years)</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-2">Specific Concern</label>
                <div className="flex gap-2">
                  <input 
                    type="text"
                    value={challenge}
                    onChange={e => setChallenge(e.target.value)}
                    className="flex-1 p-4 rounded-2xl border border-slate-100 bg-slate-50/50 font-black text-slate-900 text-sm shadow-inner placeholder-slate-400"
                    placeholder="Describe behavior..."
                  />
                  <button onClick={() => handleGetAdvice()} className="w-14 h-14 bg-amber-500 text-white rounded-2xl shadow-lg hover:bg-amber-600 transition-transform active:scale-95">✨</button>
                </div>
              </div>
            </div>

            <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Quick Access Modules</h4>
              <div className="grid grid-cols-1 gap-2">
                {COMMON_CHALLENGES.map(c => (
                  <button 
                    key={c.id} 
                    onClick={() => { setChallenge(c.label); handleGetAdvice(c.label); }}
                    className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between hover:shadow-md hover:-translate-y-1 transition-all group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="text-xl">{c.icon}</span>
                      <span className="text-sm font-bold text-slate-700">{c.label}</span>
                    </div>
                    {c.source && <span className="text-[8px] font-black bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded uppercase tracking-widest">{c.source}</span>}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="lg:col-span-2">
            {loading ? (
              <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-white rounded-[3rem] border border-slate-100 animate-pulse text-center space-y-4">
                <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center text-4xl animate-bounce">🧠</div>
                <p className="font-black text-slate-400 uppercase tracking-widest text-xs">Synthesizing clinical strategies...</p>
              </div>
            ) : advice ? (
              <div className="bg-white p-12 rounded-[4rem] border-l-[20px] border-l-amber-500 shadow-2xl animate-in zoom-in-95 relative overflow-hidden">
                <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-amber-500 rounded-full opacity-5 blur-[100px]"></div>
                <div className="relative z-10 whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic prose prose-lg max-w-none">
                  {advice.text}
                </div>
              </div>
            ) : (
              <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-slate-50/50 border-4 border-dashed border-slate-200 rounded-[4rem] text-center p-12 space-y-6">
                <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center text-5xl shadow-sm grayscale opacity-30">🌻</div>
                <div className="max-w-sm">
                  <h4 className="font-black text-slate-800 text-xl tracking-tight mb-2">Strategy Lab</h4>
                  <p className="text-slate-400 font-medium">Describe a parenting challenge or select a module to receive tailored clinical insights.</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'literacy' && (
        <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
          <section className="bg-emerald-900 p-10 rounded-[4rem] text-white shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
             <div className="relative z-10 space-y-6">
                <h3 className="text-3xl font-black italic tracking-tighter">Medical Term Explainer</h3>
                <p className="text-emerald-100 font-medium italic opacity-80 max-w-xl leading-relaxed">
                  Confused by clinical jargon? Type a term or condition below, and our Clinical AI will provide an age-appropriate explanation based on RCH and Raising Children Network standards.
                </p>
                <div className="flex gap-2 max-w-md">
                   <input 
                    type="text" 
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                    placeholder="e.g. Bronchiolitis, RSV, Stridor..."
                    className="flex-1 p-5 rounded-2xl bg-white font-black text-slate-900 outline-none border-none shadow-xl placeholder-slate-400"
                    onKeyPress={e => e.key === 'Enter' && handleExplainTerm()}
                   />
                   <button 
                    onClick={handleExplainTerm}
                    disabled={literacyLoading}
                    className="w-16 h-16 bg-emerald-500 text-white rounded-2xl flex items-center justify-center text-2xl shadow-xl hover:bg-emerald-400 transition-all active:scale-95"
                   >
                     {literacyLoading ? '⏳' : '🔍'}
                   </button>
                </div>
             </div>
          </section>

          {aiTermExplanation && (
            <div className="bg-white p-12 rounded-[4rem] border-l-[20px] border-l-emerald-600 shadow-2xl animate-in zoom-in-95 relative overflow-hidden">
               <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-emerald-500 rounded-full opacity-5 blur-[100px]"></div>
               <div className="flex items-center gap-4 mb-8">
                  <div className="w-14 h-14 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">✨</div>
                  <h4 className="text-2xl font-black text-slate-800 italic uppercase">AI Clinical Insights</h4>
               </div>
               <div className="relative z-10 whitespace-pre-wrap text-slate-700 leading-relaxed font-bold italic prose prose-lg max-w-none border-l-4 border-slate-100 pl-8">
                  {aiTermExplanation}
               </div>
            </div>
          )}

