          </div>
        </div>
      )}

      {activeTab === 'mentalhealth' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-right-4 duration-500">
          {MENTAL_HEALTH_RESOURCES.map((res, i) => (
