import React, { useState, useMemo, useEffect } from 'react';
import { ViewType, ChildProfile, MedicalHistory, ClinicalEvent, AcuteLogEntry, Vaccination, GrowthRecord, Milestone, Appointment, SpecialistContact, Medication, Condition } from './types';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { SymptomChecker } from './components/SymptomChecker';
import { GrowthTracker } from './components/GrowthTracker';
import { DoseCalculator } from './components/DoseCalculator';
import { MilestoneNavigator } from './components/MilestoneNavigator';
import { CalmStory } from './components/CalmStory';
import { VaccineTracker } from './components/VaccineTracker';
import { ScreeningTool } from './components/ScreeningTool';
import { MedicalProfile } from './components/MedicalProfile';
import { AppointmentManager } from './components/AppointmentManager';
import { RedBook } from './components/RedBook';
import { ParentingTips } from './components/ParentingTips';
import { ChildProfileSetup } from './components/ChildProfileSetup';
import { BondingJournal } from './components/BondingJournal';
import { AcuteTracker } from './components/AcuteTracker';

const STORAGE_KEYS = {
  PROFILE: 'pedipulse_profile',
  HISTORY: 'pedipulse_history',
  BONDING: 'pedipulse_bonding'
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('dashboard');

  // Initial state loading from localStorage
  const [childProfile, setChildProfile] = useState<ChildProfile | undefined>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.PROFILE);
    return saved ? JSON.parse(saved) : undefined;
  });

  const [medicalHistory, setMedicalHistory] = useState<MedicalHistory>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.HISTORY);
    return saved ? JSON.parse(saved) : {
      pastMedicalHistory: '',
      surgicalHistory: '',
      currentMedications: [],
      previousMedications: [],
      allergies: [],
      familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
      specialists: [],
      appointments: [],
      devices: [],
      sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '', planPhoto: undefined },
      activeRecommendations: [],
      medicalReports: [],
      conditions: [],
      vaccinations: [],
      growthRecords: [],
      milestones: [],
      acuteLogs: []
    };
  });

  const [bondingNotes, setBondingNotes] = useState<string>(() => {
    return localStorage.getItem(STORAGE_KEYS.BONDING) || '';
  });

  const [pendingClinicalEvents, setPendingClinicalEvents] = useState<ClinicalEvent[]>([]);

  // Persistence Effects
  useEffect(() => {
    if (childProfile) {
      localStorage.setItem(STORAGE_KEYS.PROFILE, JSON.stringify(childProfile));
    }
  }, [childProfile]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.HISTORY, JSON.stringify(medicalHistory));
  }, [medicalHistory]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.BONDING, bondingNotes);
  }, [bondingNotes]);

  // Sync latest weight to profile
  const latestWeight = useMemo(() => {
    if (medicalHistory.growthRecords && medicalHistory.growthRecords.length > 0) {
      return medicalHistory.growthRecords[medicalHistory.growthRecords.length - 1].weight;
    }
    return childProfile?.weight;
  }, [medicalHistory.growthRecords, childProfile]);

  const handleAddAcuteLog = (entry: Omit<AcuteLogEntry, 'id'>) => {
    const newEntry = { ...entry, id: Math.random().toString(36).substr(2, 9) } as AcuteLogEntry;
    setMedicalHistory(prev => ({
      ...prev,
      acuteLogs: [newEntry, ...(prev.acuteLogs || [])]
    }));
  };

  const updateMedicalHistory = (updates: Partial<MedicalHistory>) => {
    setMedicalHistory(prev => ({ ...prev, ...updates }));
  };

  const handleAddAppointment = (apt: Appointment, addToCareTeam: boolean) => {
    setMedicalHistory(prev => {
      const newAppointments = [...prev.appointments, apt];
      let newSpecialists = [...prev.specialists];

      if (addToCareTeam) {
        const exists = newSpecialists.some(s => s.name.toLowerCase() === apt.provider.toLowerCase());
        if (!exists) {
          const newSpecialist: SpecialistContact = {
            id: Math.random().toString(36).substr(2, 9),
            name: apt.provider,
            specialty: apt.specialty,
            category: 'Medical'
          };
          newSpecialists.push(newSpecialist);
        }
      }

      return {
        ...prev,
        appointments: newAppointments,
        specialists: newSpecialists
      };
    });
  };

  const nextAppointment = useMemo(() => {
    const upcoming = medicalHistory.appointments
      .filter(a => a.status === 'Upcoming' && new Date(a.dateTime) > new Date())
      .sort((a,b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
    return upcoming[0];
  }, [medicalHistory.appointments]);

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard': return (
        <div className="space-y-12">
          {nextAppointment && (
            <div className="bg-indigo-600 p-8 rounded-[3rem] text-white flex items-center justify-between shadow-2xl animate-in slide-in-from-top-4">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-3xl">🗓️</div>
                <div>
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Next Appointment</p>
                   <p className="text-2xl font-black italic">{nextAppointment.specialty} with {nextAppointment.provider}</p>
                   <p className="text-sm font-medium opacity-80">{new Date(nextAppointment.dateTime).toLocaleDateString()} @ {new Date(nextAppointment.dateTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                </div>
              </div>
              <button onClick={() => setActiveView('appointments')} className="bg-white text-indigo-600 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">Prepare Now</button>
            </div>
          )}
          <Dashboard onNavigate={setActiveView} latestWeight={latestWeight} childProfile={childProfile} />
        </div>
      );
      case 'acutelogs': return <AcuteTracker onLogEntry={handleAddAcuteLog} entries={medicalHistory.acuteLogs || []} childWeight={latestWeight} />;
      case 'appointments': return (
        <AppointmentManager 
          history={medicalHistory} 
          onAddAppointment={handleAddAppointment}
          onUpdateAppointments={(apts) => updateMedicalHistory({ appointments: apts })}
        />
      );
      case 'profile': return (
        <MedicalProfile 
          history={medicalHistory}
          updateHistory={updateMedicalHistory}
          attachmentData={{ caregiverObservations: bondingNotes }} 
          pendingEvents={pendingClinicalEvents} 
        />
      );
      case 'redbook': return (
        <RedBook 
          vaccinations={medicalHistory.vaccinations || []} 
          growthRecords={medicalHistory.growthRecords || []} 
          onVaccineUpdate={(v) => updateMedicalHistory({ vaccinations: v })} 
          onGrowthUpdate={(g) => updateMedicalHistory({ growthRecords: g })} 
          onWeightUpdate={(w) => {/* Handled by growth records */}}
        />
      );
      case 'setup': return <ChildProfileSetup initialProfile={childProfile} onSave={setChildProfile} onCancel={() => setActiveView('dashboard')} />;
      case 'symptoms': return <SymptomChecker onSaveEvent={e => setPendingClinicalEvents(prev => [{...e, id: Math.random().toString(36)}, ...prev])} />;
      case 'growth': return <GrowthTracker onWeightUpdate={(w) => {/* Handled by RedBook */}} />;
      case 'dosage': return <DoseCalculator initialWeight={latestWeight} />;
      case 'milestones': return <MilestoneNavigator onLogRedFlag={(desc) => {
        setPendingClinicalEvents(prev => [{ id: Math.random().toString(36), source: 'Development', description: desc, date: new Date().toLocaleDateString(), severity: 'Medium' }, ...prev]);
      }} />;
      case 'bonding': return <BondingJournal observations={bondingNotes} onUpdate={setBondingNotes} childName={childProfile?.name} />;
      case 'vaccines': return <VaccineTracker onSaveEvent={e => setPendingClinicalEvents(prev => [{...e, id: Math.random().toString(36)}, ...prev])} />;
      case 'parenting': return <ParentingTips />;
      case 'stories': return <CalmStory />;
      case 'screening': return <ScreeningTool />;
      default: return <Dashboard onNavigate={setActiveView} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';

interface AcuteTrackerProps {
  onLogEntry: (entry: Omit<AcuteLogEntry, 'id'>) => void;
  entries: AcuteLogEntry[];
  childWeight?: number;
}

export const AcuteTracker: React.FC<AcuteTrackerProps> = ({ onLogEntry, entries, childWeight }) => {
  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: 500,
    intervalVolume: 5,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  useEffect(() => {
    if (childWeight && !challenge.isActive) {
      const recommendedInterval = Math.round(childWeight); 
      setChallenge(prev => ({
        ...prev,
        intervalVolume: recommendedInterval,
        targetVolume: recommendedInterval * 12 
      }));
    }
  }, [childWeight, challenge.isActive]);

  const handleAdd = () => {
    if (!value) return;
    const finalValue = type === 'Temperature' && !value.includes('°C') ? `${value}°C` : value;
    onLogEntry({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type,
      value: finalValue,
      notes
    });
    setValue('');
    setNotes('');
  };

  const handleStartChallenge = () => {
    setChallenge(prev => ({ 
      ...prev, 
      isActive: true, 
      startTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      totalConsumed: 0,
      vomitCount: 0
    }));
  };

  const logChallengeFluid = (amount: number) => {
    onLogEntry({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Fluid',
      value: `${amount}ml`,
      notes: 'Part of Rehydration Challenge',
      isChallengeEntry: true
    });
    setChallenge(prev => ({ ...prev, totalConsumed: prev.totalConsumed + amount }));
  };

  const logChallengeVomit = () => {
    onLogEntry({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Vomit',
      value: 'Vomit recorded',
      notes: 'Loss during rehydration challenge',
      isChallengeEntry: true
    });
    setChallenge(prev => ({ ...prev, vomitCount: prev.vomitCount + 1 }));
  };

  const icons = { Fluid: '🥤', Temperature: '🌡️', Output: '🚽', Medication: '💊', Vomit: '🤮' };

  const successRate = Math.min(Math.round((challenge.totalConsumed / challenge.targetVolume) * 100), 100);

  return (
    <div className="space-y-6 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Sync Log</span></h2>
          <p className="text-slate-500 text-xs font-medium italic mt-1">Track fluids, fever (°C), and output for clinical review.</p>
        </div>

        {!challenge.isActive ? (
          <button 
            onClick={handleStartChallenge}
            className="w-full sm:w-auto bg-teal-600 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center justify-center gap-2"
          >
            <span>💧</span> Fluids Challenge
          </button>
        ) : (
          <button 
            onClick={() => setChallenge(prev => ({ ...prev, isActive: false }))}
            className="w-full sm:w-auto bg-slate-900 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl"
          >
            End Challenge
          </button>
        )}
      </header>

      {challenge.isActive && (
        <div className="bg-white rounded-[2.5rem] border-4 border-teal-500 shadow-2xl overflow-hidden animate-in zoom-in-95">
           <div className="bg-teal-500 px-6 py-4 flex items-center justify-between text-white">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-xl animate-pulse">🧪</div>
                 <div>
                    <h3 className="text-lg font-black italic leading-none">Hydration Challenge</h3>
                    <p className="text-[9px] font-bold uppercase tracking-widest opacity-80 mt-1">Target: {challenge.intervalVolume}ml / {challenge.intervalMinutes}m</p>
                 </div>
              </div>
           </div>

           <div className="p-6 space-y-8">
              <div className="flex flex-col items-center">
                 <div className="relative w-40 h-40">
                    <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                      <circle cx="50" cy="50" r="40" stroke="#f1f5f9" strokeWidth="10" fill="transparent" />
                      <circle 
                        cx="50" cy="50" r="40" 
                        stroke="#14b8a6" 
                        strokeWidth="10" fill="transparent" 
                        strokeDasharray={`${successRate * 2.512}, 251.2`}
                        strokeLinecap="round"
                        className="transition-all duration-1000"
                      />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                       <span className="text-3xl font-black text-slate-800 leading-none">{challenge.totalConsumed}</span>
                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ml Intake</span>
                    </div>
                 </div>
              </div>

              <div className="space-y-4">
                 <div className="overflow-x-auto no-scrollbar pb-2">
                    <div className="flex gap-2 min-w-max">
                       {[5, 10, 20, 50].map(amt => (
                         <button 
                          key={amt} 
                          onClick={() => logChallengeFluid(amt)}
                          className="px-6 py-4 rounded-2xl bg-teal-50 border border-teal-100 text-teal-700 font-black text-xs hover:bg-teal-100 transition-all active:scale-95 shadow-sm"
                         >
                            +{amt}ml
                         </button>
                       ))}
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                    <button 
                      onClick={logChallengeVomit}
                      className="p-4 rounded-3xl bg-rose-50 border border-rose-100 text-rose-700 flex flex-col items-center gap-1 group"
                    >
                       <span className="text-3xl group-active:scale-125 transition-transform">🤮</span>
                       <span className="text-[10px] font-black uppercase">Record Vomit</span>
                       <span className="text-[8px] font-bold opacity-60">Total: {challenge.vomitCount}</span>
                    </button>

                    <div className="p-4 rounded-3xl bg-indigo-50 border border-indigo-100 text-indigo-700 flex flex-col items-center gap-1">
                       <span className="text-3xl">⏱️</span>
                       <span className="text-[10px] font-black uppercase">Next Dose</span>
                       <span className="text-[8px] font-bold opacity-60">Guidelines: 5m Wait</span>
                    </div>
                 </div>
              </div>
           </div>

           <div className="bg-slate-50 px-6 py-4 border-t border-slate-100">
              <p className="text-[10px] font-bold text-slate-500 italic leading-relaxed text-center">
                 Persistence vomiting (2+ times) indicates failure; consider hospital presentation if child is lethargic.
              </p>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
            <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100">
               {['Fluid', 'Temperature', 'Output', 'Medication'].map((t) => (
                  <button
                    key={t}
                    onClick={() => setType(t as any)}
                    className={`flex-1 py-3 rounded-xl text-xl transition-all ${type === t ? 'bg-white shadow-sm' : 'opacity-40'}`}
                  >
                    {icons[t as keyof typeof icons]}
                  </button>
               ))}
            </div>

            <div className="space-y-4">
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Value</label>
                  <input 
                    value={value} 
                    onChange={e => setValue(e.target.value)} 
                    placeholder={type === 'Fluid' ? '50ml' : type === 'Temperature' ? '38.5°C' : 'Wet Nappy'}
                    className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-base text-slate-900 placeholder-slate-400 focus:ring-2 focus:ring-rose-500 outline-none"
                  />
               </div>
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Note</label>
                  <input 
                    value={notes} 
                    onChange={e => setNotes(e.target.value)} 
                    placeholder="e.g. refused half..."
                    className="w-full p-4 rounded-2xl border border-slate-100 bg-white text-xs font-black text-slate-900 placeholder-slate-400 focus:ring-2 focus:ring-rose-500 outline-none"
                  />
               </div>
               <button onClick={handleAdd} className="w-full py-5 bg-rose-600 text-white font-black rounded-[1.5rem] shadow-xl text-[11px] uppercase tracking-widest active:scale-95 transition-all">Log Event</button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3">
           <div className="bg-white p-5 sm:p-10 rounded-[2.5rem] border border-slate-100 shadow-sm min-h-[400px]">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xl font-black text-slate-800 tracking-tight">Timeline (24h)</h3>
                 <span className="text-[9px] font-black text-slate-400 uppercase border border-slate-100 px-3 py-1 rounded-full">Wt: {childWeight || '--'}kg</span>
              </div>
              <div className="space-y-3">
                 {entries.length > 0 ? entries.map(entry => (
                    <div key={entry.id} className={`flex items-center gap-4 p-4 rounded-2xl border transition-all ${entry.isChallengeEntry ? 'bg-teal-50 border-teal-50' : 'bg-slate-50/20 border-slate-50 shadow-sm'}`}>
                       <span className="text-[10px] font-black text-slate-400 w-12">{entry.timestamp}</span>
                       <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-xl shadow-sm border border-slate-50 shrink-0">{icons[entry.type]}</div>
                       <div className="flex-1 overflow-hidden">
                          <p className="text-sm font-black text-slate-800 truncate">
                             {entry.value} 
                             <span className="text-[8px] text-slate-400 uppercase tracking-widest ml-1.5">{entry.type}</span>
                          </p>
                          {entry.notes && <p className="text-[10px] font-bold text-slate-400 italic truncate leading-tight mt-0.5">{entry.notes}</p>}
                       </div>
                    </div>
                 )) : (
                    <div className="flex flex-col items-center justify-center py-20 opacity-20">
                       <span className="text-6xl mb-4">📉</span>
                       <p className="font-black text-sm uppercase tracking-widest text-slate-900">No entries yet</p>
                    </div>
                 )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

