import React, { createContext, useContext, useMemo, useState, useCallback } from 'react';
import { MedicalHistory, ClinicalEvent, AcuteLogEntry, Appointment, SpecialistContact } from '../types';
import { useLocalStorage } from '../hooks/useLocalStorage';

const DEFAULT_HISTORY: MedicalHistory = {
  pastMedicalHistory: '',
  surgicalHistory: '',
  currentMedications: [],
  previousMedications: [],
  allergies: [],
  familyHistory: { maternal: '', paternal: '', siblings: '', other: '' },
  specialists: [],
  appointments: [],
  devices: [],
  sickDayPlan: { instructions: '', emergencyMeds: '', fluidRequirements: '', triggers: '', emergencyContact: '' },
  activeRecommendations: [],
  medicalReports: [],
  conditions: [],
  vaccinations: [],
  growthRecords: [],
  milestones: [],
  acuteLogs: []
};

interface MedicalHistoryContextType {
  history: MedicalHistory;
  updateHistory: (updates: Partial<MedicalHistory>) => void;
  addAcuteLog: (entry: Omit<AcuteLogEntry, 'id'>) => void;
  addClinicalEvent: (event: Omit<ClinicalEvent, 'id'>) => void;
  addAppointment: (apt: Appointment, addToCareTeam: boolean) => void;
  pendingEvents: ClinicalEvent[];
  latestWeight?: number;
}

const MedicalHistoryContext = createContext<MedicalHistoryContextType | undefined>(undefined);

export const MedicalHistoryProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [history, setHistory] = useLocalStorage<MedicalHistory>('pedipulse_history', DEFAULT_HISTORY);
  const [pendingEvents, setPendingEvents] = useState<ClinicalEvent[]>([]);

  const updateHistory = useCallback((updates: Partial<MedicalHistory>) => {
    setHistory(prev => ({ ...prev, ...updates }));
  }, [setHistory]);

  const addAcuteLog = useCallback((entry: Omit<AcuteLogEntry, 'id'>) => {
    const newEntry = { ...entry, id: crypto.randomUUID() } as AcuteLogEntry;
    setHistory(prev => ({
      ...prev,
      acuteLogs: [newEntry, ...(prev.acuteLogs || [])]
    }));
  }, [setHistory]);

  const addClinicalEvent = useCallback((event: Omit<ClinicalEvent, 'id'>) => {
    const newEvent = { ...event, id: crypto.randomUUID() } as ClinicalEvent;
    setPendingEvents(prev => [newEvent, ...prev]);
  }, []);

  const addAppointment = useCallback((apt: Appointment, addToCareTeam: boolean) => {
    setHistory(prev => {
      const newAppointments = [...prev.appointments, apt];
      let newSpecialists = [...prev.specialists];

      if (addToCareTeam) {
        const exists = newSpecialists.some(s => s.name.toLowerCase() === apt.provider.toLowerCase());
        if (!exists) {
          const newSpecialist: SpecialistContact = {
            id: crypto.randomUUID(),
            name: apt.provider,
            specialty: apt.specialty,
            category: 'Medical'
          };
          newSpecialists.push(newSpecialist);
        }
      }

      return { ...prev, appointments: newAppointments, specialists: newSpecialists };
    });
  }, [setHistory]);

  const latestWeight = useMemo(() => {
    if (history.growthRecords && history.growthRecords.length > 0) {
      return history.growthRecords[history.growthRecords.length - 1].weight;
    }
    return undefined;
  }, [history.growthRecords]);

  return (
    <MedicalHistoryContext.Provider value={{ 
      history, 
      updateHistory, 
      addAcuteLog, 
      addClinicalEvent, 
      addAppointment,
      pendingEvents,
      latestWeight 
    }}>
      {children}
    </MedicalHistoryContext.Provider>
  );
};

export const useMedicalHistory = () => {
  const context = useContext(MedicalHistoryContext);
  if (!context) {
    throw new Error('useMedicalHistory must be used within a MedicalHistoryProvider');
  }
  return context;
};

import React, { useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { SymptomChecker } from './components/SymptomChecker';
import { GrowthTracker } from './components/GrowthTracker';
import { DoseCalculator } from './components/DoseCalculator';
import { MilestoneNavigator } from './components/MilestoneNavigator';
import { CalmStory } from './components/CalmStory';
import { VaccineTracker } from './components/VaccineTracker';
import { ScreeningTool } from './components/ScreeningTool';
import { MedicalProfile } from './components/MedicalProfile';
import { AppointmentManager } from './components/AppointmentManager';
import { RedBook } from './components/RedBook';
import { ParentingTips } from './components/ParentingTips';
import { ChildProfileSetup } from './components/ChildProfileSetup';
import { BondingJournal } from './components/BondingJournal';
import { AcuteTracker } from './components/AcuteTracker';
import { NavigationProvider, useNavigation } from './context/NavigationContext';
import { ChildProfileProvider, useChildProfile } from './context/ChildProfileContext';
import { MedicalHistoryProvider, useMedicalHistory } from './context/MedicalHistoryContext';
import { ViewType } from './types';

const AppContent: React.FC = () => {
  const { activeView, navigateTo } = useNavigation();
  const { childProfile, setChildProfile } = useChildProfile();
  const { history, updateHistory, addAppointment, addClinicalEvent, pendingEvents, latestWeight } = useMedicalHistory();

  const nextAppointment = useMemo(() => {
    const upcoming = history.appointments
      .filter(a => a.status === 'Upcoming' && new Date(a.dateTime) > new Date())
      .sort((a,b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
    return upcoming[0];
  }, [history.appointments]);

  // View Registry Pattern
  const ViewComponent = useMemo(() => {
    const views: Record<ViewType, React.ReactNode> = {
      dashboard: (
        <div className="space-y-12">
          {nextAppointment && (
            <div className="bg-indigo-600 p-8 rounded-[3rem] text-white flex items-center justify-between shadow-2xl animate-in slide-in-from-top-4">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-3xl">🗓️</div>
                <div>
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Next Appointment</p>
                   <p className="text-2xl font-black italic">{nextAppointment.specialty} with {nextAppointment.provider}</p>
                   <p className="text-sm font-medium opacity-80">{new Date(nextAppointment.dateTime).toLocaleDateString()} @ {new Date(nextAppointment.dateTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                </div>
              </div>
              <button onClick={() => navigateTo('appointments')} className="bg-white text-indigo-600 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">Prepare Now</button>
            </div>
          )}
          <Dashboard />
        </div>
      ),
      acutelogs: <AcuteTracker />,
      appointments: (
        <AppointmentManager 
          history={history} 
          onAddAppointment={addAppointment}
          onUpdateAppointments={(apts) => updateHistory({ appointments: apts })}
        />
      ),
      profile: (
        <MedicalProfile 
          history={history}
          updateHistory={updateHistory}
          pendingEvents={pendingEvents} 
        />
      ),
      redbook: (
        <RedBook 
          vaccinations={history.vaccinations || []} 
          growthRecords={history.growthRecords || []} 
          onVaccineUpdate={(v) => updateHistory({ vaccinations: v })} 
          onGrowthUpdate={(g) => updateHistory({ growthRecords: g })} 
        />
      ),
      setup: <ChildProfileSetup initialProfile={childProfile} onSave={setChildProfile} onCancel={() => navigateTo('dashboard')} />,
      symptoms: <SymptomChecker onSaveEvent={addClinicalEvent} />,
      growth: <GrowthTracker />,
      dosage: <DoseCalculator initialWeight={latestWeight} />,
      milestones: <MilestoneNavigator onLogRedFlag={(desc) => {
        addClinicalEvent({ source: 'Development', description: desc, date: new Date().toLocaleDateString(), severity: 'Medium' });
      }} />,
      bonding: <BondingJournal />,
      vaccines: <VaccineTracker onSaveEvent={addClinicalEvent} />,
      parenting: <ParentingTips />,
      stories: <CalmStory />,
      screening: <ScreeningTool />,
    };
    return views[activeView] || views.dashboard;
  }, [activeView, nextAppointment, navigateTo, history, addAppointment, updateHistory, pendingEvents, childProfile, setChildProfile, addClinicalEvent, latestWeight]);

  return (
    <Layout activeView={activeView} onNavigate={navigateTo}>
      <div className="bg-rose-50 border-b border-rose-100 px-6 py-2 text-center text-[10px] font-black text-rose-600 uppercase tracking-[0.2em] mb-8 rounded-2xl shadow-sm">
        ⚠️ This tool does not replace professional medical advice. Always confirm doses and symptoms with a clinician.
      </div>
      {ViewComponent}
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <NavigationProvider>
      <ChildProfileProvider>
        <MedicalHistoryProvider>
          <AppContent />
        </MedicalHistoryProvider>
      </ChildProfileProvider>
    </NavigationProvider>
  );
};

