          <button 
            onClick={handleStartChallenge}
            className="w-full sm:w-auto bg-teal-600 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 transition-all hover:bg-teal-700"
          >
            <span>💧</span> Fluids Challenge
