      {challenge.isActive && (
        <div className="bg-white rounded-[2.5rem] border-4 border-teal-500 shadow-2xl overflow-hidden animate-in zoom-in-95">
           <div className="bg-teal-500 px-6 py-4 flex items-center justify-between text-white">
