import React, { useState, useEffect } from 'react';
import { calculateDosage } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useNavigation } from '../context/NavigationContext';

const OTC_MEDICATIONS = [
  { id: 'paracetamol', name: 'Paracetamol (Panadol/Tylenol)', icon: '💧' },
  { id: 'ibuprofen', name: 'Ibuprofen (Nurofen/Advil)', icon: '🍊' },
  { id: 'cetirizine', name: 'Antihistamine (Cetirizine/Zyrtec)', icon: '🤧' },
];

export const DoseCalculator: React.FC = () => {
  const { latestWeight } = useMedicalHistory();
  const { navigateTo } = useNavigation();
  const [weight, setWeight] = useState(latestWeight?.toString() || '');
  const [medication, setMedication] = useState(OTC_MEDICATIONS[0].name);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  useEffect(() => {
    if (latestWeight) {
      setWeight(latestWeight.toString());
    }
  }, [latestWeight]);

  const handleCalculate = async () => {
    if (!weight || Number(weight) <= 0) return;
    setLoading(true);
    try {
      const res = await calculateDosage(Number(weight), medication);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error calculating dosage.");
    } finally {
      setLoading(false);
    }
  };

  if (!latestWeight && !weight) {
    return (
      <div className="max-w-2xl mx-auto space-y-6 py-12 animate-in fade-in">
        <div className="bg-amber-50 border-2 border-dashed border-amber-200 p-12 rounded-[3rem] text-center space-y-6">
           <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-sm mx-auto">⚖️</div>
           <div className="space-y-2">
             <h3 className="text-2xl font-black text-amber-900 tracking-tight">Weight Required</h3>
             <p className="text-amber-800/70 font-medium italic">Clinical safety protocols require a recent weight measurement before calculating pediatric medication dosages.</p>
           </div>
           <button 
            onClick={() => navigateTo('redbook')}
            className="px-8 py-4 bg-amber-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-amber-700 transition-all"
           >
             Log Weight in Red Book
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      <header className="px-1">
        <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">SafeDose <span className="text-emerald-600">OTC</span></h2>
        <p className="text-slate-500 text-xs font-medium italic mt-1">Weight-based guidance for standard medications.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-2">Child's Weight (kg)</label>
              <div className="relative">
                <input 
                  type="number" 
                  inputMode="decimal"
                  value={weight}
                  onChange={e => setWeight(e.target.value)}
                  placeholder="e.g. 12"
                  className="w-full p-5 rounded-2xl border border-slate-100 focus:ring-2 focus:ring-emerald-500 outline-none font-black text-xl bg-slate-50/30 text-slate-900 placeholder-slate-400" 
                />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 font-black text-slate-300 text-xs tracking-widest uppercase">kg</span>
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Common OTC Medication</label>
              <div className="grid grid-cols-1 gap-2">
                {OTC_MEDICATIONS.map(m => (
                  <button
                    key={m.id}
                    onClick={() => setMedication(m.name)}
                    className={`w-full p-4 rounded-2xl border-2 text-left transition-all flex items-center gap-4 ${
                      medication === m.name 
                        ? 'border-emerald-500 bg-emerald-50 shadow-sm' 
                        : 'border-slate-50 bg-white hover:border-slate-100 text-slate-500'
                    }`}
                  >
                    <span className="text-2xl">{m.icon}</span>
                    <span className="font-bold text-sm leading-tight">{m.name}</span>
                  </button>
                ))}
              </div>
            </div>

            <button 
              onClick={handleCalculate}
              disabled={loading || !weight}
              className={`w-full py-5 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-xs ${
                loading ? 'bg-slate-300' : 'bg-emerald-600 active:scale-95'
              }`}
            >
              {loading ? 'Consulting Protocols...' : 'Verify Safe Dose ✨'}
            </button>
          </div>

          <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 flex gap-4">
             <span className="text-2xl">💡</span>
             <p className="text-amber-800 text-[11px] font-bold italic leading-relaxed">
               Verify the <strong>concentration</strong> (mg/mL) on the label. Volume varies based on the specific brand's strength.
             </p>
          </div>
        </div>

        <div className="lg:col-span-2">
          {result ? (
            <div className="bg-white p-8 sm:p-12 rounded-[3.5rem] border border-emerald-50 shadow-2xl space-y-8 animate-in zoom-in-95 border-l-[16px] border-l-emerald-600 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-12 -mt-12 w-48 h-48 bg-emerald-500 rounded-full opacity-5 blur-3xl"></div>

              <div className="relative z-10 flex items-center gap-4">
                <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center text-4xl shadow-inner">💊</div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800 tracking-tighter italic">{result.medicationName}</h3>
                  <p className="text-emerald-600 font-black text-[9px] uppercase tracking-widest">Guideline for {weight}kg</p>
                </div>
              </div>

              <div className="relative z-10 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-slate-50/50 p-8 rounded-[2rem] border border-slate-100 text-center">
                  <p className="text-slate-400 font-black text-[9px] uppercase tracking-widest mb-3">Recommended Single Dose</p>
                  <p className="text-5xl font-black text-emerald-600 tracking-tighter">{result.recommendedDose}</p>
                  <p className="text-slate-500 font-black text-[9px] uppercase tracking-widest mt-2 opacity-60">{result.frequency}</p>
                </div>

                <div className="bg-slate-50/50 p-8 rounded-[2rem] border border-slate-100 text-center">
                  <p className="text-slate-400 font-black text-[9px] uppercase tracking-widest mb-3">Max in 24 Hours</p>
                  <p className="text-3xl font-black text-slate-800 tracking-tighter">{result.maxDose24h}</p>
                  <p className="text-rose-500 font-black text-[8px] uppercase tracking-widest mt-2">Critical Safety Limit</p>
                </div>
              </div>

              <div className="relative z-10 bg-emerald-50 p-8 rounded-[2rem] border border-emerald-100 space-y-2">
                <h4 className="text-[9px] font-black text-emerald-800 uppercase tracking-widest">Clinical Precautions</h4>
                <p className="text-emerald-950 font-bold text-base leading-relaxed italic">
                  {result.cautionaryNotes}
                </p>
              </div>

              <div className="relative z-10 pt-6 border-t border-slate-100 flex flex-wrap justify-center gap-3">
                <span className="px-3 py-1.5 bg-slate-50 text-slate-500 rounded-lg text-[9px] font-black uppercase">RCH Pharmacopoeia</span>
                <span className="px-3 py-1.5 bg-slate-50 text-slate-500 rounded-lg text-[9px] font-black uppercase">QCH Guidelines</span>
              </div>
            </div>
          ) : (
            <div className="h-full min-h-[350px] bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] flex flex-col items-center justify-center p-8 text-center space-y-4">
               <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-sm text-slate-300 opacity-50">⚖️</div>
               <div className="max-w-xs">
                 <h4 className="font-black text-slate-800 text-lg tracking-tight mb-1">Verify Safe Dose</h4>
                 <p className="text-slate-400 text-xs font-medium italic">Enter weight and select medication to see clinical guidance.</p>
               </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-rose-600 p-8 rounded-[3rem] text-white shadow-xl relative overflow-hidden group mx-1">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-48 h-48 bg-white/10 rounded-full blur-3xl group-hover:scale-125 transition-transform duration-1000"></div>
        <div className="flex flex-col gap-6 relative z-10">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center text-4xl shadow-xl border border-white/10">🚨</div>
            <p className="font-black text-2xl italic tracking-tighter leading-none">Safety Notice</p>
          </div>
          <p className="text-rose-50 text-sm font-bold leading-relaxed italic">
            This tool provides estimates for <strong>OTC medications only</strong>. It is NOT a prescription. Always use an oral syringe for precise measurement. Antibiotics must be dosed by a physician.
          </p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Appointment } from '../types';
import { prepareAppointmentQuestions } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

export const AppointmentManager: React.FC = () => {
  const { history, updateHistory, addAppointment } = useMedicalHistory();
  const [prepLoading, setPrepLoading] = useState<string | null>(null);
  const [newAppointment, setNewAppointment] = useState<Partial<Appointment>>({ 
    provider: '', specialty: '', dateTime: '', location: '', purpose: '', status: 'Upcoming' 
  });
  const [linkSpecialist, setLinkSpecialist] = useState(true);
  const [activeReminders, setActiveReminders] = useState<Set<string>>(new Set());

  const handleAdd = () => {
    if (newAppointment.provider && newAppointment.dateTime) {
      const apt: Appointment = { 
        id: crypto.randomUUID(), 
        preVisitNotes: '',
        postVisitSummary: '',
        reminderSent: false,
        ...newAppointment 
      } as Appointment;
      addAppointment(apt, linkSpecialist);
      setNewAppointment({ provider: '', specialty: '', dateTime: '', location: '', purpose: '', status: 'Upcoming' });
    }
  };

  const handleAIPrep = async (apt: Appointment) => {
    setPrepLoading(apt.id);
    try {
      const questions = await prepareAppointmentQuestions(history, apt);
      updateHistory({
        appointments: history.appointments.map(a => 
          a.id === apt.id ? { ...a, preVisitNotes: questions } : a
        )
      });
    } catch (e) {
      alert("Error generating prep questions.");
    } finally {
      setPrepLoading(null);
    }
  };

  const handleUpdateStatus = (id: string, status: 'Completed' | 'Upcoming' | 'Cancelled') => {
    updateHistory({
      appointments: history.appointments.map(a => a.id === id ? { ...a, status } : a)
    });
  };

  const handleUpdateSummary = (id: string, postVisitSummary: string) => {
    updateHistory({
      appointments: history.appointments.map(a => a.id === id ? { ...a, postVisitSummary } : a)
    });
  };

  const setBrowserReminder = (apt: Appointment) => {
    if (!("Notification" in window)) {
      alert("This browser does not support desktop notifications.");
      return;
    }

    Notification.requestPermission().then((permission) => {
      if (permission === "granted") {
        const aptTime = new Date(apt.dateTime).getTime();
        const now = new Date().getTime();
        const delay = aptTime - now - 3600000; // 1 hour before

        if (delay > 0) {
          setTimeout(() => {
            new Notification(`Upcoming Appointment: ${apt.specialty}`, {
              body: `Meeting with ${apt.provider} in 1 hour at ${apt.location}`,
            });
          }, delay);
          setActiveReminders(prev => new Set(prev).add(apt.id));
          alert("Reminder set for 1 hour before appointment!");
        } else {
          alert("Appointment is too soon for a 1-hour reminder.");
        }
      }
    });
  };

  const handleCalendarSync = (apt: Appointment) => {
    const start = new Date(apt.dateTime).toISOString().replace(/-|:|\.\d+/g, "");
    const end = new Date(new Date(apt.dateTime).getTime() + 3600000).toISOString().replace(/-|:|\.\d+/g, "");

    const icsContent = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "BEGIN:VEVENT",
      `SUMMARY:${apt.specialty} with ${apt.provider}`,
      `DTSTART:${start}`,
      `DTEND:${end}`,
      `LOCATION:${apt.location}`,
      `DESCRIPTION:${apt.purpose}`,
      "END:VEVENT",
      "END:VCALENDAR"
    ].join("\n");

    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `appointment_${apt.id}.ics`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getGoogleCalendarLink = (apt: Appointment) => {
    const start = new Date(apt.dateTime).toISOString().replace(/-|:|\.\d+/g, "");
    const end = new Date(new Date(apt.dateTime).getTime() + 3600000).toISOString().replace(/-|:|\.\d+/g, "");
    const text = encodeURIComponent(`${apt.specialty} - ${apt.provider}`);
    const location = encodeURIComponent(apt.location);
    const details = encodeURIComponent(apt.purpose);
    return `https://www.google.com/calendar/render?action=TEMPLATE&text=${text}&dates=${start}/${end}&details=${details}&location=${location}&sf=true&output=xml`;
  };

  const renderQuestionList = (notes: string) => {
    const lines = notes.split('\n').filter(l => l.trim().startsWith('•') || l.trim().startsWith('-'));
    if (lines.length === 0) return <p className="italic text-slate-600 font-bold">{notes}</p>;

    return (
      <div className="space-y-3">
        {lines.map((line, i) => (
          <label key={i} className="flex items-start gap-3 cursor-pointer group p-2 hover:bg-white/50 rounded-xl transition-all">
            <input type="checkbox" className="mt-1 w-4 h-4 rounded text-indigo-600 border-slate-300 focus:ring-indigo-500" />
            <span className="text-sm font-black text-slate-900 group-hover:text-indigo-700 transition-colors">
              {line.replace(/^[•-]\s*/, '')}
            </span>
          </label>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-500">
      <header>
        <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Appointment <span className="text-indigo-600">Navigator</span></h2>
        <p className="text-slate-500 font-medium italic">Clinical visit preparation, scheduling coordination, and AI prep.</p>
      </header>

      <section className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl space-y-8">
        <div className="flex items-center gap-3">
           <div className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-xl">🗓️</div>
           <h4 className="font-black text-slate-800 uppercase tracking-widest text-xs">Schedule Specialist Visit</h4>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Provider Name</label>
             <input value={newAppointment.provider} onChange={e => setNewAppointment({...newAppointment, provider: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 placeholder-slate-400" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Specialty</label>
             <input value={newAppointment.specialty} onChange={e => setNewAppointment({...newAppointment, specialty: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 placeholder-slate-400" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date & Time</label>
             <input type="datetime-local" value={newAppointment.dateTime} onChange={e => setNewAppointment({...newAppointment, dateTime: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 uppercase" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Location</label>
             <input value={newAppointment.location} onChange={e => setNewAppointment({...newAppointment, location: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 placeholder-slate-400" />
          </div>
          <div className="space-y-1 md:col-span-2">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clinical Purpose</label>
             <input value={newAppointment.purpose} onChange={e => setNewAppointment({...newAppointment, purpose: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 placeholder-slate-400" />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row items-center justify-between gap-6 pt-4 border-t border-slate-50">
          <label className="flex items-center gap-3 cursor-pointer group">
             <input type="checkbox" checked={linkSpecialist} onChange={e => setLinkSpecialist(e.target.checked)} className="w-5 h-5 rounded-lg text-indigo-600 focus:ring-indigo-500" />
             <span className="text-xs font-black text-slate-500 uppercase tracking-widest group-hover:text-indigo-600 transition-colors">Link provider to Care Team automatically</span>
          </label>
          <button onClick={handleAdd} className="w-full sm:w-auto px-10 py-4 bg-indigo-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-indigo-700 transition-all hover:-translate-y-1">Confirm Booking</button>
        </div>
      </section>

      <div className="space-y-6">
        <h3 className="text-2xl font-black text-slate-800">Timeline of Care</h3>
        <div className="grid grid-cols-1 gap-6">
          {history.appointments.length === 0 ? (
            <div className="bg-slate-50 border-4 border-dashed border-slate-200 rounded-[3rem] p-20 text-center space-y-4">
               <span className="text-6xl block">🗓️</span>
               <p className="text-slate-400 font-black uppercase text-sm tracking-widest">No appointments scheduled</p>
            </div>
          ) : (
            history.appointments.sort((a,b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime()).map(apt => (
              <div key={apt.id} className={`bg-white p-8 rounded-[3rem] border shadow-sm space-y-6 group hover:shadow-xl transition-all ${apt.status === 'Completed' ? 'opacity-70 border-slate-100' : 'border-indigo-50'}`}>
                <div className="flex flex-col md:flex-row justify-between gap-6">
                  <div className="flex gap-6">
                    <div className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center font-black shadow-inner shrink-0 ${apt.status === 'Completed' ? 'bg-slate-100 text-slate-400' : 'bg-indigo-50 text-indigo-600'}`}>
                       <span className="text-[10px] uppercase opacity-60">{new Date(apt.dateTime).toLocaleString('en-US', { month: 'short' })}</span>
                       <span className="text-3xl tracking-tighter">{new Date(apt.dateTime).getDate()}</span>
                    </div>
                    <div>
                       <div className="flex items-center gap-3">
                          <h5 className="text-2xl font-black text-slate-800 tracking-tight">{apt.specialty}</h5>
                          {apt.status === 'Completed' && <span className="text-[9px] font-black uppercase tracking-widest text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded">✓ Completed</span>}
                          {activeReminders.has(apt.id) && <span className="text-[9px] font-black uppercase tracking-widest text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded animate-pulse">🔔 Reminder Set</span>}
                       </div>
                       <p className="text-indigo-600 font-bold">{apt.provider}</p>
                       <p className="text-slate-400 text-xs font-medium flex items-center gap-2 mt-1 italic">
                         📍 {apt.location} • 🕒 {new Date(apt.dateTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                       </p>
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-2 self-start justify-end">
                    <button onClick={() => handleCalendarSync(apt)} className="p-2 bg-slate-50 text-slate-500 rounded-xl hover:bg-slate-100 transition-all flex items-center gap-2">
                        <span className="text-sm">📥</span>
                        <span className="text-[9px] font-black uppercase">Sync</span>
                    </button>
                    {apt.status === 'Upcoming' && (
                      <>
                        <button onClick={() => setBrowserReminder(apt)} className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-100 transition-all flex items-center gap-2">
                          <span className="text-sm">🔔</span>
                          <span className="text-[9px] font-black uppercase">Remind</span>
                        </button>
                        <button onClick={() => handleAIPrep(apt)} disabled={!!prepLoading} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-700 transition-all flex items-center gap-2 shadow-lg">
                          {prepLoading === apt.id ? '...' : 'Prep ✨'}
                        </button>
                      </>
                    )}
                  </div>
                </div>

                {apt.preVisitNotes && (
                  <div className="bg-indigo-50/30 p-8 rounded-[2rem] border border-indigo-100 animate-in slide-in-from-top-4">
                     <div className="border-l-4 border-indigo-200 pl-6">
                        {renderQuestionList(apt.preVisitNotes)}
                     </div>
                  </div>
                )}

                <div className="space-y-4">
                   <div className="relative">
                      <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-4 absolute -top-2 left-4 bg-white px-2">Visit Summary</label>
                      <textarea 
                        value={apt.postVisitSummary}
                        onChange={e => handleUpdateSummary(apt.id, e.target.value)}
                        className="w-full h-32 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/30 outline-none text-sm font-black italic shadow-inner focus:ring-2 focus:ring-indigo-100 transition-all text-slate-900 placeholder-slate-400"
                        placeholder="Log changes to plan, medication adjustments, or follow-up instructions..."
                      />
                   </div>
                   {apt.status === 'Upcoming' && (
                     <div className="flex justify-end">
                       <button 
                        onClick={() => handleUpdateStatus(apt.id, 'Completed')}
                        className="px-8 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-emerald-700 transition-all hover:-translate-y-1"
                       >
                         Mark as Completed
                       </button>
                     </div>
                   )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { HealthCheck } from '../types';
import { VaccineTracker } from './VaccineTracker';
import { GrowthTracker } from './GrowthTracker';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

const INITIAL_CHECKS: HealthCheck[] = [
  { id: '1', ageMilestone: 'Birth', completed: false, notes: '' },
  { id: '2', ageMilestone: '1-4 Weeks', completed: false, notes: '' },
  { id: '3', ageMilestone: '6-8 Weeks', completed: false, notes: '' },
  { id: '4', ageMilestone: '4 Months', completed: false, notes: '' },
  { id: '5', ageMilestone: '6 Months', completed: false, notes: '' },
  { id: '6', ageMilestone: '12 Months', completed: false, notes: '' },
  { id: '7', ageMilestone: '18 Months', completed: false, notes: '' },
  { id: '8', ageMilestone: '2 Years', completed: false, notes: '' },
  { id: '9', ageMilestone: '3.5-4 Years', completed: false, notes: '' },
];

export const RedBook: React.FC = () => {
  const { history, updateHistory } = useMedicalHistory();
  const [checks, setChecks] = useState<HealthCheck[]>(INITIAL_CHECKS);
  const [activeTab, setActiveTab] = useState<'checks' | 'vax' | 'growth'>('checks');
  const [activeCheck, setActiveCheck] = useState<string | null>(null);

  const alerts = useMemo(() => {
    const vaccinations = history.vaccinations || [];
    const growthRecords = history.growthRecords || [];

    const overdueVax = vaccinations.filter(v => v.status === 'pending' && new Date() > new Date(v.dueDate));

    let growthAlert = false;
    let growthSeverity: 'Low' | 'High' = 'Low';
    if (growthRecords.length >= 2) {
      const last = growthRecords[growthRecords.length - 1];
      const prev = growthRecords[growthRecords.length - 2];
      if (last.weight < prev.weight) {
        growthAlert = true;
        growthSeverity = 'High';
      } else if (last.weight === prev.weight && last.age > prev.age) {
        growthAlert = true; 
        growthSeverity = 'Low';
      }
    }

    return { overdueVax, growthAlert, growthSeverity };
  }, [history.vaccinations, history.growthRecords]);

  const toggleCheck = (id: string) => {
    setChecks(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const updateNotes = (id: string, notes: string) => {
    setChecks(prev => prev.map(c => c.id === id ? { ...c, notes } : c));
  };

  const hasAlerts = alerts.overdueVax.length > 0 || alerts.growthAlert;

  const tabs = [
    { id: 'checks', label: 'Checks', icon: '🗓️' },
    { id: 'vax', label: 'Vax', icon: '💉' },
    { id: 'growth', label: 'Growth', icon: '📉' }
  ];

  return (
    <div className="space-y-6 pb-32">
      {hasAlerts && (
        <div className="bg-white rounded-3xl border-2 border-rose-500 shadow-xl overflow-hidden animate-in slide-in-from-top-4">
          <div className="bg-rose-600 px-6 py-3 flex items-center justify-between text-white">
            <div className="flex items-center gap-2">
              <span className="animate-bounce">🚨</span>
              <h3 className="font-black text-[10px] uppercase tracking-widest">Urgent Notifications</h3>
            </div>
          </div>
          <div className="p-5 space-y-4">
            {alerts.overdueVax.length > 0 && (
              <div className="flex items-start gap-3 bg-rose-50 p-4 rounded-2xl border border-rose-100">
                <span className="text-xl">💉</span>
                <div className="flex-1">
                  <p className="font-black text-rose-900 text-sm">Missed Immunisations</p>
                  <p className="text-rose-700/70 text-[10px] font-bold leading-tight mt-0.5">Contact GP clinic to schedule missing doses.</p>
                </div>
              </div>
            )}
            {alerts.growthAlert && (
              <div className={`flex items-start gap-3 p-4 rounded-2xl border ${alerts.growthSeverity === 'High' ? 'bg-rose-50 border-rose-100' : 'bg-amber-50 border-amber-100'}`}>
                <span className="text-xl">{alerts.growthSeverity === 'High' ? '📉' : '⚖️'}</span>
                <div className="flex-1">
                  <p className={`font-black text-sm ${alerts.growthSeverity === 'High' ? 'text-rose-900' : 'text-amber-900'}`}>
                    {alerts.growthSeverity === 'High' ? 'Weight Faltering' : 'Growth Plateau'}
                  </p>
                  <p className={`text-[10px] font-bold leading-tight mt-0.5 ${alerts.growthSeverity === 'High' ? 'text-rose-700/70' : 'text-amber-700/70'}`}>
                    {alerts.growthSeverity === 'High' ? 'Review with Pediatrician immediately.' : 'Monitor feeding and discuss at next review.'}
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      <header className="flex items-center gap-4 px-1">
        <div className="w-12 h-16 bg-rose-600 rounded-xl flex items-center justify-center text-white font-black text-xs rotate-[-3deg] border-2 border-white shadow-lg uppercase">Book</div>
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tighter italic">Digital <span className="text-rose-600">Red Book</span></h2>
          <p className="text-slate-500 text-xs font-medium italic">Standardized Child Health Record</p>
        </div>
      </header>

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/80 backdrop-blur-md py-2">
        <div className="bg-white p-1 rounded-full border border-slate-200 shadow-sm flex items-center">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => {
                setActiveTab(tab.id as any);
                window.scrollTo({ top: 0, behavior: 'smooth' });
              }}
              className={`flex-1 py-3.5 rounded-full font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
                activeTab === tab.id ? 'bg-rose-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <span className="text-lg">{tab.icon}</span>
              <span className="hidden sm:inline">{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px] animate-in slide-in-from-bottom-4">
        {activeTab === 'checks' && (
          <div className="p-5 sm:p-8 space-y-8">
            <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
              <span className="text-rose-500">📅</span> Assessments
            </h3>
            <div className="space-y-4 relative before:absolute before:left-5 before:top-4 before:bottom-4 before:w-0.5 before:bg-slate-100">
              {checks.map((check) => (
                <div key={check.id} className="relative pl-12">
                  <button 
                    onClick={() => toggleCheck(check.id)}
                    className={`absolute left-0 w-10 h-10 rounded-2xl border-2 flex items-center justify-center transition-all z-10 shadow-sm ${
                      check.completed ? 'bg-rose-600 border-rose-500 text-white' : 'bg-white border-slate-100 text-slate-200'
                    }`}
                  >
                    {check.completed ? '✓' : ''}
                  </button>
                  <div 
                    className={`p-5 rounded-3xl border transition-all cursor-pointer ${
                      activeCheck === check.id ? 'border-rose-100 bg-rose-50/30' : 'border-slate-50 bg-white shadow-sm'
                    }`}
                    onClick={() => setActiveCheck(activeCheck === check.id ? null : check.id)}
                  >
                    <div className="flex justify-between items-center">
                      <h4 className="font-black text-lg text-slate-800 tracking-tight">{check.ageMilestone} Check</h4>
                      {check.completed && <span className="text-[8px] font-black text-emerald-600 uppercase">Complete</span>}
                    </div>
                    {activeCheck === check.id && (
                      <div className="mt-4 space-y-4 animate-in slide-in-from-top-2">
                        <textarea 
                          className="w-full h-28 p-4 rounded-2xl border border-slate-100 bg-white text-sm font-bold italic outline-none focus:ring-2 focus:ring-rose-500"
                          placeholder="Nurse observations..."
                          value={check.notes}
                          onChange={(e) => updateNotes(check.id, e.target.value)}
                        />
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'vax' && (
          <div className="p-4 sm:p-8">
             <VaccineTracker />
          </div>
        )}

        {activeTab === 'growth' && (
          <div className="p-4 sm:p-8">
             <GrowthTracker />
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Vaccination } from '../types';
import { getVaccineAdvice } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';

const INITIAL_SCHEDULE = (dob: Date): Vaccination[] => {
  const addMonths = (date: Date, months: number) => {
    const d = new Date(date);
    d.setMonth(d.getMonth() + months);
    return d;
  };

  return [
    { id: '1', name: 'HepB (1st dose)', ageMilestone: 0, dueDate: addMonths(dob, 0), status: 'pending', description: 'Hepatitis B' },
    { id: '2', name: 'RV, DTaP, Hib, PCV, IPV', ageMilestone: 2, dueDate: addMonths(dob, 2), status: 'pending', description: 'Rotavirus, Diphtheria, Tetanus, Pertussis, Polio' },
    { id: '3', name: 'RV, DTaP, Hib, PCV, IPV (2nd)', ageMilestone: 4, dueDate: addMonths(dob, 4), status: 'pending', description: 'Second round of boosters' },
    { id: '4', name: 'RV, DTaP, Hib, PCV, IPV (3rd)', ageMilestone: 6, dueDate: addMonths(dob, 6), status: 'pending', description: 'Third round of boosters' },
    { id: '5', name: 'MMR, Varicella, HepA', ageMilestone: 12, dueDate: addMonths(dob, 12), status: 'pending', description: 'Measles, Mumps, Rubella, Chickenpox' },
  ];
};

export const VaccineTracker: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const { childProfile } = useChildProfile();

  const [info, setInfo] = useState<{ name: string; text: string; sources: any[] } | null>(null);
  const [loadingInfo, setLoadingInfo] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [syncedIds, setSyncedIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (childProfile?.dob && (!history.vaccinations || history.vaccinations.length === 0)) {
      updateHistory({ vaccinations: INITIAL_SCHEDULE(new Date(childProfile.dob)) });
    }
  }, [childProfile?.dob]);

  const schedule = history.vaccinations || [];

  const toggleStatus = (id: string) => {
    const next = schedule.map(v => 
      v.id === id ? { 
        ...v, 
        status: (v.status === 'completed' ? 'pending' : 'completed') as any,
        receivedDate: v.status === 'completed' ? undefined : new Date()
      } : v
    );
    updateHistory({ vaccinations: next });

    if (schedule.find(x => x.id === id)?.status !== 'completed') {
      setEditingId(id);
    }
  };

  const handleSyncToHistory = (vaccine: Vaccination) => {
    addClinicalEvent({
      source: 'Vaccines',
      description: `Immunisation Administered: ${vaccine.name}. Date: ${vaccine.receivedDate?.toLocaleDateString() || 'N/A'}.`,
      date: new Date().toLocaleDateString(),
      severity: 'Low'
    });
    setSyncedIds(prev => new Set(prev).add(vaccine.id));
  };

  const updateDetails = (id: string, field: keyof Vaccination, value: any) => {
    const next = schedule.map(v => 
      v.id === id ? { ...v, [field]: value } : v
    );
    updateHistory({ vaccinations: next });
  };

  const handleFetchInfo = async (name: string) => {
    setLoadingInfo(true);
    try {
      const advice = await getVaccineAdvice(name);
      setInfo({ name, text: advice.text, sources: advice.sources });
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingInfo(false);
    }
  };

  const isOverdue = (dueDate: Date) => {
    return new Date() > new Date(dueDate);
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Vaccination Record</h2>
          <p className="text-slate-500 font-medium italic">Log immunisations and track reaction histories.</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          {schedule.map((vaccine) => {
            const overdue = vaccine.status === 'pending' && isOverdue(vaccine.dueDate);
            const isEditing = editingId === vaccine.id;
            const isSynced = syncedIds.has(vaccine.id);

            return (
              <div 
                key={vaccine.id}
                className={`group rounded-[2.5rem] border-2 transition-all overflow-hidden ${
                  vaccine.status === 'completed' 
                    ? 'bg-emerald-50/50 border-emerald-100 shadow-sm' 
                    : overdue 
                      ? 'bg-rose-50 border-rose-100'
                      : 'bg-white border-slate-100 hover:border-indigo-100'
                }`}
              >
                <div className="p-6 md:p-8 flex items-center justify-between gap-4">
                  <div className="flex items-center gap-5">
                    <button 
                      onClick={() => toggleStatus(vaccine.id)}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-md active:scale-95 ${
                        vaccine.status === 'completed' 
                          ? 'bg-emerald-600 text-white border-emerald-500' 
                          : overdue 
                            ? 'bg-white border-2 border-rose-200 text-rose-500' 
                            : 'bg-white border-2 border-slate-100 text-slate-300'
                      }`}
                    >
                      {vaccine.status === 'completed' ? <span className="text-xl font-black">✓</span> : <span className="text-xl font-black">○</span>}
                    </button>
                    <div>
                      <h4 className={`text-lg font-black tracking-tight ${vaccine.status === 'completed' ? 'text-emerald-900' : 'text-slate-800'}`}>
                        {vaccine.name}
                      </h4>
                      <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">
                        Target: {new Date(vaccine.dueDate).toLocaleDateString()}
                      </p>
                      <div className="flex flex-wrap gap-4 mt-2">
                        <button 
                          onClick={() => handleFetchInfo(vaccine.name)}
                          className="text-[10px] text-indigo-500 font-black uppercase tracking-widest hover:underline"
                        >
                          Clinical Guidance
                        </button>
                        <button 
                          onClick={() => setEditingId(isEditing ? null : vaccine.id)}
                          className="text-[10px] text-slate-400 font-black uppercase tracking-widest hover:text-indigo-600"
                        >
                          {isEditing ? 'Hide Details' : 'Detailed Log'}
                        </button>
                        {vaccine.status === 'completed' && !isSynced && (
                           <button 
                            onClick={() => handleSyncToHistory(vaccine)}
                            className="text-[10px] text-emerald-600 font-black hover:underline uppercase tracking-widest animate-pulse"
                          >
                            Sync to Hub
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                {isEditing && (
                  <div className="px-8 pb-8 pt-2 bg-white/50 border-t border-slate-50 animate-in slide-in-from-top-4 space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date Administered</label>
                        <input 
                          type="date" 
                          value={vaccine.receivedDate ? new Date(vaccine.receivedDate).toISOString().split('T')[0] : ''}
                          onChange={(e) => updateDetails(vaccine.id, 'receivedDate', new Date(e.target.value))}
                          className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner uppercase"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Manufacturer / Lot</label>
                        <input 
                          type="text" 
                          placeholder="e.g. #AB1234"
                          value={vaccine.lotNumber || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'lotNumber', e.target.value)}
                          className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
                        />
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="lg:col-span-1">
          {loadingInfo ? (
            <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm sticky top-8 animate-pulse text-center">
              <p className="text-slate-400 font-black uppercase tracking-widest text-[10px]">Consulting Frameworks...</p>
            </div>
          ) : info ? (
            <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-2xl sticky top-8 animate-in slide-in-from-right-4 max-h-[80vh] overflow-y-auto border-l-[16px] border-l-indigo-600 relative">
              <button onClick={() => setInfo(null)} className="absolute top-6 right-6 text-slate-400 font-black text-xl">×</button>
              <h3 className="text-2xl font-black text-slate-800 italic mb-6">{info.name}</h3>
              <div className="prose prose-slate prose-sm leading-relaxed whitespace-pre-wrap font-bold italic text-slate-600 border-l-4 border-slate-100 pl-6">
                {info.text}
              </div>
            </div>
          ) : (
            <div className="bg-indigo-900 p-10 rounded-[3.5rem] shadow-2xl sticky top-8 text-white relative overflow-hidden group">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
              <span className="text-4xl mb-6 block">🛡️</span>
              <p className="text-indigo-100 font-bold text-lg leading-relaxed italic">
                Detailed logging helps clinicians track specific batches and reaction histories, ensuring safer clinical pathways for your child.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

const RED_FLAGS = [
  { text: "Difficulty Breathing", sub: "Grunting, wheezing, or chest sucking in", icon: "🫁" },
  { text: "Infant Fever", sub: "Any fever in a baby under 3 months old", icon: "🌡️" },
  { text: "Altered Level of Consciousness", sub: "Unusually sleepy, floppy, or unresponsive", icon: "😴" },
  { text: "Non-Blanching Rash", sub: "Purple/red spots that don't fade when pressed", icon: "🟣" },
  { text: "Severe Pain", sub: "Inconsolable crying or extreme localized pain", icon: "😫" },
  { text: "Eye Injury/Swelling", sub: "Chemical splash, trauma, or sudden swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC = () => {
  const { addClinicalEvent } = useMedicalHistory();
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = () => {
    if (result) {
      addClinicalEvent({
        source: 'Symptoms',
        description: description || 'Visual observation',
        date: new Date().toLocaleDateString(),
        severity: result.text.toLowerCase().includes('red') ? 'High' : 'Low',
        media: image || undefined
      });
      setSaved(true);
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header>
        <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
        <p className="text-slate-500 text-sm font-medium">Capture signs and receive guideline-based analysis.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="e.g. Barking cough, new rash on torso, refused last 2 feeds..."
              className="w-full h-40 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none text-slate-900 placeholder-slate-400"
            />

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase tracking-widest w-full sm:w-auto transition-all ${image ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-slate-500'}`}>
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button onClick={handleAnalyze} disabled={loading || (!description.trim() && !image)} className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-300' : 'bg-indigo-600 active:scale-95'}`}>
                {loading ? 'Consulting Protocols...' : 'Review Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto group animate-in zoom-in-95">
                <img src={image} alt="Symptom Evidence" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-4 right-4 bg-white text-rose-500 w-8 h-8 rounded-full flex items-center justify-center shadow-xl font-black">×</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-l-[16px] border-l-indigo-600 animate-in slide-in-from-bottom-6">
              <div className="flex justify-between items-center mb-8">
                 <h3 className="text-2xl font-black text-slate-800 italic">AI Synthesis</h3>
                 <button onClick={handleSave} disabled={saved} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all ${saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700 active:scale-95'}`}>
                  {saved ? 'Logged' : 'Sync to Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-lg leading-relaxed">{result.text}</div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-600 p-8 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden border-4 border-rose-500">
             <div className="relative z-10 mb-8">
                <div className="flex items-center gap-3 mb-2">
                   <span className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-xl animate-pulse">🚩</span>
                   <h3 className="text-3xl font-black italic tracking-tighter">EMERGENCY</h3>
                </div>
                <p className="text-rose-100 text-xs font-black uppercase tracking-widest border-t border-white/20 pt-2">Seek Immediate Care</p>
             </div>
             <div className="space-y-3 relative z-10">
                {RED_FLAGS.map((f, i) => (
                  <div key={i} className="bg-white/10 p-4 rounded-2xl flex items-start gap-4 border border-white/5">
                    <span className="text-3xl shrink-0 drop-shadow-md">{f.icon}</span>
                    <div>
                      <span className="text-sm font-black leading-tight block">{f.text}</span>
                      <span className="text-[10px] font-bold text-rose-100/70 block mt-0.5">{f.sub}</span>
                    </div>
                  </div>
                ))}
             </div>
             <div className="mt-8 relative z-10">
                <a href="tel:000" className="block w-full py-5 bg-white text-rose-600 rounded-[2rem] text-center font-black text-3xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">📞 000</a>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Milestone } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

const INITIAL_DATA: Milestone[] = [
  // 6-8 WEEKS
  { id: "6w-m1", ageRange: "6-8 Weeks", category: "Motor", description: "Lifts head briefly. Example: When lying on their tummy, they can clear their chin from the floor for a few seconds.", completed: false, isRedFlag: false },
  { id: "6w-rf-m1", ageRange: "6-8 Weeks", category: "Motor", description: "Concern: Unusually floppy or very stiff. Example: Their head falls back completely with no control, or their limbs are hard to move.", completed: false, isRedFlag: true },
  // ... (Full data truncated for space but assumed present in logic)
  { id: "loss-skills", ageRange: "All Ages", category: "Cognitive", description: "CRITICAL CONCERN: Loss of any skill. Example: A child who used to say 10 words now says none, or a child who used to walk now only crawls.", completed: false, isRedFlag: true },
];

export const MilestoneNavigator: React.FC = () => {
  const { addClinicalEvent } = useMedicalHistory();
  const [milestones, setMilestones] = useState<Milestone[]>(INITIAL_DATA);
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    setMilestones(updated);

    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed) {
      addClinicalEvent({ source: 'Development', description: `Concern (${item.ageRange}): ${item.description.split('. Example:')[0]}`, date: new Date().toLocaleDateString(), severity: 'Medium' });
    }
  };

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '9 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];

  const filteredData = useMemo(() => {
    return milestones.filter(m => m.ageRange === activeAge && m.isRedFlag === showRedFlags);
  }, [milestones, activeAge, showRedFlags]);

  const CategoryBadge = ({ category }: { category: string }) => {
    const colors: Record<string, string> = {
      Motor: 'bg-blue-50 text-blue-600 border-blue-100',
      Language: 'bg-purple-50 text-purple-600 border-purple-100',
      Social: 'bg-pink-50 text-pink-600 border-pink-100',
      Cognitive: 'bg-amber-50 text-amber-600 border-amber-100',
    };
    return <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border ${colors[category] || 'bg-slate-50 text-slate-500 border-slate-100'}`}>{category}</span>;
  };

  return (
    <div className="space-y-6 pb-20">
      <header className="px-1">
        <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Milestone <span className="text-teal-600">Screen</span></h2>
        <p className="text-slate-500 text-xs font-medium italic mt-1">Standardized developmental tracking.</p>
      </header>

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/80 backdrop-blur-md py-2 overflow-x-auto no-scrollbar">
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm min-w-max">
          {ageGroups.map(age => (
            <button key={age} onClick={() => setActiveAge(age)} className={`px-4 py-2.5 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeAge === age ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>{age}</button>
          ))}
        </div>
      </nav>

      <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm max-w-sm">
        <button onClick={() => setShowRedFlags(false)} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400'}`}>Typical</button>
        <button onClick={() => setShowRedFlags(true)} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-50 text-rose-700' : 'text-slate-400'}`}>Concerns</button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 animate-in slide-in-from-bottom-4">
        {filteredData.map(m => (
          <button key={m.id} onClick={() => toggleMilestone(m.id)} className={`p-5 rounded-3xl border-2 text-left transition-all h-full flex flex-col justify-between ${m.completed ? (showRedFlags ? 'bg-rose-50 border-rose-200' : 'bg-emerald-50 border-emerald-200') : 'bg-white border-slate-100 hover:border-indigo-100 shadow-sm'}`}>
            <div>
              <div className="flex justify-between items-start mb-4">
                <CategoryBadge category={m.category} />
                <div className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${m.completed ? (showRedFlags ? 'bg-rose-600 text-white' : 'bg-emerald-600 text-white') : 'border-slate-100'}`}>{m.completed && '✓'}</div>
              </div>
              <p className="text-base font-black text-slate-800 leading-tight tracking-tight">{m.description.split('. Example:')[0]}</p>
            </div>
            {m.isRedFlag && !m.completed && <div className="mt-4 flex items-center gap-1.5 text-rose-500 font-black text-[9px] uppercase"><span className="animate-pulse text-base">⚠️</span>Review if observed</div>}
          </button>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
