      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl min-h-[500px] p-8">
        {activeTab === 'history' && (
          <div className="space-y-10">
            <section className="space-y-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><span className="text-indigo-600">📜</span> Birth Story & Narrative</h3>
              <textarea value={history.pastMedicalHistory} onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} className="w-full h-48 p-6 rounded-3xl border border-slate-100 bg-slate-50/50 outline-none font-bold italic resize-none text-slate-900" />
            </section>
