  const { history, latestWeight } = useMedicalHistory();
  const { childProfile } = useChildProfile();

  const data = generateHandover(childProfile, history, latestWeight);

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-black">Clinician Handover Summary</h1>

      <section>
        <h2 className="font-bold">Patient</h2>
