export type RedFlagSeverity = 'Urgent' | 'Moderate';

export interface RedFlag {
  id: string;
  message: string;
  subtext: string;
  severity: RedFlagSeverity;
}

export interface ClinicalInput {
  ageMonths?: number;
  temperature?: number;
  symptoms: string[];
  durationDays?: number;
}

/**
 * Evaluates clinical inputs against standard pediatric safety rules.
 * This logic provides a fallback safety net for the AI triage.
 */
export function evaluateRedFlags(input: ClinicalInput): RedFlag[] {
  const flags: RedFlag[] = [];

  // Neonatal Fever Rule (Critical)
  if (input.ageMonths !== undefined && input.ageMonths < 3 && input.temperature && input.temperature >= 38) {
    flags.push({
      id: 'neonate-fever',
      message: 'Urgent Medical Review Required',
      subtext: 'Fever ≥38°C in an infant under 3 months is a medical emergency until proven otherwise.',
      severity: 'Urgent'
    });
  }

  // Respiratory Distress logic
  const respDistressKeywords = ['difficulty breathing', 'grunting', 'wheezing', 'chest sucking', 'fast breathing', 'stridor'];
  const hasRespDistress = input.symptoms.some(s => 
    respDistressKeywords.some(keyword => s.toLowerCase().includes(keyword))
  );

  if (hasRespDistress) {
    flags.push({
      id: 'resp-distress',
      message: 'Respiratory Distress Detected',
      subtext: 'Signs of increased work of breathing require immediate clinical assessment.',
      severity: 'Urgent'
    });
  }

  // Prolonged Illness
  if (input.durationDays && input.durationDays > 5) {
    flags.push({
      id: 'prolonged-illness',
      message: 'Persistent Symptoms',
      subtext: 'Symptoms lasting more than 5 days should be reviewed by a GP even if they appear mild.',
      severity: 'Moderate'
    });
  }

  // High Fever
  if (input.temperature && input.temperature >= 40) {
    flags.push({
      id: 'high-fever',
      message: 'High Pyrexia',
      subtext: 'Temperature of 40°C or higher requires clinical review to identify the source of infection.',
      severity: 'Moderate'
    });
  }

  return flags;
}

