export const SymptomChecker: React.FC = () => {
  const { addClinicalEvent } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const isOnline = useConnectivity();

  const [description, setDescription] = useState('');
  const [temp, setTemp] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Derive age in months for red flag engine
  const ageMonths = useMemo(() => {
    if (!childProfile?.dob) return undefined;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    return (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
  }, [childProfile]);

  // Integrated Safety Engine
  const activeRedFlags = useMemo(() => evaluateRedFlags({
    ageMonths,
    temperature: temp ? parseFloat(temp) : undefined,
    symptoms: [description]
  }), [ageMonths, temp, description]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection. Please follow local red flag guidance.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = () => {
    if (result) {
      addClinicalEvent({
        source: 'Symptoms',
        description: description || 'Visual observation',
        date: new Date().toLocaleDateString(),
        severity: result.text.toLowerCase().includes('red') || activeRedFlags.length > 0 ? 'High' : 'Low',
        media: image || undefined
      });
      setSaved(true);
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex justify-between items-start">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
          <p className="text-slate-500 text-sm font-medium">Capture signs and receive guideline-based analysis.</p>
        </div>
        {!isOnline && (
          <div className="bg-amber-100 text-amber-700 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border border-amber-200">
            <span>📡</span> Offline Mode
          </div>
        )}
      </header>

      {/* Persistent Logic Red Flags (Non-dismissible) */}
      {activeRedFlags.length > 0 && (
        <div className="space-y-3">
          {activeRedFlags.map(flag => (
            <div key={flag.id} className={`p-6 rounded-[2rem] border-2 shadow-lg animate-in slide-in-from-top-4 ${flag.severity === 'Urgent' ? 'bg-rose-50 border-rose-600' : 'bg-amber-50 border-amber-600'}`}>
              <div className="flex items-center gap-4">
                 <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl shadow-sm ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white' : 'bg-amber-600 text-white'}`}>
                    {flag.severity === 'Urgent' ? '🚨' : '⚠️'}
                 </div>
                 <div>
                    <h4 className={`font-black uppercase tracking-widest text-xs ${flag.severity === 'Urgent' ? 'text-rose-700' : 'text-amber-700'}`}>{flag.message}</h4>
                    <p className={`font-bold italic text-sm ${flag.severity === 'Urgent' ? 'text-rose-900' : 'text-amber-900'}`}>{flag.subtext}</p>
                 </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <div className="space-y-4">
               <div className="flex flex-col sm:flex-row gap-4">
                  <div className="flex-1 space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Temperature (°C)</label>
                    <input 
                      type="number" step="0.1" value={temp} onChange={e => setTemp(e.target.value)} placeholder="37.0"
                      className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/30 font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>
                  <div className="flex-[2] space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Patient Description</label>
                    <textarea
                      value={description}
                      onChange={(e) => setDescription(e.target.value)}
                      placeholder="Barking cough, new rash, refused feeds..."
                      className="w-full h-24 p-4 rounded-2xl border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none text-slate-900 placeholder-slate-400"
                    />
                  </div>
               </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase tracking-widest w-full sm:w-auto transition-all ${image ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-slate-500'}`}>
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button 
                onClick={handleAnalyze} 
                disabled={loading || (!description.trim() && !image)} 
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-300' : 'bg-indigo-600 active:scale-95'}`}
              >
                {!isOnline ? 'System Offline' : loading ? 'Consulting Protocols...' : 'Review Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto group animate-in zoom-in-95">
                <img src={image} alt="Symptom Evidence" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-4 right-4 bg-white text-rose-500 w-8 h-8 rounded-full flex items-center justify-center shadow-xl font-black">×</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-l-[16px] border-l-indigo-600 animate-in slide-in-from-bottom-6">
              <div className="flex justify-between items-center mb-8">
                 <h3 className="text-2xl font-black text-slate-800 italic">AI Synthesis</h3>
                 <button onClick={handleSave} disabled={saved} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all ${saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700 active:scale-95'}`}>
                  {saved ? 'Logged' : 'Sync to Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-lg leading-relaxed">{result.text}</div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-600 p-8 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden border-4 border-rose-500">
             <div className="relative z-10 mb-8">
                <div className="flex items-center gap-3 mb-2">
                   <span className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-xl animate-pulse">🚩</span>
                   <h3 className="text-3xl font-black italic tracking-tighter">EMERGENCY</h3>
                </div>
                <p className="text-rose-100 text-xs font-black uppercase tracking-widest border-t border-white/20 pt-2">Seek Immediate Care</p>
             </div>
             <div className="space-y-3 relative z-10">
                {RED_FLAGS_LIST.map((f, i) => (
                  <div key={i} className="bg-white/10 p-4 rounded-2xl flex items-start gap-4 border border-white/5">
                    <span className="text-3xl shrink-0 drop-shadow-md">{f.icon}</span>
