export const DoseCalculator: React.FC = () => {
  const { latestWeight } = useMedicalHistory();
  const { navigateTo } = useNavigation();
  const { role } = useRole();
  const isOnline = useConnectivity();

  const [weight, setWeight] = useState(latestWeight?.toString() || '');
  const [medication, setMedication] = useState(OTC_MEDICATIONS[0].name);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  useEffect(() => {
    if (latestWeight) {
      setWeight(latestWeight.toString());
    }
  }, [latestWeight]);

  const handleCalculate = async () => {
    if (!weight || Number(weight) <= 0) return;

    // Offline safety fallback
    if (!isOnline) {
      setResult({
        medicationName: medication,
        recommendedDose: "Check physical product label (Conservative rounding applied)",
        frequency: "Every 4-6 hours",
        maxDose24h: "4 doses in 24 hours",
        cautionaryNotes: "Offline mode: Full AI clinical precision unavailable. Always use the device provided with the medicine."
      });
      return;
    }

    setLoading(true);
    try {
      const res = await calculateDosage(Number(weight), medication);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error calculating dosage.");
    } finally {
      setLoading(false);
    }
  };

  if (!latestWeight && !weight) {
    return (
      <div className="max-w-2xl mx-auto space-y-6 py-12 animate-in fade-in">
