    const result = calculateSafetyCeiling(100, 'Paracetamol');
    expect(result?.mgPerDose).toBe(DOSING_GUIDELINES.PARACETAMOL.MAX_SINGLE_MG);
  });

  test('Paracetamol: Calculates 15mg/kg for standard weight', () => {
