export const DoseCalculator: React.FC = () => {
  const { latestWeight } = useMedicalHistory();
  const { navigateTo } = useNavigation();
  const { role } = useRole();
  const isOnline = useConnectivity();

  const [weight, setWeight] = useState(latestWeight?.toString() || '');
  const [medication, setMedication] = useState(OTC_MEDICATIONS[0].name);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  // Deterministic Safety Check
  const safetyCeiling = useMemo(() => {
    if (!weight || isNaN(parseFloat(weight))) return null;
    return calculateSafetyCeiling(parseFloat(weight), medication);
  }, [weight, medication]);

  useEffect(() => {
    if (latestWeight) {
      setWeight(latestWeight.toString());
    }
  }, [latestWeight]);

  const handleCalculate = async () => {
    if (!weight || Number(weight) <= 0) return;

    // Offline safety fallback or verify against safety engine
    if (!isOnline) {
      if (safetyCeiling) {
        setResult({
          medicationName: safetyCeiling.medication,
          recommendedDose: `${safetyCeiling.mgPerDose} mg (Calculated Offline)`,
          frequency: `Every ${safetyCeiling.intervalHours} hours`,
          maxDose24h: `${safetyCeiling.maxDosesPerDay} doses in 24 hours`,
          cautionaryNotes: `Offline Mode. ${safetyCeiling.safetyWarnings.join(' ')}`
        });
      } else {
        alert("Medication unknown to offline safety engine. Reconnect to use AI Triage.");
      }
      return;
    }

    setLoading(true);
    try {
      const res = await calculateDosage(Number(weight), medication);
      setResult(res);
    } catch (error) {
      console.error(error);
      alert("Error calculating dosage.");
    } finally {
      setLoading(false);
    }
  };

  if (!latestWeight && !weight) {
    return (
      <div className="max-w-2xl mx-auto space-y-6 py-12 animate-in fade-in">
        <div className="bg-amber-50 border-2 border-dashed border-amber-200 p-12 rounded-[3rem] text-center space-y-6">
           <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-sm mx-auto">⚖️</div>
           <div className="space-y-2">
             <h3 className="text-2xl font-black text-amber-900 tracking-tight">Weight Required</h3>
             <p className="text-amber-800/70 font-medium italic">Clinical safety protocols require a recent weight measurement before calculating pediatric medication dosages.</p>
           </div>
           <button 
            onClick={() => navigateTo('redbook')}
            className="px-8 py-4 bg-amber-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-amber-700 transition-all"
           >
             Log Weight in Red Book
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      <header className="px-1 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">SafeDose <span className="text-emerald-600">OTC</span></h2>
          <p className="text-slate-500 text-xs font-medium italic mt-1">Weight-based guidance for standard medications.</p>
        </div>
        <div className="flex gap-2">
          {!isOnline && (
            <span className="px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest bg-amber-100 text-amber-700 border border-amber-200">Offline Mode</span>
          )}
          <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border ${role === 'clinician' ? 'bg-slate-900 text-white border-slate-900' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
            {role === 'clinician' ? 'Exact mg/kg Mode' : 'Standard Rounding'}
          </span>
        </div>
      </header>

      {/* Persistent Disclaimer */}
      <div className="bg-blue-50 border border-blue-100 p-6 rounded-[2rem] flex items-start gap-4">
         <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-xl shrink-0 shadow-sm">ℹ️</div>
         <p className="text-blue-900 text-xs font-bold leading-relaxed italic">
            <strong>Dose Safety:</strong> Medications doses shown are estimates based on standard weight-based protocols. They may not be appropriate for your child if they have underlying health conditions. <strong>Always check the product label and oral syringe carefully.</strong>
         </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-2">Child's Weight (kg)</label>
              <div className="relative">
                <input 
                  type="number" 
                  inputMode="decimal"
                  value={weight}
                  onChange={e => setWeight(e.target.value)}
                  placeholder="e.g. 12"
                  className="w-full p-5 rounded-2xl border border-slate-100 focus:ring-2 focus:ring-emerald-500 outline-none font-black text-xl bg-slate-50/30 text-slate-900 placeholder-slate-400" 
