export type RedFlagSeverity = 'Urgent' | 'Moderate';

export interface RedFlag {
  id: string;
  message: string;
  subtext: string;
  severity: RedFlagSeverity;
}

export interface ClinicalInput {
  ageMonths?: number;
  temperature?: number;
  symptoms: string[];
  durationDays?: number;
  environment?: EnvironmentMode;
}

/**
 * Evaluates clinical inputs against standard pediatric safety rules.
 */
export function evaluateRedFlags(input: ClinicalInput): RedFlag[] {
  const flags: RedFlag[] = [];
  const isLowResource = input.environment === 'low-resource';

  // Neonatal Fever Rule (Critical)
  if (input.ageMonths !== undefined && input.ageMonths < 3 && input.temperature && input.temperature >= 38) {
    flags.push({
      id: 'neonate-fever',
      message: 'Urgent Medical Review Required',
      subtext: 'Fever ≥38°C in an infant under 3 months is a medical emergency.',
      severity: 'Urgent'
    });
  }

  // Respiratory Distress logic
  const respDistressKeywords = ['difficulty breathing', 'grunting', 'wheezing', 'chest sucking', 'fast breathing', 'stridor'];
  const hasRespDistress = input.symptoms.some(s => 
    respDistressKeywords.some(keyword => s.toLowerCase().includes(keyword))
  );

  if (hasRespDistress) {
    flags.push({
      id: 'resp-distress',
      message: 'Respiratory Distress Detected',
      subtext: 'Signs of increased work of breathing require immediate clinical assessment.',
      severity: 'Urgent'
    });
  }

  // Prolonged Illness - Conservative Threshold in Low-Resource
  const durationThreshold = isLowResource ? 3 : 5;
  if (input.durationDays && input.durationDays > durationThreshold) {
    flags.push({
      id: 'prolonged-illness',
      message: isLowResource ? 'Early Escalation Recommended' : 'Persistent Symptoms',
      subtext: isLowResource 
        ? `In settings with limited resources, symptoms exceeding ${durationThreshold} days warrant early professional review.`
        : `Symptoms lasting more than ${durationThreshold} days should be reviewed by a GP.`,
      severity: isLowResource ? 'Urgent' : 'Moderate'
    });
  }

  // High Fever
  if (input.temperature && input.temperature >= 40) {
    flags.push({
      id: 'high-fever',
      message: 'High Pyrexia',
      subtext: 'Temperature of 40°C or higher requires clinical review.',
      severity: 'Moderate'
    });
  }

  return flags;
}

