  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection. Please follow deterministic red flag guidance below.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
