      addEntry({
        eventType: "symptom_evaluation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Desc: ${description.slice(0, 50)}... Temp: ${temp || 'N/A'} Duration: ${duration || 'N/A'}`,
