const AppContent: React.FC = () => {
  const { activeView, navigateTo } = useNavigation();
  const { childProfile, setChildProfile } = useChildProfile();
  const { history } = useMedicalHistory();
  const [showDisclaimer, setShowDisclaimer] = useState(() => !localStorage.getItem('pedipulse_disclaimer_accepted'));

  const nextAppointment = useMemo(() => {
    const upcoming = history.appointments
      .filter(a => a.status === 'Upcoming' && new Date(a.dateTime) > new Date())
      .sort((a,b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
    return upcoming[0];
  }, [history.appointments]);

  const acceptDisclaimer = () => {
    localStorage.setItem('pedipulse_disclaimer_accepted', 'true');
    setShowDisclaimer(false);
  };

  const ViewComponent = useMemo(() => {
    const views: Record<ViewType, React.ReactNode> = {
      dashboard: (
        <div className="space-y-12">
          {nextAppointment && (
            <div className="bg-indigo-600 p-8 rounded-[3rem] text-white flex items-center justify-between shadow-2xl animate-in slide-in-from-top-4">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-3xl">🗓️</div>
                <div>
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Next Appointment</p>
                   <p className="text-2xl font-black italic">{nextAppointment.specialty} with {nextAppointment.provider}</p>
                   <p className="text-sm font-medium opacity-80">{new Date(nextAppointment.dateTime).toLocaleDateString()} @ {new Date(nextAppointment.dateTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                </div>
              </div>
              <button onClick={() => navigateTo('appointments')} className="bg-white text-indigo-600 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">Prepare Now</button>
            </div>
          )}
          <Dashboard />
        </div>
      ),
      acutelogs: <AcuteTracker />,
      appointments: <AppointmentManager />,
      profile: <MedicalProfile />,
      redbook: <RedBook />,
      setup: <ChildProfileSetup initialProfile={childProfile} onSave={setChildProfile} onCancel={() => navigateTo('dashboard')} />,
      symptoms: <SymptomChecker />,
      growth: <GrowthTracker />,
      dosage: <DoseCalculator />,
      milestones: <MilestoneNavigator />,
      bonding: <BondingJournal />,
      vaccines: <VaccineTracker />,
      parenting: <ParentingTips />,
      stories: <CalmStory />,
      screening: <ScreeningTool />,
      handover: <HandoverSummary />,
      governance: <GovernanceLog />,
      ethics: <EthicsSafety />
    };
    return views[activeView] || views.dashboard;
  }, [activeView, nextAppointment, navigateTo, childProfile, setChildProfile]);

  return (
    <Layout activeView={activeView} onNavigate={navigateTo}>
      {showDisclaimer && (
        <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] max-w-lg w-full p-10 shadow-2xl space-y-8 animate-in zoom-in-95">
             <div className="w-20 h-20 bg-rose-50 text-rose-600 rounded-[2rem] flex items-center justify-center text-4xl shadow-inner mx-auto">⚠️</div>
             <div className="text-center space-y-4">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight italic leading-none">Intended Purpose & Safety Notice</h2>
                <div className="text-slate-500 font-medium italic space-y-4 leading-relaxed text-sm">
                   <p>PediPulse AI is a <strong>decision-support and information tool only</strong>. It organizes patient data and highlights potential red flags.</p>
                   <p>It is <strong>NOT intended to provide medical advice, diagnosis, or treatment.</strong> All data remains stored locally on your device.</p>
                   <p>If your child appears unwell or you observe dangerous signs, <strong>seek professional medical care immediately.</strong></p>
                </div>
             </div>
             <div className="space-y-3">
               <button 
                onClick={acceptDisclaimer}
                className="w-full py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all"
               >
                 I Understand & Agree
               </button>
               <button 
                onClick={() => { acceptDisclaimer(); navigateTo('ethics'); }}
                className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-indigo-600 transition-colors"
               >
                 View Safety Framework
               </button>
             </div>
          </div>
        </div>
      )}

      <div className="bg-rose-50 border-b border-rose-100 px-6 py-3 text-center mb-8 rounded-2xl shadow-sm space-y-1">
        <p className="text-[10px] font-black text-rose-600 uppercase tracking-[0.2em]">⚠️ Safety Notice: Decision Support Tool Only</p>
        <p className="text-[9px] text-rose-500 italic font-bold">Local storage only • Non-diagnostic • Replaces no clinical judgment.</p>
      </div>
      {ViewComponent}
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <NavigationProvider>
      <EnvironmentProvider>
        <RoleProvider>
          <GovernanceProvider>
            <ChildProfileProvider>
