import React, { useState, useMemo } from 'react';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useGovernance } from '../context/GovernanceContext';
import { analyzeMedicalProfile } from '../services/gemini';
import { generateHandoverData } from '../clinical/handover';
import { generateClinicalExportBundle } from '../clinical/exportBundle';

export const HandoverSummary: React.FC = () => {
  const { history, latestWeight, pendingEvents } = useMedicalHistory();
  const { childProfile, childAge } = useChildProfile();
  const { log: governanceLog } = useGovernance();
  const [loading, setLoading] = useState(false);
  const [aiIsbar, setAiIsbar] = useState<string | null>(null);

  const handover = useMemo(() => 
    generateHandoverData(childProfile, history, childAge, latestWeight),
  [childProfile, history, childAge, latestWeight]);

  const generateAIAnalysis = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents, childProfile });
      setAiIsbar(result.text);
    } catch (e) {
      alert("Analysis error.");
    } finally {
      setLoading(false);
    }
  };

  const exportAsClinicalBundle = () => {
    const bundleText = generateClinicalExportBundle(handover, governanceLog);
    const dataStr = "data:text/plain;charset=utf-8," + encodeURIComponent(bundleText);
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `pedipulse_clinical_bundle_${handover.identification.name.replace(/\s+/g, '_')}.txt`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const copyToClipboard = () => {
    const text = document.getElementById('handover-content')?.innerText;
    if (text) {
      navigator.clipboard.writeText(text);
      alert("Summary copied to clipboard!");
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-24">
      <header className="flex flex-col md:flex-row justify-between items-start gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Clinician <span className="text-indigo-600">Handover</span></h2>
          <p className="text-slate-500 font-medium max-w-xl">Comprehensive clinical summary generated in ISBAR format for seamless tertiary care transitions.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <button onClick={exportAsClinicalBundle} className="px-6 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-800 shadow-xl transition-all flex items-center gap-2">
            <span>🛡️</span> Bundle Export
          </button>
          <button onClick={() => window.print()} className="px-6 py-4 bg-white border-2 border-slate-100 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-50 shadow-sm transition-all">Print PDF 🖨️</button>
          <button onClick={copyToClipboard} className="px-6 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-700 shadow-xl transition-all">Copy Text 📋</button>
        </div>
      </header>

      <div id="handover-content" className="bg-white p-12 rounded-[4rem] border border-slate-100 shadow-2xl space-y-12 relative overflow-hidden">
        <div className="absolute top-0 right-0 -mr-24 -mt-24 w-96 h-96 bg-indigo-50 rounded-full opacity-50 blur-[100px] -z-10"></div>

        {/* IDENTIFICATION */}
        <section className="space-y-4">
           <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em] border-b border-indigo-50 pb-2">Identification (Demographics)</h3>
           <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
              <div><p className="text-[10px] font-black text-slate-400 uppercase">Patient Name</p><p className="text-xl font-black text-slate-800">{handover.identification.name}</p></div>
              <div><p className="text-[10px] font-black text-slate-400 uppercase">D.O.B</p><p className="text-xl font-black text-slate-800">{handover.identification.dob}</p></div>
              <div><p className="text-[10px] font-black text-slate-400 uppercase">Current Age</p><p className="text-xl font-black text-slate-800">{handover.identification.age}</p></div>
              <div><p className="text-[10px] font-black text-slate-400 uppercase">Latest Weight</p><p className="text-xl font-black text-slate-800">{handover.identification.weight}</p></div>
           </div>
        </section>

        {/* ALLERGIES & ALERTS */}
        <section className="bg-rose-50 p-8 rounded-[2rem] border border-rose-100">
           <h3 className="text-xs font-black text-rose-600 uppercase tracking-[0.3em] mb-4">Critical Alerts & Allergies</h3>
           <div className="flex flex-wrap gap-3">
              {handover.background.allergies.length > 0 ? handover.background.allergies.map((a, i) => (
                <span key={i} className="px-4 py-2 bg-white text-rose-600 rounded-xl text-xs font-black border border-rose-200 uppercase tracking-widest">⚠️ {a}</span>
              )) : <p className="text-rose-400 font-bold italic">No known allergies logged.</p>}
           </div>
        </section>

        {/* SITUATION & ACUTE TRENDS */}
        <section className="space-y-4">
           <h3 className="text-xs font-black text-teal-600 uppercase tracking-[0.3em] border-b border-teal-50 pb-2">Situation (Active Issues & Recent Trends)</h3>
           <div className="space-y-6">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Ongoing Diagnoses</p>
                <div className="flex flex-wrap gap-2">
                  {handover.situation.activeIssues.map((issue, i) => (
                    <span key={i} className="px-3 py-1 bg-teal-50 text-teal-700 rounded-lg text-[10px] font-black border border-teal-100">{issue}</span>
                  ))}
                  {handover.situation.activeIssues.length === 0 && <p className="text-slate-400 text-sm italic">None recorded.</p>}
                </div>
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Acute Log Timeline (Recent)</p>
                <div className="space-y-2">
                  {handover.situation.recentAcuteLogs.map(log => (
                    <div key={log.id} className="flex gap-4 p-3 rounded-xl hover:bg-slate-50 transition-colors">
                      <span className="text-[10px] font-black text-slate-300 w-16">{log.timestamp}</span>
                      <p className="text-sm font-bold text-slate-800">{log.type}: {log.value} <span className="text-slate-400 font-medium italic ml-2">{log.notes}</span></p>
                    </div>
                  ))}
                </div>
              </div>
           </div>
        </section>

        {/* BACKGROUND */}
        <section className="space-y-4">
           <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] border-b border-slate-50 pb-2">Background (PMHx)</h3>
           <p className="text-slate-700 font-medium italic leading-relaxed whitespace-pre-wrap">{handover.background.pastMedicalHistory}</p>

           <div className="mt-6 space-y-2">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active Care Team</p>
              <div className="flex flex-wrap gap-2">
                {handover.background.careTeam.map((teamMember, i) => (
                  <span key={i} className="px-3 py-1.5 bg-slate-50 text-slate-600 rounded-lg text-[10px] font-black border border-slate-100">{teamMember}</span>
                ))}
              </div>
           </div>
        </section>

        {/* MEDICATION */}
        <section className="space-y-4">
           <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] border-b border-slate-50 pb-2">Current Medications</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {handover.background.medications.map((med, i) => (
                <div key={i} className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100 flex justify-between items-center">
                   <p className="font-black text-slate-800">{med}</p>
                </div>
              ))}
              {handover.background.medications.length === 0 && <p className="text-slate-400 italic">No active medications logged.</p>}
           </div>
        </section>

        {/* AI SYNTHESIS */}
        <section className="space-y-6">
           <div className="flex items-center justify-between">
              <h3 className="text-xs font-black text-teal-600 uppercase tracking-[0.3em]">AI Narrative Interpretation</h3>
              <button onClick={generateAIAnalysis} disabled={loading} className="text-[10px] font-black text-indigo-600 uppercase tracking-widest hover:underline">{loading ? 'Synthesizing...' : 'Generate AI ISBAR Synthesis ✨'}</button>
           </div>
           {aiIsbar ? (
             <div className="bg-slate-50 p-10 rounded-[3rem] border border-indigo-50 font-bold italic text-slate-700 leading-relaxed whitespace-pre-wrap animate-in zoom-in-95">
                {aiIsbar}
             </div>
           ) : (
             <div className="p-10 border-4 border-dashed border-slate-50 rounded-[3rem] text-center">
                <p className="text-slate-300 font-black uppercase tracking-widest text-[10px]">No AI narrative generated yet</p>
             </div>
           )}
        </section>
      </div>

      <div className="bg-indigo-900 p-10 rounded-[3rem] text-white shadow-2xl flex flex-col md:flex-row items-center gap-8 relative overflow-hidden">
        <div className="absolute top-0 right-0 -mr-10 -mt-10 w-40 h-40 bg-white/10 rounded-full blur-2xl"></div>
        <div className="w-20 h-20 bg-white/10 rounded-[2rem] flex items-center justify-center text-5xl">📋</div>
        <div>
           <h4 className="text-2xl font-black italic tracking-tighter">Usage Note</h4>
           <p className="text-indigo-100 font-medium leading-relaxed italic mt-2 opacity-80">
             Providing a combined <strong>Handover + Governance Log</strong> bundle ensures clinicians have full visibility into the system's decision rationale and identified red flags.
           </p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useConnectivity } from '../hooks/useConnectivity';
import { useGovernance } from '../context/GovernanceContext';
import { useEnvironment } from '../context/EnvironmentContext';
import { useRole } from '../context/RoleContext';
import { evaluateRedFlags } from '../clinical/redFlags';
import { evaluateIMCIRedFlags } from '../clinical/redFlagsIMCI';

const RED_FLAGS_LIST = [
  { text: "Difficulty Breathing", sub: "Grunting, wheezing, or chest sucking in", icon: "🫁" },
  { text: "Infant Fever", sub: "Any fever in a baby under 3 months old", icon: "🌡️" },
  { text: "Altered Level of Consciousness", sub: "Unusually sleepy, floppy, or unresponsive", icon: "😴" },
  { text: "Non-Blanching Rash", sub: "Purple/red spots that don't fade when pressed", icon: "🟣" },
  { text: "Severe Pain", sub: "Inconsolable crying or extreme localized pain", icon: "😫" },
  { text: "Eye Injury/Swelling", sub: "Chemical splash, trauma, or sudden swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC = () => {
  const { addClinicalEvent } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { addEntry } = useGovernance();
  const { mode } = useEnvironment();
  const { role } = useRole();
  const isOnline = useConnectivity();

  const [description, setDescription] = useState('');
  const [temp, setTemp] = useState('');
  const [duration, setDuration] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Derive age in months for red flag engine
  const ageMonths = useMemo(() => {
    if (!childProfile?.dob) return undefined;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
    if (now.getDate() < birth.getDate()) months--;
    return months;
  }, [childProfile]);

  // Integrated Safety Engine - Automatically switches between High-Nuance and IMCI presets
  const activeRedFlags = useMemo(() => {
    const input = {
      ageMonths,
      temperature: temp ? parseFloat(temp) : undefined,
      symptoms: [description],
      durationDays: duration ? parseInt(duration) : undefined,
      environment: mode
    };

    // In Low-Resource or Offline mode, we strictly apply IMCI "General Danger Signs"
    const imciFlags = evaluateIMCIRedFlags({ symptoms: [description] });
    const stdFlags = evaluateRedFlags(input);

    return mode === 'low-resource' ? [...imciFlags, ...stdFlags] : stdFlags;
  }, [ageMonths, temp, description, duration, mode]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection. Please follow deterministic IMCI/Safety red flag guidance below.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);

      // Clinical Governance Logging
      addEntry({
        eventType: "symptom_evaluation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Desc: ${description.slice(0, 50)}... Temp: ${temp || 'N/A'}`,
        outputSummary: `AI triage completed. System flags identified: ${activeRedFlags.map(f => f.id).join(', ') || 'None'}`,
        redFlags: activeRedFlags.map(rf => rf.id),
        disclaimerShown: true
      });
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = () => {
    if (result) {
      addClinicalEvent({
        source: 'Symptoms',
        description: `${description} (Temp: ${temp}°C, Duration: ${duration} days)`,
        date: new Date().toLocaleDateString(),
        severity: result.text.toLowerCase().includes('red') || activeRedFlags.some(f => f.severity === 'Urgent') ? 'High' : 'Low',
        media: image || undefined
      });
      setSaved(true);
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
          <p className="text-slate-500 text-sm font-medium">Capture signs and receive guideline-based analysis.</p>
        </div>
        <div className="flex gap-2">
          {!isOnline && (
            <div className="bg-amber-100 text-amber-700 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border border-amber-200">
              <span>📡</span> Offline
            </div>
          )}
          {mode === 'low-resource' && (
            <div className="bg-rose-100 text-rose-700 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border border-rose-200 shadow-sm">
              <span>🌍</span> WHO IMCI Protocol
            </div>
          )}
        </div>
      </header>

      {/* Mode Disclosure */}
      {mode === 'low-resource' && (
        <div className="bg-amber-50 border border-amber-600 p-6 rounded-[2rem] text-xs font-bold text-amber-900 flex gap-4 items-center animate-in slide-in-from-top-2">
           <span className="text-2xl">🚨</span>
           <p><strong>IMCI Danger Signs Active:</strong> System is monitoring for WHO General Danger Signs. If access to tertiary care is limited, seek immediate professional review for any positive flag.</p>
        </div>
      )}

      {/* PERSISTENT CLINICAL RED FLAGS - Non-dismissible fallback */}
      {activeRedFlags.length > 0 && (
        <div className="space-y-3 animate-in slide-in-from-top-4 duration-500">
          {activeRedFlags.map(flag => (
            <div key={flag.id} className={`p-6 rounded-[2.5rem] border-4 shadow-xl flex items-start gap-6 transition-all ${flag.severity === 'Urgent' ? 'bg-rose-50 border-rose-600' : 'bg-amber-50 border-amber-500'}`}>
              <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-4xl shadow-inner shrink-0 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white animate-pulse' : 'bg-amber-500 text-white'}`}>
                {flag.severity === 'Urgent' ? '🚨' : '⚠️'}
              </div>
              <div className="space-y-1">
                <h4 className={`text-2xl font-black italic tracking-tight ${flag.severity === 'Urgent' ? 'text-rose-900' : 'text-amber-900'}`}>
                  {flag.message}
                </h4>
                <p className={`text-sm font-bold leading-relaxed ${flag.severity === 'Urgent' ? 'text-rose-800/80' : 'text-amber-800/80'}`}>
                  {flag.subtext}
                </p>
                <div className="pt-2">
                  <a href="tel:000" className={`inline-flex items-center gap-2 px-6 py-2 rounded-xl font-black text-xs uppercase tracking-widest shadow-md transition-all active:scale-95 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white' : 'bg-amber-600 text-white'}`}>
                    📞 Call 000 / Emergency
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Temperature (°C)</label>
                 <div className="relative">
                   <input 
                     type="number" step="0.1" value={temp} onChange={e => setTemp(e.target.value)} placeholder="37.0"
                     className="w-full p-4 pl-12 rounded-2xl border border-slate-100 bg-slate-50/30 font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                   />
                   <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xl opacity-40">🌡️</span>
                 </div>
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Duration (Days)</label>
                 <div className="relative">
                    <input 
                      type="number" min="0" value={duration} onChange={e => setDuration(e.target.value)} placeholder="0"
                      className="w-full p-4 pl-12 rounded-2xl border border-slate-100 bg-slate-50/30 font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    />
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xl opacity-40">📅</span>
                 </div>
               </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Symptom Description</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Barking cough, lethargy, persistent vomiting, no wet nappies..."
                className="w-full h-32 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none text-slate-900 placeholder-slate-400 transition-all"
              />
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase tracking-widest w-full sm:w-auto transition-all ${image ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-slate-500 shadow-sm'}`}>
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button 
                onClick={handleAnalyze} 
                disabled={loading || (!description.trim() && !image)} 
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'}`}
              >
                {!isOnline ? 'Internet Required for AI' : loading ? 'Reviewing Protocols...' : 'Analyze Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto group animate-in zoom-in-95">
                <img src={image} alt="Symptom Evidence" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-4 right-4 bg-white text-rose-500 w-10 h-10 rounded-full flex items-center justify-center shadow-xl font-black hover:bg-rose-50 transition-colors">✕</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[4rem] shadow-2xl border-l-[20px] border-l-indigo-600 animate-in slide-in-from-bottom-6 duration-700 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl"></div>
              <div className="flex justify-between items-center mb-10 relative z-10">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">✨</div>
                    <h3 className="text-3xl font-black text-slate-800 italic tracking-tighter">AI Synthesis</h3>
                 </div>
                 <button onClick={handleSave} disabled={saved} className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all ${saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700 hover:bg-indigo-200 active:scale-95'}`}>
                  {saved ? '✓ Event Logged' : 'Sync to Medical Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-xl leading-relaxed relative z-10">{result.text}</div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden border-4 border-rose-500 group">
             <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px] group-hover:scale-110 transition-transform duration-1000"></div>
             <div className="relative z-10 mb-10">
                <div className="flex items-center gap-3 mb-2">
                   <span className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-2xl animate-pulse">🚩</span>
                   <h3 className="text-3xl font-black italic tracking-tighter">EMERGENCY</h3>
                </div>
                <p className="text-rose-100 text-[10px] font-black uppercase tracking-[0.2em] border-t border-white/20 pt-3">Seek Immediate Care for:</p>
             </div>
             <div className="space-y-4 relative z-10">
                {RED_FLAGS_LIST.map((f, i) => (
                  <div key={i} className="bg-white/10 p-5 rounded-3xl flex items-start gap-4 border border-white/5 backdrop-blur-sm hover:bg-white/15 transition-colors cursor-default">
                    <span className="text-4xl shrink-0 drop-shadow-lg">{f.icon}</span>
                    <div>
                      <span className="text-base font-black leading-tight block">{f.text}</span>
                      <span className="text-[10px] font-bold text-rose-100/70 block mt-1 leading-relaxed italic">{f.sub}</span>
                    </div>
                  </div>
                ))}
             </div>
             <div className="mt-10 relative z-10">
                <a href="tel:000" className="block w-full py-6 bg-white text-rose-600 rounded-[2rem] text-center font-black text-4xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 hover:brightness-105">
                  <span className="text-2xl opacity-50">📞</span> 000
                </a>
             </div>
          </div>

          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-lg space-y-4">
             <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">💡</div>
             <h4 className="text-xl font-black text-slate-800 tracking-tight">Parenting Note</h4>
             <p className="text-slate-500 text-xs font-medium leading-relaxed italic">
               You know your child best. If you feel something is "just not right", trust your intuition even if the system doesn't flag it.
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export type UserRole = 'parent' | 'clinician';
export type EnvironmentMode = 'standard' | 'low-resource';

export interface ClinicalEvent {
  id: string;
  source: string;
  description: string;
  date: string;
  severity: 'Low' | 'Medium' | 'High';
  media?: string;
}

export interface AttachmentAnalysis {
  caregiverObservations?: string;
}

export interface Appointment {
