  { id: "loss-skills", ageRange: "All Ages", category: "Cognitive", description: "CRITICAL CONCERN: Loss of any skill. Example: A child who used to say 10 words now says none, or a child who used to walk now only crawls.", completed: false, isRedFlag: true },
];

export const MilestoneNavigator: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);

  // Initialize milestones in history if not present
  useEffect(() => {
    if (!history.milestones || history.milestones.length === 0) {
      updateHistory({ milestones: INITIAL_DATA });
    }
  }, [history.milestones, updateHistory]);

  const milestones = history.milestones || [];

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    updateHistory({ milestones: updated });

    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed) {
      addClinicalEvent({ 
        source: 'Development', 
        description: `Concern (${item.ageRange}): ${item.description.split('. Example:')[0]}`, 
        date: new Date().toLocaleDateString(), 
        severity: 'Medium' 
      });
    }
  };

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '9 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];

  const filteredData = useMemo(() => {
    return milestones.filter(m => m.ageRange === activeAge && m.isRedFlag === showRedFlags);
  }, [milestones, activeAge, showRedFlags]);

  const CategoryBadge = ({ category }: { category: string }) => {
    const colors: Record<string, string> = {
      Motor: 'bg-blue-50 text-blue-600 border-blue-100',
      Language: 'bg-purple-50 text-purple-600 border-purple-100',
      Social: 'bg-pink-50 text-pink-600 border-pink-100',
      Cognitive: 'bg-amber-50 text-amber-600 border-amber-100',
    };
    return <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border ${colors[category] || 'bg-slate-50 text-slate-500 border-slate-100'}`}>{category}</span>;
  };

  return (
    <div className="space-y-6 pb-20">
      <header className="px-1">
        <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Milestone <span className="text-teal-600">Screen</span></h2>
        <p className="text-slate-500 text-xs font-medium italic mt-1">Standardized developmental tracking.</p>
      </header>

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/80 backdrop-blur-md py-2 overflow-x-auto no-scrollbar">
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm min-w-max">
          {ageGroups.map(age => (
            <button key={age} onClick={() => setActiveAge(age)} className={`px-4 py-2.5 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeAge === age ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>{age}</button>
          ))}
        </div>
      </nav>

      <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm max-w-sm">
        <button onClick={() => setShowRedFlags(false)} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400'}`}>Typical</button>
        <button onClick={() => setShowRedFlags(true)} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-50 text-rose-700' : 'text-slate-400'}`}>Concerns</button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 animate-in slide-in-from-bottom-4">
        {filteredData.map(m => (
          <button key={m.id} onClick={() => toggleMilestone(m.id)} className={`p-5 rounded-3xl border-2 text-left transition-all h-full flex flex-col justify-between ${m.completed ? (showRedFlags ? 'bg-rose-50 border-rose-200' : 'bg-emerald-50 border-emerald-200') : 'bg-white border-slate-100 hover:border-indigo-100 shadow-sm'}`}>
            <div>
              <div className="flex justify-between items-start mb-4">
                <CategoryBadge category={m.category} />
                <div className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${m.completed ? (showRedFlags ? 'bg-rose-600 text-white' : 'bg-emerald-600 text-white') : 'border-slate-100'}`}>{m.completed && '✓'}</div>
              </div>
              <p className="text-base font-black text-slate-800 leading-tight tracking-tight">{m.description.split('. Example:')[0]}</p>
            </div>
            {m.isRedFlag && !m.completed && <div className="mt-4 flex items-center gap-1.5 text-rose-500 font-black text-[9px] uppercase"><span className="animate-pulse text-base">⚠️</span>Review if observed</div>}
          </button>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { HealthCheck, Vaccination } from '../types';
import { VaccineTracker } from './VaccineTracker';
import { GrowthTracker } from './GrowthTracker';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';

const INITIAL_CHECKS: HealthCheck[] = [
  { id: '1', ageMilestone: 'Birth', completed: false, notes: '' },
  { id: '2', ageMilestone: '1-4 Weeks', completed: false, notes: '' },
  { id: '3', ageMilestone: '6-8 Weeks', completed: false, notes: '' },
  { id: '4', ageMilestone: '4 Months', completed: false, notes: '' },
  { id: '5', ageMilestone: '6 Months', completed: false, notes: '' },
  { id: '6', ageMilestone: '12 Months', completed: false, notes: '' },
  { id: '7', ageMilestone: '18 Months', completed: false, notes: '' },
  { id: '8', ageMilestone: '2 Years', completed: false, notes: '' },
  { id: '9', ageMilestone: '3.5-4 Years', completed: false, notes: '' },
];

export const RedBook: React.FC = () => {
  const { history, updateHistory } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const [checks, setChecks] = useState<HealthCheck[]>(INITIAL_CHECKS);
  const [activeTab, setActiveTab] = useState<'checks' | 'vax' | 'growth'>('checks');
  const [activeCheck, setActiveCheck] = useState<string | null>(null);

  const alerts = useMemo(() => {
    const vaccinations = history.vaccinations || [];
    const growthRecords = history.growthRecords || [];
    const milestones = history.milestones || [];

    // Pattern: Overdue Vaccines
    const overdueVax = vaccinations.filter(v => v.status === 'pending' && new Date() > new Date(v.dueDate));
    const vaxClusterConcern = overdueVax.length >= 3;

    // Pattern: Growth
    let growthAlert = false;
    let growthSeverity: 'Low' | 'High' = 'Low';
    if (growthRecords.length >= 2) {
      const last = growthRecords[growthRecords.length - 1];
      const prev = growthRecords[growthRecords.length - 2];
      if (last.weight < prev.weight) {
        growthAlert = true;
        growthSeverity = 'High';
      } else if (last.weight === prev.weight && last.age > prev.age) {
        growthAlert = true; 
        growthSeverity = 'Low';
      }
    }

    // Pattern: Development Red Flags
    const activeRedFlags = milestones.filter(m => m.isRedFlag && m.completed);
    const incompleteRedFlagWarnings = milestones.filter(m => m.isRedFlag && !m.completed && m.ageRange === 'All Ages');

    return { overdueVax, vaxClusterConcern, growthAlert, growthSeverity, activeRedFlags, incompleteRedFlagWarnings };
  }, [history.vaccinations, history.growthRecords, history.milestones]);

  const toggleCheck = (id: string) => {
    setChecks(prev => prev.map(c => c.id === id ? { ...c, completed: !c.completed } : c));
  };

  const updateNotes = (id: string, notes: string) => {
    setChecks(prev => prev.map(c => c.id === id ? { ...c, notes } : c));
  };

  const getVaxStatusForMilestone = (milestone: string): Vaccination | undefined => {
    if (!history.vaccinations) return undefined;
    // Map milestone strings to vax age milestones
    const map: Record<string, number> = {
      'Birth': 0,
      '6-8 Weeks': 2,
      '4 Months': 4,
      '6 Months': 6,
      '12 Months': 12,
      '18 Months': 18
    };
    const age = map[milestone];
    return history.vaccinations.find(v => v.ageMilestone === age);
  };

  const hasAlerts = alerts.overdueVax.length > 0 || alerts.growthAlert || alerts.activeRedFlags.length > 0;

  const tabs = [
    { id: 'checks', label: 'Checks', icon: '🗓️' },
    { id: 'vax', label: 'Vax', icon: '💉' },
    { id: 'growth', label: 'Growth', icon: '📉' }
  ];

  return (
    <div className="space-y-6 pb-32">
      {hasAlerts && (
        <div className="bg-white rounded-3xl border-2 border-rose-500 shadow-xl overflow-hidden animate-in slide-in-from-top-4">
          <div className="bg-rose-600 px-6 py-3 flex items-center justify-between text-white">
            <div className="flex items-center gap-2">
              <span className="animate-bounce">🚨</span>
              <h3 className="font-black text-[10px] uppercase tracking-widest">Clinical Patterns of Concern</h3>
            </div>
          </div>
          <div className="p-5 space-y-4">
            {alerts.overdueVax.length > 0 && (
              <div className="flex items-start gap-3 bg-rose-50 p-4 rounded-2xl border border-rose-100">
                <span className="text-xl">💉</span>
                <div className="flex-1">
                  <p className="font-black text-rose-900 text-sm">
                    {alerts.vaxClusterConcern ? 'Significant Missed Immunisations' : 'Missed Immunisations'}
                  </p>
                  <p className="text-rose-700/70 text-[10px] font-bold leading-tight mt-0.5">
                    {alerts.vaxClusterConcern 
                      ? `${alerts.overdueVax.length} doses are overdue. Cluster missing increases community risk. Contact GP immediately.`
                      : `A dose is overdue. Contact GP clinic to schedule.`}
                  </p>
                </div>
              </div>
            )}
            {alerts.activeRedFlags.length > 0 && (
              <div className="flex items-start gap-3 bg-rose-100 p-4 rounded-2xl border border-rose-200">
                <span className="text-xl">🚩</span>
                <div className="flex-1">
                  <p className="font-black text-rose-900 text-sm">Developmental Red Flags Identified</p>
                  <p className="text-rose-800 text-[10px] font-bold leading-tight mt-0.5">
                    {alerts.activeRedFlags.length} observed concerns require clinical review by a Pediatrician.
                  </p>
                </div>
              </div>
            )}
            {alerts.growthAlert && (
              <div className={`flex items-start gap-3 p-4 rounded-2xl border ${alerts.growthSeverity === 'High' ? 'bg-rose-50 border-rose-100' : 'bg-amber-50 border-amber-100'}`}>
                <span className="text-xl">{alerts.growthSeverity === 'High' ? '📉' : '⚖️'}</span>
                <div className="flex-1">
                  <p className={`font-black text-sm ${alerts.growthSeverity === 'High' ? 'text-rose-900' : 'text-amber-900'}`}>
                    {alerts.growthSeverity === 'High' ? 'Weight Faltering' : 'Growth Plateau'}
                  </p>
                  <p className={`text-[10px] font-bold leading-tight mt-0.5 ${alerts.growthSeverity === 'High' ? 'text-rose-700/70' : 'text-amber-700/70'}`}>
                    {alerts.growthSeverity === 'High' ? 'Review with Pediatrician immediately.' : 'Monitor feeding and discuss at next review.'}
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      <header className="flex items-center gap-4 px-1">
        <div className="w-12 h-16 bg-rose-600 rounded-xl flex items-center justify-center text-white font-black text-xs rotate-[-3deg] border-2 border-white shadow-lg uppercase">Book</div>
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tighter italic">Digital <span className="text-rose-600">Red Book</span></h2>
          <p className="text-slate-500 text-xs font-medium italic">Standardized Child Health Record</p>
        </div>
      </header>

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/80 backdrop-blur-md py-2">
        <div className="bg-white p-1 rounded-full border border-slate-200 shadow-sm flex items-center">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => {
                setActiveTab(tab.id as any);
                window.scrollTo({ top: 0, behavior: 'smooth' });
              }}
              className={`flex-1 py-3.5 rounded-full font-black transition-all text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 ${
                activeTab === tab.id ? 'bg-rose-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <span className="text-lg">{tab.icon}</span>
              <span className="hidden sm:inline">{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden min-h-[500px] animate-in slide-in-from-bottom-4">
        {activeTab === 'checks' && (
          <div className="p-5 sm:p-8 space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <span className="text-rose-500">📅</span> Health Assessments
              </h3>
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-lg">
                Link: Vax Record Integrated
              </span>
            </div>

            <div className="space-y-4 relative before:absolute before:left-5 before:top-4 before:bottom-4 before:w-0.5 before:bg-slate-100">
              {checks.map((check) => {
                const vax = getVaxStatusForMilestone(check.ageMilestone);
                return (
                  <div key={check.id} className="relative pl-12">
                    <button 
                      onClick={() => toggleCheck(check.id)}
                      className={`absolute left-0 w-10 h-10 rounded-2xl border-2 flex items-center justify-center transition-all z-10 shadow-sm ${
                        check.completed ? 'bg-rose-600 border-rose-500 text-white' : 'bg-white border-slate-100 text-slate-200'
                      }`}
                    >
                      {check.completed ? '✓' : ''}
                    </button>
                    <div 
                      className={`p-5 rounded-3xl border transition-all cursor-pointer ${
                        activeCheck === check.id ? 'border-rose-100 bg-rose-50/30' : 'border-slate-50 bg-white shadow-sm hover:border-rose-100'
                      }`}
                      onClick={() => setActiveCheck(activeCheck === check.id ? null : check.id)}
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h4 className="font-black text-lg text-slate-800 tracking-tight">{check.ageMilestone} Check</h4>
                          <div className="flex gap-2 mt-1">
                            {check.completed && <span className="text-[8px] font-black text-emerald-600 uppercase">Check Done</span>}
                            {vax && (
                              <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${
                                vax.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'
                              }`}>
                                {vax.status === 'completed' ? 'Vax Completed' : 'Vax Due'}
                              </span>
                            )}
                          </div>
                        </div>
                        <span className="text-slate-300 text-xs">▼</span>
                      </div>
                      {activeCheck === check.id && (
                        <div className="mt-4 space-y-4 animate-in slide-in-from-top-2">
                          <textarea 
                            className="w-full h-28 p-4 rounded-2xl border border-slate-100 bg-white text-sm font-bold italic outline-none focus:ring-2 focus:ring-rose-500"
                            placeholder="Nurse observations..."
                            value={check.notes}
                            onClick={(e) => e.stopPropagation()}
                            onChange={(e) => updateNotes(check.id, e.target.value)}
                          />
                          {vax && vax.status === 'pending' && (
                            <button 
                              onClick={(e) => { e.stopPropagation(); setActiveTab('vax'); }}
                              className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl font-black text-[10px] uppercase tracking-widest border border-rose-100"
                            >
                              Go to Vaccine Tracker for this age
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {activeTab === 'vax' && (
          <div className="p-4 sm:p-8">
             <VaccineTracker />
          </div>
        )}

        {activeTab === 'growth' && (
          <div className="p-4 sm:p-8">
             <GrowthTracker />
          </div>
        )}
      </div>
    </div>
  );
};

