const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "AUSTRALIAN 4x4 PROTOCOL:\n1. Give 4 puffs of blue reliever via spacer.\n2. Wait 4 minutes.\n3. Repeat if no improvement.",
    triggers: "Viral colds, exercise, weather changes.",
    emergencyMeds: "Salbutamol 100mcg via spacer.",
    fluidRequirements: "Encourage small, frequent sips.",
    emergencyContact: "GP Clinic, 1800 022 222, or 000."
  }
};

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [pendingExtraction, setPendingExtraction] = useState<any | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active', notes: '' });
  const [newInvestigation, setNewInvestigation] = useState<Partial<Investigation>>({ name: '', result: '', date: new Date().toISOString().split('T')[0] });

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      setPendingExtraction(null);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          // Stage extraction for user review
          setPendingExtraction({ ...result, photoUrl: reader.result as string });
          setActiveTab('reports');
        } catch (err) {
          alert("Failed to analyze report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const syncExtractionToProfile = () => {
    if (!pendingExtraction) return;

    const newReport: MedicalReport = {
      id: crypto.randomUUID(),
      date: new Date().toLocaleDateString(),
      specialist: pendingExtraction.specialist.name,
      summary: pendingExtraction.summary,
      actionItems: pendingExtraction.actionItems,
      photoUrl: pendingExtraction.photoUrl
    };

    const newConditions: Condition[] = (pendingExtraction.foundDiagnoses || []).map((d: string) => ({
      id: crypto.randomUUID(),
      name: d,
      status: 'Active',
      dateDiagnosed: new Date().toLocaleDateString(),
      clinicianVerified: false,
      notes: `Extracted from ${pendingExtraction.specialist.name} letter`
    }));

    const newMeds: Medication[] = (pendingExtraction.foundMedications || []).map((m: any) => ({
      ...m,
      id: crypto.randomUUID(),
      startDate: new Date().toISOString()
    }));

    updateHistory({ 
      medicalReports: [...(history.medicalReports || []), newReport],
      conditions: [...(history.conditions || []), ...newConditions],
      currentMedications: [...(history.currentMedications || []), ...newMeds]
    });

    setPendingExtraction(null);
    alert("Profile updated with extracted details.");
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '' });
    }
  };

