import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';

const SICK_DAY_TEMPLATES: Record<string, Partial<SickDayPlan>> = {
  asthma: {
    instructions: "AUSTRALIAN 4x4 PROTOCOL:\n1. Give 4 puffs of blue reliever via spacer.\n2. Wait 4 minutes.\n3. Repeat if no improvement.",
    triggers: "Viral colds, exercise, weather changes.",
    emergencyMeds: "Salbutamol 100mcg via spacer.",
    fluidRequirements: "Encourage small, frequent sips.",
    emergencyContact: "GP Clinic, 1800 022 222, or 000."
  }
};

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, addAcuteLog, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [pendingExtraction, setPendingExtraction] = useState<any | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // Clinician Physical Exam State
  const [examObs, setExamObs] = useState({
    hr: '', rr: '', spo2: '', crt: 'Normal (<2s)', workOfBreathing: 'Normal', appearance: 'Well/Interactive', neuro: 'AVPU: A'
  });

  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active', notes: '' });
  const [newInvestigation, setNewInvestigation] = useState<Partial<Investigation>>({ name: '', result: '', date: new Date().toISOString().split('T')[0] });

  const logClinicianObs = () => {
    const summary = `Obs: HR ${examObs.hr}, RR ${examObs.rr}, SpO2 ${examObs.spo2}%. Perfusion: ${examObs.crt}. WoB: ${examObs.workOfBreathing}. App: ${examObs.appearance}. ${examObs.neuro}.`;
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Physical Exam',
      value: 'Physical Assessment Logged',
      notes: summary,
      clinicianLogged: true
    });
    alert("Clinical assessment logged to child's history.");
    setExamObs({ hr: '', rr: '', spo2: '', crt: 'Normal (<2s)', workOfBreathing: 'Normal', appearance: 'Well/Interactive', neuro: 'AVPU: A' });
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      setPendingExtraction(null);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          setPendingExtraction({ ...result, photoUrl: reader.result as string });
          setActiveTab('reports');
        } catch (err) {
          alert("Failed to analyze report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const syncExtractionToProfile = () => {
    if (!pendingExtraction) return;

    const newReport: MedicalReport = {
      id: crypto.randomUUID(),
      date: new Date().toLocaleDateString(),
      specialist: pendingExtraction.specialist.name,
      summary: pendingExtraction.summary,
      actionItems: pendingExtraction.actionItems,
      photoUrl: pendingExtraction.photoUrl
    };

    const newConditions: Condition[] = (pendingExtraction.foundDiagnoses || []).map((d: string) => ({
      id: crypto.randomUUID(),
      name: d,
      status: 'Active',
      dateDiagnosed: new Date().toLocaleDateString(),
      clinicianVerified: role === 'clinician',
      notes: `AI Extraction from ${pendingExtraction.specialist.name} letter`
    }));

    const newMeds: Medication[] = (pendingExtraction.foundMedications || []).map((m: any) => ({
      ...m,
      id: crypto.randomUUID(),
      startDate: new Date().toISOString()
    }));

    updateHistory({ 
      medicalReports: [...(history.medicalReports || []), newReport],
      conditions: [...(history.conditions || []), ...newConditions],
      currentMedications: [...(history.currentMedications || []), ...newMeds]
    });

    setPendingExtraction(null);
    alert("Profile updated with extracted details.");
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '' });
    }
  };

  const addIssue = () => {
    if (newIssue.name) {
      const issue: Condition = {
        id: crypto.randomUUID(),
        name: newIssue.name,
        status: newIssue.status as any,
        notes: newIssue.notes,
        dateDiagnosed: new Date().toISOString().split('T')[0],
        clinicianVerified: role === 'clinician'
      };
      updateHistory({ conditions: [...(history.conditions || []), issue] });
      setNewIssue({ name: '', status: 'Active', notes: '' });
    }
  };

  const addInvestigation = () => {
    if (newInvestigation.name) {
      const inv: Investigation = {
        id: crypto.randomUUID(),
        name: newInvestigation.name,
        result: newInvestigation.result || '',
        date: newInvestigation.date || new Date().toISOString().split('T')[0]
      };
      updateHistory({ investigations: [...(history.investigations || []), inv] });
      setNewInvestigation({ name: '', result: '', date: new Date().toISOString().split('T')[0] });
    }
  };

  const handleApplySickDayTemplate = (type: string) => {
    const template = SICK_DAY_TEMPLATES[type];
    if (template) {
      updateHistory({ sickDayPlan: { ...history.sickDayPlan, ...template } });
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'sickday', label: 'Sick Day', icon: '🚨' }
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 text-sm font-medium">Shared clinical repository for parents and care teams.</p>
        </div>
        <button onClick={handleGenerateHandover} disabled={loading} className="bg-indigo-600 text-white px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all active:scale-95">
          {loading ? 'Analyzing...' : 'Generate ISBAR Handover ✨'}
        </button>
      </header>

      {/* ROLE INDICATOR */}
      <div className={`p-4 rounded-2xl border flex items-center justify-between ${role === 'clinician' ? 'bg-slate-900 border-slate-800 text-white' : 'bg-indigo-50 border-indigo-100 text-indigo-700'}`}>
         <div className="flex items-center gap-3">
           <span className="text-xl">{role === 'clinician' ? '👨‍⚕️' : '👪'}</span>
           <span className="text-[10px] font-black uppercase tracking-widest">Currently Viewing as {role}</span>
         </div>
         {role === 'clinician' && <span className="bg-indigo-600 px-2 py-0.5 rounded text-[8px] font-black uppercase">Technical Entry Enabled</span>}
      </div>

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-2 overflow-x-auto no-scrollbar">
        <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex min-w-max">
          {tabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
              <span className="text-lg">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl min-h-[500px] p-8">

        {/* CLINICIAN PHYSICAL EXAM PANEL (Exclusive to Clinician Role) */}
        {role === 'clinician' && activeTab === 'history' && (
           <div className="mb-12 bg-slate-50 p-8 rounded-[3rem] border border-slate-200 space-y-8 animate-in slide-in-from-top-4">
              <div className="flex justify-between items-center">
                 <h3 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em]">Physical Exam / Clinician Quick-Log</h3>
                 <span className="text-[9px] font-black text-indigo-600 uppercase">Synchronizes to Parent Log</span>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Heart Rate</label>
                    <input type="number" placeholder="bpm" value={examObs.hr} onChange={e => setExamObs({...examObs, hr: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-sm font-black" />
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Resp Rate</label>
                    <input type="number" placeholder="breaths/m" value={examObs.rr} onChange={e => setExamObs({...examObs, rr: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-sm font-black" />
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">SpO2 (%)</label>
                    <input type="number" placeholder="%" value={examObs.spo2} onChange={e => setExamObs({...examObs, spo2: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-sm font-black" />
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Cap Refill (s)</label>
                    <select value={examObs.crt} onChange={e => setExamObs({...examObs, crt: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black">
                       <option>Normal (<2s)</option>
                       <option>Delayed (2-3s)</option>
                       <option>Prolonged (>3s)</option>
                    </select>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Work of Breathing</label>
                    <select value={examObs.workOfBreathing} onChange={e => setExamObs({...examObs, workOfBreathing: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black">
                       <option>Normal</option>
                       <option>Increased (Tug/Recessions)</option>
                       <option>Significant Distress</option>
                    </select>
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Appearance</label>
                    <select value={examObs.appearance} onChange={e => setExamObs({...examObs, appearance: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black">
                       <option>Well/Interactive</option>
                       <option>Irritable but Consolable</option>
                       <option>Unwell/Lethargic</option>
                    </select>
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Neuro Status</label>
                    <select value={examObs.neuro} onChange={e => setExamObs({...examObs, neuro: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black">
                       <option>AVPU: A</option>
                       <option>AVPU: V</option>
                       <option>AVPU: P</option>
                       <option>AVPU: U</option>
                    </select>
                 </div>
              </div>
              <button onClick={logClinicianObs} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-black transition-all">Submit Physical Assessment</button>
           </div>
        )}

        {/* EXTRACTION REVIEW (From specialist letters) */}
        {pendingExtraction && activeTab === 'reports' && (
          <div className="mb-10 bg-indigo-50 border-2 border-indigo-200 p-8 rounded-[3rem] animate-in zoom-in-95 space-y-6">
             <div className="flex justify-between items-start">
               <div className="flex items-center gap-4">
                 <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-3xl shadow-sm border border-indigo-100">✨</div>
                 <div>
                   <h4 className="text-2xl font-black text-indigo-900 tracking-tight italic">New Information Found</h4>
                   <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">Review AI Extraction from Specialist Letter</p>
                 </div>
               </div>
               <button onClick={() => setPendingExtraction(null)} className="text-indigo-300 hover:text-rose-500 text-xl font-black">✕</button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white/60 p-6 rounded-3xl border border-indigo-100">
                   <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-3">Diagnoses Found</p>
                   <div className="flex flex-wrap gap-2">
                     {pendingExtraction.foundDiagnoses?.length > 0 ? pendingExtraction.foundDiagnoses.map((d: string) => (
                       <span key={d} className="px-3 py-1 bg-white text-indigo-700 rounded-lg text-xs font-black border border-indigo-200">+ {d}</span>
                     )) : <p className="text-slate-400 italic text-xs">No specific diagnoses detected.</p>}
                   </div>
                </div>
                <div className="bg-white/60 p-6 rounded-3xl border border-indigo-100">
                   <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-3">Medications Mentioned</p>
                   <div className="space-y-2">
                     {pendingExtraction.foundMedications?.length > 0 ? pendingExtraction.foundMedications.map((m: any) => (
                       <p key={m.name} className="text-xs font-black text-indigo-900">• {m.name} {m.dose}</p>
                     )) : <p className="text-slate-400 italic text-xs">No new medications detected.</p>}
                   </div>
                </div>
             </div>

             <button 
              onClick={syncExtractionToProfile}
              className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all flex items-center justify-center gap-3"
             >
               <span>📥</span> Sync all findings to longitudinal profile
             </button>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><span className="text-indigo-600">📜</span> Medical History</h3>
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">PMHx</span>
                </div>
                <textarea 
                  value={history.pastMedicalHistory} 
                  onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} 
                  placeholder="Known chronic conditions, developmental diagnoses..."
                  className="w-full h-48 p-6 rounded-3xl border border-slate-100 bg-slate-50/50 outline-none font-bold italic resize-none text-slate-900 focus:ring-2 focus:ring-indigo-500" 
                />
              </section>
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><span className="text-rose-600">✂️</span> Surgical History</h3>
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">PSHx</span>
                </div>
                <textarea 
                  value={history.surgicalHistory} 
                  onChange={e => updateHistory({ surgicalHistory: e.target.value })} 
                  placeholder="Previous operations, hospitalisations, procedures..."
                  className="w-full h-48 p-6 rounded-3xl border border-slate-100 bg-slate-50/50 outline-none font-bold italic resize-none text-slate-900 focus:ring-2 focus:ring-rose-500" 
                />
              </section>
            </div>

            {/* Active Issues List */}
            <section className="space-y-6">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><span className="text-amber-500">🚩</span> Issues List</h3>
                <span className={`text-[9px] font-black uppercase px-2 py-1 rounded ${role === 'clinician' ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
                  {role === 'clinician' ? 'Clinician Entry Active' : 'Parent View'}
                </span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(history.conditions || []).map(issue => (
                  <div key={issue.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 flex justify-between items-center shadow-sm">
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-black text-slate-800">{issue.name}</p>
                        {issue.clinicianVerified && <span className="text-[8px] bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded font-black uppercase">Verified</span>}
                      </div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{issue.status} • {issue.dateDiagnosed}</p>
                      {issue.notes && <p className="text-[10px] font-medium text-slate-500 italic mt-1">{issue.notes}</p>}
                    </div>
                    <button onClick={() => updateHistory({ conditions: history.conditions?.filter(x => x.id !== issue.id) })} className="text-slate-300 hover:text-rose-500 transition-colors">✕</button>
                  </div>
                ))}
                <div className="bg-white p-6 rounded-3xl border-2 border-dashed border-slate-100 space-y-4">
                  <div className="grid grid-cols-2 gap-2">
                    <input 
                      placeholder="Issue Name" 
                      value={newIssue.name} 
                      onChange={e => setNewIssue({...newIssue, name: e.target.value})} 
                      className="p-3 rounded-xl bg-slate-50 text-xs font-bold outline-none border border-transparent focus:border-indigo-100"
                    />
                    <select 
                      value={newIssue.status} 
                      onChange={e => setNewIssue({...newIssue, status: e.target.value as any})}
                      className="p-3 rounded-xl bg-slate-50 text-xs font-bold outline-none border border-transparent focus:border-indigo-100"
                    >
                      <option>Active</option>
                      <option>Under Investigation</option>
                      <option>Resolved</option>
                    </select>
                  </div>
                  <button onClick={addIssue} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest">Add Issue</button>
                </div>
              </div>
            </section>

            {/* Investigations */}
            <section className="space-y-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><span className="text-teal-600">🔬</span> Previous Investigations</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {(history.investigations || []).map(inv => (
                  <div key={inv.id} className="bg-teal-50/30 p-6 rounded-3xl border border-teal-100 flex justify-between items-start">
                    <div>
                      <p className="text-[9px] font-black text-teal-600 uppercase tracking-widest">{inv.date}</p>
                      <p className="font-black text-teal-900">{inv.name}</p>
                      <p className="text-xs font-bold text-teal-700/70 italic mt-1">"{inv.result}"</p>
                    </div>
                    <button onClick={() => updateHistory({ investigations: history.investigations?.filter(x => x.id !== inv.id) })} className="text-teal-200 hover:text-rose-500">✕</button>
                  </div>
                ))}
                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-3">
                   <input type="date" value={newInvestigation.date} onChange={e => setNewInvestigation({...newInvestigation, date: e.target.value})} className="w-full p-2 rounded-lg bg-white text-[10px] font-bold border border-slate-100" />
                   <input placeholder="Test (e.g. MRI Brain)" value={newInvestigation.name} onChange={e => setNewInvestigation({...newInvestigation, name: e.target.value})} className="w-full p-2 rounded-lg bg-white text-xs font-bold border border-slate-100" />
                   <input placeholder="Outcome/Result" value={newInvestigation.result} onChange={e => setNewInvestigation({...newInvestigation, result: e.target.value})} className="w-full p-2 rounded-lg bg-white text-xs font-bold border border-slate-100" />
                   <button onClick={addInvestigation} className="w-full py-2.5 bg-teal-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest">Log Investigation</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="space-y-12">
            <section className="space-y-6">
              <h3 className="text-xl font-black text-slate-800">Current Medications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {history.currentMedications.map(m => (
                  <div key={m.id} className="bg-emerald-50/30 p-6 rounded-3xl border border-emerald-100 flex justify-between items-start">
                    <div>
                      <p className="font-black text-emerald-900">{m.name} {m.dose}</p>
                      <p className="text-xs font-bold text-emerald-700/70">{m.instructions}</p>
                      <p className="text-[10px] font-black uppercase text-emerald-600 mt-2 italic">{m.indication}</p>
                    </div>
                    <button onClick={() => updateHistory({ currentMedications: history.currentMedications.filter(x => x.id !== m.id) })} className="text-emerald-300 hover:text-rose-500 transition-colors">✕</button>
                  </div>
                ))}
              </div>
              <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                <input placeholder="Name" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="p-3 rounded-xl border border-slate-100 text-sm font-bold" />
                <input placeholder="Dose" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="p-3 rounded-xl border border-slate-100 text-sm font-bold" />
                <input placeholder="Frequency" value={newMed.instructions} onChange={e => setNewMed({...newMed, instructions: e.target.value})} className="p-3 rounded-xl border border-slate-100 text-sm font-bold" />
                <button onClick={addMedication} className="bg-indigo-600 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest">Add Med</button>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'mdt' && (
          <div className="space-y-8">
            <section className="space-y-6">
              <h3 className="text-xl font-black text-slate-800">Multi-Disciplinary Team (Specialists)</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
