              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Heart Rate</label>
                    <input type="number" placeholder="bpm" value={examObs.hr} onChange={e => setExamObs({...examObs, hr: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-sm font-black shadow-inner" />
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Resp Rate</label>
                    <input type="number" placeholder="breaths/m" value={examObs.rr} onChange={e => setExamObs({...examObs, rr: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-sm font-black shadow-inner" />
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">SpO2 (%)</label>
                    <input type="number" placeholder="%" value={examObs.spo2} onChange={e => setExamObs({...examObs, spo2: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-sm font-black shadow-inner" />
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Cap Refill (s)</label>
                    <select value={examObs.crt} onChange={e => setExamObs({...examObs, crt: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black shadow-inner">
                       <option value="Normal (<2s)">Normal (&lt;2s)</option>
                       <option value="Delayed (2-3s)">Delayed (2-3s)</option>
                       <option value="Prolonged (>3s)">Prolonged (&gt;3s)</option>
                    </select>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Work of Breathing</label>
                    <select value={examObs.workOfBreathing} onChange={e => setExamObs({...examObs, workOfBreathing: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black shadow-inner">
                       <option>Normal</option>
                       <option>Increased (Tug/Recessions)</option>
                       <option>Significant Distress</option>
                    </select>
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Appearance</label>
                    <select value={examObs.appearance} onChange={e => setExamObs({...examObs, appearance: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black shadow-inner">
                       <option>Well/Interactive</option>
                       <option>Irritable but Consolable</option>
                       <option>Unwell/Lethargic</option>
                    </select>
                 </div>
                 <div>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Neuro Status</label>
                    <select value={examObs.neuro} onChange={e => setExamObs({...examObs, neuro: e.target.value})} className="w-full p-3 rounded-xl bg-white border border-slate-200 text-[10px] font-black shadow-inner">
                       <option>AVPU: A</option>
                       <option>AVPU: V</option>
                       <option>AVPU: P</option>
                       <option>AVPU: U</option>
                    </select>
                 </div>
              </div>
              <button onClick={logClinicianObs} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-black transition-all">Submit Physical Assessment</button>
           </div>
        )}

        {/* CLINICIAN CONSULTATION NOTES */}
        {activeTab === 'history' && (
          <section className="mb-12 space-y-4">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <span className="text-indigo-600">✍️</span> Consultation Notes
              </h3>
              {role === 'parent' && <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Clinic Entry</span>}
            </div>
            {role === 'clinician' ? (
              <textarea 
                value={history.consultationNotes} 
                onChange={e => updateHistory({ consultationNotes: e.target.value })} 
                placeholder="Clinic summary, plan, and follow-up. Parents can see these notes."
                className="w-full h-32 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic resize-none text-slate-900 focus:ring-2 focus:ring-indigo-500 shadow-inner" 
              />
            ) : (
              <div className="bg-indigo-50/30 p-8 rounded-[2rem] border border-indigo-100 font-bold italic text-slate-700 leading-relaxed whitespace-pre-wrap">
                {history.consultationNotes || "No clinician notes for this period yet."}
