        {activeTab === 'history' && (
          <div className="space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <section className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><span className="text-indigo-600">📜</span> Medical History</h3>
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">PMHx</span>
                </div>
                <textarea 
                  value={history.pastMedicalHistory} 
                  onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} 
