                  className="w-full h-48 p-6 rounded-3xl border border-slate-100 bg-slate-50/50 outline-none font-bold italic resize-none text-slate-900 focus:ring-2 focus:ring-indigo-500 shadow-inner" 
                />
              </section>
              <section className="space-y-4">
                <div className="flex items-center justify-between">
