                      {issue.notes && <p className="text-[10px] font-medium text-slate-500 italic mt-1">{issue.notes}</p>}
                    </div>
                    <button onClick={() => updateHistory({ conditions: history.conditions?.filter(x => x.id !== issue.id) })} className="text-slate-300 hover:text-rose-500">✕</button>
                  </div>
                ))}
                <div className="bg-white p-6 rounded-3xl border-2 border-dashed border-slate-100 space-y-4">
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="Issue Name" value={newIssue.name} onChange={e => setNewIssue({...newIssue, name: e.target.value})} className="p-3 rounded-xl bg-slate-50 text-xs font-bold outline-none border border-transparent shadow-inner" />
                    <select value={newIssue.status} onChange={e => setNewIssue({...newIssue, status: e.target.value as any})} className="p-3 rounded-xl bg-slate-50 text-xs font-bold shadow-inner">
                      <option>Active</option>
                      <option>Resolved</option>
                    </select>
                  </div>
                  <button onClick={addIssue} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-md">Add Issue</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {/* Meds, Reports, Team, Gear (Simplified for brevity as they haven't changed) */}
        {activeTab === 'meds' && (
          <div className="space-y-6">
            <h3 className="text-xl font-black text-slate-800">Current Medications</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {history.currentMedications.map(m => (
                <div key={m.id} className="bg-emerald-50/30 p-6 rounded-3xl border border-emerald-100 flex justify-between items-start shadow-sm">
                  <div>
                    <p className="font-black text-emerald-900">{m.name} {m.dose}</p>
                    <p className="text-xs font-bold text-emerald-700/70">{m.instructions}</p>
                  </div>
                  <button onClick={() => updateHistory({ currentMedications: history.currentMedications.filter(x => x.id !== m.id) })} className="text-emerald-300 hover:text-rose-500">✕</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* NEW STRUCTURED SICK DAY PLAN */}
        {activeTab === 'sickday' && (
          <div className="space-y-12 animate-in slide-in-from-bottom-6">
             <div className="bg-rose-600 p-8 sm:p-12 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
                <div className="relative z-10 space-y-10">
                   <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                      <div>
                        <h3 className="text-3xl font-black italic tracking-tighter leading-none">Sick Day Action Plan</h3>
                        <p className="text-rose-100/70 text-[10px] font-black uppercase tracking-[0.2em] mt-2">Personalized Acute Protocol</p>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        <button 
                          onClick={() => planPhotoRef.current?.click()}
                          className="px-5 py-3 bg-white/20 rounded-xl text-[9px] font-black uppercase border border-white/20 hover:bg-white/30 transition-all flex items-center gap-2"
                        >
                          <span>📷</span> {history.sickDayPlan.planPhoto ? 'Update Photo' : 'Capture Physical Plan'}
                        </button>
                        <input type="file" accept="image/*" capture="environment" className="hidden" ref={planPhotoRef} onChange={handlePlanPhotoUpload} />
                        {role === 'clinician' && (
                           <div className="relative group">
                              <button className="px-5 py-3 bg-white text-rose-600 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-xl flex items-center gap-2">
                                <span>📋</span> Apply Template
                              </button>
                              <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 overflow-hidden">
                                 {Object.keys(SICK_DAY_TEMPLATES).map(k => (
                                   <button key={k} onClick={() => handleApplySickDayTemplate(k)} className="w-full p-4 text-left text-[9px] font-black uppercase tracking-widest text-slate-500 hover:bg-rose-50 hover:text-rose-600 border-b border-slate-50 transition-colors">
                                      + {k}
                                   </button>
                                 ))}
                              </div>
                           </div>
                        )}
                      </div>
                   </div>

                   {/* Structured Zone Inputs */}
                   <div className="grid grid-cols-1 gap-6">
                      {/* GREEN ZONE */}
                      <div className="bg-emerald-500/20 p-6 rounded-[2.5rem] border border-emerald-400/30 space-y-3">
                         <div className="flex items-center gap-2">
                            <span className="w-4 h-4 rounded-full bg-emerald-400 animate-pulse shadow-[0_0_10px_rgba(52,211,153,0.8)]"></span>
                            <p className="text-[10px] font-black uppercase tracking-widest text-emerald-100">Green Zone: All Well / Regular Care</p>
                         </div>
                         <textarea 
                            value={history.sickDayPlan.greenZone} 
                            onChange={e => updateSickDayField('greenZone', e.target.value)}
                            className="w-full h-24 p-5 rounded-2xl bg-white/10 text-white font-bold text-sm italic outline-none border border-white/10 shadow-inner focus:bg-white/20"
                            placeholder="Routine actions when child is healthy..."
                         />
                      </div>

                      {/* YELLOW ZONE */}
                      <div className="bg-amber-500/20 p-6 rounded-[2.5rem] border border-amber-400/30 space-y-3">
                         <div className="flex items-center gap-2">
                            <span className="w-4 h-4 rounded-full bg-amber-400 shadow-[0_0_10px_rgba(251,191,36,0.8)]"></span>
                            <p className="text-[10px] font-black uppercase tracking-widest text-amber-100">Yellow Zone: Caution / Mild Illness</p>
                         </div>
                         <textarea 
                            value={history.sickDayPlan.yellowZone} 
                            onChange={e => updateSickDayField('yellowZone', e.target.value)}
                            className="w-full h-32 p-5 rounded-2xl bg-white/10 text-white font-bold text-sm italic outline-none border border-white/10 shadow-inner focus:bg-white/20"
                            placeholder="Escalation steps: extra meds, call GP, monitor signs..."
                         />
                      </div>

                      {/* RED ZONE */}
                      <div className="bg-white/10 p-6 rounded-[2.5rem] border border-white/30 space-y-3 shadow-[0_0_30px_rgba(255,255,255,0.05)]">
                         <div className="flex items-center gap-2">
                            <span className="w-4 h-4 rounded-full bg-white animate-bounce"></span>
                            <p className="text-[10px] font-black uppercase tracking-widest text-white">Red Zone: EMERGENCY / CRITICAL</p>
                         </div>
                         <textarea 
                            value={history.sickDayPlan.redZone} 
                            onChange={e => updateSickDayField('redZone', e.target.value)}
                            className="w-full h-32 p-5 rounded-2xl bg-white text-rose-700 font-black text-sm italic outline-none shadow-2xl"
                            placeholder="IMMEDIATE STEPS: 000, EpiPen, Rescue protocol..."
                         />
                      </div>
                   </div>

                   {/* Background for ED / Responders */}
                   <div className="bg-slate-900/40 p-8 rounded-[2.5rem] border border-white/10 space-y-4">
                      <div className="flex items-center gap-3">
                         <span className="text-xl">🚑</span>
                         <p className="text-[10px] font-black uppercase tracking-widest opacity-80">Background for Emergency Staff</p>
                      </div>
                      <textarea 
                        value={history.sickDayPlan.backgroundForED} 
                        onChange={e => updateSickDayField('backgroundForED', e.target.value)}
                        className="w-full h-24 p-5 rounded-2xl bg-white/10 text-white font-bold text-sm italic outline-none border border-white/10 shadow-inner"
                        placeholder="Vital context for doctors who don't know your child (e.g. 'Difficulty Intubating', 'Metabolic Defect')..."
                      />
                   </div>

                   {/* Standard Fields Grid */}
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="bg-white/5 p-6 rounded-3xl border border-white/10 space-y-2">
                        <p className="text-[9px] font-black uppercase tracking-widest opacity-60">Emergency Triggers</p>
                        <input className="w-full bg-transparent border-none outline-none font-bold text-sm" value={history.sickDayPlan.triggers} onChange={e => updateSickDayField('triggers', e.target.value)} />
                      </div>
                      <div className="bg-white/5 p-6 rounded-3xl border border-white/10 space-y-2">
                        <p className="text-[9px] font-black uppercase tracking-widest opacity-60">Emergency Meds</p>
                        <input className="w-full bg-transparent border-none outline-none font-bold text-sm" value={history.sickDayPlan.emergencyMeds} onChange={e => updateSickDayField('emergencyMeds', e.target.value)} />
                      </div>
                      <div className="bg-white/5 p-6 rounded-3xl border border-white/10 space-y-2">
                        <p className="text-[9px] font-black uppercase tracking-widest opacity-60">Fluid Requirements</p>
                        <input className="w-full bg-transparent border-none outline-none font-bold text-sm" value={history.sickDayPlan.fluidRequirements} onChange={e => updateSickDayField('fluidRequirements', e.target.value)} />
                      </div>
                      <div className="bg-white/5 p-6 rounded-3xl border border-white/10 space-y-2">
                        <p className="text-[9px] font-black uppercase tracking-widest opacity-60">Emergency Contact</p>
                        <input className="w-full bg-transparent border-none outline-none font-bold text-sm" value={history.sickDayPlan.emergencyContact} onChange={e => updateSickDayField('emergencyContact', e.target.value)} />
                      </div>
                   </div>

                   {/* Physical Photo */}
                   {history.sickDayPlan.planPhoto && (
                     <div className="pt-8 border-t border-white/10 space-y-4">
                        <div className="flex justify-between items-center px-2">
                           <p className="text-[9px] font-black uppercase tracking-widest opacity-60">Physical Plan Reference</p>
                           <button onClick={() => updateSickDayField('planPhoto', '')} className="text-[9px] font-black uppercase text-rose-300 hover:text-white">Delete Photo</button>
                        </div>
                        <img src={history.sickDayPlan.planPhoto} alt="Physical Plan" className="w-full rounded-[2rem] border-4 border-white/20 shadow-2xl" />
                     </div>
                   )}
                </div>
             </div>
          </div>
        )}
      </div>

      {aiAnalysis && (
        <div className="bg-slate-900 p-10 rounded-[3rem] text-white shadow-2xl animate-in zoom-in-95 border-l-[16px] border-l-indigo-600 relative overflow-hidden">
           <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-600 rounded-full opacity-10 blur-[100px]"></div>
           <div className="flex justify-between items-center mb-8 relative z-10">
             <h3 className="text-3xl font-black italic tracking-tighter text-indigo-100">ISBAR Handover Synthesis</h3>
             <button onClick={() => setAiAnalysis(null)} className="text-slate-500 font-black uppercase text-[10px] tracking-widest">Dismiss</button>
           </div>
           <div className="whitespace-pre-wrap text-lg font-bold italic leading-relaxed text-indigo-50 border-l-4 border-white/10 pl-8 relative z-10">{aiAnalysis.text}</div>
        </div>
      )}
    </div>
  );
};

