export type UserRole = 'parent' | 'clinician';
export type EnvironmentMode = 'standard' | 'low-resource';

export interface ClinicalEvent {
  id: string;
  source: string;
  description: string;
  date: string;
  severity: 'Low' | 'Medium' | 'High';
  media?: string;
}

export interface AttachmentAnalysis {
  caregiverObservations?: string;
}

export interface Appointment {
  id: string;
  provider: string;
  specialty: string;
  dateTime: string;
  location: string;
  purpose: string;
  reminderSent: boolean;
  preVisitNotes: string;
  postVisitSummary: string;
  status: 'Upcoming' | 'Completed' | 'Cancelled';
}

export interface SymptomLog {
  id: string;
  timestamp: Date;
  description: string;
  aiResponse: string;
  media?: string;
}

export interface HydrationChallenge {
  isActive: boolean;
  startTime?: string;
  targetVolume: number;
  intervalVolume: number;
  intervalMinutes: number;
  totalConsumed: number;
  vomitCount: number;
}

export interface AcuteLogEntry {
  id: string;
  timestamp: string;
  type: 'Fluid' | 'Temperature' | 'Output' | 'Medication' | 'Vomit' | 'Vitals' | 'Physical Exam';
  value: string;
  notes?: string;
  isChallengeEntry?: boolean;
  clinicianLogged?: boolean;
}

export interface MedicalReport {
  id: string;
  date: string;
  specialist: string;
  summary: string;
  actionItems: string[];
  photoUrl?: string;
}

export interface GrowthRecord {
  age: number;
  weight: number;
  height: number;
  headCircumference?: number;
  date: string;
}

export interface Medication {
  id: string;
  name: string;
  dose: string;
  instructions: string;
  indication: string;
  startDate: string;
}

export interface PreviousMedication {
  id: string;
  name: string;
  dose: string;
  indication: string;
  startDate?: string;
  ceasedDate: string;
  ceaseReason: string;
}

export interface Vaccination {
  id: string;
  name: string;
  dueDate: Date;
  receivedDate?: Date;
  status: 'pending' | 'completed' | 'overdue';
  description: string;
  ageMilestone: number;
  manufacturer?: string;
  lotNumber?: string;
  clinic?: string;
  sideEffects?: string;
}

export interface Milestone {
  id: string;
  ageRange: string;
  category: 'Motor' | 'Cognitive' | 'Social' | 'Language';
  description: string;
  completed: boolean;
  isRedFlag: boolean;
}

export interface HealthCheck {
  id: string;
  ageMilestone: string;
  date?: string;
  completed: boolean;
  notes: string;
  professionalName?: string;
}

export interface SpecialistContact {
  id: string;
  name: string;
  specialty: string;
  category: 'Medical' | 'Allied Health' | 'Support';
  hospital?: string;
  contact?: string;
  lastSeen?: string;
  nextReview?: string;
  goals?: string;
}

export interface MedicalDevice {
  id: string;
  type: string;
  model?: string;
  size?: string;
  lastChanged?: string;
  nextChangeDue?: string;
  notes?: string;
}

export interface FamilyHistory {
  maternal: string;
  paternal: string;
  siblings: string;
  other: string;
}

export interface SickDayPlan {
  greenZone: string; // Routine unwell management
  yellowZone: string; // Escalate care/Call GP
  redZone: string; // Emergency/ED
  backgroundForED: string; // Vital info for hospital staff
  emergencyMeds: string;
  fluidRequirements: string;
  triggers: string;
  emergencyContact: string;
  planPhoto?: string;
}

export interface Recommendation {
  id: string;
  source: string;
  date: string;
  action: string;
}

export interface Condition {
  id: string;
  name: string;
  dateDiagnosed?: string;
  status: 'Active' | 'Resolved' | 'Under Investigation';
  notes?: string;
  clinicianVerified?: boolean;
}

export interface Investigation {
  id: string;
  date: string;
  name: string;
  result: string;
  location?: string;
}

export interface MedicalHistory {
