                    <div className="flex items-center gap-3">
                    <span className="w-5 h-5 rounded-full bg-white animate-bounce shadow-lg"></span>
                    <p className="text-xs font-black uppercase tracking-[0.2em] text-white">Red Zone: EMERGENCY / CRITICAL</p>
                    </div>
                    <textarea 
                    value={history.sickDayPlan.redZone} 
                    onChange={e => updateSickDayField('redZone', e.target.value)}
                    className="w-full h-32 p-6 rounded-2xl bg-white text-rose-700 font-black text-base italic outline-none shadow-2xl focus:ring-4 focus:ring-white/20 transition-all"
                    placeholder="IMMEDIATE STEPS: 000, EpiPen, Rescue protocol..."
                    />
