import React, { useState, useEffect } from 'react';
import { Vaccination } from '../types';
import { getVaccineAdvice } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';

/**
 * Australian National Immunisation Program (NIP) Schedule
 * Source: health.gov.au
 */
const INITIAL_SCHEDULE = (dob: Date): Vaccination[] => {
  const addMonths = (date: Date, months: number) => {
    const d = new Date(date);
    d.setMonth(d.getMonth() + months);
    return d;
  };

  const addYears = (date: Date, years: number) => {
    const d = new Date(date);
    d.setFullYear(d.getFullYear() + years);
    return d;
  };

  return [
    { 
      id: 'nip-birth', 
      name: 'Hepatitis B', 
      ageMilestone: 0, 
      dueDate: addMonths(dob, 0), 
      status: 'pending', 
      description: 'Protects against Hepatitis B virus. Usually given within 24 hours of birth.' 
    },
    { 
      id: 'nip-2mo', 
      name: 'DTPa-hepB-IPV-Hib, 13vPCV, Rotavirus', 
      ageMilestone: 2, 
      dueDate: addMonths(dob, 2), 
      status: 'pending', 
      description: '6-in-1 (Diphtheria, Tetanus, Pertussis, Hep B, Polio, Hib), Pneumococcal, and Oral Rotavirus.' 
    },
    { 
      id: 'nip-4mo', 
      name: 'DTPa-hepB-IPV-Hib, 13vPCV, Rotavirus', 
      ageMilestone: 4, 
      dueDate: addMonths(dob, 4), 
      status: 'pending', 
      description: 'Second dose of the 6-in-1, Pneumococcal, and Rotavirus vaccines.' 
    },
    { 
      id: 'nip-6mo', 
      name: 'DTPa-hepB-IPV-Hib', 
      ageMilestone: 6, 
      dueDate: addMonths(dob, 6), 
      status: 'pending', 
      description: 'Third dose of the 6-in-1 vaccine. Note: Rotavirus and PCV schedule may vary by state/risk.' 
    },
    { 
      id: 'nip-12mo', 
      name: 'MMR, MenACWY, 13vPCV', 
      ageMilestone: 12, 
      dueDate: addMonths(dob, 12), 
      status: 'pending', 
      description: 'Measles, Mumps, Rubella; Meningococcal ACWY; and a Pneumococcal booster.' 
    },
    { 
      id: 'nip-18mo', 
      name: 'MMRV, DTPa, Hib', 
      ageMilestone: 18, 
      dueDate: addMonths(dob, 18), 
      status: 'pending', 
      description: 'Measles, Mumps, Rubella, Varicella (Chickenpox); DTPa booster; and Haemophilus influenzae type b booster.' 
    },
    { 
      id: 'nip-4yr', 
      name: 'DTPa-IPV', 
      ageMilestone: 48, 
      dueDate: addYears(dob, 4), 
      status: 'pending', 
      description: 'Final childhood booster for Diphtheria, Tetanus, Pertussis, and Polio before school.' 
    },
  ];
};

export const VaccineTracker: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const { childProfile } = useChildProfile();

  const [info, setInfo] = useState<{ name: string; text: string; sources: any[] } | null>(null);
  const [loadingInfo, setLoadingInfo] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [syncedIds, setSyncedIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (childProfile?.dob && (!history.vaccinations || history.vaccinations.length === 0)) {
      updateHistory({ vaccinations: INITIAL_SCHEDULE(new Date(childProfile.dob)) });
    }
  }, [childProfile?.dob]);

  const schedule = history.vaccinations || [];

  const toggleStatus = (id: string) => {
    const next = schedule.map(v => 
      v.id === id ? { 
        ...v, 
        status: (v.status === 'completed' ? 'pending' : 'completed') as any,
        receivedDate: v.status === 'completed' ? undefined : new Date()
      } : v
    );
    updateHistory({ vaccinations: next });

    const targetVax = next.find(x => x.id === id);
    if (targetVax?.status === 'completed') {
      setEditingId(id);
    }
  };

  const handleSyncToHistory = (vaccine: Vaccination) => {
    addClinicalEvent({
      source: 'Vaccines',
      description: `Immunisation Administered: ${vaccine.name}. Lot: ${vaccine.lotNumber || 'N/A'}. Clinic: ${vaccine.clinic || 'N/A'}.`,
      date: new Date().toLocaleDateString(),
      severity: 'Low'
    });
    setSyncedIds(prev => new Set(prev).add(vaccine.id));
    alert(`${vaccine.name} synced to medical timeline!`);
  };

  const updateDetails = (id: string, field: keyof Vaccination, value: any) => {
    const next = schedule.map(v => 
      v.id === id ? { ...v, [field]: value } : v
    );
    updateHistory({ vaccinations: next });
  };

  const handleFetchInfo = async (name: string) => {
    setLoadingInfo(true);
    try {
      const advice = await getVaccineAdvice(name);
      setInfo({ name, text: advice.text, sources: advice.sources });
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingInfo(false);
    }
  };

  const isOverdue = (dueDate: Date) => {
    return new Date() > new Date(dueDate);
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">NIP <span className="text-indigo-600">Vaccination Record</span></h2>
          <p className="text-slate-500 font-medium italic">Track Australian National Immunisation Program milestones.</p>
        </div>
        <div className="bg-indigo-50 border border-indigo-100 px-4 py-2 rounded-xl text-[9px] font-black uppercase text-indigo-600 tracking-widest">
           Australian Standards (NIP)
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          {schedule.map((vaccine) => {
            const overdue = vaccine.status === 'pending' && isOverdue(vaccine.dueDate);
            const isEditing = editingId === vaccine.id;
            const isSynced = syncedIds.has(vaccine.id);

            return (
              <div 
                key={vaccine.id}
                className={`group rounded-[2.5rem] border-2 transition-all overflow-hidden ${
                  vaccine.status === 'completed' 
                    ? 'bg-emerald-50/50 border-emerald-100 shadow-sm' 
                    : overdue 
                      ? 'bg-rose-50 border-rose-100'
                      : 'bg-white border-slate-100 hover:border-indigo-100 shadow-sm'
                }`}
              >
                <div className="p-6 md:p-8 flex items-center justify-between gap-4">
                  <div className="flex items-center gap-5">
                    {/* Tick Box Toggle */}
                    <div className="relative flex items-center shrink-0">
                      <input 
                        type="checkbox"
                        checked={vaccine.status === 'completed'}
                        onChange={() => toggleStatus(vaccine.id)}
                        className="w-12 h-12 rounded-2xl border-4 border-slate-100 text-emerald-600 focus:ring-emerald-500 cursor-pointer appearance-none checked:bg-emerald-600 checked:border-emerald-600 transition-all shadow-md active:scale-90"
                      />
                      {vaccine.status === 'completed' && (
                        <span className="absolute inset-0 flex items-center justify-center text-white pointer-events-none text-2xl font-black">✓</span>
                      )}
                      {vaccine.status !== 'completed' && overdue && (
                        <span className="absolute -top-1 -right-1 w-4 h-4 bg-rose-500 rounded-full animate-pulse border-2 border-white"></span>
                      )}
                    </div>

                    <div>
                      <h4 className={`text-xl font-black tracking-tight leading-tight ${vaccine.status === 'completed' ? 'text-emerald-900' : 'text-slate-800'}`}>
                        {vaccine.name}
                      </h4>
                      <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest flex items-center gap-2">
                        {vaccine.status === 'completed' 
                          ? <span>📅 Received: {vaccine.receivedDate ? new Date(vaccine.receivedDate).toLocaleDateString() : 'Date missing'}</span> 
                          : <span>🎯 Scheduled: {new Date(vaccine.dueDate).toLocaleDateString()}</span>
                        }
                        {overdue && <span className="text-rose-600 font-black animate-pulse">• OVERDUE</span>}
                      </p>

                      <div className="mt-3 p-3 bg-slate-50/50 rounded-xl border border-slate-100">
                         <p className="text-xs font-bold text-slate-500 italic leading-relaxed">
                            {vaccine.description}
                         </p>
                      </div>

                      <div className="flex flex-wrap gap-4 mt-4">
                        <button 
                          onClick={() => handleFetchInfo(vaccine.name)}
                          className="text-[10px] text-indigo-600 font-black uppercase tracking-widest hover:underline"
                        >
                          Deep Dive (AI)
                        </button>
                        <button 
                          onClick={() => setEditingId(isEditing ? null : vaccine.id)}
                          className={`text-[10px] font-black uppercase tracking-widest transition-all ${isEditing ? 'text-rose-500' : 'text-slate-400 hover:text-indigo-600'}`}
                        >
                          {isEditing ? 'Close Details' : 'Input Logistics'}
                        </button>
                        {vaccine.status === 'completed' && !isSynced && (
                           <button 
                            onClick={() => handleSyncToHistory(vaccine)}
                            className="text-[10px] text-emerald-600 font-black hover:underline uppercase tracking-widest animate-pulse"
                          >
                            Sync to Hub
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                {isEditing && (
                  <div className="px-8 pb-8 pt-2 bg-white/50 border-t border-slate-100 animate-in slide-in-from-top-4 space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 pt-4">
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Exact Date Administered</label>
                        <input 
                          type="date" 
                          value={vaccine.receivedDate ? new Date(vaccine.receivedDate).toISOString().split('T')[0] : ''}
                          onChange={(e) => updateDetails(vaccine.id, 'receivedDate', new Date(e.target.value))}
                          className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner uppercase"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clinic / Pharmacy / GP</label>
                        <input 
                          type="text" 
                          placeholder="e.g. Royal Children's Outpatients"
                          value={vaccine.clinic || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'clinic', e.target.value)}
                          className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Manufacturer (e.g. GSK, Sanofi)</label>
                        <input 
                          type="text" 
                          placeholder="e.g. Infanrix hexa"
                          value={vaccine.manufacturer || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'manufacturer', e.target.value)}
                          className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Batch / Lot # (Crucial for safety)</label>
                        <input 
                          type="text" 
                          placeholder="e.g. ABC12345"
                          value={vaccine.lotNumber || ''}
                          onChange={(e) => updateDetails(vaccine.id, 'lotNumber', e.target.value)}
                          className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
                        />
                      </div>
                    </div>
                    <div className="space-y-1">
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Post-Vax Observations (Fever, Rash, Pain)</label>
                       <textarea 
                        placeholder="Log any immediate reactions or side effects over the next 48 hours..."
                        value={vaccine.sideEffects || ''}
                        onChange={(e) => updateDetails(vaccine.id, 'sideEffects', e.target.value)}
                        className="w-full h-24 p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none italic text-sm"
                       />
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="lg:col-span-1">
          {loadingInfo ? (
            <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm sticky top-8 animate-pulse text-center">
              <div className="w-16 h-16 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-4">🔬</div>
              <p className="text-slate-400 font-black uppercase tracking-widest text-[10px]">Consulting Australian Guidelines...</p>
            </div>
          ) : info ? (
            <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-2xl sticky top-8 animate-in slide-in-from-right-4 max-h-[80vh] overflow-y-auto border-l-[16px] border-l-indigo-600 relative">
              <button onClick={() => setInfo(null)} className="absolute top-6 right-6 text-slate-400 font-black text-xl hover:text-rose-500 transition-colors">×</button>
              <h3 className="text-2xl font-black text-slate-800 italic mb-6 leading-tight">{info.name}</h3>
              <div className="prose prose-slate prose-sm leading-relaxed whitespace-pre-wrap font-bold italic text-slate-600 border-l-4 border-slate-50 pl-6">
                {info.text}
              </div>
            </div>
          ) : (
            <div className="bg-indigo-900 p-10 rounded-[3.5rem] shadow-2xl sticky top-8 text-white relative overflow-hidden group">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
              <div className="relative z-10">
                <span className="text-5xl mb-6 block">🛡️</span>
                <h4 className="text-xl font-black italic mb-4">Why track batches?</h4>
                <p className="text-indigo-100 font-bold text-base leading-relaxed italic">
                  Digital tracking of lot numbers and clinics ensures that if a vaccine batch is recalled, or if your child has a reaction, you have the precise data clinicians need for safe reporting.
                </p>
                <div className="mt-8 pt-8 border-t border-white/10">
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Source Recognition</p>
                   <p className="text-xs font-medium italic opacity-80 mt-1">Aligned with health.gov.au childhood immunisation schedule.</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

