export const MilestoneNavigator: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showAddCustom, setShowAddCustom] = useState(false);
  const [customMilestone, setCustomMilestone] = useState<Partial<Milestone>>({ description: '', category: 'Motor' });

  // Initialize milestones in history if not present
  useEffect(() => {
    if (!history.milestones || history.milestones.length === 0) {
      updateHistory({ milestones: INITIAL_DATA });
    }
  }, [history.milestones, updateHistory]);

  const milestones = history.milestones || [];

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    updateHistory({ milestones: updated });

    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed) {
      addClinicalEvent({ 
        source: 'Development', 
        description: `Concern (${item.ageRange}): ${item.description.split('. Example:')[0]}`, 
        date: new Date().toLocaleDateString(), 
        severity: 'Medium' 
      });
    }
    // Auto-expand for notes when marking as completed
    if (item?.completed) setExpandedId(id);
  };

  const updateNotes = (id: string, notes: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, notes } : m);
    updateHistory({ milestones: updated });
  };

  const handleAddCustom = () => {
    if (!customMilestone.description) return;
    const newM: Milestone = {
      id: crypto.randomUUID(),
      ageRange: activeAge,
      category: customMilestone.category as any,
      description: customMilestone.description,
      completed: true,
      isRedFlag: false,
      notes: ''
    };
    updateHistory({ milestones: [...milestones, newM] });
    setCustomMilestone({ description: '', category: 'Motor' });
    setShowAddCustom(false);
    setExpandedId(newM.id);
  };

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '9 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];

  const filteredData = useMemo(() => {
    return milestones.filter(m => m.ageRange === activeAge && m.isRedFlag === showRedFlags);
  }, [milestones, activeAge, showRedFlags]);

  const CategoryBadge = ({ category }: { category: string }) => {
    const colors: Record<string, string> = {
      Motor: 'bg-blue-50 text-blue-600 border-blue-100',
      Language: 'bg-purple-50 text-purple-600 border-purple-100',
      Social: 'bg-pink-50 text-pink-600 border-pink-100',
      Cognitive: 'bg-amber-50 text-amber-600 border-amber-100',
    };
    return <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border ${colors[category] || 'bg-slate-50 text-slate-500 border-slate-100'}`}>{category}</span>;
  };

  return (
    <div className="space-y-8 pb-24">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4 px-1">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Milestone <span className="text-teal-600">Sync</span></h2>
          <p className="text-slate-500 text-sm font-medium italic mt-1">Evidence-based developmental markers and clinical flags.</p>
        </div>
        <button 
          onClick={() => setShowAddCustom(!showAddCustom)}
          className="bg-white border-2 border-teal-100 text-teal-600 px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-teal-50 transition-all shadow-sm"
        >
          {showAddCustom ? 'Cancel' : '+ Add Custom Marker'}
        </button>
      </header>

      {showAddCustom && (
        <div className="bg-teal-50 p-8 rounded-[3rem] border border-teal-100 animate-in zoom-in-95 space-y-6">
           <h3 className="text-lg font-black text-teal-900 italic">Custom Development Marker for {activeAge}</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input 
                placeholder="What did you observe? (e.g. Points to birds)" 
                value={customMilestone.description}
                onChange={e => setCustomMilestone({...customMilestone, description: e.target.value})}
                className="p-4 rounded-2xl bg-white border border-teal-200 font-black text-slate-900 outline-none"
              />
              <select 
                value={customMilestone.category}
                onChange={e => setCustomMilestone({...customMilestone, category: e.target.value as any})}
                className="p-4 rounded-2xl bg-white border border-teal-200 font-black text-slate-900 outline-none"
              >
                <option>Motor</option>
                <option>Social</option>
                <option>Language</option>
                <option>Cognitive</option>
              </select>
           </div>
           <button onClick={handleAddCustom} className="w-full py-4 bg-teal-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Record Observation</button>
        </div>
      )}

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-3 overflow-x-auto no-scrollbar">
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm min-w-max">
          {ageGroups.map(age => (
            <button key={age} onClick={() => {setActiveAge(age); setExpandedId(null);}} className={`px-5 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeAge === age ? 'bg-teal-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>{age}</button>
          ))}
        </div>
      </nav>

      <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm max-w-sm">
        <button onClick={() => setShowRedFlags(false)} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-teal-50 text-teal-700' : 'text-slate-400'}`}>Typical Progress</button>
        <button onClick={() => setShowRedFlags(true)} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-50 text-rose-700' : 'text-slate-400'}`}>Clinical Flags</button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 animate-in slide-in-from-bottom-4">
        {filteredData.length > 0 ? filteredData.map(m => {
          const parts = m.description.split('. Example:');
          const title = parts[0];
          const example = parts[1];
          const isExpanded = expandedId === m.id;

          return (
            <div 
              key={m.id}
              className={`rounded-[2.5rem] border-2 transition-all flex flex-col overflow-hidden shadow-sm ${
                m.completed 
                  ? (showRedFlags ? 'bg-rose-50 border-rose-200' : 'bg-emerald-50 border-emerald-200 shadow-md') 
                  : 'bg-white border-slate-100 hover:border-teal-100'
              }`}
            >
              <div className="p-8 flex flex-col h-full gap-4">
                <div className="flex justify-between items-start">
                  <CategoryBadge category={m.category} />
                  <button 
                    onClick={() => toggleMilestone(m.id)}
                    className={`w-14 h-14 rounded-2xl border-4 flex items-center justify-center transition-all ${
                      m.completed 
                        ? (showRedFlags ? 'bg-rose-600 border-white text-white rotate-[360deg]' : 'bg-emerald-600 border-white text-white rotate-[360deg]') 
                        : 'border-slate-100 text-slate-100 hover:border-teal-200 hover:scale-105 active:scale-90'
                    }`}
                  >
                    {m.completed ? <span className="font-black text-xl">✓</span> : null}
                  </button>
                </div>

                <div className="flex-1">
                  <p className="text-2xl font-black text-slate-800 leading-tight tracking-tight mb-2">
                    {title}
                  </p>
                  {example && (
                    <p className="text-sm font-bold text-slate-400 italic leading-relaxed mb-4">
                      Example: {example}
                    </p>
                  )}
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-slate-50/50">
                   <button 
                    onClick={() => setExpandedId(isExpanded ? null : m.id)}
                    className={`text-[10px] font-black uppercase tracking-widest ${m.notes ? 'text-teal-600' : 'text-slate-400'} hover:underline`}
                   >
                     {isExpanded ? 'Hide Notes' : m.notes ? 'View Notes 📝' : 'Add Note +'}
                   </button>
                   {m.isRedFlag && !m.completed && (
                    <div className="flex items-center gap-1.5 text-rose-500 font-black text-[8px] uppercase tracking-widest">
                      <span className="text-base animate-pulse">⚠️</span>
                      <span>Review Required</span>
                    </div>
                  )}
                </div>
              </div>

              {isExpanded && (
                <div className="px-8 pb-8 pt-2 bg-white/40 border-t border-slate-50 animate-in slide-in-from-top-2">
                   <label className="block text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2">Observation Notes (Free Text)</label>
                   <textarea 
                    value={m.notes || ''}
                    onChange={e => updateNotes(m.id, e.target.value)}
                    placeholder="Specific details about how they achieved this, or any concerns you noticed..."
                    className="w-full h-24 p-4 rounded-2xl bg-white border border-slate-100 font-bold italic text-slate-600 text-sm outline-none focus:ring-2 focus:ring-teal-100 shadow-inner resize-none"
                   />
                </div>
              )}
            </div>
          );
        }) : (
          <div className="col-span-full py-24 flex flex-col items-center justify-center bg-slate-50/50 border-4 border-dashed border-slate-100 rounded-[4rem] text-center opacity-40">
            <span className="text-7xl mb-6">🌱</span>
            <p className="font-black text-lg uppercase tracking-widest text-slate-500">No markers logged for this age group</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Medication, SpecialistContact, MedicalDevice, MedicalReport, Condition, Investigation } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';
import { SickDayPlanView } from './SickDayPlanView';

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, addAcuteLog, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'reports' | 'mdt' | 'gear' | 'sickday'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);
  const [pendingExtraction, setPendingExtraction] = useState<any | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // Clinician Physical Exam State
  const [examObs, setExamObs] = useState({
    hr: '', rr: '', spo2: '', crt: 'Normal (<2s)', workOfBreathing: 'Normal', appearance: 'Well/Interactive', neuro: 'AVPU: A'
  });

  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active', notes: '' });
  const [newInvestigation, setNewInvestigation] = useState<Partial<Investigation>>({ name: '', result: '', date: new Date().toISOString().split('T')[0] });

  const logClinicianObs = () => {
    const summary = `Obs: HR ${examObs.hr}, RR ${examObs.rr}, SpO2 ${examObs.spo2}%. Perfusion: ${examObs.crt}. WoB: ${examObs.workOfBreathing}. App: ${examObs.appearance}. ${examObs.neuro}.`;
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Physical Exam',
      value: 'Physical Assessment Logged',
      notes: summary,
      clinicianLogged: true
    });
    alert("Clinical assessment logged to child's history.");
    setExamObs({ hr: '', rr: '', spo2: '', crt: 'Normal (<2s)', workOfBreathing: 'Normal', appearance: 'Well/Interactive', neuro: 'AVPU: A' });
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      setPendingExtraction(null);
      const reader = new FileReader();
      reader.onloadend = async () => {
        try {
          const result = await analyzeMedicalReport(reader.result as string);
          setPendingExtraction({ ...result, photoUrl: reader.result as string });
          setActiveTab('reports');
        } catch (err) {
          alert("Failed to analyze report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const syncExtractionToProfile = () => {
    if (!pendingExtraction) return;

    const newReport: MedicalReport = {
      id: crypto.randomUUID(),
      date: new Date().toLocaleDateString(),
      specialist: pendingExtraction.specialist.name,
      summary: pendingExtraction.summary,
      actionItems: pendingExtraction.actionItems,
      photoUrl: pendingExtraction.photoUrl
    };

    const newConditions: Condition[] = (pendingExtraction.foundDiagnoses || []).map((d: string) => ({
      id: crypto.randomUUID(),
      name: d,
      status: 'Active',
      dateDiagnosed: new Date().toLocaleDateString(),
      clinicianVerified: role === 'clinician',
      notes: `AI Extraction from ${pendingExtraction.specialist.name} letter`,
    }));

    const newMeds: Medication[] = (pendingExtraction.foundMedications || []).map((m: any) => ({
      ...m,
      id: crypto.randomUUID(),
      startDate: new Date().toISOString(),
    }));

    updateHistory({ 
      medicalReports: [...(history.medicalReports || []), newReport],
      conditions: [...(history.conditions || []), ...newConditions],
      currentMedications: [...(history.currentMedications || []), ...newMeds]
    });

    setPendingExtraction(null);
    alert("Profile updated with extracted details.");
  };

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '' });
    }
  };

  const addIssue = () => {
    if (newIssue.name) {
      const issue: Condition = {
        id: crypto.randomUUID(),
        name: newIssue.name,
        status: newIssue.status as any,
        notes: newIssue.notes,
        dateDiagnosed: new Date().toISOString().split('T')[0],
        clinicianVerified: role === 'clinician'
      };
      updateHistory({ conditions: [...(history.conditions || []), issue] });
      setNewIssue({ name: '', status: 'Active', notes: '' });
    }
  };

  const addInvestigation = () => {
    if (newInvestigation.name) {
      const inv: Investigation = {
        id: crypto.randomUUID(),
        name: newInvestigation.name,
        result: newInvestigation.result || '',
        date: newInvestigation.date || new Date().toISOString().split('T')[0]
      };
      updateHistory({ investigations: [...(history.investigations || []), inv] });
      setNewInvestigation({ name: '', result: '', date: new Date().toISOString().split('T')[0] });
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'sickday', label: 'Sick Day', icon: '🚨' }
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 text-sm font-medium">Longitudinal clinical story shared by parent and clinician.</p>
        </div>
        <button onClick={handleGenerateHandover} disabled={loading} className="bg-indigo-600 text-white px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all active:scale-95">
          {loading ? 'Analyzing...' : 'Generate ISBAR Handover ✨'}
        </button>
      </header>

      {/* ROLE INDICATOR */}
      <div className={`p-4 rounded-2xl border flex items-center justify-between ${role === 'clinician' ? 'bg-slate-900 border-slate-800 text-white' : 'bg-indigo-50 border-indigo-100 text-indigo-700'}`}>
         <div className="flex items-center gap-3">
           <span className="text-xl">{role === 'clinician' ? '👨‍⚕️' : '👪'}</span>
           <span className="text-[10px] font-black uppercase tracking-widest">Currently Viewing as {role}</span>
         </div>
         {role === 'clinician' && <span className="bg-indigo-600 px-3 py-1 rounded-full text-[9px] font-black uppercase shadow-lg">Technical Entry Enabled</span>}
      </div>

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-2 overflow-x-auto no-scrollbar">
        <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex min-w-max">
          {tabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
              <span className="text-lg">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl min-h-[500px] p-8">

        {/* CLINICIAN PHYSICAL EXAM PANEL */}
