  const isOnline = useConnectivity();

  const [description, setDescription] = useState('');
  const [temp, setTemp] = useState('');
  const [duration, setDuration] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const ageMonths = useMemo(() => {
    if (!childProfile?.dob) return undefined;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
    if (now.getDate() < birth.getDate()) months--;
    return months;
  }, [childProfile]);

  const activeRedFlags = useMemo(() => {
    const input = {
      ageMonths,
      temperature: temp ? parseFloat(temp) : undefined,
      symptoms: [description],
      durationDays: duration ? parseInt(duration) : undefined,
      environment: mode
    };

    const imciFlags = evaluateIMCIRedFlags({ symptoms: [description] });
    const stdFlags = evaluateRedFlags(input);

    return mode === 'low-resource' ? [...imciFlags, ...stdFlags] : stdFlags;
  }, [ageMonths, temp, description, duration, mode]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);

      addEntry({
        eventType: "symptom_evaluation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Desc: ${description.slice(0, 50)}... Temp: ${temp || 'N/A'}`,
        outputSummary: `AI triage completed.`,
        redFlags: activeRedFlags.map(rf => rf.id),
        disclaimerShown: true
      });
    } catch (error) {
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSyncToLog = () => {
    if (result) {
      const severityStr = activeRedFlags.some(f => f.severity === 'Urgent') ? '🔴 URGENT' : '🟡 Review';
      addAcuteLog({
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        type: 'Triage',
        value: `AI Triage: ${severityStr}`,
        notes: `Input: ${description}\n\nAI Result: ${result.text.slice(0, 500)}...`,
        media: image || undefined
      });
      setSaved(true);
      alert("Triage details synced to Acute Logs.");
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
          <p className="text-slate-500 text-sm font-medium">Capture signs and receive clinical insights.</p>
        </div>
        <div className="flex gap-2">
          {!isOnline && <span className="bg-amber-100 text-amber-700 px-4 py-2 rounded-xl text-[10px] font-black uppercase">Offline</span>}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Temperature (°C)</label>
                 <input type="number" step="0.1" value={temp} onChange={e => setTemp(e.target.value)} placeholder="37.0" className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/30 font-black" />
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Duration (Days)</label>
                 <input type="number" value={duration} onChange={e => setDuration(e.target.value)} placeholder="0" className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/30 font-black" />
               </div>
            </div>

            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Barking cough, lethargy, etc..."
              className="w-full h-32 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none text-slate-900"
            />

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase bg-white border-slate-100 text-slate-500 w-full sm:w-auto">
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button 
                onClick={handleAnalyze} 
                disabled={loading || (!description.trim() && !image)} 
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase text-sm w-full ${loading ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700'}`}
              >
                {loading ? 'Analyzing...' : 'Analyze Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto animate-in zoom-in-95">
                <img src={image} alt="Symptom" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-4 right-4 bg-white text-rose-500 w-10 h-10 rounded-full flex items-center justify-center shadow-xl font-black">✕</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[4rem] shadow-2xl border-l-[20px] border-l-indigo-600 animate-in slide-in-from-bottom-6 duration-700 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl"></div>
              <div className="flex justify-between items-center mb-10 relative z-10">
                 <h3 className="text-3xl font-black text-slate-800 italic">AI Synthesis</h3>
                 <button onClick={handleSyncToLog} disabled={saved} className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all ${saved ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-700'}`}>
                  {saved ? '✓ Logged to Tracker' : 'Sync to Acute Logs'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-xl leading-relaxed relative z-10">{result.text}</div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
             <h3 className="text-3xl font-black italic tracking-tighter mb-6">RED FLAGS</h3>
             <div className="space-y-4">
                {RED_FLAGS_LIST.map((f, i) => (
                  <div key={i} className="bg-white/10 p-5 rounded-3xl flex items-start gap-4">
                    <span className="text-4xl">{f.icon}</span>
                    <div>
                      <span className="text-base font-black leading-tight block">{f.text}</span>
                      <span className="text-[10px] font-bold opacity-70 block mt-1 italic">{f.sub}</span>
                    </div>
                  </div>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, latestWeight } = useMedicalHistory();
  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: 500,
    intervalVolume: 5,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  useEffect(() => {
    if (latestWeight && !challenge.isActive) {
      const recommendedInterval = Math.round(latestWeight); 
      setChallenge(prev => ({
        ...prev,
        intervalVolume: recommendedInterval,
        targetVolume: recommendedInterval * 12 
      }));
    }
  }, [latestWeight, challenge.isActive]);

  const handleAdd = () => {
    if (!value) return;
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type,
      value: type === 'Temperature' && !value.includes('°C') ? `${value}°C` : value,
      notes
    });
    setValue('');
    setNotes('');
  };

  const icons = { Fluid: '🥤', Temperature: '🌡️', Output: '🚽', Medication: '💊', Vomit: '🤮', Triage: '✨', Vitals: '🩺', 'Physical Exam': '👨‍⚕️' };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Sync Log</span></h2>
          <p className="text-slate-500 text-xs font-medium italic mt-1">Timeline of clinical values and interventions.</p>
        </div>
        <button onClick={() => setChallenge(prev => ({ ...prev, isActive: !prev.isActive }))} className={`px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center gap-2 ${challenge.isActive ? 'bg-slate-900 text-white' : 'bg-teal-600 text-white'}`}>
           {challenge.isActive ? 'End Fluid Challenge' : 'Start Fluid Challenge 💧'}
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
            <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 shadow-inner">
               {['Fluid', 'Temperature', 'Output', 'Medication'].map((t) => (
                  <button key={t} onClick={() => setType(t as any)} className={`flex-1 py-3 rounded-xl text-xl transition-all ${type === t ? 'bg-white shadow-md' : 'opacity-40 grayscale'}`}>
                    {(icons as any)[t]}
                  </button>
               ))}
            </div>
            <div className="space-y-4">
               <input value={value} onChange={e => setValue(e.target.value)} placeholder="Value (e.g. 38.5)" className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-slate-900 outline-none shadow-inner" />
               <input value={notes} onChange={e => setNotes(e.target.value)} placeholder="Context..." className="w-full p-4 rounded-2xl border border-slate-100 bg-white text-xs font-black outline-none shadow-inner" />
               <button onClick={handleAdd} className="w-full py-5 bg-rose-600 text-white font-black rounded-[1.5rem] shadow-xl text-[11px] uppercase active:scale-95 transition-all">Log Event</button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3">
           <div className="bg-white p-5 sm:p-10 rounded-[2.5rem] border border-slate-100 shadow-sm min-h-[400px]">
              <h3 className="text-xl font-black text-slate-800 tracking-tight mb-6">Log Timeline (24h)</h3>
              <div className="space-y-3">
                 {(history.acuteLogs || []).map(entry => (
                    <div key={entry.id} className={`p-5 rounded-3xl border flex flex-col gap-4 transition-all ${entry.type === 'Triage' ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50/20 border-slate-50'}`}>
                       <div className="flex items-center gap-4">
                          <span className="text-[10px] font-black text-slate-400 w-12 shrink-0">{entry.timestamp}</span>
                          <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-2xl shadow-sm shrink-0">{(icons as any)[entry.type]}</div>
                          <div className="flex-1 overflow-hidden">
                             <p className="text-lg font-black text-slate-800">{entry.value}</p>
                             <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">{entry.type}</p>
                          </div>
                       </div>
                       {entry.notes && <p className="text-xs font-bold text-slate-600 italic whitespace-pre-wrap pl-16 border-l-2 border-slate-100 ml-6">{entry.notes}</p>}
                       {entry.media && (
                          <div className="pl-16">
                            <img src={entry.media} alt="Logged Triage" className="w-32 h-32 object-cover rounded-2xl border-2 border-white shadow-md hover:scale-105 transition-transform" />
                          </div>
                       )}
                    </div>
                 ))}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Medication, SpecialistContact, MedicalDevice, MedicalReport, Condition, Investigation, PreviousMedication } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'diagnostics' | 'reports' | 'gear' | 'family'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', size: '', nextChangeDue: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active' });

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}?`);
    if (reason === null) return;
    const ceased: PreviousMedication = { ...med, ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: reason };
    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), ceased]
    });
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '', size: '', nextChangeDue: '' });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        try {
          const result = await analyzeMedicalReport(base64);
          if (result) {
            const newReport: MedicalReport = { id: crypto.randomUUID(), date: new Date().toLocaleDateString(), specialist: result.specialist.name, summary: result.summary, actionItems: result.actionItems, photoUrl: base64 };
            updateHistory({
              medicalReports: [...(history.medicalReports || []), newReport],
              conditions: [...(history.conditions || []), ...(result.foundDiagnoses || []).map((d: string) => ({ id: crypto.randomUUID(), name: d, status: 'Active', dateDiagnosed: new Date().toLocaleDateString() }))],
              currentMedications: [...(history.currentMedications || []), ...(result.foundMedications || []).map((m: any) => ({ ...m, id: crypto.randomUUID(), startDate: new Date().toISOString() }))]
            });
            alert("Specialist letter synced.");
          }
        } catch (error) {
          alert("Error processing letter.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'diagnostics', label: 'Tests', icon: '🧪' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'family', label: 'Family', icon: '🌳' }
  ];

  return (
    <div className="space-y-8 pb-24 animate-in fade-in">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical repository and care team coordination.</p>
        </div>
        <button onClick={handleGenerateHandover} disabled={loading} className="bg-indigo-600 text-white px-8 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest shadow-2xl">
          {loading ? 'Analyzing...' : 'Generate ISBAR Handover ✨'}
        </button>
      </header>

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/95 backdrop-blur-xl py-4 overflow-x-auto no-scrollbar border-b border-slate-100">
        <div className="flex gap-2 min-w-max">
          {tabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl' : 'bg-white text-slate-400 border border-slate-100'}`}>
              <span className="text-xl">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl min-h-[600px] p-12">
        {activeTab === 'history' && (
          <div className="space-y-16">
            <section className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-4">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>📜</span> Past Medical History</h3>
                <textarea value={history.pastMedicalHistory} onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} placeholder="..." className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 font-bold italic text-slate-900" />
              </div>
              <div className="space-y-4">
                <h3 className="text-xs font-black text-rose-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>✂️</span> Surgical History</h3>
                <textarea value={history.surgicalHistory} onChange={e => updateHistory({ surgicalHistory: e.target.value })} placeholder="..." className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 font-bold italic text-slate-900" />
              </div>
            </section>
            <section className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Active Issues List</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {(history.conditions || []).map(issue => (
                  <div key={issue.id} className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 relative group">
                    <button onClick={() => updateHistory({ conditions: history.conditions?.filter(x => x.id !== issue.id) })} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <p className="font-black text-slate-800 mb-1">{issue.name}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase">{issue.status}</p>
                  </div>
                ))}
                <div className="bg-white p-6 rounded-[2rem] border-4 border-dashed border-slate-100 flex flex-col gap-3">
                   <input placeholder="New Issue..." value={newIssue.name} onChange={e => setNewIssue({...newIssue, name: e.target.value})} className="bg-slate-50 p-3 rounded-xl text-xs font-black outline-none" />
                   <button onClick={() => { if(newIssue.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newIssue, id: crypto.randomUUID(), dateDiagnosed: new Date().toLocaleDateString() } as Condition] }); setNewIssue({name: ''}); } }} className="bg-indigo-600 text-white py-2 rounded-xl text-[10px] font-black uppercase">Add Issue</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="space-y-16">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Active Medications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.currentMedications.map(m => (
                  <div key={m.id} className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 flex flex-col justify-between shadow-sm group relative">
                    <button onClick={() => ceaseMedication(m)} className="absolute top-8 right-8 bg-white text-rose-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 shadow-sm">Cease Med</button>
                    <div className="space-y-4">
                      <p className="text-3xl font-black text-emerald-900">{m.name} <span className="text-emerald-500/50 font-medium">{m.dose}</span></p>
                      <p className="text-sm font-bold text-emerald-800 italic">"Indication: {m.indication || 'N/A'}"</p>
                      <p className="text-xs font-bold text-emerald-700/60 leading-relaxed">{m.instructions}</p>
                    </div>
                  </div>
                ))}
                <div className="bg-white p-10 rounded-[3rem] border-4 border-dashed border-slate-100 space-y-6">
                   <div className="grid grid-cols-2 gap-4">
                      <input placeholder="Drug" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none" />
                      <input placeholder="Dose" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none" />
                   </div>
                   <input placeholder="Indication..." value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none" />
