export const MilestoneNavigator: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);
  const [showAddCustom, setShowAddCustom] = useState(false);
  const [customMilestone, setCustomMilestone] = useState<Partial<Milestone>>({ description: '', category: 'Motor' });

  useEffect(() => {
    if (!history.milestones || history.milestones.length === 0) {
      updateHistory({ milestones: INITIAL_DATA });
    }
  }, [history.milestones, updateHistory]);

  const milestones = history.milestones || [];

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    updateHistory({ milestones: updated });

    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed) {
      addClinicalEvent({ 
        source: 'Development', 
        description: `Concern (${item.ageRange}): ${item.description.split('. Example:')[0]}`, 
        date: new Date().toLocaleDateString(), 
        severity: 'Medium' 
      });
    }
  };

  const updateNotes = (id: string, notes: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, notes } : m);
    updateHistory({ milestones: updated });
  };

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '9 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];
  const filteredData = useMemo(() => milestones.filter(m => m.ageRange === activeAge && m.isRedFlag === showRedFlags), [milestones, activeAge, showRedFlags]);

  return (
    <div className="space-y-8 pb-32 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row justify-between items-start gap-6 px-1">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">Milestone <span className="text-teal-600">Sync</span></h2>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Standardized developmental markers and clinical observation log.</p>
        </div>
        <button onClick={() => setShowAddCustom(!showAddCustom)} className="bg-white border-2 border-teal-100 text-teal-600 px-8 py-4 rounded-[1.5rem] font-black text-[11px] uppercase tracking-widest hover:bg-teal-50">
          {showAddCustom ? 'Cancel' : '+ Custom Marker'}
        </button>
      </header>

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-4 overflow-x-auto no-scrollbar border-b border-slate-100">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm min-w-max">
          {ageGroups.map(age => (
            <button key={age} onClick={() => setActiveAge(age)} className={`px-6 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeAge === age ? 'bg-teal-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>{age}</button>
          ))}
        </div>
      </nav>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm max-w-sm">
        <button onClick={() => setShowRedFlags(false)} className={`flex-1 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-teal-50 text-teal-700' : 'text-slate-400'}`}>Progress</button>
        <button onClick={() => setShowRedFlags(true)} className={`flex-1 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-50 text-rose-700' : 'text-slate-400'}`}>Clinical Flags</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-8">
        {filteredData.map(m => (
          <div key={m.id} className={`rounded-[3.5rem] border-2 transition-all overflow-hidden shadow-sm ${m.completed ? (showRedFlags ? 'bg-rose-50 border-rose-200' : 'bg-emerald-50 border-emerald-200 shadow-xl') : 'bg-white border-slate-100'}`}>
            <div className="p-8 md:p-10 space-y-6">
              <div className="flex justify-between items-start">
                <span className="px-2 py-1 rounded-lg text-[10px] font-black uppercase border bg-white/50">{m.category}</span>
                <button onClick={() => toggleMilestone(m.id)} className={`w-16 h-16 rounded-[2rem] border-4 flex items-center justify-center transition-all ${m.completed ? (showRedFlags ? 'bg-rose-600 text-white' : 'bg-emerald-600 text-white') : 'bg-slate-50 border-slate-100 text-slate-200'}`}>
                  {m.completed ? '✓' : ''}
                </button>
              </div>
              <p className="text-2xl font-black text-slate-800 leading-tight tracking-tight">{m.description.split('. Example:')[0]}</p>
              <p className="text-sm font-bold text-slate-400 italic">"Example: {m.description.split('. Example:')[1] || ''}"</p>

              <div className="pt-6 border-t border-slate-100 space-y-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-4">Observation Notes (Free Text)</label>
                <textarea 
                  value={m.notes || ''} 
                  onChange={e => updateNotes(m.id, e.target.value)} 
                  placeholder="Record how they achieved this, or any concerns..." 
                  className="w-full h-32 p-6 rounded-[2rem] bg-white/50 border border-slate-100 font-bold italic text-slate-600 text-sm outline-none shadow-inner resize-none" 
                />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

