  password?: string;
  stayLoggedIn?: boolean;
}

export type ViewType = 'dashboard' | 'symptoms' | 'growth' | 'dosage' | 'milestones' | 'stories' | 'vaccines' | 'screening' | 'profile' | 'redbook' | 'parenting' | 'setup' | 'bonding' | 'acutelogs' | 'appointments' | 'handover' | 'governance' | 'ethics' | 'regulatory' | 'sickday';

import React, { useState, useRef, useMemo } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useConnectivity } from '../hooks/useConnectivity';
import { useGovernance } from '../context/GovernanceContext';
import { useEnvironment } from '../context/EnvironmentContext';
import { useRole } from '../context/RoleContext';
import { evaluateRedFlags } from '../clinical/redFlags';
import { evaluateIMCIRedFlags } from '../clinical/redFlagsIMCI';

const RED_FLAGS_LIST = [
  { text: "Difficulty Breathing", sub: "Grunting, wheezing, or chest sucking in", icon: "🫁" },
  { text: "Infant Fever", sub: "Any fever in a baby under 3 months old", icon: "🌡️" },
  { text: "Altered Level of Consciousness", sub: "Unusually sleepy, floppy, or unresponsive", icon: "😴" },
  { text: "Non-Blanching Rash", sub: "Purple/red spots that don't fade when pressed", icon: "🟣" },
  { text: "Severe Pain", sub: "Inconsolable crying or extreme localized pain", icon: "😫" },
  { text: "Eye Injury/Swelling", sub: "Chemical splash, trauma, or sudden swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC = () => {
  const { addAcuteLog } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { addEntry } = useGovernance();
  const { mode } = useEnvironment();
  const { role } = useRole();
  const isOnline = useConnectivity();

  const [description, setDescription] = useState('');
  const [temp, setTemp] = useState('');
  const [duration, setDuration] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Derive age in months for red flag engine
  const ageMonths = useMemo(() => {
    if (!childProfile?.dob) return undefined;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
    if (now.getDate() < birth.getDate()) months--;
    return months;
  }, [childProfile]);

  // Integrated Safety Engine
  const activeRedFlags = useMemo(() => {
    const input = {
      ageMonths,
      temperature: temp ? parseFloat(temp) : undefined,
      symptoms: [description],
      durationDays: duration ? parseInt(duration) : undefined,
      environment: mode
    };

    const imciFlags = evaluateIMCIRedFlags({ symptoms: [description] });
    const stdFlags = evaluateRedFlags(input);

    return mode === 'low-resource' ? [...imciFlags, ...stdFlags] : stdFlags;
  }, [ageMonths, temp, description, duration, mode]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(description || "Visual symptom provided in image", image || undefined);
      setResult(res);

      addEntry({
        eventType: "symptom_evaluation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Desc: ${description.slice(0, 50)}... Temp: ${temp || 'N/A'}`,
        outputSummary: `AI triage completed.`,
        redFlags: activeRedFlags.map(rf => rf.id),
        disclaimerShown: true
      });
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveToLogs = () => {
    if (result) {
      const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      addAcuteLog({
        timestamp,
        type: 'Triage',
        value: activeRedFlags.length > 0 ? 'Urgent Review Indicated' : 'Standard Home Care',
        notes: `SYMPTOMS: ${description}\n\nAI SYNTHESIS:\n${result.text}`,
        media: image || undefined
      });
      setSaved(true);
      alert("Triage result successfully synced to Medical Hub logs.");
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
          <p className="text-slate-500 text-sm font-medium">Capture signs and receive guideline-based analysis.</p>
        </div>
        <div className="flex gap-2">
          {!isOnline && (
            <div className="bg-amber-100 text-amber-700 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border border-amber-200">
              <span>📡</span> Offline
            </div>
          )}
        </div>
      </header>

      {/* PERSISTENT CLINICAL RED FLAGS */}
      {activeRedFlags.length > 0 && (
        <div className="space-y-3 animate-in slide-in-from-top-4 duration-500">
          {activeRedFlags.map(flag => (
            <div key={flag.id} className={`p-6 rounded-[2.5rem] border-4 shadow-xl flex items-start gap-6 transition-all ${flag.severity === 'Urgent' ? 'bg-rose-50 border-rose-600' : 'bg-amber-50 border-amber-500'}`}>
              <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-4xl shadow-inner shrink-0 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white animate-pulse' : 'bg-amber-500 text-white'}`}>
                {flag.severity === 'Urgent' ? '🚨' : '⚠️'}
              </div>
              <div className="space-y-1">
                <h4 className={`text-2xl font-black italic tracking-tight ${flag.severity === 'Urgent' ? 'text-rose-900' : 'text-amber-900'}`}>
                  {flag.message}
                </h4>
                <p className={`text-sm font-bold leading-relaxed ${flag.severity === 'Urgent' ? 'text-rose-800/80' : 'text-amber-800/80'}`}>
                  {flag.subtext}
                </p>
                <div className="pt-2">
                  <a href="tel:000" className={`inline-flex items-center gap-2 px-6 py-2 rounded-xl font-black text-xs uppercase tracking-widest shadow-md transition-all active:scale-95 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white' : 'bg-amber-600 text-white'}`}>
                    📞 Call 000 / Emergency
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Temperature (°C)</label>
                 <input 
                   type="number" step="0.1" value={temp} onChange={e => setTemp(e.target.value)} placeholder="37.0"
                   className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/30 font-black text-slate-900"
                 />
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Duration (Days)</label>
                 <input 
                   type="number" min="0" value={duration} onChange={e => setDuration(e.target.value)} placeholder="0"
                   className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/30 font-black text-slate-900"
                 />
               </div>
            </div>

            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Barking cough, lethargy, persistent vomiting, no wet nappies..."
              className="w-full h-32 p-6 rounded-[2rem] border border-slate-100 bg-slate-50/30 font-bold italic outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner resize-none text-slate-900"
            />

            <div className="flex flex-col sm:flex-row items-center gap-4">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black border-2 text-[10px] uppercase tracking-widest w-full sm:w-auto transition-all bg-white border-slate-100 text-slate-500">
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button 
                onClick={handleAnalyze} 
                disabled={loading || (!description.trim() && !image)} 
                className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700'}`}
              >
                {loading ? 'Reviewing Protocols...' : 'Analyze Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-sm mx-auto animate-in zoom-in-95">
                <img src={image} alt="Symptom" className="w-full h-64 object-cover rounded-3xl border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-4 right-4 bg-white text-rose-500 w-10 h-10 rounded-full flex items-center justify-center shadow-xl font-black">✕</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-10 rounded-[4rem] shadow-2xl border-l-[20px] border-l-indigo-600 animate-in slide-in-from-bottom-6 duration-700 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl"></div>
              <div className="flex justify-between items-center mb-10 relative z-10">
                 <h3 className="text-3xl font-black text-slate-800 italic">AI Synthesis</h3>
                 <button 
                  onClick={handleSaveToLogs} 
                  disabled={saved} 
                  className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all ${saved ? 'bg-emerald-500 text-white' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
                 >
                  {saved ? '✓ Logged to Hub' : 'Sync to Medical Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-700 font-bold italic border-l-4 border-slate-100 pl-8 text-xl leading-relaxed relative z-10">{result.text}</div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-rose-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
             <h3 className="text-3xl font-black italic mb-10">EMERGENCY</h3>
             <div className="space-y-4">
                {RED_FLAGS_LIST.map((f, i) => (
                  <div key={i} className="bg-white/10 p-5 rounded-3xl flex items-start gap-4">
                    <span className="text-4xl">{f.icon}</span>
                    <div>
                      <span className="text-base font-black leading-tight block">{f.text}</span>
                      <span className="text-[10px] font-bold text-rose-100/70 block mt-1 italic">{f.sub}</span>
                    </div>
                  </div>
                ))}
             </div>
             <div className="mt-10">
                <a href="tel:000" className="block w-full py-6 bg-white text-rose-600 rounded-[2rem] text-center font-black text-4xl shadow-2xl active:scale-95">
                  📞 000
                </a>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Medication, SpecialistContact, MedicalDevice, MedicalReport, Condition, Investigation, PreviousMedication } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';
import { AcuteTracker } from './AcuteTracker';

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'diagnostics' | 'reports' | 'gear' | 'family' | 'logs'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // Expanded Form States
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', size: '', nextChangeDue: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active', notes: '' });

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}? (e.g. Side effects, completed course)`);
    if (reason === null) return;
    const ceased: PreviousMedication = {
      ...med,
      ceasedDate: new Date().toISOString().split('T')[0],
      ceaseReason: reason
    };
    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), ceased]
    });
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '', size: '', nextChangeDue: '' });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        try {
          const result = await analyzeMedicalReport(base64);
          if (result) {
            const newReport: MedicalReport = {
              id: crypto.randomUUID(),
              date: new Date().toLocaleDateString(),
              specialist: result.specialist.name,
              summary: result.summary,
              actionItems: result.actionItems,
              photoUrl: base64
            };
            updateHistory({
              medicalReports: [...(history.medicalReports || []), newReport],
              conditions: [...(history.conditions || []), ...(result.foundDiagnoses || []).map((d: string) => ({ id: crypto.randomUUID(), name: d, status: 'Active', dateDiagnosed: new Date().toLocaleDateString() }))],
              currentMedications: [...(history.currentMedications || []), ...(result.foundMedications || []).map((m: any) => ({ ...m, id: crypto.randomUUID(), startDate: new Date().toISOString() }))]
            });
            alert("Report analysis imported.");
          }
        } catch (error) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'diagnostics', label: 'Tests', icon: '🧪' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'family', label: 'Family', icon: '🌳' },
    { id: 'logs', label: 'Logs', icon: '📈' }
  ];

  return (
    <div className="space-y-8 pb-24 animate-in fade-in duration-700">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">Comprehensive clinical story and multidisciplinary coordination.</p>
        </div>
        <button onClick={handleGenerateHandover} disabled={loading} className="bg-indigo-600 text-white px-8 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest shadow-2xl transition-all active:scale-95 hover:bg-indigo-700">
          {loading ? 'Synthesizing...' : 'Generate AI Handover ✨'}
        </button>
      </header>

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/95 backdrop-blur-xl py-4 overflow-x-auto no-scrollbar border-b border-slate-100">
        <div className="flex gap-2 min-w-max">
          {tabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105' : 'bg-white text-slate-400 border border-slate-100 hover:bg-slate-50'}`}>
              <span className="text-xl">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl min-h-[600px] p-8 md:p-12">

        {activeTab === 'history' && (
          <div className="space-y-16">
            <section className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-4">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>📜</span> Past Medical History</h3>
                <textarea 
                  value={history.pastMedicalHistory} 
                  onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} 
                  placeholder="Chronic conditions..."
                  className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-indigo-50 shadow-inner resize-none" 
                />
              </div>
              <div className="space-y-4">
                <h3 className="text-xs font-black text-rose-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>✂️</span> Surgical History</h3>
                <textarea 
                  value={history.surgicalHistory} 
                  onChange={e => updateHistory({ surgicalHistory: e.target.value })} 
                  placeholder="Operations..."
                  className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-rose-50 shadow-inner resize-none" 
                />
              </div>
            </section>
            <section className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Active Issues List</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {(history.conditions || []).map(issue => (
                  <div key={issue.id} className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ conditions: history.conditions?.filter(x => x.id !== issue.id) })} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity">✕</button>
                    <p className="font-black text-slate-800 mb-1">{issue.name}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{issue.status}</p>
