                ))}
                <div className="bg-white p-6 rounded-[2rem] border-4 border-dashed border-slate-100 flex flex-col gap-3">
                   <input placeholder="New Issue Name..." value={newIssue.name} onChange={e => setNewIssue({...newIssue, name: e.target.value})} className="bg-slate-50 p-3 rounded-xl text-xs font-black outline-none" />
                   <button onClick={() => { if(newIssue.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newIssue, id: crypto.randomUUID(), dateDiagnosed: new Date().toLocaleDateString() } as Condition] }); setNewIssue({name: ''}); } }} className="bg-indigo-600 text-white py-2 rounded-xl text-[10px] font-black uppercase">Add Issue</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="space-y-16">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Active Medications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.currentMedications.map(m => (
                  <div key={m.id} className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 flex flex-col justify-between shadow-sm relative group">
                    <button onClick={() => ceaseMedication(m)} className="absolute top-8 right-8 bg-white text-rose-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity shadow-sm">Cease Med</button>
                    <div className="space-y-4">
                      <p className="text-3xl font-black text-emerald-900 tracking-tight">{m.name} <span className="text-emerald-500/50 font-medium">{m.dose}</span></p>
                      <div className="space-y-2">
                        <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Indication</p>
                        <p className="text-sm font-bold text-emerald-800 italic">"{m.indication || 'N/A'}"</p>
                      </div>
                      <p className="text-xs font-bold text-emerald-700/60 leading-relaxed">{m.instructions}</p>
                    </div>
                  </div>
                ))}
                <div className="bg-white p-10 rounded-[3rem] border-4 border-dashed border-slate-100 space-y-6">
                   <div className="grid grid-cols-2 gap-4">
                      <input placeholder="Drug Name" value={newMed.name} onChange={e => setNewMed({...newMed, name: e.target.value})} className="bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none" />
                      <input placeholder="Dose" value={newMed.dose} onChange={e => setNewMed({...newMed, dose: e.target.value})} className="bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none" />
                   </div>
                   <input placeholder="Indication..." value={newMed.indication} onChange={e => setNewMed({...newMed, indication: e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none" />
                   <button onClick={addMedication} className="w-full bg-indigo-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs shadow-xl">Add Active Medication</button>
                </div>
              </div>
            </section>
            <section className="space-y-8 pt-12 border-t border-slate-50">
              <h3 className="text-2xl font-black text-slate-400 italic">Medication History (Ceased)</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
