import React, { useState, useEffect } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, latestWeight } = useMedicalHistory();
  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: 500,
    intervalVolume: 5,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  useEffect(() => {
    if (latestWeight && !challenge.isActive) {
      const recommendedInterval = Math.round(latestWeight); 
      setChallenge(prev => ({
        ...prev,
        intervalVolume: recommendedInterval,
        targetVolume: recommendedInterval * 12 
      }));
    }
  }, [latestWeight, challenge.isActive]);

  const handleAdd = () => {
    if (!value) return;
    const finalValue = type === 'Temperature' && !value.includes('°C') ? `${value}°C` : value;
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type,
      value: finalValue,
      notes
    });
    setValue('');
    setNotes('');
  };

  const handleStartChallenge = () => {
    setChallenge(prev => ({ 
      ...prev, 
      isActive: true, 
      startTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      totalConsumed: 0,
      vomitCount: 0
    }));
  };

  const logChallengeFluid = (amount: number) => {
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Fluid',
      value: `${amount}ml`,
      notes: 'Part of Rehydration Challenge',
      isChallengeEntry: true
    });
    setChallenge(prev => ({ ...prev, totalConsumed: prev.totalConsumed + amount }));
  };

  const logChallengeVomit = () => {
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Vomit',
      value: 'Vomit recorded',
      notes: 'Loss during rehydration challenge',
      isChallengeEntry: true
    });
    setChallenge(prev => ({ ...prev, vomitCount: prev.vomitCount + 1 }));
  };

  const icons = { Fluid: '🥤', Temperature: '🌡️', Output: '🚽', Medication: '💊', Vomit: '🤮', Triage: '✨', Vitals: '🩺', 'Physical Exam': '👨‍⚕️' };

  const successRate = Math.min(Math.round((challenge.totalConsumed / challenge.targetVolume) * 100), 100);

  return (
    <div className="space-y-6 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Sync Log</span></h2>
          <p className="text-slate-500 text-xs font-medium italic mt-1">Track fluids, fever, and triage insights.</p>
        </div>

        {!challenge.isActive ? (
          <button 
            onClick={handleStartChallenge}
            className="w-full sm:w-auto bg-teal-600 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 transition-all hover:bg-teal-700"
          >
            <span>💧</span> Fluids Challenge
          </button>
        ) : (
          <button 
            onClick={() => setChallenge(prev => ({ ...prev, isActive: false }))}
            className="w-full sm:w-auto bg-slate-900 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl"
          >
            End Challenge
          </button>
        )}
      </header>

      {challenge.isActive && (
        <div className="bg-white rounded-[2.5rem] border-4 border-teal-500 shadow-2xl overflow-hidden animate-in zoom-in-95 mb-8">
           <div className="bg-teal-500 px-6 py-4 flex items-center justify-between text-white">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-xl animate-pulse">🧪</div>
                 <div>
                    <h3 className="text-lg font-black italic leading-none">Hydration Challenge</h3>
                    <p className="text-[9px] font-bold uppercase tracking-widest opacity-80 mt-1">Target: {challenge.intervalVolume}ml / {challenge.intervalMinutes}m</p>
                 </div>
              </div>
           </div>

           <div className="p-6 space-y-8">
              <div className="flex flex-col items-center">
                 <div className="relative w-40 h-40">
                    <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                      <circle cx="50" cy="50" r="40" stroke="#f1f5f9" strokeWidth="10" fill="transparent" />
                      <circle 
                        cx="50" cy="50" r="40" 
                        stroke="#14b8a6" 
                        strokeWidth="10" fill="transparent" 
                        strokeDasharray={`${successRate * 2.512}, 251.2`}
                        strokeLinecap="round"
                        className="transition-all duration-1000"
                      />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                       <span className="text-3xl font-black text-slate-800 leading-none">{challenge.totalConsumed}</span>
                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ml Intake</span>
                    </div>
                 </div>
              </div>

              <div className="space-y-4">
                 <div className="overflow-x-auto no-scrollbar pb-2">
                    <div className="flex gap-2 min-w-max">
                       {[5, 10, 20, 50].map(amt => (
                         <button 
                          key={amt} 
                          onClick={() => logChallengeFluid(amt)}
                          className="px-6 py-4 rounded-2xl bg-teal-50 border border-teal-100 text-teal-700 font-black text-xs hover:bg-teal-100 transition-all active:scale-95 shadow-sm"
                         >
                            +{amt}ml
                         </button>
                       ))}
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                    <button 
                      onClick={logChallengeVomit}
                      className="p-4 rounded-3xl bg-rose-50 border border-rose-100 text-rose-700 flex flex-col items-center gap-1 group"
                    >
                       <span className="text-3xl group-active:scale-125 transition-transform">🤮</span>
                       <span className="text-[10px] font-black uppercase">Record Vomit</span>
                       <span className="text-[8px] font-bold opacity-60">Total: {challenge.vomitCount}</span>
                    </button>
                    <div className="p-4 rounded-3xl bg-indigo-50 border border-indigo-100 text-indigo-700 flex flex-col items-center gap-1">
                       <span className="text-3xl">⏱️</span>
                       <span className="text-[10px] font-black uppercase">Next Dose</span>
                       <span className="text-[8px] font-bold opacity-60">5m Wait Rule</span>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
            <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 shadow-inner">
               {['Fluid', 'Temperature', 'Output', 'Medication'].map((t) => (
                  <button
                    key={t}
                    onClick={() => setType(t as any)}
                    className={`flex-1 py-3 rounded-xl text-xl transition-all ${type === t ? 'bg-white shadow-md text-indigo-600' : 'opacity-40 grayscale'}`}
                  >
                    {(icons as any)[t]}
                  </button>
               ))}
            </div>

            <div className="space-y-4">
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Clinical Value</label>
                  <input 
                    value={value} 
                    onChange={e => setValue(e.target.value)} 
                    placeholder={type === 'Fluid' ? '50ml' : type === 'Temperature' ? '38.5°C' : 'Wet Nappy'}
                    className="w-full p-4 rounded-2xl border border-slate-100 bg-white font-black text-base text-slate-900 placeholder-slate-400 focus:ring-2 focus:ring-indigo-500 outline-none shadow-inner"
                  />
               </div>
               <button onClick={handleAdd} className="w-full py-5 bg-rose-600 text-white font-black rounded-[1.5rem] shadow-xl text-[11px] uppercase tracking-widest active:scale-95 transition-all hover:bg-rose-700">Log Event</button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3">
           <div className="bg-white p-5 sm:p-10 rounded-[2.5rem] border border-slate-100 shadow-sm min-h-[400px]">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xl font-black text-slate-800 tracking-tight">Clinical Timeline</h3>
                 <span className="text-[9px] font-black text-slate-400 uppercase border border-slate-100 px-3 py-1 rounded-full">Weight: {latestWeight || '--'}kg</span>
              </div>
              <div className="space-y-4">
                 {(history.acuteLogs || []).length > 0 ? (history.acuteLogs || []).map(entry => (
                    <div key={entry.id} className={`p-5 rounded-3xl border transition-all ${entry.type === 'Triage' ? 'bg-indigo-50 border-indigo-100 shadow-lg scale-[1.01]' : entry.isChallengeEntry ? 'bg-teal-50 border-teal-50' : 'bg-slate-50/20 border-slate-50 shadow-sm'}`}>
                       <div className="flex items-center gap-4">
                          <span className="text-[10px] font-black text-slate-400 w-12 shrink-0">{entry.timestamp}</span>
                          <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-xl shadow-sm border border-slate-50 shrink-0">{(icons as any)[entry.type]}</div>
                          <div className="flex-1 overflow-hidden">
                             <p className={`text-sm font-black ${entry.type === 'Triage' ? 'text-indigo-900' : 'text-slate-800'}`}>
                                {entry.value} 
                                <span className="text-[8px] text-slate-400 uppercase tracking-widest ml-2 font-black">{entry.type}</span>
                             </p>
                             {entry.notes && (
                                <p className="text-[10px] font-bold text-slate-500 italic mt-1 whitespace-pre-wrap leading-relaxed">
                                   {entry.notes}
                                </p>
                             )}
                          </div>
                       </div>
                       {entry.media && (
                          <div className="mt-4 ml-16 relative w-32 h-32 group">
                             <img src={entry.media} alt="Clinical Visual" className="w-full h-full object-cover rounded-2xl border-2 border-white shadow-md group-hover:scale-110 transition-transform cursor-pointer" onClick={() => window.open(entry.media)} />
                          </div>
                       )}
                    </div>
                 )) : (
                    <div className="flex flex-col items-center justify-center py-20 opacity-20">
                       <span className="text-6xl mb-4">📉</span>
                       <p className="font-black text-sm uppercase tracking-widest text-slate-900">No clinical entries</p>
                    </div>
                 )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Medication, SpecialistContact, MedicalDevice, MedicalReport, Condition, Investigation, PreviousMedication } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'diagnostics' | 'reports' | 'gear' | 'family'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // High-Fidelity Form States
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', size: '', lastChanged: '', nextChangeDue: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active' });
  const [newInvestigation, setNewInvestigation] = useState<Partial<Investigation>>({ name: '', result: '', date: new Date().toISOString().split('T')[0] });

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}? (e.g., side effects, course finished)`);
    if (reason === null) return;
    const ceased: PreviousMedication = { 
      ...med, 
      ceasedDate: new Date().toISOString().split('T')[0], 
      ceaseReason: reason 
    };
    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), ceased]
    });
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '', size: '', lastChanged: '', nextChangeDue: '' });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
