                <div className="bg-white p-6 rounded-[2rem] border-4 border-dashed border-slate-100 flex flex-col gap-3">
                   <input placeholder="Diagnosis Name..." value={newIssue.name} onChange={e => setNewIssue({...newIssue, name: e.target.value})} className="bg-slate-50 p-3 rounded-xl text-xs font-black outline-none" />
                   <button onClick={() => { if(newIssue.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newIssue, id: crypto.randomUUID(), dateDiagnosed: new Date().toLocaleDateString() } as Condition] }); setNewIssue({name: ''}); } }} className="bg-indigo-600 text-white py-2 rounded-xl text-[10px] font-black uppercase">Add Diagnosis</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="space-y-16">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Current Medications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.currentMedications.map(m => (
