import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, latestWeight } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: 500,
    intervalVolume: 5,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  // Neonatal Logic
  const isNeonate = useMemo(() => {
    if (!childProfile?.dob) return false;
    const birth = new Date(childProfile.dob);
    const diff = Date.now() - birth.getTime();
    const ageMonths = diff / (1000 * 60 * 60 * 24 * 30.44);
    return ageMonths < 3;
  }, [childProfile]);

  const showNeonatalWarning = useMemo(() => {
    if (type === 'Temperature' && isNeonate) {
      const temp = parseFloat(value);
      return !isNaN(temp) && temp >= 38.0;
    }
    return false;
  }, [type, value, isNeonate]);

  useEffect(() => {
    if (latestWeight && !challenge.isActive) {
      const recommendedInterval = Math.round(latestWeight); 
      setChallenge(prev => ({
        ...prev,
        intervalVolume: recommendedInterval,
        targetVolume: recommendedInterval * 12 
      }));
    }
  }, [latestWeight, challenge.isActive]);

  const handleAdd = () => {
    if (!value) return;
    const finalValue = type === 'Temperature' && !value.includes('degree Celsius') ? `${value} degree Celsius` : value;
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type,
      value: finalValue,
      notes
    });
    setValue('');
    setNotes('');
  };

  const handleStartChallenge = () => {
    setChallenge(prev => ({ 
      ...prev, 
      isActive: true, 
      startTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      totalConsumed: 0,
      vomitCount: 0
    }));
  };

  const logChallengeFluid = (amount: number) => {
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Fluid',
      value: `${amount}ml`,
      notes: 'Part of Rehydration Challenge',
      isChallengeEntry: true
    });
    setChallenge(prev => ({ ...prev, totalConsumed: prev.totalConsumed + amount }));
  };

  const logChallengeVomit = () => {
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'Vomit',
      value: 'Vomit recorded',
      notes: 'Loss during rehydration challenge',
      isChallengeEntry: true
    });
    setChallenge(prev => ({ ...prev, vomitCount: prev.vomitCount + 1 }));
  };

  const icons = { Fluid: '🥤', Temperature: '🌡️', Output: '🚽', Medication: '💊', Vomit: '🤮', Triage: '✨', Vitals: '🩺', 'Physical Exam': '👨‍⚕️' };

  const successRate = Math.min(Math.round((challenge.totalConsumed / challenge.targetVolume) * 100), 100);

  return (
    <div className="space-y-6 pb-20 animate-in fade-in">
      {/* Lightbox Modal */}
      {lightboxImage && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-6" onClick={() => setLightboxImage(null)}>
           <div className="relative max-w-4xl w-full bg-white p-2 rounded-[2rem] shadow-2xl animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
              <button onClick={() => setLightboxImage(null)} className="absolute -top-12 right-0 text-white font-black text-2xl">✕ Close</button>
              <img src={lightboxImage} alt="Clinical Visual Full Size" className="w-full h-auto rounded-[1.5rem] shadow-inner" />
           </div>
        </div>
      )}

      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Sync Log</span></h2>
          <p className="text-slate-500 text-xs font-medium italic mt-1">Track fluids, fever, and triage insights.</p>
        </div>

        {!challenge.isActive ? (
          <button 
            onClick={handleStartChallenge}
            className="w-full sm:w-auto bg-teal-600 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 transition-all hover:bg-teal-700"
          >
            <span>💧</span> Fluids Challenge
          </button>
        ) : (
          <button 
            onClick={() => setChallenge(prev => ({ ...prev, isActive: false }))}
            className="w-full sm:w-auto bg-slate-900 text-white px-6 py-4 rounded-3xl font-black text-[10px] uppercase tracking-widest shadow-xl"
          >
            End Challenge
          </button>
        )}
      </header>

      {challenge.isActive && (
        <div className="bg-white rounded-[2.5rem] border-4 border-teal-500 shadow-2xl overflow-hidden animate-in zoom-in-95 mb-8">
           <div className="bg-teal-500 px-6 py-4 flex items-center justify-between text-white">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-xl animate-pulse">🧪</div>
                 <div>
                    <h3 className="text-lg font-black italic leading-none">Hydration Challenge</h3>
                    <p className="text-[9px] font-bold uppercase tracking-widest opacity-80 mt-1">Target: {challenge.intervalVolume}ml / {challenge.intervalMinutes}m</p>
                 </div>
              </div>
           </div>

           <div className="p-6 space-y-8">
              <div className="flex flex-col items-center">
                 <div className="relative w-40 h-40">
                    <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                      <circle cx="50" cy="50" r="40" stroke="#f1f5f9" strokeWidth="10" fill="transparent" />
                      <circle 
                        cx="50" cy="50" r="40" 
                        stroke="#14b8a6" 
                        strokeWidth="10" fill="transparent" 
                        strokeDasharray={`${successRate * 2.512}, 251.2`}
                        strokeLinecap="round"
                        className="transition-all duration-1000"
                      />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                       <span className="text-3xl font-black text-slate-800 leading-none">{challenge.totalConsumed}</span>
                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ml Intake</span>
                    </div>
                 </div>
                 {/* Progress Bar Alternative */}
                 <div className="w-full max-w-xs h-2 bg-slate-100 rounded-full mt-6 overflow-hidden">
                    <div className="h-full bg-teal-500 transition-all duration-1000" style={{ width: `${successRate}%` }}></div>
                 </div>
              </div>

              <div className="space-y-4">
