import React, { useState, useEffect, useMemo } from 'react';
import { calculateDosage } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useNavigation } from '../context/NavigationContext';
import { useRole } from '../context/RoleContext';
import { useConnectivity } from '../hooks/useConnectivity';
import { useGovernance } from '../context/GovernanceContext';
import { useEnvironment } from '../context/EnvironmentContext';
import { calculateSafetyCeiling } from '../clinical/dosing';

const OTC_MEDICATIONS = [
  { id: 'paracetamol', name: 'Paracetamol (Panadol/Tylenol)', icon: '💧' },
  { id: 'ibuprofen', name: 'Ibuprofen (Nurofen/Advil)', icon: '🍊' },
  { id: 'cetirizine', name: 'Antihistamine (Cetirizine/Zyrtec)', icon: '🤧' },
];

export const DoseCalculator: React.FC = () => {
  const { latestWeight } = useMedicalHistory();
  const { navigateTo } = useNavigation();
  const { role } = useRole();
  const { addEntry } = useGovernance();
  const { mode } = useEnvironment();
  const isOnline = useConnectivity();

  const [weight, setWeight] = useState(latestWeight?.toString() || '');
  const [medication, setMedication] = useState(OTC_MEDICATIONS[0].name);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  // Deterministic Safety Check - Runs automatically
  const safetyCeiling = useMemo(() => {
    const wNum = parseFloat(weight);
    if (!weight || isNaN(wNum)) return null;
    return calculateSafetyCeiling(wNum, medication);
  }, [weight, medication]);

  useEffect(() => {
    if (latestWeight) {
      setWeight(latestWeight.toString());
    }
  }, [latestWeight]);

  const handleCalculate = async () => {
    const weightNum = parseFloat(weight);
    if (!weight || isNaN(weightNum) || weightNum <= 0) return;

    const safetyMultiplier = mode === 'low-resource' ? 0.8 : 1.0;

    if (!isOnline) {
      if (safetyCeiling) {
        const adjustedDose = Math.floor((safetyCeiling.mgPerDose * safetyMultiplier) / 10) * 10;
        setResult({
          medicationName: safetyCeiling.medication,
          recommendedDose: `${adjustedDose} mg (Conservative Offline Calc)`,
          frequency: `Every ${safetyCeiling.intervalHours} hours`,
          maxDose24h: `${safetyCeiling.maxDosesPerDay} doses in 24 hours`,
          cautionaryNotes: `Offline Mode. ${mode === 'low-resource' ? 'Low-resource safety margin applied.' : ''} ${safetyCeiling.safetyWarnings.join(' ')}`
        });
      }
      return;
    }

    setLoading(true);
    try {
      const res = await calculateDosage(weightNum, medication);
      setResult(res);

      addEntry({
        eventType: "dose_calculation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Weight: ${weight}kg, Medication: ${medication}`,
        outputSummary: `Dose calculated: ${res.recommendedDose}`,
        disclaimerShown: true
      });
    } catch (error) {
      console.error(error);
      alert("Error calculating dosage.");
    } finally {
      setLoading(false);
    }
  };

  if (!latestWeight && !weight) {
    return (
      <div className="max-w-2xl mx-auto space-y-6 py-12 animate-in fade-in">
        <div className="bg-amber-50 border-2 border-dashed border-amber-200 p-12 rounded-[3rem] text-center space-y-6">
           <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-sm mx-auto">⚖️</div>
           <div className="space-y-2">
             <h3 className="text-2xl font-black text-amber-900 tracking-tight">Weight Required</h3>
             <p className="text-amber-800/70 font-medium italic">Clinical safety protocols require a recent weight measurement before calculating dosages.</p>
           </div>
           <button onClick={() => navigateTo('redbook')} className="px-8 py-4 bg-amber-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-amber-700 transition-all">Log Weight in Red Book</button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      <header className="px-1 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">SafeDose <span className="text-emerald-600">OTC</span></h2>
          <p className="text-slate-500 text-xs font-medium italic mt-1">Weight-based guidance for standard medications.</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-2">Child's Weight (kg)</label>
              <div className="relative">
                <input type="number" inputMode="decimal" value={weight} onChange={e => setWeight(e.target.value)} placeholder="e.g. 12" className="w-full p-5 rounded-2xl border border-slate-100 focus:ring-2 focus:ring-emerald-500 outline-none font-black text-xl bg-slate-50/30 text-slate-900 placeholder-slate-400" />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 font-black text-slate-300 text-xs tracking-widest uppercase">kg</span>
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Common OTC Medication</label>
              <div className="grid grid-cols-1 gap-2">
                {OTC_MEDICATIONS.map(m => (
                  <button key={m.id} onClick={() => setMedication(m.name)} className={`w-full p-4 rounded-2xl border-2 text-left transition-all flex items-center gap-4 ${medication === m.name ? 'border-emerald-500 bg-emerald-50 shadow-sm' : 'border-slate-50 bg-white hover:border-slate-100 text-slate-500'}`}>
                    <span className="text-2xl">{m.icon}</span>
                    <span className="font-bold text-sm leading-tight">{m.name}</span>
                  </button>
                ))}
              </div>
            </div>

            <button onClick={handleCalculate} disabled={loading || !weight} className={`w-full py-5 rounded-2xl font-black text-white shadow-xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-300' : 'bg-emerald-600 active:scale-95'}`}>{loading ? 'Consulting Protocols...' : 'Verify Safe Dose ✨'}</button>
          </div>

          {/* DETERMINISTIC BASELINE WARNING */}
          {safetyCeiling && (
            <div className="bg-emerald-900 p-6 rounded-[2rem] text-white shadow-xl space-y-3 animate-in fade-in">
               <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Local Safety Baseline (Verified)</p>
               <h5 className="text-lg font-black italic tracking-tight">Max Safe Dose: {safetyCeiling.mgPerDose} mg</h5>
               <p className="text-[10px] font-bold text-emerald-100/70 leading-relaxed italic">This is the RCH Melbourne standard for a {weight} kg child. Ensure AI calculations do not exceed this value.</p>
            </div>
          )}
        </div>

        <div className="lg:col-span-2">
          {result ? (
            <div className="bg-white p-8 sm:p-12 rounded-[3.5rem] border border-emerald-50 shadow-2xl space-y-8 animate-in zoom-in-95 border-l-[16px] border-l-emerald-600 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-12 -mt-12 w-48 h-48 bg-emerald-500 rounded-full opacity-5 blur-3xl"></div>
              <div className="relative z-10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center text-4xl shadow-inner">💊</div>
                  <div>
                    <h3 className="text-2xl font-black text-slate-800 tracking-tighter italic">{result.medicationName}</h3>
                    <p className="text-emerald-600 font-black text-[9px] uppercase tracking-widest">Guideline for {weight}kg</p>
                  </div>
                </div>
              </div>
              <div className="relative z-10 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-slate-50/50 p-8 rounded-[2rem] border border-slate-100 text-center">
                  <p className="text-slate-400 font-black text-[9px] uppercase tracking-widest mb-3">Recommended Single Dose</p>
                  <p className="text-5xl font-black text-emerald-600 tracking-tighter">{role === 'clinician' ? result.recommendedDose : result.recommendedDose.split('(')[0]}</p>
                  <p className="text-slate-500 font-black text-[9px] uppercase tracking-widest mt-2 opacity-60">{result.frequency}</p>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-[2rem] border border-slate-100 text-center">
                  <p className="text-slate-400 font-black text-[9px] uppercase tracking-widest mb-3">Max in 24 Hours</p>
                  <p className="text-3xl font-black text-slate-800 tracking-tighter">{result.maxDose24h}</p>
                  <p className="text-rose-500 font-black text-[8px] uppercase tracking-widest mt-2">Critical Safety Limit</p>
                </div>
              </div>
              <div className="relative z-10 bg-emerald-50 p-8 rounded-[2rem] border border-emerald-100 space-y-2">
                <h4 className="text-[9px] font-black text-emerald-800 uppercase tracking-widest">Clinical Precautions</h4>
                <p className="text-emerald-950 font-bold text-base leading-relaxed italic">{result.cautionaryNotes}</p>
              </div>
            </div>
          ) : (
            <div className="h-full min-h-[350px] bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] flex flex-col items-center justify-center p-8 text-center space-y-4">
               <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-sm text-slate-300 opacity-50">⚖️</div>
               <div className="max-w-xs">
                 <h4 className="font-black text-slate-800 text-lg tracking-tight mb-1">Verify Safe Dose</h4>
                 <p className="text-slate-400 text-xs font-medium italic">Enter weight and select medication to see clinical guidance baseline.</p>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { GrowthRecord } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';

const WHO_WEIGHT_REF = [
  { age: 0, p3: 2.4, p50: 3.3, p97: 4.3 },
  { age: 3, p3: 5.0, p50: 6.4, p97: 8.0 },
  { age: 6, p3: 6.4, p50: 7.9, p97: 9.8 },
  { age: 9, p3: 7.1, p50: 8.9, p97: 11.0 },
  { age: 12, p3: 7.7, p50: 9.6, p97: 12.0 },
  { age: 18, p3: 8.8, p50: 10.9, p97: 13.7 },
  { age: 24, p3: 9.7, p50: 12.2, p97: 15.3 },
  { age: 36, p3: 11.3, p50: 14.3, p97: 18.3 },
  { age: 48, p3: 12.7, p50: 16.3, p97: 21.2 },
];

export const GrowthTracker: React.FC = () => {
  const { history, updateHistory } = useMedicalHistory();
  const records = history.growthRecords || [];
  const [showReferenceLines, setShowReferenceLines] = useState(true);

  const [newRecord, setNewRecord] = useState({ 
    age: '', weight: '', height: '', head: '', 
    date: new Date().toISOString().split('T')[0] 
  });

  const handleAddRecord = () => {
    const ageNum = Number(newRecord.age);
    const weightNum = Number(newRecord.weight);
    if (isNaN(ageNum) || isNaN(weightNum) || weightNum < 1 || weightNum > 150) {
       alert("Please enter a realistic pediatric weight (2kg - 100kg).");
       return;
    }
    if (!newRecord.age || !newRecord.weight || !newRecord.height) return;
    const record: GrowthRecord = {
      age: ageNum,
      weight: weightNum,
      height: Number(newRecord.height),
      headCircumference: newRecord.head ? Number(newRecord.head) : undefined,
      date: newRecord.date
    };
    const updated = [...records, record].sort((a, b) => a.age - b.age);
    updateHistory({ growthRecords: updated });
    setNewRecord({ age: '', weight: '', height: '', head: '', date: new Date().toISOString().split('T')[0] });
  };

  const chartData = useMemo(() => {
    const ages = Array.from(new Set([
      ...WHO_WEIGHT_REF.map(r => r.age), 
      ...records.map(r => r.age)
    ])).sort((a, b) => a - b);

    return ages.map(age => {
      const ref = WHO_WEIGHT_REF.find(r => r.age === age);
      const user = records.find(r => r.age === age);
      return {
        age,
        weight: user?.weight,
        height: user?.height,
        p3_weight: ref?.p3,
        p50_weight: ref?.p50,
        p97_weight: ref?.p97
      };
    });
  }, [records]);

  const currentPercentile = useMemo(() => {
    if (records.length === 0) return null;
    const last = records[records.length - 1];
    const ref = WHO_WEIGHT_REF.reduce((prev, curr) => 
      Math.abs(curr.age - last.age) < Math.abs(prev.age - last.age) ? curr : prev
    );

    if (last.weight < ref.p3) return "Below 3rd (Consult GP)";
    if (last.weight < ref.p50) return "15th - 50th";
    if (last.weight === ref.p50) return "50th (Average)";
    if (last.weight < ref.p97) return "50th - 97th";
    return "Above 97th";
  }, [records]);

  return (
    <div className="space-y-6">
      <header className="flex flex-col sm:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Growth Trajectory</h2>
          <p className="text-slate-500 font-medium">WHO Reference Percentiles integrated tracking.</p>
        </div>
        <div className="flex gap-2">
           <button onClick={() => setShowReferenceLines(!showReferenceLines)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${showReferenceLines ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-400 border-slate-100'}`}>
              {showReferenceLines ? 'Hide WHO Lines' : 'Show WHO Lines'}
           </button>
           {currentPercentile && (
              <div className="bg-emerald-600 px-6 py-2 rounded-xl text-white shadow-lg">
                 <p className="text-[10px] font-black uppercase tracking-widest opacity-70 leading-none">Weight Category</p>
                 <p className="text-sm font-black mt-1">{currentPercentile}</p>
              </div>
           )}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="lg:col-span-1 bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 self-start">
          <h3 className="font-bold text-slate-800 mb-6 uppercase text-[10px] tracking-widest">Log Measurement</h3>
          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Age (months)</label>
              <input type="number" value={newRecord.age} onChange={e => setNewRecord({...newRecord, age: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/50 outline-none focus:ring-2 focus:ring-blue-500 font-black text-slate-900" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Weight (kg)</label>
                <input type="number" step="0.1" value={newRecord.weight} onChange={e => setNewRecord({...newRecord, weight: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/50 font-black text-slate-900" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-2">Height (cm)</label>
                <input type="number" step="0.1" value={newRecord.height} onChange={e => setNewRecord({...newRecord, height: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50/50 font-black text-slate-900" />
              </div>
            </div>
            <button onClick={handleAddRecord} className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl hover:bg-blue-700 transition-all transform active:scale-95">Log Measurement</button>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 h-full min-h-[500px]">
            <h3 className="text-xl font-bold text-slate-800 mb-8 flex items-center gap-2">
              <span className="text-blue-500">📉</span> Interactive Trajectory
            </h3>
            <div className="h-[450px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="age" tick={{ fill: '#64748b', fontSize: 12, fontWeight: 700 }} />
                  <YAxis yAxisId="kg" domain={['auto', 'auto']} tick={{ fill: '#64748b', fontSize: 12, fontWeight: 700 }} />
                  <Tooltip contentStyle={{ borderRadius: '1.5rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '16px' }} />
                  <Legend verticalAlign="top" height={36}/>

                  {showReferenceLines && <Line yAxisId="kg" type="monotone" dataKey="p97_weight" stroke="#cbd5e1" strokeWidth={1} strokeDasharray="5 5" dot={false} name="WHO 97th" />}
                  {showReferenceLines && <Line yAxisId="kg" type="monotone" dataKey="p50_weight" stroke="#94a3b8" strokeWidth={1.5} strokeDasharray="10 5" dot={false} name="WHO 50th (Mean)" />}
                  {showReferenceLines && <Line yAxisId="kg" type="monotone" dataKey="p3_weight" stroke="#cbd5e1" strokeWidth={1} strokeDasharray="5 5" dot={false} name="WHO 3rd" />}

                  <Line yAxisId="kg" type="monotone" dataKey="weight" stroke="#3b82f6" strokeWidth={5} dot={{ r: 8, fill: '#3b82f6', strokeWidth: 4, stroke: '#fff' }} name="Child's Weight" animationDuration={1000} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Appointment } from '../types';
import { prepareAppointmentQuestions } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useGovernance } from '../context/GovernanceContext';

export const AppointmentManager: React.FC = () => {
  const { history, updateHistory, addAppointment } = useMedicalHistory();
  const { log } = useGovernance();
  const [prepLoading, setPrepLoading] = useState<string | null>(null);
  const [newAppointment, setNewAppointment] = useState<Partial<Appointment>>({ 
    provider: '', specialty: '', dateTime: '', location: '', purpose: '', status: 'Upcoming' 
  });
  const [linkSpecialist, setLinkSpecialist] = useState(true);

  const handleAdd = () => {
    if (newAppointment.provider && newAppointment.dateTime) {
      const apt: Appointment = { 
        id: crypto.randomUUID(), 
        preVisitNotes: '',
        postVisitSummary: '',
        reminderSent: false,
        ...newAppointment 
      } as Appointment;
      addAppointment(apt, linkSpecialist);
      setNewAppointment({ provider: '', specialty: '', dateTime: '', location: '', purpose: '', status: 'Upcoming' });
    }
  };

  const handleAIPrep = async (apt: Appointment) => {
    setPrepLoading(apt.id);
    try {
      // Logic Improvement: Include last 3 urgent alerts in prep
      const recentUrgentFlags = log
        .filter(e => e.redFlags && e.redFlags.length > 0)
        .slice(0, 3)
        .flatMap(e => e.redFlags || []);

      const questions = await prepareAppointmentQuestions(history, apt, recentUrgentFlags);
      updateHistory({
        appointments: history.appointments.map(a => 
          a.id === apt.id ? { ...a, preVisitNotes: questions } : a
        )
      });
    } catch (e) {
      alert("Error generating prep questions.");
    } finally {
      setPrepLoading(null);
    }
  };

  const handleUpdateStatus = (id: string, status: 'Completed' | 'Upcoming' | 'Cancelled') => {
    updateHistory({
      appointments: history.appointments.map(a => a.id === id ? { ...a, status } : a)
    });
  };

  const handleUpdateSummary = (id: string, postVisitSummary: string) => {
    updateHistory({
      appointments: history.appointments.map(a => a.id === id ? { ...a, postVisitSummary } : a)
    });
  };

  const renderQuestionList = (notes: string) => {
    const lines = notes.split('\n').filter(l => l.trim().startsWith('•') || l.trim().startsWith('-'));
    if (lines.length === 0) return <p className="italic text-slate-600 font-bold leading-relaxed">{notes}</p>;

    return (
      <div className="space-y-3">
        {lines.map((line, i) => (
          <label key={i} className="flex items-start gap-3 cursor-pointer group p-2 hover:bg-white/50 rounded-xl transition-all">
            <input type="checkbox" className="mt-1 w-4 h-4 rounded text-indigo-600 border-slate-300 focus:ring-indigo-500" />
            <span className="text-sm font-black text-slate-900 group-hover:text-indigo-700 transition-colors">
              {line.replace(/^[•-]\s*/, '')}
            </span>
          </label>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-500">
      <header>
        <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Appointment <span className="text-indigo-600">Navigator</span></h2>
        <p className="text-slate-500 font-medium italic">Clinical visit preparation, scheduling coordination, and AI prep.</p>
      </header>

      <section className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl space-y-8">
        <div className="flex items-center gap-3">
           <div className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-xl">🗓️</div>
           <h4 className="font-black text-slate-800 uppercase tracking-widest text-xs">Schedule Specialist Visit</h4>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Provider Name</label>
             <input value={newAppointment.provider} onChange={e => setNewAppointment({...newAppointment, provider: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Specialty</label>
             <input value={newAppointment.specialty} onChange={e => setNewAppointment({...newAppointment, specialty: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date & Time</label>
             <input type="datetime-local" value={newAppointment.dateTime} onChange={e => setNewAppointment({...newAppointment, dateTime: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 uppercase" />
          </div>
          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Location</label>
             <input value={newAppointment.location} onChange={e => setNewAppointment({...newAppointment, location: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="space-y-1 md:col-span-2">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clinical Purpose</label>
             <input value={newAppointment.purpose} onChange={e => setNewAppointment({...newAppointment, purpose: e.target.value})} className="w-full p-4 rounded-2xl border border-slate-100 bg-slate-50 shadow-inner text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row items-center justify-between gap-6 pt-4 border-t border-slate-50">
          <label className="flex items-center gap-3 cursor-pointer group">
             <input type="checkbox" checked={linkSpecialist} onChange={e => setLinkSpecialist(e.target.checked)} className="w-5 h-5 rounded-lg text-indigo-600 focus:ring-indigo-500" />
             <span className="text-xs font-black text-slate-500 uppercase tracking-widest group-hover:text-indigo-600 transition-colors">Link provider to Care Team automatically</span>
          </label>
          <button onClick={handleAdd} className="w-full sm:w-auto px-10 py-4 bg-indigo-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-indigo-700 transition-all hover:-translate-y-1">Confirm Booking</button>
        </div>
      </section>

      <div className="space-y-6">
        <h3 className="text-2xl font-black text-slate-800">Timeline of Care</h3>
        <div className="grid grid-cols-1 gap-6">
          {history.appointments.length === 0 ? (
            <div className="bg-slate-50 border-4 border-dashed border-slate-200 rounded-[3rem] p-20 text-center space-y-4">
               <span className="text-6xl block">🗓️</span>
               <p className="text-slate-400 font-black uppercase text-sm tracking-widest">No appointments scheduled</p>
            </div>
          ) : (
            history.appointments.sort((a,b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime()).map(apt => (
              <div key={apt.id} className={`bg-white p-8 rounded-[3rem] border shadow-sm space-y-6 group hover:shadow-xl transition-all ${apt.status === 'Completed' ? 'opacity-70 border-slate-100' : 'border-indigo-50'}`}>
                <div className="flex flex-col md:flex-row justify-between gap-6">
                  <div className="flex gap-6">
                    <div className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center font-black shadow-inner shrink-0 ${apt.status === 'Completed' ? 'bg-slate-100 text-slate-400' : 'bg-indigo-50 text-indigo-600'}`}>
                       <span className="text-[10px] uppercase opacity-60">{new Date(apt.dateTime).toLocaleString('en-US', { month: 'short' })}</span>
                       <span className="text-3xl tracking-tighter">{new Date(apt.dateTime).getDate()}</span>
                    </div>
                    <div>
                       <div className="flex items-center gap-3">
                          <h5 className="text-2xl font-black text-slate-800 tracking-tight">{apt.specialty}</h5>
                          {apt.status === 'Completed' && <span className="text-[9px] font-black uppercase tracking-widest text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded">✓ Completed</span>}
                       </div>
                       <p className="text-indigo-600 font-bold">{apt.provider}</p>
                       <p className="text-slate-400 text-xs font-medium flex items-center gap-2 mt-1 italic">📍 {apt.location} • 🕒 {new Date(apt.dateTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-2 self-start justify-end">
                    {apt.status === 'Upcoming' && (
                      <button onClick={() => handleAIPrep(apt)} disabled={!!prepLoading} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-700 transition-all flex items-center gap-2 shadow-lg">
                        {prepLoading === apt.id ? 'Analyzing Alerts...' : 'AI Prep ✨'}
                      </button>
                    )}
                  </div>
                </div>

                {apt.preVisitNotes && (
                  <div className="bg-indigo-50/30 p-8 rounded-[2rem] border border-indigo-100 animate-in slide-in-from-top-4">
                     <p className="text-[9px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-4">Recommended Clinical Questions</p>
                     <div className="border-l-4 border-indigo-200 pl-6">
                        {renderQuestionList(apt.preVisitNotes)}
