              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ChildProfile, Medication } from '../types';
import { useChildProfile } from '../context/ChildProfileContext';
import { useNavigation } from '../context/NavigationContext';

export const ChildProfileSetup: React.FC = () => {
  const { childProfile, setChildProfile } = useChildProfile();
  const { navigateTo } = useNavigation();

  // Child Info
  const [name, setName] = useState(childProfile?.name || '');
  const [dob, setDob] = useState(childProfile?.dob || '');
  const [sex, setSex] = useState<ChildProfile['sex']>(childProfile?.sex || 'Male');
  const [weight, setWeight] = useState(childProfile?.weight?.toString() || '');
  const [height, setHeight] = useState(childProfile?.height?.toString() || '');
  const [medHistory, setMedHistory] = useState(childProfile?.pastMedicalHistory || '');

  // Account Info
  const [email, setEmail] = useState(childProfile?.email || '');
  const [password, setPassword] = useState(childProfile?.password || '');
  const [stayLoggedIn, setStayLoggedIn] = useState(childProfile?.stayLoggedIn ?? true);
  const [agreedToTerms, setAgreedToTerms] = useState(false);

  const [meds, setMeds] = useState<Medication[]>(childProfile?.medications || []);
  const [allergies, setAllergies] = useState<string[]>(childProfile?.allergies || []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !dob || !email) {
      alert("Please complete the required fields (Name, DOB, and Email).");
      return;
    }

    const weightNum = parseFloat(weight);
    if (weight && (weightNum < 2 || weightNum > 150)) {
       alert("Please enter a realistic pediatric weight (2 kg to 150 kg).");
       return;
    }

    if (new Date(dob) > new Date()) {
       alert("Date of Birth cannot be in the future.");
       return;
    }

    if (!childProfile && !agreedToTerms) {
      alert("Please agree to the clinical terms and privacy policy.");
      return;
    }
    setChildProfile({
      name,
      dob,
      sex,
      weight: weight ? parseFloat(weight) : undefined,
      height: height ? parseFloat(height) : undefined,
      pastMedicalHistory: medHistory,
      medications: meds,
      previousMedications: childProfile?.previousMedications || [],
      allergies: allergies,
      email,
      password,
      stayLoggedIn
    });
    navigateTo('dashboard');
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-10 duration-700 pb-20">
      <header className="text-center space-y-4">
        <div className="w-24 h-24 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-6 shadow-2xl rotate-3">🩺</div>
        <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">
          {childProfile ? 'Account Settings' : 'Clinical Onboarding'}
        </h2>
      </header>

      <form onSubmit={handleSubmit} className="space-y-10">
        <section className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
          <div className="flex items-center gap-3">
            <span className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-lg">🆔</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Core Profile Information</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Child's Legal Name</label>
              <input type="text" required value={name} onChange={(e) => setName(e.target.value)} placeholder="Full Name" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg" />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date of Birth</label>
              <input type="date" required max={new Date().toISOString().split('T')[0]} value={dob} onChange={(e) => setDob(e.target.value)} className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg uppercase" />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Weight (kg)</label>
              <input type="number" step="0.1" min="2" max="150" value={weight} onChange={(e) => setWeight(e.target.value)} placeholder="Baseline weight" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg" />
            </div>
            <div className="space-y-2">
               <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Account Email</label>
               <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="parent@example.com" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg" />
            </div>
          </div>
        </section>

        <div className="flex gap-4 pt-4">
          <button type="button" onClick={() => navigateTo('dashboard')} className="flex-1 py-6 bg-slate-100 text-slate-500 font-black rounded-3xl hover:bg-slate-200 transition-all text-sm uppercase tracking-widest">Cancel</button>
          <button type="submit" className="flex-grow py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-2xl hover:bg-indigo-700 transition-all transform active:scale-95 text-sm uppercase tracking-widest">{childProfile ? 'Save Changes' : 'Initialize Health Hub ✨'}</button>
        </div>
      </form>
    </div>
  );
};

