            { id: 'mentalhealth', label: 'Resources', color: 'text-indigo-600' },
            { id: 'clinical', label: 'Frameworks', color: 'text-teal-600' }
          ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-4 sm:px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? `bg-white ${tab.color} shadow-md` : 'text-slate-400 hover:text-slate-600'}`}
