                            <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">{item.label}</p>
                        </div>
                        <input 
                            className="w-full bg-transparent border-none outline-none font-black text-lg placeholder-white/20 text-white" 
                            placeholder="..."
