export const ScreeningTool: React.FC = () => {
  const [activeModKey, setActiveModKey] = useState<string | null>(null);
  const [responses, setResponses] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState<any>(null);

  const activeMod = activeModKey ? SCREENING_MODS[activeModKey] : null;

  const chartData = useMemo(() => {
    if (!analysis || !activeMod) return [];

    // Group responses by category and average them
    const categories = Array.from(new Set(activeMod.questions.map(q => q.category)));
    return categories.map(cat => {
      const catQuestions = activeMod.questions.filter(q => q.category === cat);
      const sum = catQuestions.reduce((acc, q) => acc + parseInt(responses[q.id] || '0'), 0);
      return {
        subject: cat,
        A: sum / catQuestions.length,
        fullMark: 2,
      };
    });
  }, [analysis, responses, activeMod]);

  const handleResponse = (qId: string, val: string) => {
    setResponses(prev => ({ ...prev, [qId]: val }));
  };

  const handleSubmit = async () => {
    if (!activeMod) return;
    setLoading(true);
    try {
      const result = await analyzeScreening(activeMod.name, responses);
      setAnalysis(result);
    } catch (e) {
      console.error(e);
      alert("Error analyzing assessment.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      <header className="flex justify-between items-start">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">Wellbeing <span className="text-teal-600">Screening</span></h2>
          <p className="text-slate-500 font-medium italic">Standardized tools for clinical behavioral insight.</p>
        </div>
        {activeModKey && (
          <button onClick={() => {setActiveModKey(null); setAnalysis(null); setResponses({});}} className="bg-slate-100 px-6 py-2 rounded-xl font-black text-[10px] uppercase">Cancel Test</button>
        )}
      </header>

      {!activeModKey ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {Object.entries(SCREENING_MODS).map(([key, mod]) => (
            <button key={key} onClick={() => setActiveModKey(key)} className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm text-left hover:shadow-xl transition-all group relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-8 -mt-8 w-24 h-24 bg-teal-50 rounded-full group-hover:scale-150 transition-transform"></div>
              <h3 className="text-2xl font-black text-slate-800 mb-2 relative z-10">{mod.name}</h3>
              <p className="text-sm text-slate-500 italic relative z-10 leading-relaxed">{mod.description}</p>
              <div className="mt-6 flex items-center gap-2 text-teal-600 font-black text-[9px] uppercase tracking-widest relative z-10">Start Assessment <span>→</span></div>
            </button>
          ))}
        </div>
      ) : (
        <div className="space-y-6">
          {!analysis ? (
            <div className="space-y-4 animate-in slide-in-from-bottom-4">
              {activeMod?.questions.map((q, i) => (
                <div key={q.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 flex flex-col lg:flex-row justify-between items-center gap-6 shadow-sm hover:border-teal-100 transition-colors">
                  <div className="flex gap-4 items-start flex-1">
                    <span className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-[10px] font-black text-slate-400 shrink-0">{i+1}</span>
                    <p className="text-lg font-bold text-slate-700 italic leading-snug">{q.text}</p>
                  </div>
                  <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100 shadow-inner">
                    {activeMod.options.map(opt => (
                      <button 
                        key={opt.value}
                        onClick={() => handleResponse(q.id, opt.value)}
                        className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${responses[q.id] === opt.value ? 'bg-teal-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                        {opt.label}
                      </button>
                    ))}
                  </div>
                </div>
              ))}
              <div className="pt-8">
                <button 
                    onClick={handleSubmit} 
                    disabled={loading || Object.keys(responses).length < (activeMod?.questions.length || 0)}
                    className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl disabled:bg-slate-200 transition-all hover:bg-indigo-700 active:scale-95"
                >
                    {loading ? 'Synthesizing Patterns...' : 'Submit Assessment ✨'}
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-8 animate-in zoom-in-95">
              <div className="bg-white p-10 rounded-[4rem] border-l-[24px] border-l-teal-600 shadow-2xl space-y-12">
                 <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
                    <div className="space-y-6">
                        <div className="flex items-center gap-4">
                            <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center text-4xl shadow-inner border border-teal-100">🧠</div>
                            <div>
                                <h3 className="text-3xl font-black text-slate-800 italic">Clinical Synthesis</h3>
                                <p className="text-[10px] font-black uppercase tracking-widest text-teal-600">Behavioral Profile</p>
                            </div>
