                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="bg-slate-50/50 p-8 rounded-[3.5rem] border border-slate-100 h-[450px]">
                        <div className="text-center mb-6">
                            <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Clinical Radar (Fixed Scale 0-2)</h4>
                        </div>
                        <ResponsiveContainer width="100%" height="100%">
                            <RadarChart cx="50%" cy="50%" outerRadius="80%" data={chartData}>
                                <PolarGrid stroke="#cbd5e1" />
                                <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 10, fontWeight: 900 }} />
                                <PolarRadiusAxis angle={30} domain={[0, 2]} tick={false} axisLine={false} />
                                <Radar
                                    name="Current Score"
                                    dataKey="A"
