                <span className="text-lg">{mode === 'low-resource' ? '🌍' : '⚡'}</span>
                <div className="leading-none">
                  <p className="text-[9px] font-black uppercase tracking-widest">{mode === 'low-resource' ? 'Low Resource' : 'Standard'}</p>
                  <p className="text-[8px] font-bold opacity-60 mt-1">{mode === 'low-resource' ? 'Offline Active' : 'AI Triage Active'}</p>
                </div>
              </div>
           </div>
        </div>

        <div className="space-y-8">
          {groups.map((group) => (
            <div key={group.title} className="space-y-2">
              <h3 className={`text-[10px] font-black ${group.color} uppercase tracking-[0.25em] px-5 flex items-center gap-2 opacity-80`}>
                {group.title}
              </h3>
              <div className="flex flex-col gap-1.5 px-2">
                {group.items.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => handleNav(item.id as ViewType)}
                    className={`flex items-center gap-4 px-5 py-3.5 rounded-2xl transition-all border-2 ${
                      activeView === item.id 
                        ? `${group.bgColor} ${group.color} font-black border-white shadow-xl translate-x-1` 
                        : 'text-slate-500 hover:bg-slate-50 border-transparent hover:translate-x-1'
                    }`}
                  >
                    <span className={`text-xl ${item.highContrast ? 'filter drop-shadow-[0_2px_4px_rgba(0,0,0,0.2)] scale-125' : ''}`}>{item.icon}</span>
                    <span className="whitespace-nowrap text-sm font-black tracking-tight">{item.label}</span>
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-8 pt-6 border-t border-slate-100 px-4 space-y-2">
         <button onClick={() => handleNav('ethics')} className={`w-full flex items-center gap-4 px-6 py-4 rounded-[2rem] transition-all ${activeView === 'ethics' ? 'bg-indigo-600 text-white shadow-2xl scale-105' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>
          <span className="text-xl">🛡️</span>
          <span className="text-[11px] font-black uppercase tracking-widest">Safety & Ethics</span>
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#FBFBFE]">
      <div className="md:hidden flex items-center justify-between px-5 py-4 bg-white/95 backdrop-blur-xl border-b border-slate-100 sticky top-0 z-50 shadow-sm">
        <div className="flex items-center gap-3" onClick={() => handleNav('dashboard')}>
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg border-2 border-white">👶</div>
          <h1 className="text-lg font-black text-slate-800 italic tracking-tighter">PediPulse <span className="text-indigo-600">AI</span></h1>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="w-12 h-12 flex items-center justify-center bg-slate-50 rounded-2xl text-slate-600 border border-slate-200">
            {isMobileMenuOpen ? <span className="text-xl">✕</span> : <span className="text-2xl">☰</span>}
        </button>
      </div>

      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-[60] bg-white p-6 overflow-y-auto animate-in slide-in-from-right duration-500">
           <div className="flex justify-end mb-4">
             <button onClick={() => setIsMobileMenuOpen(false)} className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center font-black text-xl">×</button>
           </div>
          <NavContent />
        </div>
      )}

      <nav className="hidden md:flex w-72 bg-white border-r border-slate-200 p-4 sticky top-0 h-screen flex-col justify-between overflow-y-auto no-scrollbar shadow-2xl z-50">
        <NavContent />
      </nav>

      <main className="flex-1 p-4 sm:p-6 md:p-10 lg:p-14 overflow-y-auto">
        <div className="max-w-5xl mx-auto pb-24">{children}</div>
      </main>

      <div className="md:hidden fixed bottom-0 left-0 right-0 h-20 bg-white/80 backdrop-blur-2xl border-t border-slate-100 px-6 flex items-center justify-between z-50 shadow-[0_-10px_40px_-15px_rgba(0,0,0,0.1)]">
        {bottomNavItems.map(item => (
          <button key={item.id} onClick={() => handleNav(item.id as ViewType)} className={`flex flex-col items-center gap-1 transition-all ${activeView === item.id ? 'text-indigo-600 scale-110' : 'text-slate-400 grayscale opacity-60'}`}>
            <span className="text-2xl">{item.icon}</span>
            <span className="text-[9px] font-black uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
        <button onClick={() => handleNav('dashboard')} className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-2xl transition-all -translate-y-4 border-4 border-white ${activeView === 'dashboard' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
          <span className="text-2xl">🏠</span>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Medication, SpecialistContact, MedicalDevice, MedicalReport, Condition, Investigation, PreviousMedication } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, pendingEvents } = useMedicalHistory();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'history' | 'meds' | 'mdt' | 'diagnostics' | 'reports' | 'gear' | 'family'>('history');
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // Form States
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', size: '', lastChanged: '', nextChangeDue: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active' });
  const [newInvestigation, setNewInvestigation] = useState<Partial<Investigation>>({ name: '', result: '', date: new Date().toISOString().split('T')[0] });

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const handleClearAllData = () => {
    if (confirm("🚨 CRITICAL: This will delete ALL pediatric records stored locally on this device. This action cannot be undone. Are you sure?")) {
       localStorage.clear();
       window.location.reload();
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}? (e.g., side effects, course finished)`);
    if (reason === null) return;
    const ceased: PreviousMedication = { ...med, ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: reason };
    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), ceased]
    });
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '', size: '', lastChanged: '', nextChangeDue: '' });
    }
  };

  const addInvestigation = () => {
    if (newInvestigation.name) {
      updateHistory({ investigations: [...(history.investigations || []), { ...newInvestigation, id: crypto.randomUUID() } as Investigation] });
      setNewInvestigation({ name: '', result: '', date: new Date().toISOString().split('T')[0] });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        try {
          const result = await analyzeMedicalReport(base64);
          if (result) {
            const newReport: MedicalReport = {
              id: crypto.randomUUID(),
              date: new Date().toLocaleDateString(),
              specialist: result.specialist.name,
              summary: result.summary,
              actionItems: result.actionItems,
              photoUrl: base64
            };
            updateHistory({
              medicalReports: [...(history.medicalReports || []), newReport],
              conditions: [...(history.conditions || []), ...(result.foundDiagnoses || []).map((d: string) => ({ id: crypto.randomUUID(), name: d, status: 'Active', dateDiagnosed: new Date().toLocaleDateString() }))],
              currentMedications: [...(history.currentMedications || []), ...(result.foundMedications || []).map((m: any) => ({ ...m, id: crypto.randomUUID(), startDate: new Date().toISOString() }))]
            });
            alert("Specialist letter integrated.");
          }
        } catch (error) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const tabs = [
    { id: 'history', label: 'History', icon: '📜' },
    { id: 'meds', label: 'Meds', icon: '💊' },
    { id: 'mdt', label: 'Team', icon: '🫂' },
    { id: 'diagnostics', label: 'Tests', icon: '🧪' },
    { id: 'reports', label: 'Letters', icon: '✉️' },
    { id: 'gear', label: 'Gear', icon: '⚙️' },
    { id: 'family', label: 'Family', icon: '🌳' }
  ];

  return (
    <div className="space-y-8 pb-24 animate-in fade-in duration-700">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">Medical <span className="text-indigo-600">Hub</span></h2>
          <p className="text-slate-500 font-medium italic">High-fidelity longitudinal clinical record.</p>
        </div>
        <button onClick={handleGenerateHandover} disabled={loading} className="bg-indigo-600 text-white px-8 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest shadow-2xl hover:bg-indigo-700">
          {loading ? 'Synthesizing...' : 'Generate AI Handover ✨'}
        </button>
      </header>

      <nav className="sticky top-[64px] md:top-0 z-40 bg-[#FBFBFE]/95 backdrop-blur-xl py-4 overflow-x-auto no-scrollbar border-b border-slate-100">
        <div className="flex gap-2 min-w-max">
          {tabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl scale-105' : 'bg-white text-slate-400 border border-slate-100'}`}>
              <span className="text-xl">{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl min-h-[600px] p-8 md:p-12 relative overflow-hidden">

        {activeTab === 'history' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-4">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>📜</span> Past Medical History</h3>
                <textarea value={history.pastMedicalHistory} onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} placeholder="Chronic conditions..." className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-indigo-50 shadow-inner resize-none" />
              </div>
              <div className="space-y-4">
                <h3 className="text-xs font-black text-rose-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>✂️</span> Surgical History</h3>
                <textarea value={history.surgicalHistory} onChange={e => updateHistory({ surgicalHistory: e.target.value })} placeholder="Operations..." className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-rose-50 shadow-inner resize-none" />
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Active Issues</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {(history.conditions || []).map(issue => (
                  <div key={issue.id} className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ conditions: history.conditions?.filter(x => x.id !== issue.id) })} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <p className="font-black text-slate-800 mb-1">{issue.name}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{issue.status}</p>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-6 rounded-[2rem] flex flex-col gap-2">
                   <input value={newIssue.name} onChange={e => setNewIssue({ ...newIssue, name: e.target.value })} placeholder="Add condition..." className="bg-transparent font-bold text-sm outline-none" />
                   <button onClick={() => { if(newIssue.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newIssue, id: crypto.randomUUID(), status: 'Active' } as Condition] }); setNewIssue({ name: '' }); } }} className="text-[10px] font-black text-indigo-600 uppercase">Add Issue +</button>
                </div>
              </div>
            </section>

            <section className="pt-20 border-t border-slate-100 space-y-6">
               <div className="bg-rose-50 p-8 rounded-[3rem] border border-rose-100 flex flex-col md:flex-row items-center justify-between gap-6">
                  <div className="space-y-2 text-center md:text-left">
                     <h4 className="text-xl font-black text-rose-900 italic uppercase">Danger Zone</h4>
                     <p className="text-sm font-bold text-rose-800/60 leading-relaxed italic">Exercise your 'Right to be Forgotten'. This deletes all pediatric logs from local storage.</p>
                  </div>
                  <button onClick={handleClearAllData} className="px-10 py-5 bg-rose-600 text-white rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-rose-700 active:scale-95 transition-all">Clear All Data Permanently</button>
               </div>
            </section>
          </div>
        )}

        {activeTab === 'meds' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Current Medications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.currentMedications.map(m => (
                  <div key={m.id} className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 relative group shadow-sm">
                    <button onClick={() => ceaseMedication(m)} className="absolute top-8 right-8 bg-white text-rose-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 shadow-sm transition-opacity">Cease Med</button>
                    <div className="space-y-4">
                      <p className="text-3xl font-black text-emerald-900 tracking-tight">{m.name} <span className="text-emerald-500/50 font-medium">{m.dose}</span></p>
                      <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Indication</p>
                      <p className="text-sm font-bold text-emerald-800 italic">"{m.indication || 'No indication recorded'}"</p>
                      <p className="text-xs font-bold text-emerald-700/60 leading-relaxed">{m.instructions}</p>
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add New Medication</h4>
                   <input value={newMed.name} onChange={e => setNewMed({ ...newMed, name: e.target.value })} placeholder="Medication Name" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newMed.dose} onChange={e => setNewMed({ ...newMed, dose: e.target.value })} placeholder="Dose (e.g. 5mg)" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input value={newMed.indication} onChange={e => setNewMed({ ...newMed, indication: e.target.value })} placeholder="Indication (e.g. Asthma)" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <button onClick={addMedication} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Add Medication +</button>
                </div>
              </div>
            </section>

            {history.previousMedications?.length > 0 && (
              <section className="space-y-8">
                 <h3 className="text-xl font-black text-slate-400 italic">Ceased Medications</h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {history.previousMedications.map(pm => (
                      <div key={pm.id} className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100 opacity-60">
                        <p className="font-black text-slate-800">{pm.name}</p>
                        <p className="text-[10px] font-bold text-slate-400">Ceased: {pm.ceasedDate}</p>
                        <p className="text-[10px] font-bold text-rose-600 mt-2 italic">Reason: {pm.ceaseReason}</p>
                      </div>
                    ))}
                 </div>
              </section>
            )}
          </div>
        )}

        {activeTab === 'mdt' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Multidisciplinary Team (Care Team)</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.specialists.map(s => (
                  <div key={s.id} className="bg-indigo-50/50 p-10 rounded-[3rem] border border-indigo-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ specialists: history.specialists.filter(x => x.id !== s.id) })} className="absolute top-8 right-8 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <div className="space-y-4">
                       <p className="text-3xl font-black text-indigo-900 tracking-tight">{s.specialty}</p>
                       <p className="text-xl font-black text-indigo-700">{s.name}</p>
                       <div className="flex gap-4">
                          <span className="text-[9px] font-black uppercase text-indigo-400 tracking-widest">Hospital: {s.hospital || 'N/A'}</span>
                       </div>
                       {s.goals && <p className="text-sm font-bold text-indigo-800/60 italic leading-relaxed">"Goals: {s.goals}"</p>}
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add Specialist</h4>
                   <input value={newSpecialist.specialty} onChange={e => setNewSpecialist({ ...newSpecialist, specialty: e.target.value })} placeholder="Specialty (e.g. Neurology)" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newSpecialist.name} onChange={e => setNewSpecialist({ ...newSpecialist, name: e.target.value })} placeholder="Doctor's Name" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input value={newSpecialist.hospital} onChange={e => setNewSpecialist({ ...newSpecialist, hospital: e.target.value })} placeholder="Hospital/Clinic" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <button onClick={addSpecialist} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Add Specialist +</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'diagnostics' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Investigations & Diagnostics</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {(history.investigations || []).map(inv => (
                  <div key={inv.id} className="bg-teal-50/50 p-10 rounded-[3rem] border border-teal-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ investigations: history.investigations?.filter(x => x.id !== inv.id) })} className="absolute top-8 right-8 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <div className="space-y-4">
                       <p className="text-xl font-black text-teal-900 tracking-tight">{inv.name}</p>
                       <p className="text-sm font-bold text-teal-700 italic">Result: {inv.result}</p>
                       <p className="text-[10px] font-black text-teal-400 uppercase">Date: {inv.date}</p>
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add Test Result</h4>
                   <input value={newInvestigation.name} onChange={e => setNewInvestigation({ ...newInvestigation, name: e.target.value })} placeholder="Test Name (e.g. MRI Brain)" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newInvestigation.result} onChange={e => setNewInvestigation({ ...newInvestigation, result: e.target.value })} placeholder="Key Findings/Summary" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input type="date" value={newInvestigation.date} onChange={e => setNewInvestigation({ ...newInvestigation, date: e.target.value })} className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none uppercase" />
                   <button onClick={addInvestigation} className="w-full py-4 bg-teal-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Record Investigation +</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <div className="flex justify-between items-center">
                 <h3 className="text-2xl font-black text-slate-800 italic">Specialist Letters & Reports</h3>
                 <button onClick={() => reportInputRef.current?.click()} disabled={reportLoading} className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl">
