import React, { useState, useRef, useMemo } from 'react';
import { Medication, SpecialistContact, MedicalDevice, MedicalReport, Condition, Investigation, PreviousMedication } from '../types';
import { analyzeMedicalProfile, analyzeMedicalReport } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useRole } from '../context/RoleContext';
import { useNavigation } from '../context/NavigationContext';

export const MedicalProfile: React.FC = () => {
  const { history, updateHistory, pendingEvents } = useMedicalHistory();
  const { activeView } = useNavigation();
  const { role } = useRole();
  const [loading, setLoading] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<{ text: string; sources: any[] } | null>(null);

  const reportInputRef = useRef<HTMLInputElement>(null);

  // Form States
  const [newMed, setNewMed] = useState<Partial<Medication>>({ name: '', dose: '', instructions: '', indication: '' });
  const [newSpecialist, setNewSpecialist] = useState<Partial<SpecialistContact>>({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
  const [newDevice, setNewDevice] = useState<Partial<MedicalDevice>>({ type: '', model: '', size: '', lastChanged: '', nextChangeDue: '' });
  const [newIssue, setNewIssue] = useState<Partial<Condition>>({ name: '', status: 'Active' });
  const [newInvestigation, setNewInvestigation] = useState<Partial<Investigation>>({ name: '', result: '', date: new Date().toISOString().split('T')[0] });

  const handleGenerateHandover = async () => {
    setLoading(true);
    try {
      const result = await analyzeMedicalProfile({ history, linkedEvents: pendingEvents });
      setAiAnalysis(result);
    } catch (e) {
      alert("Error generating handover.");
    } finally {
      setLoading(false);
    }
  };

  const handleClearAllData = () => {
    if (confirm("🚨 CRITICAL: This will delete ALL pediatric records stored locally on this device. This action cannot be undone. Are you sure?")) {
       localStorage.clear();
       window.location.reload();
    }
  };

  const addMedication = () => {
    if (newMed.name) {
      updateHistory({ currentMedications: [...history.currentMedications, { ...newMed, id: crypto.randomUUID(), startDate: new Date().toISOString() } as Medication] });
      setNewMed({ name: '', dose: '', instructions: '', indication: '' });
    }
  };

  const ceaseMedication = (med: Medication) => {
    const reason = prompt(`Reason for ceasing ${med.name}? (e.g., side effects, course finished)`);
    if (reason === null) return;
    const ceased: PreviousMedication = { ...med, ceasedDate: new Date().toISOString().split('T')[0], ceaseReason: reason };
    updateHistory({
      currentMedications: history.currentMedications.filter(m => m.id !== med.id),
      previousMedications: [...(history.previousMedications || []), ceased]
    });
  };

  const addSpecialist = () => {
    if (newSpecialist.name) {
      updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] });
      setNewSpecialist({ name: '', specialty: '', hospital: '', goals: '', nextReview: '' });
    }
  };

  const addDevice = () => {
    if (newDevice.type) {
      updateHistory({ devices: [...history.devices, { ...newDevice, id: crypto.randomUUID() } as MedicalDevice] });
      setNewDevice({ type: '', model: '', size: '', lastChanged: '', nextChangeDue: '' });
    }
  };

  const addInvestigation = () => {
    if (newInvestigation.name) {
      updateHistory({ investigations: [...(history.investigations || []), { ...newInvestigation, id: crypto.randomUUID() } as Investigation] });
      setNewInvestigation({ name: '', result: '', date: new Date().toISOString().split('T')[0] });
    }
  };

  const handleReportUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReportLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        try {
          const result = await analyzeMedicalReport(base64);
          if (result) {
            const newReport: MedicalReport = {
              id: crypto.randomUUID(),
              date: new Date().toLocaleDateString(),
              specialist: result.specialist.name,
              summary: result.summary,
              actionItems: result.actionItems,
              photoUrl: base64
            };
            updateHistory({
              medicalReports: [...(history.medicalReports || []), newReport],
              conditions: [...(history.conditions || []), ...(result.foundDiagnoses || []).map((d: string) => ({ id: crypto.randomUUID(), name: d, status: 'Active', dateDiagnosed: new Date().toLocaleDateString() }))],
              currentMedications: [...(history.currentMedications || []), ...(result.foundMedications || []).map((m: any) => ({ ...m, id: crypto.randomUUID(), startDate: new Date().toISOString() }))]
            });
            alert("Specialist letter integrated.");
          }
        } catch (error) {
          alert("Error analyzing report.");
        } finally {
          setReportLoading(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const currentSection = useMemo(() => {
    switch (activeView) {
      case 'history': return 'history';
      case 'medications': return 'meds';
      case 'careteam': return 'mdt';
      case 'diagnostics': return 'diagnostics';
      case 'reports': return 'reports';
      case 'devices': return 'gear';
      case 'familyhistory': return 'family';
      default: return 'overview';
    }
  }, [activeView]);

  return (
    <div className="space-y-8 pb-24 animate-in fade-in duration-700">
      <header className="flex flex-col lg:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic">
            {currentSection === 'overview' ? 'Medical Hub' : 
             currentSection === 'history' ? 'History & Issues' :
             currentSection === 'meds' ? 'Medications' :
             currentSection === 'mdt' ? 'Care Team' :
             currentSection === 'diagnostics' ? 'Diagnostics' :
             currentSection === 'reports' ? 'Letters & Reports' :
             currentSection === 'gear' ? 'Medical Gear' : 'Family History'}
          </h2>
          <p className="text-slate-500 font-medium italic">High-fidelity longitudinal clinical record.</p>
        </div>
        {currentSection === 'overview' && (
          <button onClick={handleGenerateHandover} disabled={loading} className="bg-indigo-600 text-white px-8 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest shadow-2xl hover:bg-indigo-700">
            {loading ? 'Synthesizing...' : 'Generate AI Handover ✨'}
          </button>
        )}
      </header>

      <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl min-h-[600px] p-8 md:p-12 relative overflow-hidden">

        {currentSection === 'overview' && (
          <div className="space-y-12 flex flex-col items-center justify-center py-20 text-center animate-in zoom-in-95">
             <div className="w-24 h-24 bg-indigo-50 text-indigo-600 rounded-[2rem] flex items-center justify-center text-5xl shadow-inner mb-4">🏥</div>
             <div className="max-w-xl space-y-4">
                <h3 className="text-3xl font-black text-slate-800 italic">Welcome to the Hub</h3>
                <p className="text-slate-500 font-bold leading-relaxed italic text-lg">
                  Navigate using the sidebar to record clinical data. Once complete, return here to generate a comprehensive AI ISBAR Handover for your specialist visit.
                </p>
             </div>
             {aiAnalysis && (
                <div className="w-full text-left mt-10">
                   <div className="bg-slate-900 p-12 rounded-[4rem] text-white shadow-2xl animate-in zoom-in-95 border-l-[24px] border-l-indigo-600 relative overflow-hidden">
                      <div className="absolute top-0 right-0 -mr-20 -mt-20 w-96 h-96 bg-indigo-600 rounded-full opacity-10 blur-[120px]"></div>
                      <div className="flex justify-between items-center mb-10 relative z-10">
                        <h3 className="text-4xl font-black italic tracking-tighter text-indigo-100 uppercase">ISBAR Synthesis</h3>
                        <button onClick={() => setAiAnalysis(null)} className="bg-white/10 hover:bg-white/20 px-6 py-2 rounded-full font-black uppercase text-[10px] tracking-widest">Dismiss</button>
                      </div>
                      <div className="whitespace-pre-wrap text-xl font-bold italic leading-relaxed text-indigo-50 border-l-4 border-white/10 pl-10 relative z-10">{aiAnalysis.text}</div>
                   </div>
                </div>
             )}
          </div>
        )}

        {currentSection === 'history' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-4">
                <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>📜</span> Past Medical History</h3>
                <textarea value={history.pastMedicalHistory} onChange={e => updateHistory({ pastMedicalHistory: e.target.value })} placeholder="Chronic conditions..." className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-indigo-50 shadow-inner resize-none" />
              </div>
              <div className="space-y-4">
                <h3 className="text-xs font-black text-rose-600 uppercase tracking-[0.3em] flex items-center gap-2"><span>✂️</span> Surgical History</h3>
                <textarea value={history.surgicalHistory} onChange={e => updateHistory({ surgicalHistory: e.target.value })} placeholder="Operations..." className="w-full h-48 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-rose-50 shadow-inner resize-none" />
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Active Issues</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {(history.conditions || []).map(issue => (
                  <div key={issue.id} className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ conditions: history.conditions?.filter(x => x.id !== issue.id) })} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <p className="font-black text-slate-800 mb-1">{issue.name}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{issue.status}</p>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-6 rounded-[2rem] flex flex-col gap-2">
                   <input value={newIssue.name} onChange={e => setNewIssue({ ...newIssue, name: e.target.value })} placeholder="Add condition..." className="bg-transparent font-bold text-sm outline-none" />
                   <button onClick={() => { if(newIssue.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newIssue, id: crypto.randomUUID(), status: 'Active' } as Condition] }); setNewIssue({ name: '' }); } }} className="text-[10px] font-black text-indigo-600 uppercase">Add Issue +</button>
                </div>
              </div>
            </section>

            <section className="pt-20 border-t border-slate-100 space-y-6">
