                  <div className="space-y-2 text-center md:text-left">
                     <h4 className="text-xl font-black text-rose-900 italic uppercase">Danger Zone</h4>
                     <p className="text-sm font-bold text-rose-800/60 leading-relaxed italic">Exercise your 'Right to be Forgotten'. This deletes all pediatric logs from local storage.</p>
                  </div>
                  <button onClick={handleClearAllData} className="px-10 py-5 bg-rose-600 text-white rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-rose-700 active:scale-95 transition-all">Clear All Data Permanently</button>
               </div>
            </section>
          </div>
        )}

        {currentSection === 'meds' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Current Medications</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.currentMedications.map(m => (
                  <div key={m.id} className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 relative group shadow-sm">
                    <button onClick={() => ceaseMedication(m)} className="absolute top-8 right-8 bg-white text-rose-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 shadow-sm transition-opacity">Cease Med</button>
                    <div className="space-y-4">
                      <p className="text-3xl font-black text-emerald-900 tracking-tight">{m.name} <span className="text-emerald-500/50 font-medium">{m.dose}</span></p>
