                      <p className="text-sm font-bold text-emerald-800 italic">"{m.indication || 'No indication recorded'}"</p>
                      <p className="text-xs font-bold text-emerald-700/60 leading-relaxed">{m.instructions}</p>
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add New Medication</h4>
                   <input value={newMed.name} onChange={e => setNewMed({ ...newMed, name: e.target.value })} placeholder="Medication Name" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newMed.dose} onChange={e => setNewMed({ ...newMed, dose: e.target.value })} placeholder="Dose (e.g. 5mg)" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input value={newMed.indication} onChange={e => setNewMed({ ...newMed, indication: e.target.value })} placeholder="Indication (e.g. Asthma)" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <button onClick={addMedication} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Add Medication +</button>
                </div>
              </div>
            </section>

            {history.previousMedications?.length > 0 && (
              <section className="space-y-8">
                 <h3 className="text-xl font-black text-slate-400 italic">Ceased Medications</h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {history.previousMedications.map(pm => (
                      <div key={pm.id} className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100 opacity-60">
                        <p className="font-black text-slate-800">{pm.name}</p>
                        <p className="text-[10px] font-bold text-slate-400">Ceased: {pm.ceasedDate}</p>
                        <p className="text-[10px] font-bold text-rose-600 mt-2 italic">Reason: {pm.ceaseReason}</p>
                      </div>
                    ))}
                 </div>
              </section>
            )}
          </div>
        )}

        {currentSection === 'mdt' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Multidisciplinary Team (Care Team)</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.specialists.map(s => (
                  <div key={s.id} className="bg-indigo-50/50 p-10 rounded-[3rem] border border-indigo-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ specialists: history.specialists.filter(x => x.id !== s.id) })} className="absolute top-8 right-8 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <div className="space-y-4">
                       <p className="text-3xl font-black text-indigo-900 tracking-tight">{s.specialty}</p>
                       <p className="text-xl font-black text-indigo-700">{s.name}</p>
                       <div className="flex gap-4">
                          <span className="text-[9px] font-black uppercase text-indigo-400 tracking-widest">Hospital: {s.hospital || 'N/A'}</span>
                       </div>
                       {s.goals && <p className="text-sm font-bold text-indigo-800/60 italic leading-relaxed">"Goals: {s.goals}"</p>}
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add Specialist</h4>
                   <input value={newSpecialist.specialty} onChange={e => setNewSpecialist({ ...newSpecialist, specialty: e.target.value })} placeholder="Specialty (e.g. Neurology)" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newSpecialist.name} onChange={e => setNewSpecialist({ ...newSpecialist, name: e.target.value })} placeholder="Doctor's Name" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input value={newSpecialist.hospital} onChange={e => setNewSpecialist({ ...newSpecialist, hospital: e.target.value })} placeholder="Hospital/Clinic" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <button onClick={addSpecialist} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Add Specialist +</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {currentSection === 'diagnostics' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Investigations & Diagnostics</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {(history.investigations || []).map(inv => (
                  <div key={inv.id} className="bg-teal-50/50 p-10 rounded-[3rem] border border-teal-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ investigations: history.investigations?.filter(x => x.id !== inv.id) })} className="absolute top-8 right-8 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <div className="space-y-4">
                       <p className="text-xl font-black text-teal-900 tracking-tight">{inv.name}</p>
                       <p className="text-sm font-bold text-teal-700 italic">Result: {inv.result}</p>
                       <p className="text-[10px] font-black text-teal-400 uppercase">Date: {inv.date}</p>
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add Test Result</h4>
                   <input value={newInvestigation.name} onChange={e => setNewInvestigation({ ...newInvestigation, name: e.target.value })} placeholder="Test Name (e.g. MRI Brain)" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newInvestigation.result} onChange={e => setNewInvestigation({ ...newInvestigation, result: e.target.value })} placeholder="Key Findings/Summary" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input type="date" value={newInvestigation.date} onChange={e => setNewInvestigation({ ...newInvestigation, date: e.target.value })} className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none uppercase" />
                   <button onClick={addInvestigation} className="w-full py-4 bg-teal-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Record Investigation +</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {currentSection === 'reports' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <div className="flex justify-between items-center">
                 <h3 className="text-2xl font-black text-slate-800 italic">Specialist Letters & Reports</h3>
                 <button onClick={() => reportInputRef.current?.click()} disabled={reportLoading} className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl">
                   {reportLoading ? 'Processing OCR...' : '+ Upload Letter'}
                 </button>
                 <input type="file" ref={reportInputRef} onChange={handleReportUpload} accept="image/*" className="hidden" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {(history.medicalReports || []).map(report => (
                  <div key={report.id} className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 space-y-6 relative group shadow-sm">
                    <button onClick={() => updateHistory({ medicalReports: history.medicalReports?.filter(x => x.id !== report.id) })} className="absolute top-8 right-8 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <div className="flex justify-between">
                       <p className="text-xl font-black text-slate-800">{report.specialist}</p>
                       <p className="text-[10px] font-black text-slate-400 uppercase">{report.date}</p>
                    </div>
                    <p className="text-sm font-bold text-slate-600 italic leading-relaxed">"{report.summary}"</p>
                    <div className="space-y-2">
                       <p className="text-[9px] font-black uppercase text-indigo-600 tracking-widest">Key Actions</p>
                       {report.actionItems.map((item, i) => (
                         <div key={i} className="flex gap-2 text-xs font-bold text-slate-700">
                           <span>•</span> <span>{item}</span>
                         </div>
                       ))}
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {currentSection === 'gear' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-8">
              <h3 className="text-2xl font-black text-slate-800 italic">Medical Devices & Gear</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.devices.map(d => (
                  <div key={d.id} className="bg-amber-50/50 p-10 rounded-[3rem] border border-amber-100 relative group shadow-sm">
                    <button onClick={() => updateHistory({ devices: history.devices.filter(x => x.id !== d.id) })} className="absolute top-8 right-8 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">✕</button>
                    <div className="space-y-4">
                       <p className="text-3xl font-black text-amber-900 tracking-tight">{d.type}</p>
                       <p className="text-xl font-black text-amber-700">{d.model}</p>
                       <div className="flex flex-wrap gap-4">
                          <span className="text-[9px] font-black uppercase text-amber-500">Size: {d.size || 'N/A'}</span>
                          <span className="text-[9px] font-black uppercase text-amber-500">Last Changed: {d.lastChanged || 'N/A'}</span>
                       </div>
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 p-10 rounded-[3rem] space-y-4">
                   <h4 className="font-black text-slate-400 uppercase text-[10px] tracking-widest">Add Device</h4>
                   <input value={newDevice.type} onChange={e => setNewDevice({ ...newDevice, type: e.target.value })} placeholder="Device Type (e.g. NG Tube)" className="w-full bg-transparent border-b border-slate-200 py-2 font-black outline-none" />
                   <input value={newDevice.model} onChange={e => setNewDevice({ ...newDevice, model: e.target.value })} placeholder="Model/Brand" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <input value={newDevice.size} onChange={e => setNewDevice({ ...newDevice, size: e.target.value })} placeholder="Size/Details" className="w-full bg-transparent border-b border-slate-200 py-2 font-bold outline-none" />
                   <button onClick={addDevice} className="w-full py-4 bg-amber-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest">Register Gear +</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {currentSection === 'family' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="grid grid-cols-1 md:grid-cols-2 gap-10">
               {[
                 { id: 'maternal', label: 'Maternal History', color: 'text-pink-600', icon: '🤰' },
                 { id: 'paternal', label: 'Paternal History', color: 'text-blue-600', icon: '🧔' },
                 { id: 'siblings', label: 'Sibling History', color: 'text-indigo-600', icon: '🧒' },
                 { id: 'other', label: 'Extended Family', color: 'text-slate-600', icon: '🌳' }
               ].map(side => (
                <div key={side.id} className="space-y-4">
                  <h3 className={`text-xs font-black ${side.color} uppercase tracking-[0.3em] flex items-center gap-2`}><span>{side.icon}</span> {side.label}</h3>
                  <textarea 
                    value={(history.familyHistory as any)[side.id]} 
                    onChange={e => updateHistory({ familyHistory: { ...history.familyHistory, [side.id]: e.target.value } })} 
                    placeholder="Specific conditions, genetic markers..." 
                    className="w-full h-40 p-8 rounded-[2.5rem] border border-slate-100 bg-slate-50/50 outline-none font-bold italic text-slate-900 focus:ring-4 focus:ring-indigo-50 shadow-inner resize-none" 
                  />
                </div>
               ))}
            </section>
          </div>
        )}
      </div>
    </div>
