import React, { useState } from 'react';
import { ConsultationNote, ClinicalFindings } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { GoogleGenAI } from "@google/genai";

export const ClinicianTools: React.FC<{ type: 'consults' | 'reasoning' }> = ({ type }) => {
  const { history, updateHistory } = useMedicalHistory();
  const [loading, setLoading] = useState(false);
  const [reasoningResult, setReasoningResult] = useState<string | null>(null);

  // SOAP State
  const [newSoap, setNewSoap] = useState<Partial<ConsultationNote>>({
    clinicianName: '', subjective: '', objective: '', assessment: '', plan: ''
  });

  // Reasoning State
  const [findings, setFindings] = useState<ClinicalFindings>({
    history: '', examination: '', vitals: {}
  });

  const handleAddConsult = () => {
    if (!newSoap.assessment || !newSoap.plan) return;
    const consult: ConsultationNote = {
      ...newSoap,
      id: crypto.randomUUID(),
      date: new Date().toISOString()
    } as ConsultationNote;
    updateHistory({ formalConsults: [consult, ...(history.formalConsults || [])] });
    setNewSoap({ clinicianName: '', subjective: '', objective: '', assessment: '', plan: '' });
  };

  const handleRunReasoning = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Act as a senior pediatric clinical advisor. 
      Analyze the following clinical findings and patient baseline to synthesize 3-4 differential diagnoses and primary management priorities.
      Reference standard Australian Pediatric Clinical Practice Guidelines (CPGs).

      PATIENT BASELINE:
      ${history.pastMedicalHistory}
      Current Meds: ${history.currentMedications.map(m => m.name).join(', ')}

      FINDINGS:
      History: ${findings.history}
      Exam: ${findings.examination}
      Vitals: ${JSON.stringify(findings.vitals)}

      OUTPUT FORMAT:
      1. Differential Diagnoses (ranked by likelihood)
      2. Clinical Red Flags to monitor
      3. Immediate Management Steps (CPG-linked)
      4. Required Investigations

      LANGUAGE: Professional Clinician-to-Clinician shorthand.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt
      });
      setReasoningResult(response.text || 'Synthesis failed.');
    } catch (e) {
      alert("Error generating reasoning.");
    } finally {
      setLoading(false);
    }
  };

  if (type === 'consults') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
