                {/* GREEN ZONE */}
                <div className="bg-emerald-500/20 p-8 rounded-[3rem] border border-emerald-400/30 space-y-4 shadow-inner">
                    <div className="flex items-center gap-3">
                    <span className="w-5 h-5 rounded-full bg-emerald-400 animate-pulse shadow-[0_0_15px_rgba(52,211,153,0.8)]"></span>
                    <p className="text-xs font-black uppercase tracking-[0.2em] text-emerald-100">Green Zone: All Well / Maintenance</p>
                    </div>
                    <textarea 
                    value={history.sickDayPlan.greenZone} 
                    onChange={e => updateSickDayField('greenZone', e.target.value)}
                    className="w-full h-24 p-6 rounded-2xl bg-white/10 text-white font-bold text-base italic outline-none border border-white/10 shadow-inner focus:bg-white/20 transition-all"
                    placeholder="Routine actions when child is healthy..."
                    />
                </div>
            </div>

            {/* Background for ED / Responders */}
            <div className="bg-slate-900/50 p-10 rounded-[3.5rem] border border-white/10 space-y-6 shadow-2xl">
                <div className="flex items-center gap-4">
                    <span className="text-3xl">🚑</span>
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-80 text-rose-100">Background for Emergency Staff</p>
                        <p className="text-[9px] font-bold text-rose-100/50 uppercase">Vital Context for Triage Doctors</p>
                    </div>
                </div>
                <textarea 
                value={history.sickDayPlan.backgroundForED} 
                onChange={e => updateSickDayField('backgroundForED', e.target.value)}
                className="w-full h-24 p-6 rounded-2xl bg-white/5 text-white font-bold text-base italic outline-none border border-white/10 shadow-inner focus:bg-white/10 transition-all"
                placeholder="Vital context for doctors who don't know your child (e.g. 'Difficult Airway', 'Metabolic Condition')..."
                />
            </div>

            {/* Standard Fields Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {[
                    { label: 'Emergency Triggers', field: 'triggers', icon: '⚡' },
                    { label: 'Rescue Medication', field: 'emergencyMeds', icon: '💊' },
                    { label: 'Fluid Requirements', field: 'fluidRequirements', icon: '💧' },
                    { label: 'Emergency Contact', field: 'emergencyContact', icon: '📞' }
                ].map((item) => (
                    <div key={item.field} className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10 space-y-3 hover:bg-white/10 transition-colors">
                        <div className="flex items-center gap-2">
                            <span className="text-lg opacity-70">{item.icon}</span>
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">{item.label}</p>
                        </div>
                        <input 
                            className="w-full bg-transparent border-none outline-none font-black text-lg placeholder-white/20 text-white" 
                            placeholder="..."
                            value={(history.sickDayPlan as any)[item.field]} 
                            onChange={e => updateSickDayField(item.field as any, e.target.value)} 
                        />
                    </div>
                ))}
            </div>

            {/* Physical Photo Reference */}
            {history.sickDayPlan.planPhoto && (
                <div className="pt-10 border-t border-white/10 space-y-6">
                <div className="flex justify-between items-center px-4">
                    <div className="flex items-center gap-3">
                        <span className="text-2xl">📸</span>
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-80">Attached Physical Action Plan</p>
                    </div>
                    <button onClick={() => updateSickDayField('planPhoto', '')} className="text-[10px] font-black uppercase text-rose-300 hover:text-white transition-colors">Remove Photo</button>
                </div>
                <div className="p-2 bg-white rounded-[3rem] shadow-2xl border-4 border-rose-400/30 overflow-hidden">
                    <img src={history.sickDayPlan.planPhoto} alt="Physical Plan" className="w-full rounded-[2.5rem] object-cover max-h-[600px]" />
                </div>
                </div>
            )}
        </div>
      </div>

      <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-lg flex items-center gap-8">
        <div className="w-20 h-20 bg-rose-50 text-rose-600 rounded-[2rem] flex items-center justify-center text-4xl shadow-inner border border-rose-100">💡</div>
        <div>
            <h4 className="text-xl font-black text-slate-800 tracking-tight">Parenting Strategy</h4>
            <p className="text-slate-500 font-medium leading-relaxed italic max-w-2xl mt-1">
                "This document is a joint clinical protocol. Ensure it is updated after every specialist review to ensure the rescue triggers match your child's current development."
            </p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ConsultationNote, ClinicalFindings, AssignedTest } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { GoogleGenAI } from "@google/genai";

const SCREENING_MODS = [
  { id: 'snap4', name: 'SNAP-IV (ADHD)', domain: 'Focus' },
  { id: 'mchat', name: 'M-CHAT-R (Autism)', domain: 'Social' },
  { id: 'asq3', name: 'ASQ-3 (Development)', domain: 'Development' },
  { id: 'gad7', name: 'GAD-7 (Anxiety)', domain: 'Mood' },
  { id: 'phq9', name: 'PHQ-9 (Mood/Depression)', domain: 'Mood' },
  { id: 'sdq', name: 'SDQ (Behavior)', domain: 'Behavior' },
];

const REASONING_FRAMEWORKS = [
  { id: 'standard', name: 'Standard Clinical', desc: 'General differential ranking' },
  { id: 'vindicate', name: 'VINDICATE', desc: 'Vascular, Infectious, Neoplastic, Degenerative, etc.' },
  { id: 'vitamins', name: 'VITAMINS', desc: 'Vascular, Infectious, Traumatic, Autoimmune, etc.' },
  { id: 'surgical_sieve', name: 'Surgical Sieve', desc: 'Anatomical vs Pathological mapping' },
];

const CLINICAL_SHORTHAND = {
  general: ['Alert/Active', 'Well Appearance', 'Mildly Unwell', 'NAD', 'Euvolaemic'],
  respiratory: ['Chest Clear', 'Symmetrical Expansion', 'No Wheeze/Stridor', 'Air Entry + Bilat', 'No Distressed Signs'],
  cardiac: ['HS I + II + 0', 'Femoral Pulps + Bilat', 'Cap Refill < 2s', 'Rhythm Regular'],
  abdominal: ['Soft/Non-tender', 'No Masses', 'BS + Active', 'No Guarding'],
  neurological: ['Tone Normal', 'Pupils PERL', 'GCS 15', 'No Focal Deficits'],
  skin: ['No Rashes', 'Warm/Pink', 'Skin Turgor Normal', 'No Petechiae']
};

export const ClinicianTools: React.FC<{ type: 'consults' | 'reasoning' | 'assignments' }> = ({ type }) => {
  const { history, updateHistory } = useMedicalHistory();
  const [loading, setLoading] = useState(false);
  const [reasoningResult, setReasoningResult] = useState<{text: string, sources: any[]} | null>(null);
  const [activeFramework, setActiveFramework] = useState('standard');
  const [activeInputTab, setActiveInputTab] = useState<'history' | 'exam' | 'investigations'>('history');

  const assignedTests = history.assignedTests || [];

  // SOAP State
  const [newSoap, setNewSoap] = useState<Partial<ConsultationNote>>({
    clinicianName: '', subjective: '', objective: '', assessment: '', plan: ''
  });

  // Detailed Reasoning State
  const [findings, setFindings] = useState<{
    history: string;
    exam: {
      general: string;
      respiratory: string;
      cardiac: string;
      abdominal: string;
      neurological: string;
      skin: string;
    };
    investigations: string;
    vitals: { hr?: string; rr?: string; temp?: string; o2?: string; bp?: string; glu?: string };
  }>({
    history: '',
    exam: { general: '', respiratory: '', cardiac: '', abdominal: '', neurological: '', skin: '' },
    investigations: '',
    vitals: {}
  });

  const injectShorthand = (section: keyof typeof findings.exam, term: string) => {
    setFindings(prev => ({
      ...prev,
      exam: {
        ...prev.exam,
        [section]: prev.exam[section] ? `${prev.exam[section]}, ${term}` : term
      }
    }));
  };

  const toggleTestAssignment = (testId: string) => {
    const isAssigned = assignedTests.some(t => t.testId === testId);
    let next: AssignedTest[];
    if (isAssigned) {
      next = assignedTests.filter(t => t.testId !== testId);
    } else {
      next = [...assignedTests, { testId, assignedDate: new Date().toISOString(), status: 'pending' }];
    }
    updateHistory({ assignedTests: next });
  };

  const handleAddConsult = () => {
    if (!newSoap.assessment || !newSoap.plan) return;
    const consult: ConsultationNote = {
      ...newSoap,
      id: crypto.randomUUID(),
      date: new Date().toISOString()
    } as ConsultationNote;
    updateHistory({ formalConsults: [consult, ...(history.formalConsults || [])] });
    setNewSoap({ clinicianName: '', subjective: '', objective: '', assessment: '', plan: '' });
  };

  const handleRunReasoning = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const frameworkInstruction = 
        activeFramework === 'vindicate' ? "Use the VINDICATE acronym (Vascular, Infectious, Neoplastic, Degenerative, Idiopathic, Congenital, Autoimmune, Traumatic, Endocrine) to structure your differential thought process." :
        activeFramework === 'vitamins' ? "Use the VITAMINS mnemonic to explore Vascular, Infectious, Traumatic, Autoimmune, Metabolic, Idiopathic, Neoplastic, and Social causes." :
        activeFramework === 'surgical_sieve' ? "Apply a Surgical Sieve approach, categorizing causes into congenital, traumatic, inflammatory, neoplastic, etc." : 
        "Provide a high-yield prioritized differential list.";

      const prompt = `Act as a senior pediatric consultant. Analyze the following pediatric clinical presentation.

      FRAMEWORK: ${frameworkInstruction}

      PATIENT CONTEXT:
      PMHx: ${history.pastMedicalHistory}
      Current Meds: ${history.currentMedications.map(m => m.name).join(', ')}

      HISTORY: ${findings.history}

      VITALS: HR: ${findings.vitals.hr}, RR: ${findings.vitals.rr}, SpO2: ${findings.vitals.o2}, Temp: ${findings.vitals.temp}, BP: ${findings.vitals.bp}, BSL: ${findings.vitals.glu}

      EXAMINATION:
      - General: ${findings.exam.general}
      - Resp: ${findings.exam.respiratory}
      - CVS: ${findings.exam.cardiac}
      - Abdo: ${findings.exam.abdominal}
      - CNS: ${findings.exam.neurological}
      - Skin: ${findings.exam.skin}

      INVESTIGATIONS (Current/Pending): ${findings.investigations}

      OUTPUT REQUIREMENTS:
      1. Differential Diagnosis Breakdown (using the selected framework)
      2. Red Flags & 'Can't Miss' diagnoses
      3. Immediate Diagnostic & Management Plan
      4. Evidence-Based Rationale: Provide links or citations to relevant research, clinical guidelines (e.g., RCH Melbourne, UpToDate, or Lancet Pediatrics journals). Use the googleSearch tool to find up-to-date EBM links.

      LANGUAGE: Professional, clinical, concise.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
      });

      setReasoningResult({
        text: response.text || 'Synthesis failed.',
        sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
      });
    } catch (e) {
      alert("Error generating reasoning.");
    } finally {
      setLoading(false);
    }
  };

  if (type === 'assignments') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Assignment <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Curate specific assessments for the caregiver to complete before review.</p>
        </header>

        <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">📋</div>
              <div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight">Instrument Selection</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Pre-Appointment Clinical Pack</p>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {SCREENING_MODS.map(test => {
                const assignment = assignedTests.find(t => t.testId === test.id);
                const isAssigned = !!assignment;
                const isCompleted = assignment?.status === 'completed';

                return (
                  <button 
                    key={test.id}
                    onClick={() => toggleTestAssignment(test.id)}
                    className={`p-8 rounded-[3rem] border-2 text-left transition-all relative group flex flex-col justify-between h-48 ${
                      isCompleted ? 'bg-emerald-50 border-emerald-500' :
                      isAssigned ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-105' : 
                      'bg-slate-50 border-slate-100 hover:border-indigo-300 hover:bg-white'
                    }`}
                  >
                    <div>
                      <div className="flex justify-between items-start mb-2">
                        <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full ${isAssigned ? 'bg-white/20' : 'bg-slate-200 text-slate-500'}`}>{test.domain}</span>
                        {isCompleted && <span className="text-emerald-600 text-xs font-black">✓ Done</span>}
                      </div>
                      <h4 className={`text-xl font-black tracking-tight leading-none ${isAssigned && !isCompleted ? 'text-white' : 'text-slate-800'}`}>{test.name}</h4>
                    </div>

                    <div className="flex items-center justify-between mt-4">
                      <span className={`text-[10px] font-black uppercase tracking-widest ${isAssigned && !isCompleted ? 'text-indigo-100' : 'text-slate-400'}`}>
                        {isCompleted ? 'Finished' : isAssigned ? 'Assigned' : 'Click to Assign'}
                      </span>
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-transform group-hover:scale-110 ${isAssigned ? 'bg-white text-indigo-600 shadow-lg' : 'bg-slate-200 text-slate-400'}`}>
                        {isAssigned ? '✓' : '+'}
                      </div>
                    </div>
                  </button>
                );
              })}
           </div>
        </div>
      </div>
    );
  }

  if (type === 'consults') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">SOAP <span className="text-indigo-600">Consultations</span></h2>
          <p className="text-slate-500 font-medium italic">Formal clinical documentation for professional record keeping.</p>
        </header>

        <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Subjective (S)</label>
                <textarea value={newSoap.subjective} onChange={e => setNewSoap({...newSoap, subjective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 font-bold italic text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Patient's report, parent observations..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Objective (O)</label>
                <textarea value={newSoap.objective} onChange={e => setNewSoap({...newSoap, objective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 font-bold italic text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Vitals, physical exam, labs..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Assessment (A)</label>
                <textarea value={newSoap.assessment} onChange={e => setNewSoap({...newSoap, assessment: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-indigo-50/30 border border-indigo-100 font-bold italic text-indigo-900 outline-none focus:ring-4 focus:ring-indigo-100" placeholder="Clinician interpretation, diagnosis..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Plan (P)</label>
                <textarea value={newSoap.plan} onChange={e => setNewSoap({...newSoap, plan: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-emerald-50/30 border border-emerald-100 font-bold italic text-emerald-900 outline-none focus:ring-4 focus:ring-emerald-100" placeholder="Next steps, medications, follow-up..." />
             </div>
          </div>
          <div className="flex justify-between items-center pt-8 border-t border-slate-50">
             <input value={newSoap.clinicianName} onChange={e => setNewSoap({...newSoap, clinicianName: e.target.value})} placeholder="Signing Clinician Name" className="p-4 bg-slate-50 rounded-xl font-black text-xs outline-none" />
             <button onClick={handleAddConsult} className="px-10 py-5 bg-indigo-600 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-700">Record Formal Consult</button>
          </div>
        </section>

        <section className="space-y-6">
           <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Clinical Archive</h3>
           <div className="space-y-6">
              {(history.formalConsults || []).map(note => (
                <div key={note.id} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-6">
                   <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                      <div>
                         <p className="text-xl font-black text-slate-800 italic">Consultation Note</p>
                         <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Clinician: {note.clinicianName}</p>
                      </div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(note.date).toLocaleDateString()}</p>
                   </div>
                   <div className="grid grid-cols-2 gap-8">
                      <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Subjective</p><p className="text-sm font-medium italic text-slate-600">"{note.subjective}"</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Objective</p><p className="text-sm font-medium italic text-slate-600">"{note.objective}"</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-indigo-400 uppercase">Assessment</p><p className="text-sm font-black text-slate-800">{note.assessment}</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-emerald-400 uppercase">Plan</p><p className="text-sm font-black text-slate-800">{note.plan}</p></div>
                   </div>
                </div>
              ))}
           </div>
        </section>
      </div>
    );
  }

  return (
    <div className="space-y-12 pb-24 animate-in fade-in">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Reasoning <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Advanced AI-augmented differential diagnosis assistant.</p>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-200">
           {REASONING_FRAMEWORKS.map(f => (
             <button
              key={f.id}
              onClick={() => setActiveFramework(f.id)}
              className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${activeFramework === f.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400'}`}
             >
               {f.name}
             </button>
           ))}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
         <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8 h-fit">
            <nav className="flex gap-4 border-b border-slate-50 pb-4">
               {['history', 'exam', 'investigations'].map(tab => (
                 <button 
                  key={tab} 
                  onClick={() => setActiveInputTab(tab as any)}
                  className={`text-[10px] font-black uppercase tracking-[0.2em] pb-2 border-b-4 transition-all ${activeInputTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-300'}`}
                 >
                   {tab}
                 </button>
               ))}
            </nav>

            <div className="space-y-6">
               {activeInputTab === 'history' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Clinical History Highlights</label>
                      <textarea value={findings.history} onChange={e => setFindings({...findings, history: e.target.value})} className="w-full h-32 p-5 rounded-2xl bg-slate-50 font-bold italic outline-none border border-slate-100 focus:ring-2 focus:ring-indigo-50" placeholder="Onset, character, associated symptoms, relevant exposures..." />
                    </div>
                    <div className="grid grid-cols-3 gap-4">
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">HR</label>
                        <input placeholder="e.g. 110" value={findings.vitals.hr} onChange={e => setFindings({...findings, vitals: {...findings.vitals, hr: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">RR</label>
                        <input placeholder="e.g. 24" value={findings.vitals.rr} onChange={e => setFindings({...findings, vitals: {...findings.vitals, rr: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">SpO2</label>
                        <input placeholder="e.g. 98%" value={findings.vitals.o2} onChange={e => setFindings({...findings, vitals: {...findings.vitals, o2: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">Temp</label>
                        <input placeholder="e.g. 38.2" value={findings.vitals.temp} onChange={e => setFindings({...findings, vitals: {...findings.vitals, temp: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">BSL / Glu</label>
                        <input placeholder="e.g. 5.1" value={findings.vitals.glu} onChange={e => setFindings({...findings, vitals: {...findings.vitals, glu: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100" />
                      </div>
                    </div>
                 </div>
               )}

               {activeInputTab === 'exam' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4 max-h-[600px] overflow-y-auto pr-2 no-scrollbar">
                    {(Object.keys(CLINICAL_SHORTHAND) as Array<keyof typeof findings.exam>).map(sysKey => (
                      <div key={sysKey} className="space-y-3">
                        {/* Fix: Explicitly wrap sysKey in String() to prevent implicit symbol to string conversion error in label interpolation */}
                        <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block">{String(sysKey)} Systems</label>

                        <div className="flex flex-wrap gap-1.5 mb-2">
                           {CLINICAL_SHORTHAND[sysKey].map(term => (
                             <button 
                              key={term}
                              onClick={() => injectShorthand(sysKey, term)}
                              className="px-3 py-1 bg-slate-50 border border-slate-200 rounded-lg text-[9px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
