                          value={findings.exam[sysKey]} 
                          onChange={e => setFindings({...findings, exam: {...findings.exam, [sysKey]: e.target.value}})} 
                          className="w-full p-4 rounded-xl bg-slate-50 font-bold italic outline-none border border-slate-100 focus:ring-2 focus:ring-indigo-50 text-sm shadow-inner" 
