                    {loading ? 'Synthesizing Pathophysiology...' : 'Run Differential Engine ✨'}
                  </button>
               </div>
            </div>
         </section>

         <section className="h-full">
            {reasoningResult ? (
              <div className="space-y-6 h-full flex flex-col">
                <div className="bg-slate-900 p-12 rounded-[4rem] text-white shadow-2xl animate-in zoom-in-95 border-l-[24px] border-l-indigo-600 relative overflow-hidden flex-1 overflow-y-auto no-scrollbar">
                   <div className="absolute top-0 right-0 -mr-20 -mt-20 w-96 h-96 bg-indigo-600 rounded-full opacity-10 blur-[120px]"></div>
                   <div className="flex justify-between items-center mb-10 relative z-10">
                      <h3 className="text-3xl font-black italic text-indigo-200 uppercase tracking-tighter">AI Clinical Insight</h3>
                      <span className="px-4 py-1.5 bg-white/10 rounded-full text-[8px] font-black uppercase tracking-widest border border-white/10">{activeFramework} MODE</span>
                   </div>

                   <div className="whitespace-pre-wrap text-lg font-bold italic leading-relaxed text-indigo-50 border-l-4 border-white/10 pl-8 mb-12">
                      {reasoningResult.text}
                   </div>

                   {reasoningResult.sources.length > 0 && (
                     <div className="pt-8 border-t border-white/10 space-y-4">
                        <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Relevant Evidence & Guidelines</p>
                        <div className="flex flex-wrap gap-3">
                           {reasoningResult.sources.map((s, i) => (
                             <a key={i} href={s.web?.uri} target="_blank" className="px-4 py-2 bg-white/5 hover:bg-white/10 rounded-xl text-[10px] font-bold text-indigo-200 border border-white/5 transition-colors flex items-center gap-2">
                               <span>🔗</span> {s.web?.title || 'EBM Source'}
                             </a>
                           ))}
                        </div>
                     </div>
                   )}

                   <div className="mt-12 pt-8 border-t border-white/10">
                      <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Professional Notice</p>
                      <p className="text-xs italic opacity-50 mt-2 leading-relaxed">This synthesis is a reasoning aide only, using LLM-augmented grounding. Final diagnosis must be confirmed via standard clinical pathways and face-to-face assessment.</p>
                   </div>
                </div>
              </div>
            ) : (
              <div className="h-full min-h-[600px] border-4 border-dashed border-slate-200 rounded-[4rem] flex flex-col items-center justify-center p-20 opacity-30 text-center grayscale">
                 <span className="text-8xl mb-8">🧠</span>
                 <p className="text-xl font-black uppercase tracking-widest">Bench Ready</p>
                 <p className="text-sm font-medium italic mt-2">Input history, exam systems, and tests to run clinical synthesis.</p>
              </div>
            )}
         </section>
      </div>
    </div>
  );
};

