                    className="flex-1 p-5 rounded-2xl bg-white font-black text-slate-900 outline-none border-none shadow-xl placeholder-slate-400"
                    onKeyPress={e => e.key === 'Enter' && handleExplainTerm()}
                   />
                   <button 
