import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useRole } from '../context/RoleContext';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, Area, ComposedChart, Line
} from 'recharts';

const icons = { 
  Fluid: '🥤', 
  Temperature: '🌡️', 
  Output: '🚽', 
  Medication: '💊', 
  Vomit: '🤮', 
  Triage: '✨', 
  Vitals: '🩺', 
  'Physical Exam': '👨‍⚕️' 
};

// CEWT Scoring Constants (Generic Pediatric Baseline - 1-4 years approx)
const getCEWTScore = (type: string, val: any, effort?: string): number => {
  if (type === 'RR') {
    const n = parseInt(val);
    if (!n) return 0;
    if (n < 15 || n > 50) return 3;
    if (n > 40) return 2;
    if (n > 30) return 1;
    return 0;
  }
  if (type === 'HR') {
    const n = parseInt(val);
    if (!n) return 0;
    if (n < 70 || n > 170) return 3;
    if (n > 150) return 2;
    if (n > 130) return 1;
    return 0;
  }
  if (type === 'SpO2') {
    const n = parseInt(val);
    if (!n) return 0;
    if (n < 90) return 3;
    if (n < 94) return 2;
    if (n < 95) return 1;
    return 0;
  }
  if (type === 'Effort') {
    if (effort === 'Severe') return 3;
    if (effort === 'Moderate') return 2;
    if (effort === 'Mild') return 1;
    return 0;
  }
  return 0;
};

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, updateHistory } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { role } = useRole();

  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');

  // CEWT Form State
  const [obs, setObs] = useState({
    rr: '', hr: '', spo2: '', temp: '', cbt: 'Normal', effort: 'None', avpu: 'A'
  });

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: 500,
    intervalVolume: 5,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  const isNeonate = useMemo(() => {
    if (!childProfile?.dob) return false;
    const birth = new Date(childProfile.dob);
    const diff = Date.now() - birth.getTime();
    return (diff / (1000 * 60 * 60 * 24 * 30.44)) < 3;
  }, [childProfile]);

  const cewtResult = useMemo(() => {
    const score = 
      getCEWTScore('RR', obs.rr) + 
      getCEWTScore('HR', obs.hr) + 
      getCEWTScore('SpO2', obs.spo2) + 
      getCEWTScore('Effort', null, obs.effort);

    return {
      score,
      level: score >= 8 ? 'CRITICAL' : score >= 5 ? 'URGENT' : score >= 2 ? 'WATCH' : 'STABLE',
      color: score >= 8 ? 'bg-rose-600' : score >= 5 ? 'bg-orange-500' : (score >= 2 ? 'bg-amber-500' : 'bg-emerald-600')
    };
  }, [obs]);

  const ioBalance = useMemo(() => {
    const logs = history.acuteLogs || [];
    const last24h = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const recent = logs.filter(l => new Date(l.timestamp) > last24h);

    const input = recent.filter(l => l.type === 'Fluid').reduce((acc, curr) => acc + (parseInt(curr.value) || 0), 0);
    const output = recent.filter(l => l.type === 'Output' || l.type === 'Vomit').reduce((acc, curr) => acc + (parseInt(curr.value) || 0), 0);

    return { input, output, balance: input - output };
  }, [history.acuteLogs]);

  // Unified Data Processing for Analytics
  const trendData = useMemo(() => {
    const logs = [...(history.acuteLogs || [])].reverse();
    let cumulativeBalance = 0;

    return logs.map(log => {
      if (log.type === 'Fluid') cumulativeBalance += (parseInt(log.value) || 0);
      if (log.type === 'Output' || log.type === 'Vomit') cumulativeBalance -= (parseInt(log.value) || 0);

      let hr, rr, temp, spo2;
      if (log.type === 'Vitals') {
        const hrMatch = log.value.match(/HR:\s*(\d+)/);
        const rrMatch = log.value.match(/RR:\s*(\d+)/);
        const o2Match = log.value.match(/O2:\s*(\d+)/);
        const tMatch = log.value.match(/T:\s*([\d.]+)/);
        if (hrMatch) hr = parseInt(hrMatch[1]);
        if (rrMatch) rr = parseInt(rrMatch[1]);
        if (o2Match) spo2 = parseInt(o2Match[1]);
        if (tMatch) temp = parseFloat(tMatch[1]);
      } else if (log.type === 'Temperature') {
        temp = parseFloat(log.value);
      }

      return {
        time: log.timestamp,
        temp,
        hr,
        rr,
        spo2,
        balance: cumulativeBalance,
      };
    });
  }, [history.acuteLogs]);

  const handleAddObs = () => {
    const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const summary = `CEWT: ${cewtResult.score} | HR: ${obs.hr}, RR: ${obs.rr}, O2: ${obs.spo2}%, T: ${obs.temp}°`;
