                      <Line yAxisId="temp" type="monotone" dataKey="temp" stroke="#e11d48" strokeWidth={4} dot={{ r: 6, fill: '#e11d48', stroke: '#fff', strokeWidth: 2 }} name="Temperature" connectNulls />
