import React, { useState } from 'react';
import { ChildProfile, Medication } from '../types';
import { useChildProfile } from '../context/ChildProfileContext';
import { useNavigation } from '../context/NavigationContext';

export const ChildProfileSetup: React.FC = () => {
  const { childProfile, setChildProfile } = useChildProfile();
  const { navigateTo } = useNavigation();
  const [isSaving, setIsSaving] = useState(false);

  // Child Info
  const [name, setName] = useState(childProfile?.name || '');
  const [dob, setDob] = useState(childProfile?.dob || '');
  const [sex, setSex] = useState<ChildProfile['sex']>(childProfile?.sex || 'Male');
  const [weight, setWeight] = useState(childProfile?.weight?.toString() || '');
  const [height, setHeight] = useState(childProfile?.height?.toString() || '');
  const [medHistory, setMedHistory] = useState(childProfile?.pastMedicalHistory || '');

  // Account Info
  const [email, setEmail] = useState(childProfile?.email || '');
  const [password, setPassword] = useState(childProfile?.password || '');
  const [stayLoggedIn, setStayLoggedIn] = useState(childProfile?.stayLoggedIn ?? true);
  const [agreedToTerms, setAgreedToTerms] = useState(!!childProfile);

  const [meds] = useState<Medication[]>(childProfile?.medications || []);
  const [allergies] = useState<string[]>(childProfile?.allergies || []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!name || !dob || !email) {
      alert("Please complete the required fields (Name, DOB, and Email).");
      return;
    }

    const weightNum = parseFloat(weight);
    if (weight && (weightNum < 2 || weightNum > 150)) {
       alert("Please enter a realistic pediatric weight (2 kg to 150 kg).");
       return;
    }

    if (new Date(dob) > new Date()) {
       alert("Date of Birth cannot be in the future.");
       return;
    }

    if (!agreedToTerms) {
      alert("Please agree to the clinical safety terms before proceeding.");
      return;
    }

    setIsSaving(true);

    // Simulate a brief persistence lag for UX feedback
    setTimeout(() => {
      setChildProfile({
        name,
        dob,
        sex,
        weight: weight ? parseFloat(weight) : undefined,
        height: height ? parseFloat(height) : undefined,
        pastMedicalHistory: medHistory,
        medications: meds,
        previousMedications: childProfile?.previousMedications || [],
        allergies: allergies,
        email,
        password,
        stayLoggedIn
      });
      navigateTo('dashboard');
      setIsSaving(false);
    }, 600);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-10 duration-700 pb-20">
      <header className="text-center space-y-4">
        <div className="w-24 h-24 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-6 shadow-2xl rotate-3">🩺</div>
        <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">
          {childProfile ? 'Account Settings' : 'Clinical Onboarding'}
        </h2>
        <p className="text-slate-500 font-medium italic">Initialize your child's local clinical record.</p>
      </header>

      <form onSubmit={handleSubmit} className="space-y-10">
        <section className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
          <div className="flex items-center gap-3 border-b border-slate-50 pb-6">
            <span className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-lg shadow-inner">🆔</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Core Patient Identity</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Legal Full Name</label>
              <input type="text" required value={name} onChange={(e) => setName(e.target.value)} placeholder="Full Name" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg transition-all" />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Date of Birth</label>
              <input type="date" required max={new Date().toISOString().split('T')[0]} value={dob} onChange={(e) => setDob(e.target.value)} className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg uppercase transition-all" />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Current Weight (kg)</label>
              <div className="relative">
                <input type="number" step="0.1" min="2" max="150" value={weight} onChange={(e) => setWeight(e.target.value)} placeholder="e.g. 12.5" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg transition-all" />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300 uppercase tracking-widest">KG</span>
              </div>
            </div>
            <div className="space-y-2">
               <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Account Email</label>
               <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="parent@example.com" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg transition-all" />
            </div>
          </div>
        </section>

        {!childProfile && (
          <section className="bg-indigo-50 p-10 rounded-[3rem] border border-indigo-100 space-y-6">
            <h4 className="text-sm font-black text-indigo-900 uppercase tracking-widest">Clinical Governance & Privacy</h4>
            <label className="flex items-start gap-4 cursor-pointer group">
              <div className="relative pt-1">
                <input 
                  type="checkbox" 
                  checked={agreedToTerms} 
                  onChange={e => setAgreedToTerms(e.target.checked)}
                  className="w-8 h-8 rounded-xl border-2 border-indigo-200 text-indigo-600 focus:ring-indigo-500 transition-all cursor-pointer"
                />
              </div>
              <div className="space-y-1">
                <p className="text-sm font-black text-indigo-950 italic leading-snug group-hover:text-indigo-600 transition-colors">
                  "I understand PediPulse AI is a decision-support tool and not a medical device. I agree to the local data storage policy and clinical safety guardrails."
                </p>
                <p className="text-[10px] font-bold text-indigo-400 leading-relaxed italic">
                  By checking this box, you confirm that you will seek immediate medical care for any urgent or life-threatening symptoms.
                </p>
              </div>
            </label>
          </section>
        )}

        <div className="flex flex-col sm:flex-row gap-4 pt-4">
          <button 
            type="button" 
            onClick={() => navigateTo('dashboard')} 
            className="flex-1 py-6 bg-slate-100 text-slate-500 font-black rounded-[2rem] hover:bg-slate-200 transition-all text-sm uppercase tracking-widest"
          >
            Cancel
          </button>
          <button 
            type="submit" 
            disabled={isSaving}
            className={`flex-[2] py-6 text-white font-black rounded-[2rem] shadow-2xl transition-all transform active:scale-95 text-sm uppercase tracking-[0.2em] flex items-center justify-center gap-3 ${isSaving ? 'bg-indigo-400' : 'bg-indigo-600 hover:bg-indigo-700'}`}
          >
            {isSaving ? (
              <>
                <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                Saving Record...
              </>
            ) : (
              <>{childProfile ? 'Sync Changes' : 'Initialize Local Hub ✨'}</>
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

