               <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="parent@example.com" className="w-full p-5 rounded-2xl border border-slate-100 bg-slate-50/50 focus:ring-2 focus:ring-indigo-500 outline-none font-black text-slate-900 text-lg transition-all" />
            </div>
          </div>
        </section>

        {!childProfile && (
          <section className="bg-indigo-50 p-10 rounded-[3rem] border border-indigo-100 space-y-6">
            <h4 className="text-sm font-black text-indigo-900 uppercase tracking-widest">Clinical Terms & Sovereignty</h4>
            <label className="flex items-start gap-4 cursor-pointer group">
              <div className="relative pt-1">
                <input 
                  type="checkbox" 
                  checked={agreedToTerms} 
                  onChange={e => setAgreedToTerms(e.target.checked)}
                  className="w-8 h-8 rounded-xl border-2 border-indigo-200 text-indigo-600 focus:ring-indigo-500 transition-all cursor-pointer"
                />
              </div>
              <div className="space-y-1">
                <p className="text-sm font-black text-indigo-950 italic leading-snug group-hover:text-indigo-600 transition-colors">
                  "I understand PediPulse is a decision-support tool. All clinical data remains local to this device. I agree to seek professional care for all urgent concerns."
                </p>
                <p className="text-[10px] font-bold text-indigo-400 italic">
                  Confirmation required to initialize your local pediatric record.
                </p>
              </div>
            </label>
          </section>
        )}

        <div className="space-y-4">
          <button 
            type="submit" 
            disabled={isSaving || validationErrors.length > 0}
            className={`w-full py-7 text-white font-black rounded-[2.5rem] shadow-2xl transition-all transform active:scale-95 text-base uppercase tracking-[0.2em] flex items-center justify-center gap-3 ${
              isSuccess ? 'bg-emerald-500' :
              (validationErrors.length > 0 ? 'bg-slate-200 cursor-not-allowed text-slate-400 shadow-none' : 'bg-indigo-600 hover:bg-indigo-700')
            }`}
          >
            {isSuccess ? (
              <>
                <span className="text-2xl animate-bounce">✓</span>
                Initialization Complete!
              </>
            ) : isSaving ? (
              <>
                <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                Securing Local Database...
              </>
            ) : (
              <>{childProfile ? 'Update Health Baseline' : 'Initialize Local Hub ✨'}</>
            )}
          </button>

          {validationErrors.length > 0 && (
            <p className="text-center text-[10px] font-black text-slate-400 uppercase tracking-widest animate-pulse">
              Please complete all required fields and accept terms to proceed.
            </p>
          )}
        </div>
      </form>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useRole } from '../context/RoleContext';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, Area, ComposedChart, Line
} from 'recharts';

const icons = { 
  Fluid: '🥤', 
  Temperature: '🌡️', 
  Output: '🚽', 
  Medication: '💊', 
  Vomit: '🤮', 
  Triage: '✨', 
  Vitals: '🩺', 
  'Physical Exam': '👨‍⚕️' 
};

// CEWT Scoring Constants (Generic Pediatric Baseline - 1-4 years approx)
const getCEWTScore = (type: string, val: any, effort?: string): number => {
  if (type === 'RR') {
    const n = parseInt(val);
    if (!n) return 0;
    if (n < 15 || n > 50) return 3;
    if (n > 40) return 2;
    if (n > 30) return 1;
    return 0;
  }
  if (type === 'HR') {
    const n = parseInt(val);
    if (!n) return 0;
    if (n < 70 || n > 170) return 3;
    if (n > 150) return 2;
    if (n > 130) return 1;
    return 0;
  }
  if (type === 'SpO2') {
    const n = parseInt(val);
    if (!n) return 0;
    if (n < 90) return 3;
    if (n < 94) return 2;
    if (n < 95) return 1;
    return 0;
  }
  if (type === 'Effort') {
    if (effort === 'Severe') return 3;
    if (effort === 'Moderate') return 2;
    if (effort === 'Mild') return 1;
    return 0;
  }
  return 0;
};

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, updateHistory, latestWeight } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { role } = useRole();

  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');

  // CEWT Form State
  const [obs, setObs] = useState({
    rr: '', hr: '', spo2: '', temp: '', cbt: 'Normal', effort: 'None', avpu: 'A'
  });

  // Fluid Challenge Logic (RCH/QCH Alignment)
  const suggestedTargets = useMemo(() => {
    const weight = latestWeight || childProfile?.weight || 0;
    if (weight === 0) return { targetVolume: 200, intervalVolume: 5, intervalMinutes: 5 };

    // RCH Standard: 10ml/kg per hour for fluid challenge (mild/mod dehydration)
    const hourlyTarget = Math.round(weight * 10);
    // Suggest 5-minute intervals (Standard ED Protocol)
    const intervalVolume = weight < 10 ? 2 : 5; 

    return {
      targetVolume: hourlyTarget,
      intervalVolume,
      intervalMinutes: 5
    };
  }, [latestWeight, childProfile?.weight]);

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: suggestedTargets.targetVolume,
    intervalVolume: suggestedTargets.intervalVolume,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  // Keep challenge targets synced with weight updates if not already active
  useEffect(() => {
    if (!challenge.isActive) {
      setChallenge(prev => ({
        ...prev,
        targetVolume: suggestedTargets.targetVolume,
        intervalVolume: suggestedTargets.intervalVolume
      }));
    }
  }, [suggestedTargets, challenge.isActive]);

  const isNeonate = useMemo(() => {
    if (!childProfile?.dob) return false;
    const birth = new Date(childProfile.dob);
    const diff = Date.now() - birth.getTime();
    const months = (diff / (1000 * 60 * 60 * 24 * 30.44));
    return months < 3;
  }, [childProfile]);

  const cewtResult = useMemo(() => {
    const score = 
      getCEWTScore('RR', obs.rr) + 
      getCEWTScore('HR', obs.hr) + 
      getCEWTScore('SpO2', obs.spo2) + 
      getCEWTScore('Effort', null, obs.effort);

    return {
      score,
      level: score >= 8 ? 'CRITICAL' : (score >= 5 ? 'URGENT' : (score >= 2 ? 'WATCH' : 'STABLE')),
      color: score >= 8 ? 'bg-rose-600' : (score >= 5 ? 'bg-orange-500' : (score >= 2 ? 'bg-amber-500' : 'bg-emerald-600'))
    };
  }, [obs]);

  const ioBalance = useMemo(() => {
    const logs = history.acuteLogs || [];
    const last24h = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const recent = logs.filter(l => new Date(l.timestamp) > last24h);

    const input = recent.filter(l => l.type === 'Fluid').reduce((acc, curr) => acc + (parseInt(curr.value) || 0), 0);
    const output = recent.filter(l => l.type === 'Output' || l.type === 'Vomit').reduce((acc, curr) => acc + (parseInt(curr.value) || 0), 0);

    return { input, output, balance: input - output };
  }, [history.acuteLogs]);

  const trendData = useMemo(() => {
    const logs = [...(history.acuteLogs || [])].reverse();
    let cumulativeBalance = 0;

    return logs.map(log => {
      if (log.type === 'Fluid') cumulativeBalance += (parseInt(log.value) || 0);
      if (log.type === 'Output' || log.type === 'Vomit') cumulativeBalance -= (parseInt(log.value) || 0);

      let hr, rr, temp, spo2;
      if (log.type === 'Vitals') {
        const hrMatch = log.value.match(/HR:\s*(\d+)/);
        const rrMatch = log.value.match(/RR:\s*(\d+)/);
        const o2Match = log.value.match(/O2:\s*(\d+)/);
        const tMatch = log.value.match(/T:\s*([\d.]+)/);
        if (hrMatch) hr = parseInt(hrMatch[1]);
        if (rrMatch) rr = parseInt(rrMatch[1]);
        if (o2Match) spo2 = parseInt(o2Match[1]);
        if (tMatch) temp = parseFloat(tMatch[1]);
      } else if (log.type === 'Temperature') {
        temp = parseFloat(log.value);
      }

      return {
        time: log.timestamp,
        temp,
        hr,
        rr,
        spo2,
        balance: cumulativeBalance
      };
    });
  }, [history.acuteLogs]);

  const latestTemp = useMemo(() => {
    if (!history.acuteLogs || history.acuteLogs.length === 0) return 0;
    const tempLogs = history.acuteLogs.filter(l => {
      if (l.type === 'Temperature') return true;
      if (l.type === 'Vitals' && l.value.includes('T:')) return true;
      return false;
    });
    if (tempLogs.length === 0) return 0;
    const latest = tempLogs[0];
    if (latest.type === 'Temperature') return parseFloat(latest.value);
    const tMatch = latest.value.match(/T:\s*([\d.]+)/);
    return tMatch ? parseFloat(tMatch[1]) : 0;
  }, [history.acuteLogs]);

  const activeNeonateFever = useMemo(() => {
    if (!isNeonate) return false;
    if (type === 'Temperature' && parseFloat(value) >= 38) return true;
    if (role === 'clinician' && parseFloat(obs.temp) >= 38) return true;
    return latestTemp >= 38;
  }, [isNeonate, latestTemp, value, type, obs.temp, role]);

  const handleAddObs = () => {
    const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const summary = `CEWT: ${cewtResult.score} | HR: ${obs.hr}, RR: ${obs.rr}, O2: ${obs.spo2}%, T: ${obs.temp} degree Celsius`;
    addAcuteLog({
      timestamp,
      type: 'Vitals',
      value: summary,
      notes: `Effort: ${obs.effort}, AVPU: ${obs.avpu}. Clinical review level: ${cewtResult.level}`,
      clinicianLogged: true
    });
    setObs({ rr: '', hr: '', spo2: '', temp: '', cbt: 'Normal', effort: 'None', avpu: 'A' });
  };

  const handleAdd = () => {
    if (!value) return;
    const valInt = parseInt(value) || 0;
    addAcuteLog({
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type,
      value: type === 'Temperature' ? `${value} degree Celsius` : value,
      notes,
      clinicianLogged: role === 'clinician'
    });

    // Update active challenge total
    if (challenge.isActive && type === 'Fluid') {
      setChallenge(prev => ({ ...prev, totalConsumed: prev.totalConsumed + valInt }));
    } else if (challenge.isActive && type === 'Vomit') {
      setChallenge(prev => ({ ...prev, vomitCount: prev.vomitCount + 1 }));
    }

    setValue('');
    setNotes('');
  };

  const deleteEntry = (id: string) => {
    if (confirm("Delete this entry?")) {
      updateHistory({ acuteLogs: (history.acuteLogs || []).filter(l => l.id !== id) });
    }
  };

  const NeonateAlertBanner = () => {
    if (!activeNeonateFever) return null;
    return (
      <div className="bg-rose-600 p-8 rounded-[2.5rem] text-white shadow-2xl animate-pulse mb-8 border-4 border-rose-400">
        <div className="flex items-center gap-6">
          <span className="text-5xl">🚨</span>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-[0.2em]">URGENT REVIEW REQUIRED</h2>
            <p className="text-base font-bold mt-2 leading-relaxed italic">
              Fever of 38.0 degree Celsius or higher in an infant under 3 months is a clinical emergency. 
              Present to the nearest Emergency Department immediately or call 000.
            </p>
          </div>
        </div>
      </div>
    );
  };

  // Professional Clinician Interface
  if (role === 'clinician') {
    return (
      <div className="space-y-10 pb-20 animate-in fade-in duration-500">
        <NeonateAlertBanner />

        <header className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-6">
           <div>
              <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Acuity <span className="text-indigo-600">Workstation</span></h2>
              <p className="text-slate-500 font-medium italic">High-fidelity observation trends and CEWT monitoring.</p>
           </div>
           <div className="flex gap-4">
              <div className="bg-white px-6 py-3 rounded-2xl border border-slate-100 shadow-sm text-center">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Net Balance (24h)</p>
                  <p className={`text-xl font-black ${ioBalance.balance < 0 ? 'text-rose-600' : 'text-teal-600'}`}>{ioBalance.balance} ml</p>
              </div>
              {challenge.isActive && (
                <div className="bg-teal-600 px-6 py-3 rounded-2xl text-white shadow-xl text-center">
                  <p className="text-[9px] font-black uppercase opacity-70">Challenge Progress</p>
                  <p className="text-xl font-black">{challenge.totalConsumed} / {challenge.targetVolume} ml</p>
                </div>
              )}
           </div>
        </header>

        {/* GUIDELINE FLUID CHALLENGE - CLINICIAN VIEW */}
        <section className={`bg-white p-10 rounded-[3.5rem] border shadow-xl space-y-8 transition-all ${challenge.isActive ? 'border-teal-500 ring-4 ring-teal-50' : 'border-slate-100'}`}>
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-3xl shadow-inner ${challenge.isActive ? 'bg-teal-50 text-teal-600' : 'bg-slate-50 text-slate-400'}`}>💧</div>
              <div>
                <h3 className="text-2xl font-black italic tracking-tight">Standardized Fluid Challenge</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Aligned with RCH Melbourne / QCH Guideline (10ml/kg/hr)</p>
              </div>
            </div>
            {!challenge.isActive ? (
               <button 
                onClick={() => setChallenge(prev => ({ ...prev, isActive: true, startTime: new Date().toLocaleTimeString() }))}
                className="bg-teal-600 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-teal-700 transition-all"
               >
                Initiate Protocol
               </button>
            ) : (
               <button 
                onClick={() => setChallenge(prev => ({ ...prev, isActive: false }))}
                className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl"
               >
                Deactivate Challenge
               </button>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Hourly Target Volume</label>
              <div className="relative">
                <input 
                  type="number"
                  value={challenge.targetVolume}
                  onChange={e => setChallenge({...challenge, targetVolume: parseInt(e.target.value) || 0})}
                  className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-lg"
                />
                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300">ML / HR</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Suggested Syringe Dose</label>
              <div className="relative">
                <input 
                  type="number"
                  value={challenge.intervalVolume}
                  onChange={e => setChallenge({...challenge, intervalVolume: parseInt(e.target.value) || 0})}
                  className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-lg"
                />
                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300">ML</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Administration Interval</label>
              <div className="relative">
                <input 
                  type="number"
                  value={challenge.intervalMinutes}
                  onChange={e => setChallenge({...challenge, intervalMinutes: parseInt(e.target.value) || 0})}
                  className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-lg"
                />
                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300">MINUTES</span>
              </div>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <section className="lg:col-span-8 bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-2xl space-y-10 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl"></div>
              <div className="flex items-center justify-between relative z-10">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner">🩺</div>
                    <div>
                       <h3 className="text-2xl font-black italic tracking-tight">Vitals Entry</h3>
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Standardized Clinical Dataset</p>
                    </div>
                 </div>
                 <div className={`${cewtResult.color} px-8 py-3 rounded-2xl text-white shadow-xl`}>
                    <p className="text-[9px] font-black uppercase tracking-[0.2em] opacity-80">CEWT Status</p>
                    <p className="text-2xl font-black">{cewtResult.score} — {cewtResult.level}</p>
                 </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-6 relative z-10">
                 {[
                    { label: 'Resp Rate', field: 'rr', unit: 'bpm', placeholder: '24' },
                    { label: 'Heart Rate', field: 'hr', unit: 'bpm', placeholder: '110' },
                    { label: 'SpO2', field: 'spo2', unit: '%', placeholder: '98' },
                    { label: 'Temp', field: 'temp', unit: '°C', placeholder: '37.0' }
                 ].map(f => (
                   <div key={f.field} className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">{f.label}</label>
                      <div className="relative">
                         <input 
                            value={(obs as any)[f.field]}
                            onChange={e => setObs({...obs, [f.field]: e.target.value})}
                            className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-lg outline-none focus:ring-4 focus:ring-indigo-50"
                         />
                         <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] font-black text-slate-300 uppercase">{f.unit}</span>
                      </div>
                   </div>
                 ))}
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Resp Effort</label>
                    <select value={obs.effort} onChange={e => setObs({...obs, effort: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-xs outline-none">
                       <option>None</option><option>Mild</option><option>Moderate</option><option>Severe</option>
                    </select>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">AVPU</label>
                    <select value={obs.avpu} onChange={e => setObs({...obs, avpu: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-black text-xs outline-none">
                       <option value="A">Alert</option><option value="V">Voice</option><option value="P">Pain</option><option value="U">Unresponsive</option>
                    </select>
                 </div>
              </div>
              <button onClick={handleAddObs} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all">Record Observation & Chart ✨</button>
           </section>

           <section className="lg:col-span-4 bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
              <h3 className="text-xl font-black text-slate-800 italic">I/O Balance</h3>
              <div className="space-y-4">
                 <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 shadow-inner">
                    {['Fluid', 'Output', 'Vomit'].map(t => (
                       <button key={t} onClick={() => setType(t as any)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${type === t ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400'}`}>{t}</button>
                    ))}
                 </div>
                 <div className="relative">
                    <input value={value} onChange={e => setValue(e.target.value)} placeholder="Amount (ml)..." className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 font-black text-lg" />
                    <span className="absolute right-5 top-1/2 -translate-y-1/2 text-xs font-black text-slate-300">ML</span>
                 </div>
                 <button onClick={handleAdd} className="w-full py-4 bg-teal-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg">Log Volume</button>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="p-4 bg-teal-50 rounded-2xl text-center"><p className="text-[9px] font-black text-teal-600">IN</p><p className="text-xl font-black">{ioBalance.input}ml</p></div>
                 <div className="p-4 bg-rose-50 rounded-2xl text-center"><p className="text-[9px] font-black text-rose-600">OUT</p><p className="text-xl font-black">{ioBalance.output}ml</p></div>
              </div>
           </section>
        </div>

        {/* CLINICIAN VITALS CHART */}
        <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-2xl space-y-8">
           <div className="flex justify-between items-center px-4">
              <h3 className="text-2xl font-black text-slate-800 italic tracking-tight">Observation Chart (Hospital Style)</h3>
              <div className="flex gap-4">
                <span className="flex items-center gap-2"><span className="w-3 h-3 bg-red-500 rounded-full"></span><span className="text-[9px] font-black">TEMP</span></span>
                <span className="flex items-center gap-2"><span className="w-3 h-3 bg-blue-500 rounded-full"></span><span className="text-[9px] font-black">HR</span></span>
                <span className="flex items-center gap-2"><span className="w-3 h-3 bg-green-500 rounded-full"></span><span className="text-[9px] font-black">RR</span></span>
              </div>
           </div>
           <div className="h-[500px] w-full bg-slate-50/50 p-6 rounded-[3rem] border border-slate-100">
              <ResponsiveContainer width="100%" height="100%">
                 <ComposedChart data={trendData}>
                    <CartesianGrid strokeDasharray="1 1" stroke="#e2e8f0" vertical={true} />
                    <XAxis dataKey="time" tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 900 }} />
                    <YAxis yAxisId="temp" domain={[35, 41]} tick={{ fill: '#e11d48', fontSize: 10, fontWeight: 900 }} label={{ value: '°C', angle: -90, position: 'insideLeft' }} />
                    <YAxis yAxisId="vitals" orientation="right" domain={[0, 200]} tick={{ fill: '#64748b', fontSize: 10, fontWeight: 900 }} label={{ value: 'HR/RR', angle: 90, position: 'insideRight' }} />
