        <section className="bg-white p-10 rounded-[4rem] border-2 border-slate-200 shadow-sm overflow-hidden">
           <h3 className="text-2xl font-black text-slate-800 italic mb-8">Clinical Archive</h3>
           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead className="text-[11px] font-black text-slate-600 uppercase tracking-widest border-b-2 border-slate-100">
                    <tr><th className="pb-4 px-6">Timestamp</th><th className="pb-4 px-6">Event</th><th className="pb-4 px-6">Observation</th><th className="pb-4 px-6">Notes</th><th className="pb-4 px-6 text-right">Actions</th></tr>
                 </thead>
                 <tbody className="divide-y-2 divide-slate-50">
                    {history.acuteLogs?.map(entry => (
