import React, { useState, useRef, useMemo } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useConnectivity } from '../hooks/useConnectivity';
import { useGovernance } from '../context/GovernanceContext';
import { useEnvironment } from '../context/EnvironmentContext';
import { useRole } from '../context/RoleContext';
import { evaluateRedFlags } from '../clinical/redFlags';
import { evaluateIMCIRedFlags } from '../clinical/redFlagsIMCI';

const RED_FLAGS_LIST = [
  { text: "Difficulty Breathing", sub: "Grunting, wheezing, or chest sucking in", icon: "🫁" },
  { text: "Infant Fever", sub: "Any fever in a baby under 3 months old", icon: "🌡️" },
  { text: "Altered Level of Consciousness", sub: "Unusually sleepy, floppy, or unresponsive", icon: "😴" },
  { text: "Non-Blanching Rash", sub: "Purple/red spots that don't fade when pressed", icon: "🟣" },
  { text: "Severe Pain", sub: "Inconsolable crying or extreme localized pain", icon: "😫" },
  { text: "Eye Injury/Swelling", sub: "Chemical splash, trauma, or sudden swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC = () => {
  const { addAcuteLog } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { addEntry } = useGovernance();
  const { mode } = useEnvironment();
  const { role } = useRole();
  const isOnline = useConnectivity();

  const [description, setDescription] = useState('');
  const [temp, setTemp] = useState('');
  const [duration, setDuration] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Derive age in months for red flag engine
  const ageMonths = useMemo(() => {
    if (!childProfile?.dob) return undefined;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
    if (now.getDate() < birth.getDate()) months--;
    return months;
  }, [childProfile]);

  // Integrated Safety Engine
  const activeRedFlags = useMemo(() => {
    const input = {
      ageMonths,
      temperature: temp ? parseFloat(temp) : undefined,
      symptoms: [description],
      durationDays: duration ? parseInt(duration) : undefined,
      environment: mode
    };

    const imciFlags = evaluateIMCIRedFlags({ symptoms: [description] });
    const stdFlags = evaluateRedFlags(input);

    return mode === 'low-resource' ? [...imciFlags, ...stdFlags] : stdFlags;
  }, [ageMonths, temp, description, duration, mode]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(
        description || "Visual symptom provided in image", 
        image || undefined, 
        activeRedFlags.map(rf => rf.message)
      );
      setResult(res);

      addEntry({
        eventType: "symptom_evaluation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Desc: ${description.slice(0, 50)}... Temp: ${temp || 'N/A'}`,
        outputSummary: `AI triage completed.`,
        redFlags: activeRedFlags.map(rf => rf.id),
        disclaimerShown: true
      });
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveToLogs = () => {
    if (result) {
      const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      addAcuteLog({
        timestamp,
        type: 'Triage',
        value: activeRedFlags.length > 0 ? 'Urgent Review Indicated' : 'Standard Home Care',
        notes: `SYMPTOMS: ${description}\n\nAI SYNTHESIS:\n${result.text}`,
        media: image || undefined
      });
      setSaved(true);
      alert("Triage result successfully synced to Medical Hub logs.");
    }
  };

  const inputClass = "w-full p-5 rounded-2xl border-2 border-slate-300 bg-white focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100 outline-none font-black text-slate-900 shadow-sm transition-all placeholder:text-slate-400";
  const labelClass = "text-[11px] font-black text-slate-700 uppercase tracking-widest ml-2 mb-1 block";

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
          <p className="text-slate-600 font-bold italic">Capture signs and receive guideline-based analysis.</p>
        </div>
        <div className="flex gap-2">
          {!isOnline && (
            <div className="bg-amber-100 text-amber-900 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border-2 border-amber-300 shadow-sm">
              <span>📡</span> Offline
            </div>
          )}
        </div>
      </header>

      {/* PERSISTENT CLINICAL RED FLAGS */}
      {activeRedFlags.length > 0 && (
        <div className="space-y-4 animate-in slide-in-from-top-4 duration-500">
          {activeRedFlags.map(flag => (
            <div key={flag.id} className={`p-8 rounded-[3rem] border-4 shadow-2xl flex items-start gap-8 transition-all ${flag.severity === 'Urgent' ? 'bg-rose-50 border-rose-600' : 'bg-amber-50 border-amber-500'}`}>
              <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center text-5xl shadow-inner shrink-0 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white animate-pulse' : 'bg-amber-500 text-white'}`}>
                {flag.severity === 'Urgent' ? '🚨' : '⚠️'}
              </div>
              <div className="space-y-2">
                <h4 className={`text-3xl font-black italic tracking-tight ${flag.severity === 'Urgent' ? 'text-rose-950' : 'text-amber-950'}`}>
                  {flag.message}
                </h4>
                <p className={`text-base font-bold leading-relaxed ${flag.severity === 'Urgent' ? 'text-rose-900/80' : 'text-amber-900/80'}`}>
                  {flag.subtext}
                </p>
                <div className="pt-4">
                  <a href="tel:000" className={`inline-flex items-center gap-3 px-8 py-3 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all active:scale-95 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white hover:bg-rose-700' : 'bg-amber-600 text-white hover:bg-amber-700'}`}>
                    📞 Call 000 / Emergency
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-10 rounded-[3.5rem] border-2 border-slate-200 shadow-xl space-y-8">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
               <div className="space-y-1">
                 <label className={labelClass}>Temperature (°C)</label>
                 <input 
                   type="number" step="0.1" value={temp} onChange={e => setTemp(e.target.value)} placeholder="37.0"
                   className={inputClass}
                 />
               </div>
               <div className="space-y-1">
                 <label className={labelClass}>Duration (Days)</label>
                 <input 
                   type="number" min="0" value={duration} onChange={e => setDuration(e.target.value)} placeholder="0"
                   className={inputClass}
                 />
               </div>
            </div>

            <div className="space-y-1">
              <label className={labelClass}>Patient Symptoms / Report</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Barking cough, lethargy, persistent vomiting..."
                className={`${inputClass} h-40 resize-none italic font-bold leading-relaxed`}
              />
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-6">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 px-10 py-5 rounded-2xl font-black border-2 text-xs uppercase tracking-widest w-full sm:w-auto transition-all bg-white border-slate-300 text-slate-700 hover:bg-slate-50 shadow-sm">
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button 
                onClick={handleAnalyze} 
                disabled={loading || (!description.trim() && !image)} 
                className={`flex-1 py-5 rounded-2xl font-black text-white shadow-2xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'}`}
              >
                {loading ? 'Consulting Protocols...' : 'Analyze Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-md mx-auto animate-in zoom-in-95 pt-4">
                <img src={image} alt="Symptom" className="w-full h-80 object-cover rounded-[2.5rem] border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-8 right-4 bg-white text-rose-600 w-12 h-12 rounded-full flex items-center justify-center shadow-2xl font-black text-xl border-2 border-rose-100 hover:bg-rose-50 transition-colors">✕</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white p-12 rounded-[4rem] shadow-2xl border-l-[24px] border-l-indigo-600 animate-in slide-in-from-bottom-8 duration-700 relative overflow-hidden">
              <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-5 blur-3xl"></div>
              <div className="flex justify-between items-center mb-10 relative z-10">
                 <h3 className="text-3xl font-black text-slate-800 italic uppercase tracking-tighter">AI Synthesis</h3>
                 <button 
                  onClick={handleSaveToLogs} 
                  disabled={saved} 
                  className={`px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all ${saved ? 'bg-emerald-600 text-white' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
                 >
                  {saved ? '✓ Logged to Hub' : 'Sync to Medical Hub'}
                </button>
              </div>
              <div className="whitespace-pre-wrap text-slate-800 font-bold italic border-l-4 border-slate-200 pl-10 text-2xl leading-relaxed relative z-10 mb-12">{result.text}</div>

              {result.sources.length > 0 && (
                <div className="pt-10 border-t-2 border-slate-100 space-y-5 relative z-10">
                  <p className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.3em]">Grounding Sources & Guidelines</p>
                  <div className="flex flex-wrap gap-3">
                    {result.sources.map((s: any, i: number) => (
                      <a key={i} href={s.web?.uri} target="_blank" rel="noopener noreferrer" className="text-[11px] font-black text-slate-700 hover:text-indigo-600 bg-white px-5 py-2.5 rounded-xl border-2 border-slate-200 hover:border-indigo-300 transition-all shadow-sm flex items-center gap-2">
                        {s.web?.title || 'Health Resource'} <span>↗</span>
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="space-y-8">
          <div className="bg-rose-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden border-b-[16px] border-rose-800">
             <h3 className="text-3xl font-black italic mb-10 uppercase tracking-tighter">Emergency</h3>
             <div className="space-y-6">
                {RED_FLAGS_LIST.map((f, i) => (
                  <div key={i} className="bg-white/15 p-6 rounded-[2rem] flex items-start gap-5 border border-white/10 shadow-inner group hover:bg-white/20 transition-colors">
                    <span className="text-5xl group-hover:scale-110 transition-transform">{f.icon}</span>
                    <div>
                      <span className="text-lg font-black leading-tight block">{f.text}</span>
                      <span className="text-xs font-bold text-rose-100 block mt-2 italic leading-snug">{f.sub}</span>
                    </div>
                  </div>
                ))}
             </div>
             <div className="mt-12">
                <a href="tel:000" className="block w-full py-7 bg-white text-rose-600 rounded-[2.5rem] text-center font-black text-5xl shadow-2xl active:scale-95 transition-all hover:bg-rose-50 border-4 border-rose-200">
                  📞 000
                </a>
                <p className="text-center text-[10px] font-black uppercase tracking-[0.4em] mt-6 opacity-60">National Emergency Line</p>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { calculateDosage } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useNavigation } from '../context/NavigationContext';
import { useRole } from '../context/RoleContext';
import { useConnectivity } from '../hooks/useConnectivity';
import { useGovernance } from '../context/GovernanceContext';
import { useEnvironment } from '../context/EnvironmentContext';
import { calculateSafetyCeiling } from '../clinical/dosing';

const OTC_MEDICATIONS = [
  { id: 'paracetamol', name: 'Paracetamol (Panadol/Tylenol)', icon: '💧' },
  { id: 'ibuprofen', name: 'Ibuprofen (Nurofen/Advil)', icon: '🍊' },
  { id: 'cetirizine', name: 'Antihistamine (Cetirizine/Zyrtec)', icon: '🤧' },
];

export const DoseCalculator: React.FC = () => {
  const { latestWeight } = useMedicalHistory();
  const { navigateTo } = useNavigation();
  const { role } = useRole();
  const { addEntry } = useGovernance();
  const { mode } = useEnvironment();
  const isOnline = useConnectivity();

  const [weight, setWeight] = useState(latestWeight?.toString() || '');
  const [medication, setMedication] = useState(OTC_MEDICATIONS[0].name);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  // Deterministic Safety Check - Runs automatically
  const safetyCeiling = useMemo(() => {
    const wNum = parseFloat(weight);
    if (!weight || isNaN(wNum)) return null;
    return calculateSafetyCeiling(wNum, medication);
  }, [weight, medication]);

  useEffect(() => {
    if (latestWeight) {
      setWeight(latestWeight.toString());
    }
  }, [latestWeight]);

  const handleCalculate = async () => {
    const weightNum = parseFloat(weight);
    if (!weight || isNaN(weightNum) || weightNum <= 0) return;

    const safetyMultiplier = mode === 'low-resource' ? 0.8 : 1.0;

    if (!isOnline) {
      if (safetyCeiling) {
        const adjustedDose = Math.floor((safetyCeiling.mgPerDose * safetyMultiplier) / 10) * 10;
        setResult({
          medicationName: safetyCeiling.medication,
          recommendedDose: `${adjustedDose} mg (Conservative Offline Calc)`,
          frequency: `Every ${safetyCeiling.intervalHours} hours`,
          maxDose24h: `${safetyCeiling.maxDosesPerDay} doses in 24 hours`,
          cautionaryNotes: `Offline Mode. ${mode === 'low-resource' ? 'Low-resource safety margin applied.' : ''} ${safetyCeiling.safetyWarnings.join(' ')}`
        });
      }
      return;
    }

    setLoading(true);
    try {
      const res = await calculateDosage(weightNum, medication);
      setResult(res);

      addEntry({
        eventType: "dose_calculation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Weight: ${weight}kg, Medication: ${medication}`,
        outputSummary: `Dose calculated: ${res.recommendedDose}`,
        disclaimerShown: true
      });
    } catch (error) {
      console.error(error);
      alert("Error calculating dosage.");
    } finally {
      setLoading(false);
    }
  };

  const inputClass = "w-full p-5 rounded-2xl border-2 border-slate-300 bg-white focus:border-emerald-600 focus:ring-4 focus:ring-emerald-100 outline-none font-black text-2xl text-slate-900 placeholder:text-slate-400 shadow-sm transition-all";
  const labelClass = "block text-[11px] font-black text-slate-700 uppercase tracking-widest ml-2 mb-1";

  if (!latestWeight && !weight) {
    return (
      <div className="max-w-2xl mx-auto space-y-6 py-12 animate-in fade-in">
        <div className="bg-amber-50 border-4 border-dashed border-amber-300 p-12 rounded-[4rem] text-center space-y-8">
           <div className="w-24 h-24 bg-white rounded-3xl flex items-center justify-center text-5xl shadow-xl mx-auto border-2 border-amber-100">⚖️</div>
           <div className="space-y-3">
             <h3 className="text-3xl font-black text-amber-950 tracking-tighter italic">Weight Required</h3>
             <p className="text-amber-900 text-base font-bold italic leading-relaxed max-w-sm mx-auto">Clinical safety protocols require a recent weight measurement before calculating safe pediatric dosages.</p>
           </div>
           <button onClick={() => navigateTo('redbook')} className="px-10 py-5 bg-amber-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-amber-700 transition-all hover:scale-105">Log Weight in Red Book</button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-20">
      <header className="px-1 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">SafeDose <span className="text-emerald-600">OTC</span></h2>
          <p className="text-slate-600 font-bold italic mt-1">Weight-based guidance for standard medications.</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-8 rounded-[3.5rem] shadow-xl border-2 border-slate-200 space-y-8">
            <div className="space-y-1">
              <label className={labelClass}>Child's Weight (kg)</label>
              <div className="relative">
                <input type="number" inputMode="decimal" value={weight} onChange={e => setWeight(e.target.value)} placeholder="e.g. 12" className={inputClass} />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 font-black text-slate-400 text-sm tracking-widest uppercase">kg</span>
              </div>
            </div>

            <div className="space-y-3">
              <label className={labelClass}>Common OTC Medication</label>
              <div className="grid grid-cols-1 gap-3">
                {OTC_MEDICATIONS.map(m => (
                  <button key={m.id} onClick={() => setMedication(m.name)} className={`w-full p-5 rounded-[2rem] border-2 text-left transition-all flex items-center gap-5 ${medication === m.name ? 'border-emerald-600 bg-emerald-50 shadow-md scale-105' : 'border-slate-200 bg-white hover:border-emerald-200 text-slate-500'}`}>
                    <span className="text-3xl">{m.icon}</span>
                    <span className="font-black text-sm leading-tight text-slate-800">{m.name}</span>
                  </button>
                ))}
              </div>
            </div>

            <button onClick={handleCalculate} disabled={loading || !weight} className={`w-full py-6 rounded-[2rem] font-black text-white shadow-2xl transition-all uppercase tracking-widest text-sm w-full ${loading ? 'bg-slate-400' : 'bg-emerald-600 hover:bg-emerald-700 active:scale-95'}`}>{loading ? 'Consulting Protocols...' : 'Verify Safe Dose ✨'}</button>
          </div>

          {/* DETERMINISTIC BASELINE WARNING */}
          {safetyCeiling && (
            <div className="bg-emerald-950 p-8 rounded-[3rem] text-white shadow-2xl space-y-4 animate-in fade-in border-b-[12px] border-emerald-900">
               <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-emerald-800 rounded-xl flex items-center justify-center text-xl">🛡️</div>
                  <p className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-400">Deterministic Safety Floor</p>
               </div>
               <h5 className="text-2xl font-black italic tracking-tighter">Max Safe Dose: {safetyCeiling.mgPerDose} mg</h5>
               <p className="text-sm font-bold text-emerald-100/60 leading-relaxed italic border-t border-white/10 pt-4">This is the Australian clinical standard (15mg/kg) for a {weight} kg child. Do not exceed.</p>
