import React, { createContext, useContext, useMemo } from 'react';
import { ChildProfile } from '../types';
import { useLocalStorage } from '../hooks/useLocalStorage';

interface ChildProfileContextType {
  childProfile?: ChildProfile;
  setChildProfile: (profile: ChildProfile) => void;
  childAge: string | null;
  hasSkippedSetup: boolean;
  setHasSkippedSetup: (val: boolean) => void;
}

const ChildProfileContext = createContext<ChildProfileContextType | undefined>(undefined);

export const ChildProfileProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [childProfile, setChildProfile] = useLocalStorage<ChildProfile | undefined>('pedipulse_profile', undefined);
  const [hasSkippedSetup, setHasSkippedSetup] = useLocalStorage<boolean>('pedipulse_setup_skipped', false);

  const childAge = useMemo(() => {
    if (!childProfile?.dob) return null;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let years = now.getFullYear() - birth.getFullYear();
    let months = now.getMonth() - birth.getMonth();
    if (months < 0 || (months === 0 && now.getDate() < birth.getDate())) {
      years--;
      months += 12;
    }
    if (years === 0) return `${months} months old`;
    return `${years} years, ${months % 12} months`;
  }, [childProfile]);

  return (
    <ChildProfileContext.Provider value={{ childProfile, setChildProfile, childAge, hasSkippedSetup, setHasSkippedSetup }}>
      {children}
    </ChildProfileContext.Provider>
  );
};

export const useChildProfile = () => {
  const context = useContext(ChildProfileContext);
  if (!context) {
    throw new Error('useChildProfile must be used within a ChildProfileProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { ChildProfile, Medication } from '../types';
import { useChildProfile } from '../context/ChildProfileContext';
import { useNavigation } from '../context/NavigationContext';

export const ChildProfileSetup: React.FC = () => {
  const { childProfile, setChildProfile, setHasSkippedSetup } = useChildProfile();
  const { navigateTo } = useNavigation();
  const [isSaving, setIsSaving] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // Child Info
  const [name, setName] = useState(childProfile?.name || '');
  const [dob, setDob] = useState(childProfile?.dob || '');
  const [sex, setSex] = useState<'Male' | 'Female' | 'Other'>(childProfile?.sex || 'Male');
  const [weight, setWeight] = useState(childProfile?.weight?.toString() || '');
  const [height, setHeight] = useState(childProfile?.height?.toString() || '');
  const [medHistory, setMedHistory] = useState(childProfile?.pastMedicalHistory || '');

  // Account Info
  const [email, setEmail] = useState(childProfile?.email || '');
  const [password, setPassword] = useState(childProfile?.password || '');
  const [stayLoggedIn, setStayLoggedIn] = useState(childProfile?.stayLoggedIn ?? true);
  const [agreedToTerms, setAgreedToTerms] = useState(!!childProfile);

  const [validationErrors, setValidationErrors] = useState<string[]>([]);

  useEffect(() => {
    const errors = [];
    if (!name) errors.push("Name is required");
    if (!dob) errors.push("DOB is required");
    if (!email) errors.push("Email is required");
    if (!agreedToTerms) errors.push("Agreement required");
    setValidationErrors(errors);
  }, [name, dob, email, agreedToTerms]);

  const handleSkip = () => {
    setHasSkippedSetup(true);
    navigateTo('dashboard');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (validationErrors.length > 0) {
      return;
    }

    const weightNum = parseFloat(weight);
    if (weight && (weightNum < 2 || weightNum > 150)) {
       alert("Please enter a realistic pediatric weight (2 kg to 150 kg).");
       return;
    }

    setIsSaving(true);

    setTimeout(() => {
      setChildProfile({
        name,
        dob,
        sex,
        weight: weight ? parseFloat(weight) : undefined,
        height: height ? parseFloat(height) : undefined,
        pastMedicalHistory: medHistory,
        medications: childProfile?.medications || [],
        previousMedications: childProfile?.previousMedications || [],
        allergies: childProfile?.allergies || [],
        email,
        password,
        stayLoggedIn
      });
      setHasSkippedSetup(false); // Reset skip flag if they completed setup
      setIsSuccess(true);
      setTimeout(() => {
        navigateTo('dashboard');
        setIsSaving(false);
      }, 800);
    }, 600);
  };

  const inputClass = "w-full p-5 rounded-2xl border-2 border-slate-400 bg-white focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100 outline-none font-black text-slate-900 text-lg transition-all placeholder:text-slate-400 shadow-sm";
