        <p className="text-slate-600 font-bold italic">Your local, private pediatric health hub.</p>

        {!childProfile && (
          <div className="pt-4">
            <button 
              onClick={handleSkip}
              className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400 hover:text-indigo-600 border-2 border-slate-200 hover:border-indigo-200 px-8 py-3 rounded-2xl transition-all"
            >
              Skip & Use as Guest →
            </button>
          </div>
        )}
      </header>

      <form onSubmit={handleSubmit} className="space-y-10">
        <section className="bg-white p-10 rounded-[3.5rem] border-2 border-slate-300 shadow-xl space-y-8">
          <div className="flex items-center gap-3 border-b-2 border-slate-100 pb-6">
            <span className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-lg shadow-inner">🆔</span>
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Identity & Baseline</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-1">
              <label className={labelClass}>Child's Name</label>
              <input type="text" required value={name} onChange={(e) => setName(e.target.value)} placeholder="Full Name" className={inputClass} />
            </div>
            <div className="space-y-1">
              <label className={labelClass}>Birth Date</label>
              <input type="date" required max={new Date().toISOString().split('T')[0]} value={dob} onChange={(e) => setDob(e.target.value)} className={inputClass} />
            </div>
            <div className="space-y-1">
              <label className={labelClass}>Latest Weight (kg)</label>
              <div className="relative">
                <input type="number" step="0.1" min="2" max="150" value={weight} onChange={(e) => setWeight(e.target.value)} placeholder="e.g. 12.5" className={inputClass} />
                <span className="absolute right-5 top-1/2 -translate-y-1/2 text-[11px] font-black text-slate-500 uppercase tracking-widest">KG</span>
              </div>
            </div>
            <div className="space-y-1">
               <label className={labelClass}>Guardian Email</label>
               <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="parent@example.com" className={inputClass} />
            </div>
          </div>
        </section>

        {!childProfile && (
          <section className="bg-indigo-50 p-10 rounded-[3rem] border-2 border-indigo-200 space-y-6">
            <h4 className="text-sm font-black text-indigo-900 uppercase tracking-widest">Clinical Terms & Sovereignty</h4>
            <label className="flex items-start gap-4 cursor-pointer group">
              <div className="relative pt-1">
                <input 
                  type="checkbox" 
                  checked={agreedToTerms} 
                  onChange={e => setAgreedToTerms(e.target.checked)}
                  className="w-8 h-8 rounded-xl border-2 border-indigo-400 text-indigo-600 focus:ring-indigo-500 transition-all cursor-pointer bg-white"
                />
              </div>
              <div className="space-y-1">
                <p className="text-sm font-black text-indigo-950 italic leading-snug group-hover:text-indigo-600 transition-colors">
                  "I understand PediPulse is a decision-support tool. All clinical data remains local to this device. I agree to seek professional care for all urgent concerns."
                </p>
                <p className="text-xs font-bold text-indigo-600 italic">
                  Confirmation required to initialize your local pediatric record.
                </p>
              </div>
            </label>
          </section>
        )}

        <div className="space-y-4">
          <button 
            type="submit" 
            disabled={isSaving || validationErrors.length > 0}
            className={`w-full py-7 text-white font-black rounded-[2.5rem] shadow-2xl transition-all transform active:scale-95 text-base uppercase tracking-[0.2em] flex items-center justify-center gap-3 ${
              isSuccess ? 'bg-emerald-500' :
              (validationErrors.length > 0 ? 'bg-slate-300 cursor-not-allowed text-slate-500 shadow-none' : 'bg-indigo-600 hover:bg-indigo-700')
            }`}
          >
            {isSuccess ? (
              <>
                <span className="text-2xl animate-bounce">✓</span>
                Initialization Complete!
              </>
            ) : isSaving ? (
              <>
                <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                Securing Local Database...
              </>
            ) : (
              <>{childProfile ? 'Update Health Baseline' : 'Initialize Local Hub ✨'}</>
            )}
          </button>

          {validationErrors.length > 0 && (
            <p className="text-center text-xs font-black text-rose-600 uppercase tracking-widest animate-pulse">
              Please complete all required fields and accept terms to proceed.
            </p>
          )}
        </div>
      </form>
    </div>
  );
};

