import React, { useState } from 'react';
import { ConsultationNote, ClinicalFindings, AssignedTest } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { GoogleGenAI } from "@google/genai";

const SCREENING_MODS = [
  { id: 'snap4', name: 'SNAP-IV (ADHD)', domain: 'Focus' },
  { id: 'mchat', name: 'M-CHAT-R (Autism)', domain: 'Social' },
  { id: 'asq3', name: 'ASQ-3 (Development)', domain: 'Development' },
  { id: 'gad7', name: 'GAD-7 (Anxiety)', domain: 'Mood' },
  { id: 'phq9', name: 'PHQ-9 (Mood/Depression)', domain: 'Mood' },
  { id: 'sdq', name: 'SDQ (Behavior)', domain: 'Behavior' },
];

const REASONING_FRAMEWORKS = [
  { id: 'standard', name: 'Standard Clinical', desc: 'General differential ranking' },
  { id: 'vindicate', name: 'VINDICATE', desc: 'Vascular, Infectious, Neoplastic, Degenerative, etc.' },
  { id: 'vitamins', name: 'VITAMINS', desc: 'Vascular, Infectious, Traumatic, Autoimmune, etc.' },
  { id: 'surgical_sieve', name: 'Surgical Sieve', desc: 'Anatomical vs Pathological mapping' },
];

const CLINICAL_SHORTHAND = {
  general: ['Alert/Active', 'Well Appearance', 'Mildly Unwell', 'NAD', 'Euvolaemic'],
  respiratory: ['Chest Clear', 'Symmetrical Expansion', 'No Wheeze/Stridor', 'Air Entry + Bilat', 'No Distressed Signs'],
  cardiac: ['HS I + II + 0', 'Femoral Pulps + Bilat', 'Cap Refill < 2s', 'Rhythm Regular'],
  abdominal: ['Soft/Non-tender', 'No Masses', 'BS + Active', 'No Guarding'],
  neurological: ['Tone Normal', 'Pupils PERL', 'GCS 15', 'No Focal Deficits'],
  skin: ['No Rashes', 'Warm/Pink', 'Skin Turgor Normal', 'No Petechiae']
};

export const ClinicianTools: React.FC<{ type: 'consults' | 'reasoning' | 'assignments' }> = ({ type }) => {
  const { history, updateHistory } = useMedicalHistory();
  const [loading, setLoading] = useState(false);
  const [reasoningResult, setReasoningResult] = useState<{text: string, sources: any[]} | null>(null);
  const [activeFramework, setActiveFramework] = useState('standard');
  const [activeInputTab, setActiveInputTab] = useState<'history' | 'exam' | 'investigations'>('history');

  const assignedTests = history.assignedTests || [];

  const [newSoap, setNewSoap] = useState<Partial<ConsultationNote>>({
    clinicianName: '', subjective: '', objective: '', assessment: '', plan: ''
  });

  const [findings, setFindings] = useState<{
    history: string;
    exam: {
      general: string;
      respiratory: string;
      cardiac: string;
      abdominal: string;
      neurological: string;
      skin: string;
    };
    investigations: string;
    vitals: { hr?: string; rr?: string; temp?: string; o2?: string; bp?: string; glu?: string };
  }>({
    history: '',
    exam: { general: '', respiratory: '', cardiac: '', abdominal: '', neurological: '', skin: '' },
    investigations: '',
    vitals: {}
  });

  const injectShorthand = (section: keyof typeof findings.exam, term: string) => {
    setFindings(prev => ({
      ...prev,
      exam: {
        ...prev.exam,
        [section]: prev.exam[section] ? `${prev.exam[section]}, ${term}` : term
      }
    }));
  };

  const toggleTestAssignment = (testId: string) => {
    const isAssigned = assignedTests.some(t => t.testId === testId);
    let next: AssignedTest[];
    if (isAssigned) {
      next = assignedTests.filter(t => t.testId !== testId);
    } else {
      next = [...assignedTests, { testId, assignedDate: new Date().toISOString(), status: 'pending' }];
    }
    updateHistory({ assignedTests: next });
  };

  const handleAddConsult = () => {
    if (!newSoap.assessment || !newSoap.plan) return;
    const consult: ConsultationNote = {
      ...newSoap,
      id: crypto.randomUUID(),
      date: new Date().toISOString()
    } as ConsultationNote;
    updateHistory({ formalConsults: [consult, ...(history.formalConsults || [])] });
    setNewSoap({ clinicianName: '', subjective: '', objective: '', assessment: '', plan: '' });
  };

  const handleRunReasoning = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const frameworkInstruction = 
        activeFramework === 'vindicate' ? "Use the VINDICATE acronym to structure your differential." :
        activeFramework === 'vitamins' ? "Use the VITAMINS mnemonic to structure your differential." :
        activeFramework === 'surgical_sieve' ? "Apply a Surgical Sieve approach." : 
        "Provide a prioritized differential list.";

      const prompt = `Act as a senior pediatric consultant. Analyze this clinical presentation.
      FRAMEWORK: ${frameworkInstruction}
      PATIENT: PMHx: ${history.pastMedicalHistory}, Meds: ${history.currentMedications.map(m => m.name).join(', ')}
      HISTORY: ${findings.history}
      VITALS: HR: ${findings.vitals.hr}, RR: ${findings.vitals.rr}, SpO2: ${findings.vitals.o2}, Temp: ${findings.vitals.temp}, BP: ${findings.vitals.bp}, BSL: ${findings.vitals.glu}
      EXAM: Gen: ${findings.exam.general}, Resp: ${findings.exam.respiratory}, CVS: ${findings.exam.cardiac}, Abdo: ${findings.exam.abdominal}, CNS: ${findings.exam.neurological}, Skin: ${findings.exam.skin}
      TESTS: ${findings.investigations}
      REQUIREMENTS: 1. Differential 2. Red Flags 3. Plan 4. Evidence (EBM). Format clearly with numbered sections.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
      });
      setReasoningResult({
        text: response.text || 'Synthesis failed.',
        sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
      });
    } catch (e) {
      alert("Error generating reasoning.");
    } finally {
      setLoading(false);
    }
  };

  if (type === 'assignments') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Assignment <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Curate specific assessments for the caregiver to complete before review.</p>
        </header>

        <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">📋</div>
              <div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight">Instrument Selection</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Pre-Appointment Clinical Pack</p>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {SCREENING_MODS.map(test => {
                const assignment = assignedTests.find(t => t.testId === test.id);
                const isAssigned = !!assignment;
                const isCompleted = assignment?.status === 'completed';

                return (
                  <button 
                    key={test.id}
                    onClick={() => toggleTestAssignment(test.id)}
                    className={`p-8 rounded-[3rem] border-2 text-left transition-all relative group flex flex-col justify-between h-48 ${
                      isCompleted ? 'bg-emerald-50 border-emerald-500' :
                      isAssigned ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-105' : 
                      'bg-slate-50 border-slate-100 hover:border-indigo-300 hover:bg-white'
                    }`}
                  >
                    <div>
                      <div className="flex justify-between items-start mb-2">
                        <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full ${isAssigned ? 'bg-white/20' : 'bg-slate-200 text-slate-500'}`}>{test.domain}</span>
                        {isCompleted && <span className="text-emerald-600 text-xs font-black">✓ Done</span>}
                      </div>
                      <h4 className={`text-xl font-black tracking-tight leading-none ${isAssigned && !isCompleted ? 'text-white' : 'text-slate-800'}`}>{test.name}</h4>
                    </div>

                    <div className="flex items-center justify-between mt-4">
                      <span className={`text-[10px] font-black uppercase tracking-widest ${isAssigned && !isCompleted ? 'text-indigo-100' : 'text-slate-400'}`}>
                        {isCompleted ? 'Finished' : isAssigned ? 'Assigned' : 'Click to Assign'}
                      </span>
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-transform group-hover:scale-110 ${isAssigned ? 'bg-white text-indigo-600 shadow-lg' : 'bg-slate-200 text-slate-400'}`}>
                        {isAssigned ? '✓' : '+'}
                      </div>
                    </div>
                  </button>
                );
              })}
           </div>
        </div>
      </div>
    );
  }

  if (type === 'consults') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">SOAP <span className="text-indigo-600">Consultations</span></h2>
          <p className="text-slate-500 font-medium italic">Formal clinical documentation for professional record keeping.</p>
        </header>

        <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Subjective (S)</label>
                <textarea value={newSoap.subjective} onChange={e => setNewSoap({...newSoap, subjective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 font-bold italic text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Patient's report..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Objective (O)</label>
                <textarea value={newSoap.objective} onChange={e => setNewSoap({...newSoap, objective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 font-bold italic text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Vitals, physical exam..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Assessment (A)</label>
                <textarea value={newSoap.assessment} onChange={e => setNewSoap({...newSoap, assessment: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-indigo-50/30 border border-indigo-100 font-bold italic text-indigo-900 outline-none focus:ring-4 focus:ring-indigo-100" placeholder="Diagnosis..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Plan (P)</label>
                <textarea value={newSoap.plan} onChange={e => setNewSoap({...newSoap, plan: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-emerald-50/30 border border-emerald-100 font-bold italic text-emerald-900 outline-none focus:ring-4 focus:ring-emerald-100" placeholder="Next steps..." />
             </div>
          </div>
          <div className="flex justify-between items-center pt-8 border-t border-slate-50">
             <input value={newSoap.clinicianName} onChange={e => setNewSoap({...newSoap, clinicianName: e.target.value})} placeholder="Clinician Name" className="p-4 bg-slate-50 rounded-xl font-black text-xs outline-none" />
             <button onClick={handleAddConsult} className="px-10 py-5 bg-indigo-600 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-700">Record Formal Consult</button>
          </div>
        </section>

        <section className="space-y-6">
           <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Clinical Archive</h3>
           <div className="space-y-6">
              {(history.formalConsults || []).map(note => (
                <div key={note.id} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-6">
                   <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                      <div>
                         <p className="text-xl font-black text-slate-800 italic">Consultation Note</p>
                         <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Clinician: {note.clinicianName}</p>
                      </div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(note.date).toLocaleDateString()}</p>
                   </div>
                   <div className="grid grid-cols-2 gap-8">
                      <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Subjective</p><p className="text-sm font-medium italic text-slate-600">"{note.subjective}"</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Objective</p><p className="text-sm font-medium italic text-slate-600">"{note.objective}"</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-indigo-400 uppercase">Assessment</p><p className="text-sm font-black text-slate-800">{note.assessment}</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-emerald-400 uppercase">Plan</p><p className="text-sm font-black text-slate-800">{note.plan}</p></div>
                   </div>
                </div>
              ))}
           </div>
        </section>
      </div>
    );
  }

  return (
    <div className="space-y-12 pb-24 animate-in fade-in">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Reasoning <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Advanced AI-augmented differential diagnosis assistant.</p>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-200">
           {REASONING_FRAMEWORKS.map(f => (
             <button
              key={f.id}
              onClick={() => setActiveFramework(f.id)}
              className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${activeFramework === f.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400'}`}
             >
               {f.name}
             </button>
           ))}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
         <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8 h-fit">
            <nav className="flex gap-4 border-b border-slate-50 pb-4">
               {['history', 'exam', 'investigations'].map(tab => (
                 <button 
                  key={tab} 
                  onClick={() => setActiveInputTab(tab as any)}
                  className={`text-[10px] font-black uppercase tracking-[0.2em] pb-2 border-b-4 transition-all ${activeInputTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-300'}`}
                 >
                   {tab}
                 </button>
               ))}
            </nav>

            <div className="space-y-6">
               {activeInputTab === 'history' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Clinical History Highlights</label>
                      <textarea value={findings.history} onChange={e => setFindings({...findings, history: e.target.value})} className="w-full h-32 p-5 rounded-2xl bg-slate-50 font-bold italic outline-none border border-slate-100 focus:ring-2 focus:ring-indigo-50 shadow-inner" placeholder="Onset, character, associated symptoms..." />
                    </div>
                    <div className="grid grid-cols-3 gap-4">
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">HR</label>
                        <input placeholder="e.g. 110" value={findings.vitals.hr} onChange={e => setFindings({...findings, vitals: {...findings.vitals, hr: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">RR</label>
                        <input placeholder="e.g. 24" value={findings.vitals.rr} onChange={e => setFindings({...findings, vitals: {...findings.vitals, rr: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">SpO2</label>
                        <input placeholder="e.g. 98%" value={findings.vitals.o2} onChange={e => setFindings({...findings, vitals: {...findings.vitals, o2: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">Temp</label>
                        <input placeholder="e.g. 38.2" value={findings.vitals.temp} onChange={e => setFindings({...findings, vitals: {...findings.vitals, temp: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">BSL / Glu</label>
                        <input placeholder="e.g. 5.1" value={findings.vitals.glu} onChange={e => setFindings({...findings, vitals: {...findings.vitals, glu: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                    </div>
                 </div>
               )}

               {activeInputTab === 'exam' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4 max-h-[500px] overflow-y-auto pr-2 no-scrollbar">
                    {(Object.keys(CLINICAL_SHORTHAND) as Array<keyof typeof findings.exam>).map(sysKey => (
                      <div key={sysKey} className="space-y-3">
                        <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block">{String(sysKey)} Systems</label>
                        <div className="flex flex-wrap gap-1.5 mb-2">
                           {CLINICAL_SHORTHAND[sysKey].map(term => (
                             <button 
                              key={term}
                              onClick={() => injectShorthand(sysKey, term)}
                              className="px-3 py-1 bg-slate-50 border border-slate-200 rounded-lg text-[9px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                             >
                               {term}
                             </button>
                           ))}
                        </div>
                        <input 
                          value={findings.exam[sysKey]} 
                          onChange={e => setFindings({...findings, exam: {...findings.exam, [sysKey]: e.target.value}})} 
                          className="w-full p-4 rounded-xl bg-slate-50 font-bold italic outline-none border border-slate-100 focus:ring-2 focus:ring-indigo-50 text-sm shadow-inner" 
                          placeholder={`Specific observations for ${String(sysKey)}...`}
                        />
                      </div>
                    ))}
                 </div>
               )}

               {activeInputTab === 'investigations' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Laboratory & Imaging Results</label>
                      <textarea value={findings.investigations} onChange={e => setFindings({...findings, investigations: e.target.value})} className="w-full h-48 p-5 rounded-2xl bg-slate-50 font-bold italic outline-none border border-slate-100 focus:ring-2 focus:ring-indigo-50 shadow-inner" placeholder="CBC, CXR findings..." />
                    </div>
                 </div>
               )}

               <div className="pt-6 border-t border-slate-50">
                  <button onClick={handleRunReasoning} disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-slate-800 transition-all active:scale-95 flex items-center justify-center gap-3">
                    {loading ? (
                      <>
                        <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                        Consulting EBM Pipeline...
                      </>
                    ) : 'Run Differential Engine ✨'}
                  </button>
               </div>
            </div>
         </section>

         <section className="h-full">
            {reasoningResult ? (
              <div className="space-y-6 h-full flex flex-col">
                <div className="bg-slate-900 p-10 sm:p-14 rounded-[4rem] text-white shadow-2xl animate-in zoom-in-95 border-l-[24px] border-l-indigo-600 relative overflow-hidden flex-1 overflow-y-auto no-scrollbar">
                   <div className="absolute top-0 right-0 -mr-20 -mt-20 w-96 h-96 bg-indigo-600 rounded-full opacity-10 blur-[120px]"></div>
                   <div className="flex justify-between items-center mb-12 relative z-10">
                      <div className="flex items-center gap-4">
                        <div className="w-14 h-14 bg-indigo-500/20 rounded-2xl flex items-center justify-center text-3xl shadow-inner border border-white/10">🧠</div>
                        <h3 className="text-3xl font-black italic text-indigo-100 uppercase tracking-tighter leading-none">Clinical Insight Report</h3>
                      </div>
                      <span className="px-4 py-1.5 bg-white/10 rounded-full text-[8px] font-black uppercase tracking-widest border border-white/10">{activeFramework} MODE</span>
                   </div>

                   {/* Report Body Structure */}
                   <div className="relative z-10 text-indigo-50 space-y-10 mb-16">
                      {reasoningResult.text.split('\n').map((line, idx) => {
                        const isHeader = line.match(/^\d\./);
                        const isListItem = line.match(/^[-•]/);
                        return (
                          <p key={idx} className={`
                            ${isHeader ? "text-2xl text-indigo-300 not-italic font-black border-b border-white/10 pb-2 mt-12 mb-4 uppercase tracking-tighter" : "text-lg font-bold italic leading-relaxed tracking-tight"}
                            ${isListItem ? "ml-8 list-item not-italic font-medium text-base text-indigo-100/90" : ""}
                          `}>
                            {line.replace(/^[-•]\s*/, '')}
                          </p>
                        );
                      })}
                   </div>

                   {reasoningResult.sources.length > 0 && (
                     <div className="pt-10 border-t border-white/10 space-y-6 relative z-10">
                        <p className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">Validated Evidence Registry</p>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                           {reasoningResult.sources.map((s, i) => (
                             <a key={i} href={s.web?.uri} target="_blank" className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl text-[10px] font-bold text-indigo-200 border border-white/5 transition-all flex items-center justify-between group">
                               <span className="truncate pr-4">{s.web?.title || 'EBM Source'}</span>
                               <span className="group-hover:translate-x-1 transition-transform opacity-60">↗</span>
                             </a>
                           ))}
                        </div>
                     </div>
                   )}

                   <div className="mt-16 pt-10 border-t border-white/10 opacity-40">
                      <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Professional Notice</p>
                      <p className="text-[11px] italic mt-3 leading-relaxed">Synthesis generated via clinician-in-the-loop reasoning. This artifact is intended as an augmentation tool for medical practitioners and does not constitute a standalone diagnosis.</p>
                   </div>
                </div>
              </div>
            ) : (
              <div className="h-full min-h-[600px] border-4 border-dashed border-slate-200 rounded-[4rem] flex flex-col items-center justify-center p-20 opacity-30 text-center grayscale">
                 <span className="text-8xl mb-8">🧠</span>
                 <p className="text-xl font-black uppercase tracking-widest">Bench Ready</p>
                 <p className="text-sm font-medium italic mt-2">Input history, exam systems, and tests to run clinical synthesis.</p>
              </div>
            )}
         </section>
      </div>
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { analyzeSymptoms } from '../services/gemini';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useConnectivity } from '../hooks/useConnectivity';
import { useGovernance } from '../context/GovernanceContext';
import { useEnvironment } from '../context/EnvironmentContext';
import { useRole } from '../context/RoleContext';
import { evaluateRedFlags } from '../clinical/redFlags';
import { evaluateIMCIRedFlags } from '../clinical/redFlagsIMCI';

const RED_FLAGS_LIST = [
  { text: "Difficulty Breathing", sub: "Grunting, wheezing, or chest sucking in", icon: "🫁" },
  { text: "Infant Fever", sub: "Any fever in a baby under 3 months old", icon: "🌡️" },
  { text: "Altered Level of Consciousness", sub: "Unusually sleepy, floppy, or unresponsive", icon: "😴" },
  { text: "Non-Blanching Rash", sub: "Purple/red spots that don't fade when pressed", icon: "🟣" },
  { text: "Severe Pain", sub: "Inconsolable crying or extreme localized pain", icon: "😫" },
  { text: "Eye Injury/Swelling", sub: "Chemical splash, trauma, or sudden swelling", icon: "👁️" }
];

export const SymptomChecker: React.FC = () => {
  const { addAcuteLog } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { addEntry } = useGovernance();
  const { mode } = useEnvironment();
  const { role } = useRole();
  const isOnline = useConnectivity();

  const [description, setDescription] = useState('');
  const [temp, setTemp] = useState('');
  const [duration, setDuration] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ text: string; sources: any[] } | null>(null);
  const [image, setImage] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const ageMonths = useMemo(() => {
    if (!childProfile?.dob) return undefined;
    const birth = new Date(childProfile.dob);
    const now = new Date();
    let months = (now.getFullYear() - birth.getFullYear()) * 12 + (now.getMonth() - birth.getMonth());
    if (now.getDate() < birth.getDate()) months--;
    return months;
  }, [childProfile]);

  const activeRedFlags = useMemo(() => {
    const input = {
      ageMonths,
      temperature: temp ? parseFloat(temp) : undefined,
      symptoms: [description],
      durationDays: duration ? parseInt(duration) : undefined,
      environment: mode
    };
    const imciFlags = evaluateIMCIRedFlags({ symptoms: [description] });
    const stdFlags = evaluateRedFlags(input);
    return mode === 'low-resource' ? [...imciFlags, ...stdFlags] : stdFlags;
  }, [ageMonths, temp, description, duration, mode]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description.trim() && !image) return;
    if (!isOnline) {
      alert("Offline Mode: AI Triage requires an internet connection.");
      return;
    }
    setLoading(true);
    setSaved(false);
    try {
      const res = await analyzeSymptoms(
        description || "Visual symptom provided in image", 
        image || undefined, 
        activeRedFlags.map(rf => rf.message)
      );
      setResult(res);
      addEntry({
        eventType: "symptom_evaluation",
        userRole: role,
        environment: mode,
        online: isOnline,
        inputSummary: `Desc: ${description.slice(0, 50)}... Temp: ${temp || 'N/A'}`,
        outputSummary: `AI triage completed.`,
        redFlags: activeRedFlags.map(rf => rf.id),
        disclaimerShown: true
      });
    } catch (error) {
      console.error(error);
      alert("Error reviewing symptoms.");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveToLogs = () => {
    if (result) {
      const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      addAcuteLog({
        timestamp,
        type: 'Triage',
        value: activeRedFlags.length > 0 ? 'Urgent Review Indicated' : 'Standard Home Care',
        notes: `SYMPTOMS: ${description}\n\nAI SYNTHESIS:\n${result.text}`,
        media: image || undefined
      });
      setSaved(true);
      alert("Triage result successfully synced to Medical Hub logs.");
    }
  };

  const triageLevel = useMemo(() => {
    if (activeRedFlags.some(f => f.severity === 'Urgent')) return { color: 'bg-rose-600', text: 'Emergency Action', width: 'w-full', icon: '🚨' };
    if (activeRedFlags.length > 0) return { color: 'bg-amber-500', text: 'Clinical Review Needed', width: 'w-2/3', icon: '⚠️' };
    return { color: 'bg-emerald-500', text: 'Supportive Care / Home', width: 'w-1/3', icon: '✅' };
  }, [activeRedFlags]);

  const inputClass = "w-full p-5 rounded-2xl border-2 border-slate-300 bg-white focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100 outline-none font-black text-slate-900 shadow-sm transition-all placeholder:text-slate-400";
  const labelClass = "text-[11px] font-black text-slate-700 uppercase tracking-widest ml-2 mb-1 block";

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 italic">Symptom <span className="text-indigo-600">AI Triage</span></h2>
          <p className="text-slate-600 font-bold italic">Capture signs and receive guideline-based analysis.</p>
        </div>
        <div className="flex gap-2">
          {!isOnline && (
            <div className="bg-amber-100 text-amber-900 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 border-2 border-amber-300 shadow-sm">
              <span>📡</span> Offline
            </div>
          )}
        </div>
      </header>

      {activeRedFlags.length > 0 && (
        <div className="space-y-4 animate-in slide-in-from-top-4 duration-500">
          {activeRedFlags.map(flag => (
            <div key={flag.id} className={`p-8 rounded-[3rem] border-4 shadow-2xl flex items-start gap-8 transition-all ${flag.severity === 'Urgent' ? 'bg-rose-50 border-rose-600' : 'bg-amber-50 border-amber-500'}`}>
              <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center text-5xl shadow-inner shrink-0 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white animate-pulse' : 'bg-amber-500 text-white'}`}>
                {flag.severity === 'Urgent' ? '🚨' : '⚠️'}
              </div>
              <div className="space-y-2">
                <h4 className={`text-3xl font-black italic tracking-tight ${flag.severity === 'Urgent' ? 'text-rose-950' : 'text-amber-950'}`}>
                  {flag.message}
                </h4>
                <p className={`text-base font-bold leading-relaxed ${flag.severity === 'Urgent' ? 'text-rose-900/80' : 'text-amber-900/80'}`}>
                  {flag.subtext}
                </p>
                <div className="pt-4">
                  <a href="tel:000" className={`inline-flex items-center gap-3 px-8 py-3 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all active:scale-95 ${flag.severity === 'Urgent' ? 'bg-rose-600 text-white hover:bg-rose-700' : 'bg-amber-600 text-white hover:bg-amber-700'}`}>
                    📞 Call 000 / Emergency
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-10 rounded-[3.5rem] border-2 border-slate-200 shadow-xl space-y-8">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
               <div className="space-y-1">
                 <label className={labelClass}>Temperature (°C)</label>
                 <input 
                   type="number" step="0.1" value={temp} onChange={e => setTemp(e.target.value)} placeholder="37.0"
                   className={inputClass}
                 />
               </div>
               <div className="space-y-1">
                 <label className={labelClass}>Duration (Days)</label>
                 <input 
                   type="number" min="0" value={duration} onChange={e => setDuration(e.target.value)} placeholder="0"
                   className={inputClass}
                 />
               </div>
            </div>

            <div className="space-y-1">
              <label className={labelClass}>Patient Symptoms / Report</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Barking cough, lethargy, persistent vomiting..."
                className={`${inputClass} h-40 resize-none italic font-bold leading-relaxed`}
              />
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-6">
              <input type="file" accept="image/*" capture="environment" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 px-10 py-5 rounded-2xl font-black border-2 text-xs uppercase tracking-widest w-full sm:w-auto transition-all bg-white border-slate-400 text-slate-900 hover:bg-slate-50 shadow-sm">
                {image ? '📷 Retake Photo' : '📷 Take Triage Photo'}
              </button>
              <button 
                onClick={handleAnalyze} 
                disabled={loading || (!description.trim() && !image)} 
                className={`flex-1 py-5 rounded-2xl font-black text-white shadow-2xl transition-all uppercase tracking-widest text-sm w-full flex items-center justify-center gap-3 ${loading ? 'bg-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'}`}
              >
                {loading ? (
                  <>
                    <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                    Synthesizing Guidelines...
                  </>
                ) : 'Analyze Symptoms ✨'}
              </button>
            </div>

            {image && (
              <div className="relative w-full max-w-md mx-auto animate-in zoom-in-95 pt-4">
                <img src={image} alt="Symptom" className="w-full h-80 object-cover rounded-[2.5rem] border-4 border-white shadow-2xl" />
                <button onClick={() => setImage(null)} className="absolute top-8 right-4 bg-white text-rose-600 w-12 h-12 rounded-full flex items-center justify-center shadow-2xl font-black text-xl border-2 border-rose-100 hover:bg-rose-50 transition-colors">✕</button>
              </div>
            )}
          </div>

          {result && (
            <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 animate-in slide-in-from-bottom-8 duration-700 relative overflow-hidden flex flex-col">
              {/* Professional Branding & Header */}
              <div className="bg-slate-900 p-8 sm:p-12 text-white relative">
                 <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full opacity-20 blur-[80px]"></div>
                 <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 relative z-10">
                    <div className="flex items-center gap-5">
                      <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center text-4xl shadow-inner border border-white/10">🛡️</div>
                      <div>
                        <h3 className="text-3xl font-black italic tracking-tighter leading-none uppercase">Clinical Synthesis</h3>
                        <div className="flex items-center gap-2 mt-3">
                           <span className="text-[9px] font-black uppercase tracking-widest text-indigo-400 bg-indigo-500/10 px-2 py-1 rounded">RCH Standard Aligned</span>
                           <span className="text-[9px] font-black uppercase tracking-widest text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded">Decision Support Only</span>
                        </div>
                      </div>
                    </div>
                    <button 
                      onClick={handleSaveToLogs} 
                      disabled={saved} 
                      className={`px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all ${saved ? 'bg-emerald-600' : 'bg-indigo-600 hover:bg-indigo-500'}`}
                    >
                      {saved ? '✓ Profile Synced' : 'Sync to Medical Hub'}
                    </button>
                 </div>
              </div>

              {/* Triage Level Diagram */}
              <div className="px-10 sm:px-12 py-8 bg-slate-50 border-b border-slate-100">
                 <div className="flex justify-between items-end mb-4">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Calculated Urgency Level</p>
                    <p className={`text-sm font-black italic ${triageLevel.color.replace('bg-', 'text-')}`}>{triageLevel.text}</p>
                 </div>
                 <div className="h-6 w-full bg-slate-200 rounded-full overflow-hidden shadow-inner flex">
                    <div className={`${triageLevel.color} h-full transition-all duration-1000 ease-out flex items-center justify-center text-white text-[10px] font-black shadow-lg ${triageLevel.width}`}>
