                      const isList = line.match(/^[-•]/);
                      return (
                        <div key={idx} className={`${isList ? 'ml-6' : ''}`}>
                           {isBold ? (
                              <div className="bg-amber-50/50 p-6 rounded-3xl border border-amber-100 shadow-sm">
                                <h5 className="text-xl font-black text-amber-950 uppercase tracking-tight mb-2 flex items-center gap-2">
                                   <span className="w-3 h-3 rounded-full bg-amber-500"></span>
                                   {line.replace(/\*\*/g, '')}
                                </h5>
                              </div>
                           ) : isList ? (
                              <div className="flex gap-4 items-start py-2">
                                 <span className="w-2 h-2 rounded-full bg-amber-200 mt-2 shrink-0 shadow-sm"></span>
                                 <p className="text-lg font-black italic text-slate-700 leading-relaxed">
                                    {line.replace(/^[-•]\s*/, '')}
                                 </p>
                              </div>
                           ) : (
                              <p className="text-xl font-black italic text-slate-800 leading-relaxed pl-8 border-l-4 border-slate-100">
                                 {line}
                              </p>
                           )}
                        </div>
                      );
                   })}
                </div>

                {advice.sources.length > 0 && (
                  <div className="pt-10 mt-16 border-t border-slate-100 space-y-4 relative z-10">
                    <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest">Guideline Registry</p>
                    <div className="flex flex-wrap gap-3">
                      {advice.sources.map((s: any, i: number) => (
                        <a key={i} href={s.web?.uri} target="_blank" rel="noopener noreferrer" className="text-[10px] font-black text-slate-400 hover:text-amber-600 bg-white px-5 py-2.5 rounded-2xl border-2 border-slate-100 transition-all flex items-center gap-2 shadow-sm group">
                          {s.web?.title || 'Health Resource'} <span className="text-xs transition-transform group-hover:translate-x-1">↗</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                <div className="mt-12 pt-8 border-t border-slate-50 opacity-40">
                   <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest text-center italic">
                      Disclaimer: This strategy is for educational support only. <br/> Consult a professional for complex behavioral concerns.
                   </p>
                </div>
              </div>
            ) : (
              <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-slate-50/50 border-4 border-dashed border-slate-200 rounded-[4rem] text-center p-12 space-y-6">
                <div className="w-24 h-24 bg-white rounded-[2rem] flex items-center justify-center text-5xl shadow-sm grayscale opacity-30">🌻</div>
                <div className="max-w-sm">
                  <h4 className="font-black text-slate-800 text-xl tracking-tight mb-2 uppercase italic">Strategy Lab</h4>
                  <p className="text-slate-600 font-bold italic">Describe a parenting challenge or select a clinical module to receive tailored synthesis.</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'mentalhealth' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="bg-indigo-900 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
            <h3 className="text-3xl font-black italic tracking-tighter mb-4 relative z-10">Professional Support Registry</h3>
            <p className="text-indigo-100 font-medium italic opacity-80 max-w-2xl relative z-10">
              Validated Australian mental health and developmental resources for families.
            </p>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {MENTAL_HEALTH_RESOURCES.map((res, i) => (
              <a 
                key={i} 
                href={res.url} 
                target="_blank" 
                rel="noopener noreferrer"
                className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all group"
              >
                <div className="flex justify-between items-start mb-6">
                  <div className="flex flex-wrap gap-2">
                    {res.tags.map(tag => (
                      <span key={tag} className="px-3 py-1 bg-indigo-50 text-indigo-600 rounded-full text-[8px] font-black uppercase tracking-widest border border-indigo-100">
                        {tag}
                      </span>
                    ))}
                  </div>
                  <span className="text-slate-300 group-hover:text-indigo-600 transition-colors">↗</span>
                </div>
                <h4 className="text-2xl font-black text-slate-800 mb-2 group-hover:text-indigo-600 transition-colors">{res.name}</h4>
                <p className="text-slate-500 font-medium italic text-sm leading-relaxed">{res.desc}</p>
              </a>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'clinical' && (
        <div className="space-y-10 animate-in slide-in-from-bottom-4 duration-500">
          <div className="bg-teal-900 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
            <h3 className="text-3xl font-black italic tracking-tighter mb-4 relative z-10">Evidence-Based Frameworks</h3>
            <p className="text-teal-100 font-medium italic opacity-80 max-w-2xl relative z-10">
              Understanding the clinical models used by pediatricians and child psychologists.
            </p>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {CLINICAL_MODULES.map((mod, i) => (
              <div key={i} className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-col justify-between group hover:shadow-xl transition-all">
                <div className="space-y-6">
                  <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center text-4xl shadow-inner group-hover:scale-110 transition-transform">
                    {mod.icon}
                  </div>
                  <div>
                    <p className="text-[9px] font-black text-teal-600 uppercase tracking-[0.2em] mb-2">{mod.focus}</p>
                    <h4 className="text-2xl font-black text-slate-800 leading-tight mb-4">{mod.title}</h4>
                    <p className="text-slate-500 font-medium italic text-sm leading-relaxed">{mod.desc}</p>
                  </div>
                </div>
                <div className="mt-10 pt-6 border-t border-slate-50">
                   <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Model of Care</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { ConsultationNote, ClinicalFindings, AssignedTest } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { GoogleGenAI } from "@google/genai";

const SCREENING_MODS = [
  { id: 'snap4', name: 'SNAP-IV (ADHD)', domain: 'Focus' },
  { id: 'mchat', name: 'M-CHAT-R (Autism)', domain: 'Social' },
  { id: 'asq3', name: 'ASQ-3 (Development)', domain: 'Development' },
  { id: 'gad7', name: 'GAD-7 (Anxiety)', domain: 'Mood' },
  { id: 'phq9', name: 'PHQ-9 (Mood/Depression)', domain: 'Mood' },
  { id: 'sdq', name: 'SDQ (Behavior)', domain: 'Behavior' },
];

const REASONING_FRAMEWORKS = [
  { id: 'standard', name: 'Standard Clinical', desc: 'General differential ranking' },
  { id: 'vindicate', name: 'VINDICATE', desc: 'Vascular, Infectious, Neoplastic, Degenerative, etc.' },
  { id: 'vitamins', name: 'VITAMINS', desc: 'Vascular, Infectious, Traumatic, Autoimmune, etc.' },
  { id: 'surgical_sieve', name: 'Surgical Sieve', desc: 'Anatomical vs Pathological mapping' },
];

const CLINICAL_SHORTHAND = {
  general: ['Alert/Active', 'Well Appearance', 'Mildly Unwell', 'NAD', 'Euvolaemic'],
  respiratory: ['Chest Clear', 'Symmetrical Expansion', 'No Wheeze/Stridor', 'Air Entry + Bilat', 'No Distressed Signs'],
  cardiac: ['HS I + II + 0', 'Femoral Pulps + Bilat', 'Cap Refill < 2s', 'Rhythm Regular'],
  abdominal: ['Soft/Non-tender', 'No Masses', 'BS + Active', 'No Guarding'],
  neurological: ['Tone Normal', 'Pupils PERL', 'GCS 15', 'No Focal Deficits'],
  skin: ['No Rashes', 'Warm/Pink', 'Skin Turgor Normal', 'No Petechiae']
};

export const ClinicianTools: React.FC<{ type: 'consults' | 'reasoning' | 'assignments' }> = ({ type }) => {
  const { history, updateHistory } = useMedicalHistory();
  const [loading, setLoading] = useState(false);
  const [reasoningResult, setReasoningResult] = useState<{text: string, sources: any[]} | null>(null);
  const [activeFramework, setActiveFramework] = useState('standard');
  const [activeInputTab, setActiveInputTab] = useState<'history' | 'exam' | 'investigations'>('history');

  const assignedTests = history.assignedTests || [];

  const [newSoap, setNewSoap] = useState<Partial<ConsultationNote>>({
    clinicianName: '', subjective: '', objective: '', assessment: '', plan: ''
  });

  const [findings, setFindings] = useState<{
    history: string;
    exam: {
      general: string;
      respiratory: string;
      cardiac: string;
      abdominal: string;
      neurological: string;
      skin: string;
    };
    investigations: string;
    vitals: { hr?: string; rr?: string; temp?: string; o2?: string; bp?: string; glu?: string };
  }>({
    history: '',
    exam: { general: '', respiratory: '', cardiac: '', abdominal: '', neurological: '', skin: '' },
    investigations: '',
    vitals: {}
  });

  const injectShorthand = (section: keyof typeof findings.exam, term: string) => {
    setFindings(prev => ({
      ...prev,
      exam: {
        ...prev.exam,
        [section]: prev.exam[section] ? `${prev.exam[section]}, ${term}` : term
      }
    }));
  };

  const toggleTestAssignment = (testId: string) => {
    const isAssigned = assignedTests.some(t => t.testId === testId);
    let next: AssignedTest[];
    if (isAssigned) {
      next = assignedTests.filter(t => t.testId !== testId);
    } else {
      next = [...assignedTests, { testId, assignedDate: new Date().toISOString(), status: 'pending' }];
    }
    updateHistory({ assignedTests: next });
  };

  const handleAddConsult = () => {
    if (!newSoap.assessment || !newSoap.plan) return;
    const consult: ConsultationNote = {
      ...newSoap,
      id: crypto.randomUUID(),
      date: new Date().toISOString()
    } as ConsultationNote;
    updateHistory({ formalConsults: [consult, ...(history.formalConsults || [])] });
    setNewSoap({ clinicianName: '', subjective: '', objective: '', assessment: '', plan: '' });
  };

  const handleRunReasoning = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const frameworkInstruction = 
        activeFramework === 'vindicate' ? "Use the VINDICATE acronym to structure your differential." :
        activeFramework === 'vitamins' ? "Use the VITAMINS mnemonic to structure your differential." :
        activeFramework === 'surgical_sieve' ? "Apply a Surgical Sieve approach." : 
        "Provide a prioritized differential list.";

      const prompt = `Act as a senior pediatric consultant. Analyze this clinical presentation.
      FRAMEWORK: ${frameworkInstruction}
      PATIENT: PMHx: ${history.pastMedicalHistory}, Meds: ${history.currentMedications.map(m => m.name).join(', ')}
      HISTORY: ${findings.history}
      VITALS: HR: ${findings.vitals.hr}, RR: ${findings.vitals.rr}, SpO2: ${findings.vitals.o2}, Temp: ${findings.vitals.temp}, BP: ${findings.vitals.bp}, BSL: ${findings.vitals.glu}
      EXAM: Gen: ${findings.exam.general}, Resp: ${findings.exam.respiratory}, CVS: ${findings.exam.cardiac}, Abdo: ${findings.exam.abdominal}, CNS: ${findings.exam.neurological}, Skin: ${findings.exam.skin}
      TESTS: ${findings.investigations}
      REQUIREMENTS: 1. Differential 2. Red Flags 3. Plan 4. Evidence (EBM). Format clearly with numbered sections.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
      });
      setReasoningResult({
        text: response.text || 'Synthesis failed.',
        sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
      });
    } catch (e) {
      alert("Error generating reasoning.");
    } finally {
      setLoading(false);
    }
  };

  if (type === 'assignments') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Assignment <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Curate specific assessments for the caregiver to complete before review.</p>
        </header>

        <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">📋</div>
              <div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight">Instrument Selection</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Pre-Appointment Clinical Pack</p>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {SCREENING_MODS.map(test => {
                const assignment = assignedTests.find(t => t.testId === test.id);
                const isAssigned = !!assignment;
                const isCompleted = assignment?.status === 'completed';

                return (
                  <button 
                    key={test.id}
                    onClick={() => toggleTestAssignment(test.id)}
                    className={`p-8 rounded-[3rem] border-2 text-left transition-all relative group flex flex-col justify-between h-48 ${
                      isCompleted ? 'bg-emerald-50 border-emerald-500' :
                      isAssigned ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-105' : 
                      'bg-slate-50 border-slate-100 hover:border-indigo-300 hover:bg-white'
                    }`}
                  >
                    <div>
                      <div className="flex justify-between items-start mb-2">
                        <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full ${isAssigned ? 'bg-white/20' : 'bg-slate-200 text-slate-500'}`}>{test.domain}</span>
                        {isCompleted && <span className="text-emerald-600 text-xs font-black">✓ Done</span>}
                      </div>
                      <h4 className={`text-xl font-black tracking-tight leading-none ${isAssigned && !isCompleted ? 'text-white' : 'text-slate-800'}`}>{test.name}</h4>
                    </div>

                    <div className="flex items-center justify-between mt-4">
                      <span className={`text-[10px] font-black uppercase tracking-widest ${isAssigned && !isCompleted ? 'text-indigo-100' : 'text-slate-400'}`}>
                        {isCompleted ? 'Finished' : isAssigned ? 'Assigned' : 'Click to Assign'}
                      </span>
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-transform group-hover:scale-110 ${isAssigned ? 'bg-white text-indigo-600 shadow-lg' : 'bg-slate-200 text-slate-400'}`}>
                        {isAssigned ? '✓' : '+'}
                      </div>
                    </div>
                  </button>
                );
              })}
           </div>
        </div>
      </div>
    );
  }

  if (type === 'consults') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">SOAP <span className="text-indigo-600">Consultations</span></h2>
          <p className="text-slate-500 font-medium italic">Formal clinical documentation for professional record keeping.</p>
        </header>

        <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Subjective (S)</label>
                <textarea value={newSoap.subjective} onChange={e => setNewSoap({...newSoap, subjective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 font-bold italic text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Patient's report..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Objective (O)</label>
                <textarea value={newSoap.objective} onChange={e => setNewSoap({...newSoap, objective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-100 font-bold italic text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Vitals, physical exam..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Assessment (A)</label>
                <textarea value={newSoap.assessment} onChange={e => setNewSoap({...newSoap, assessment: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-indigo-50/30 border border-indigo-100 font-bold italic text-indigo-900 outline-none focus:ring-4 focus:ring-indigo-100" placeholder="Diagnosis..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Plan (P)</label>
                <textarea value={newSoap.plan} onChange={e => setNewSoap({...newSoap, plan: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-emerald-50/30 border border-emerald-100 font-bold italic text-emerald-900 outline-none focus:ring-4 focus:ring-emerald-100" placeholder="Next steps..." />
             </div>
          </div>
          <div className="flex justify-between items-center pt-8 border-t border-slate-50">
             <input value={newSoap.clinicianName} onChange={e => setNewSoap({...newSoap, clinicianName: e.target.value})} placeholder="Clinician Name" className="p-4 bg-slate-50 rounded-xl font-black text-xs outline-none" />
             <button onClick={handleAddConsult} className="px-10 py-5 bg-indigo-600 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-700">Record Formal Consult</button>
          </div>
        </section>

        <section className="space-y-6">
           <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Clinical Archive</h3>
           <div className="space-y-6">
              {(history.formalConsults || []).map(note => (
                <div key={note.id} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-6">
                   <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                      <div>
                         <p className="text-xl font-black text-slate-800 italic">Consultation Note</p>
                         <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Clinician: {note.clinicianName}</p>
                      </div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(note.date).toLocaleDateString()}</p>
                   </div>
                   <div className="grid grid-cols-2 gap-8">
                      <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Subjective</p><p className="text-sm font-medium italic text-slate-600">"{note.subjective}"</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Objective</p><p className="text-sm font-medium italic text-slate-600">"{note.objective}"</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-indigo-400 uppercase">Assessment</p><p className="text-sm font-black text-slate-800">{note.assessment}</p></div>
                      <div className="space-y-1"><p className="text-[9px] font-black text-emerald-400 uppercase">Plan</p><p className="text-sm font-black text-slate-800">{note.plan}</p></div>
                   </div>
                </div>
              ))}
           </div>
        </section>
      </div>
    );
  }

  return (
    <div className="space-y-12 pb-24 animate-in fade-in">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Reasoning <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Advanced AI-augmented differential diagnosis assistant.</p>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-200 shadow-inner">
           {REASONING_FRAMEWORKS.map(f => (
             <button
              key={f.id}
              onClick={() => setActiveFramework(f.id)}
              className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${activeFramework === f.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
             >
               {f.name}
             </button>
           ))}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
         <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8 h-fit">
            <nav className="flex gap-4 border-b border-slate-50 pb-4">
               {['history', 'exam', 'investigations'].map(tab => (
                 <button 
                  key={tab} 
                  onClick={() => setActiveInputTab(tab as any)}
                  className={`text-[10px] font-black uppercase tracking-[0.2em] pb-2 border-b-4 transition-all ${activeInputTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-300'}`}
                 >
                   {tab}
                 </button>
               ))}
            </nav>

            <div className="space-y-6">
               {activeInputTab === 'history' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Clinical History Highlights</label>
                      <textarea value={findings.history} onChange={e => setFindings({...findings, history: e.target.value})} className="w-full h-32 p-5 rounded-2xl bg-slate-50 font-bold italic outline-none border border-slate-100 focus:ring-2 focus:ring-indigo-50 shadow-inner" placeholder="Onset, character, associated symptoms..." />
                    </div>
                    <div className="grid grid-cols-3 gap-4">
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">HR</label>
                        <input placeholder="e.g. 110" value={findings.vitals.hr} onChange={e => setFindings({...findings, vitals: {...findings.vitals, hr: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">RR</label>
                        <input placeholder="e.g. 24" value={findings.vitals.rr} onChange={e => setFindings({...findings, vitals: {...findings.vitals, rr: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-400 uppercase ml-2">SpO2</label>
                        <input placeholder="e.g. 98%" value={findings.vitals.o2} onChange={e => setFindings({...findings, vitals: {...findings.vitals, o2: e.target.value}})} className="w-full p-4 bg-slate-50 rounded-xl font-black text-xs border border-slate-100 outline-none" />
                      </div>
