export const MilestoneNavigator: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);
  const [showAddCustom, setShowAddCustom] = useState(false);
  const [customMilestone, setCustomMilestone] = useState<Partial<Milestone>>({ description: '', category: 'Motor' });

  useEffect(() => {
    if (!history.milestones || history.milestones.length === 0) {
      updateHistory({ milestones: INITIAL_DATA });
    }
  }, [history.milestones, updateHistory]);

  const milestones = history.milestones || [];

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    updateHistory({ milestones: updated });

    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed) {
      addClinicalEvent({ 
        source: 'Developmental Alert', 
        description: `QCH Red Flag Identified (${item.ageRange}): ${item.description.split('. Example:')[0]}`, 
        date: new Date().toLocaleDateString(), 
        severity: 'High' 
      });
    }
  };

  const updateNotes = (id: string, notes: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, notes } : m);
    updateHistory({ milestones: updated });
  };

  const handleAddCustom = () => {
    if (!customMilestone.description) return;
    const newM: Milestone = {
      id: crypto.randomUUID(),
      ageRange: activeAge,
      category: customMilestone.category as any,
      description: customMilestone.description,
      completed: true,
      isRedFlag: false,
      notes: ''
    };
    updateHistory({ milestones: [...milestones, newM] });
    setCustomMilestone({ description: '', category: 'Motor' });
    setShowAddCustom(false);
  };

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', 'All Ages'];

  const filteredData = useMemo(() => {
    return milestones.filter(m => m.ageRange === activeAge && m.isRedFlag === showRedFlags);
  }, [milestones, activeAge, showRedFlags]);

  const CategoryBadge = ({ category }: { category: string }) => {
    const colors: Record<string, string> = {
      Motor: 'bg-blue-50 text-blue-600 border-blue-100',
      Language: 'bg-purple-50 text-purple-600 border-purple-100',
      Social: 'bg-pink-50 text-pink-600 border-pink-100',
      Cognitive: 'bg-amber-50 text-amber-600 border-amber-100',
    };
    return <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest border ${colors[category] || 'bg-slate-50 text-slate-500 border-slate-100'}`}>{category}</span>;
  };

  return (
    <div className="space-y-8 pb-32 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row justify-between items-start gap-6 px-1">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter italic leading-none">Milestone <span className="text-teal-600">Sync</span></h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-slate-500 text-sm font-medium italic">Standardized clinical markers.</p>
            <a 
              href="https://www.childrens.health.qld.gov.au/__data/assets/pdf_file/0026/167093/red-flags.pdf" 
              target="_blank" 
              rel="noopener noreferrer"
              className="text-[9px] font-black text-teal-600 bg-teal-50 px-2 py-1 rounded border border-teal-100 uppercase tracking-widest hover:bg-teal-100 transition-colors"
            >
              Source: QCH Red Flags ↗
            </a>
          </div>
        </div>
        <button 
          onClick={() => setShowAddCustom(!showAddCustom)}
          className="bg-white border-2 border-teal-100 text-teal-600 px-8 py-4 rounded-[1.5rem] font-black text-[11px] uppercase tracking-widest hover:bg-teal-50 shadow-sm transition-all"
        >
          {showAddCustom ? 'Cancel' : '+ Custom Marker'}
        </button>
      </header>

      {showAddCustom && (
        <div className="bg-teal-50 p-10 rounded-[3.5rem] border border-teal-100 animate-in zoom-in-95 space-y-6">
           <h3 className="text-2xl font-black text-teal-900 italic">Custom Observation for {activeAge}</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-teal-600 uppercase tracking-widest ml-4">What was observed?</label>
                <input 
                  placeholder="e.g. Points to birds, says 'Dada'..." 
                  value={customMilestone.description}
                  onChange={e => setCustomMilestone({...customMilestone, description: e.target.value})}
                  className="w-full p-5 rounded-2xl bg-white border border-teal-200 font-black text-slate-900 outline-none shadow-inner"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-teal-600 uppercase tracking-widest ml-4">Category</label>
                <select 
                  value={customMilestone.category}
                  onChange={e => setCustomMilestone({...customMilestone, category: e.target.value as any})}
                  className="w-full p-5 rounded-2xl bg-white border border-teal-200 font-black text-slate-900 outline-none shadow-inner"
                >
                  <option>Motor</option>
                  <option>Social</option>
                  <option>Language</option>
                  <option>Cognitive</option>
                </select>
              </div>
           </div>
           <button onClick={handleAddCustom} className="w-full py-5 bg-teal-600 text-white rounded-[1.5rem] font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-teal-700 active:scale-95 transition-all">Record Milestone ✨</button>
        </div>
      )}

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-4 overflow-x-auto no-scrollbar border-b border-slate-100">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm min-w-max">
          {ageGroups.map(age => (
            <button key={age} onClick={() => setActiveAge(age)} className={`px-6 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeAge === age ? 'bg-teal-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>{age}</button>
          ))}
        </div>
      </nav>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm max-w-sm">
        <button onClick={() => setShowRedFlags(false)} className={`flex-1 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-teal-50 text-teal-700' : 'text-slate-400'}`}>Typical Progress</button>
        <button onClick={() => setShowRedFlags(true)} className={`flex-1 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-900 text-white shadow-lg' : 'text-slate-400'}`}>Clinical Red Flags</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-8">
        {filteredData.length > 0 ? filteredData.map(m => {
          const parts = m.description.split('. Example:');
          const title = parts[0];
          const example = parts[1];

          return (
            <div 
              key={m.id}
              className={`rounded-[3.5rem] border-2 transition-all flex flex-col overflow-hidden shadow-sm group ${
                m.completed 
                  ? (showRedFlags ? 'bg-rose-100 border-rose-900 shadow-rose-200 shadow-2xl scale-[1.02]' : 'bg-emerald-50 border-emerald-200 shadow-xl scale-[1.01]') 
                  : 'bg-white border-slate-100 hover:border-teal-100'
              }`}
            >
              <div className="p-8 md:p-10 flex flex-col h-full gap-6">
                <div className="flex justify-between items-start">
                  <div className="flex flex-col gap-2">
                    <CategoryBadge category={m.category} />
                    {m.isRedFlag && (
                        <span className="bg-rose-600 text-white text-[8px] font-black uppercase tracking-[0.2em] px-2 py-0.5 rounded-full w-fit animate-pulse">QCH Clinical Alert</span>
                    )}
                  </div>
                  <button 
                    onClick={() => toggleMilestone(m.id)}
                    className={`w-16 h-16 rounded-[2rem] border-4 flex items-center justify-center transition-all ${
                      m.completed 
                        ? (showRedFlags ? 'bg-rose-900 border-white text-white rotate-[360deg]' : 'bg-emerald-600 border-white text-white rotate-[360deg]') 
                        : 'bg-slate-50 border-slate-100 text-slate-200 hover:border-teal-200 hover:bg-white active:scale-90 shadow-inner'
                    }`}
                  >
                    {m.completed ? <span className="font-black text-2xl">✓</span> : null}
                  </button>
                </div>

                <div className="flex-1 space-y-4">
                  <p className={`text-2xl font-black leading-tight tracking-tight ${showRedFlags ? 'text-rose-950 underline decoration-rose-300' : 'text-slate-800'}`}>
                    {title}
                  </p>
                  {example && (
                    <p className={`text-sm font-bold italic leading-relaxed ${showRedFlags ? 'text-rose-800/70' : 'text-slate-400'}`}>
                      "Example: {example}"
                    </p>
                  )}
                </div>

                <div className={`pt-6 border-t space-y-2 ${showRedFlags ? 'border-rose-200' : 'border-slate-100'}`}>
                   <label className={`text-[9px] font-black uppercase tracking-widest ml-4 ${showRedFlags ? 'text-rose-400' : 'text-slate-400'}`}>Observation Notes (Free Text)</label>
                   <textarea 
                    value={m.notes || ''}
                    onChange={e => updateNotes(m.id, e.target.value)}
