                  className="w-full p-5 rounded-2xl bg-white border border-teal-200 font-black text-slate-900 outline-none shadow-inner"
                >
                  <option>Motor</option>
                  <option>Social</option>
                  <option>Language</option>
                  <option>Cognitive</option>
                </select>
              </div>
           </div>
           <button onClick={handleAddCustom} className="w-full py-5 bg-teal-600 text-white rounded-[1.5rem] font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-teal-700 active:scale-95 transition-all">Record Milestone ✨</button>
        </div>
      )}

      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-md py-4 overflow-x-auto no-scrollbar border-b border-slate-100">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm min-w-max">
          {ageGroups.map(age => (
            <button key={age} onClick={() => setActiveAge(age)} className={`px-6 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeAge === age ? 'bg-teal-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>{age}</button>
          ))}
        </div>
      </nav>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm max-w-sm">
        <button onClick={() => setShowRedFlags(false)} className={`flex-1 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-teal-50 text-teal-700' : 'text-slate-400'}`}>Typical Progress</button>
        <button onClick={() => setShowRedFlags(true)} className={`flex-1 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-900 text-white shadow-lg' : 'text-slate-400'}`}>Clinical Red Flags</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-8">
        {filteredData.length > 0 ? filteredData.map(m => {
          const parts = m.description.split('. Example:');
          const title = parts[0];
          const example = parts[1];

          return (
            <div 
              key={m.id}
              className={`rounded-[3.5rem] border-2 transition-all flex flex-col overflow-hidden shadow-sm group ${
                m.completed 
                  ? (showRedFlags ? 'bg-rose-100 border-rose-900 shadow-rose-200 shadow-2xl scale-[1.02]' : 'bg-emerald-50 border-emerald-200 shadow-xl scale-[1.01]') 
                  : 'bg-white border-slate-100 hover:border-teal-100'
              }`}
            >
              <div className="p-8 md:p-10 flex flex-col h-full gap-6">
                <div className="flex justify-between items-start">
