export const MilestoneNavigator: React.FC = () => {
  const { history, updateHistory, addClinicalEvent } = useMedicalHistory();
  const [activeAge, setActiveAge] = useState('6-8 Weeks');
  const [showRedFlags, setShowRedFlags] = useState(false);
  const [selectedDomain, setSelectedDomain] = useState<'All' | 'Motor' | 'Cognitive' | 'Social' | 'Language'>('All');
  const [showAddCustom, setShowAddCustom] = useState(false);
  const [customMilestone, setCustomMilestone] = useState<Partial<Milestone>>({ description: '', category: 'Motor' });

  useEffect(() => {
    if (!history.milestones || history.milestones.length === 0) {
      updateHistory({ milestones: INITIAL_DATA });
    }
  }, [history.milestones, updateHistory]);

  const milestones = history.milestones || [];

  const ageGroups = ['6-8 Weeks', '4 Months', '6 Months', '9 Months', '12 Months', '18 Months', '2 Years', '3 Years', '4 Years', '5 Years', 'All Ages'];
  const domains = ['All', 'Motor', 'Cognitive', 'Social', 'Language'];

  const completionStats = useMemo(() => {
    return ageGroups.reduce((acc, age) => {
      const group = milestones.filter(m => m.ageRange === age && !m.isRedFlag);
      const completed = group.filter(m => m.completed).length;
      acc[age] = { completed, total: group.length };
      return acc;
    }, {} as Record<string, { completed: number; total: number }>);
  }, [milestones]);

  const toggleMilestone = (id: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, completed: !m.completed } : m);
    updateHistory({ milestones: updated });

    const item = updated.find(x => x.id === id);
    if (item?.isRedFlag && item.completed) {
      addClinicalEvent({ 
        source: 'Developmental Alert', 
        description: `QCH Red Flag Identified (${item.ageRange}): ${item.description.split('. Example:')[0]}`, 
        date: new Date().toLocaleDateString(), 
        severity: 'High' 
      });
    }
  };

  const updateNotes = (id: string, notes: string) => {
    const updated = milestones.map(m => m.id === id ? { ...m, notes } : m);
    updateHistory({ milestones: updated });
  };

  const handleAddCustom = () => {
    if (!customMilestone.description) return;
    const newM: Milestone = {
      id: crypto.randomUUID(),
      ageRange: activeAge,
      category: customMilestone.category as any,
      description: customMilestone.description,
      completed: true,
      isRedFlag: false,
      notes: ''
    };
    updateHistory({ milestones: [...milestones, newM] });
    setCustomMilestone({ description: '', category: 'Motor' });
    setShowAddCustom(false);
  };

  const filteredData = useMemo(() => {
    return milestones.filter(m => 
      m.ageRange === activeAge && 
      m.isRedFlag === showRedFlags &&
      (selectedDomain === 'All' || m.category === selectedDomain)
    );
  }, [milestones, activeAge, showRedFlags, selectedDomain]);

  const CategoryBadge = ({ category }: { category: string }) => {
    const colors: Record<string, string> = {
      Motor: 'bg-blue-50 text-blue-600 border-blue-100',
      Language: 'bg-purple-50 text-purple-600 border-purple-100',
      Social: 'bg-pink-50 text-pink-600 border-pink-100',
      Cognitive: 'bg-amber-50 text-amber-600 border-amber-100',
    };
    return <span className={`px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest border shadow-sm ${colors[category] || 'bg-slate-50 text-slate-500 border-slate-100'}`}>{category}</span>;
  };

  return (
    <div className="space-y-10 pb-32 animate-in fade-in duration-700">
      {/* Header Section */}
      <header className="flex flex-col md:flex-row justify-between items-start gap-8 px-2">
        <div className="space-y-2">
          <div className="flex items-center gap-4">
             <div className="w-14 h-14 bg-teal-600 rounded-2xl flex items-center justify-center text-3xl shadow-xl rotate-[-3deg]">✨</div>
             <h2 className="text-5xl font-black text-slate-800 tracking-tighter italic">Milestone <span className="text-teal-600">Sync</span></h2>
          </div>
          <div className="flex items-center gap-3 pt-2">
            <p className="text-slate-500 font-bold italic">Grounded in Queensland Children's Health standards.</p>
            <a 
              href="https://www.childrens.health.qld.gov.au/__data/assets/pdf_file/0026/167093/red-flags.pdf" 
              target="_blank" 
              rel="noopener noreferrer"
              className="px-3 py-1 bg-teal-50 text-teal-600 text-[10px] font-black uppercase rounded-lg border border-teal-100 hover:bg-teal-100 transition-colors"
            >
              QCH Source ↗
            </a>
          </div>
        </div>
        <button 
          onClick={() => setShowAddCustom(!showAddCustom)}
          className="w-full md:w-auto bg-white border-2 border-teal-100 text-teal-600 px-10 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest hover:bg-teal-50 shadow-xl transition-all active:scale-95"
        >
          {showAddCustom ? 'Cancel Entry' : '+ Record Observation'}
        </button>
      </header>

      {/* Custom Entry Panel */}
      {showAddCustom && (
        <div className="bg-teal-50/50 p-12 rounded-[4rem] border-2 border-teal-100 animate-in zoom-in-95 space-y-8 shadow-2xl">
           <h3 className="text-3xl font-black text-teal-900 italic tracking-tight">Log Private Observation for {activeAge}</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-teal-600 uppercase tracking-[0.2em] ml-4">Behavior or Achievement</label>
                <input 
                  placeholder="e.g. Points to birds, says 'Dada'..." 
                  value={customMilestone.description}
                  onChange={e => setCustomMilestone({...customMilestone, description: e.target.value})}
                  className="w-full p-6 rounded-3xl bg-white border-2 border-teal-200 font-black text-slate-900 outline-none shadow-inner focus:border-teal-500 transition-colors"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-teal-600 uppercase tracking-[0.2em] ml-4">Developmental Category</label>
                <select 
                  value={customMilestone.category}
                  onChange={e => setCustomMilestone({...customMilestone, category: e.target.value as any})}
                  className="w-full p-6 rounded-3xl bg-white border-2 border-teal-200 font-black text-slate-900 outline-none shadow-inner appearance-none cursor-pointer"
                >
                  <option>Motor</option>
                  <option>Social</option>
                  <option>Language</option>
                  <option>Cognitive</option>
                </select>
              </div>
           </div>
           <button onClick={handleAddCustom} className="w-full py-6 bg-teal-600 text-white rounded-[2rem] font-black text-sm uppercase tracking-[0.3em] shadow-2xl hover:bg-teal-700 active:scale-95 transition-all">Synchronize to Hub ✨</button>
        </div>
      )}

      {/* Age Group Slider */}
      <nav className="sticky top-[58px] md:top-0 z-40 bg-[#FBFBFE]/90 backdrop-blur-xl py-6 overflow-x-auto no-scrollbar border-b border-slate-100 flex items-center gap-4 px-2">
        <div className="flex bg-white p-2 rounded-[2.5rem] border-2 border-slate-100 shadow-lg min-w-max">
          {ageGroups.map(age => {
            const stats = completionStats[age] || { completed: 0, total: 0 };
            const isActive = activeAge === age;
            const isDone = stats.total > 0 && stats.completed === stats.total;
            return (
              <button 
                key={age} 
                onClick={() => setActiveAge(age)} 
                className={`px-8 py-4 rounded-[2rem] text-[11px] font-black uppercase tracking-widest transition-all flex items-center gap-3 ${
                  isActive 
                    ? 'bg-teal-600 text-white shadow-2xl scale-105' 
                    : 'text-slate-400 hover:bg-slate-50'
                }`}
              >
                <span>{age}</span>
                {stats.total > 0 && (
                  <span className={`px-2 py-0.5 rounded-lg text-[9px] ${isActive ? 'bg-white/20 text-white' : (isDone ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-100 text-slate-400')}`}>
                    {stats.completed}/{stats.total}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </nav>

      {/* Secondary Logic Filter */}
      <div className="flex flex-col md:flex-row gap-6 items-center justify-between px-2">
         <div className="flex bg-white p-1.5 rounded-[1.5rem] border-2 border-slate-100 shadow-sm w-full md:w-auto">
            <button onClick={() => setShowRedFlags(false)} className={`flex-1 md:px-8 py-3.5 rounded-xl font-black text-[11px] uppercase tracking-widest transition-all ${!showRedFlags ? 'bg-teal-50 text-teal-700' : 'text-slate-400'}`}>Standard Progress</button>
            <button onClick={() => setShowRedFlags(true)} className={`flex-1 md:px-8 py-3.5 rounded-xl font-black text-[11px] uppercase tracking-widest transition-all ${showRedFlags ? 'bg-rose-900 text-white shadow-lg' : 'text-slate-400'}`}>Clinical Red Flags</button>
         </div>

         <div className="flex bg-slate-50 p-1.5 rounded-[1.5rem] border-2 border-slate-100 shadow-inner w-full md:w-auto overflow-x-auto no-scrollbar">
            {domains.map(d => (
              <button 
                key={d} 
                onClick={() => setSelectedDomain(d as any)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedDomain === d ? 'bg-white text-slate-800 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {d}
              </button>
            ))}
         </div>
      </div>

      {/* Milestone Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-8 duration-700">
        {filteredData.length > 0 ? filteredData.map(m => {
          const parts = m.description.split('. Example:');
          const title = parts[0];
          const example = parts[1];

          return (
            <div 
              key={m.id}
              className={`rounded-[3.5rem] border-4 transition-all flex flex-col overflow-hidden group min-h-[400px] ${
                m.completed 
                  ? (showRedFlags ? 'bg-rose-100 border-rose-900 shadow-rose-200 shadow-2xl scale-[1.03]' : 'bg-emerald-50 border-emerald-300 shadow-xl') 
                  : 'bg-white border-slate-100 hover:border-teal-200 hover:shadow-2xl'
              }`}
            >
              <div className="p-10 flex flex-col h-full gap-8 relative overflow-hidden">
                {/* Decorative Pattern for Red Flags */}
                {showRedFlags && (
                  <div className="absolute top-0 right-0 w-32 h-32 bg-rose-200/20 rotate-45 translate-x-16 -translate-y-16 group-hover:scale-150 transition-transform duration-1000"></div>
                )}

                <div className="flex justify-between items-start z-10">
                  <div className="flex flex-col gap-2">
