                  </div>
                  <button 
                    onClick={() => toggleMilestone(m.id)}
                    className={`w-14 h-14 rounded-[1.75rem] border-4 flex items-center justify-center transition-all z-10 ${
                      m.completed 
                        ? (showRedFlags ? 'bg-rose-900 border-white text-white rotate-[360deg] shadow-lg' : 'bg-emerald-600 border-white text-white rotate-[360deg] shadow-lg') 
                        : 'bg-slate-50 border-slate-100 text-slate-200 hover:border-teal-300 hover:bg-white active:scale-90 shadow-inner'
                    }`}
                  >
                    {m.completed ? <span className="font-black text-2xl">✓</span> : null}
                  </button>
                </div>

                <div className="flex-1 space-y-6 z-10">
                  <p className={`text-2xl font-black leading-tight tracking-tight italic ${showRedFlags ? 'text-rose-950 underline decoration-rose-300' : 'text-slate-800'}`}>
                    {title}
                  </p>
                  {example && (
                    <div className={`p-5 rounded-[1.5rem] border-2 ${showRedFlags ? 'bg-white/40 border-rose-200' : 'bg-slate-50 border-slate-100'}`}>
                        <p className={`text-xs font-bold italic leading-relaxed ${showRedFlags ? 'text-rose-800' : 'text-slate-500'}`}>
                        "Example: {example}"
                        </p>
                    </div>
                  )}
                </div>

                <div className={`pt-6 border-t-2 z-10 space-y-3 ${showRedFlags ? 'border-rose-200' : 'border-slate-100'}`}>
