        <div className="space-y-6 relative z-10">
          <h4 className="text-3xl font-black italic uppercase tracking-tighter text-indigo-100">The Clinical Role of Red Flags</h4>
          <p className="text-indigo-50/70 text-lg font-medium italic leading-relaxed max-w-3xl">
            "Developmental red flags represent significant risks of longitudinal delay. These markers do not offer a diagnosis but signal the critical need for a child development referral. Early intervention is the primary driver of positive neurodevelopmental outcomes."
          </p>
          <div className="flex items-center justify-between border-t border-white/5 pt-6">
             <p className="text-[11px] font-black uppercase tracking-[0.4em] text-indigo-400">PediPulse Evidence Pipeline • Version 1.0</p>
             <div className="flex gap-2">
                <span className="w-2 h-2 rounded-full bg-teal-500"></span>
                <span className="w-2 h-2 rounded-full bg-indigo-500"></span>
                <span className="w-2 h-2 rounded-full bg-rose-500"></span>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

