                <span className="w-2 h-2 rounded-full bg-teal-500"></span>
                <span className="w-2 h-2 rounded-full bg-indigo-500"></span>
                <span className="w-2 h-2 rounded-full bg-rose-500"></span>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

