                    </div>
                  </div>
                ))}
                <div className="bg-indigo-50/20 border-2 border-dashed border-indigo-200 p-8 rounded-[2.5rem] flex flex-col gap-4">
                   <input value={newIssue.name} onChange={e => setNewIssue({ ...newIssue, name: e.target.value })} placeholder="Add diagnosis..." className="bg-transparent font-black text-lg outline-none placeholder-indigo-200 text-indigo-900" />
                   <button onClick={() => { if(newIssue.name) { updateHistory({ conditions: [...(history.conditions || []), { ...newIssue, id: crypto.randomUUID(), status: 'Active', clinicianVerified: role === 'clinician' } as Condition] }); setNewIssue({ name: '' }); } }} className="w-fit px-6 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">Add Issue +</button>
                </div>
              </div>
            </section>
          </div>
        )}

        {currentSection === 'dev' && (
          <div className="space-y-12 animate-in slide-in-from-bottom-4">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {/* PRENATAL */}
                <div className="bg-blue-50/50 p-8 rounded-[3rem] border border-blue-100 space-y-6">
                   <h3 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em]">Prenatal Context</h3>
                   <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-slate-400 uppercase">Scans Normal</span>
                        <input type="checkbox" checked={history.developmentalHistory.prenatal.scansNormal} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, prenatal: { ...history.developmentalHistory.prenatal, scansNormal: e.target.checked } } })} className="w-5 h-5 rounded text-blue-600" />
                      </div>
                      <textarea value={history.developmentalHistory.prenatal.complications} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, prenatal: { ...history.developmentalHistory.prenatal, complications: e.target.value } } })} placeholder="Pregnancy complications..." className="w-full h-24 p-4 rounded-2xl bg-white border border-blue-50 text-xs italic font-bold outline-none" />
                      <textarea value={history.developmentalHistory.prenatal.medications} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, prenatal: { ...history.developmentalHistory.prenatal, medications: e.target.value } } })} placeholder="Maternal medications..." className="w-full h-24 p-4 rounded-2xl bg-white border border-blue-50 text-xs italic font-bold outline-none" />
                   </div>
                </div>
                {/* PERINATAL */}
                <div className="bg-indigo-50/50 p-8 rounded-[3rem] border border-indigo-100 space-y-6">
                   <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em]">Perinatal (Birth)</h3>
                   <div className="space-y-4">
                      <input placeholder="Gestation (e.g. 40+2)" value={history.developmentalHistory.perinatal.gestation} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, perinatal: { ...history.developmentalHistory.perinatal, gestation: e.target.value } } })} className="w-full p-4 rounded-xl bg-white border border-indigo-50 text-xs font-black" />
                      <input placeholder="Delivery Type (e.g. LSCS)" value={history.developmentalHistory.perinatal.deliveryType} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, perinatal: { ...history.developmentalHistory.perinatal, deliveryType: e.target.value } } })} className="w-full p-4 rounded-xl bg-white border border-indigo-50 text-xs font-black" />
                      <input placeholder="Birth Weight" value={history.developmentalHistory.perinatal.birthWeight} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, perinatal: { ...history.developmentalHistory.perinatal, birthWeight: e.target.value } } })} className="w-full p-4 rounded-xl bg-white border border-indigo-50 text-xs font-black" />
                   </div>
                </div>
                {/* NEONATAL */}
                <div className="bg-emerald-50/50 p-8 rounded-[3rem] border border-emerald-100 space-y-6">
                   <h3 className="text-xs font-black text-emerald-600 uppercase tracking-[0.3em]">Neonatal Stage</h3>
                   <div className="space-y-4">
                      <div className="flex gap-4">
                        <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400">
                          <input type="checkbox" checked={history.developmentalHistory.neonatal.nicuStay} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, neonatal: { ...history.developmentalHistory.neonatal, nicuStay: e.target.checked } } })} /> NICU
                        </label>
                        <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400">
                          <input type="checkbox" checked={history.developmentalHistory.neonatal.jaundice} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, neonatal: { ...history.developmentalHistory.neonatal, jaundice: e.target.checked } } })} /> Jaundice
                        </label>
                      </div>
                      <textarea value={history.developmentalHistory.neonatal.feedingIssues} onChange={e => updateHistory({ developmentalHistory: { ...history.developmentalHistory, neonatal: { ...history.developmentalHistory.neonatal, feedingIssues: e.target.value } } })} placeholder="Early feeding (Breast/Bottle/Tube)..." className="w-full h-24 p-4 rounded-2xl bg-white border border-emerald-50 text-xs italic font-bold outline-none" />
                   </div>
                </div>
             </div>
          </div>
        )}

        {currentSection === 'family' && (
          <div className="space-y-12 animate-in slide-in-from-bottom-4">
            <div className="bg-indigo-900 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
               <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-[80px]"></div>
               <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
                  <div className="space-y-4 text-center md:text-left">
                     <h3 className="text-3xl font-black italic tracking-tighter leading-none">Pediatric Genogram</h3>
                     <p className="text-indigo-100 font-medium italic text-sm opacity-80 max-w-xl leading-relaxed">
                       A visual clinical tool mapping familial conditions and lineage. Circles represent females, squares represent males, and shaded shapes indicate chronic conditions.
                     </p>
                  </div>
                  {/* GENERATED GENOGRAM VIEW */}
                  <div className="bg-white/10 p-6 rounded-[2.5rem] backdrop-blur-md border border-white/20 min-w-[280px]">
                     <div className="flex flex-wrap justify-center gap-6">
                        {/* Recursive or tiered rendering would be better, but for MVP we use a simple horizontal flow */}
                        {history.familyHistory.members?.length > 0 ? (
                          history.familyHistory.members.map(member => (
                            <GenogramIcon key={member.id} member={member} />
                          ))
                        ) : (
                          <div className="text-center py-4">
                            <p className="text-[10px] font-black uppercase text-indigo-300">No members mapped</p>
                          </div>
                        )}
                        {/* Patient Icon Placeholder */}
                        <div className="flex flex-col items-center gap-1 border-t-2 border-indigo-400/50 pt-2">
                          <div className="w-10 h-10 rounded-full bg-emerald-400 border-4 border-white shadow-lg animate-pulse flex items-center justify-center text-[10px] font-black">PT</div>
                          <span className="text-[8px] font-black text-emerald-400 uppercase">Patient</span>
                        </div>
                     </div>
                  </div>
               </div>
            </div>

            <section className="bg-slate-50 p-10 rounded-[3.5rem] border border-slate-100 space-y-8">
               <div className="flex items-center gap-3 ml-4">
                  <span className="text-xl">🧬</span>
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Map Lineage & Conditions</h4>
               </div>
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                  <select value={newRelative.relation} onChange={e => setNewRelative({...newRelative, relation: e.target.value})} className="p-4 rounded-xl bg-white border border-slate-200 font-black text-xs">
                     <option>Father</option><option>Mother</option><option>Sibling</option><option>Paternal Grandma</option><option>Paternal Grandpa</option><option>Maternal Grandma</option><option>Maternal Grandpa</option><option>Aunt/Uncle</option>
                  </select>
                  <select value={newRelative.sex} onChange={e => setNewRelative({...newRelative, sex: e.target.value as any})} className="p-4 rounded-xl bg-white border border-slate-200 font-black text-xs">
                     <option value="Male">Male (Square)</option>
                     <option value="Female">Female (Circle)</option>
                     <option value="Other">Other (Diamond)</option>
                  </select>
                  <input placeholder="Known condition (e.g. T1DM)" value={newRelative.condition} onChange={e => setNewRelative({...newRelative, condition: e.target.value})} className="p-4 rounded-xl bg-white border border-slate-200 font-black text-xs" />
