const GenogramIcon: React.FC<{ member: GenogramMember }> = ({ member }) => {
  // OSCB Standards: Male = Square, Female = Circle, Gender Neutral = Diamond/Other, Pregnancy = Triangle
  const shapeClass = 
    member.sex === 'Male' ? 'rounded-none border-2' : 
    member.sex === 'Female' ? 'rounded-full border-2' : 
    member.sex === 'Pregnancy' ? 'w-0 h-0 border-l-[20px] border-l-transparent border-r-[20px] border-r-transparent border-b-[35px] border-b-slate-400 !bg-transparent !shadow-none' :
    'rounded-lg rotate-45 border-2';

  const colorClass = member.condition ? 'bg-rose-500 border-rose-600' : 'bg-white border-slate-400';

  return (
    <div className="flex flex-col items-center gap-1 group relative">
      <div className={`
        ${member.sex === 'Pregnancy' ? '' : 'w-12 h-12 flex items-center justify-center shadow-md transition-all group-hover:scale-110'} 
        ${member.isIndex ? 'outline outline-4 outline-offset-2 outline-indigo-600' : ''}
        ${shapeClass} ${colorClass} relative
      `}>
         {!member.isAlive && member.sex !== 'Pregnancy' && (
           <div className="absolute inset-0 flex items-center justify-center overflow-hidden">
             <div className="w-[140%] h-[2px] bg-slate-900 rotate-45"></div>
             <div className="w-[140%] h-[2px] bg-slate-900 -rotate-45"></div>
           </div>
         )}
      </div>
      <span className="text-[9px] font-black text-slate-600 uppercase tracking-tighter text-center leading-none mt-1">
        {member.relation}
      </span>
      {member.condition && (
        <div className="absolute -top-14 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[9px] font-bold p-2 rounded-xl opacity-0 group-hover:opacity-100 transition-opacity shadow-2xl whitespace-nowrap z-20 pointer-events-none">
          {member.condition}
        </div>
      )}
    </div>
  );
};

