                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-slate-500 uppercase ml-4">Clinical Conditions</label>
                    <input placeholder="e.g. T1DM, CF, Cancer..." value={newRelative.condition} onChange={e => setNewRelative({...newRelative, condition: e.target.value})} className={inputClass} />
                  </div>
                  <div className="flex items-end gap-3">
                    <label className="flex items-center gap-3 p-4 bg-white border border-slate-300 rounded-2xl cursor-pointer flex-1 justify-center">
                       <input type="checkbox" checked={newRelative.isAlive} onChange={e => setNewRelative({...newRelative, isAlive: e.target.checked})} className="w-6 h-6 rounded text-indigo-600 border-slate-300" />
                       <span className="text-[10px] font-black uppercase text-slate-800 tracking-widest">Alive</span>
