                    <button onClick={addRelative} className="bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest px-8 py-4 shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Add</button>
                  </div>
               </div>

               {history.familyHistory.members?.length > 0 && (
                 <div className="pt-10 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                   {history.familyHistory.members.map(member => (
                     <div key={member.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between group hover:shadow-lg transition-all shadow-sm">
                        <div className="flex items-center gap-5">
                           <div className={`w-10 h-10 ${member.sex === 'Male' ? 'rounded-none' : 'rounded-full'} ${member.condition ? 'bg-rose-500' : 'bg-slate-200'} shrink-0 shadow-inner border border-slate-400 flex items-center justify-center relative`}>
                              {!member.isAlive && member.sex !== 'Pregnancy' && <div className="absolute inset-0 flex items-center justify-center"><div className="w-[140%] h-[1px] bg-slate-900 rotate-45"></div><div className="w-[140%] h-[1px] bg-slate-900 -rotate-45"></div></div>}
                              {member.sex === 'Pregnancy' && <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-b-[10px] border-b-slate-400" />}
                           </div>
                           <div>
                              <p className="font-black text-slate-900 text-base italic leading-none">{member.relation} {!member.isAlive && '(Deceased)'}</p>
                              {member.condition && <p className="text-[11px] font-bold text-rose-600 italic mt-1">{member.condition}</p>}
                           </div>
                        </div>
                        <button onClick={() => updateHistory({ familyHistory: { ...history.familyHistory, members: history.familyHistory.members.filter(x => x.id !== member.id) } })} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2 font-black">✕</button>
                     </div>
                   ))}
                 </div>
               )}
            </section>

            <section className="grid grid-cols-1 md:grid-cols-2 gap-12 pt-10 border-t-4 border-slate-50">
               {[
                 { id: 'maternal', label: 'Maternal Lineage Narrative', color: 'text-rose-600', icon: '👩‍👦', bg: 'bg-rose-50/50', border: 'border-rose-200' },
                 { id: 'paternal', label: 'Paternal Lineage Narrative', color: 'text-indigo-600', icon: '👨‍👦', bg: 'bg-indigo-50/50', border: 'border-indigo-200' },
               ].map(side => (
                <div key={side.id} className="space-y-4">
                  <div className="flex items-center gap-4 px-4">
                    <span className="text-3xl">{side.icon}</span>
                    <h3 className={`text-xs font-black ${side.color} uppercase tracking-[0.4em]`}>{side.label}</h3>
                  </div>
                  <textarea 
                    value={(history.familyHistory as any)[side.id]} 
                    onChange={e => updateHistory({ familyHistory: { ...history.familyHistory, [side.id]: e.target.value } })} 
                    placeholder="Specific chronic illnesses, genetic variants, or shared family conditions..." 
                    className={textAreaClass + ` h-48 border-2 ${side.border} ${side.bg}`} 
                  />
                </div>
               ))}
            </section>
          </div>
        )}

        {currentSection === 'meds' && (
          <div className="space-y-12 animate-in slide-in-from-bottom-4">
            <section className="space-y-10">
              <div className="flex justify-between items-end px-6">
                 <h3 className="text-3xl font-black text-slate-900 italic tracking-tight">Active Medication Registry</h3>
                 <button onClick={() => setShowCeasedMeds(!showCeasedMeds)} className="text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-indigo-600 underline transition-all">
                   {showCeasedMeds ? 'Hide Archives' : 'View Medication Archive'}
                 </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 px-2">
                {history.currentMedications.map(m => (
                  <div key={m.id} className="bg-emerald-50/50 p-10 rounded-[3.5rem] border border-emerald-100 relative group shadow-sm hover:shadow-2xl transition-all">
                    <div className="space-y-6">
                      <p className="text-4xl font-black text-emerald-900 tracking-tighter leading-none italic">{m.name}</p>
                      <div className="bg-white/80 p-6 rounded-[2.5rem] border border-emerald-100 shadow-inner">
                         <p className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.3em] mb-3">Dose & Frequency</p>
                         <p className="text-3xl font-black text-emerald-950 italic leading-none">{m.dose}</p>
                         <p className="text-sm font-bold text-emerald-800/70 mt-4 leading-relaxed italic border-t border-emerald-50 pt-4">{m.instructions || 'Follow clinical guidance.'}</p>
                      </div>
                      <div className="space-y-1 ml-4">
                         <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Indication</p>
                         <p className="text-base font-black text-emerald-900/60 italic">{m.indication || 'Chronic management'}</p>
                      </div>
                    </div>
                  </div>
                ))}
                <div className="bg-slate-50 border-4 border-dashed border-slate-200 p-10 rounded-[3.5rem] space-y-6 flex flex-col justify-center min-h-[350px] group hover:border-emerald-300 transition-all">
                   <div className="space-y-6">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-500 uppercase ml-4">Medication Name</label>
                        <input value={newMed.name} onChange={e => setNewMed({ ...newMed, name: e.target.value })} placeholder="e.g. Paracetamol" className={inputClass} />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-500 uppercase ml-4">Dose / Frequency</label>
                        <input value={newMed.dose} onChange={e => setNewMed({ ...newMed, dose: e.target.value })} placeholder="e.g. 5ml Every 6 hours" className={inputClass} />
                      </div>
                      <button onClick={addMedication} className="w-full py-5 bg-emerald-600 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-xl hover:bg-emerald-700 active:scale-95 transition-all">Record Script +</button>
                   </div>
                </div>
              </div>
            </section>
          </div>
        )}

        {/* Other sections Medications, MDT, diagnostics follow the same style for input visibility */}

        {currentSection === 'mdt' && (
          <div className="space-y-16 animate-in slide-in-from-bottom-4">
            <section className="space-y-10">
              <div className="flex justify-between items-center px-4">
                <h3 className="text-3xl font-black text-slate-900 italic tracking-tight">Clinical Care Team</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {history.specialists.map(s => (
                    <div key={s.id} className="p-10 rounded-[3.5rem] border-2 bg-white border-slate-100 text-slate-900 shadow-sm transition-all hover:shadow-lg">
                      <div className="space-y-8">
                         <div>
                            <p className="text-4xl font-black tracking-tighter italic leading-none mb-3 text-slate-900">{s.specialty}</p>
                            <p className="text-xl font-bold text-indigo-600">{s.name}</p>
                         </div>
                         <div className="flex flex-wrap gap-4 pt-6 border-t border-slate-100">
                            <div className="space-y-1">
                               <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Site / Service</p>
                               <p className="text-base font-bold italic leading-none">{s.hospital || 'Community / Private Practice'}</p>
                            </div>
                         </div>
                      </div>
                    </div>
                ))}
                <div className="bg-slate-50 border-4 border-dashed border-slate-200 p-12 rounded-[4rem] space-y-8 flex flex-col justify-center group hover:border-indigo-300 transition-all">
                   <h4 className="font-black text-slate-500 uppercase text-[10px] tracking-widest text-center">Add New Specialist</h4>
                   <div className="space-y-5">
                      <input value={newSpecialist.specialty} onChange={e => setNewSpecialist({ ...newSpecialist, specialty: e.target.value })} placeholder="e.g. Neurology" className={inputClass} />
                      <input value={newSpecialist.name} onChange={e => setNewSpecialist({ ...newSpecialist, name: e.target.value })} placeholder="Professional Full Name" className={inputClass} />
                      <button onClick={() => { if(newSpecialist.name) { updateHistory({ specialists: [...history.specialists, { ...newSpecialist, id: crypto.randomUUID(), category: 'Medical' } as SpecialistContact] }); setNewSpecialist({ name: '', specialty: '' }); } }} className="w-full py-5 bg-indigo-600 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-700 active:scale-95 transition-all">Add to Care Team +</button>
                   </div>
                </div>
              </div>
            </section>
          </div>
        )}
      </div>

      <div className="flex justify-center mt-12">
        <button 
          onClick={() => {
            if (confirm("🚨 CRITICAL: Delete ALL medical records stored on this device?")) {
               localStorage.clear();
               window.location.reload();
            }
          }}
          className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-300 hover:text-rose-500 transition-colors"
        >
          Factory Reset Vault 🗑️
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ConsultationNote, ClinicalFindings, AssignedTest } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { GoogleGenAI } from "@google/genai";

const SCREENING_MODS = [
  { id: 'snap4', name: 'SNAP-IV (ADHD)', domain: 'Focus' },
  { id: 'mchat', name: 'M-CHAT-R (Autism)', domain: 'Social' },
  { id: 'asq3', name: 'ASQ-3 (Development)', domain: 'Development' },
  { id: 'gad7', name: 'GAD-7 (Anxiety)', domain: 'Mood' },
  { id: 'phq9', name: 'PHQ-9 (Mood/Depression)', domain: 'Mood' },
  { id: 'sdq', name: 'SDQ (Behavior)', domain: 'Behavior' },
];

const REASONING_FRAMEWORKS = [
  { id: 'standard', name: 'Standard Clinical', desc: 'General differential ranking' },
  { id: 'vindicate', name: 'VINDICATE', desc: 'Vascular, Infectious, Neoplastic, Degenerative, etc.' },
  { id: 'vitamins', name: 'VITAMINS', desc: 'Vascular, Infectious, Traumatic, Autoimmune, etc.' },
  { id: 'surgical_sieve', name: 'Surgical Sieve', desc: 'Anatomical vs Pathological mapping' },
];

const CLINICAL_SHORTHAND = {
  general: ['Alert/Active', 'Well Appearance', 'Mildly Unwell', 'NAD', 'Euvolaemic'],
  respiratory: ['Chest Clear', 'Symmetrical Expansion', 'No Wheeze/Stridor', 'Air Entry + Bilat', 'No Distressed Signs'],
  cardiac: ['HS I + II + 0', 'Femoral Pulps + Bilat', 'Cap Refill < 2s', 'Rhythm Regular'],
  abdominal: ['Soft/Non-tender', 'No Masses', 'BS + Active', 'No Guarding'],
  neurological: ['Tone Normal', 'Pupils PERL', 'GCS 15', 'No Focal Deficits'],
  skin: ['No Rashes', 'Warm/Pink', 'Skin Turgor Normal', 'No Petechiae']
};

export const ClinicianTools: React.FC<{ type: 'consults' | 'reasoning' | 'assignments' }> = ({ type }) => {
  const { history, updateHistory } = useMedicalHistory();
  const [loading, setLoading] = useState(false);
  const [reasoningResult, setReasoningResult] = useState<{text: string, sources: any[]} | null>(null);
  const [activeFramework, setActiveFramework] = useState('standard');
  const [activeInputTab, setActiveInputTab] = useState<'history' | 'exam' | 'investigations'>('history');

  const assignedTests = history.assignedTests || [];

  const [newSoap, setNewSoap] = useState<Partial<ConsultationNote>>({
    clinicianName: '', subjective: '', objective: '', assessment: '', plan: ''
  });

  const [findings, setFindings] = useState<{
    history: string;
    exam: {
      general: string;
      respiratory: string;
      cardiac: string;
      abdominal: string;
      neurological: string;
      skin: string;
    };
    investigations: string;
    vitals: { hr?: string; rr?: string; temp?: string; o2?: string; bp?: string; glu?: string };
  }>({
    history: '',
    exam: { general: '', respiratory: '', cardiac: '', abdominal: '', neurological: '', skin: '' },
    investigations: '',
    vitals: {}
  });

  const injectShorthand = (section: keyof typeof findings.exam, term: string) => {
    setFindings(prev => ({
      ...prev,
      exam: {
        ...prev.exam,
        [section]: prev.exam[section] ? `${prev.exam[section]}, ${term}` : term
      }
    }));
  };

  const toggleTestAssignment = (testId: string) => {
    const isAssigned = assignedTests.some(t => t.testId === testId);
    let next: AssignedTest[];
    if (isAssigned) {
      next = assignedTests.filter(t => t.testId !== testId);
    } else {
      next = [...assignedTests, { testId, assignedDate: new Date().toISOString(), status: 'pending' }];
    }
    updateHistory({ assignedTests: next });
  };

  const handleAddConsult = () => {
    if (!newSoap.assessment || !newSoap.plan) return;
    const consult: ConsultationNote = {
      ...newSoap,
      id: crypto.randomUUID(),
      date: new Date().toISOString()
    } as ConsultationNote;
    updateHistory({ formalConsults: [consult, ...(history.formalConsults || [])] });
    setNewSoap({ clinicianName: '', subjective: '', objective: '', assessment: '', plan: '' });
  };

  const handleRunReasoning = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const frameworkInstruction = 
        activeFramework === 'vindicate' ? "Use the VINDICATE acronym to structure your differential." :
        activeFramework === 'vitamins' ? "Use the VITAMINS mnemonic to structure your differential." :
        activeFramework === 'surgical_sieve' ? "Apply a Surgical Sieve approach." : 
        "Provide a prioritized differential list.";

      const prompt = `Act as a senior pediatric consultant. Analyze this clinical presentation.
      FRAMEWORK: ${frameworkInstruction}
      PATIENT: PMHx: ${history.pastMedicalHistory}, Meds: ${history.currentMedications.map(m => m.name).join(', ')}
      HISTORY: ${findings.history}
      VITALS: HR: ${findings.vitals.hr}, RR: ${findings.vitals.rr}, SpO2: ${findings.vitals.o2}, Temp: ${findings.vitals.temp}, BP: ${findings.vitals.bp}, BSL: ${findings.vitals.glu}
      EXAM: Gen: ${findings.exam.general}, Resp: ${findings.exam.respiratory}, CVS: ${findings.exam.cardiac}, Abdo: ${findings.exam.abdominal}, CNS: ${findings.exam.neurological}, Skin: ${findings.exam.skin}
      TESTS: ${findings.investigations}
      REQUIREMENTS: 1. Differential 2. Red Flags 3. Plan 4. Evidence (EBM). Format clearly with numbered sections.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
      });
      setReasoningResult({
        text: response.text || 'Synthesis failed.',
        sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
      });
    } catch (e) {
      alert("Error generating reasoning.");
    } finally {
      setLoading(false);
    }
  };

  if (type === 'assignments') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Assignment <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Curate assessments for pre-review completion.</p>
        </header>

        <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {SCREENING_MODS.map(test => {
                const assignment = assignedTests.find(t => t.testId === test.id);
                const isAssigned = !!assignment;
                const isCompleted = assignment?.status === 'completed';

                return (
                  <button 
                    key={test.id}
                    onClick={() => toggleTestAssignment(test.id)}
                    className={`p-8 rounded-[3rem] border-2 text-left transition-all relative group flex flex-col justify-between h-48 ${
                      isCompleted ? 'bg-emerald-50 border-emerald-500' :
                      isAssigned ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-105' : 
                      'bg-slate-50 border-slate-100 hover:border-indigo-300 hover:bg-white'
                    }`}
                  >
                    <div>
                      <div className="flex justify-between items-start mb-2">
                        <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full ${isAssigned ? 'bg-white/20' : 'bg-slate-200 text-slate-500'}`}>{test.domain}</span>
                        {isCompleted && <span className="text-emerald-600 text-xs font-black">✓ Done</span>}
                      </div>
                      <h4 className={`text-xl font-black tracking-tight leading-none ${isAssigned && !isCompleted ? 'text-white' : 'text-slate-900'}`}>{test.name}</h4>
                    </div>

                    <div className="flex items-center justify-between mt-4">
                      <span className={`text-[10px] font-black uppercase tracking-widest ${isAssigned && !isCompleted ? 'text-indigo-100' : 'text-slate-500'}`}>
                        {isCompleted ? 'Finished' : isAssigned ? 'Assigned' : 'Click to Assign'}
                      </span>
                    </div>
                  </button>
                );
              })}
           </div>
        </div>
      </div>
    );
  }

  if (type === 'consults') {
    return (
      <div className="space-y-12 pb-24 animate-in fade-in">
        <header>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">SOAP <span className="text-indigo-600">Consultations</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical documentation workspace.</p>
        </header>

        <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-4">Subjective (S)</label>
                <textarea value={newSoap.subjective} onChange={e => setNewSoap({...newSoap, subjective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-200 font-bold italic text-slate-900 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Patient report..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-4">Objective (O)</label>
                <textarea value={newSoap.objective} onChange={e => setNewSoap({...newSoap, objective: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-slate-50 border border-slate-200 font-bold italic text-slate-900 outline-none focus:ring-4 focus:ring-indigo-50" placeholder="Exam findings..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-4">Assessment (A)</label>
                <textarea value={newSoap.assessment} onChange={e => setNewSoap({...newSoap, assessment: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-indigo-50/30 border border-indigo-100 font-bold italic text-slate-900 outline-none focus:ring-4 focus:ring-indigo-100" placeholder="Diagnosis..." />
             </div>
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-4">Plan (P)</label>
                <textarea value={newSoap.plan} onChange={e => setNewSoap({...newSoap, plan: e.target.value})} className="w-full h-32 p-6 rounded-[2rem] bg-emerald-50/30 border border-emerald-100 font-bold italic text-slate-900 outline-none focus:ring-4 focus:ring-emerald-100" placeholder="Next steps..." />
             </div>
          </div>
          <div className="flex justify-between items-center pt-8 border-t border-slate-100">
             <input value={newSoap.clinicianName} onChange={e => setNewSoap({...newSoap, clinicianName: e.target.value})} placeholder="Clinician Name" className="p-4 bg-slate-50 border border-slate-200 rounded-xl font-black text-xs text-slate-900 outline-none" />
             <button onClick={handleAddConsult} className="px-10 py-5 bg-indigo-600 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-700">Record Consult</button>
          </div>
        </section>
      </div>
    );
  }

  return (
    <div className="space-y-12 pb-24 animate-in fade-in">
      <header className="flex flex-col md:flex-row justify-between items-start gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">Reasoning <span className="text-indigo-600">Bench</span></h2>
          <p className="text-slate-500 font-medium italic">Clinical differential augmentation.</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
         <section className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8 h-fit">
            <nav className="flex gap-4 border-b border-slate-50 pb-4">
               {['history', 'exam', 'investigations'].map(tab => (
                 <button 
                  key={tab} 
                  onClick={() => setActiveInputTab(tab as any)}
                  className={`text-[10px] font-black uppercase tracking-[0.2em] pb-2 border-b-4 transition-all ${activeInputTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-300'}`}
                 >
                   {tab}
                 </button>
               ))}
            </nav>

            <div className="space-y-6">
               {activeInputTab === 'history' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase ml-2">History Highlights</label>
                      <textarea value={findings.history} onChange={e => setFindings({...findings, history: e.target.value})} className="w-full h-32 p-5 rounded-2xl bg-slate-50 font-bold italic text-slate-900 outline-none border border-slate-200 focus:ring-2 focus:ring-indigo-50 shadow-inner" placeholder="..." />
                    </div>
                    <div className="grid grid-cols-3 gap-4">
                      {['hr', 'rr', 'o2', 'temp', 'bp', 'glu'].map(v => (
                         <div key={v} className="space-y-1">
                            <label className="text-[8px] font-black text-slate-500 uppercase ml-2">{v.toUpperCase()}</label>
                            <input placeholder="..." value={(findings.vitals as any)[v]} onChange={e => setFindings({...findings, vitals: {...findings.vitals, [v]: e.target.value}})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-black text-xs text-slate-900 outline-none" />
                         </div>
                      ))}
                    </div>
                 </div>
               )}

               {activeInputTab === 'exam' && (
                 <div className="space-y-6 animate-in slide-in-from-left-4 max-h-[500px] overflow-y-auto pr-2 no-scrollbar">
                    {(Object.keys(CLINICAL_SHORTHAND) as Array<keyof typeof findings.exam>).map(sysKey => (
                      <div key={sysKey} className="space-y-3">
                        <label className="text-[9px] font-black text-slate-500 uppercase ml-2 block">{String(sysKey)} Systems</label>
                        <input 
                          value={findings.exam[sysKey]} 
                          onChange={e => setFindings({...findings, exam: {...findings.exam, [sysKey]: e.target.value}})} 
                          className="w-full p-4 rounded-xl bg-slate-50 font-bold italic text-slate-900 outline-none border border-slate-200 focus:ring-2 focus:ring-indigo-50 text-sm shadow-inner" 
                        />
                      </div>
                    ))}
                 </div>
               )}

               <div className="pt-6 border-t border-slate-100">
                  <button onClick={handleRunReasoning} disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-slate-800 transition-all flex items-center justify-center gap-3">
                    {loading ? 'Synthesizing...' : 'Run Differential ✨'}
                  </button>
               </div>
            </div>
         </section>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ChildProfile, Medication } from '../types';
import { useChildProfile } from '../context/ChildProfileContext';
import { useNavigation } from '../context/NavigationContext';

export const ChildProfileSetup: React.FC = () => {
  const { childProfile, setChildProfile, setHasSkippedSetup } = useChildProfile();
  const { navigateTo } = useNavigation();
  const [isSaving, setIsSaving] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // Child Info
  const [name, setName] = useState(childProfile?.name || '');
  const [dob, setDob] = useState(childProfile?.dob || '');
  const [sex, setSex] = useState<'Male' | 'Female' | 'Other'>(childProfile?.sex || 'Male');
  const [weight, setWeight] = useState(childProfile?.weight?.toString() || '');
  const [height, setHeight] = useState(childProfile?.height?.toString() || '');
  const [medHistory, setMedHistory] = useState(childProfile?.pastMedicalHistory || '');

  // Account Info
  const [email, setEmail] = useState(childProfile?.email || '');
  const [password, setPassword] = useState(childProfile?.password || '');
  const [stayLoggedIn, setStayLoggedIn] = useState(childProfile?.stayLoggedIn ?? true);
  const [agreedToTerms, setAgreedToTerms] = useState(!!childProfile);

  const [validationErrors, setValidationErrors] = useState<string[]>([]);

  useEffect(() => {
    const errors = [];
    if (!name) errors.push("Name is required");
    if (!dob) errors.push("DOB is required");
    if (!email) errors.push("Email is required");
    if (!agreedToTerms) errors.push("Agreement required");
    setValidationErrors(errors);
  }, [name, dob, email, agreedToTerms]);

  const handleSkip = () => {
    setHasSkippedSetup(true);
    navigateTo('dashboard');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (validationErrors.length > 0) {
      return;
    }

    const weightNum = parseFloat(weight);
    if (weight && (weightNum < 2 || weightNum > 150)) {
       alert("Please enter a realistic pediatric weight (2 kg to 150 kg).");
       return;
    }

    setIsSaving(true);

    setTimeout(() => {
      setChildProfile({
        name,
        dob,
        sex,
        weight: weight ? parseFloat(weight) : undefined,
        height: height ? parseFloat(height) : undefined,
        pastMedicalHistory: medHistory,
        medications: childProfile?.medications || [],
        previousMedications: childProfile?.previousMedications || [],
        allergies: childProfile?.allergies || [],
        email,
        password,
        stayLoggedIn
      });
      setHasSkippedSetup(false);
      setIsSuccess(true);

      setTimeout(() => {
        navigateTo('dashboard');
        setIsSaving(false);
      }, 800);
    }, 1000);
  };

  const inputClass = "w-full p-5 rounded-2xl border-2 border-slate-300 bg-white focus:border-indigo-600 focus:ring-4 focus:ring-indigo-100 outline-none font-black text-slate-900 text-lg transition-all placeholder:text-slate-400 shadow-sm";
  const labelClass = "block text-[11px] font-black text-slate-700 uppercase tracking-widest ml-2 mb-1";

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-10 duration-700 pb-20">
      <header className="text-center space-y-4">
        <div className="w-24 h-24 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-6 shadow-2xl rotate-3 transition-transform hover:rotate-0 cursor-default">🩺</div>
        <h2 className="text-4xl font-black text-slate-800 tracking-tight italic">
          {childProfile ? 'Profile Edit' : 'Clinical Onboarding'}
        </h2>
        <p className="text-slate-600 font-bold italic">Persistence for clinical baseline and alerts.</p>

        {!childProfile && !isSuccess && (
          <div className="pt-4">
            <button onClick={handleSkip} className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-500 hover:text-indigo-600 border-2 border-slate-200 px-8 py-3 rounded-2xl transition-all">Skip →</button>
          </div>
        )}
      </header>

      <form onSubmit={handleSubmit} className="space-y-10">
        <section className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-xl space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-1">
              <label className={labelClass}>Child's Name</label>
              <input type="text" required value={name} onChange={(e) => setName(e.target.value)} placeholder="Full Name" className={inputClass} />
            </div>
            <div className="space-y-1">
              <label className={labelClass}>Birth Date</label>
              <input type="date" required max={new Date().toISOString().split('T')[0]} value={dob} onChange={(e) => setDob(e.target.value)} className={inputClass + " uppercase"} />
            </div>
            <div className="space-y-1">
              <label className={labelClass}>Latest Weight (kg)</label>
              <input type="number" step="0.1" value={weight} onChange={(e) => setWeight(e.target.value)} placeholder="e.g. 12.5" className={inputClass} />
            </div>
            <div className="space-y-1">
               <label className={labelClass}>Guardian Email</label>
               <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="parent@example.com" className={inputClass} />
            </div>
          </div>
        </section>

        <div className="space-y-4">
          <button type="submit" disabled={isSaving || validationErrors.length > 0} className={`w-full py-7 text-white font-black rounded-[2.5rem] shadow-2xl transition-all transform active:scale-95 text-base uppercase tracking-[0.2em] flex items-center justify-center gap-3 ${isSuccess ? 'bg-emerald-500' : (validationErrors.length > 0 ? 'bg-slate-300' : 'bg-indigo-600 hover:bg-indigo-700')}`}>
            {isSuccess ? 'Profile Ready ✓' : isSaving ? 'Saving...' : 'Sync Registry ✨'}
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
