  return (
    <div className="relative p-8 rounded-[3rem] bg-indigo-950/20 backdrop-blur-xl border border-white/5 shadow-inner min-w-[500px] space-y-12">
      {/* GEN 1: Grandparents */}
      <div className="flex justify-between w-full px-4">
