import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useRole } from '../context/RoleContext';
import { DOSING_GUIDELINES } from '../clinical/dosing';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, Area, ComposedChart, Line
} from 'recharts';

const icons = { 
  Fluid: '🥤', 
  Temperature: '🌡️', 
  Output: '🚽', 
  Medication: '💊', 
  Vomit: '🤮', 
  Triage: '✨', 
  Vitals: '🩺', 
  'Physical Exam': '👨‍⚕️' 
};

const units: Record<string, string> = {
  Fluid: 'ml',
  Temperature: '°C',
  Output: 'ml',
  Vomit: 'ml',
  Medication: 'mg/ml',
  Vitals: ''
};

const formatLogTime = (isoString: string) => {
  try {
    return new Date(isoString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  } catch {
    return isoString;
  }
};

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, updateHistory, latestWeight } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { role } = useRole();

  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');
  const [selectedMed, setSelectedMed] = useState<'Paracetamol' | 'Ibuprofen'>('Paracetamol');

  // CEWT Form State
  const [obs, setObs] = useState({
    rr: '', hr: '', spo2: '', temp: '', cbt: 'Normal', effort: 'None', avpu: 'A'
  });

  const suggestedTargets = useMemo(() => {
    const weight = latestWeight || childProfile?.weight || 0;
    if (weight === 0) return { targetVolume: 200, intervalVolume: 5, intervalMinutes: 5 };
    const hourlyTarget = Math.round(weight * 10);
    const intervalVolume = weight < 10 ? 2 : 5; 
    return { targetVolume: hourlyTarget, intervalVolume, intervalMinutes: 5 };
  }, [latestWeight, childProfile?.weight]);

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: suggestedTargets.targetVolume,
    intervalVolume: suggestedTargets.intervalVolume,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  useEffect(() => {
    if (!challenge.isActive) {
      setChallenge(prev => ({
        ...prev,
        targetVolume: suggestedTargets.targetVolume,
        intervalVolume: suggestedTargets.intervalVolume
      }));
    }
  }, [suggestedTargets, challenge.isActive]);

  const isNeonate = useMemo(() => {
    if (!childProfile?.dob) return false;
    const birth = new Date(childProfile.dob);
    const diff = Date.now() - birth.getTime();
    const months = (diff / (1000 * 60 * 60 * 24 * 30.44));
    return months < 3;
  }, [childProfile]);

  // MEDICATION SAFETY LOGIC
  const lastDoseInfo = useMemo(() => {
    if (type !== 'Medication') return null;
    const logs = history.acuteLogs || [];
    const drugLogs = logs.filter(l => l.type === 'Medication' && l.medicationName === selectedMed);
    if (drugLogs.length === 0) return null;

    const lastDose = drugLogs[0]; // Most recent is first
    const lastTime = new Date(lastDose.timestamp);
    const diffMs = Date.now() - lastTime.getTime();
    const diffHours = diffMs / (1000 * 60 * 60);

    const requiredInterval = selectedMed === 'Paracetamol' 
      ? DOSING_GUIDELINES.PARACETAMOL.MIN_INTERVAL_HOURS 
      : DOSING_GUIDELINES.IBUPROFEN.MIN_INTERVAL_HOURS;

    const isTooSoon = diffHours < requiredInterval;
    const nextSafeTime = new Date(lastTime.getTime() + requiredInterval * 60 * 60 * 1000);

    return {
      lastTime,
      isTooSoon,
      nextSafeTime,
      diffHours,
      requiredInterval
    };
  }, [type, selectedMed, history.acuteLogs]);

  const trendData = useMemo(() => {
    const logs = [...(history.acuteLogs || [])].reverse();
    let cumulativeBalance = 0;

    return logs.map(log => {
      if (log.type === 'Fluid') cumulativeBalance += (parseInt(log.value) || 0);
      if (log.type === 'Output' || log.type === 'Vomit') cumulativeBalance -= (parseInt(log.value) || 0);

      let hr, rr, temp, spo2;
      if (log.type === 'Vitals') {
        const hrMatch = log.value.match(/HR:\s*(\d+)/);
        const rrMatch = log.value.match(/RR:\s*(\d+)/);
        const o2Match = log.value.match(/O2:\s*(\d+)/);
        const tMatch = log.value.match(/T:\s*([\d.]+)/);
        if (hrMatch) hr = parseInt(hrMatch[1]);
        if (rrMatch) rr = parseInt(rrMatch[1]);
        if (o2Match) spo2 = parseInt(o2Match[1]);
        if (tMatch) temp = parseFloat(tMatch[1]);
      } else if (log.type === 'Temperature') {
        temp = parseFloat(log.value);
      }

      return {
        time: formatLogTime(log.timestamp),
        temp,
        hr,
        rr,
        spo2,
        balance: cumulativeBalance
      };
    });
  }, [history.acuteLogs]);

  const handleAdd = (quickVal?: string) => {
    const finalVal = quickVal || value;
    if (!finalVal) return;

    const valInt = parseInt(finalVal) || 0;
    const displayUnit = units[type] || '';

    const isSafetyViolation = lastDoseInfo?.isTooSoon && type === 'Medication';
    const safetyNote = isSafetyViolation 
      ? `🚨 CLINICAL ALERT: Dose administered too close together (${lastDoseInfo.diffHours.toFixed(1)}h since last dose). Recommended interval: ${lastDoseInfo.requiredInterval}h.` 
      : '';

    addAcuteLog({
      timestamp: new Date().toISOString(),
      type,
      value: type === 'Temperature' ? `${finalVal} degree Celsius` : 
             type === 'Medication' ? `${selectedMed}: ${finalVal} ${displayUnit}` :
             `${finalVal} ${displayUnit}`,
      notes: `${notes}${safetyNote ? ' ' + safetyNote : ''}`.trim(),
      medicationName: type === 'Medication' ? selectedMed : undefined,
      clinicianLogged: role === 'clinician'
    });

    if (challenge.isActive && type === 'Fluid') {
      setChallenge(prev => ({ ...prev, totalConsumed: prev.totalConsumed + valInt }));
    } else if (challenge.isActive && type === 'Vomit') {
      setChallenge(prev => ({ ...prev, vomitCount: prev.vomitCount + 1 }));
    }

    setValue('');
    setNotes('');
  };

  const inputBaseClass = "w-full p-5 bg-white border-2 border-slate-300 rounded-2xl font-black text-slate-900 outline-none focus:border-indigo-600 focus:ring-4 focus:ring-indigo-50 transition-all placeholder:text-slate-400 text-xl";
  const labelBaseClass = "text-[11px] font-black text-slate-700 uppercase tracking-widest ml-2 mb-1 block";
  const quickButtonClass = "flex-1 py-4 bg-white border-2 border-slate-200 rounded-2xl font-black text-slate-800 hover:border-teal-500 hover:bg-teal-50 transition-all shadow-sm active:scale-95 text-sm";

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Sync Log</span></h2>
          <p className="text-slate-600 font-bold italic mt-1">Track fluids, fever, and triage insights.</p>
        </div>
        {!challenge.isActive ? (
          <button 
            onClick={() => setChallenge(prev => ({ ...prev, isActive: true, startTime: new Date().toLocaleTimeString() }))} 
            className="w-full sm:w-auto bg-teal-600 text-white px-8 py-4 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 hover:bg-teal-700 transition-all"
          >
            <span>💧</span> Setup Fluid Challenge
          </button>
        ) : (
          <button onClick={() => setChallenge(prev => ({ ...prev, isActive: false }))} className="w-full sm:w-auto bg-slate-900 text-white px-8 py-4 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl">Stop Tracking</button>
        )}
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[3.5rem] shadow-xl border-2 border-slate-200 space-y-8">
            <div className="flex bg-slate-100 p-1.5 rounded-2xl border-2 border-slate-200 shadow-inner">
               {['Fluid', 'Temperature', 'Output', 'Medication', 'Vomit'].map((t) => (
                  <button key={t} onClick={() => setType(t as any)} title={t} className={`flex-1 py-5 rounded-xl text-3xl transition-all ${type === t ? 'bg-white shadow-lg text-indigo-600 scale-110 z-10' : 'opacity-30 grayscale hover:opacity-50'}`}>{(icons as any)[t]}</button>
               ))}
            </div>

            <div className="space-y-6">
               {type === 'Medication' && (
                 <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                    <div className="flex bg-indigo-50 p-1 rounded-xl border border-indigo-100">
                      <button 
                        onClick={() => setSelectedMed('Paracetamol')}
                        className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${selectedMed === 'Paracetamol' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                      >Paracetamol</button>
                      <button 
                        onClick={() => setSelectedMed('Ibuprofen')}
                        className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${selectedMed === 'Ibuprofen' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                      >Ibuprofen</button>
                    </div>

                    {lastDoseInfo ? (
                      <div className={`p-4 rounded-2xl border-2 transition-all ${lastDoseInfo.isTooSoon ? 'bg-rose-50 border-rose-200' : 'bg-emerald-50 border-emerald-200'}`}>
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Dosing Integrity</p>
                        <p className="text-xs font-bold text-slate-700 italic">
                          Last Dose: {formatLogTime(lastDoseInfo.lastTime.toISOString())} 
                          ({lastDoseInfo.diffHours.toFixed(1)}h ago)
                        </p>
                        {lastDoseInfo.isTooSoon ? (
                          <div className="mt-2 space-y-1">
                            <p className="text-sm font-black text-rose-600 uppercase tracking-tight">⚠️ WAIT: Dose too close</p>
                            <p className="text-[10px] font-bold text-rose-500 italic">Next safe dose at: {formatLogTime(lastDoseInfo.nextSafeTime.toISOString())}</p>
                          </div>
                        ) : (
                          <p className="text-sm font-black text-emerald-600 uppercase tracking-tight mt-2">✓ Safe to administer</p>
                        )}
                      </div>
                    ) : (
                      <div className="p-4 rounded-2xl bg-slate-50 border border-slate-200">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">No recent {selectedMed} doses recorded.</p>
                      </div>
                    )}
                 </div>
               )}

               {(type === 'Fluid' || type === 'Output' || type === 'Vomit') && (
                 <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                   <label className={labelBaseClass}>Quick Presets ({units[type]})</label>
                   <div className="flex gap-2">
                      {['5', '10', '20', '50'].map(v => (
                        <button key={v} onClick={() => handleAdd(v)} className={quickButtonClass}>{v}</button>
                      ))}
                   </div>
                 </div>
               )}

               <div className="space-y-1">
                  <label className={labelBaseClass}>{type === 'Temperature' ? 'Fever Reading' : type === 'Medication' ? `${selectedMed} Dose` : 'Manual Entry'}</label>
                  <div className="relative">
                    <input value={value} onChange={e => setValue(e.target.value)} placeholder="..." className={`${inputBaseClass} ${isNeonate && type === 'Temperature' && parseFloat(value) >= 38 ? 'border-rose-600 ring-4 ring-rose-100' : ''}`} />
                    <span className="absolute right-6 top-1/2 -translate-y-1/2 font-black text-slate-400 uppercase tracking-widest text-sm">{units[type] || ''}</span>
                  </div>
               </div>

               {isNeonate && type === 'Temperature' && parseFloat(value) >= 38 && (
