                 {history.acuteLogs?.length ? history.acuteLogs.slice(0, 10).map(entry => (
                    <div key={entry.id} className={`p-6 rounded-[2.5rem] border-2 transition-all hover:scale-[1.01] ${entry.type === 'Triage' ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-slate-100'}`}>
