  };

  const suggestedTargets = useMemo(() => {
    const weight = latestWeight || childProfile?.weight || 0;
    if (weight === 0) return { targetVolume: 200, intervalVolume: 5, intervalMinutes: 5 };
    const hourlyTarget = Math.round(weight * 10);
    const intervalVolume = weight < 10 ? 2 : 5; 
    return { targetVolume: hourlyTarget, intervalVolume, intervalMinutes: 5 };
  }, [latestWeight, childProfile?.weight]);

  const [challenge, setChallenge] = useState<HydrationChallenge>({
    isActive: false,
    targetVolume: suggestedTargets.targetVolume,
    intervalVolume: suggestedTargets.intervalVolume,
    intervalMinutes: 5,
    totalConsumed: 0,
    vomitCount: 0
  });

  useEffect(() => {
    if (!challenge.isActive) {
      setChallenge(prev => ({
        ...prev,
        targetVolume: suggestedTargets.targetVolume,
        intervalVolume: suggestedTargets.intervalVolume
      }));
    }
  }, [suggestedTargets, challenge.isActive]);

  const isNeonate = useMemo(() => {
    if (!childProfile?.dob) return false;
    const birth = new Date(childProfile.dob);
    const diff = Date.now() - birth.getTime();
    const months = (diff / (1000 * 60 * 60 * 24 * 30.44));
    return months < 3;
  }, [childProfile]);

  const balanceStats = useMemo(() => {
    const logs = history.acuteLogs || [];
    const input = logs.filter(l => l.type === 'Fluid').reduce((sum, l) => sum + (parseInt(l.value) || 0), 0);
    const output = logs.filter(l => l.type === 'Output' || l.type === 'Vomit').reduce((sum, l) => sum + (parseInt(l.value) || 0), 0);
    return { input, output, balance: input - output };
  }, [history.acuteLogs]);

  const lastDoseInfo = useMemo(() => {
    if (type !== 'Medication') return null;
    const logs = history.acuteLogs || [];
    const drugLogs = logs.filter(l => l.type === 'Medication' && l.medicationName === selectedMed);
    if (drugLogs.length === 0) return null;

    const lastDose = drugLogs[0]; 
    const lastTime = new Date(lastDose.timestamp);
    const diffMs = Date.now() - lastTime.getTime();
    const diffHours = diffMs / (1000 * 60 * 60);

    const requiredInterval = selectedMed === 'Paracetamol' 
      ? DOSING_GUIDELINES.PARACETAMOL.MIN_INTERVAL_HOURS 
      : DOSING_GUIDELINES.IBUPROFEN.MIN_INTERVAL_HOURS;

    const isTooSoon = diffHours < requiredInterval;
    const nextSafeTime = new Date(lastTime.getTime() + requiredInterval * 60 * 60 * 1000);

    return {
      lastTime,
      isTooSoon,
      nextSafeTime,
      diffHours,
      requiredInterval
    };
  }, [type, selectedMed, history.acuteLogs]);

  const trendData = useMemo(() => {
    const logs = [...(history.acuteLogs || [])].reverse();
    let cumulativeBalance = 0;

    return logs.map(log => {
      if (log.type === 'Fluid') cumulativeBalance += (parseInt(log.value) || 0);
      if (log.type === 'Output' || log.type === 'Vomit') cumulativeBalance -= (parseInt(log.value) || 0);

      let hr, rr, temp, spo2;
      if (log.type === 'Vitals') {
        const hrMatch = log.value.match(/HR:\s*(\d+)/);
        const rrMatch = log.value.match(/RR:\s*(\d+)/);
        const o2Match = log.value.match(/O2:\s*(\d+)/);
        const tMatch = log.value.match(/T:\s*([\d.]+)/);
        if (hrMatch) hr = parseInt(hrMatch[1]);
        if (rrMatch) rr = parseInt(rrMatch[1]);
        if (o2Match) spo2 = parseInt(o2Match[1]);
        if (tMatch) temp = parseFloat(tMatch[1]);
      } else if (log.type === 'Temperature') {
        temp = parseFloat(log.value);
      }

      return {
        time: formatLogTime(log.timestamp),
        temp,
        hr,
        rr,
        spo2,
        balance: cumulativeBalance,
        rawInput: log.type === 'Fluid' ? parseInt(log.value) : 0,
        rawOutput: (log.type === 'Output' || log.type === 'Vomit') ? parseInt(log.value) : 0
      };
    });
  }, [history.acuteLogs]);

  const handleAdd = (quickVal?: string) => {
    const finalVal = quickVal || value;
    if (!finalVal && type !== 'Vitals') return;

    const displayUnit = units[type] || '';
    const isSafetyViolation = lastDoseInfo?.isTooSoon && type === 'Medication';
    const safetyNote = isSafetyViolation 
      ? `🚨 CLINICAL ALERT: Dose administered too close together (${lastDoseInfo.diffHours.toFixed(1)}h since last dose). Recommended interval: ${lastDoseInfo.requiredInterval}h.` 
      : '';

    if (type === 'Vitals') {
        const vitalString = `HR: ${obs.hr}, RR: ${obs.rr}, O2: ${obs.spo2}%, T: ${obs.temp}C, BP: ${obs.bp || '--'}, CNS: ${obs.avpu}, CBT: ${obs.cbt}`;
        addAcuteLog({
            timestamp: new Date().toISOString(),
            type: 'Vitals',
            value: vitalString,
            notes: notes.trim(),
            clinicianLogged: role === 'clinician'
        });
        setObs({ rr: '', hr: '', spo2: '', temp: '', bp: '', cbt: 'Normal', effort: 'None', avpu: 'A' });
    } else {
        addAcuteLog({
            timestamp: new Date().toISOString(),
            type,
            value: type === 'Temperature' ? `${finalVal} degree Celsius` : 
                   type === 'Medication' ? `${selectedMed}: ${finalVal} ${displayUnit}` :
                   `${finalVal} ${displayUnit}`,
            notes: `${notes}${safetyNote ? ' ' + safetyNote : ''}`.trim(),
            medicationName: type === 'Medication' ? selectedMed : undefined,
            clinicianLogged: role === 'clinician'
        });

        if (challenge.isActive && type === 'Fluid') {
            const valInt = parseInt(finalVal) || 0;
            setChallenge(prev => ({ ...prev, totalConsumed: prev.totalConsumed + valInt }));
        } else if (challenge.isActive && type === 'Vomit') {
            setChallenge(prev => ({ ...prev, vomitCount: prev.vomitCount + 1 }));
        }
    }

    setValue('');
    setNotes('');
  };

  const inputBaseClass = "w-full p-4 bg-white border-2 border-slate-200 rounded-xl font-black text-slate-900 outline-none focus:border-indigo-600 transition-all placeholder:text-slate-300";
  const labelBaseClass = "text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2 mb-1 block";

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic">Acute <span className="text-rose-600">Clinical Sync</span></h2>
          <p className="text-slate-600 font-bold italic mt-1">{role === 'clinician' ? 'Professional Vital Bundle & Balance' : 'Track fluids, fever, and symptoms.'}</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
            <div className="bg-indigo-50 border border-indigo-100 px-4 py-2 rounded-xl flex items-center gap-3">
                <span className="text-indigo-600 font-black text-xs uppercase tracking-widest">Balance</span>
                <span className={`font-black text-sm ${balanceStats.balance < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                    {balanceStats.balance > 0 ? '+' : ''}{balanceStats.balance} ml
                </span>
            </div>
            {role === 'clinician' && (
                <div className="bg-slate-900 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                    Professional Mode
                </div>
            )}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 space-y-6">
          <div className="bg-white p-8 rounded-[3.5rem] shadow-xl border-2 border-slate-100 space-y-8">
            <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-200 shadow-inner overflow-x-auto no-scrollbar">
               {['Fluid', 'Temperature', 'Output', 'Medication', 'Vitals', 'Vomit'].map((t) => (
                  <button 
                    key={t} 
                    onClick={() => setType(t as any)} 
                    className={`flex-1 py-4 px-2 rounded-xl text-2xl transition-all min-w-[60px] ${type === t ? 'bg-white shadow-md text-indigo-600 scale-105 z-10' : 'opacity-30 grayscale hover:opacity-100'}`}
                  >
                    <span className="block">{(icons as any)[t]}</span>
                    <span className="text-[8px] font-black uppercase tracking-tighter mt-1 block">{t}</span>
                  </button>
               ))}
            </div>

            <div className="space-y-6">
               {type === 'Vitals' && (
                 <div className="space-y-4 animate-in slide-in-from-left-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className={labelBaseClass}>HR (bpm)</label>
                            <input value={obs.hr} onChange={e => setObs({...obs, hr: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>RR (bpm)</label>
                            <input value={obs.rr} onChange={e => setObs({...obs, rr: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>SpO2 (%)</label>
                            <input value={obs.spo2} onChange={e => setObs({...obs, spo2: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>Temp (C)</label>
                            <input value={obs.temp} onChange={e => setObs({...obs, temp: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className={labelBaseClass}>CNS (AVPU)</label>
                            <select value={obs.avpu} onChange={e => setObs({...obs, avpu: e.target.value})} className={inputBaseClass}>
                                <option value="A">Alert</option>
                                <option value="V">Voice</option>
                                <option value="P">Pain</option>
                                <option value="U">Unresponsive</option>
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>CBT (sec)</label>
                            <select value={obs.cbt} onChange={e => setObs({...obs, cbt: e.target.value})} className={inputBaseClass}>
                                <option value="Normal">Normal (&lt;2s)</option>
                                <option value="Sluggish">Sluggish (2-3s)</option>
                                <option value="Slow">Slow (&gt;3s)</option>
                            </select>
                        </div>
                    </div>
                 </div>
               )}

               {type === 'Medication' && (
                 <div className="space-y-4 animate-in slide-in-from-left-4">
                    <div className="flex bg-indigo-50 p-1 rounded-xl border border-indigo-100">
                      {['Paracetamol', 'Ibuprofen'].map(m => (
                        <button key={m} onClick={() => setSelectedMed(m as any)} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${selectedMed === m ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>{m}</button>
                      ))}
                    </div>
                    {lastDoseInfo && (
                      <div className={`p-4 rounded-2xl border-2 transition-all ${lastDoseInfo.isTooSoon ? 'bg-rose-50 border-rose-200 animate-pulse' : 'bg-emerald-50 border-emerald-200'}`}>
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Dosing Safety Check</p>
                        <p className="text-xs font-bold text-slate-700 italic">Last: {formatLogTime(lastDoseInfo.lastTime.toISOString())} ({lastDoseInfo.diffHours.toFixed(1)}h ago)</p>
                        {lastDoseInfo.isTooSoon && <p className="text-sm font-black text-rose-600 uppercase tracking-tight mt-2">⚠️ Too Close! Wait until {formatLogTime(lastDoseInfo.nextSafeTime.toISOString())}</p>}
                      </div>
                    )}
                 </div>
               )}

               {type !== 'Vitals' && (
                  <div className="space-y-1">
                    <label className={labelBaseClass}>{type} Value ({units[type] || 'Value'})</label>
                    <input value={value} onChange={e => setValue(e.target.value)} placeholder="..." className={inputBaseClass} />
                  </div>
               )}

               <div className="space-y-1">
                  <label className={labelBaseClass}>Clinical Notes / Observations</label>
                  <textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder="WOB, behavior, hydration signs..." className={inputBaseClass + " h-24 resize-none italic font-bold text-sm"} />
               </div>

               <button 
                onClick={() => handleAdd()} 
                className={`w-full py-6 text-white font-black rounded-[2rem] shadow-2xl text-xs uppercase tracking-[0.2em] active:scale-95 transition-all ${lastDoseInfo?.isTooSoon ? 'bg-rose-600' : 'bg-indigo-600 hover:bg-indigo-700'}`}
               >
                 {type === 'Vitals' ? 'Commit Vital Sign Bundle' : lastDoseInfo?.isTooSoon ? 'Authorize Over-Interval Dose' : 'Record Entry'}
               </button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-7 space-y-8">
          <div className="bg-white p-8 rounded-[4rem] border border-slate-100 shadow-sm space-y-6">
             <div className="flex justify-between items-center px-4">
                <h3 className="text-2xl font-black text-slate-800 tracking-tight italic">Input/Output Balance</h3>
                <div className="flex gap-4">
                   <div className="flex items-center gap-2"><span className="w-3 h-3 bg-teal-500 rounded-full"></span><span className="text-[10px] font-black text-slate-600 uppercase">Input</span></div>
                   <div className="flex items-center gap-2"><span className="w-3 h-3 bg-rose-500 rounded-full"></span><span className="text-[10px] font-black text-slate-600 uppercase">Output</span></div>
                </div>
             </div>
             <div className="h-[250px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                   <ComposedChart data={trendData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                      <XAxis dataKey="time" hide />
                      <YAxis yAxisId="ml" hide />
                      <Tooltip contentStyle={{ borderRadius: '1.5rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 900 }} />
                      <Bar yAxisId="ml" dataKey="rawInput" fill="#14b8a6" radius={[4, 4, 0, 0]} name="In" />
                      <Bar yAxisId="ml" dataKey="rawOutput" fill="#e11d48" radius={[4, 4, 0, 0]} name="Out" />
                      <Line yAxisId="ml" type="monotone" dataKey="balance" stroke="#4f46e5" strokeWidth={4} dot={{ r: 6, fill: '#4f46e5' }} name="Net Balance" />
                   </ComposedChart>
                </ResponsiveContainer>
             </div>
          </div>

          <div className="bg-white p-8 rounded-[4rem] border border-slate-100 shadow-sm space-y-6">
              <h3 className="text-2xl font-black text-slate-800 tracking-tight italic ml-4">Clinical Timeline</h3>
              <div className="space-y-3 max-h-[500px] overflow-y-auto pr-2 no-scrollbar">
                 {history.acuteLogs?.length ? history.acuteLogs.map(entry => (
                    <div key={entry.id} className={`p-5 rounded-3xl border transition-all hover:scale-[1.01] flex items-center justify-between group ${entry.clinicianLogged ? 'bg-slate-900 text-white border-slate-800' : 'bg-white border-slate-100'}`}>
                       <div className="flex items-center gap-6">
                          <span className={`text-[10px] font-black w-14 shrink-0 uppercase ${entry.clinicianLogged ? 'text-indigo-400' : 'text-slate-400'}`}>{formatLogTime(entry.timestamp)}</span>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl shrink-0 ${entry.clinicianLogged ? 'bg-white/10' : 'bg-slate-50'}`}>{(icons as any)[entry.type]}</div>
                          <div>
                             <p className="text-sm font-black leading-none">{entry.value}</p>
                             {entry.notes && <p className={`text-[11px] font-bold italic mt-2 leading-snug ${entry.clinicianLogged ? 'text-slate-400' : 'text-slate-500'}`}>{entry.notes}</p>}
                          </div>
                       </div>
                       <button onClick={() => deleteEntry(entry.id)} className="opacity-0 group-hover:opacity-100 text-rose-500 p-2 font-black text-xs transition-all">✕</button>
                    </div>
                 )) : (
                    <div className="py-20 text-center text-slate-300 font-black uppercase text-xs italic">No clinical logs recorded.</div>
                 )}
              </div>
          </div>
        </div>
      </div>
    </div>
  );
};

