export type AgeGroup = 'Neo' | 'Infant' | 'Toddler' | 'Child' | 'Adolescent';

export interface VitalSignScore {
  parameter: string;
  value: string | number;
  score: number; // 0, 1 (Yellow), 3 (Red)
}

export interface CEWTRow {
  timestamp: string;
  totalScore: number;
  scores: Record<string, VitalSignScore>;
}

export const getAgeGroup = (ageMonths: number): AgeGroup => {
  if (ageMonths < 3) return 'Neo';
  if (ageMonths < 12) return 'Infant';
  if (ageMonths < 60) return 'Toddler';
  if (ageMonths < 144) return 'Child';
  return 'Adolescent';
};

/**
 * Simplified Clinical Thresholds for CEWT (Based on standard Pediatric Observation Charts)
 * Scores: 0 = Normal, 1 = Deviation (Yellow), 3 = Significant Deviation (Red)
 */
export const calculateCEWT = (vitals: any, ageGroup: AgeGroup): CEWTRow => {
  const result: Record<string, VitalSignScore> = {};
  let total = 0;

  const scoreIt = (param: string, val: any, s: number) => {
    result[param] = { parameter: param, value: val, score: s };
    total += s;
  };

  // 1. RESPIRATORY RATE
  const rr = parseInt(vitals.rr) || 0;
  let rrScore = 0;
  if (ageGroup === 'Infant') {
    if (rr < 20 || rr > 60) rrScore = 3;
    else if (rr < 30 || rr > 50) rrScore = 1;
  } else if (ageGroup === 'Child') {
    if (rr < 15 || rr > 40) rrScore = 3;
    else if (rr < 20 || rr > 30) rrScore = 1;
  } else {
    if (rr < 10 || rr > 50) rrScore = 3;
    else if (rr < 15 || rr > 35) rrScore = 1;
  }
  scoreIt('RR', rr || '--', rrScore);

  // 2. SpO2 (Oxygen)
  const o2 = parseInt(vitals.o2) || 100;
  let o2Score = 0;
  if (o2 < 90) o2Score = 3;
  else if (o2 < 94) o2Score = 1;
  scoreIt('SpO2', o2 ? `${o2}%` : '--', o2Score);

  // 3. HEART RATE
  const hr = parseInt(vitals.hr) || 0;
  let hrScore = 0;
  if (ageGroup === 'Infant') {
    if (hr < 80 || hr > 190) hrScore = 3;
    else if (hr < 100 || hr > 170) hrScore = 1;
  } else if (ageGroup === 'Child') {
    if (hr < 60 || hr > 140) hrScore = 3;
    else if (hr < 70 || hr > 120) hrScore = 1;
  } else {
    if (hr < 50 || hr > 160) hrScore = 3;
    else if (hr < 60 || hr > 130) hrScore = 1;
  }
  scoreIt('HR', hr || '--', hrScore);

  // 4. TEMPERATURE
  const temp = parseFloat(vitals.temp) || 37;
  let tScore = 0;
  if (temp < 35 || temp >= 39) tScore = 3;
  else if (temp < 36 || temp >= 38) tScore = 1;
  scoreIt('Temp', temp ? `${temp}°C` : '--', tScore);

  // 5. CNS (AVPU)
  const avpu = vitals.avpu || 'A';
  let avpuScore = (avpu !== 'A') ? 3 : 0;
  scoreIt('CNS', avpu, avpuScore);

  return {
    timestamp: vitals.timestamp,
    totalScore: total,
    scores: result
  };
};

import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useRole } from '../context/RoleContext';
import { DOSING_GUIDELINES } from '../clinical/dosing';
import { calculateCEWT, getAgeGroup, CEWTRow } from '../clinical/cewt';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Area, ComposedChart, Line, Bar
} from 'recharts';

const icons = { 
  Fluid: '🥤', 
  Temperature: '🌡️', 
  Output: '🚽', 
  Medication: '💊', 
  Vomit: '🤮', 
  Triage: '✨', 
  Vitals: '🩺', 
  'Physical Exam': '👨‍⚕️' 
};

const units: Record<string, string> = {
  Fluid: 'ml',
  Temperature: '°C',
  Output: 'ml',
  Vomit: 'ml',
  Medication: 'mg/ml',
  Vitals: ''
};

const formatLogTime = (isoString: string) => {
  try {
    return new Date(isoString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
  } catch {
    return isoString;
  }
};

const CEWTGrid: React.FC<{ data: CEWTRow[] }> = ({ data }) => {
  const parameters = ['RR', 'SpO2', 'HR', 'Temp', 'CNS'];

  if (data.length === 0) return (
    <div className="py-12 text-center text-slate-300 font-black uppercase text-[10px] italic border-2 border-dashed border-slate-100 rounded-[2rem]">
      No vital bundles recorded for CEWT synthesis.
    </div>
  );

  const getCellColor = (score: number) => {
    if (score >= 3) return 'bg-rose-500 text-white';
    if (score >= 1) return 'bg-amber-400 text-slate-900';
    return 'bg-white text-slate-600';
  };

  return (
    <div className="overflow-x-auto no-scrollbar rounded-[2rem] border border-slate-200 bg-white shadow-sm">
      <table className="w-full text-center border-collapse min-w-[600px]">
        <thead>
          <tr className="bg-slate-50 border-b border-slate-200">
            <th className="p-4 text-[10px] font-black uppercase text-slate-400 text-left sticky left-0 bg-slate-50 z-10 w-24">Parameter</th>
            {data.map((col, i) => (
              <th key={i} className="p-4 text-[10px] font-black uppercase text-slate-600 border-l border-slate-100 min-w-[80px]">
                {formatLogTime(col.timestamp)}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {parameters.map(param => (
            <tr key={param} className="border-b border-slate-100">
              <td className="p-4 text-xs font-black text-slate-800 text-left sticky left-0 bg-white z-10 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{param}</td>
              {data.map((col, i) => {
                const cell = col.scores[param];
                return (
                  <td key={i} className={`p-4 text-xs font-bold border-l border-slate-50 transition-colors ${getCellColor(cell?.score || 0)}`}>
                    {cell?.value || '--'}
                  </td>
                );
              })}
            </tr>
          ))}
          <tr className="bg-indigo-900 text-white font-black">
            <td className="p-4 text-[10px] uppercase tracking-widest text-left sticky left-0 bg-indigo-900 z-10">Total Score</td>
            {data.map((col, i) => (
              <td key={i} className={`p-4 text-sm border-l border-white/10 ${col.totalScore >= 4 ? 'bg-rose-600 animate-pulse' : ''}`}>
                {col.totalScore}
              </td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
};

export const AcuteTracker: React.FC = () => {
  const { history, addAcuteLog, updateHistory, latestWeight } = useMedicalHistory();
  const { childProfile } = useChildProfile();
  const { role } = useRole();

  const [type, setType] = useState<AcuteLogEntry['type']>('Fluid');
  const [value, setValue] = useState('');
  const [notes, setNotes] = useState('');
  const [selectedMed, setSelectedMed] = useState<'Paracetamol' | 'Ibuprofen'>('Paracetamol');

  const [obs, setObs] = useState({
    rr: '', hr: '', spo2: '', temp: '', bp: '', cbt: 'Normal', effort: 'None', avpu: 'A'
  });

  const deleteEntry = (id: string) => {
    if (confirm("Delete this clinical entry?")) {
      updateHistory({
        acuteLogs: history.acuteLogs?.filter(log => log.id !== id)
      });
    }
  };

  const balanceStats = useMemo(() => {
    const logs = history.acuteLogs || [];
    const input = logs.filter(l => l.type === 'Fluid').reduce((sum, l) => sum + (parseInt(l.value) || 0), 0);
    const output = logs.filter(l => l.type === 'Output' || l.type === 'Vomit').reduce((sum, l) => sum + (parseInt(l.value) || 0), 0);
    return { input, output, balance: input - output };
  }, [history.acuteLogs]);

  // CEWT Synthesis
  const cewtData = useMemo(() => {
    const logs = history.acuteLogs || [];
    const ageGroup = getAgeGroup(childProfile?.dob ? (new Date().getFullYear() - new Date(childProfile.dob).getFullYear()) * 12 : 12);

    return logs
      .filter(l => l.type === 'Vitals' || (l.type === 'Temperature' && !isNaN(parseFloat(l.value))))
      .map(l => {
        let vitalsObj: any = { timestamp: l.timestamp };
        if (l.type === 'Vitals') {
          const hrM = l.value.match(/HR:\s*(\d+)/);
          const rrM = l.value.match(/RR:\s*(\d+)/);
          const o2M = l.value.match(/O2:\s*(\d+)/);
          const tM = l.value.match(/T:\s*([\d.]+)/);
          const cnsM = l.value.match(/CNS:\s*(\w+)/);
          vitalsObj.hr = hrM ? hrM[1] : '';
          vitalsObj.rr = rrM ? rrM[1] : '';
          vitalsObj.o2 = o2M ? o2M[1] : '';
          vitalsObj.temp = tM ? tM[1] : '';
          vitalsObj.avpu = cnsM ? cnsM[1] : 'A';
        } else {
          vitalsObj.temp = l.value.split(' ')[0];
          vitalsObj.avpu = 'A';
        }
        return calculateCEWT(vitalsObj, ageGroup);
      })
      .reverse();
  }, [history.acuteLogs, childProfile]);

  const lastCewt = cewtData[cewtData.length - 1];

  const lastDoseInfo = useMemo(() => {
    if (type !== 'Medication') return null;
    const logs = history.acuteLogs || [];
    const drugLogs = logs.filter(l => l.type === 'Medication' && l.medicationName === selectedMed);
    if (drugLogs.length === 0) return null;
    const lastDose = drugLogs[0]; 
    const lastTime = new Date(lastDose.timestamp);
    const diffHours = (Date.now() - lastTime.getTime()) / (1000 * 60 * 60);
    const interval = selectedMed === 'Paracetamol' ? 4 : 6;
    return { isTooSoon: diffHours < interval, lastTime, diffHours, interval };
  }, [type, selectedMed, history.acuteLogs]);

  const handleAdd = () => {
    if (!value && type !== 'Vitals') return;
    const isSafetyViolation = lastDoseInfo?.isTooSoon && type === 'Medication';

    if (type === 'Vitals') {
      const vStr = `HR: ${obs.hr}, RR: ${obs.rr}, O2: ${obs.spo2}%, T: ${obs.temp}C, CNS: ${obs.avpu}`;
      addAcuteLog({
        timestamp: new Date().toISOString(),
        type: 'Vitals',
        value: vStr,
        notes: notes.trim(),
        clinicianLogged: role === 'clinician'
      });
      setObs({ rr: '', hr: '', spo2: '', temp: '', bp: '', cbt: 'Normal', effort: 'None', avpu: 'A' });
    } else {
      addAcuteLog({
        timestamp: new Date().toISOString(),
        type,
        value: type === 'Temperature' ? `${value} degree Celsius` : `${value} ${units[type] || ''}`,
        notes: notes.trim(),
        medicationName: type === 'Medication' ? selectedMed : undefined,
        clinicianLogged: role === 'clinician'
      });
    }
    setValue('');
    setNotes('');
  };

  const inputBaseClass = "w-full p-4 bg-white border-2 border-slate-100 rounded-xl font-black text-slate-900 outline-none focus:border-indigo-600 transition-all placeholder:text-slate-200";
  const labelBaseClass = "text-[9px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-1 block";

  return (
    <div className="space-y-8 pb-20 animate-in fade-in">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-1">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight italic leading-none">Inpatient <span className="text-rose-600">Observation</span></h2>
          <p className="text-slate-500 font-bold italic mt-2">{role === 'clinician' ? 'Clinical Registry & CEWT Dash' : 'Track recovery and vital signs.'}</p>
        </div>
        <div className="flex gap-2">
            <div className="bg-indigo-50 border border-indigo-100 px-4 py-2 rounded-xl flex items-center gap-3">
                <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest">Balance</span>
                <span className={`font-black text-sm ${balanceStats.balance < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                    {balanceStats.balance > 0 ? '+' : ''}{balanceStats.balance} ml
                </span>
            </div>
            {lastCewt && (
              <div className={`px-4 py-2 rounded-xl text-white font-black text-sm flex items-center gap-2 shadow-lg ${lastCewt.totalScore >= 4 ? 'bg-rose-600 animate-pulse' : 'bg-indigo-600'}`}>
                CEWT: {lastCewt.totalScore}
              </div>
            )}
        </div>
      </header>

      {role === 'clinician' && (
        <section className="space-y-6 animate-in slide-in-from-top-4">
           <div className="flex items-center justify-between px-4">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Professional EMR Chart (CEWT)</h3>
              {lastCewt && lastCewt.totalScore > 0 && (
                <div className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${lastCewt.totalScore >= 4 ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-700'}`}>
                   Triggers: {lastCewt.totalScore >= 4 ? '🚨 MET Call Required' : '⚠️ Clinical Review (RN/Registrar)'}
                </div>
              )}
           </div>
           <CEWTGrid data={cewtData} />
        </section>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 space-y-6">
          <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-xl space-y-8">
            <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-200 shadow-inner overflow-x-auto no-scrollbar">
               {['Fluid', 'Temperature', 'Output', 'Medication', 'Vitals'].map((t) => (
                  <button 
                    key={t} 
                    onClick={() => setType(t as any)} 
                    className={`flex-1 py-4 px-2 rounded-xl text-2xl transition-all min-w-[70px] ${type === t ? 'bg-white shadow-md text-indigo-600 scale-105 z-10' : 'opacity-30 grayscale hover:opacity-100'}`}
                  >
                    <span className="block">{(icons as any)[t]}</span>
                    <span className="text-[8px] font-black uppercase mt-1 block">{t}</span>
                  </button>
               ))}
            </div>

            <div className="space-y-6">
               {type === 'Vitals' ? (
                 <div className="space-y-4 animate-in slide-in-from-left-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className={labelBaseClass}>HR (bpm)</label>
                            <input value={obs.hr} onChange={e => setObs({...obs, hr: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>RR (bpm)</label>
                            <input value={obs.rr} onChange={e => setObs({...obs, rr: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>SpO2 (%)</label>
                            <input value={obs.spo2} onChange={e => setObs({...obs, spo2: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                        <div className="space-y-1">
                            <label className={labelBaseClass}>Temp (C)</label>
                            <input value={obs.temp} onChange={e => setObs({...obs, temp: e.target.value})} placeholder="..." className={inputBaseClass} />
                        </div>
                    </div>
                    <div className="space-y-1">
                        <label className={labelBaseClass}>CNS (AVPU)</label>
                        <div className="flex gap-2">
                           {['A', 'V', 'P', 'U'].map(v => (
                             <button key={v} onClick={() => setObs({...obs, avpu: v})} className={`flex-1 py-3 rounded-xl font-black text-xs transition-all border-2 ${obs.avpu === v ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-400'}`}>
                               {v}
