                    </div>
                 </div>
               ) : (
                  <div className="space-y-1">
                    <label className={labelBaseClass}>{type} Value ({units[type] || 'Value'})</label>
                    <input value={value} onChange={e => setValue(e.target.value)} placeholder="..." className={inputBaseClass} />
                  </div>
               )}

               <div className="space-y-1">
                  <label className={labelBaseClass}>Clinical Notes</label>
                  <textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder="Observations..." className={inputBaseClass + " h-20 resize-none italic font-bold text-sm"} />
               </div>

               <button onClick={handleAdd} className="w-full py-6 bg-indigo-600 text-white font-black rounded-[2rem] shadow-2xl text-[11px] uppercase tracking-widest active:scale-95 transition-all">
                 {type === 'Vitals' ? 'Commit Vital Bundle' : 'Record Observation'}
