            </div>
          </div>
        </div>

        <div className="lg:col-span-7 space-y-6">
          <div className="bg-white p-8 rounded-[4rem] border border-slate-100 shadow-sm space-y-6">
              <h3 className="text-2xl font-black text-slate-800 tracking-tight italic ml-4">Registry Timeline</h3>
              <div className="space-y-3 max-h-[450px] overflow-y-auto pr-2 no-scrollbar">
                 {history.acuteLogs?.length ? history.acuteLogs.map(entry => (
                    <div key={entry.id} className={`p-5 rounded-3xl border transition-all flex items-center justify-between group ${entry.clinicianLogged ? 'bg-slate-900 text-white border-slate-800' : 'bg-white border-slate-100'}`}>
                       <div className="flex items-center gap-6">
                          <span className={`text-[10px] font-black w-12 shrink-0 uppercase ${entry.clinicianLogged ? 'text-indigo-400' : 'text-slate-400'}`}>{formatLogTime(entry.timestamp)}</span>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl shrink-0 ${entry.clinicianLogged ? 'bg-white/10' : 'bg-slate-50'}`}>{(icons as any)[entry.type]}</div>
                          <div>
                             <p className="text-sm font-black leading-none">{entry.value}</p>
                             {entry.notes && <p className={`text-[10px] font-bold italic mt-2 leading-snug ${entry.clinicianLogged ? 'text-slate-500' : 'text-slate-400'}`}>{entry.notes}</p>}
                          </div>
                       </div>
                       <button onClick={() => deleteEntry(entry.id)} className="opacity-0 group-hover:opacity-100 text-rose-500 p-2 font-black text-xs transition-all">✕</button>
                    </div>
                 )) : (
                    <div className="py-20 text-center text-slate-200 font-black uppercase text-xs italic">No logs on current record.</div>
                 )}
              </div>
          </div>
        </div>
      </div>
    </div>
  );
};

