export type AgeGroup = 'Neo' | 'Infant' | 'Toddler' | 'Child' | 'Adolescent';

export interface VitalSignScore {
  parameter: string;
  value: string | number;
  score: number; // 0, 1 (Yellow), 3 (Red)
}

export interface CEWTRow {
  timestamp: string;
  totalScore: number;
  scores: Record<string, VitalSignScore>;
}

export const getAgeGroup = (ageMonths: number): AgeGroup => {
  if (ageMonths < 3) return 'Neo';
  if (ageMonths < 12) return 'Infant';
  if (ageMonths < 60) return 'Toddler';
  if (ageMonths < 144) return 'Child';
  return 'Adolescent';
};

/**
 * Professional Clinical Thresholds for CEWT
 * Scores: 0 = Normal, 1 = Deviation (Yellow), 3 = Significant Deviation (Red)
 */
export const calculateCEWT = (vitals: any, ageGroup: AgeGroup): CEWTRow => {
  const result: Record<string, VitalSignScore> = {};
  let total = 0;

  const scoreIt = (param: string, val: any, s: number) => {
    result[param] = { parameter: param, value: val, score: s };
    total += s;
  };

  // 1. RESPIRATORY RATE
  const rr = parseInt(vitals.rr) || 0;
  let rrScore = 0;
  if (ageGroup === 'Infant') {
    if (rr < 20 || rr > 60) rrScore = 3;
    else if (rr < 30 || rr > 50) rrScore = 1;
  } else if (ageGroup === 'Child') {
    if (rr < 15 || rr > 40) rrScore = 3;
    else if (rr < 20 || rr > 30) rrScore = 1;
  } else {
    if (rr < 10 || rr > 50) rrScore = 3;
    else if (rr < 15 || rr > 35) rrScore = 1;
  }
  scoreIt('RR', rr || '--', rrScore);

  // 2. SpO2 (Oxygen)
  const o2 = parseInt(vitals.o2) || 100;
  let o2Score = 0;
  if (o2 < 90) o2Score = 3;
  else if (o2 < 94) o2Score = 1;
  scoreIt('SpO2', o2 ? `${o2}%` : '--', o2Score);

  // 3. HEART RATE
  const hr = parseInt(vitals.hr) || 0;
  let hrScore = 0;
  if (ageGroup === 'Infant') {
    if (hr < 80 || hr > 190) hrScore = 3;
    else if (hr < 100 || hr > 170) hrScore = 1;
  } else if (ageGroup === 'Child') {
    if (hr < 60 || hr > 140) hrScore = 3;
    else if (hr < 70 || hr > 120) hrScore = 1;
  } else {
    if (hr < 50 || hr > 160) hrScore = 3;
    else if (hr < 60 || hr > 130) hrScore = 1;
  }
  scoreIt('HR', hr || '--', hrScore);

  // 4. TEMPERATURE
  const temp = parseFloat(vitals.temp) || 37;
  let tScore = 0;
  if (temp < 35 || temp >= 39) tScore = 3;
  else if (temp < 36 || temp >= 38) tScore = 1;
  scoreIt('Temp', temp ? `${temp}°C` : '--', tScore);

  // 5. CNS (AVPU)
  const avpu = vitals.avpu || 'A';
  let avpuScore = (avpu !== 'A') ? 3 : 0;
  scoreIt('CNS', avpu, avpuScore);

  // 6. CRT (Capillary Refill)
  const crt = vitals.crt || 'Normal';
  let crtScore = 0;
  if (crt === 'Sluggish') crtScore = 1;
  if (crt === 'Slow') crtScore = 3;
  scoreIt('CRT', crt, crtScore);

  // 7. BP (Systolic) - Simplified scoring for clinician mode
  const sbp = parseInt(vitals.bp?.split('/')[0]) || 0;
  let bpScore = 0;
  if (sbp > 0) {
    if (ageGroup === 'Infant' && sbp < 60) bpScore = 3;
    if (ageGroup === 'Toddler' && sbp < 70) bpScore = 3;
    if (ageGroup === 'Child' && sbp < 80) bpScore = 3;
    if (ageGroup === 'Adolescent' && sbp < 90) bpScore = 3;
  }
  scoreIt('BP', vitals.bp || '--', bpScore);

  return {
    timestamp: vitals.timestamp,
    totalScore: total,
    scores: result
  };
};

import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry, HydrationChallenge } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useRole } from '../context/RoleContext';
import { DOSING_GUIDELINES } from '../clinical/dosing';
import { calculateCEWT, getAgeGroup, CEWTRow } from '../clinical/cewt';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Area, ComposedChart, Line, Bar, Legend
} from 'recharts';

const icons = { 
  Fluid: '🥤', 
  Temperature: '🌡️', 
  Output: '🚽', 
  Medication: '💊', 
  Vomit: '🤮', 
  Triage: '✨', 
  Vitals: '🩺', 
  'Physical Exam': '👨‍⚕️' 
};

const units: Record<string, string> = {
  Fluid: 'ml',
  Temperature: '°C',
  Output: 'ml',
  Vomit: 'ml',
  Medication: 'mg/ml',
  Vitals: ''
};

const formatLogTime = (isoString: string) => {
  try {
    return new Date(isoString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
  } catch {
    return isoString;
  }
};

const CEWTVisualization: React.FC<{ data: CEWTRow[] }> = ({ data }) => {
  const parameters = ['RR', 'SpO2', 'HR', 'Temp', 'CNS', 'CRT', 'BP'];

  if (data.length === 0) return (
    <div className="py-12 text-center text-slate-300 font-black uppercase text-[10px] italic border-2 border-dashed border-slate-100 rounded-[2rem]">
      No vital bundles recorded for CEWT synthesis.
    </div>
  );

  const getCellColor = (score: number) => {
    if (score >= 3) return 'bg-rose-500 text-white';
    if (score >= 1) return 'bg-amber-400 text-slate-900';
    return 'bg-white text-slate-600';
  };

  const chartData = [...data].sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()).map(row => ({
    time: formatLogTime(row.timestamp),
    score: row.totalScore,
    rawTimestamp: row.timestamp
  }));

  return (
    <div className="space-y-6">
      {/* CEWT Score Line Graph */}
      <div className="bg-slate-900 p-8 rounded-[3rem] shadow-2xl h-[280px] relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-500 rounded-full blur-[100px] opacity-10"></div>
        <div className="relative z-10 flex flex-col h-full">
          <div className="flex justify-between items-center mb-6">
            <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">Escalation Velocity (CEWT)</h4>
            <div className="flex gap-4">
              <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span><span className="text-[9px] font-black text-rose-100 uppercase">Critical Zone (4+)</span></div>
            </div>
          </div>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(255,255,255,0.05)" />
                <XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: 'rgba(255,255,255,0.4)', fontSize: 10, fontWeight: 900 }} />
                <YAxis domain={[0, 10]} axisLine={false} tickLine={false} tick={{ fill: 'rgba(255,255,255,0.4)', fontSize: 10, fontWeight: 900 }} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', borderRadius: '1rem', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', fontWeight: 900 }}
                  itemStyle={{ color: '#fff' }}
                />
                <Area type="monotone" dataKey="score" fill="rgba(79, 70, 229, 0.1)" stroke="none" />
                <Line 
                  type="monotone" 
                  dataKey="score" 
                  stroke="#6366f1" 
                  strokeWidth={4} 
                  dot={(props: any) => {
                    const { cx, cy, payload } = props;
                    const isHigh = payload.score >= 4;
                    return <circle cx={cx} cy={cy} r={isHigh ? 6 : 4} fill={isHigh ? '#e11d48' : '#fff'} stroke={isHigh ? '#fff' : '#6366f1'} strokeWidth={2} />;
                  }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* CEWT Data Grid */}
      <div className="overflow-x-auto no-scrollbar rounded-[2rem] border border-slate-200 bg-white shadow-sm">
        <table className="w-full text-center border-collapse min-w-[700px]">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="p-4 text-[10px] font-black uppercase text-slate-400 text-left sticky left-0 bg-slate-50 z-10 w-28">Obs Parameter</th>
              {data.map((col, i) => (
                <th key={i} className="p-4 text-[10px] font-black uppercase text-slate-600 border-l border-slate-100 min-w-[80px]">
                  {formatLogTime(col.timestamp)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {parameters.map(param => (
              <tr key={param} className="border-b border-slate-100">
                <td className="p-4 text-xs font-black text-slate-800 text-left sticky left-0 bg-white z-10 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{param}</td>
                {data.map((col, i) => {
                  const cell = col.scores[param];
                  return (
                    <td key={i} className={`p-4 text-xs font-bold border-l border-slate-50 transition-colors ${getCellColor(cell?.score || 0)}`}>
                      {cell?.value || '--'}
                    </td>
                  );
                })}
              </tr>
            ))}
            <tr className="bg-slate-900 text-white font-black">
              <td className="p-4 text-[10px] uppercase tracking-widest text-left sticky left-0 bg-slate-900 z-10">Total CEWT</td>
              {data.map((col, i) => (
                <td key={i} className={`p-4 text-sm border-l border-white/10 ${col.totalScore >= 4 ? 'bg-rose-600 animate-pulse' : ''}`}>
                  {col.totalScore}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export const AcuteTracker: React.FC = () => {
