import React, { useState, useEffect, useMemo } from 'react';
import { AcuteLogEntry } from '../types';
import { useMedicalHistory } from '../context/MedicalHistoryContext';
import { useChildProfile } from '../context/ChildProfileContext';
import { useRole } from '../context/RoleContext';
import { calculateCEWT, getAgeGroup, CEWTRow } from '../clinical/cewt';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Area, ComposedChart, Line, Bar, ReferenceLine
} from 'recharts';

const icons = { 
  Fluid: '🥤', 
  Temperature: '🌡️', 
  Output: '🚽', 
  Medication: '💊', 
  Vomit: '🤮', 
  Triage: '✨', 
  Vitals: '🩺', 
  'Physical Exam': '👨‍⚕️' 
};

const units: Record<string, string> = {
  Fluid: 'ml',
  Temperature: '°C',
  Output: 'ml',
  Vomit: 'ml',
  Medication: 'mg/ml',
  Vitals: ''
};

const formatLogTime = (isoString: string) => {
  try {
    return new Date(isoString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
  } catch {
    return isoString;
  }
};

const CEWTEscalationChart: React.FC<{ data: CEWTRow[] }> = ({ data }) => {
  const chartData = useMemo(() => 
    [...data].sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()).map(row => ({
      time: formatLogTime(row.timestamp),
      score: row.totalScore,
      rawTimestamp: row.timestamp
    }))
  , [data]);

  if (data.length < 1) return null;

  return (
    <div className="bg-slate-900 p-6 sm:p-8 rounded-[3rem] shadow-2xl h-[320px] relative overflow-hidden border border-white/5 group">
