        <div className="flex justify-between items-center mb-6">
          <div>
            <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">Escalation Velocity</h4>
            <p className="text-white/40 text-[9px] font-bold italic">Total CEWT Score Progression</p>
          </div>
          <div className="flex gap-4">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span>
