              <YAxis domain={[0, 12]} axisLine={false} tickLine={false} tick={{ fill: 'rgba(255,255,255,0.4)', fontSize: 10, fontWeight: 900 }} />
              <Tooltip 
                contentStyle={{ backgroundColor: '#1e293b', borderRadius: '1rem', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', fontWeight: 900, fontSize: '12px' }}
                itemStyle={{ color: '#fff' }}
              />
              <ReferenceLine y={4} stroke="#e11d48" strokeDasharray="5 5" label={{ position: 'right', value: 'MET', fill: '#e11d48', fontSize: 10, fontWeight: 900 }} />
              <Area type="monotone" dataKey="score" fill="rgba(79, 70, 229, 0.15)" stroke="none" />
              <Line 
                type="monotone" 
                dataKey="score" 
                stroke="#6366f1" 
